Expected pattern: not /require\(["'][^"']*routes\/conversations["']\)/
Received string:      "const path = require(\"node:path\");
const express = require(\"express\");
const methodOverride = require(\"method-override\");
const ejsMate = require(\"ejs-mate\");
const session = require(\"express-session\");
const { MongoStore } = require(\"connect-mongo\");
const flash = require(\"connect-flash\");
const passport = require(\"passport\");
const LocalStrategy = require(\"passport-local\");
const { canonicalUrl, robotsMeta, absoluteUrl } = require(\"./utils/seo\");
const { loadEnv } = require(\"./config/env\");
const { configureCloudinary } = require(\"./config/cloudinary\");
const pinoHttp = require(\"pino-http\");
const { randomUUID } = require(\"node:crypto\");
const { NotFoundError } = require(\"./utils/errors\");
const { createLogger } = require(\"./config/logger\");
const { createErrorHandler } = require(\"./middleware/errors\");
const User = require(\"./models/user.js\");
const { can } = require(\"./policies\");
const { fullTitle, metaDescription } = require(\"./utils/pageMeta\");
const { formatMoney } = require(\"./utils/money\");
