} = require(\"./middleware/security\");
const { csrfProtection } = require(\"./middleware/csrf\");
const { inputGuard, URLENCODED_OPTIONS } = require(\"./middleware/inputGuard\");
const { recoverCheckout } = require(\"./middleware/checkoutRecovery\");
const { createHealthRouter } = require(\"./routes/health\");
const { createSeoRouter } = require(\"./routes/seo\");
const emailAuthRouter = require(\"./routes/emailAuth\");
const { redactPath } = require(\"./utils/redactPath\");
const notificationPrefsRouter = require(\"./routes/notificationPrefs\");
const { createNotificationMailer } = require(\"./services/notificationEmail\");
const { createEmailService } = require(\"./services/email\");

const ROOT_DIR = path.join(__dirname, \"..\");

/**
 * Builds the Express application. Requiring this file has no side effects:
 * nothing connects to MongoDB, nothing listens on a port, and no environment
 * is read until createApp() runs. server.js connects the database and listens.
 *
 * @param {object} [options]
 * @param {object} [options.config] Validated config from src/config/env.js
 *   (default: loadEnv(), which reads process.env and throws if it is invalid).
 * @param {object} [options.sessionStore] express-session store. Default: a
 *   MongoStore on config.mongodbUri. Tests pass a MemoryStore so no database
 *   is needed.
 * @param {object} [options.logger] pino logger (default: JSON to stdout;
 *   silent when config.isTest).
 * @param {{ send: Function }} [options.emailService] sends mail (default: the
 *   transport in config.email; tests pass createMemoryEmailService()).
 * @param {() => boolean} [options.isDbReady] answers /readyz (default: the
 *   Mongoose connection is open). Tests pass a stub.
 */
function createApp({
  config = loadEnv(),
  sessionStore,
  logger = createLogger({ level: config.isTest ? \"silent\" : \"info\" }),
  isDbReady,
  emailService,
} = {}) {
  configureCloudinary(config.cloudinary);
  configureLocationSecret(config.sessionSecret); // keys the public-location offset (P06-T02)

  const app = express();

  app.set(\"view engine\", \"ejs\");
  app.set(\"views\", path.join(ROOT_DIR, \"views\"));
  // <title> and meta description helpers used by views/layouts/boilerPlate.ejs
  // Email (P02-T05). Without config.email (older test configs) nothing asks for
  // a confirmed address.
  app.locals.emailService =
    emailService ||
    createEmailService({ email: config.email, isProduction: Boolean(config.isProduction), logger });
  app.locals.emailVerificationRequired = Boolean(config.email && config.email.verificationRequired);
  app.locals.appBaseUrl = config.appBaseUrl;
  // How long after a stay a review may be written, and edited (P12-T01, P12-T03).
  app.locals.reviewWindowDays = config.reviews && config.reviews.windowDays;
  app.locals.reviewEditDays = config.reviews && config.reviews.editDays;
  app.locals.notificationSecret = config.sessionSecret; // keys the \"stop these emails\" links (P11-T05)
  // Email copies of notifications (P11-T05): only with a real config.email
  // (older test configs have none, so tests stay silent).
  if (config.email) {
    require(\"./services/notificationEvents\").notifier.setMailer(
      createNotificationMailer({
        emailService: app.locals.emailService,
        baseUrl: config.appBaseUrl,
        secret: config.sessionSecret,
        logger,
      }),
    );
  }
  app.locals.logger = logger;
  app.locals.fullTitle = fullTitle;
  app.locals.metaDescription = metaDescription;
  app.locals.imageUrl = imageUrl; // Cloudinary size/format presets for <img>
  app.locals.imageSrcset = imageSrcset; // the same photo at several widths
  app.locals.pagination = pagination;
  app.locals.hiddenFields = hiddenFields; // carries the search state through a form
  app.locals.listingsUrl = listingsUrl; // /listings?... links that keep the query // used by views/partials/pagination.ejs

  app.disable(\"x-powered-by\");
  // Behind reverse proxies (Render, Railway, nginx...): needed for secure
  // cookies and for rate limiting by the real client address. The number of
  // hops is TRUST_PROXY_HOPS (default 1); see docs/DEPLOYMENT.md.
  if (config.isProduction) app.set(\"trust proxy\", config.trustProxyHops || 1);

  app.engine(\"ejs\", ejsMate);
  // Before static files so every response carries the security headers.
  app.use(assignCspNonce);
  app.use(securityHeaders({ isProduction: Boolean(config.isProduction) }));
  // Health checks (P19-T03): before the request log, the session and CSRF, so
  // a check every few seconds writes no log line, creates no session and needs
  // no cookie or token.
  app.use(createHealthRouter({ isDbReady }));
  // /robots.txt and /sitemap.xml (P18-T05): no session, no cookie, cached.
  app.use(createSeoRouter({ baseUrl: config.appBaseUrl }));
  // What the layout needs for <link rel=\"canonical\">, <meta name=\"robots\"> and
  // the Open Graph tags (P18-T05). They are functions because the status of the
  // answer is only known when the page is rendered (an error page has no
  // canonical URL and is not indexed). The path is read now: a router that
  // handles the request later sees a shortened one.
  app.use((req, res, next) => {
    const { path, query } = req;
    res.locals.seoUrl = () =>
      canonicalUrl(config.appBaseUrl, { path, query, status: res.statusCode });
    res.locals.seoRobots = () => robotsMeta({ path, status: res.statusCode });
    res.locals.siteUrl = (to) => absoluteUrl(config.appBaseUrl, to);
    next();
  });
  app.use(express.static(path.join(ROOT_DIR, \"public\")));

  // After static files (so assets are not logged), before everything else so
  // every other log line and error carries the request id. Only the id, method
  // and path (no query string, headers or body) are logged for a request.
  app.use(
    pinoHttp({
      logger,
      genReqId: (req, res) => {
        const id = randomUUID();
        res.setHeader(\"X-Request-Id\", id);
        return id;
      },
      serializers: {
        req: (req) => ({
          id: req.id,
          method: req.method,
          url: redactPath(req.url),
        }),
        res: (res) => ({ statusCode: res.statusCode }),
      },
      customLogLevel: (req, res, err) =>
        err || res.statusCode >= 500 ? \"error\" : \"info\",
    }),
  );

  app.use(express.urlencoded(URLENCODED_OPTIONS));
  // Refuse operator keys ($ne, a.b), NUL bytes and absurd nesting (P17-T02).
  app.use(inputGuard);
  app.use(methodOverride(\"_method\"));

  let store = sessionStore;
  if (!store) {
    store = MongoStore.create({
      mongoUrl: config.mongodbUri,
      touchAfter: 24 * 60 * 60,
    });

    store.on(\"error\", (err) => {
      console.error(\"Error in Mongo session store:\", err);
    });
  }

  const sessionOptions = {
    store,
    secret: config.sessionSecret,
    resave: false,
    saveUninitialized: false,
    cookie: {
      maxAge: 7 * 24 * 60 * 60 * 1000,
      httpOnly: true,
      sameSite: \"lax\",
      secure: Boolean(config.isProduction),
    },
  };

  app.use(session(sessionOptions));
  app.use(flash());

  // After the session and the urlencoded parser, before multer and every
  // router: no state-changing route can run without a valid token (P01-T10).
  app.use(csrfProtection({ onInvalid: recoverCheckout }));

  app.use(passport.initialize());
  app.use(passport.session());
  passport.use(new LocalStrategy(User.authenticate()));

  passport.serializeUser(User.serializeUser());
  passport.deserializeUser(User.deserializeUser());

  app.use((req, res, next) => {
    res.locals.success = req.flash(\"success\");
    res.locals.error = req.flash(\"error\");
    res.locals.currUser = req.user;
    res.locals.currentPath = req.path; // marks the current page in the navbar
    res.locals.formatMoney = formatMoney; // integer minor units -> \"₹1,200\"
    // Views ask the same policies as the routes: can(\"listing:edit\", listing).
    res.locals.can = (action, resource) => can(action, req.user, resource);
    res.locals.mapPublicToken = config.mapbox.publicToken;
    next();
