  const limiters = createAuthLimiters();
  app.post(\"/login\", limiters.login);
  app.post(\"/signup\", limiters.signup);
  app.post(\"/forgot-password\", limiters.emailLink);
  app.post(\"/verify-email/resend\", limiters.emailLink);

  app.use(\"/api/listings/:id/quote\", limiters.quote);
  app.use(\"/api/destinations\", limiters.destinations);
  app.post(\"/reports\", limiters.report); // counts, then lets the reports router answer
  // Sending a message or starting a conversation (P11-T02); counts, then the router answers.
  app.post(
    [
      \"/api/conversations/:id/messages\",
      \"/api/listings/:id/conversations\",
      \"/api/reservations/:id/conversation\",
      \"/listings/:id/contact\",
      \"/conversations/:id/messages\",
    ],
    limiters.message,
  );
  app.use(\"/api\", apiRouter);
  app.use(\"/admin\", adminRouter);
  app.use(\"/host\", hostRouter);
  app.use(\"/listings/:id/images\", imagesRouter);
  app.use(\"/listings\", listingRouter);
  app.use(\"/listings/:id/reviews\", reviewRouter);
  app.use(\"/\", reportsRouter);
  app.use(\"/\", wishlistsRouter);
  app.use(\"/\", compareRouter);
  app.use(\"/\", profileRouter);
  app.use(\"/\", tripsRouter);
  app.use(\"/\", notificationsRouter);
  app.use(\"/\", conversationsRouter);
  app.use(\"/\", pagesRouter);
  app.use(\"/\", emailAuthRouter);
  app.use(\"/\", notificationPrefsRouter);
  app.use(\"/\", useRouter);
  app.use(\"/\", accountRouter);

  app.all(\"/{*splat}\", (req, res, next) => {
    next(new NotFoundError());
  });

  app.use(createErrorHandler({ isProduction: config.isProduction, logger }));

  return app;
}

module.exports = { createApp };

// Cancellation policies as DATA (P09-T03). src/services/refunds.js reads this
// and nothing else to decide a refund, so a rule is changed here, in one place.
//
// The sentences guests read (checkout page, booking page) are
// CANCELLATION_TERMS in src/config/constants.js. They describe exactly the
// rules below; change both together (tests/unit/refunds.test.js checks the
// numbers the sentences promise).
//
// Vocabulary
//   checkInAt   check-in date at the listing's check-in time, on the clock of
//               the listing's time zone (\"00:00\" when the listing gives none)
//   total       what the guest was quoted (pricingSnapshot.totalMinor)
//   firstNight  one night's average price (pricingSnapshot.avgPerNightMinor)
//   rest        the nights' price (pricingSnapshot.subtotalMinor) minus firstNight
//
// Rules are tried in order; the first whose `when` holds decides. `keep` says
// what the host keeps (everything else is refunded): \"nothing\", the first
// night plus a share of the rest (rounded up, so a part-paise goes to the
// host), \"everything\", or `refundShareOfTotal` (the guest gets that share of
// the total back, rounded down).
const HOUR_MS = 60 * 60 * 1000;
const DAY_MS = 24 * HOUR_MS;

const POLICIES = Object.freeze({
  // Free until 24 hours before check-in; then the first night is kept.
  flexible: Object.freeze([
    Object.freeze({
      id: \"flexible_free\",
      when: { freeUntilHoursBeforeCheckIn: 24 },
      keep: { kind: \"nothing\" },
    }),
    Object.freeze({
      id: \"flexible_late\",
      when: { before: \"checkIn\" },
      keep: { kind: \"firstNight\", restShare: 0 },
    }),
  ]),
  // Free until 5 days before check-in; then the first night and half the rest.
  moderate: Object.freeze([
    Object.freeze({
      id: \"moderate_free\",
      when: { freeUntilHoursBeforeCheckIn: 5 * 24 },
      keep: { kind: \"nothing\" },
    }),
    Object.freeze({
      id: \"moderate_late\",
      when: { before: \"checkIn\" },
      keep: { kind: \"firstNight\", restShare: 0.5 },
    }),
  ]),
  // Free within 48 h of booking when check-in is 14+ days away; half back until
  // 7 days before check-in; nothing after.
  strict: Object.freeze([
    Object.freeze({
      id: \"strict_grace\",
      when: { withinHoursOfBooking: 48, minHoursBeforeCheckIn: 14 * 24 },
      keep: { kind: \"nothing\" },
    }),
    Object.freeze({
      id: \"strict_half\",
      when: { freeUntilHoursBeforeCheckIn: 7 * 24 },
      keep: { kind: \"refundShareOfTotal\", share: 0.5 },
    }),
    Object.freeze({
      id: \"strict_none\",
      when: { before: \"checkIn\" },
      keep: { kind: \"everything\" },
    }),
  ]),
});

// Short sentence per rule, shown with the refund on the booking page.
const RULE_TEXT = Object.freeze({
  host_cancelled: \"The host cancelled, so you get everything back.\",
  request_withdrawn: \"The host had not answered yet, so cancelling is free.\",
  stay_started: \"The stay had already started, so nothing is refunded.\",
  no_policy:
    \"The listing states no cancellation policy, so no refund is promised.\",
  flexible_free: \"Cancelled at least 24 hours before check-in: full refund.\",
  flexible_late:
    \"Cancelled less than 24 hours before check-in: the first night is not refunded.\",
  moderate_free: \"Cancelled at least 5 days before check-in: full refund.\",
  moderate_late:
    \"Cancelled less than 5 days before check-in: the first night and half of the remaining nights are not refunded.\",
  strict_grace:
    \"Cancelled within 48 hours of booking, with check-in at least 14 days away: full refund.\",
  strict_half:
    \"Cancelled at least 7 days before check-in: half of the total is refunded.\",
  strict_none:
    \"Cancelled less than 7 days before check-in: nothing is refunded.\",
});

module.exports = { POLICIES, RULE_TEXT, HOUR_MS, DAY_MS };

// What a guest is told about a listing's cancellation policy (checkout page,
// P08-T03; booking page, P09-T01). There is ONE set of sentences:
// CANCELLATION_TERMS in src/config/constants.js, which describes the refund
// rules in src/config/cancellation.js that P09-T03 applies. This file only
// adds the sentence for a listing that states no policy.
const { CANCELLATION_TERMS } = require(\"./constants\");

const POLICY_TEXT = CANCELLATION_TERMS;

const NO_POLICY_TEXT =
  \"This listing does not state a cancellation policy, so no refund is promised.\";

/** The sentence for a policy value (undefined or unknown -> the no-policy sentence). */
function cancellationText(value) {
  return Object.hasOwn(POLICY_TEXT, value)
    ? POLICY_TEXT[value]
    : NO_POLICY_TEXT;
}

module.exports = { POLICY_TEXT, NO_POLICY_TEXT, cancellationText };

// The category strip on /listings (P05-T04). Every category is a rule over a
// field the Listing model really has, so a category link can only ever return
// listings that match it. `field` is one of:
//   vibe          the setting a host chose (beach, mountain, ...)
//   propertyType  the kind of property
//   roomType      what the guest gets
//   amenities     a listing must have ALL of the `values`
// A category the data cannot back (Trending, Castles, Skiing, ...) is not here.
// `slug` is what the URL carries: /listings?category=beach
const CATEGORIES = Object.freeze(
  [
    { slug: \"beach\", label: \"Beach\", icon: \"fa-umbrella-beach\", field: \"vibe\", values: [\"beach\"] },
    { slug: \"mountains\", label: \"Mountains\", icon: \"fa-mountain-sun\", field: \"vibe\", values: [\"mountain\"] },
    { slug: \"lakefront\", label: \"Lakefront\", icon: \"fa-water\", field: \"vibe\", values: [\"lake\"] },
    { slug: \"desert\", label: \"Desert\", icon: \"fa-sun\", field: \"vibe\", values: [\"desert\"] },
    { slug: \"countryside\", label: \"Countryside\", icon: \"fa-tree\", field: \"vibe\", values: [\"countryside\"] },
    { slug: \"city\", label: \"City\", icon: \"fa-city\", field: \"vibe\", values: [\"city\"] },
    { slug: \"farm-stays\", label: \"Farm stays\", icon: \"fa-tractor\", field: \"propertyType\", values: [\"farm_stay\"] },
    { slug: \"cabins\", label: \"Cabins\", icon: \"fa-house-chimney\", field: \"propertyType\", values: [\"cabin\"] },
    { slug: \"villas\", label: \"Villas\", icon: \"fa-landmark\", field: \"propertyType\", values: [\"villa\"] },
    { slug: \"apartments\", label: \"Apartments\", icon: \"fa-building\", field: \"propertyType\", values: [\"apartment\"] },
    { slug: \"amazing-pools\", label: \"Amazing pools\", icon: \"fa-person-swimming\", field: \"amenities\", values: [\"pool\"] },
    { slug: \"rooms\", label: \"Rooms\", icon: \"fa-bed\", field: \"roomType\", values: [\"private_room\", \"shared_room\"] },
  ].map((category) => Object.freeze({ ...category, values: Object.freeze([...category.values]) })),
);

const CATEGORY_SLUGS = Object.freeze(CATEGORIES.map((category) => category.slug));
const BY_SLUG = new Map(CATEGORIES.map((category) => [category.slug, category]));

/** The category for a slug, or null (also for anything that is not a string). */
function getCategory(slug) {
  return typeof slug === \"string\" ? (BY_SLUG.get(slug) ?? null) : null;
}

/**
 * The Mongo condition a category stands for, or null for an unknown slug.
 * Built only from this file's constants, never from request text.
 */
function categoryClause(slug) {
  const category = getCategory(slug);
  if (!category) return null;
  const values = [...category.values];
  return category.field === \"amenities\"
    ? { amenities: { $all: values } }
    : { [category.field]: { $in: values } };
}

module.exports = { CATEGORIES, CATEGORY_SLUGS, getCategory, categoryClause };

const cloudinary = require(\"cloudinary\").v2;
const multer = require(\"multer\");

// Credentials are applied by createApp() (src/app.js), not when this file is
// required, so importing it has no side effects.
function configureCloudinary({ cloudName, apiKey, apiSecret }) {
  cloudinary.config({
    cloud_name: cloudName,
    api_key: apiKey,
    api_secret: apiSecret,
  });
}

const UPLOAD_FOLDER = \"dimora_DEV\";
const MAX_IMAGE_BYTES = 5 * 1024 * 1024;
const MAX_UPLOAD_FILES = 10;
// Cloudinary refuses anything that is not one of these, whatever the browser
// said it was (defence in depth: src/services/images.js already checks the
// first bytes of every file before it is sent).
const ALLOWED_FORMATS = [\"jpg\", \"png\", \"webp\"];

// Files are held in memory, then streamed to Cloudinary. There is deliberately
// no fileFilter on the declared type: the browser chooses that, so it proves
// nothing. src/services/images.js looks at the file's real first bytes.
// Text fields of a multipart form are limited too (P17-T02): multer's default
// allows any number of fields of 1 MB each.
const limits = { fileSize: MAX_IMAGE_BYTES, fieldSize: 100 * 1024, fields: 100 };
const upload = multer({
  storage: multer.memoryStorage(),
  limits: { ...limits, files: 1 },
});
const uploadPhotos = multer({
  storage: multer.memoryStorage(),
  limits: { ...limits, files: MAX_UPLOAD_FILES },
});

function uploadBuffer(buffer) {
  return new Promise((resolve, reject) => {
    const stream = cloudinary.uploader.upload_stream(
      {
        folder: UPLOAD_FOLDER,
        resource_type: \"image\",
        allowed_formats: ALLOWED_FORMATS,
      },
      (err, result) => (err ? reject(err) : resolve(result)),
    );
    stream.end(buffer);
  });
}

// Runs after upload.single(...). Sets req.file.path / req.file.filename to the
// same values multer-storage-cloudinary used to set, so controllers are unchanged.
async function uploadToCloudinary(req, res, next) {
  try {
    if (req.file) {
      const result = await uploadBuffer(req.file.buffer);
      req.file.path = result.secure_url;
      req.file.filename = result.public_id;
      delete req.file.buffer;
    }
    next();
  } catch (err) {
    next(err);
  }
}

// Best-effort removal of an image we uploaded (replaced image, or an upload
// whose listing could not be saved). Never throws: a leftover image is not worth
// failing the request. Ignores ids outside our folder (e.g. old seed data).
async function deleteImage(publicId, log) {
  if (typeof publicId !== \"string\" || !publicId.startsWith(\"dimora_\")) {
    return false;
  }
  try {
    await cloudinary.uploader.destroy(publicId);
    return true;
  } catch (err) {
    if (log) log.warn({ err, publicId }, \"could not delete image\");
    return false;
  }
}

module.exports = {
  cloudinary,
  UPLOAD_FOLDER,
  deleteImage,
  configureCloudinary,
  upload,
  uploadPhotos,
  uploadBuffer,
  uploadToCloudinary,
  MAX_IMAGE_BYTES,
  MAX_UPLOAD_FILES,
  ALLOWED_FORMATS,
};

// Lists shared by the listing model, the listing wizard (P04-T02) and its
// views. `value` is what is stored; `label` is what a host sees.

const PROPERTY_TYPES = [
  { value: \"house\", label: \"House\" },
  { value: \"apartment\", label: \"Apartment\" },
  { value: \"villa\", label: \"Villa\" },
  { value: \"cabin\", label: \"Cabin\" },
  { value: \"cottage\", label: \"Cottage\" },
  { value: \"farm_stay\", label: \"Farm stay\" },
  { value: \"hotel\", label: \"Hotel or guest house\" },
  { value: \"other\", label: \"Something else\" },
];

const ROOM_TYPES = [
  { value: \"entire_place\", label: \"The whole place\" },
  { value: \"private_room\", label: \"A private room\" },
  { value: \"shared_room\", label: \"A shared room\" },
];

// The setting around a place (P05-T04). A host picks one; the category strip on
// /listings uses it for Beach, Mountains, Lake, Desert, Countryside and City.
const VIBES = [
  { value: \"beach\", label: \"Beach\" },
  { value: \"mountain\", label: \"Mountains\" },
  { value: \"lake\", label: \"Lake\" },
  { value: \"desert\", label: \"Desert\" },
  { value: \"countryside\", label: \"Countryside\" },
  { value: \"city\", label: \"City\" },
];

const CANCELLATION_POLICIES = [
  { value: \"flexible\", label: \"Flexible\" },
  { value: \"moderate\", label: \"Moderate\" },
  { value: \"strict\", label: \"Strict\" },
];

// What each cancellation policy says on a booking (P09-T01, P09-T03). Plain
// wording shown to guests at checkout and on the booking page. The refund rules
// that enforce it are DATA in src/config/cancellation.js: change a sentence and
// its rule together (tests/unit/refunds.test.js checks the numbers).
