const PAGE_SIZE = 12;

module.exports.PAGE_SIZE = PAGE_SIZE;

// The sort choices offered on the listings page, in the order shown.
const SORT_OPTIONS = Object.freeze([
  { value: \"relevance\", label: \"Best match\" },
  { value: \"price_asc\", label: \"Price: low to high\" },
  { value: \"price_desc\", label: \"Price: high to low\" },
  { value: \"rating\", label: \"Top rated\" },
  { value: \"newest\", label: \"Newest\" },
]);
const DEFAULT_SORT = \"relevance\";

module.exports.SORT_OPTIONS = SORT_OPTIONS;

module.exports.index = async (req, res) => {
  const now = new Date();
  const { parsed, filter, takenIds } = await listingFilterFor(req.query, {
    now,
  });
  const sort = parsed.state.sort || DEFAULT_SORT;
  const requested = parsed.page;

  const total = await Listing.countDocuments(filter);
  const totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE));
  // A page past the last one (with results to show) is explained, not fetched.
  const outOfRange = total > 0 && requested > totalPages;
  const page = Math.min(requested, totalPages);

  // A trip purpose re-orders \"Best match\" (P15-T06). It needs that sort and no
  // search words (words have their own relevance), and says so when it cannot act.
  const purpose = getPurpose(parsed.state.purpose);
  const hasText = Boolean(filter.$text);
  const purposeActive = Boolean(purpose) && sort === \"relevance\" && !hasText;
  // Which ordering the page shows, for the click-through comparison; null for
  // the other sort orders and for word searches (not comparable).
  const rankVariant = sort === \"relevance\" && !hasText ? (purpose ? purpose.slug : \"default\") : null;

  let listings = [];
  if (!outOfRange) {
    if (purposeActive) {
      listings = await rankedPage({ Listing, filter, purpose, page, pageSize: PAGE_SIZE });
    } else {
      const spec = sortSpec(sort, { hasText });
      const cursor = spec.projection
        ? Listing.find(filter, spec.projection)
        : Listing.find(filter);
      listings = await cursor
        .sort(spec.sort)
        .skip((page - 1) * PAGE_SIZE)
        .limit(PAGE_SIZE);
    }
    // Counters only, never in the way of the page, and not for crawlers.
    if (rankVariant && listings.length > 0 && !/bot|crawl|spider|preview|monitor/i.test(req.get(\"user-agent\") || \"\")) {
      recordShown({ ListingStat, ids: listings.map((l) => l._id), variant: rankVariant }).catch(() => {});
    }
  }

  const pageState = { ...parsed.state };
  delete pageState.page;
  // A sort order alone is not a search.
  const filterState = { ...pageState };
  delete filterState.sort;
  delete filterState.purpose;
  const filtered = Object.keys(filterState).length > 0;

  // Sort links keep the search and start again at page 1.
  const sortLinks = SORT_OPTIONS.map((option) => ({
    ...option,
    current: option.value === sort,
    href: listingsUrl(pageState, {
      sort: option.value === DEFAULT_SORT ? undefined : option.value,
    }),
  }));
  // \"Plan for\": the purposes, each as a link that keeps the search (P15-T06).
  const purposeLinks = [
    { slug: \"\", label: \"Any trip\", current: !purpose, href: listingsUrl(pageState, { purpose: undefined }) },
    ...PURPOSES.map((p) => ({
      slug: p.slug,
      label: p.label,
      current: Boolean(purpose) && purpose.slug === p.slug,
      href: listingsUrl(pageState, { purpose: p.slug }),
    })),
  ];
  const purposeInfo = purpose
    ? {
        slug: purpose.slug,
        label: purpose.label,
        summary: purpose.summary,
        rules: purpose.rules,
        max: maxScore(purpose),
        active: purposeActive,
        why: purposeActive
          ? null
          : hasText
            ? \"Trip ranking is off while you search by words.\"
            : \"Trip ranking only applies to the Best match order.\",
      }
    : null;

  const from = (page - 1) * PAGE_SIZE + 1;
  const showing =
    total > 0 && !outOfRange && totalPages > 1
      ? { from, to: from + listings.length - 1 }
      : null;

  // Only an empty, filtered search gets suggestions (at most 5 extra queries).
  const suggestions =
    total === 0 && filtered
      ? await suggestForEmptyResults({ Listing, parsed, takenIds })
      : null;

  res.render(\"listings/index.ejs\", {
    allListings: listings,
    state: { ...pageState, ...(page > 1 ? { page } : {}) },
    pageState,
    form: parsed.form,
    errors: parsed.errors,
    chips: activeChips(pageState),
    filterCount: filterCount(pageState),
    resetFiltersHref: resetFiltersHref(pageState),
    categories: categoryLinks(pageState),
    activeCategory: getCategory(pageState.category),
    panel: {
      values: pageState,
      typed: parsed.drawer,
      fields: PANEL_FIELDS,
      lists: { PROPERTY_TYPES, ROOM_TYPES, AMENITIES, RADII_KM },
    },
    hiddenFields,
    mapQuery: new URLSearchParams(queryPairs(pageState)).toString(),
    sortLinks,
    purposeLinks,
    purposeInfo,
    rankVariant,
    showing,
    outOfRange,
    lastPageHref: listingsUrl(pageState, { page: totalPages }),
    suggestions,
    total,
    page,
    totalPages,
    filtered,
    suggestions,
    today: formatDateOnly(todayIn(DEFAULT_TIMEZONE, now)),
    pageTitle: filtered
      ? \"Search results\"
      : page > 1
        ? `Explore stays (page ${page})`
        : \"Explore stays\",
    pageDescription: \"Browse places to stay on Dimora.\",
  });
};

// GET /api/search/map?bbox=west,south,east,north&<the listings page filters>
// GeoJSON of at most MAP_RESULT_CAP stays (approximate points only); without
// `bbox` it covers every place. `meta` says how many matched and whether the
// list was cut. Wrong filter values are ignored as on the page; a wrong bbox is
// a 400.
// Suggestions for the destination boxes (P05-T06). `q` is whatever was typed; a
// missing, repeated or too short `q` is an empty list, not an error.
module.exports.destinations = async (req, res) => {
  const q = typeof req.query.q === \"string\" ? req.query.q : \"\";
  const suggestions = await suggestDestinations({ Listing, q });
  res.set(\"Cache-Control\", \"private, max-age=30\");
  res.json({ suggestions });
};

module.exports.mapData = async (req, res) => {
  let boxes = null;
  if (req.query.bbox !== undefined) {
    const box = parseBbox(req.query.bbox);
    if (!box.ok) throw new ValidationError(box.message);
    boxes = box.boxes;
  }
  const { filter } = await listingFilterFor(req.query);
  const result = await searchMap(Listing, filter, boxes);
  res.set(\"Cache-Control\", \"no-store\");
  res.json(result);
};

// Editing a listing section by section (P04-T04): /listings/:id/edit shows the
// same forms as the wizard, each saved on its own. The address is special: a
// changed address is looked up first and only saved after the host confirms the
// match. Validation is the wizard's (src/validation/wizard.js), so a published
// listing can never be edited into something the wizard would have refused.
const wizard = require(\"../services/wizard\");
const { galleryOf, MAX_IMAGES } = require(\"../services/images\");
const {
  lookupAddress,
  LocationNotFoundError,
  GeocoderUnavailableError,
} = require(\"../services/geocoding\");
const { rememberLookup, takeLookup } = require(\"../services/locationConfirm\");
const { validateStep } = require(\"../validation/wizard\");
const { NotFoundError } = require(\"../utils/errors\");
const {
  PROPERTY_TYPES,
  ROOM_TYPES,
  VIBES,
  CANCELLATION_POLICIES,
  AMENITIES,
  ACCESSIBILITY_FEATURES,
} = require(\"../config/constants\");

// URL key -> wizard step number. Photos have their own routes.
const SECTIONS = Object.freeze({ basics: 1, location: 2, details: 3, pricing: 5 });
const LISTS = { PROPERTY_TYPES, ROOM_TYPES, VIBES, CANCELLATION_POLICIES, AMENITIES, ACCESSIBILITY_FEATURES };

const editUrl = (listing, key) => `/listings/${listing._id}/edit${key ? `#${key}` : \"\"}`;

/** The edit page. `failed` = { key, values, errors, formError } for a section that was refused. */
function renderEdit(res, listing, { failed, status = 200 } = {}) {
  const values = {};
  const errors = {};
  for (const [key, step] of Object.entries(SECTIONS)) {
    const own = failed && failed.key === key;
    values[key] = own && failed.values ? failed.values : wizard.formValues(listing, step);
    errors[key] = own && failed.errors ? failed.errors : {};
  }
  res.status(status).render(\"listings/edit.ejs\", {
    listing,
    values,
    errors,
    formError: failed && failed.formError,
    failedKey: failed && failed.key,
    lists: LISTS,
    gallery: galleryOf(listing),
    maxImages: MAX_IMAGES,
    pageTitle: `Edit ${listing.title}`,
    pageDescription: \"Change the details of your listing.\",
  });
}

module.exports.renderEdit = renderEdit;
module.exports.SECTIONS = SECTIONS;

module.exports.renderEditForm = (req, res) => {
  // A listing still being written belongs in the wizard.
  if (req.listing.status === \"draft\") {
    return res.redirect(`/host/listings/${req.listing._id}`);
  }
  renderEdit(res, req.listing);
};

module.exports.save = async (req, res) => {
  const listing = req.listing; // loaded by authorize(\"listing:edit\")
  const key = req.params.key;
  if (!Object.hasOwn(SECTIONS, key)) {
    throw new NotFoundError(\"That part of the listing does not exist.\");
  }
  if (listing.status === \"draft\") {
    return res.redirect(`/host/listings/${listing._id}`);
  }
  const step = SECTIONS[key];

  // `confirmed` belongs to the location confirmation form, not to the address.
  const { confirmed, ...body } = req.body ?? {};
  const { value, errors } = validateStep(step, body);
  if (!value) {
    return renderEdit(res, listing, {
      failed: { key, values: body, errors },
      status: 400,
    });
  }

  let geometry;
  if (step === 2 && wizard.addressChanged(listing, value)) {
    const pending = confirmed === \"on\" ? takeLookup(req.session, listing._id, value) : null;
    if (pending) {
      geometry = pending.geometry;
    } else {
      let found;
      try {
        found = await lookupAddress({
          location: wizard.addressQuery(value),
          country: value.country,
        });
      } catch (err) {
        if (err instanceof LocationNotFoundError) {
          return renderEdit(res, listing, {
            failed: { key, values: body, errors: { line1: err.message } },
            status: 400,
          });
        }
        if (err instanceof GeocoderUnavailableError) {
          if (req.log) req.log.warn({ err }, \"geocoding failed\");
          return renderEdit(res, listing, {
            failed: { key, values: body, formError: err.message },
            status: 503,
          });
        }
        throw err;
      }
      rememberLookup(req.session, listing._id, value, found);
      return res.render(\"listings/confirm-location.ejs\", {
        listing,
        address: value,
        placeName: found.placeName,
        pageTitle: \"Confirm the location\",
        pageDescription: \"Check that we found the right place.\",
      });
    }
  }

  wizard.applyStep(listing, step, value, { geometry });
  await listing.save();
  req.flash(\"success\", \"Changes saved.\");
  res.redirect(editUrl(listing, key));
};

// /trips (a guest's bookings in four tabs) and /trips/:id (one booking's
// confirmation page, also readable by the booking's host and by an admin).
const Reservation = require(\"../models/reservation\");
const { can } = require(\"../policies\");
const { sameId } = require(\"../policies/shared\");
const { listTrips, describeTrip } = require(\"../services/trips\");
const reviewService = require(\"../services/reviews\");
const { cancelBooking } = require(\"../services/cancellations\");
const modifications = require(\"../services/modifications\");
const {
  lineLabel,
  referenceOf,
  formatStayDate,
  formatStayWeekday,
} = require(\"../services/trips\");
const { formatMoney } = require(\"../utils/money\");
const { formatDateOnly, todayIn, DEFAULT_TIMEZONE } = require(\"../utils/dates\");
const {
  NotFoundError,
  ConflictError,
  ValidationError,
  PriceChangedError,
} = require(\"../utils/errors\");

const OBJECT_ID = /^[0-9a-f]{24}$/i;

module.exports.index = async (req, res) => {
  const trips = await listTrips({}, req.user._id, {
    tab: req.query.tab,
    page: req.query.page,
    windowDays: req.app.locals.reviewWindowDays,
  });
  res.render(\"trips/index.ejs\", { ...trips, pageTitle: \"Your trips\" });
};

module.exports.show = async (req, res) => {
  const { id } = req.params;
  const reservation = OBJECT_ID.test(id)
    ? await Reservation.findById(id)
        .populate(
          \"listing\",
          \"title address location country geometry deletedAt\",
        )
        .populate(\"host\", \"displayName username email\")
        .populate(\"guest\", \"displayName username\")
        .lean()
    : null;
  // Someone who may not see it gets the same answer as for a booking that does
  // not exist: the page never confirms that a reference is real.
  if (!reservation || !can(\"reservation:view\", req.user, reservation)) {
    throw new NotFoundError(\"That booking does not exist.\");
  }
  const viewerRole = sameId(reservation.guest, req.user._id)
    ? \"guest\"
    : sameId(reservation.host, req.user._id)
      ? \"host\"
      : \"admin\";
  // The review form, the review itself, or why there is none (P12-T02).
  const review =
    viewerRole === \"guest\"
      ? await reviewService.stateFor({
          user: req.user,
          reservation,
          windowDays: req.app.locals.reviewWindowDays,
          editDays: req.app.locals.reviewEditDays,
        })
      : { state: \"none\" };
  const trip = describeTrip(reservation, { viewerRole, formatMoney, review });
  res.set(\"Cache-Control\", \"no-store\"); // contains contact details and an address
  res.render(\"trips/show.ejs\", {
    trip,
    pageTitle: `Booking ${trip.reference}`,
  });
};

// POST /trips/:id/cancel: the guest cancels (P09-T03). A booking that changed
// under them (answered, cancelled, over) is shown again with the reason.
module.exports.cancel = async (req, res) => {
  let result;
  try {
    result = await cancelBooking(
      { logger: req.log },
      {
        id: req.params.id,
        user: req.user,
        reason: req.body ? req.body.reason : undefined,
      },
    );
  } catch (err) {
    if (err instanceof ConflictError) {
      req.flash(\"error\", err.message);
      return res.redirect(`/trips/${req.params.id}`);
    }
    throw err;
  }
  req.flash(
    \"success\",
    \"Your booking is cancelled and the dates are free again. The refund below is calculated only: Dimora does not move money yet.\",
  );
  return res.redirect(`/trips/${result.reservation._id}`);
};

// ---- Change the dates (P09-T04) ----------------------------------------

// A query or body value is used only when it is one plain string (never an
// array or an object made by repeated or bracketed parameters).
const plain = (value) => (typeof value === \"string\" ? value : undefined);

const changePath = (id, { in: checkIn, out } = {}) => {
  const q = [];
  if (checkIn) q.push(`in=${encodeURIComponent(checkIn)}`);
  if (out) q.push(`out=${encodeURIComponent(out)}`);
  return `/trips/${id}/change${q.length ? `?${q.join(\"&\")}` : \"\"}`;
};

// What the change page prints. The new stay's amounts are the ones the service
// will store (the same pricing call), nothing is computed here.
function changeView(preview, extra = {}) {
  const { reservation, listing, quote } = preview;
  const snap = reservation.listingSnapshot || {};
  const tz = snap.timezone || DEFAULT_TIMEZONE;
  const price = reservation.pricingSnapshot || {};
  const currency = price.currency || \"INR\";
  const id = String(reservation._id);
  return {
    id,
    reference: referenceOf(reservation),
    title: snap.title || (listing && listing.title) || \"Your stay\",
    reapproval: preview.reapproval,
    instantBook: Boolean(snap.instantBook),
    current: {
      inLabel: `${formatStayWeekday(reservation.checkIn)}, ${formatStayDate(reservation.checkIn)}`,
      outLabel: `${formatStayWeekday(reservation.checkOut)}, ${formatStayDate(reservation.checkOut)}`,
      inIso: formatDateOnly(reservation.checkIn),
      outIso: formatDateOnly(reservation.checkOut),
      nights: reservation.nights,
      guests: reservation.guests,
      totalText: formatMoney(price.totalMinor, currency),
    },
    form: {
      in: preview.checkIn ? formatDateOnly(preview.checkIn) : \"\",
      out: preview.checkOut ? formatDateOnly(preview.checkOut) : \"\",
    },
    minDate: formatDateOnly(todayIn(tz)),
    problems: preview.problems.map((p) => p.message),
    proposal: quote
      ? {
          inLabel: `${formatStayWeekday(preview.checkIn)}, ${formatStayDate(preview.checkIn)}`,
          outLabel: `${formatStayWeekday(preview.checkOut)}, ${formatStayDate(preview.checkOut)}`,
          nights: quote.nights,
          lines: (quote.lines || []).map((line) => ({
            label: lineLabel(line, formatMoney, quote.currency),
            amount: formatMoney(line.amountMinor, quote.currency),
            included: Boolean(line.included),
          })),
          totalText: formatMoney(quote.totalMinor, quote.currency),
          totalMinor: quote.totalMinor,
          difference: modifications.describeDifference(preview.differenceMinor, {
            formatMoney,
            currency: quote.currency,
          }),
        }
      : null,
    priceChanged: extra.previousTotalMinor
      ? { previousText: formatMoney(extra.previousTotalMinor, currency) }
      : null,
  };
}

async function renderChange(req, res, status, preview, extra) {
  res.set(\"Cache-Control\", \"no-store\");
  res.status(status).render(\"trips/change.ejs\", {
    change: changeView(preview, extra),
    pageTitle: \"Change dates\",
  });
}

// GET /trips/:id/change[?in=&out=]: the form, and with dates the new price and
// the difference. Changes nothing.
module.exports.changeForm = async (req, res) => {
  let preview;
  try {
    preview = await modifications.previewChange({
      id: req.params.id,
      user: req.user,
      in: plain(req.query.in),
      out: plain(req.query.out),
    });
  } catch (err) {
    if (err instanceof ConflictError) {
      req.flash(\"error\", err.message);
      return res.redirect(`/trips/${req.params.id}`);
    }
    throw err;
  }
  return renderChange(req, res, 200, preview);
};

// POST /trips/:id/change: applies the change the guest confirmed. The total
// they looked at travels with the form; the server compares it with its own.
module.exports.change = async (req, res) => {
  const body = req.body || {};
  const stay = { in: plain(body.in), out: plain(body.out) };
  let result;
  try {
    result = await modifications.changeDates({
      id: req.params.id,
      user: req.user,
      ...stay,
      expectedTotalMinor: plain(body.expectedTotalMinor),
    });
  } catch (err) {
    if (err instanceof PriceChangedError) {
      // Nothing changed: show the new price and ask again.
      const preview = await modifications.previewChange({
        id: req.params.id,
        user: req.user,
        ...stay,
      });
      return renderChange(req, res, 409, preview, {
        previousTotalMinor: Number(plain(body.expectedTotalMinor)) || null,
      });
    }
    if (err instanceof ConflictError && err.code === \"nights_unavailable\") {
      req.flash(\"error\", \"Some of those nights were just taken. Please choose other dates.\");
      return res.redirect(changePath(req.params.id, stay));
    }
    if (err instanceof ConflictError) {
      req.flash(\"error\", err.message);
      return res.redirect(`/trips/${req.params.id}`);
    }
    if (err instanceof ValidationError && err.code !== \"validation_error\") {
      req.flash(\"error\", err.message);
      return res.redirect(changePath(req.params.id, stay));
    }
    throw err;
  }
  req.flash(
    \"success\",
    result.reapproval
      ? \"Your new dates were sent back to the host, who has 24 hours to answer. The new nights are held for you meanwhile. (Simulation: no payment was taken or returned.)\"
      : \"Your dates are changed. The price difference is recorded only: Dimora does not take or return money yet.\",
  );
  return res.redirect(`/trips/${result.reservation._id}`);
};

const mongoose = require(\"mongoose\");
const passport = require(\"passport\");
const User = require(\"../models/user\");
const { signupSchema } = require(\"../validation\");
const { safeRedirectPath } = require(\"../utils/safeRedirect\");
const { sendVerification } = require(\"../services/emailAuth\");

// What the visitor is told. None of this text comes from the database driver,
// passport or Mongoose.
const MESSAGES = Object.freeze({
  // Same text for an unknown user, a wrong password, a locked account and a
  // deleted account, so the form cannot be used to find out which usernames exist.
  loginFailed:
    \"Incorrect username or password. After several failed attempts an account is locked for a while.\",
  suspended:
    \"This account is suspended. Contact support if you think this is a mistake.\",
  usernameTaken: \"That username is already taken. Choose another one.\",
  // Does not say which of the two was the problem: a taken email must not be
  // confirmable from the signup form.
  cannotCreate:
    \"We couldn't create an account with those details. If you already have an account, log in instead.\",
  signupInvalid: \"Please check the details you entered and try again.\",
});

// The unique index on `email` (P02-T01) rejects a second account with the same
// address with a duplicate-key error.
function isDuplicateEmailError(err) {
  if (!err || err.code !== 11000) return false;
  if (err.keyPattern && err.keyPattern.email) return true;
  return typeof err.message === \"string\" && err.message.includes(\"email\");
}

function isUsernameTakenError(err) {
  return Boolean(err) && err.name === \"UserExistsError\";
}

function isDuplicateUsernameError(err) {
  if (!err || err.code !== 11000) return false;
  if (err.keyPattern && err.keyPattern.username) return true;
  return typeof err.message === \"string\" && err.message.includes(\"username\");
}

module.exports.signup = async (req, res, next) => {
  const { error, value } = signupSchema.validate(req.body ?? {}, {
    abortEarly: false,
    // Fields the form does not have (role, status, ...) are dropped here and
    // below only username, email and password are used.
    stripUnknown: true,
    errors: { wrap: { label: false } },
  });
  if (error) {
    // Joi messages for this schema are our own text (see validation/index.js).
    // One flash entry: the layout prints the array joined by bare commas.
    const messages = [...new Set(error.details.map((d) => d.message))];
    req.flash(\"error\", messages.join(\" \"));
    return res.redirect(\"/signup\");
  }

  try {
    const { username, email, password } = value;
    const registeredUser = await User.register(
      new User({ email, username }),
      password,
    );
    // Ask for a confirmed address (P02-T05). A failed email never fails the signup.
    let confirmationSent = false;
    if (req.app.locals.emailVerificationRequired) {
      try {
        await sendVerification({
          user: registeredUser,
          emailService: req.app.locals.emailService,
          baseUrl: req.app.locals.appBaseUrl,
        });
        confirmationSent = true;
      } catch (mailErr) {
        const log = req.app.locals.logger;
        if (log && log.error) log.error({ err: { name: mailErr.name, message: mailErr.message } }, \"verification email failed\");
      }
    }
    req.login(registeredUser, (err) => {
      if (err) {
        return next(err);
      }
      req.flash(
        \"success\",
        confirmationSent
          ? \"User registered successfully. We sent a link to confirm your email address.\"
          : \"User registered successfully\",
      );
      res.redirect(\"/listings\");
    });
  } catch (e) {
    if (isUsernameTakenError(e) || isDuplicateUsernameError(e)) {
      req.flash(\"error\", MESSAGES.usernameTaken);
    } else if (isDuplicateEmailError(e)) {
      req.flash(\"error\", MESSAGES.cannotCreate);
    } else if (e instanceof mongoose.Error.ValidationError) {
      req.flash(\"error\", MESSAGES.signupInvalid);
    } else {
      // Unexpected (database down, ...): the error page, with the real error
      // in the log only.
      return next(e);
    }
    res.redirect(\"/signup\");
  }
};

module.exports.renderSignupForm = (req, res) => {
  res.render(\"./users/signup.ejs\", {
    pageTitle: \"Sign up\",
    pageDescription: \"Create a Dimora account to book stays or list your home.\",
  });
};
module.exports.renderLoginForm = (req, res) => {
  res.render(\"./users/login.ejs\", {
    pageTitle: \"Log in\",
    pageDescription: \"Log in to your Dimora account.\",
    next: safeRedirectPath(req.query && req.query.next, \"\"),
  });
};

function failLogin(req, res, message) {
  req.flash(\"error\", message);
  return res.redirect(\"/login\");
}

// passport.authenticate with a callback instead of failureRedirect/failureFlash:
// the failure text is ours (never passport's or the plugin's), and the account
// status is checked after the password so a stranger learns nothing from it.
module.exports.login = (req, res, next) => {
  passport.authenticate(\"local\", (err, user) => {
    if (err) return next(err);
    if (!user) return failLogin(req, res, MESSAGES.loginFailed);
    if (user.status === \"deleted\") {
      return failLogin(req, res, MESSAGES.loginFailed);
    }
    if (user.status === \"suspended\") {
      return failLogin(req, res, MESSAGES.suspended);
    }
    // req.logIn starts a new session (passport 0.7), so a session id set before
    // login cannot be reused afterwards (session fixation).
    req.logIn(user, (loginErr) => {
      if (loginErr) return next(loginErr);
      req.flash(\"success\", \"Welcome back to Dimora ,You are logged in\");
      res.redirect(res.locals.redirectUrl || \"/listings\");
    });
  })(req, res, next);
};

module.exports.logout = (req, res, next) => {
  req.logout((err) => {
    if (err) {
      return next(err);
    }
    req.flash(\"success\", \"You are logged out\");
    res.redirect(\"/listings\");
  });
};

