// A member's list of saved stays (P10-T01). Every member gets one default list
// (\"Saved\"), created the first time they save a stay. Items live in
// WishlistItem so a list can hold 100 stays without growing one document.
const mongoose = require(\"mongoose\");
const { DEFAULT_NAME } = require(\"../config/wishlists\");
const Schema = mongoose.Schema;

const wishlistSchema = new Schema(
  {
    owner: { type: Schema.Types.ObjectId, ref: \"User\", required: true },
    name: { type: String, trim: true, maxlength: 60, default: DEFAULT_NAME },
    isDefault: { type: Boolean, default: false },
    // A read-only share link (P10-T04): /shared/lists/<shareToken>. Unset = not
    // shared. The token is a capability like a \"anyone with the link\" address:
    // 24 random bytes, unique, removed when the owner stops sharing.
    shareToken: { type: String },
    sharedAt: { type: Date },
  },
  { timestamps: true },
);

// At most one default list per member, even when two requests race to make it.
wishlistSchema.index(
  { owner: 1, isDefault: 1 },
  { unique: true, partialFilterExpression: { isDefault: true } },
);
wishlistSchema.index({ owner: 1, name: 1 }, { unique: true });
wishlistSchema.index(
  { shareToken: 1 },
  { unique: true, partialFilterExpression: { shareToken: { $type: \"string\" } } },
);

module.exports = mongoose.model(\"Wishlist\", wishlistSchema);

// One saved stay in one list (P10-T01). `owner` is repeated here so \"which of
// these stays has this member saved?\" is a single indexed query.
const mongoose = require(\"mongoose\");
const Schema = mongoose.Schema;

const wishlistItemSchema = new Schema({
  wishlist: { type: Schema.Types.ObjectId, ref: \"Wishlist\", required: true },
  owner: { type: Schema.Types.ObjectId, ref: \"User\", required: true },
  listing: { type: Schema.Types.ObjectId, ref: \"Listing\", required: true },
  // The member's own note about this stay in this list (P10-T02), plain text.
  note: { type: String, trim: true, maxlength: 300 },
  createdAt: { type: Date, default: Date.now },
});

// A stay is in a list once: this index makes saving twice a no-op under races.
wishlistItemSchema.index({ wishlist: 1, listing: 1 }, { unique: true });
wishlistItemSchema.index({ owner: 1, createdAt: -1 });
wishlistItemSchema.index({ owner: 1, listing: 1 });

module.exports = mongoose.model(\"WishlistItem\", wishlistItemSchema);

// Who may open the admin area (P14-T01). `(user) => boolean`.
// Only an active admin: a suspended or deleted admin account has no access.
const { isAdmin } = require(\"./shared\");

function access(user) {
  return isAdmin(user);
}

module.exports = { access };

// Who may use a conversation (P11-T02). Only its two people: neither an admin
// nor anyone else. (An admin reaches a message only through a report, P12-T04.)
const { sameId, isActiveUser } = require(\"./shared\");

/** True when `user` is the guest or the host of `conversation` (active or not). */
function isParticipant(user, conversation) {
  return Boolean(
    user &&
    conversation &&
    (sameId(conversation.guest, user._id) ||
      sameId(conversation.host, user._id)),
  );
}

/**
 * Start a conversation about a listing (\"Contact host\"): any active member
 * except the listing's own host. Whether the host can receive messages is
 * checked by the service.
 */
function start(user, listing) {
  if (!isActiveUser(user) || !listing) return false;
  return !sameId(listing.owner, user._id);
}

/** Read a conversation: its guest or host, while their account is active. */
function view(user, conversation) {
  return isActiveUser(user) && isParticipant(user, conversation);
}

/** Send a message: same people as `view`. */
function send(user, conversation) {
  return view(user, conversation);
}

module.exports = { start, view, send, isParticipant };

// Policy registry (P02-T06). One place that says who may do what.
//
//   can(\"listing:edit\", req.user, listing)   -> true | false
//
// Policies are pure functions `(user, resource) => boolean`: no database, no
// request object, so they are easy to test (tests/unit/policies.test.js) and
// safe to call from views (`can(...)` in res.locals). Add new actions here and
// extend the matrix test; the `authorize()` middleware and the views pick them
// up by name.
const listing = require(\"./listing\");
const review = require(\"./review\");
const admin = require(\"./admin\");
const reservation = require(\"./reservation\");
const report = require(\"./report\");
const conversation = require(\"./conversation\");
const { isAdmin, hasRole } = require(\"./shared\");

const POLICIES = {
  \"listing:create\": listing.create,
  \"listing:edit\": listing.edit,
  \"listing:delete\": listing.delete,
  \"review:create\": review.create,
  \"review:delete\": review.delete,
  \"review:edit\": review.edit,
  \"review:reply\": review.reply,
  \"reservation:view\": reservation.view,
  \"reservation:respond\": reservation.respond,
  \"reservation:cancel\": reservation.cancel,
  \"reservation:modify\": reservation.modify,
  \"report:create\": report.create,
  \"conversation:start\": conversation.start,
  \"conversation:view\": conversation.view,
  \"conversation:send\": conversation.send,
  \"admin:access\": admin.access,
};

/**
 * @param {string} action   e.g. \"listing:edit\"
 * @param {object} [user]   req.user, undefined when anonymous
 * @param {object} [resource] the listing/review the action applies to
 * @returns {boolean}
 * @throws {Error} for an unknown action (a typo must fail loudly, not allow or deny silently)
 */
function can(action, user, resource) {
  const policy = POLICIES[action];
  if (!policy) throw new Error(`Unknown policy action: \"${action}\"`);
  return Boolean(policy(user, resource));
}

function actions() {
  return Object.keys(POLICIES);
}

module.exports = { can, actions, isAdmin, hasRole };

// Who may do what with a listing. `(user, listing) => boolean`.
// `user` is req.user (or undefined for an anonymous visitor).
const { sameId, isActiveUser, isAdmin } = require(\"./shared\");

/** Any active member can create a listing. */
function create(user) {
  return isActiveUser(user);
}

/** Only the host edits a listing (an admin moderates; see `remove`). */
function edit(user, listing) {
  return Boolean(
    isActiveUser(user) && listing && sameId(listing.owner, user._id),
  );
}

/** The host, or an admin. A listing without an owner can only be removed by an admin. */
function remove(user, listing) {
  return Boolean(listing) && (edit(user, listing) || isAdmin(user));
}

module.exports = { create, edit, delete: remove };

// Who may report what (P12-T04). `(user, target) => boolean`, where target is
// `{ owner }`: whoever made the thing being reported.
const { sameId, isActiveUser } = require(\"./shared\");

/** Any active member, except about their own listing, review or profile. */
function create(user, target) {
  if (!isActiveUser(user)) return false;
  return !(target && sameId(target.owner, user._id));
}

module.exports = { create };

// Who may do what with a booking. `(user, reservation) => boolean`.
// Cancelling (P09-T03) gets its own actions there.
const { sameId, isActiveUser, isAdmin } = require(\"./shared\");

/** The guest who booked it, the host of the place, or an admin (P09-T01). */
function view(user, reservation) {
  if (!reservation || !isActiveUser(user)) return false;
  return Boolean(
    sameId(reservation.guest, user._id) ||
    sameId(reservation.host, user._id) ||
    isAdmin(user),
  );
}

/**
 * Accept or decline a request (P09-T02): only the host of that booking. An
 * admin cannot answer for a host, and a suspended host cannot answer at all.
 */
function respond(user, reservation) {
  if (!reservation || !isActiveUser(user)) return false;
  return sameId(reservation.host, user._id);
}

/**
 * Cancel a booking (P09-T03): its guest or its host, nobody else (an admin
 * cannot cancel for either side). Which side is acting is decided by the
 * service from who the user is; the state machine says what each side may
 * cancel.
 */
function cancel(user, reservation) {
  if (!reservation || !isActiveUser(user)) return false;
  return (
    sameId(reservation.guest, user._id) || sameId(reservation.host, user._id)
  );
}

/**
 * Change the dates of a booking (P09-T04): only the guest who made it. The
 * host cannot move a guest's stay (they decline or cancel), an admin cannot
 * act for the guest, and a suspended guest cannot change anything.
 */
function modify(user, reservation) {
  if (!reservation || !isActiveUser(user)) return false;
  return sameId(reservation.guest, user._id);
}

module.exports = { view, respond, cancel, modify };

// Who may do what with a review. `(user, review) => boolean`.
const { sameId, isActiveUser, isAdmin } = require(\"./shared\");

/** Any active member can write a review (eligibility rules arrive in P12-T01). */
function create(user) {
  return isActiveUser(user);
}

/** The author, or an admin. A review without an author can only be removed by an admin. */
function remove(user, review) {
  if (!review) return false;
  return Boolean(
    (isActiveUser(user) && sameId(review.author, user._id)) || isAdmin(user),
  );
}

/**
 * Only the author edits a review, and only while the account is active. An
 * admin moderates (hides) but never rewrites someone's words. Whether the edit
 * window is still open is decided by services/reviews.js, which knows the time.
 */
function edit(user, review) {
  return Boolean(
    review && isActiveUser(user) && sameId(review.author, user._id),
  );
}

/**
 * The host's reply (P12-T03). The resource is the LISTING the review is on:
 * only its owner may reply, edit the reply or take it back.
 */
function reply(user, listing) {
  return Boolean(
    listing && isActiveUser(user) && sameId(listing.owner, user._id),
  );
}

module.exports = { create, delete: remove, edit, reply };

// Small helpers shared by the policy files. Pure: no database, no Express.

/** Id of an ObjectId, a populated document, a plain { _id } or a string. */
function idOf(value) {
  if (value === undefined || value === null) return null;
  if (value._id !== undefined && value._id !== null) return String(value._id);
  // A bare ObjectId (some driver versions have no `_id` getter) or a string.
  if (typeof value !== \"object\" || typeof value.toHexString === \"function\") {
    return String(value);
  }
  return null; // an object that carries no id

}

/** True when both refer to the same id. A missing id never matches. */
function sameId(a, b) {
  const x = idOf(a);
  const y = idOf(b);
  return x !== null && y !== null && x === y;
}

/**
 * A logged-in account that may act. Accounts created before the v2 user model
 * have no `status`; they count as active. Suspended/deleted accounts can do
 * nothing.
 */
function isActiveUser(user) {
  return Boolean(
    user &&
    typeof user === \"object\" &&
    user._id !== undefined &&
    user._id !== null &&
    (user.status === undefined || user.status === \"active\"),
  );
}

function hasRole(user, role) {
  return isActiveUser(user) && user.role === role;
}

function isAdmin(user) {
  return hasRole(user, \"admin\");
}

module.exports = { idOf, sameId, isActiveUser, hasRole, isAdmin };

