// The \"edit my profile\" form (P02-T03). Only these three fields are accepted;
// anything else in the request (an id, a role, an email) is refused, so the form
// can never be used to change more than it shows.
const Joi = require(\"joi\");

// eslint-disable-next-line no-control-regex -- refusing control characters is the point
const NO_CONTROL_CHARS = /^[^\\u0000-\\u0009\\u000B\\u000C\\u000E-\\u001F\\u007F]*$/;

const profileSchema = Joi.object({
  displayName: Joi.string()
    .trim()
    .max(60)
    // eslint-disable-next-line no-control-regex -- refusing control characters is the point
    .pattern(/^[^\\u0000-\\u001F\\u007F]*$/)
    .allow(\"\")
    .default(\"\")
    .label(\"Display name\")
    .messages({
      \"string.max\": \"Display name must be 60 characters or fewer.\",
      \"string.pattern.base\": \"Display name cannot contain control characters.\",
    }),
  // Line breaks are kept (as \"\\n\"); other control characters are refused.
  bio: Joi.string()
    .trim()
    .max(500)
    .allow(\"\")
    .default(\"\")
    .custom((value) => value.replace(/\\r\\n?/g, \"\\n\"))
    .pattern(NO_CONTROL_CHARS)
    .label(\"Bio\")
    .messages({
      \"string.max\": \"Bio must be 500 characters or fewer.\",
      \"string.pattern.base\": \"Bio cannot contain control characters.\",
    }),
  removeAvatar: Joi.boolean()
    .truthy(\"on\", \"1\", \"true\")
    .falsy(\"off\", \"0\", \"false\", \"\")
    .default(false),
});

/**
 * @returns {{ value: object|undefined, errors: Record<string,string> }}
 */
function validateProfile(body) {
  const { error, value } = profileSchema.validate(body ?? {}, {
    abortEarly: false,
    errors: { wrap: { label: false } },
  });
  if (!error) return { value, errors: {} };
  const errors = {};
  for (const detail of error.details) {
    const field = detail.path[0] ?? \"form\";
    if (!errors[field]) errors[field] = detail.message;
  }
  return { value: undefined, errors };
}

module.exports = { validateProfile, profileSchema };

// Query of GET /api/listings/:id/quote?in=&out=&guests= (P08-T02). Only plain
// strings are accepted (a repeated parameter or in[x]=y is refused), dates are
// strict YYYY-MM-DD (ADR-003), guests a whole number. Problems are reported
// per field so the page can show each next to its input.
const { tryParseDateOnly, isAfter } = require(\"../utils/dates\");
const { ValidationError } = require(\"../utils/errors\");

const GUESTS = /^\\d{1,3}$/;

function dateField(query, name, label, fields) {
  const raw = query ? query[name] : undefined;
  if (raw === undefined || raw === \"\") {
    fields[name] = `${label} is required (YYYY-MM-DD).`;
    return null;
  }
  const date = typeof raw === \"string\" ? tryParseDateOnly(raw) : null;
  if (!date) {
    fields[name] = `${label} must be a valid date in YYYY-MM-DD format.`;
    return null;
  }
  return date;
}

/**
 * @returns {{checkIn: Date, checkOut: Date, guests: number}}
 * @throws {ValidationError} 400, with `.fields` = { in?, out?, guests? }
 */
function parseQuoteQuery(query) {
  const fields = {};
  const checkIn = dateField(query, \"in\", \"Check-in\", fields);
  const checkOut = dateField(query, \"out\", \"Check-out\", fields);
  if (checkIn && checkOut && !isAfter(checkOut, checkIn)) {
    fields.out = \"Check-out must be after check-in.\";
  }
  const rawGuests = query ? query.guests : undefined;
  let guests = null;
  if (rawGuests === undefined || rawGuests === \"\") {
    fields.guests = \"Guests is required (a whole number, 1 or more).\";
  } else if (
    typeof rawGuests !== \"string\" ||
    !GUESTS.test(rawGuests) ||
    Number(rawGuests) < 1
  ) {
    fields.guests = \"Guests must be a whole number, 1 or more.\";
  } else {
    guests = Number(rawGuests); // the place's own capacity is a booking rule
  }
  const names = Object.keys(fields);
  if (names.length > 0) {
    const err = new ValidationError(fields[names[0]]);
    err.fields = fields;
    throw err;
  }
  return { checkIn, checkOut, guests };
}

module.exports = { parseQuoteQuery };

// Search parameters (P05-T01): what a visitor may ask for. Everything is
// coerced to a plain string, number or boolean; an object or a list where a
// single value belongs is refused, so `?guests[$gt]=1` or `?guests=1&guests=9`
// can never reach the database as an operator. Unknown names are dropped.
const Joi = require(\"joi\");
const {
  PROPERTY_TYPE_VALUES,
  ROOM_TYPE_VALUES,
  AMENITY_VALUES,
  ACCESSIBILITY_VALUES,
} = require(\"../config/constants\");
const { CATEGORY_SLUGS } = require(\"../config/categories\");

const MAX_RUPEES = 1000000;
// Result order and page (P05-T03). The default order is \"relevance\".
const SORTS = Object.freeze([\"relevance\", \"price_asc\", \"price_desc\", \"rating\", \"newest\"]);
const DEFAULT_SORT = \"relevance\";
const MAX_PAGE = 1000;

const text = (label, max) =>
  Joi.string()
    .trim()
    .max(max)
    .allow(\"\")
    .label(label)
    .messages({ \"string.max\": `${label} must be at most ${max} characters.` });

const oneOrMany = (values, label) =>
  Joi.array()
    .single()
    .items(Joi.string().valid(...values))
    .unique()
    .max(values.length)
    .label(label)
    .messages({
      \"any.only\": `${label} is not one of the choices.`,
      \"array.includes\": `${label} is not one of the choices.`,
    });

const searchSchema = Joi.object({
  destination: text(\"Destination\", 100),
  keywords: text(\"Keywords\", 100),
  minPrice: Joi.number().empty(\"\").min(0).max(MAX_RUPEES).label(\"Minimum price\"),
  maxPrice: Joi.number().empty(\"\").min(0).max(MAX_RUPEES).label(\"Maximum price\"),
  guests: Joi.number().empty(\"\").integer().min(1).max(16).label(\"Guests\"),
  bedrooms: Joi.number().empty(\"\").integer().min(0).max(50).label(\"Bedrooms\"),
  propertyType: oneOrMany(PROPERTY_TYPE_VALUES, \"Property type\"),
  roomType: oneOrMany(ROOM_TYPE_VALUES, \"Room type\"),
  amenities: oneOrMany(AMENITY_VALUES, \"Amenities\"),
  access: oneOrMany(ACCESSIBILITY_VALUES, \"Accessibility features\"),
  instantBook: Joi.boolean().truthy(\"1\", \"true\", \"on\").falsy(\"0\", \"false\", \"off\", \"\"),
  // One category from the strip (P05-T04); anything else, including a list or an
  // object, is refused.
  category: Joi.string()
    .empty(\"\")
    .valid(...CATEGORY_SLUGS)
    .label(\"Category\")
    .messages({
      \"any.only\": \"Category is not one of the choices.\",
      \"string.base\": \"Category is not one of the choices.\",
    }),
  sort: Joi.string()
    .empty(\"\")
    .valid(...SORTS)
    .label(\"Sort order\")
    .messages({ \"any.only\": \"Sort order is not one of the choices.\" }),
  page: Joi.number()
    .empty(\"\")
    .integer()
    .min(1)
    .max(MAX_PAGE)
    .label(\"Page\")
    .messages({
      \"number.base\": \"Page must be a number.\",
      \"number.integer\": \"Page must be a whole number.\",
      \"number.min\": \"Page must be 1 or more.\",
      \"number.max\": `Page must be ${MAX_PAGE} or fewer.`,
    }),
})
  .custom((value, helpers) => {
    if (
      value.minPrice !== undefined &&
      value.maxPrice !== undefined &&
      value.minPrice > value.maxPrice
    ) {
      return helpers.error(\"price.order\");
    }
    return value;
  })
  .messages({ \"price.order\": \"The minimum price cannot be more than the maximum.\" });

const KNOWN = [
  \"destination\",
  \"keywords\",
  \"minPrice\",
  \"maxPrice\",
  \"guests\",
  \"bedrooms\",
  \"propertyType\",
  \"roomType\",
  \"amenities\",
  \"access\",
  \"instantBook\",
  \"category\",
  \"sort\",
  \"page\",
];

/**
 * @param {object} query req.query (or any plain object)
 * @returns {{ value: object, errors: Record<string,string> }} `value` holds the
 * valid, coerced parameters; `errors` the problems by name. Valid parameters
 * are returned even when others failed, so a page can still search with what
 * was understood and say what was not.
 */
function parseSearchParams(query) {
  const input = query && typeof query === \"object\" ? query : {};
  const { error, value } = searchSchema.validate(input, {
    abortEarly: false,
    stripUnknown: true,
    errors: { wrap: { label: false } },
  });
  if (!error) return { value: compact(value), errors: {} };

  const errors = {};
  const bad = new Set();
  for (const detail of error.details) {
    const field = detail.path[0] ?? \"maxPrice\";
    bad.add(field);
    if (!errors[field]) errors[field] = detail.message;
  }
  // Keep the parameters that were fine.
  const kept = {};
  for (const key of KNOWN) {
    if (bad.has(key) || !Object.hasOwn(input, key)) continue;
    const original = input[key];
    const single = searchSchema.extract(key);
    const { error: oneError, value: oneValue } = single.validate(original);
    if (!oneError) kept[key] = oneValue;
  }
  return { value: compact(kept), errors };
}

/** Drops empty strings so \"destination=\" means \"no destination\". */
function compact(value) {
  const out = {};
  for (const [key, v] of Object.entries(value)) {
    if (v === \"\" || v === undefined) continue;
    if (Array.isArray(v) && v.length === 0) continue;
    out[key] = v;
  }
  return out;
}

module.exports = {
  parseSearchParams,
  searchSchema,
  MAX_RUPEES,
  SORTS,
  DEFAULT_SORT,
  MAX_PAGE,
};

// The listings page's URL (P05-T02). One function turns `req.query` into
//   state         the valid parameters, in URL names (what links are built from)
//   form          what to show in the form inputs, even when it was invalid
//   errors        a message per parameter that was wrong
//   searchParams  the same filters under the search service's names (P05-T01)
//   stay          { checkIn, checkOut, flexDays } as date-only Dates when both
//                 are valid (flexDays: 3 when \"Available +-3 days\" is on, else 0)
//
// URL names: dest, radius (km around dest), in, out, guests, minPrice, maxPrice, type, amenities,
// minRating, sort, page (and, from the search service, keywords, bedrooms,
// roomType, instantBook) and `category` (one slug from the category strip,
// P05-T04). `destination` and the navbar's old `search` are
// accepted as `dest`; `amenities[]` as `amenities`; `propertyType` as `type`.
// Unknown names are ignored. A wrong value never stops the page: the valid
// parameters still search, and the errors are shown next to the form.
const Joi = require(\"joi\");
const { parseSearchParams } = require(\"./search\");
const { PURPOSE_SLUGS } = require(\"../config/purposes\");
const {
  BOOKING_WINDOW,
  DEFAULT_TIMEZONE,
  addDays,
  formatDateOnly,
  nightsBetween,
  todayIn,
  tryParseDateOnly,
} = require(\"../utils/dates\");

// \"Available +-3 days\" on the search page (P15-T04).
const FLEX_DAYS = 3;

const SORTS = Object.freeze([
  \"relevance\",
  \"price_asc\",
  \"price_desc\",
  \"rating\",
  \"newest\",
]);
const MAX_PAGE = 1000;
// \"Within N km of the destination\" (P06-T05).
const RADII_KM = Object.freeze([5, 10, 25, 50]);

// URL name -> the name the search service uses.
const SERVICE_NAME = Object.freeze({
  dest: \"destination\",
  type: \"propertyType\",
});
const URL_NAME = Object.freeze(
  Object.fromEntries(
    Object.entries(SERVICE_NAME).map(([url, service]) => [service, url]),
  ),
);

const isPlain = (value) =>
  value !== null && typeof value === \"object\" && !Array.isArray(value);

/** First usable raw value of any of these names (strings or arrays only). */
function pick(raw, names) {
  for (const name of names) {
    if (Object.hasOwn(raw, name) && raw[name] !== undefined) return raw[name];
  }
  return undefined;
}

const numberSchema = (label, min, max, { integer = false } = {}) => {
  let schema = Joi.number().empty(\"\").min(min).max(max).label(label);
  if (integer) schema = schema.integer();
  return schema;
};

const extraSchema = Joi.object({
  minRating: numberSchema(\"Minimum rating\", 1, 5).messages({
    \"number.base\": \"Minimum rating must be a number from 1 to 5.\",
    \"number.min\": \"Minimum rating must be a number from 1 to 5.\",
    \"number.max\": \"Minimum rating must be a number from 1 to 5.\",
  }),
  sort: Joi.string()
    .valid(...SORTS)
    .empty(\"\")
    .label(\"Sort\")
    .messages({ \"any.only\": `Sort must be one of: ${SORTS.join(\", \")}.` }),
  purpose: Joi.string()
    .valid(...PURPOSE_SLUGS)
    .empty(\"\")
    .label(\"Trip purpose\")
    .messages({ \"any.only\": `Trip purpose must be one of: ${PURPOSE_SLUGS.join(\", \")}.` }),
  page: numberSchema(\"Page\", 1, MAX_PAGE, { integer: true }).messages({
    \"number.base\": \"Page must be a whole number from 1.\",
    \"number.integer\": \"Page must be a whole number from 1.\",
    \"number.min\": \"Page must be a whole number from 1.\",
    \"number.max\": `Page must be at most ${MAX_PAGE}.`,
  }),
});

/** Dates: both or neither; real calendar days; today or later; at most 90 nights. */
function parseStay(rawIn, rawOut, { now, timeZone }) {
  const errors = {};
  const empty = (v) => v === undefined || v === \"\";
  if (empty(rawIn) && empty(rawOut)) return { errors };

  const parse = (value, name, label) => {
    if (empty(value)) {
      errors[name] =
        name === \"in\" ? \"Choose a check-in date.\" : \"Choose a check-out date.\";
      return null;
    }
    if (typeof value !== \"string\") {
      errors[name] = `${label} must be a single date.`;
      return null;
    }
    const date = tryParseDateOnly(value);
    if (!date) {
      errors[name] = `${label} must be a date like 2026-12-24.`;
      return null;
    }
    return date;
  };
  const checkIn = parse(rawIn, \"in\", \"Check-in\");
  const checkOut = parse(rawOut, \"out\", \"Check-out\");
  if (!checkIn || !checkOut) return { errors };

  const today = todayIn(timeZone, now);
  if (checkIn.getTime() < today.getTime()) {
    errors.in = \"Check-in cannot be in the past.\";
  } else if (
    checkIn.getTime() >
    addDays(today, BOOKING_WINDOW.MAX_HORIZON_DAYS).getTime()
  ) {
    errors.in = \"Check-in is too far ahead.\";
  } else if (checkOut.getTime() <= checkIn.getTime()) {
    errors.out = \"Check-out must be after check-in.\";
  } else if (
    nightsBetween(checkIn, checkOut) > BOOKING_WINDOW.MAX_STAY_NIGHTS
  ) {
    errors.out = `A stay can be at most ${BOOKING_WINDOW.MAX_STAY_NIGHTS} nights.`;
  }
  return Object.keys(errors).length
    ? { errors }
    : { checkIn, checkOut, errors };
}

/**
 * @param {object} query  req.query
 * @param {{ now?: Date, timeZone?: string }} [options]
 */
function parseListingQuery(
  query,
  { now = new Date(), timeZone = DEFAULT_TIMEZONE } = {},
) {
  const raw = isPlain(query) ? query : {};

  // ---- names the search service understands (P05-T01) ----
  const serviceInput = {
    destination: pick(raw, [\"dest\", \"destination\", \"search\"]),
    keywords: pick(raw, [\"keywords\"]),
    minPrice: pick(raw, [\"minPrice\"]),
    maxPrice: pick(raw, [\"maxPrice\"]),
    guests: pick(raw, [\"guests\"]),
    bedrooms: pick(raw, [\"bedrooms\"]),
    propertyType: pick(raw, [\"type\", \"propertyType\"]),
    roomType: pick(raw, [\"roomType\"]),
    amenities: pick(raw, [\"amenities\", \"amenities[]\"]),
    access: pick(raw, [\"access\", \"access[]\"]),
    instantBook: pick(raw, [\"instantBook\"]),
    category: pick(raw, [\"category\"]),
  };
  for (const key of Object.keys(serviceInput)) {
    if (serviceInput[key] === undefined) delete serviceInput[key];
  }
  const { value: serviceValue, errors: serviceErrors } =
    parseSearchParams(serviceInput);

  const errors = {};
  for (const [name, message] of Object.entries(serviceErrors)) {
    errors[URL_NAME[name] || name] = message;
  }
  const state = {};
  for (const [name, value] of Object.entries(serviceValue)) {
    state[URL_NAME[name] || name] = value;
  }

  // ---- minRating, sort, page ----
  const extraRaw = {};
  for (const name of [\"minRating\", \"sort\", \"purpose\", \"page\"]) {
    if (Object.hasOwn(raw, name)) extraRaw[name] = raw[name];
  }
  for (const [name, value] of Object.entries(extraRaw)) {
    const { error, value: ok } = extraSchema.extract(name).validate(value, {
      errors: { wrap: { label: false } },
    });
    if (error) errors[name] = error.details[0].message;
    else if (ok !== undefined) state[name] = ok;
  }

  // ---- dates ----
  const stay = parseStay(pick(raw, [\"in\"]), pick(raw, [\"out\"]), {
    now,
    timeZone,
  });
  Object.assign(errors, stay.errors);
  if (stay.checkIn) {
    state.in = formatDateOnly(stay.checkIn);
    state.out = formatDateOnly(stay.checkOut);
  }

  // ---- flexible dates (P15-T04): only \"3\" means on; it needs valid dates ----
  const rawFlex = pick(raw, [\"flex\"]);
  let flexDays = 0;
  if (rawFlex !== undefined && rawFlex !== \"\" && rawFlex !== \"0\") {
    if (rawFlex !== \"3\") {
      errors.flex = \"Flexible dates can only be 3 days either side.\";
    } else if (stay.checkIn) {
      flexDays = FLEX_DAYS;
      state.flex = FLEX_DAYS;
    }
  }

  // ---- radius around the destination (P06-T05): needs a valid destination ----
  const rawRadius = pick(raw, [\"radius\"]);
  if (rawRadius !== undefined && rawRadius !== \"\") {
    const km = typeof rawRadius === \"string\" && /^\\d{1,3}$/.test(rawRadius) ? Number(rawRadius) : NaN;
    if (!RADII_KM.includes(km)) errors.radius = `The distance can be ${RADII_KM.join(\", \")} km.`;
    else if (!state.dest) errors.radius = \"Choose a destination to search around.\";
    else state.radius = km;
  }

  // ---- what the form inputs show (strings only, even when invalid) ----
  const text = (names) => {
    const value = pick(raw, names);
    return typeof value === \"string\" ? value.slice(0, 100) : \"\";
  };
  const form = {
    dest: text([\"dest\", \"destination\", \"search\"]),
    in: text([\"in\"]),
    out: text([\"out\"]),
    guests: text([\"guests\"]),
  };

  // What the filter panel's inputs show (strings only, even when invalid).
  const drawer = {
    minPrice: text([\"minPrice\"]),
    maxPrice: text([\"maxPrice\"]),
    bedrooms: text([\"bedrooms\"]),
  };

  // The search service's names for the filters that were valid.
  const searchParams = {};
  for (const [name, value] of Object.entries(serviceValue))
    searchParams[name] = value;

  return {
    state,
    form,
    drawer,
    errors,
    searchParams,
    stay: stay.checkIn
      ? { checkIn: stay.checkIn, checkOut: stay.checkOut, flexDays }
      : null,
    page: state.page ?? 1,
  };
}

module.exports = { parseListingQuery, SORTS, MAX_PAGE, FLEX_DAYS, RADII_KM };

// Validation for each step of the listing wizard (P04-T02). One Joi schema per
// step; the browser is never trusted, so every step is checked on the server
// every time it is saved. Field names are the form's own (flat, no listing[...]).
// Messages are written for the person filling in the form.
const Joi = require(\"joi\");
const {
  PROPERTY_TYPE_VALUES,
  ROOM_TYPE_VALUES,
  VIBE_VALUES,
  CANCELLATION_POLICY_VALUES,
  AMENITY_VALUES,
  ACCESSIBILITY_VALUES,
} = require(\"../config/constants\");

const { parseSeasons, SEASON_FIELD_NAMES } = require(\"../utils/priceRules\");

const TIME = /^([01]\\d|2[0-3]):[0-5]\\d$/;

const text = (label, { min = 1, max, required = true } = {}) => {
  let rule = Joi.string().trim().max(max).label(label);
  rule = required ? rule.min(min).required() : rule.allow(\"\").default(\"\");
  return rule.messages({
    \"any.required\": `${label} is required.`,
    \"string.empty\": `${label} is required.`,
    \"string.min\": `${label} must be at least ${min} characters.`,
    \"string.max\": `${label} must be at most ${max} characters.`,
  });
};

const whole = (label, min, max) =>
  Joi.number().integer().min(min).max(max).required().label(label).messages({
    \"any.required\": `${label} is required.`,
    \"number.base\": `${label} must be a number.`,
    \"number.integer\": `${label} must be a whole number.`,
    \"number.min\": `${label} must be at least ${min}.`,
    \"number.max\": `${label} must be at most ${max}.`,
  });

const choice = (label, values) =>
  Joi.string()
    .valid(...values)
    .required()
    .label(label)
    .messages({
      \"any.required\": `Choose ${label.toLowerCase()}.`,
      \"string.empty\": `Choose ${label.toLowerCase()}.`,
      \"any.only\": `Choose ${label.toLowerCase()} from the list.`,
    });

const rupees = (label, min, max, { required = true } = {}) => {
  let rule = Joi.number().min(min).max(max).label(label).messages({
    \"number.base\": `${label} must be a number.`,
    \"number.min\": `${label} must be at least ₹${min}.`,
    \"number.max\": `${label} must be at most ₹${max.toLocaleString(\"en-IN\")}.`,
  });
  rule = required
    ? rule.required().messages({ \"any.required\": `${label} is required.` })
    : rule.empty(\"\").default(0);
  return rule;
};

const time = (label) =>
  Joi.string()
    .trim()
    .pattern(TIME)
    .required()
    .label(label)
    .messages({
      \"any.required\": `${label} is required.`,
      \"string.empty\": `${label} is required.`,
      \"string.pattern.base\": `${label} must look like 14:00.`,
    });

// Optional booking-rule fields (P07-T06): a blank field means the default, so
// a form posted without them (or an older client) keeps working.
const optionalWhole = (label, min, max, fallback) =>
  Joi.number()
    .integer()
    .min(min)
    .max(max)
    .empty(\"\")
    .default(fallback)
    .label(label)
    .messages({
      \"number.base\": `${label} must be a number.`,
      \"number.integer\": `${label} must be a whole number.`,
      \"number.min\": `${label} must be at least ${min}.`,
      \"number.max\": `${label} must be at most ${max}.`,
    });

const optionalTime = (label, fallback) =>
  Joi.string()
    .trim()
    .pattern(TIME)
    .empty(\"\")
    .default(fallback)
    .label(label)
    .messages({ \"string.pattern.base\": `${label} must look like 20:00.` });

const basics = Joi.object({
  title: text(\"Title\", { min: 5, max: 100 }),
  description: text(\"Description\", { min: 20, max: 3000 }),
  propertyType: choice(\"Property type\", PROPERTY_TYPE_VALUES),
  roomType: choice(\"What guests get\", ROOM_TYPE_VALUES),
  // Optional: \"\" means no setting chosen.
  vibe: Joi.string()
    .valid(...VIBE_VALUES)
    .allow(\"\")
    .label(\"Setting\")
    .messages({ \"any.only\": \"Choose a setting from the list.\" }),
});

const location = Joi.object({
  line1: text(\"Street address\", { max: 200 }),
  city: text(\"City\", { max: 100 }),
  state: text(\"State or region\", { max: 100, required: false }),
  country: text(\"Country\", { max: 100 }),
  postalCode: text(\"Postal code\", { max: 20, required: false }),
});

const details = Joi.object({
  guests: whole(\"Guests\", 1, 16),
  bedrooms: whole(\"Bedrooms\", 0, 50),
  beds: whole(\"Beds\", 0, 50),
  bathrooms: Joi.number()
    .multiple(0.5)
    .min(0)
    .max(50)
    .required()
    .label(\"Bathrooms\")
    .messages({
      \"any.required\": \"Bathrooms is required.\",
      \"number.base\": \"Bathrooms must be a number.\",
      \"number.multiple\": \"Bathrooms can be a whole or half number (1 or 1.5).\",
      \"number.min\": \"Bathrooms must be at least 0.\",
      \"number.max\": \"Bathrooms must be at most 50.\",
    }),
  amenities: Joi.array()
    .single()
    .items(Joi.string().valid(...AMENITY_VALUES))
    .unique()
    .default([])
    .label(\"Amenities\")
    .messages({
      \"any.only\": \"Choose amenities from the list.\",
      \"array.includes\": \"Choose amenities from the list.\",
      \"array.unique\": \"Each amenity can be chosen once.\",
    }),
  accessibility: Joi.array()
    .single()
    .items(Joi.string().valid(...ACCESSIBILITY_VALUES))
    .unique()
    .default([])
    .label(\"Accessibility features\")
    .messages({
      \"any.only\": \"Choose accessibility features from the list.\",
      \"array.includes\": \"Choose accessibility features from the list.\",
      \"array.unique\": \"Each accessibility feature can be chosen once.\",
    }),
});

const pricing = Joi.object({
  price: rupees(\"Nightly price\", 100, 1000000),
  cleaningFee: rupees(\"Cleaning fee\", 0, 1000000, { required: false }),
  minNights: whole(\"Minimum nights\", 1, 365),
  maxNights: whole(\"Maximum nights\", 1, 365),
  advanceNoticeHours: optionalWhole(\"Advance notice\", 0, 168, 0),
  sameDayCutoffTime: optionalTime(\"Same-day cut-off\", \"20:00\"),
  checkInTime: time(\"Check-in time\"),
  checkOutTime: time(\"Check-out time\"),
  cancellationPolicy: choice(\"Cancellation policy\", CANCELLATION_POLICY_VALUES),
  instantBook: Joi.boolean()
    .truthy(\"on\", \"1\", \"true\")
    .falsy(\"off\", \"0\", \"false\", \"\")
    .default(false),
  houseRules: text(\"House rules\", { max: 2000, required: false }),
  noSpecialRules: Joi.boolean()
    .truthy(\"on\", \"1\", \"true\")
    .falsy(\"off\", \"0\", \"false\", \"\")
    .default(false),
  // Price rules (P08-T04), all optional: blank means none.
  weekendPercent: optionalWhole(\"Weekend increase\", 0, 100, 0),
  weeklyDiscountPercent: optionalWhole(\"Weekly discount\", 0, 50, 0),
  monthlyDiscountPercent: optionalWhole(\"Monthly discount\", 0, 50, 0),
  // Season rows are checked together by parseSeasons (validateStep), not here.
  ...Object.fromEntries(
    SEASON_FIELD_NAMES.map((name) => [name, Joi.string().trim().allow(\"\").max(60).default(\"\")]),
  ),
})
  .custom((value, helpers) => {
    if (value.minNights > value.maxNights) {
      return helpers.error(\"nights.order\");
    }
    return value;
  })
  .messages({
    \"nights.order\": \"Minimum nights cannot be more than maximum nights.\",
  });

// Checkboxes and empty fields are absent from a browser's form post. A
// submitted field that is not part of the step is refused, not ignored.
const STEP_SCHEMAS = { 1: basics, 2: location, 3: details, 5: pricing };

/**
 * @returns {{ value: object|undefined, errors: Record<string,string> }}
 * `errors` is empty when valid; its keys are field names.
 */
function validateStep(step, body) {
  const schema = STEP_SCHEMAS[step];
  if (!schema) throw new Error(`No form for step ${step}`);
  const { error, value } = schema.validate(body ?? {}, {
    abortEarly: false,
    errors: { wrap: { label: false } },
  });
  // Seasonal prices (step 5) are several boxes that must agree with each other.
  const seasonResult = step === 5 ? parseSeasons(body ?? {}) : { seasons: [], errors: {} };
  if (!error) {
    if (Object.keys(seasonResult.errors).length > 0) {
      return { value: undefined, errors: seasonResult.errors };
    }
    if (step === 5) {
      for (const name of SEASON_FIELD_NAMES) delete value[name];
      value.seasons = seasonResult.seasons;
    }
    return { value, errors: {} };
  }
  const errors = { ...seasonResult.errors };
  for (const detail of error.details) {
    // A rule about several fields has an empty path: show it by the first one.
    const field =
      detail.path[0] ?? (step === 5 ? \"minNights\" : String(detail.context?.label));
    if (!errors[field]) errors[field] = detail.message;
  }
  return { value: undefined, errors };
}

module.exports = { validateStep, STEP_SCHEMAS };
