// Guard and audit wrapper for the /admin area (P14-T01).
const audit = require(\"../services/audit\");
const { isAdmin } = require(\"../policies/shared\");
const { NotFoundError } = require(\"../utils/errors\");

/**
 * Thrown by an auditedMutation handler when it refuses to act (a rule is
 * broken, the form is incomplete) BEFORE changing anything. The wrapper shows
 * `message` as a flash error and redirects to `redirectTo`; no audit row is
 * written because nothing happened.
 */
class AdminRefusal extends Error {
  constructor(message, redirectTo = \"/admin\") {
    super(message);
    this.name = \"AdminRefusal\";
    this.redirectTo = redirectTo;
  }
}

/**
 * router.use(adminGuard) for the whole area. Anyone who is not an active admin
 * (visitors included) gets the ordinary 404 page, so /admin does not reveal
 * that it exists.
 */
function adminGuard(req, res, next) {
  if (!isAdmin(req.user)) throw new NotFoundError();
  res.set(\"Cache-Control\", \"no-store\");
  res.locals.pageTitle = res.locals.pageTitle || \"Admin\";
  next();
}

/**
 * Wraps every admin route that changes data. The handler does the change and
 * RETURNS what to log; it must not respond itself:
 *
 *   router.post(\"/users/:id/suspend\", auditedMutation(async (req) => {
 *     ...change something...
 *     return {
 *       audit: { action: \"user.suspend\", targetType: \"user\", targetId: id, reason, details },
 *       redirectTo: \"/admin/users\",   // or respond: (res) => res.render(...)
 *       flash: \"Account suspended.\",  // optional success message
 *     };
 *   }));
 *
 * The wrapper writes the audit row first and only then answers, so a change
 * without an audit entry never succeeds quietly: it throws (a 500 and a test
 * failure). The change itself has already happened by then; the answer is what
 * is withheld.
 */
function auditedMutation(handler) {
  async function run(req, res) {
    let result;
    try {
      result = await handler(req, res);
    } catch (err) {
      if (err instanceof AdminRefusal && !res.headersSent) {
        req.flash(\"error\", err.message);
        return res.redirect(err.redirectTo);
      }
      throw err;
    }
    if (res.headersSent) {
      throw new Error(\"auditedMutation: the handler responded itself; return { audit, ... } instead\");
    }
    if (!result || !result.audit) {
      throw new Error(\"auditedMutation: the handler returned no audit entry\");
    }
    await audit.record({ ...result.audit, req });
    if (req.auditRecorded !== 1) {
      throw new Error(`auditedMutation: expected exactly one audit entry, got ${req.auditRecorded}`);
    }
    if (result.flash) req.flash(\"success\", result.flash);
    if (typeof result.respond === \"function\") return result.respond(res);
    return res.redirect(result.redirectTo || \"/admin\");
  }

  function auditedMutationMiddleware(req, res, next) {
    req.auditRecorded = 0;
    run(req, res).catch(next);
  }
  // Lets tests check a route table without calling anything.
  auditedMutationMiddleware.auditedMutation = true;
  return auditedMutationMiddleware;
}

module.exports = { adminGuard, auditedMutation, AdminRefusal };

const { ForbiddenError } = require(\"../utils/errors\");
const { hasRole } = require(\"../policies/shared\");
const { ROLES } = require(\"../models/user\");
const { safeRedirectPath } = require(\"../utils/safeRedirect\");

/** Remembers where the visitor was going and sends them to the login page. */
function redirectToLogin(req, res) {
  req.session.redirectUrl = req.originalUrl;
  req.flash(\"error\", \"You must be logged in to do that\");
  return res.redirect(\"/login\");
}

function isLoggedIn(req, res, next) {
  if (!req.isAuthenticated()) return redirectToLogin(req, res);
  next();
}

/**
 * Login only: works out where to send the user afterwards and leaves it in
 * `res.locals.redirectUrl` (undefined = use the default). Sources, in order:
 * the page they were stopped at (session), then a `next` form field / query
 * parameter. Either is used only if it is a same-site path.
 */
function saveRedirectUrl(req, res, next) {
  const fromSession = req.session && req.session.redirectUrl;
  if (req.session) delete req.session.redirectUrl;
  const fromForm = (req.body && req.body.next) || (req.query && req.query.next);
  const target =
    safeRedirectPath(fromSession, null) || safeRedirectPath(fromForm, null);
  if (target) res.locals.redirectUrl = target;
  next();
}

/**
 * Route guard for a whole area, e.g. router.use(requireRole(\"admin\")).
 * Anonymous -> login page; logged in without the role (or suspended) -> 403.
 */
function requireRole(role) {
  if (!ROLES.includes(role)) {
    throw new Error(`requireRole: unknown role \"${role}\"`);
  }
  return function requireRoleMiddleware(req, res, next) {
    if (!req.user) return redirectToLogin(req, res);
    if (!hasRole(req.user, role)) throw new ForbiddenError();
    next();
  };
}

module.exports = { redirectToLogin, isLoggedIn, saveRedirectUrl, requireRole };

// authorize(\"listing:edit\"): loads the resource, then asks the policy.
//
//   anonymous            -> login page (same as isLoggedIn)
//   resource missing     -> 404
//   policy says no       -> 403 (or 404 with { concealForbidden: true }, for
//                           private resources, so their existence is not leaked)
//   policy says yes      -> the resource is left on req.<type> (req.listing,
//                           req.review) and the request continues
//
// Actions without a loader (listing:create, review:create) have no resource.
// `{ resource: \"listing\" }` loads a different resource than the action's prefix
// names: \"review:reply\" is decided by the listing's owner, so its route loads
// the listing (req.listing) and the policy receives it.
const Listing = require(\"../models/listing.js\");
const Review = require(\"../models/review.js\");
const { can } = require(\"../policies\");
const { sameId } = require(\"../policies/shared\");
const { ForbiddenError, NotFoundError } = require(\"../utils/errors\");
const { redirectToLogin } = require(\"./auth\");

const LOADERS = {
  listing: async (req) => Listing.findById(req.params.id),

  // The review must belong to the listing in the URL, otherwise
  // /listings/<any>/reviews/<id> would reach a review of another listing.
  review: async (req) => {
    const { id, reviewId } = req.params;
    const listing = await Listing.findById(id);
    if (!listing) return null;
    const belongs = (listing.reviews || []).some((r) => sameId(r, reviewId));
    if (!belongs) return null;
    return Review.findById(reviewId);
  },
};

const NOT_FOUND = {
  listing: \"That listing does not exist.\",
  review: \"That review does not exist.\",
};

const FORBIDDEN = {
  \"listing:create\": \"You are not allowed to create listings.\",
  \"listing:edit\": \"Only the host can edit this listing.\",
  \"listing:delete\": \"Only the host can delete this listing.\",
  \"review:create\": \"You are not allowed to write reviews.\",
  \"review:delete\": \"Only the author can delete this review.\",
  \"review:edit\": \"Only the author can edit this review.\",
  \"review:reply\": \"Only the host can reply to reviews.\",
};

function authorize(action, { concealForbidden = false, resource: kind } = {}) {
  // Fails at startup (route definition) for a typo, not on the first request.
  can(action, undefined, undefined);
  const type = kind || action.split(\":\")[0];
  const load = action.endsWith(\":create\") ? null : LOADERS[type];

  const authorizeMiddleware = async (req, res, next) => {
    if (!req.user) return redirectToLogin(req, res);

    let resource;
    if (load) {
      resource = await load(req);
      if (!resource) throw new NotFoundError(NOT_FOUND[type]);
    }

    if (!can(action, req.user, resource)) {
      if (concealForbidden) throw new NotFoundError(NOT_FOUND[type]);
      throw new ForbiddenError(FORBIDDEN[action]);
    }

    if (resource) req[type] = resource;
    next();
  };
  // Lets the route matrix test (P17-T01) see which action guards a route.
  authorizeMiddleware.policyAction = action;
  return authorizeMiddleware;
}

module.exports = { authorize };

// A booking form whose session ran out (P08-T03). Logging in again creates a
// new session with a new CSRF token, so the checkout form that was open in the
// browser is rejected by the CSRF check before any route runs. For that one
// route, instead of the dead-end 403 page, the guest is sent back to the GET
// checkout page for the same stay: it asks them to log in if needed, then
// returns to the checkout with a fresh form. Nothing is booked by the rejected
// request, and the redirect target is built only from the route's own id (24
// hex characters) and strictly checked stay parameters, never from a free-form
// value.
const CHECKOUT_POST = /^\\/listings\\/([0-9a-f]{24})\\/checkout\\/?$/i;
const DATE_ONLY = /^\\d{4}-\\d{2}-\\d{2}$/;
const GUESTS = /^\\d{1,3}$/;

const MESSAGE =
  \"Your session ended before the booking was sent. Nothing was booked. Please check the details and confirm again.\";

/**
 * Used as the CSRF middleware's `onInvalid`: returns true when it answered the
 * request (a redirect), false to let the normal 403 happen.
 */
function recoverCheckout(req, res) {
  if (req.method !== \"POST\") return false;
  const match = CHECKOUT_POST.exec(req.path || \"\");
  if (!match || typeof req.flash !== \"function\") return false;
  const body = req.body && typeof req.body === \"object\" ? req.body : {};
  const params = new URLSearchParams();
  if (
    typeof body.in === \"string\" &&
    DATE_ONLY.test(body.in) &&
    typeof body.out === \"string\" &&
    DATE_ONLY.test(body.out) &&
    typeof body.guests === \"string\" &&
    GUESTS.test(body.guests)
  ) {
    params.set(\"in\", body.in);
    params.set(\"out\", body.out);
    params.set(\"guests\", body.guests);
  }
  const query = params.toString();
  req.flash(\"error\", MESSAGE);
  res.redirect(`/listings/${match[1]}/checkout${query ? `?${query}` : \"\"}`);
  return true;
}

module.exports = { recoverCheckout, CHECKOUT_POST };

// CSRF protection (P01-T10, ADR-006): a synchronizer token kept in the session.
//
// - Each session gets one random token (`req.session.csrfToken`). It is exposed
//   to views as `res.locals.csrfToken` (hidden field, <meta> tag, query string).
// - Every request that is not GET/HEAD/OPTIONS must send the same token in the
//   `X-CSRF-Token` header, the `_csrf` query parameter or the `_csrf` body field.
// - Must run AFTER the session and the urlencoded body parser, and BEFORE
//   multer and every router. Multipart forms cannot send the token in the body
//   (multer has not parsed it yet), so they put it in the query string.
// - The token is bound to the session. A new session (login and logout both
//   regenerate it) gets a new token; a form rendered before that is rejected
//   with the 403 page and the visitor is asked to reload.
//
// No package is used: csurf is deprecated and this is ~40 lines.
const crypto = require(\"node:crypto\");
const { ForbiddenError } = require(\"../utils/errors\");

const SAFE_METHODS = new Set([\"GET\", \"HEAD\", \"OPTIONS\"]);
const HEADER = \"x-csrf-token\";
const FIELD = \"_csrf\";
const TOKEN_BYTES = 32;

const MESSAGE =
  \"Your form has expired or could not be verified. Please reload the page and try again.\";

/** The session's token, created on first use. Undefined if there is no session. */
function getToken(req) {
  if (!req.session) return undefined;
  if (typeof req.session.csrfToken !== \"string\") {
    req.session.csrfToken = crypto
      .randomBytes(TOKEN_BYTES)
      .toString(\"base64url\");
  }
  return req.session.csrfToken;
}

/** Constant-time comparison; false for anything that is not a matching string. */
function tokensMatch(expected, supplied) {
  if (typeof expected !== \"string\" || typeof supplied !== \"string\")
    return false;
  const a = Buffer.from(expected);
  const b = Buffer.from(supplied);
  return a.length === b.length && crypto.timingSafeEqual(a, b);
}

/** Header, then query string, then body. Only strings count (no arrays). */
function submittedToken(req) {
  const fromHeader = req.get(HEADER);
  if (typeof fromHeader === \"string\" && fromHeader) return fromHeader;
  const fromQuery = req.query && req.query[FIELD];
  if (typeof fromQuery === \"string\" && fromQuery) return fromQuery;
  const fromBody = req.body && req.body[FIELD];
  if (typeof fromBody === \"string\" && fromBody) return fromBody;
  return undefined;
}

/**
 * @param {object} [options]
 * @param {(req, res) => boolean} [options.onInvalid] called when the token is
 *   missing or wrong; return true if it already answered the request (the
 *   checkout form's \"session ended\" redirect, P08-T03), false for the 403
 */
function csrfProtection({ onInvalid } = {}) {
  return function csrfProtectionMiddleware(req, res, next) {
    const expected = getToken(req);
    res.locals.csrfToken = expected || \"\";

    if (SAFE_METHODS.has(req.method)) return next();

    if (!expected || !tokensMatch(expected, submittedToken(req))) {
      if (req.log)
        req.log.warn({ event: \"csrf_rejected\" }, \"csrf token rejected\");
      if (onInvalid && onInvalid(req, res)) return undefined;
      return next(new ForbiddenError(MESSAGE, { code: \"csrf_invalid\" }));
    }

    // The field is not part of any form's data: validation schemas reject
    // unknown keys, so remove it once it has been checked.
    if (req.body && typeof req.body === \"object\") delete req.body[FIELD];
    next();
  };
}

module.exports = { csrfProtection, getToken, tokensMatch, SAFE_METHODS };

const mongoose = require(\"mongoose\");
const { AppError } = require(\"../utils/errors\");

const TITLES = {
  400: \"Bad request\",
  401: \"Please log in\",
  403: \"Not allowed\",
  404: \"Page Not Found\",
  409: \"Conflict\",
  413: \"Upload too large\",
  429: \"Too many requests\",
  500: \"Something went wrong\",
};
const GENERIC_500 = \"Something went wrong on our side. Please try again.\";

function titleFor(status) {
  return TITLES[status] || (status >= 500 ? TITLES[500] : \"Request failed\");
}

/**
 * Turns anything that was thrown into { status, message, code, expose }.
 * `message` is always safe to show to a visitor in production.
 * Handles non-Error throws (strings, objects, null).
 */
function normalizeError(err) {
  if (err instanceof AppError) {
    const status = err.statusCode;
    return {
      status,
      code: err.code,
      message: status >= 500 ? GENERIC_500 : err.message,
    };
  }
  if (err instanceof mongoose.Error.CastError) {
    // e.g. /listings/not-an-object-id
    return { status: 404, code: \"not_found\", message: \"Page Not Found\" };
  }
  if (err instanceof mongoose.Error.ValidationError) {
    return {
      status: 400,
      code: \"validation_error\",
      message: \"The submitted data is not valid.\",
    };
  }
  if (err && typeof err === \"object\" && err.code === 11000) {
    return {
      status: 409,
      code: \"duplicate_key\",
      message: \"That value is already in use.\",
    };
  }
  if (err && typeof err === \"object\" && err.name === \"MulterError\") {
    const tooBig = err.code === \"LIMIT_FILE_SIZE\";
    const tooMany =
      err.code === \"LIMIT_FILE_COUNT\" || err.code === \"LIMIT_UNEXPECTED_FILE\";
    let message = \"The upload could not be processed.\";
    if (tooBig) message = \"That image is too large (maximum 5 MB).\";
    else if (tooMany)
      message =
        \"Too many files were sent (a listing can have at most 10 photos).\";
    return {
      status: tooBig ? 413 : 400,
      code: \"upload_rejected\",
      message,
    };
  }
  // http-errors style client errors from Express/body-parser (4xx, expose=true).
  if (
    err &&
    typeof err === \"object\" &&
    Number.isInteger(err.status) &&
    err.status >= 400 &&
    err.status < 500 &&
    err.expose === true
  ) {
    return {
      status: err.status,
      code: \"client_error\",
      message:
        typeof err.message === \"string\" ? err.message : titleFor(err.status),
    };
  }
  return { status: 500, code: \"internal_error\", message: GENERIC_500 };
}

function wantsJson(req) {
  const url = req.originalUrl || req.url || \"\";
  if (url === \"/api\" || url.startsWith(\"/api/\") || url.startsWith(\"/api?\")) {
    return true;
  }
  return req.accepts([\"html\", \"json\"]) === \"json\";
}

function detailOf(err) {
  if (err instanceof Error) return err.stack || `${err.name}: ${err.message}`;
  try {
    return `Non-error value thrown: ${JSON.stringify(err)}`;
  } catch {
    return `Non-error value thrown: ${String(err)}`;
  }
}

/**
 * Express error handler.
 * - production: only the safe message (never stack, driver text or 5xx messages)
 * - development/test: also the stack/detail
 * - /api paths (or Accept: application/json): JSON body, otherwise error.ejs
 * - if the response has already started, defer to Express (closes the socket)
 */
function createErrorHandler({ isProduction, logger }) {
  return function errorHandler(err, req, res, next) {
    if (res.headersSent) {
      return next(err);
    }

    const { status, code, message } = normalizeError(err);
    const log = req.log || logger;
    const requestId = req.id;

    if (log) {
      if (status >= 500) {
        log.error({ err, status, code }, \"request failed\");
      } else {
        log.info({ status, code, errName: err && err.name }, \"client error\");
      }
    }

    const detail = isProduction ? undefined : detailOf(err);

    if (wantsJson(req)) {
      const body = { error: { status, code, message, requestId } };
      // Per-field messages of a validation error (P08-T02), already written for users.
      if (status < 500 && err && err.fields && typeof err.fields === \"object\") {
        body.error.fields = err.fields;
      }
      if (detail) body.error.detail = detail;
      return res.status(status).json(body);
    }

    res.status(status).render(
      \"error.ejs\",
      {
        status,
        title: titleFor(status),
        pageTitle: `${status} ${titleFor(status)}`,
        message,
        detail,
        requestId,
        // Defaults for the layout when the error happened before the locals
        // middleware ran (e.g. a session store failure).
        success: res.locals.success || [],
        error: res.locals.error || [],
        currUser: res.locals.currUser || null,
        currentPath: res.locals.currentPath || \"\",
        mapPublicToken: res.locals.mapPublicToken || \"\",
      },
      (renderErr, html) => {
        if (renderErr) {
          if (log) log.error({ err: renderErr }, \"error page failed to render\");
          res
            .status(status)
            .type(\"text/plain\")
            .send(`${titleFor(status)}\\n${message}`);
          return;
        }
        res.send(html);
      },
    );
  };
}

module.exports = { createErrorHandler, normalizeError };

