// Input guard (P17-T02): refuses request input that is shaped like an attack
// before any controller sees it.
//
// 1. Operator and path injection. A key that contains \"$\" or \".\" (`email[$ne]=x`,
//    `a.b=1`), or is named __proto__/constructor/prototype, has no place in any
//    form or query this site accepts. Left alone, a nested value can end up
//    inside a database filter (`{ username: { $ne: \"\" } }`) or an update.
//    The request is refused (400), not silently cleaned, so a probe is visible
//    in the logs and in tests.
// 2. Shape. Nesting deeper than 8 levels, more than 5,000 values, or a NUL
//    character in a string is refused too.
//
// It looks at req.query and req.body. Run it right after the urlencoded parser
// (app.js), and again right after every multer middleware, because multer
// parses its text fields later than the urlencoded parser and builds nested
// objects the same way.
//
// Duplicate parameters (?q=a&q=b, \"HPP\") are NOT refused here: some parameters
// legitimately repeat (checkboxes, ?ids=). Every query parser handles arrays on
// purpose, and tests/unit/inputParsers.test.js pins how.
const { ValidationError } = require(\"../utils/errors\");

// Size limits of the form parser. 100 kb is far above any form of this site
// (the largest text field, a listing description, is capped lower by Joi);
// anything bigger answers 413 (see src/middleware/errors.js).
const URLENCODED_OPTIONS = Object.freeze({
  extended: true,
  limit: \"100kb\",
  parameterLimit: 1000,
});

const MAX_DEPTH = 8;
const MAX_VALUES = 5000;
// \"$\" or \".\" anywhere, or a prototype name (also as the start of a flat key such as \"__proto__[x]\").
const BAD_KEY = /[$.]|^(?:__proto__|constructor|prototype)(?:\\[|$)/;

/**
 * @returns {null | { reason: \"operator_key\"|\"nul\"|\"too_deep\"|\"too_large\", path: string }}
 *   `path` names keys only (never values), safe to log.
 */
function findUnsafeInput(root) {
  const stack = [{ value: root, path: \"\", depth: 0 }];
  let seen = 0;
  while (stack.length) {
    const { value, path, depth } = stack.pop();
    seen += 1;
    if (seen > MAX_VALUES) return { reason: \"too_large\", path };
    if (typeof value === \"string\") {
      if (value.includes(\"\\u0000\")) return { reason: \"nul\", path };
      continue;
    }
    if (value === null || typeof value !== \"object\") continue;
    if (depth >= MAX_DEPTH) return { reason: \"too_deep\", path };
    if (Array.isArray(value)) {
      value.forEach((item, i) =>
        stack.push({ value: item, path: `${path}[${i}]`, depth: depth + 1 }),
      );
      continue;
    }
    for (const key of Object.keys(value)) {
      const here = path ? `${path}.${key}` : key;
      if (BAD_KEY.test(key)) return { reason: \"operator_key\", path: here };
      stack.push({ value: value[key], path: here, depth: depth + 1 });
    }
  }
  return null;
}

function inputGuard(req, res, next) {
  for (const where of [\"query\", \"body\"]) {
    const found = findUnsafeInput(req[where]);
    if (found) {
      if (req.log) {
        req.log.warn(
          { where, reason: found.reason, path: found.path.slice(0, 80) },
          \"request input refused\",
        );
      }
      return next(new ValidationError(\"That request contains input we do not accept.\"));
    }
  }
  return next();
}

module.exports = { inputGuard, findUnsafeInput, URLENCODED_OPTIONS };

const { ValidationError } = require(\"../utils/errors\");
const { assertValidImage } = require(\"../services/images\");
const {
  geocodeAddress,
  LocationNotFoundError,
  GeocoderUnavailableError,
} = require(\"../services/geocoding\");

// A new listing must come with a photo. (multer has already parsed the form.)
module.exports.requireImage = (req, res, next) => {
  if (!req.file) {
    throw new ValidationError(\"Please choose an image for your listing.\");
  }
  next();
};

// A submitted photo must really be a PNG, JPEG or WebP (its first bytes are
// checked, not the name or the type the browser claims) and small enough. Runs
// before geocoding and before anything is sent to Cloudinary.
module.exports.verifyUploadedImage = (req, res, next) => {
  if (req.file) assertValidImage(req.file);
  next();
};

function hasGeometry(listing) {
  return Boolean(
    listing.geometry &&
    Array.isArray(listing.geometry.coordinates) &&
    listing.geometry.coordinates.length >= 2,
  );
}

/**
 * Sets req.geometry from the submitted location + country.
 * On edit (req.listing is set by authorize(\"listing:edit\")) it only looks the place up again when
 * the location or country changed, or when the stored listing has no coordinates.
 * A place that cannot be found, or a geocoder outage, flashes a message and sends
 * the user back to the form (`backTo(req)`) so nothing is uploaded or saved.
 */
module.exports.geocodeListing = ({ backTo }) =>
  async function geocodeListing(req, res, next) {
    const { location, country } = req.body.listing;
    const existing = req.listing;
    if (
      existing &&
      existing.location === location &&
      existing.country === country &&
      hasGeometry(existing)
    ) {
      return next();
    }
    try {
      req.geometry = await geocodeAddress({ location, country });
    } catch (err) {
      if (
        err instanceof LocationNotFoundError ||
        err instanceof GeocoderUnavailableError
      ) {
        if (req.log && err instanceof GeocoderUnavailableError) {
          req.log.warn({ err }, \"geocoding failed\");
        }
        req.flash(\"error\", err.message);
        return res.redirect(backTo(req));
      }
      throw err;
    }
    next();
  };

// Puts `savedIds` (a Set of listing ids the signed-in member has saved) in
// res.locals so the heart on a card or detail page shows the right state.
// The heart is a convenience: if the lookup fails the page still renders, with
// every heart empty, and the failure is logged.
const mongoose = require(\"mongoose\");
const { savedIdsFor } = require(\"../services/wishlists\");

async function withSavedIds(req, res, next) {
  res.locals.savedIds = new Set();
  // No database connection (a unit test, or the database is down): skip the
  // lookup instead of waiting for it to time out.
  if (!req.user || mongoose.connection.readyState !== 1) return next();
  try {
    res.locals.savedIds = await savedIdsFor(req.user._id);
  } catch (err) {
    if (req.log) req.log.warn({ err }, \"could not load saved stays\");
  }
  next();
}

module.exports = { withSavedIds };

// Security baseline (P01-T09): per-request CSP nonce, helmet headers, and rate
// limits for the login and signup forms.
const crypto = require(\"node:crypto\");
const helmet = require(\"helmet\");
const { rateLimit, ipKeyGenerator } = require(\"express-rate-limit\");
const { AppError } = require(\"../utils/errors\");

/** A fresh nonce per request; views put it on every inline <script>/<style>. */
function assignCspNonce(req, res, next) {
  res.locals.cspNonce = crypto.randomBytes(16).toString(\"base64\");
  next();
}

const nonce = (req, res) => `'nonce-${res.locals.cspNonce}'`;

// Third-party hosts the pages load from (see views/layouts/boilerPlate.ejs).
const JSDELIVR = \"https://cdn.jsdelivr.net\"; // Bootstrap CSS/JS
const CDNJS = \"https://cdnjs.cloudflare.com\"; // Font Awesome
const GOOGLE_FONTS_CSS = \"https://fonts.googleapis.com\";
const GOOGLE_FONTS_FILES = \"https://fonts.gstatic.com\";
const MAPBOX = \"https://api.mapbox.com\";
const MAPBOX_TILES = \"https://*.tiles.mapbox.com\";
const MAPBOX_EVENTS = \"https://events.mapbox.com\";
const CLOUDINARY = \"https://res.cloudinary.com\";
const UNSPLASH = \"https://images.unsplash.com\"; // seed data pictures
const MUSCACHE = \"https://a0.muscache.com\"; // pictures of imported sample_airbnb listings

/**
 * helmet with a CSP that allows only this site, the CDNs above, Mapbox and
 * Cloudinary. Inline <script>/<style> blocks need the request's nonce. Inline
 * style=\"\" attributes are still allowed (style-src-attr): Mapbox GL and a few
 * views use them; scripts get no such exception.
 */
function securityHeaders({ isProduction = false } = {}) {
  return helmet({
    contentSecurityPolicy: {
      useDefaults: true,
      directives: {
        defaultSrc: [\"'self'\"],
        scriptSrc: [\"'self'\", nonce, JSDELIVR, MAPBOX],
        scriptSrcAttr: [\"'none'\"],
        styleSrc: [\"'self'\", nonce, JSDELIVR, CDNJS, GOOGLE_FONTS_CSS, MAPBOX],
        styleSrcAttr: [\"'unsafe-inline'\"],
        fontSrc: [\"'self'\", GOOGLE_FONTS_FILES, CDNJS, \"data:\"],
        imgSrc: [
          \"'self'\",
          \"data:\",
          \"blob:\",
          CLOUDINARY,
          UNSPLASH,
          MUSCACHE,
          MAPBOX,
          MAPBOX_TILES,
        ],
        connectSrc: [\"'self'\", MAPBOX, MAPBOX_TILES, MAPBOX_EVENTS],
        workerSrc: [\"'self'\", \"blob:\"],
        childSrc: [\"'self'\", \"blob:\"],
        objectSrc: [\"'none'\"],
        baseUri: [\"'self'\"],
        formAction: [\"'self'\"],
        frameAncestors: [\"'self'\"],
        // Only meaningful (and safe) behind HTTPS.
        upgradeInsecureRequests: isProduction ? [] : null,
      },
    },
    // The Mapbox public token can be restricted by URL, which needs a Referer.
    referrerPolicy: { policy: \"strict-origin-when-cross-origin\" },
    strictTransportSecurity: isProduction ? undefined : false,
  });
}

function tooManyAttempts(req, res, next) {
  next(
    new AppError(
      429,
      \"Too many attempts. Please wait a few minutes and try again.\",
      { code: \"rate_limited\" },
    ),
  );
}

function tooManyAccountTries(req, res, next) {
  next(
    new AppError(429, \"Too many attempts on your account settings. Please wait a while and try again.\", {
      code: \"rate_limited\",
    }),
  );
}

function tooManyEmails(req, res, next) {
  next(
    new AppError(429, \"Too many email requests. Please wait a while and try again.\", {
      code: \"rate_limited\",
    }),
  );
}

function tooManySuggestions(req, res, next) {
  next(
    new AppError(429, \"Too many suggestion requests. Please wait a moment.\", {
      code: \"rate_limited\",
    }),
  );
}

function tooManyQuotes(req, res, next) {
  next(
    new AppError(429, \"Too many price checks. Please wait a minute and try again.\", {
      code: \"rate_limited\",
    }),
  );
}

function tooManyMessages(req, res, next) {
  next(
    new AppError(429, \"You are sending messages very quickly. Please wait a minute and try again.\", {
      code: \"rate_limited\",
    }),
  );
}

function tooManyReports(req, res, next) {
  next(
    new AppError(429, \"You are sending reports very quickly. Please wait a minute and try again.\", {
      code: \"rate_limited\",
    }),
  );
}

/**
 * Created per app (not at module load) so every test app starts with empty
 * counters. Login: 5 failed attempts per 15 minutes per IP (a successful
 * login is not counted). Signup: 10 per hour per IP. Quote: 60 per minute per IP.
 */
function createAuthLimiters() {
  const common = {
    standardHeaders: true,
    legacyHeaders: false,
    handler: tooManyAttempts,
  };
  return {
    login: rateLimit({
      ...common,
      windowMs: 15 * 60 * 1000,
      limit: 5,
      skipSuccessfulRequests: true,
      // passport redirects both ways, so \"success\" means \"now logged in\".
      requestWasSuccessful: (req) => Boolean(req.user),
    }),
    signup: rateLimit({ ...common, windowMs: 60 * 60 * 1000, limit: 10 }),
    // Password change and account deletion (P02-T04): 10 an hour per signed-in
    // member, on top of the account's own failed-password lock.
    account: rateLimit({
      ...common,
      handler: tooManyAccountTries,
      windowMs: 60 * 60 * 1000,
      limit: 10,
      keyGenerator: (req) => (req.user && req.user._id ? `user:${req.user._id}` : ipKeyGenerator(req.ip)),
    }),
    // Password-reset and \"send the confirmation link again\" (P02-T05): 10 an
    // hour per IP, on top of the per-account limits in services/emailTokens.js.
    emailLink: rateLimit({ ...common, handler: tooManyEmails, windowMs: 60 * 60 * 1000, limit: 10 }),
    // Destination suggestions (P05-T06): a few per second while typing, and
    // the script waits 250 ms between keystrokes.
    destinations: rateLimit({ ...common, handler: tooManySuggestions, windowMs: 60 * 1000, limit: 120 }),
    // Price checks (P08-T02): a guest picking dates makes a few per minute.
    quote: rateLimit({ ...common, handler: tooManyQuotes, windowMs: 60 * 1000, limit: 60 }),
    // Messages and \"Contact host\" (P11-T02): 20 a minute per signed-in member.
    message: rateLimit({
      ...common,
      handler: tooManyMessages,
      windowMs: 60 * 1000,
      limit: 20,
      keyGenerator: (req) => (req.user && req.user._id ? `user:${req.user._id}` : ipKeyGenerator(req.ip)),
    }),
    // Reports (P12-T04): 5 a minute per signed-in member (per IP for anyone
    // else). The daily cap is counted in the database by services/reports.js.
    report: rateLimit({
      ...common,
      handler: tooManyReports,
      windowMs: 60 * 1000,
      limit: 5,
      keyGenerator: (req) => (req.user && req.user._id ? `user:${req.user._id}` : ipKeyGenerator(req.ip)),
    }),
  };
}

module.exports = { assignCspNonce, securityHeaders, createAuthLimiters };

// \"Confirm your email first\" (P02-T05). Publishing a listing and booking a stay
// need a confirmed address. Called at the top of the controller action (not as
// route middleware, so the route guards the authorization matrix checks stay as
// they are):
//
//   if (!ensureVerifiedEmail(req, res)) return;
//
// Returns true when the request may go on. Otherwise it has already answered
// (a flash message and a redirect to /verify-email/needed) and returns false.
// The server decides; nothing the browser sends can skip it.
// With EMAIL_VERIFICATION_REQUIRED=false (app.locals.emailVerificationRequired)
// it always returns true.
const MESSAGE =
  \"Confirm your email address first. You need a confirmed address to publish a listing or book a stay.\";

function isEmailVerified(user) {
  return Boolean(user && user.emailVerifiedAt);
}

function ensureVerifiedEmail(req, res) {
  if (!req.app.locals.emailVerificationRequired) return true;
  if (isEmailVerified(req.user)) return true;
  req.flash(\"error\", MESSAGE);
  res.redirect(\"/verify-email/needed\");
  return false;
}

module.exports = { ensureVerifiedEmail, isEmailVerified, MESSAGE };

// Audit log (P14-T01): one row per administrative action, written by
// src/services/audit.js in the same request as the action itself.
//
// Append-only by design: a row is created once and never changed. Saving an
// existing row, every update/replace/delete query and bulkWrite with anything
// but inserts are refused here, and the admin area has no route that edits or
// removes rows (the viewer is read-only). A direct driver call
// (`Model.collection`) or a database shell is outside what the model can
// stop; restrict database credentials for that.
const mongoose = require(\"mongoose\");
const Schema = mongoose.Schema;

const TARGET_TYPES = Object.freeze([
  \"user\",
  \"listing\",
  \"review\",
  \"report\",
  \"reservation\",
  \"system\",
]);

const auditLogSchema = new Schema(
  {
    // The admin who acted. null for an action taken outside a login
    // (`scripts/make-admin.js`); `actorLabel` then says who/what did it.
    actor: { type: Schema.Types.ObjectId, ref: \"User\", default: null },
    actorLabel: { type: String, trim: true, maxlength: 120 },

    // Stable machine name, e.g. \"user.make_admin\", \"user.suspend\".
    action: {
      type: String,
      required: true,
      trim: true,
      match: /^[a-z][a-z0-9_]*(\\.[a-z][a-z0-9_]*)+$/,
      maxlength: 80,
    },
    targetType: { type: String, enum: TARGET_TYPES, required: true },
    targetId: { type: Schema.Types.ObjectId, default: null },

    // Required free text for actions that need a reason (suspensions...).
    reason: { type: String, trim: true, maxlength: 1000 },

    // Small, non-secret facts about the change (old/new status...). Never
    // passwords, tokens or whole documents.
    details: { type: Schema.Types.Mixed },

    requestId: { type: String, maxlength: 80 },
  },
  { timestamps: { createdAt: true, updatedAt: false }, versionKey: false },
);

// The audit page reads newest first, ties by _id (P18-T02, migration 010). With
// only createdAt in the index the _id tie-break forced a sort of the whole log,
// which only ever grows; this index delivers the order.
auditLogSchema.index({ createdAt: -1, _id: -1 }, { name: \"createdAt_-1__id_-1\" });
auditLogSchema.index({ actor: 1, createdAt: -1 });
auditLogSchema.index({ targetType: 1, targetId: 1, createdAt: -1 });
auditLogSchema.index({ action: 1, createdAt: -1 });

const REFUSED = \"Audit log entries cannot be changed or deleted.\";

auditLogSchema.pre(\"save\", function () {
  if (!this.isNew) throw new Error(REFUSED);
});

auditLogSchema.pre(
  [
    \"updateOne\",
    \"updateMany\",
    \"replaceOne\",
    \"findOneAndUpdate\",
    \"findOneAndReplace\",
    \"findOneAndDelete\",
    \"deleteOne\",
    \"deleteMany\",
  ],
  { document: false, query: true },
  function () {
    throw new Error(REFUSED);
  },
);

auditLogSchema.pre(
  [\"deleteOne\", \"updateOne\"],
  { document: true, query: false },
  function () {
    throw new Error(REFUSED);
  },
);

// Only inserts may go through bulkWrite (Mongoose 9 passes the operations as
// the first argument; throwing refuses the call).
auditLogSchema.pre(\"bulkWrite\", function (ops) {
  const onlyInserts =
    Array.isArray(ops) && ops.every((op) => op && op.insertOne);
  if (!onlyInserts) throw new Error(REFUSED);
});

const AuditLog = mongoose.model(\"AuditLog\", auditLogSchema);

module.exports = AuditLog;
module.exports.TARGET_TYPES = TARGET_TYPES;
module.exports.REFUSED_MESSAGE = REFUSED;

// A host's \"I am not available\" record (P07-T03). One document per block the
// host created: the date range as asked and an optional private note.
//
// The nights themselves live in the night ledger (src/models/stayNight.js)
// with source { kind: \"block\", id: <this _id> }; the ledger, not this record,
// decides what is blocked. After a partial unblock the record may therefore
// describe more nights than are still blocked; the calendar always reads the
// ledger. A block with no night left is deleted.
//
// `from` is the first blocked night and `to` the day after the last one (the
// same half-open range as a stay: ADR-003). Both are date-only (00:00:00Z).
const mongoose = require(\"mongoose\");
const { isDateOnly } = require(\"../utils/dates\");
const Schema = mongoose.Schema;

const NOTE_MAX_LENGTH = 200;

const dateOnly = {
  type: Date,
  required: true,
  validate: {
    validator: isDateOnly,
    message: \"must be a date-only value (00:00:00.000Z)\",
  },
};

const availabilityBlockSchema = new Schema(
  {
    listing: { type: Schema.Types.ObjectId, ref: \"Listing\", required: true },
    from: dateOnly,
    to: dateOnly,
    note: { type: String, trim: true, maxlength: NOTE_MAX_LENGTH, default: \"\" },
    createdBy: { type: Schema.Types.ObjectId, ref: \"User\" },
  },
  { timestamps: { createdAt: true, updatedAt: false }, versionKey: false },
);

availabilityBlockSchema.index({ listing: 1, from: 1 });

const AvailabilityBlock = mongoose.model(
  \"AvailabilityBlock\",
  availabilityBlockSchema,
);
AvailabilityBlock.NOTE_MAX_LENGTH = NOTE_MAX_LENGTH;

module.exports = AvailabilityBlock;

// A conversation between one guest and one host (P11-T02). Two kinds:
//   - general: about a listing, started with \"Contact host\"
//     (threadKey `listing:<listingId>:<guestId>`), and
//   - reservation-bound: about one booking, opened by either side
//     (threadKey `reservation:<reservationId>`).
// The unique index on `threadKey` makes both idempotent: starting twice (or two
// clicks at once) gives the same conversation. Created and changed only by
// src/services/conversations.js.
const mongoose = require(\"mongoose\");
const { LIMITS } = require(\"../config/conversations\");

const Schema = mongoose.Schema;

const conversationSchema = new Schema(
  {
    threadKey: { type: String, required: true, maxlength: 80 },
    listing: { type: Schema.Types.ObjectId, ref: \"Listing\", required: true },
    guest: { type: Schema.Types.ObjectId, ref: \"User\", required: true },
    host: { type: Schema.Types.ObjectId, ref: \"User\", required: true },
    reservation: { type: Schema.Types.ObjectId, ref: \"Reservation\", default: null },

    // Messages this side has not read yet (one counter per side).
    unread: {
      guest: { type: Number, default: 0, min: 0 },
      host: { type: Number, default: 0, min: 0 },
    },
    // null until the first message: such a thread is not listed.
    lastMessageAt: { type: Date, default: null },
    lastMessage: {
      sender: { type: Schema.Types.ObjectId, ref: \"User\" },
      preview: { type: String, maxlength: LIMITS.preview },
    },
  },
  { timestamps: true },
);

conversationSchema.index({ threadKey: 1 }, { unique: true });
// \"My conversations\", newest message first, for either side.
conversationSchema.index({ guest: 1, lastMessageAt: -1 });
conversationSchema.index({ host: 1, lastMessageAt: -1 });

module.exports = mongoose.model(\"Conversation\", conversationSchema);

// One-time links sent by email (P02-T05): \"confirm your address\" and \"reset your
// password\". Only a SHA-256 hash of the token is stored, so a copy of the
// database cannot be used to take over an account. A token works once (`usedAt`)
// and only until `expiresAt`; the TTL index removes rows a week after that.
const mongoose = require(\"mongoose\");

const PURPOSES = [\"verify_email\", \"reset_password\"];
const KEEP_AFTER_EXPIRY_SECONDS = 7 * 24 * 60 * 60;

const emailTokenSchema = new mongoose.Schema(
  {
    user: { type: mongoose.Schema.Types.ObjectId, ref: \"User\", required: true },
    purpose: { type: String, enum: PURPOSES, required: true },
    // The address the link was sent to. A link for an address the account no
    // longer has confirms nothing.
    email: { type: String, required: true },
    tokenHash: { type: String, required: true, unique: true },
    expiresAt: { type: Date, required: true },
    usedAt: { type: Date, default: null },
  },
  { timestamps: { createdAt: true, updatedAt: false } },
);

emailTokenSchema.index({ expiresAt: 1 }, { expireAfterSeconds: KEEP_AFTER_EXPIRY_SECONDS });
emailTokenSchema.index({ user: 1, purpose: 1, createdAt: -1 });

const EmailToken = mongoose.model(\"EmailToken\", emailTokenSchema);

module.exports = EmailToken;
module.exports.PURPOSES = PURPOSES;

// Listing model v2 (P04-T01). Money is integer paise (ADR-002). Documents
// written before v2 are upgraded by scripts/migrations/003-listing-model-v2.js;
// until it has run they still load (every new field has a default or is
// optional) but show no price, because the old `price` field is now
// `legacyPrice`.
//
// Validators only run on fields that change, so an old listing with, say, a
// price under the floor can still be edited; the floor applies to new values.
const mongoose = require(\"mongoose\");
const Schema = mongoose.Schema;
const Review = require(\"./review\");
const { keysForListing } = require(\"../utils/searchKeys\");
const { approximatePoint } = require(\"../utils/geo\");

const STATUSES = [\"draft\", \"published\", \"unpublished\", \"suspended\"];
const {
  PROPERTY_TYPE_VALUES: PROPERTY_TYPES,
  ROOM_TYPE_VALUES: ROOM_TYPES,
  VIBE_VALUES: VIBES,
  CANCELLATION_POLICY_VALUES: CANCELLATION_POLICIES,
} = require(\"../config/constants\");

// Nightly price floor: INR 100 (10 000 paise). A stay below it is almost
// certainly a typo (1 instead of 1000). Ceiling: INR 10 lakh a night.
const MIN_NIGHTLY_MINOR = 10000;
const MAX_MINOR = 100000000;
const MAX_IMAGES = 10;
const MAX_GUESTS = 16;
const TIME_PATTERN = /^([01]\\d|2[0-3]):[0-5]\\d$/;

const integer = {
  validator: (v) => v === null || v === undefined || Number.isInteger(v),
  message: \"{PATH} must be a whole number\",
};

// The floor is checked for a new or changed value only: an amount that is
// already stored (an old listing priced below today's floor) must not stop the
// host from saving, unpublishing or deleting that listing.
const minorAmount = (min, path) => ({
  type: Number,
  max: [MAX_MINOR, \"{PATH} is too large\"],
  validate: [
    integer,
    {
      validator: function atLeastMin(value) {
        if (value === null || value === undefined) return true;
        // `this` is the document when it validates itself (not in update validators).
        const isDoc = this && typeof this.isModified === \"function\";
        if (isDoc && !this.isNew && path && !this.isModified(path)) return true;
        return value >= min;
      },
      message: `{PATH} must be at least ${min} (minor units)`,
    },
  ],
});

// One gallery photo (P04-T03). `_id` identifies it in the photo routes.
// `publicId` is the Cloudinary id (empty for pictures that are not ours, such
// as seed data). `alt` is the text a screen reader reads, `caption` is shown
// under the photo in the viewer. The array order is the display order and
// `order` mirrors it (0 = the cover); src/services/images.js keeps both in step.
const imageSchema = new Schema({
  url: { type: String, required: true },
  publicId: { type: String },
  alt: { type: String, trim: true, maxlength: 200 },
  caption: { type: String, trim: true, maxlength: 200 },
  order: { type: Number, min: 0, validate: integer, default: 0 },
});

const nearbyItemSchema = new Schema(
  {
    name: { type: String },
    category: { type: String },
    distanceMeters: { type: Number, min: 0 },
  },
  { _id: false },
);

const count = (def, min, max) => ({
  type: Number,
  default: def,
  min,
  max,
  validate: integer,
});

const listingSchema = new Schema(
  {
    title: {
      type: String,
      required: true,
    },

    description: {
      type: String,
    },

    // draft until the host publishes (P04-T05). Only published listings are
    // public. Listings created before v2 are migrated to published.
    status: {
      type: String,
      enum: STATUSES,
      default: \"draft\",
      required: true,
    },

    propertyType: { type: String, enum: PROPERTY_TYPES },
    roomType: { type: String, enum: ROOM_TYPES },
    // The setting a host chose (beach, mountain, ...). Optional, no default;
    // the category strip on /listings filters on it (P05-T04).
    vibe: { type: String, enum: VIBES },

    // The setting around the place (beach, mountain, ...). Optional: the host
    // chooses it in the basics step; the category strip on /listings reads it
    // (P05-T04). Listings that never set it simply match no vibe category.
    vibe: { type: String, enum: VIBES },

    // Mirror of the cover photo (images[0]), kept in step by the media service
    // (src/services/images.js) because older pages and the cards still read it.
    // images[] is the source of truth.
    image: {
      filename: {
        type: String,
      },
      url: {
        type: String,
      },
    },

    images: {
      type: [imageSchema],
      validate: {
        validator: (v) => v.length <= MAX_IMAGES,
        message: `A listing can have at most ${MAX_IMAGES} photos`,
      },
    },

    // Free text from the old form; kept because the pages still show it.
    location: {
      type: String,
    },

    country: {
      type: String,
    },

    // Structured address (the wizard fills it in, P04-T02). Derived from
    // location/country for old listings, which are flagged needsReview.
    address: {
      line1: { type: String, trim: true, maxlength: 200 },
      city: { type: String, trim: true, maxlength: 100 },
      state: { type: String, trim: true, maxlength: 100 },
      country: { type: String, trim: true, maxlength: 100 },
      postalCode: { type: String, trim: true, maxlength: 20 },
    },

    // True while address (or price/coordinates) was guessed during migration
    // and the host has not confirmed it.
    needsReview: { type: Boolean, default: false },

    // Precise point: private (never sent to the browser as such, P06-T02).
    // A draft has none until the location step has looked the address up.
    geometry: {
      type: {
        type: String,
        enum: [\"Point\"],
        required: function () {
          return this.status !== \"draft\";
        },
      },
      coordinates: {
        type: [Number],
        required: function () {
          return this.status !== \"draft\";
        },
      },
    },

    // Approximate point shown publicly; filled by P06-T02.
    publicGeometry: {
      type: { type: String, enum: [\"Point\"] },
      coordinates: { type: [Number], default: undefined },
    },

    timezone: { type: String, default: \"Asia/Kolkata\" }, // ADR-008

    capacity: {
      guests: count(2, 1, MAX_GUESTS),
      bedrooms: count(1, 0, 50),
      beds: count(1, 0, 50),
      bathrooms: {
        type: Number,
        default: 1,
        min: 0,
        max: 50,
        validate: {
          validator: (v) => v === null || v === undefined || (v * 2) % 1 === 0,
          message: \"{PATH} must be a whole or half number\",
        },
      },
    },

    amenities: { type: [{ type: String, trim: true, maxlength: 60 }] },
    // Declared by the host, never verified (P15-T05); keys from ACCESSIBILITY_FEATURES.
    accessibility: { type: [{ type: String, trim: true, maxlength: 40 }] },
    houseRules: { type: String, trim: true, maxlength: 2000 },
    // The host explicitly says there are no special rules (a readiness item).
    noSpecialRules: { type: Boolean, default: false },

    checkInTime: {
      type: String,
      default: \"14:00\",
      match: [TIME_PATTERN, \"Check-in time must look like 14:00\"],
    },
    checkOutTime: {
      type: String,
      default: \"11:00\",
      match: [TIME_PATTERN, \"Check-out time must look like 11:00\"],
    },

    minNights: { type: Number, default: 1, min: 1, max: 365, validate: integer },
    maxNights: { type: Number, default: 30, min: 1, max: 365, validate: integer },

    // Booking rules set by the host (P07-T06; src/services/bookingRules.js).
    // Notice is measured before the check-in moment, in the listing's time
    // zone. The cut-off is the time of day (listing zone) after which a stay
    // starting today can no longer be booked.
    advanceNoticeHours: { type: Number, default: 0, min: 0, max: 168, validate: integer },
    sameDayCutoffTime: {
      type: String,
      default: \"20:00\",
      match: [TIME_PATTERN, \"Same-day cut-off must look like 20:00\"],
    },

    instantBook: { type: Boolean, default: false },
    cancellationPolicy: {
      type: String,
      enum: CANCELLATION_POLICIES,
      default: \"moderate\",
    },

    pricing: {
      nightlyMinor: minorAmount(MIN_NIGHTLY_MINOR, \"pricing.nightlyMinor\"),
      weekendNightlyMinor: minorAmount(MIN_NIGHTLY_MINOR, \"pricing.weekendNightlyMinor\"),
      cleaningFeeMinor: { ...minorAmount(0, \"pricing.cleaningFeeMinor\"), default: 0 },
      // Price rules (P08-T04), applied in the order documented in
      // src/services/pricing.js. Weekend markup: percent added to a weekend
      // night's price, in basis points (2000 = 20 %).
      weekendBps: {
        type: Number,
        validate: { validator: (v) => v === undefined || v === null || (Number.isInteger(v) && v >= 0 && v <= 10000), message: \"Weekend markup must be a whole number of basis points from 0 to 10000.\" },
      },
      // At most 5 seasons, which may not overlap; `from` and `to` are date-only
      // (UTC midnight) and both inclusive.
      seasonalRates: {
        type: [
          new Schema(
            {
              name: { type: String, required: true, trim: true, maxlength: 40 },
              from: { type: Date, required: true },
              to: { type: Date, required: true },
              nightlyMinor: minorAmount(MIN_NIGHTLY_MINOR, \"pricing.seasonalRates.nightlyMinor\"),
            },
            { _id: false },
          ),
        ],
        validate: [
          { validator: (v) => !v || v.length <= 5, message: \"A listing can have at most 5 seasonal prices.\" },
          {
            validator: (v) => !v || v.every((x) => x.from <= x.to),
            message: \"A season cannot end before it starts.\",
          },
          {
            validator: (v) => {
              const sorted = [...(v || [])].sort((a, b) => a.from - b.from);
              return sorted.every((x, i) => i === 0 || x.from > sorted[i - 1].to);
            },
            message: \"Seasonal prices cannot overlap.\",
          },
        ],
        default: undefined,
      },
      // Whole-percent discounts for long stays, in basis points (1000 = 10 %),
      // at most 50 %. A stay of 28+ nights gets the monthly one, 7+ the weekly
      // one; the larger applies, never both.
      discounts: {
        weeklyBps: { type: Number, min: 0, max: 5000, validate: integer },
        monthlyBps: { type: Number, min: 0, max: 5000, validate: integer },
      },
      currency: {
        type: String,
        default: \"INR\",
        match: [/^[A-Z]{3}$/, \"Currency must be a 3-letter code such as INR\"],
      },
    },

    // The old rupee price, kept as it was stored before migration 003.
    legacyPrice: { type: Number },

    // Denormalised from reviews (P12-T02): changed only by services/ratings.js,
    // in one atomic update together with `reviews`. ratingAvg = sum / count.
    ratingSum: { type: Number, default: 0, min: 0, validate: integer },
    ratingAvg: { type: Number, default: 0, min: 0, max: 5 },
    ratingCount: { type: Number, default: 0, min: 0, validate: integer },

    // Nearby places cache (P15-T01).
    nearby: {
      fetchedAt: { type: Date },
      items: { type: [nearbyItemSchema] },
    },

    reviews: [
      {
        type: Schema.Types.ObjectId,
        ref: \"Review\",
      },
    ],
    owner: {
      type: Schema.Types.ObjectId,
      ref: \"User\",
    },

    // Listing wizard (P04-T02). `wizardSteps` lists the steps (1-5) the host has
    // completed; `draftToken` is a one-time id the first step carries so that
    // submitting it twice (double click, back button) makes one draft.
    wizardSteps: { type: [Number], default: undefined },
    draftToken: { type: String, maxlength: 64 },

    // Search keys (P05-T01): lower-case, accent-free copies of the city, state
    // and country, kept in step with the address by the validate hook below.
    cityKey: { type: String, maxlength: 100 },
    stateKey: { type: String, maxlength: 100 },
    countryKey: { type: String, maxlength: 100 },
    locationKey: { type: String, maxlength: 320 },

    // Set only on listings imported from a sample dataset (scripts/import-dataset.js);
    // the import matches on it, so running it twice never duplicates.
    importedFrom: {
      source: { type: String, maxlength: 40 },
      id: { type: String, maxlength: 64 },
    },

    // Places around the listing, from OpenStreetMap (P15-T01). Written only by
    // src/services/nearby.js; distances are straight lines from the PUBLIC
    // (approximate) point. `key` says which precise point the data is for.
    nearby: {
      fetchedAt: { type: Date },
      attemptedAt: { type: Date },
      source: { type: String, maxlength: 60 },
      key: { type: String, maxlength: 32 },
      failures: { type: Number, default: 0, min: 0 },
      nextRetryAt: { type: Date },
      items: [
        {
          _id: false,
          category: { type: String, maxlength: 20 },
          name: { type: String, maxlength: 100 },
          kind: { type: String, maxlength: 40 },
          distanceM: { type: Number, min: 0 },
        },
      ],
    },

    // Soft delete: the row stays, the pages stop showing it (P04-T05).
    deletedAt: { type: Date },

    // Set when the listing went from published to suspended only because its
    // host's account was suspended (P14-T02). Reinstating the host restores
    // exactly these listings; a listing suspended by moderation (P14-T03) does
    // not carry the flag and stays suspended.
    hiddenByOwnerSuspension: { type: Boolean },

    // Moderation (P14-T03). `reviewedAt/By`: an admin has looked at the
    // listing (marked reviewed, suspended it or restored it); a published
    // listing without it is in the \"new\" queue. `suspended*` describe the
    // CURRENT moderation suspension, cleared when the listing is restored (the
    // audit log keeps the history). The reason is shown to the host.
    moderation: {
      reviewedAt: { type: Date },
      reviewedBy: { type: Schema.Types.ObjectId, ref: \"User\" },
      suspendedAt: { type: Date },
      suspendedBy: { type: Schema.Types.ObjectId, ref: \"User\" },
      suspendReason: { type: String, trim: true, maxlength: 500 },
    },
  },
  { timestamps: true },
);

// The search keys always follow the address (and, for old listings, the
// free-text location), so a save can never leave them stale. Updates that skip
// `save()` (updateOne, bulkWrite) must set them themselves; see buildSeedListings.
listingSchema.pre(\"validate\", function () {
  const keys = keysForListing(this);
  for (const [name, value] of Object.entries(keys)) {
    if (this.get(name) !== value) this.set(name, value);
  }
});

// The public point always follows the precise one (P06-T02): same listing, same
// offset, so it moves only when the address does. Updates that skip save() must
// set it themselves; migration 007 repairs the rest.
listingSchema.pre(\"validate\", function () {
  const coordinates = this.get(\"geometry.coordinates\");
  const precise = {
    type: this.get(\"geometry.type\"),
    coordinates: coordinates ? Array.from(coordinates) : undefined,
  };
  const wanted = approximatePoint(precise, this._id);
  if (!wanted) {
    if (this.get(\"publicGeometry.type\") !== undefined) this.set(\"publicGeometry\", undefined);
    return;
  }
  const now = this.get(\"publicGeometry.coordinates\");
  const same =
    now &&
    this.get(\"publicGeometry.type\") === \"Point\" &&
    now[0] === wanted.coordinates[0] &&
    now[1] === wanted.coordinates[1];
  if (!same) this.set(\"publicGeometry\", wanted);
});

// A stay whose minimum is longer than its maximum can never be booked.
listingSchema.pre(\"validate\", function () {
  if (
    Number.isFinite(this.minNights) &&
    Number.isFinite(this.maxNights) &&
    this.minNights > this.maxNights
  ) {
    this.invalidate(
      \"minNights\",
      \"Minimum nights cannot be more than maximum nights\",
      this.minNights,
    );
  }
});

// Index names are explicit and match the migrations, which build the same
// indexes on existing databases (003, 005-007, and 010 for the sort indexes and
// the two it drops). Migration 003 also built status_1_address.city_1 and
// pricing.nightlyMinor_1; migration 010 (P18-T02) drops them because no query
// uses them any more (see docs/PERFORMANCE.md).
listingSchema.index({ owner: 1, status: 1 }, { name: \"owner_1_status_1\" });
listingSchema.index(
  { title: \"text\", description: \"text\" },
  { name: \"title_text_description_text\" },
);
// Search (P05-T01): status + city + price, and status + country + price, serve
// the destination box and the price filter. Built by migration 006.
listingSchema.index(
  { status: 1, cityKey: 1, \"pricing.nightlyMinor\": 1 },
  { name: \"status_1_cityKey_1_pricing.nightlyMinor_1\" },
);
listingSchema.index(
  { status: 1, countryKey: 1, \"pricing.nightlyMinor\": 1 },
  { name: \"status_1_countryKey_1_pricing.nightlyMinor_1\" },
);
// Sorting the public listings without a destination (P18-T02, migration 010):
// each order the search offers, and the home page and the map, read the
// published listings already in order instead of sorting them in memory.
// Price descending reads the price index backwards.
listingSchema.index(
  { status: 1, _id: -1 },
  { name: \"status_1__id_-1\" },
);
listingSchema.index(
  { status: 1, createdAt: -1, _id: -1 },
  { name: \"status_1_createdAt_-1__id_-1\" },
);
listingSchema.index(
  { status: 1, ratingAvg: -1, ratingCount: -1, _id: -1 },
  { name: \"status_1_ratingAvg_-1_ratingCount_-1__id_-1\" },
);
listingSchema.index(
  { status: 1, \"pricing.nightlyMinor\": 1, _id: 1 },
  { name: \"status_1_pricing.nightlyMinor_1__id_1\" },
);
// Map queries (P06-T04) use the PUBLIC point only. Built by migration 007.
listingSchema.index({ publicGeometry: \"2dsphere\" }, { name: \"publicGeometry_2dsphere\" });

// One draft per (host, form): see draftToken. Built by migration 005.
listingSchema.index(
  { owner: 1, draftToken: 1 },
  {
    name: \"owner_1_draftToken_1\",
    unique: true,
    partialFilterExpression: { draftToken: { $type: \"string\" } },
  },
);

// Deleting a listing removes the reviews written before bookings existed. A
// review of a real stay (it has a reservation) is kept: it stays attached to
// the listing's id and to the snapshot taken when it was written (P12-T01).
listingSchema.post(\"findOneAndDelete\", async (listing) => {
  if (listing) {
    await Review.deleteMany({
      _id: { $in: listing.reviews },
      reservation: { $exists: false },
    });
  }
});

const Listing = mongoose.model(\"Listing\", listingSchema);

Listing.STATUSES = STATUSES;
Listing.MIN_NIGHTLY_MINOR = MIN_NIGHTLY_MINOR;
Listing.MAX_IMAGES = MAX_IMAGES;

module.exports = Listing;

// Daily counters about one listing (P13-T03), one row per listing per day.
// The day is a date-only UTC-midnight Date for the calendar day in the app's
// time zone (utils/dates DEFAULT_TIMEZONE). Rows are only ever created and
// bumped with $inc by services/listingStats.js; nothing here is exact:
//   views          page opens, once per browser session per listing per day,
//                  bots and the host's own visits left out
//   saves          stays saved that day (an un-save does not subtract: the
//                  lifetime total in ListingStat.saves is the net figure)
//   checkoutStarts checkout page opens, same once-per-session-per-day rule
const mongoose = require(\"mongoose\");
const Schema = mongoose.Schema;

const counter = { type: Number, default: 0, min: 0 };

const listingDayStatSchema = new Schema({
  listing: { type: Schema.Types.ObjectId, ref: \"Listing\", required: true },
  day: { type: Date, required: true },
  views: counter,
  saves: counter,
  checkoutStarts: counter,
});

listingDayStatSchema.index({ listing: 1, day: 1 }, { unique: true });

module.exports = mongoose.model(\"ListingDayStat\", listingDayStatSchema);

// Counters about one listing, kept apart from the listing so counting never
// rewrites (or races with) a host's edit. `saves` = wishlist entries holding
// the listing (P10-T01). Host stats (P13-T03) read it.
const mongoose = require(\"mongoose\");
const Schema = mongoose.Schema;

const listingStatSchema = new Schema({
  listing: {
    type: Schema.Types.ObjectId,
    ref: \"Listing\",
    required: true,
    unique: true,
  },
  saves: { type: Number, default: 0, min: 0 },
  // How often the stay was shown on, and opened from, a results page ordered by
  // Best match, per ordering (P15-T06; src/services/rankingStats.js).
  ranking: Object.fromEntries(
    [\"default\", \"work\", \"family\", \"weekend\"].map((variant) => [
      variant,
      { shown: { type: Number, default: 0, min: 0 }, clicked: { type: Number, default: 0, min: 0 } },
    ]),
  ),
});

module.exports = mongoose.model(\"ListingStat\", listingStatSchema);

// One message (P11-T02): plain text, written only by
// src/services/conversations.js `send`, never edited or deleted.
const mongoose = require(\"mongoose\");
const { LIMITS } = require(\"../config/conversations\");

const Schema = mongoose.Schema;

const messageSchema = new Schema(
  {
    conversation: {
      type: Schema.Types.ObjectId,
      ref: \"Conversation\",
      required: true,
    },
    sender: { type: Schema.Types.ObjectId, ref: \"User\", required: true },
    body: { type: String, required: true, maxlength: LIMITS.body },
  },
  { timestamps: { createdAt: true, updatedAt: false } },
);

messageSchema.index({ conversation: 1, _id: -1 });

module.exports = mongoose.model(\"Message\", messageSchema);

// In-app notification (P11-T01): one row per message to one member. Written
// only through src/services/notifications.js `notify`, which validates the
// text and the link; read only for the member it belongs to (every query in
// the service filters on `user`).
//
// Lifecycle: created unread (`readAt: null`, no `deleteAfter`). Reading sets
// `readAt` and `deleteAfter` (read time + READ_RETENTION_DAYS); the TTL index
// on `deleteAfter` then removes the row. MongoDB ignores a row whose
// `deleteAfter` is not a date, so unread rows are never removed by it.
const mongoose = require(\"mongoose\");
const {
  REF_KINDS,
  TYPE_PATTERN,
  LIMITS,
} = require(\"../config/notifications\");

const Schema = mongoose.Schema;

const notificationSchema = new Schema(
  {
    // The only person who can see this row.
    user: {
      type: Schema.Types.ObjectId,
      ref: \"User\",
      required: true,
    },
    type: {
      type: String,
      required: true,
      trim: true,
      match: TYPE_PATTERN,
      maxlength: LIMITS.type,
    },
    // What the message is about (a booking, a listing...), if anything.
    ref: {
      kind: { type: String, enum: REF_KINDS },
      id: { type: Schema.Types.ObjectId },
    },
    // Plain text; views escape it. `url` is a same-site path.
    title: {
      type: String,
      required: true,
      trim: true,
      maxlength: LIMITS.title,
    },
    body: { type: String, trim: true, maxlength: LIMITS.body },
    url: { type: String, trim: true, maxlength: LIMITS.url },
    readAt: { type: Date, default: null },
    deleteAfter: { type: Date },
  },
  { timestamps: { createdAt: true, updatedAt: false } },
);

// The list (newest first, optionally unread only) and the unread count.
notificationSchema.index({ user: 1, readAt: 1, createdAt: -1 });
// TTL: removes a read notification once `deleteAfter` has passed.
notificationSchema.index({ deleteAfter: 1 }, { expireAfterSeconds: 0 });

module.exports = mongoose.model(\"Notification\", notificationSchema);

// A report about a listing, review, member or message (P12-T04). Created only
// through src/services/reports.js. Never deleted: moderators (P14-T04) close
// it as resolved or dismissed.
//
// One OPEN report per (reporter, target): the partial unique index below is
// what makes that true under concurrent requests; the service only turns the
// index error into a friendly message. Once a report is closed the same
// person may report the same target again.
const mongoose = require(\"mongoose\");
const {
  KIND_VALUES,
  REASON_VALUES,
  REPORT_STATUSES,
  LIMITS,
} = require(\"../config/reports\");
const Schema = mongoose.Schema;

const reportSchema = new Schema(
  {
    reporter: { type: Schema.Types.ObjectId, ref: \"User\", required: true },
    targetKind: { type: String, enum: KIND_VALUES, required: true },
    targetId: { type: Schema.Types.ObjectId, required: true },
    // Who made the thing that was reported (listing host, review author, the
    // member). null when unknown (an old review without an author).
    targetOwner: { type: Schema.Types.ObjectId, ref: \"User\", default: null },
    // Short text so the reporter's list still reads when the target changes or goes.
    targetLabel: { type: String, trim: true, maxlength: 160 },

    reason: { type: String, enum: REASON_VALUES, required: true },
    details: { type: String, trim: true, maxlength: LIMITS.detailsMax },

    status: {
      type: String,
      enum: REPORT_STATUSES,
      default: \"open\",
      required: true,
    },
    // Filled when a moderator closes it (P14-T04).
    resolvedAt: { type: Date },
    resolvedBy: { type: Schema.Types.ObjectId, ref: \"User\" },
    resolutionNote: { type: String, trim: true, maxlength: 500 },
  },
  { timestamps: true },
);

reportSchema.index(
  { reporter: 1, targetKind: 1, targetId: 1 },
  { unique: true, partialFilterExpression: { status: \"open\" } },
);
reportSchema.index({ reporter: 1, createdAt: -1 });
reportSchema.index({ status: 1, createdAt: -1 }); // the moderators' queue
reportSchema.index({ targetKind: 1, targetId: 1 });

module.exports = mongoose.model(\"Report\", reportSchema);

// A booking (P07-T05). Created only through src/services/reservations.js,
// which holds the nights in the ledger first (ADR-004). Never hard-deleted.
//
// The snapshots keep the guest's contract correct when the listing changes
// later: the price breakdown, and the title, rules and policy as they were.
const mongoose = require(\"mongoose\");
const { isDateOnly } = require(\"../utils/dates\");
const { STATUSES, ACTORS } = require(\"../services/stateMachine\");
const Schema = mongoose.Schema;

const dateOnly = {
  type: Date,
  required: true,
  validate: {
    validator: isDateOnly,
    message: \"{PATH} must be a date-only value (00:00:00.000Z)\",
  },
};
const minor = { type: Number, min: 0, validate: Number.isSafeInteger };

const historySchema = new Schema(
  {
    from: { type: String, enum: [...STATUSES, null], default: null },
    to: { type: String, enum: STATUSES, required: true },
    at: { type: Date, required: true },
    actor: { type: String, enum: ACTORS, required: true },
    by: { type: Schema.Types.ObjectId, ref: \"User\" },
    note: { type: String, maxlength: 500 },
  },
  { _id: false },
);

const reservationSchema = new Schema(
  {
    listing: { type: Schema.Types.ObjectId, ref: \"Listing\", required: true },
    guest: { type: Schema.Types.ObjectId, ref: \"User\", required: true },
    host: { type: Schema.Types.ObjectId, ref: \"User\", required: true },

    checkIn: dateOnly,
    checkOut: dateOnly,
    nights: { type: Number, required: true, min: 1, max: 90, validate: Number.isInteger },
    guests: { type: Number, required: true, min: 1, max: 100, validate: Number.isInteger },

    status: { type: String, enum: STATUSES, required: true },
    statusHistory: { type: [historySchema], default: [] },
    // Set only while a host-approval request is pending (the ledger rows carry
    // the same instant).
    holdExpiresAt: { type: Date },

    pricingSnapshot: {
      lines: { type: [Schema.Types.Mixed], default: [] },
      nights: minor,
      subtotalMinor: minor,
      cleaningMinor: minor,
      serviceFeeMinor: minor,
      taxMinor: minor,
      totalMinor: { ...minor, required: true },
      avgPerNightMinor: minor,
      currency: { type: String, required: true, match: /^[A-Z]{3}$/ },
      taxMode: { type: String },
      taxIncluded: { type: Boolean },
      breakdownVersion: { type: Number },
    },

    listingSnapshot: {
      title: { type: String },
      city: { type: String },
      coverUrl: { type: String },
      houseRules: { type: String },
      noSpecialRules: { type: Boolean },
      cancellationPolicy: { type: String },
      checkInTime: { type: String },
      checkOutTime: { type: String },
      timezone: { type: String },
      instantBook: { type: Boolean },
    },

    // Chosen by the browser per checkout page; a repeated submit returns the
    // original reservation (unique with the guest).
    idempotencyKey: { type: String, required: true, minlength: 8, maxlength: 64 },

    // Set once by the sweeper when \"check-in tomorrow\" was sent (P11-T04), so
    // a repeated pass or a second instance sends it only once.
    reminders: { checkIn: { type: Date } },

    cancelReason: { type: String, trim: true, maxlength: 500 },
    cancelledBy: { type: String, enum: ACTORS },
    // What a cancellation refunds (P09-T03), written in the same update that
    // changes the status. CALCULATED AND RECORDED only: no money moves
    // (payments are simulated until P16, which acts on this record).
    refund: {
      amountMinor: minor,
      retainedMinor: minor,
      totalMinor: minor,
      currency: { type: String, match: /^[A-Z]{3}$/ },
      policy: { type: String },
      rule: { type: String },
      calculatedAt: { type: Date },
    },
    // Every change of dates (P09-T04), oldest first. The price snapshot above
    // always describes the CURRENT dates; each entry keeps what it replaced and
    // the difference between the two totals. CALCULATED AND RECORDED only: no
    // money moves (payments are simulated).
    modifications: {
      type: [
        new Schema(
          {
            at: { type: Date, required: true },
            by: { type: Schema.Types.ObjectId, ref: \"User\" },
            from: {
              checkIn: dateOnly,
              checkOut: dateOnly,
              nights: { type: Number, min: 1, max: 90 },
              totalMinor: minor,
            },
            to: {
              checkIn: dateOnly,
              checkOut: dateOnly,
              nights: { type: Number, min: 1, max: 90 },
              totalMinor: minor,
            },
            // new total - old total; negative when the new stay costs less
            differenceMinor: { type: Number, validate: Number.isSafeInteger },
            currency: { type: String, match: /^[A-Z]{3}$/ },
            // a pending request went back to the host for a new answer
            reapproval: { type: Boolean, default: false },
          },
          { _id: false },
        ),
      ],
      default: [],
    },
    paymentStatus: {
      type: String,
      enum: [\"none\", \"simulated_paid\", \"refunded_simulated\"],
      default: \"none\",
    },
  },
  { timestamps: true },
);

reservationSchema.pre(\"validate\", function () {
  if (this.checkIn && this.checkOut && this.checkOut <= this.checkIn) {
    this.invalidate(\"checkOut\", \"Check-out must be after check-in.\");
  }
});

reservationSchema.index({ guest: 1, createdAt: -1 });
// The host's requests inbox (P18-T02, migration 010): pending requests by
// hold, confirmed stays by check-in, already in order. They also serve every
// query on (host, status), which is why the plain (host, status) index is gone.
reservationSchema.index(
  { host: 1, status: 1, holdExpiresAt: 1, _id: 1 },
  { name: \"host_1_status_1_holdExpiresAt_1__id_1\" },
);
reservationSchema.index(
  { host: 1, status: 1, checkIn: 1, _id: 1 },
  { name: \"host_1_status_1_checkIn_1__id_1\" },
);
reservationSchema.index({ listing: 1, checkIn: 1 });
reservationSchema.index({ guest: 1, idempotencyKey: 1 }, { unique: true });
// The sweeper (P07-T07) looks for requests past their hold and for stays whose
// check-out has passed.
reservationSchema.index({ status: 1, holdExpiresAt: 1 });
reservationSchema.index({ status: 1, checkOut: 1 });

module.exports = mongoose.model(\"Reservation\", reservationSchema);

const mongoose = require(\"mongoose\");
const Schema = mongoose.Schema;

// Review model v2 (P12-T01). A new review belongs to one completed
// reservation: `reservation` is set, `legacy` is false, and a partial unique
// index allows one review per reservation. Reviews written before bookings
// existed have no reservation and are marked `legacy: true` by migration 008
// (ADR-010); they keep their content and are shown with a note.
//
// `listing` is the listing that was stayed in. It is kept even if the listing
// is later deleted, together with `listingSnapshot` (title and city when the
// review was written), so a review never loses what it was about.
const reviewSchema = new Schema(
  {
    comment: String,
    rating: {
      type: Number,
      min: 1,
      max: 5,
    },
    author: {
      type: Schema.Types.ObjectId,
      ref: \"User\",
    },
    listing: {
      type: Schema.Types.ObjectId,
      ref: \"Listing\",
    },
    reservation: {
      type: Schema.Types.ObjectId,
      ref: \"Reservation\",
    },
    legacy: {
      type: Boolean,
      default: false,
    },
    // Moderation (P14-T04). A hidden review is not shown on the listing and is
    // not in the listing's rating totals; its stay still counts as reviewed, so
    // the guest cannot simply write another. Reviews written before this field
    // existed have no status and are visible.
    status: {
      type: String,
      enum: [\"visible\", \"hidden\"],
      default: \"visible\",
    },
    moderation: {
      hiddenAt: Date,
      hiddenBy: { type: Schema.Types.ObjectId, ref: \"User\" },
      hiddenReason: { type: String, trim: true, maxlength: 500 },
    },
    listingSnapshot: {
      title: String,
      city: String,
    },
    // Set when the author changes the rating or comment inside the edit window
    // (P12-T03). Shown as \"Edited\" next to the review.
    editedAt: Date,
    // The host's one public reply (P12-T03). The host is the listing's owner;
    // `author` records who wrote it. Absent until the host replies.
    reply: {
      text: { type: String, trim: true, maxlength: 1000 },
      author: { type: Schema.Types.ObjectId, ref: \"User\" },
      createdAt: Date,
      editedAt: Date,
    },
  },
  { timestamps: true },
);

// One review per reservation. Partial, so legacy reviews (no reservation) do
// not collide. Built by migration 008 and by the model at startup.
reviewSchema.index(
  { reservation: 1 },
  {
    name: \"reservation_1_unique\",
    unique: true,
    partialFilterExpression: { reservation: { $type: \"objectId\" } },
  },
);
// A listing's reviews, newest first (the listing page and its aggregates).
reviewSchema.index(
  { listing: 1, createdAt: -1 },
  { name: \"listing_1_createdAt_-1\" },
);
reviewSchema.index(
  { author: 1, createdAt: -1 },
  { name: \"author_1_createdAt_-1\" },
);

module.exports = mongoose.model(\"Review\", reviewSchema);

// A search a member saved with a name (P10-T02). `query` is the canonical
// query string of /listings (built by the server from the validated search
// state, never copied from the browser), without the page number.
const mongoose = require(\"mongoose\");
const Schema = mongoose.Schema;

const savedSearchSchema = new Schema(
  {
    owner: { type: Schema.Types.ObjectId, ref: \"User\", required: true },
    name: { type: String, trim: true, required: true, maxlength: 60 },
    query: { type: String, required: true, maxlength: 1000 },
  },
  { timestamps: true },
);

savedSearchSchema.index({ owner: 1, name: 1 }, { unique: true });
savedSearchSchema.index({ owner: 1, createdAt: -1 });

module.exports = mongoose.model(\"SavedSearch\", savedSearchSchema);

// Night ledger (ADR-004, P07-T02). One document per occupied night of a
// listing: a reserved night (source.kind \"reservation\") or a host block
// (\"block\"). The unique index on (listing, date) is what makes double booking
// impossible: the database, not application code, refuses a second owner.
//
// `date` is a calendar date stored at 00:00:00.000Z (ADR-003). The check-out
// day of a stay is NOT a night. `holdExpiresAt` is set only while a pending
// (host-approval) request holds the night; a confirmed reservation or a block
// has none. Rows are written and removed only through src/services/ledger.js.
const mongoose = require(\"mongoose\");
const { isDateOnly } = require(\"../utils/dates\");
const Schema = mongoose.Schema;

const SOURCE_KINDS = Object.freeze([\"reservation\", \"block\"]);

const stayNightSchema = new Schema(
  {
    listing: {
      type: Schema.Types.ObjectId,
      ref: \"Listing\",
      required: true,
    },
    date: {
      type: Date,
      required: true,
      validate: {
        validator: isDateOnly,
        message: \"date must be a date-only value (00:00:00.000Z)\",
      },
    },
    source: {
      kind: { type: String, enum: SOURCE_KINDS, required: true },
      id: { type: Schema.Types.ObjectId, required: true },
    },
    holdExpiresAt: { type: Date },
  },
  { timestamps: { createdAt: true, updatedAt: false }, versionKey: false },
);

// The guard: no two rows for the same listing and night.
stayNightSchema.index({ listing: 1, date: 1 }, { unique: true });
// Release everything held by one reservation or block.
stayNightSchema.index({ \"source.id\": 1 });
// The sweeper finds expired holds (rows without a hold are skipped).
stayNightSchema.index({ holdExpiresAt: 1 }, { sparse: true });
// Search with dates (P18-T02, migration 010): \"which listings have a taken
// night between these dates\" has no listing in it, so (listing, date) cannot
// answer it and the whole ledger was read. The hold is in the key so the query
// is answered from the index alone.
stayNightSchema.index(
  { date: 1, listing: 1, holdExpiresAt: 1 },
  { name: \"date_1_listing_1_holdExpiresAt_1\" },
);

const StayNight = mongoose.model(\"StayNight\", stayNightSchema);
StayNight.SOURCE_KINDS = SOURCE_KINDS;

module.exports = StayNight;

const mongoose = require(\"mongoose\");
const passportLocalMongoose = require(\"passport-local-mongoose\").default;
const { parseDateOnly } = require(\"../utils/dates\");

const ROLES = [\"member\", \"admin\"];
const STATUSES = [\"active\", \"suspended\", \"deleted\"];

// Deliberately simple: one \"@\", no spaces, a dot in the domain. Strict address
// validation (Joi) is done by the signup form (`signupSchema`); this only keeps
// obvious garbage out of the unique index.
const EMAIL_PATTERN = /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/;

const userSchema = new mongoose.Schema(
  {
    // Stored trimmed and lower-case, so \"Ann@Example.com\" and \"ann@example.com\"
    // are the same address. The setter also applies to query filters.
    email: {
      type: String,
      required: [true, \"Email is required\"],
      trim: true,
      lowercase: true,
      unique: true,
      maxlength: [254, \"Email is too long\"],
      match: [EMAIL_PATTERN, \"Enter a valid email address\"],
    },

    // Shown instead of the username on public pages (P02-T03). Filled with the
    // username when empty (see the validate hook below).
    displayName: {
      type: String,
      trim: true,
      maxlength: [60, \"Display name must be 60 characters or fewer\"],
    },

    role: {
      type: String,
      enum: ROLES,
      default: \"member\",
      required: true,
    },

    // \"suspended\" accounts cannot log in (enforced by the login controller); \"deleted\" is
    // the anonymised state used by account deletion (P02-T04).
    status: {
      type: String,
      enum: STATUSES,
      default: \"active\",
      required: true,
    },

    // Same shape as Listing.image. Absent until the user uploads one (P02-T03).
    avatar: {
      url: { type: String },
      filename: { type: String },
    },

    bio: {
      type: String,
      trim: true,
      maxlength: [500, \"Bio must be 500 characters or fewer\"],
      default: \"\",
    },

    // How many confirmed bookings this person cancelled as a HOST (P09-T03).
    // Only ever incremented, by services/cancellations.js; shown on the
    // public profile when above zero.
    hostCancellationCount: {
      type: Number,
      default: 0,
      min: 0,
      validate: Number.isInteger,
    },

    // Which notification emails the member wants (P11-T05). Unset = the
    // group's default (config/notificationPrefs.js); in-app is always on.
    notificationEmail: {
      bookings: { type: Boolean },
      reminders: { type: Boolean },
      reviews: { type: Boolean },
    },

    // null = not verified. Set by the verification flow (P02-T05).
    emailVerifiedAt: {
      type: Date,
      default: null,
    },
  },
  { timestamps: true },
);

// Runs before validation so a user created with only a username still gets a
// display name. Not an arrow function: it needs `this`.
userSchema.pre(\"validate\", function () {
  if (!this.displayName && this.username) {
    this.displayName = this.username;
  }
});

// Per-account brake on password guessing (P02-T02), on top of the per-IP rate
// limit. passport-local-mongoose slows repeated failures down (each failure
// makes the next attempt wait longer, up to MAX_INTERVAL_MS) and, after
// MAX_ATTEMPTS failures, refuses even the correct password until
// UNLOCK_INTERVAL_MS has passed since the last attempt. A correct password
// resets the counter.
const LOGIN_LIMITS = Object.freeze({
  MAX_ATTEMPTS: 10,
  UNLOCK_INTERVAL_MS: 15 * 60 * 1000,
  MAX_INTERVAL_MS: 5 * 60 * 1000,
});

userSchema.plugin(passportLocalMongoose, {
  limitAttempts: true,
  maxAttempts: LOGIN_LIMITS.MAX_ATTEMPTS,
  unlockInterval: LOGIN_LIMITS.UNLOCK_INTERVAL_MS,
  maxInterval: LOGIN_LIMITS.MAX_INTERVAL_MS,
});

// The plugin defaults `last` (time of the last attempt) to \"now\". Accounts
// created before this task have no such field, so \"now\" would be filled in each
// time they are loaded and their first login would look like a too-fast retry.
// A missing value means \"no attempt yet\".
userSchema.path(\"last\").default(() => parseDateOnly(\"1970-01-01\"));

const User = mongoose.model(\"User\", userSchema);

module.exports = User;
module.exports.ROLES = ROLES;
module.exports.STATUSES = STATUSES;
module.exports.EMAIL_PATTERN = EMAIL_PATTERN;
module.exports.LOGIN_LIMITS = LOGIN_LIMITS;

// A member's list of saved stays (P10-T01). Every member gets one default list
// (\"Saved\"), created the first time they save a stay. Items live in
// WishlistItem so a list can hold 100 stays without growing one document.
const mongoose = require(\"mongoose\");
const { DEFAULT_NAME } = require(\"../config/wishlists\");
const Schema = mongoose.Schema;

const wishlistSchema = new Schema(
  {
    owner: { type: Schema.Types.ObjectId, ref: \"User\", required: true },
    name: { type: String, trim: true, maxlength: 60, default: DEFAULT_NAME },
    isDefault: { type: Boolean, default: false },
    // A read-only share link (P10-T04): /shared/lists/<shareToken>. Unset = not
    // shared. The token is a capability like a \"anyone with the link\" address:
    // 24 random bytes, unique, removed when the owner stops sharing.
    shareToken: { type: String },
    sharedAt: { type: Date },
  },
  { timestamps: true },
);

// At most one default list per member, even when two requests race to make it.
wishlistSchema.index(
  { owner: 1, isDefault: 1 },
  { unique: true, partialFilterExpression: { isDefault: true } },
);
wishlistSchema.index({ owner: 1, name: 1 }, { unique: true });
wishlistSchema.index(
  { shareToken: 1 },
  { unique: true, partialFilterExpression: { shareToken: { $type: \"string\" } } },
);

module.exports = mongoose.model(\"Wishlist\", wishlistSchema);

// One saved stay in one list (P10-T01). `owner` is repeated here so \"which of
// these stays has this member saved?\" is a single indexed query.
const mongoose = require(\"mongoose\");
const Schema = mongoose.Schema;

const wishlistItemSchema = new Schema({
  wishlist: { type: Schema.Types.ObjectId, ref: \"Wishlist\", required: true },
  owner: { type: Schema.Types.ObjectId, ref: \"User\", required: true },
  listing: { type: Schema.Types.ObjectId, ref: \"Listing\", required: true },
  // The member's own note about this stay in this list (P10-T02), plain text.
  note: { type: String, trim: true, maxlength: 300 },
  createdAt: { type: Date, default: Date.now },
});

// A stay is in a list once: this index makes saving twice a no-op under races.
wishlistItemSchema.index({ wishlist: 1, listing: 1 }, { unique: true });
wishlistItemSchema.index({ owner: 1, createdAt: -1 });
wishlistItemSchema.index({ owner: 1, listing: 1 });

module.exports = mongoose.model(\"WishlistItem\", wishlistItemSchema);

// Who may open the admin area (P14-T01). `(user) => boolean`.
// Only an active admin: a suspended or deleted admin account has no access.
const { isAdmin } = require(\"./shared\");

function access(user) {
  return isAdmin(user);
}

module.exports = { access };

// Who may use a conversation (P11-T02). Only its two people: neither an admin
// nor anyone else. (An admin reaches a message only through a report, P12-T04.)
const { sameId, isActiveUser } = require(\"./shared\");

/** True when `user` is the guest or the host of `conversation` (active or not). */
function isParticipant(user, conversation) {
  return Boolean(
    user &&
    conversation &&
    (sameId(conversation.guest, user._id) ||
      sameId(conversation.host, user._id)),
  );
}

/**
 * Start a conversation about a listing (\"Contact host\"): any active member
 * except the listing's own host. Whether the host can receive messages is
 * checked by the service.
 */
function start(user, listing) {
  if (!isActiveUser(user) || !listing) return false;
  return !sameId(listing.owner, user._id);
}

/** Read a conversation: its guest or host, while their account is active. */
function view(user, conversation) {
  return isActiveUser(user) && isParticipant(user, conversation);
}

/** Send a message: same people as `view`. */
function send(user, conversation) {
  return view(user, conversation);
}

module.exports = { start, view, send, isParticipant };

// Policy registry (P02-T06). One place that says who may do what.
//
//   can(\"listing:edit\", req.user, listing)   -> true | false
//
// Policies are pure functions `(user, resource) => boolean`: no database, no
// request object, so they are easy to test (tests/unit/policies.test.js) and
// safe to call from views (`can(...)` in res.locals). Add new actions here and
// extend the matrix test; the `authorize()` middleware and the views pick them
// up by name.
const listing = require(\"./listing\");
const review = require(\"./review\");
const admin = require(\"./admin\");
const reservation = require(\"./reservation\");
const report = require(\"./report\");
const conversation = require(\"./conversation\");
const { isAdmin, hasRole } = require(\"./shared\");

const POLICIES = {
  \"listing:create\": listing.create,
  \"listing:edit\": listing.edit,
  \"listing:delete\": listing.delete,
  \"review:create\": review.create,
  \"review:delete\": review.delete,
  \"review:edit\": review.edit,
  \"review:reply\": review.reply,
  \"reservation:view\": reservation.view,
  \"reservation:respond\": reservation.respond,
  \"reservation:cancel\": reservation.cancel,
  \"reservation:modify\": reservation.modify,
  \"report:create\": report.create,
  \"conversation:start\": conversation.start,
  \"conversation:view\": conversation.view,
  \"conversation:send\": conversation.send,
  \"admin:access\": admin.access,
};

/**
 * @param {string} action   e.g. \"listing:edit\"
 * @param {object} [user]   req.user, undefined when anonymous
 * @param {object} [resource] the listing/review the action applies to
 * @returns {boolean}
 * @throws {Error} for an unknown action (a typo must fail loudly, not allow or deny silently)
 */
function can(action, user, resource) {
  const policy = POLICIES[action];
  if (!policy) throw new Error(`Unknown policy action: \"${action}\"`);
  return Boolean(policy(user, resource));
}

function actions() {
  return Object.keys(POLICIES);
}

module.exports = { can, actions, isAdmin, hasRole };

// Who may do what with a listing. `(user, listing) => boolean`.
// `user` is req.user (or undefined for an anonymous visitor).
const { sameId, isActiveUser, isAdmin } = require(\"./shared\");

/** Any active member can create a listing. */
function create(user) {
  return isActiveUser(user);
}

/** Only the host edits a listing (an admin moderates; see `remove`). */
function edit(user, listing) {
  return Boolean(
    isActiveUser(user) && listing && sameId(listing.owner, user._id),
  );
}

/** The host, or an admin. A listing without an owner can only be removed by an admin. */
function remove(user, listing) {
  return Boolean(listing) && (edit(user, listing) || isAdmin(user));
}

module.exports = { create, edit, delete: remove };

// Who may report what (P12-T04). `(user, target) => boolean`, where target is
// `{ owner }`: whoever made the thing being reported.
const { sameId, isActiveUser } = require(\"./shared\");

/** Any active member, except about their own listing, review or profile. */
function create(user, target) {
  if (!isActiveUser(user)) return false;
  return !(target && sameId(target.owner, user._id));
}

module.exports = { create };

// Who may do what with a booking. `(user, reservation) => boolean`.
// Cancelling (P09-T03) gets its own actions there.
const { sameId, isActiveUser, isAdmin } = require(\"./shared\");

/** The guest who booked it, the host of the place, or an admin (P09-T01). */
function view(user, reservation) {
  if (!reservation || !isActiveUser(user)) return false;
  return Boolean(
    sameId(reservation.guest, user._id) ||
    sameId(reservation.host, user._id) ||
    isAdmin(user),
  );
}

/**
 * Accept or decline a request (P09-T02): only the host of that booking. An
 * admin cannot answer for a host, and a suspended host cannot answer at all.
 */
function respond(user, reservation) {
  if (!reservation || !isActiveUser(user)) return false;
  return sameId(reservation.host, user._id);
}

/**
 * Cancel a booking (P09-T03): its guest or its host, nobody else (an admin
 * cannot cancel for either side). Which side is acting is decided by the
 * service from who the user is; the state machine says what each side may
 * cancel.
 */
function cancel(user, reservation) {
  if (!reservation || !isActiveUser(user)) return false;
  return (
    sameId(reservation.guest, user._id) || sameId(reservation.host, user._id)
  );
}

/**
 * Change the dates of a booking (P09-T04): only the guest who made it. The
 * host cannot move a guest's stay (they decline or cancel), an admin cannot
 * act for the guest, and a suspended guest cannot change anything.
 */
function modify(user, reservation) {
  if (!reservation || !isActiveUser(user)) return false;
  return sameId(reservation.guest, user._id);
}

module.exports = { view, respond, cancel, modify };

// Who may do what with a review. `(user, review) => boolean`.
const { sameId, isActiveUser, isAdmin } = require(\"./shared\");

/** Any active member can write a review (eligibility rules arrive in P12-T01). */
function create(user) {
  return isActiveUser(user);
}

/** The author, or an admin. A review without an author can only be removed by an admin. */
function remove(user, review) {
  if (!review) return false;
  return Boolean(
    (isActiveUser(user) && sameId(review.author, user._id)) || isAdmin(user),
  );
}

/**
 * Only the author edits a review, and only while the account is active. An
 * admin moderates (hides) but never rewrites someone's words. Whether the edit
 * window is still open is decided by services/reviews.js, which knows the time.
 */
function edit(user, review) {
  return Boolean(
    review && isActiveUser(user) && sameId(review.author, user._id),
  );
}

/**
 * The host's reply (P12-T03). The resource is the LISTING the review is on:
 * only its owner may reply, edit the reply or take it back.
 */
function reply(user, listing) {
  return Boolean(
    listing && isActiveUser(user) && sameId(listing.owner, user._id),
  );
}

module.exports = { create, delete: remove, edit, reply };

// Small helpers shared by the policy files. Pure: no database, no Express.

/** Id of an ObjectId, a populated document, a plain { _id } or a string. */
function idOf(value) {
  if (value === undefined || value === null) return null;
  if (value._id !== undefined && value._id !== null) return String(value._id);
  // A bare ObjectId (some driver versions have no `_id` getter) or a string.
  if (typeof value !== \"object\" || typeof value.toHexString === \"function\") {
    return String(value);
  }
  return null; // an object that carries no id

}

/** True when both refer to the same id. A missing id never matches. */
function sameId(a, b) {
  const x = idOf(a);
  const y = idOf(b);
  return x !== null && y !== null && x === y;
}

/**
 * A logged-in account that may act. Accounts created before the v2 user model
 * have no `status`; they count as active. Suspended/deleted accounts can do
 * nothing.
 */
function isActiveUser(user) {
  return Boolean(
    user &&
    typeof user === \"object\" &&
    user._id !== undefined &&
    user._id !== null &&
    (user.status === undefined || user.status === \"active\"),
  );
}

function hasRole(user, role) {
  return isActiveUser(user) && user.role === role;
}

function isAdmin(user) {
  return hasRole(user, \"admin\");
}

module.exports = { idOf, sameId, isActiveUser, hasRole, isAdmin };

