// Changing the password and deleting the account (P02-T04).
//
// Delete is an anonymisation, not a removal: bookings, reviews, messages and
// reports other people rely on stay, but they point to an account that no
// longer holds anything personal.
//
// What deletion refuses (each with its own message and code), so nobody is left
// waiting on a person who has gone:
//   guest_confirmed  a confirmed stay as guest that has not ended
//   guest_pending    a request as guest still waiting for the host
//   host_confirmed   a confirmed stay at one of the member's places that has not ended
//   host_pending     a request waiting for the member's answer
//   last_admin       the only active administrator
// Past stays and lapsed requests do not block.
//
// What it does, in order: unpublish the member's published listings (so no new
// request can arrive), look for blockers once more (a booking may have landed
// in between; if so the listings are published again and nothing else is
// changed), then anonymise the account in one update that only applies to a
// still-active account.
//
// Anonymised account: username `deleted-<id>`, display name \"Deleted user\",
// email replaced by an unusable `.invalid` address, bio and avatar removed,
// password hash and salt replaced by random unusable values, status `deleted`,
// verification cleared. Saved stays and notifications are deleted, and the
// label of reports about the account no longer carries the old name. Reviews,
// reservations, messages, reports made by the member and audit rows stay.
// Sessions on other devices stop working because they identify the member by
// the old username.
const crypto = require(\"node:crypto\");
const { DEFAULT_TIMEZONE, todayIn } = require(\"../utils/dates\");
const { AppError } = require(\"../utils/errors\");

class AccountRefusal extends AppError {
  /** @param {string} message user-safe text @param {string} code */
  constructor(message, code, extra = {}) {
    super(409, message, { code });
    this.name = \"AccountRefusal\";
    Object.assign(this, extra);
  }
}

const plural = (n, one, many) => `${n} ${n === 1 ? one : many}`;
const idText = (v) => String(v && v._id ? v._id : v);

function models(over = {}) {
  return {
    UserModel: over.UserModel || require(\"../models/user\"),
    ListingModel: over.ListingModel || require(\"../models/listing\"),
    ReservationModel: over.ReservationModel || require(\"../models/reservation\"),
    WishlistModel: over.WishlistModel || require(\"../models/wishlist\"),
    WishlistItemModel:
      over.WishlistItemModel || require(\"../models/wishlistItem\"),
    SavedSearchModel: over.SavedSearchModel || require(\"../models/savedSearch\"),
    NotificationModel:
      over.NotificationModel || require(\"../models/notification\"),
    ReportModel: over.ReportModel || require(\"../models/report\"),
    deleteImage:
      over.deleteImage || require(\"../config/cloudinary\").deleteImage,
  };
}

/**
 * The plugin's failed-login errors as refusals; null for anything else (a bug
 * or an outage), which must not be reported as \"wrong password\".
 */
function refusalForLoginError(error, wrongPasswordText) {
  const name = error && error.name;
  if (name === \"AttemptTooSoonError\" || name === \"TooManyAttemptsError\") {
    return new AccountRefusal(
      \"Too many wrong passwords. Wait a few minutes and try again.\",
      \"locked\",
    );
  }
  if (
    name === \"IncorrectPasswordError\" ||
    name === \"MissingPasswordError\" ||
    name === \"IncorrectUsernameError\" ||
    name === \"NoSaltValueStoredError\"
  ) {
    return new AccountRefusal(wrongPasswordText, \"wrong_password\");
  }
  return null;
}

/**
 * Everything that stops this member from deleting the account right now.
 * @returns {Promise<{code: string, message: string, count?: number}[]>} empty when deletion is allowed
 */
async function deletionBlockers(user, { now = new Date(), ...over } = {}) {
  const { ReservationModel, UserModel } = models(over);
  const today = todayIn(DEFAULT_TIMEZONE, now);
  const live = { $gt: now };
  const [guestConfirmed, guestPending, hostConfirmed, hostPending] =
    await Promise.all([
      ReservationModel.countDocuments({
        guest: user._id,
        status: \"confirmed\",
        checkOut: { $gt: today },
      }),
      ReservationModel.countDocuments({
        guest: user._id,
        status: \"pending\",
        holdExpiresAt: live,
      }),
      ReservationModel.countDocuments({
        host: user._id,
        status: \"confirmed\",
        checkOut: { $gt: today },
      }),
      ReservationModel.countDocuments({
        host: user._id,
        status: \"pending\",
        holdExpiresAt: live,
      }),
    ]);
  const blockers = [];
  if (guestConfirmed) {
    blockers.push({
      code: \"guest_confirmed\",
      count: guestConfirmed,
      message: `You have ${plural(guestConfirmed, \"confirmed stay\", \"confirmed stays\")} that ${guestConfirmed === 1 ? \"has\" : \"have\"} not ended. Cancel ${guestConfirmed === 1 ? \"it\" : \"them\"} or wait until the stay is over.`,
    });
  }
  if (guestPending) {
    blockers.push({
      code: \"guest_pending\",
      count: guestPending,
      message: `You have ${plural(guestPending, \"booking request\", \"booking requests\")} waiting for a host. Withdraw ${guestPending === 1 ? \"it\" : \"them\"} first.`,
    });
  }
  if (hostConfirmed) {
    blockers.push({
      code: \"host_confirmed\",
      count: hostConfirmed,
      message: `${plural(hostConfirmed, \"guest has\", \"guests have\")} a confirmed stay at one of your places that ${hostConfirmed === 1 ? \"has\" : \"have\"} not ended. Cancel ${hostConfirmed === 1 ? \"it\" : \"them\"} or wait until the stay is over.`,
    });
  }
  if (hostPending) {
    blockers.push({
      code: \"host_pending\",
      count: hostPending,
      message: `${plural(hostPending, \"request is\", \"requests are\")} waiting for your answer. Accept or decline ${hostPending === 1 ? \"it\" : \"them\"} first.`,
    });
  }
  if (user.role === \"admin\") {
    const others = await UserModel.countDocuments({
      role: \"admin\",
      status: \"active\",
      _id: { $ne: user._id },
    });
    if (others === 0) {
      blockers.push({
        code: \"last_admin\",
        message:
          \"You are the only administrator. Make someone else an administrator before deleting this account.\",
      });
    }
  }
  return blockers;
}

/** The fields an anonymised account has (the `$set`), and the ones it loses (the `$unset`). */
function anonymisedUpdate(id) {
  const text = idText(id);
  return {
    $set: {
      username: `deleted-${text}`,
      displayName: \"Deleted user\",
      email: `deleted-${text}@deleted.invalid`,
      bio: \"\",
      status: \"deleted\",
      emailVerifiedAt: null,
      // Unusable credentials: random values nobody knows, so no password matches.
      hash: crypto.randomBytes(32).toString(\"hex\"),
      salt: crypto.randomBytes(32).toString(\"hex\"),
      attempts: 0,
    },
    $unset: { avatar: \"\" },
  };
}

/**
 * Delete (anonymise) the account of `user` after checking their password.
 * @param {{ user: object, password: string, now?: Date }} input  `user` is a Mongoose document
 * @throws {AccountRefusal} 409 with `code` and, for blockers, `blockers`
 */
async function deleteAccount({ user, password, now = new Date(), ...over }) {
  const m = models(over);
  const { user: verified, error } = await user.authenticate(
    String(password ?? \"\"),
  );
  if (!verified) {
    throw (
      refusalForLoginError(error, \"That password is not correct.\") ||
      error ||
      new AccountRefusal(\"That password is not correct.\", \"wrong_password\")
    );
  }

  const blockers = await deletionBlockers(user, { now, ...over });
  if (blockers.length > 0) {
    throw new AccountRefusal(\"Your account cannot be deleted yet.\", \"blocked\", {
      blockers,
    });
  }

  const owned = await m.ListingModel.find({
    owner: user._id,
    status: \"published\",
    deletedAt: null,
  })
    .select(\"_id\")
    .lean();
  const ids = owned.map((l) => l._id);
  const restore = () =>
    ids.length > 0
      ? m.ListingModel.updateMany(
          { _id: { $in: ids }, status: \"unpublished\" },
          { $set: { status: \"published\" } },
        )
      : null;
  if (ids.length > 0)
    await m.ListingModel.updateMany(
      { _id: { $in: ids }, status: \"published\" },
      { $set: { status: \"unpublished\" } },
    );

  try {
    // A request can have arrived between the first check and the unpublish.
    const late = await deletionBlockers(user, { now, ...over });
    if (late.length > 0) {
      await restore();
      throw new AccountRefusal(
        \"Your account cannot be deleted yet.\",
        \"blocked\",
        { blockers: late },
      );
    }
    const previousAvatar = user.avatar && user.avatar.filename;
    const done = await m.UserModel.findOneAndUpdate(
      { _id: user._id, status: \"active\" },
      anonymisedUpdate(user._id),
      { new: true },
    );
    if (!done) {
      await restore();
      throw new AccountRefusal(
        \"This account was already changed. Reload the page.\",
        \"conflict\",
      );
    }
    await Promise.all([
      m.WishlistItemModel.deleteMany({ owner: user._id }),
      m.WishlistModel.deleteMany({ owner: user._id }),
      m.SavedSearchModel.deleteMany({ owner: user._id }),
      m.NotificationModel.deleteMany({ user: user._id }),
      m.ReportModel.updateMany(
        { targetKind: \"user\", targetId: user._id },
        { $set: { targetLabel: \"Deleted user\" } },
      ),
    ]);
    if (previousAvatar)
      await Promise.resolve(m.deleteImage(previousAvatar)).catch(() => {}); // best effort: the account is already anonymised
    return { id: user._id, unpublished: ids.length };
  } catch (err) {
    if (!(err instanceof AccountRefusal))
      await Promise.resolve(restore()).catch(() => {});
    throw err;
  }
}

/**
 * Change the password after checking the current one (which also counts
 * towards the account's failed-attempt lock). The caller has already
 * validated the new password with `changePasswordSchema`.
 * @throws {AccountRefusal} wrong_password, locked
 */
async function changePassword({ user, currentPassword, newPassword }) {
  try {
    await user.changePassword(currentPassword, newPassword);
  } catch (err) {
    const refusal = refusalForLoginError(
      err,
      \"Your current password is not correct.\",
    );
    if (refusal) throw refusal;
    throw err;
  }
}

module.exports = {
  deletionBlockers,
  deleteAccount,
  changePassword,
  anonymisedUpdate,
  AccountRefusal,
};

// The only way to become an admin (P14-T01): scripts/make-admin.js calls this.
// No page, form or API sets `role`; signup and profile forms strip or refuse it.
const User = require(\"../models/user\");
const audit = require(\"./audit\");

class BootstrapError extends Error {
  constructor(message) {
    super(message);
    this.name = \"BootstrapError\";
  }
}

const ACTOR_LABEL = \"cli:make-admin\";

/**
 * Makes the active account with this email an admin and writes the audit row.
 * Running it again for an admin changes nothing and writes nothing.
 * Needs an open mongoose connection.
 * @returns {Promise<{changed: boolean, username: string}>}
 */
async function promoteToAdmin(email) {
  const address = typeof email === \"string\" ? email.trim().toLowerCase() : \"\";
  if (!User.EMAIL_PATTERN.test(address)) {
    throw new BootstrapError(\"Give the account's email address, e.g. you@example.com.\");
  }

  const user = await User.findOne({ email: address });
  if (!user) throw new BootstrapError(\"No account has that email address.\");
  if (user.status && user.status !== \"active\") {
    throw new BootstrapError(`That account is ${user.status}; only an active account can become an admin.`);
  }
  if (user.role === \"admin\") return { changed: false, username: user.username };

  const res = await User.updateOne(
    { _id: user._id, role: { $ne: \"admin\" }, status: { $in: [\"active\", null] } },
    { $set: { role: \"admin\" } },
  );
  if (res.modifiedCount !== 1) {
    // Changed by someone else between the read and the write.
    return { changed: false, username: user.username };
  }

  await audit.record({
    actorLabel: ACTOR_LABEL,
    action: \"user.make_admin\",
    targetType: \"user\",
    targetId: user._id,
    details: { username: user.username, previousRole: user.role || \"member\" },
  });
  return { changed: true, username: user.username };
}

module.exports = { promoteToAdmin, BootstrapError, ACTOR_LABEL };

// Platform summary for the admin landing page (P14-T05): real counts, read
// straight from the database on each visit. Read-only; writes nothing.
const User = require(\"../models/user\");
const Listing = require(\"../models/listing\");
const Reservation = require(\"../models/reservation\");
const Report = require(\"../models/report\");
const { STATUSES: RESERVATION_STATUSES } = require(\"./stateMachine\");

/** { status: count } for every value in `all`, zero when there are none. */
async function countBy(Model, field, all, match = {}) {
  const rows = await Model.aggregate([
    { $match: match },
    { $group: { _id: `$${field}`, count: { $sum: 1 } } },
  ]);
  const found = new Map(rows.map((r) => [r._id, r.count]));
  const out = {};
  for (const value of all) out[value] = found.get(value) || 0;
  return out;
}

const sum = (counts) => Object.values(counts).reduce((n, c) => n + c, 0);

/**
 * @returns {Promise<{
 *   users: {byStatus: object, total: number, admins: number},
 *   listings: {byStatus: object, total: number},
 *   reservations: {byStatus: object, total: number},
 *   openReports: number
 * }>}
 */
async function platformSummary() {
  const [userStatus, admins, listingStatus, reservationStatus, openReports] = await Promise.all([
    countBy(User, \"status\", User.STATUSES),
    User.countDocuments({ role: \"admin\", status: \"active\" }),
    // A listing a host deleted (deletedAt set) is not counted.
    countBy(Listing, \"status\", Listing.STATUSES, { deletedAt: null }),
    countBy(Reservation, \"status\", RESERVATION_STATUSES),
    Report.countDocuments({ status: \"open\" }),
  ]);
  return {
    users: { byStatus: userStatus, total: sum(userStatus), admins },
    listings: { byStatus: listingStatus, total: sum(listingStatus) },
    reservations: { byStatus: reservationStatus, total: sum(reservationStatus) },
    openReports,
  };
}

module.exports = { platformSummary };

// Search within a distance of a destination (P06-T05).
//
// \"Goa within 25 km\" means: stays within 25 km of the middle of the stays that
// match \"Goa\" (the same text match as the destination box), so nearby towns with
// another city name are included. The middle is the average of the matching
// stays' PUBLIC points, taken from our own data: no outside geocoding call per
// search (that would cost money for every visitor and Mapbox's temporary mode
// does not allow keeping its results).
//
// Privacy: only `publicGeometry` (the approximate point of P06-T02, 300 to 800 m
// from the real one) is ever read, so which side of the circle a stay falls on
// can be wrong by that much; the circle is therefore never smaller than 5 km.
// The precise `geometry` is not touched.
const { buildFilter } = require(\"./search\");

const RADII_KM = Object.freeze([5, 10, 25, 50]);
const EARTH_RADIUS_KM = 6378.1; // $centerSphere takes radians

/**
 * The middle of the public stays that match a destination text.
 * @param {object} Listing the model
 * @param {string} destination the validated destination text
 * @returns {Promise<{ lng: number, lat: number, count: number } | null>}
 */
async function areaCentre(Listing, destination) {
  const match = { ...buildFilter({ destination }), \"publicGeometry.type\": \"Point\" };
  const rows = await Listing.aggregate([
    { $match: match },
    {
      $group: {
        _id: null,
        lng: { $avg: { $arrayElemAt: [\"$publicGeometry.coordinates\", 0] } },
        lat: { $avg: { $arrayElemAt: [\"$publicGeometry.coordinates\", 1] } },
        count: { $sum: 1 },
      },
    },
  ]);
  const row = Array.isArray(rows) ? rows[0] : null;
  if (!row || !Number.isFinite(row.lng) || !Number.isFinite(row.lat)) return null;
  return { lng: row.lng, lat: row.lat, count: row.count };
}

/** The Mongo condition: public point inside the circle (centre as [lng, lat]). */
function areaCondition(centre, km) {
  return {
    publicGeometry: {
      $geoWithin: { $centerSphere: [[centre.lng, centre.lat], km / EARTH_RADIUS_KM] },
    },
  };
}

module.exports = { areaCentre, areaCondition, RADII_KM, EARTH_RADIUS_KM };

// Audit service (P14-T01). Every administrative action writes exactly one row
// through record(), in the same request as the action (see
// src/middleware/admin.js `auditedMutation`, which enforces that). The viewer
// reads through listAudit(); nothing here updates or deletes a row.
const AuditLog = require(\"../models/auditLog\");
const User = require(\"../models/user\");
const { tryParseDateOnly, formatDateOnly, addDays } = require(\"../utils/dates\");

const { TARGET_TYPES } = AuditLog;

const PAGE_SIZE = 25;

// Details are small facts about a change (old/new status...). Anything that
// looks like a credential is refused so a careless caller cannot leak one into
// a log that admins read.
const SECRET_KEY = /pass(word)?|token|secret|hash|salt|cookie|authorization/i;

function assertSafeDetails(details, path = \"details\") {
  if (details === undefined || details === null) return;
  if (Array.isArray(details)) {
    details.forEach((item, i) => assertSafeDetails(item, `${path}[${i}]`));
    return;
  }
  if (typeof details === \"object\") {
    for (const [key, value] of Object.entries(details)) {
      if (SECRET_KEY.test(key)) {
        throw new Error(`audit.record: ${path}.${key} must not be logged`);
      }
      assertSafeDetails(value, `${path}.${key}`);
    }
  }
}

/**
 * Writes one audit row and counts it on the request (`req.auditRecorded`), so
 * the auditedMutation wrapper can check it.
 *
 * @param {object} entry
 * @param {object} [entry.actor] the admin user (default: req.user)
 * @param {string} [entry.actorLabel] who acted when there is no logged-in admin
 * @param {string} entry.action e.g. \"user.suspend\" (lower-case, dot separated)
 * @param {string} entry.targetType user | listing | review | report | reservation | system
 * @param {*} [entry.targetId]
 * @param {string} [entry.reason]
 * @param {object} [entry.details]
 * @param {object} [entry.req] the Express request (request id, default actor)
 * @param {object} [options] { session } for a MongoDB transaction
 */
async function record(entry, options = {}) {
  const { req, reason, details } = entry;
  const actor = entry.actor || (req && req.user) || null;
  const actorLabel = entry.actorLabel;
  if (!actor && !actorLabel) {
    throw new Error(\"audit.record: an actor or an actorLabel is required\");
  }
  assertSafeDetails(details);

  const doc = {
    actor: actor ? actor._id || actor : null,
    actorLabel: actorLabel || undefined,
    action: entry.action,
    targetType: entry.targetType,
    targetId: entry.targetId ?? null,
    reason: typeof reason === \"string\" && reason.trim() ? reason : undefined,
    details: details ?? undefined,
    requestId: req && req.id ? String(req.id) : undefined,
  };

  const [row] = await AuditLog.create([doc], options.session ? { session: options.session } : {});
  if (req) req.auditRecorded = (req.auditRecorded || 0) + 1;
  return row;
}

/** A positive whole page number, else 1 (never throws, never reaches the query). */
function toPageNumber(value) {
  if (typeof value !== \"string\" || !/^[0-9]{1,6}$/.test(value)) return 1;
  const n = Number(value);
  return n >= 1 ? n : 1;
}

const FILTER_MAX = 80;
const ACTION_PREFIX = /^[a-z][a-z0-9_.]*$/;
const escapeRegex = (text) => text.replace(/[.*+?^${}()|[\\]\\\\]/g, \"\\\\$&\");

/**
 * The log's filters, cleaned. Text is matched as plain text; a date that is not
 * a real YYYY-MM-DD is ignored. `to` is inclusive (the whole day, UTC).
 */
function cleanFilters({ action, actor, targetType, from, to } = {}) {
  const str = (v) => (typeof v === \"string\" ? v.trim().slice(0, FILTER_MAX) : \"\");
  const fromDate = tryParseDateOnly(str(from));
  const toDate = tryParseDateOnly(str(to));
  const act = str(action).toLowerCase();
  return {
    action: ACTION_PREFIX.test(act) ? act : \"\",
    actor: str(actor),
    targetType: TARGET_TYPES.includes(str(targetType)) ? str(targetType) : \"\",
    from: fromDate ? formatDateOnly(fromDate) : \"\",
    to: toDate ? formatDateOnly(toDate) : \"\",
    fromDate,
    toDate,
  };
}

/**
 * One page of the log, newest first, for the read-only viewer, optionally
 * filtered by action (exact name or a prefix such as \"user.\"), actor username,
 * target type and a UTC date range.
 * @returns {{rows: object[], page: number, totalPages: number, total: number, pageSize: number, filters: object}}
 */
async function listAudit({ page, ...rawFilters } = {}) {
  const f = cleanFilters(rawFilters);
  const filter = {};
  if (f.action) filter.action = new RegExp(`^${escapeRegex(f.action)}`);
  if (f.targetType) filter.targetType = f.targetType;
  if (f.actor) {
    const rx = new RegExp(`^${escapeRegex(f.actor)}$`, \"i\");
    const users = await User.find({ username: rx }).select(\"_id\").limit(5).lean();
    // Rows written outside a login are labelled instead (see audit.record).
    filter.$or = [{ actor: { $in: users.map((u) => u._id) } }, { actorLabel: rx }];
  }
  if (f.fromDate || f.toDate) {
    filter.createdAt = {};
    if (f.fromDate) filter.createdAt.$gte = f.fromDate;
    if (f.toDate) filter.createdAt.$lt = addDays(f.toDate, 1);
  }

  const total = await AuditLog.countDocuments(filter);
  const totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE));
  const current = Math.min(toPageNumber(page), totalPages);
  const rows = await AuditLog.find(filter)
    .sort({ createdAt: -1, _id: -1 })
    .skip((current - 1) * PAGE_SIZE)
    .limit(PAGE_SIZE)
    .populate(\"actor\", \"username displayName\")
    .lean();
  const { fromDate, toDate, ...shown } = f;
  return { rows, page: current, totalPages, total, pageSize: PAGE_SIZE, filters: shown };
}

module.exports = { record, listAudit, cleanFilters, toPageNumber, PAGE_SIZE };

// Host availability calendar (P07-T03).
//
//   monthView(listing, monthValue, { now })   the month grid, as plain data
//   listBlocks(listing, { now })              the host's upcoming blocked runs
//   blockDates(listing, input, { now, userId })
//   unblockDates(listing, input, { now })
//
// The night ledger (ADR-004) is the only source of truth for what is taken:
// a reserved night, a pending request's live hold and a host block are all
// rows in it. A block is made with `reserveNights(..., { kind: \"block\" })`, so
// the unique (listing, date) index refuses a night a guest already holds, even
// when the guest books at the same moment. Unblocking releases only rows whose
// source kind is \"block\". The optional note lives in an AvailabilityBlock
// record whose _id is the ledger source id.
//
// Dates are strict YYYY-MM-DD strings parsed by src/utils/dates.js (ADR-003);
// \"today\" is the listing's own time zone's calendar date.
const mongoose = require(\"mongoose\");
const ledgerService = require(\"./ledger\");
const AvailabilityBlockModel = require(\"../models/availabilityBlock\");
const { ConflictError, ValidationError } = require(\"../utils/errors\");
const {
  BOOKING_WINDOW,
  DEFAULT_TIMEZONE,
  addDays,
  addMonths,
  daysInMonth,
  eachNight,
  formatDateOnly,
  formatMonthKey,
  isoWeekday,
  isBefore,
  isAfter,
  nightsBetween,
  parseMonthKey,
  startOfMonth,
  todayIn,
  tryParseDateOnly,
} = require(\"../utils/dates\");

const NOTE_MAX_LENGTH = 200;
const MONTHS_BACK = 12; // how far back the host may look
const MAX_RUNS_LISTED = 100;
const LIST_SPAN_DAYS = 400; // the ledger's longest range
const PLURAL = (n, one, many) => `${n} ${n === 1 ? one : many}`;

// Fixed English names rather than Intl: the text must not change with the
// server's ICU version, and a date-only value has no time zone to apply.
const MONTH_NAMES = Object.freeze([
  \"January\",
  \"February\",
  \"March\",
  \"April\",
  \"May\",
  \"June\",
  \"July\",
  \"August\",
  \"September\",
  \"October\",
  \"November\",
  \"December\",
]);
const monthLabel = (date) =>
  `${MONTH_NAMES[date.getUTCMonth()]} ${date.getUTCFullYear()}`;
/** \"5 Nov 2026\" */
const shortDay = (date) =>
  `${date.getUTCDate()} ${MONTH_NAMES[date.getUTCMonth()].slice(0, 3)} ${date.getUTCFullYear()}`;
/** \"Tuesday 3 November 2026\" */
const fullDay = (date) =>
  `${WEEKDAYS[isoWeekday(date)].long} ${date.getUTCDate()} ${MONTH_NAMES[date.getUTCMonth()]} ${date.getUTCFullYear()}`;

// Monday first. `long` is for assistive technology (abbr attribute).
const WEEKDAYS = Object.freeze([
  { short: \"Mon\", long: \"Monday\" },
  { short: \"Tue\", long: \"Tuesday\" },
  { short: \"Wed\", long: \"Wednesday\" },
  { short: \"Thu\", long: \"Thursday\" },
  { short: \"Fri\", long: \"Friday\" },
  { short: \"Sat\", long: \"Saturday\" },
  { short: \"Sun\", long: \"Sunday\" },
]);

const STATE_LABELS = Object.freeze({
  free: \"\",
  blocked: \"Blocked\",
  reserved: \"Reserved\",
  requested: \"Request\",
});
const STATE_WORDS = Object.freeze({
  free: \"available\",
  blocked: \"blocked by you\",
  reserved: \"reserved by a guest\",
  requested: \"held for a guest request awaiting your answer\",
});

/** Free text from a form: one line, no control characters, trimmed. */
function cleanNote(value) {
  if (value === undefined || value === null) return \"\";
  if (typeof value !== \"string\") {
    throw new ValidationError(\"The note must be text.\");
  }
  // eslint-disable-next-line no-control-regex
  const note = value.replace(/[\\u0000-\\u001f\\u007f]+/g, \" \").replace(/\\s+/g, \" \");
  const trimmed = note.trim();
  if (trimmed.length > NOTE_MAX_LENGTH) {
    throw new ValidationError(
      `The note can be at most ${NOTE_MAX_LENGTH} characters.`,
    );
  }
  return trimmed;
}

/**
 * The block / unblock form: first night, last night (both included) and an
 * optional note. Nights already in the past cannot be changed, and nothing
 * beyond the booking horizon can be blocked. Throws ValidationError (400)
 * with a message the host can act on.
 * @returns {{from: Date, through: Date, to: Date, nights: number, note: string}}
 */
function parseRange(input, { today, withNote = false }) {
  const body = input && typeof input === \"object\" ? input : {};
  const from = tryParseDateOnly(body.from);
  if (!from) {
    throw new ValidationError(\"Enter the first night as a valid date.\");
  }
  const through = tryParseDateOnly(body.through);
  if (!through) {
    throw new ValidationError(\"Enter the last night as a valid date.\");
  }
  if (isBefore(through, from)) {
    throw new ValidationError(
      \"The last night cannot be before the first night.\",
    );
  }
  if (isBefore(from, today)) {
    throw new ValidationError(
      \"Nights that have already passed cannot be changed.\",
    );
  }
  const latest = addDays(today, BOOKING_WINDOW.MAX_HORIZON_DAYS);
  if (isAfter(through, latest)) {
    throw new ValidationError(
      `You can change availability up to a year ahead (until ${formatDateOnly(latest)}).`,
    );
  }
  const to = addDays(through, 1);
  const nights = nightsBetween(from, to); // at most horizon + 1 (checked above)
  return {
    from,
    through,
    to,
    nights,
    note: withNote ? cleanNote(body.note) : \"\",
  };
}

const listDates = (dates) => dates.map(shortDay).join(\", \");

/**
 * @param {object} [deps] replaceable in unit tests
 */
function createAvailabilityService({
  ledger = ledgerService,
  blockModel = AvailabilityBlockModel,
  newId = () => new mongoose.Types.ObjectId(),
} = {}) {
  const todayFor = (listing, now) =>
    todayIn(listing.timezone || DEFAULT_TIMEZONE, now);

  /** The months the host may open: a year back to the end of the horizon. */
  function monthBounds(today) {
    return {
      min: addMonths(today, -MONTHS_BACK),
      max: startOfMonth(addDays(today, BOOKING_WINDOW.MAX_HORIZON_DAYS)),
    };
  }

  /** First day of the month to show: the one asked for, else this month, kept in bounds. */
  function resolveMonth(value, today) {
    const { min, max } = monthBounds(today);
    let month = parseMonthKey(value) || startOfMonth(today);
    if (isBefore(month, min)) month = min;
    if (isAfter(month, max)) month = max;
    return month;
  }

  /** The month grid for one listing as plain data (nothing about guests). */
  async function monthView(listing, monthValue, { now = new Date() } = {}) {
    const today = todayFor(listing, now);
    const { min, max } = monthBounds(today);
    const month = resolveMonth(monthValue, today);
    const next = addMonths(month, 1);
    const rows = await ledger.nightsInRange(listing._id, month, next, { now });
    const byDate = new Map(rows.map((row) => [row.date.getTime(), row]));

    const counts = { blocked: 0, reserved: 0, requested: 0 };
    const cells = [];
    for (let i = 0; i < isoWeekday(month); i += 1) cells.push(null);
    for (let i = 0; i < daysInMonth(month); i += 1) {
      const date = addDays(month, i);
      const row = byDate.get(date.getTime());
      let state = \"free\";
      if (row) {
        if (row.source.kind === \"block\") state = \"blocked\";
        else state = row.holdExpiresAt ? \"requested\" : \"reserved\";
        counts[state] += 1;
      }
      const isToday = date.getTime() === today.getTime();
      const past = isBefore(date, today);
      cells.push({
        day: date.getUTCDate(),
        iso: formatDateOnly(date),
        state,
        stateLabel: STATE_LABELS[state],
        past,
        today: isToday,
        srLabel: `${fullDay(date)}: ${STATE_WORDS[state]}${isToday ? \", today\" : \"\"}`,
      });
    }
    while (cells.length % 7 !== 0) cells.push(null);
    const weeks = [];
    for (let i = 0; i < cells.length; i += 7) weeks.push(cells.slice(i, i + 7));

    return {
      monthKey: formatMonthKey(month),
      label: monthLabel(month),
      prevKey: isAfter(month, min) ? formatMonthKey(addMonths(month, -1)) : null,
      nextKey: isBefore(month, max) ? formatMonthKey(addMonths(month, 1)) : null,
      weekdays: WEEKDAYS,
      weeks,
      counts,
      todayIso: formatDateOnly(today),
      latestIso: formatDateOnly(addDays(today, BOOKING_WINDOW.MAX_HORIZON_DAYS)),
    };
  }

  /**
   * Upcoming blocked stretches (from today on), each a run of consecutive
   * nights of one block, soonest first, with the block's note.
   */
  async function listBlocks(listing, { now = new Date() } = {}) {
    const today = todayFor(listing, now);
    const rows = (
      await ledger.nightsInRange(
        listing._id,
        today,
        addDays(today, LIST_SPAN_DAYS),
        { now },
      )
    ).filter((row) => row.source.kind === \"block\");

    const open = new Map(); // source id -> the run still being extended
    const runs = [];
    for (const row of rows) {
      const key = String(row.source.id);
      const run = open.get(key);
      if (run && run.to.getTime() === row.date.getTime()) {
        run.to = addDays(row.date, 1);
        run.nights += 1;
      } else {
        const fresh = {
          sourceId: row.source.id,
          from: row.date,
          to: addDays(row.date, 1),
          nights: 1,
        };
        open.set(key, fresh);
        runs.push(fresh);
      }
    }
    runs.sort((a, b) => a.from.getTime() - b.from.getTime());
    const shown = runs.slice(0, MAX_RUNS_LISTED);

    const ids = [...new Set(shown.map((run) => String(run.sourceId)))];
    const records = ids.length
      ? await blockModel
          .find({ _id: { $in: shown.map((r) => r.sourceId) }, listing: listing._id })
          .lean()
      : [];
    const notes = new Map(records.map((r) => [String(r._id), r.note || \"\"]));

    return {
      truncated: runs.length > shown.length,
      runs: shown.map((run) => {
        const through = addDays(run.to, -1);
        return {
          nights: run.nights,
          nightsLabel: PLURAL(run.nights, \"night\", \"nights\"),
          fromIso: formatDateOnly(run.from),
          throughIso: formatDateOnly(through),
          fromLabel: shortDay(run.from),
          throughLabel: shortDay(through),
          note: notes.get(String(run.sourceId)) || \"\",
        };
      }),
    };
  }

  /**
   * Blocks the nights from `input.from` to `input.through` (both included).
   * Nights the host already blocked are skipped; a night a guest holds makes
   * the whole request fail (nothing is blocked).
   * @throws {ValidationError} bad dates or note (400)
   * @throws {ConflictError}   a guest holds some of the nights (409)
   * @returns {Promise<{changed: boolean, blocked: number, alreadyBlocked: number, from: Date}>}
   */
  async function blockDates(listing, input, { now = new Date(), userId } = {}) {
    const today = todayFor(listing, now);
    const range = parseRange(input, { today, withNote: true });
    const nights = eachNight(range.from, range.to, {
      maxNights: BOOKING_WINDOW.MAX_HORIZON_DAYS + 1,
    });

    const rows = await ledger.nightsInRange(listing._id, range.from, range.to, {
      now,
    });
    const heldByGuests = rows.filter((row) => row.source.kind !== \"block\");
    if (heldByGuests.length > 0) {
      const err = new ConflictError(
        `Guests already hold these nights, so they cannot be blocked: ${listDates(heldByGuests.map((r) => r.date))}. Nothing was blocked.`,
        { code: \"nights_reserved\" },
      );
      err.conflictingDates = heldByGuests.map((r) => r.date);
      throw err;
    }
    const alreadyBlocked = new Set(rows.map((row) => row.date.getTime()));
    const free = nights.filter((night) => !alreadyBlocked.has(night.getTime()));
    if (free.length === 0) {
      return {
        changed: false,
        blocked: 0,
        alreadyBlocked: nights.length,
        from: range.from,
      };
    }

    const blockId = newId();
    try {
      await ledger.reserveNights(
        listing._id,
        free,
        { kind: \"block\", id: blockId },
        null,
        { now },
      );
    } catch (err) {
      if (err instanceof ConflictError && err.code === \"nights_unavailable\") {
        const taken = err.conflictingDates || [];
        throw new ConflictError(
          taken.length
            ? `A guest just took these nights: ${listDates(taken)}. Nothing was blocked.`
            : \"A guest just took some of those nights. Nothing was blocked.\",
          { code: \"nights_reserved\" },
        );
      }
      throw err;
    }

    try {
      await blockModel.create({
        _id: blockId,
        listing: listing._id,
        from: range.from,
        to: range.to,
        note: range.note,
        createdBy: userId,
      });
    } catch (err) {
      await ledger.releaseNights(blockId); // no night without its record
      throw err;
    }
    return {
      changed: true,
      blocked: free.length,
      alreadyBlocked: nights.length - free.length,
      from: range.from,
    };
  }

  /**
   * Frees the blocked nights between `input.from` and `input.through` (both
   * included). Reserved nights and guest holds are never touched.
   * @returns {Promise<{released: number, from: Date}>}
   */
  async function unblockDates(listing, input, { now = new Date() } = {}) {
    const today = todayFor(listing, now);
    const range = parseRange(input, { today });
    const { released, emptiedSourceIds } = await ledger.releaseBlockedNights(
      listing._id,
      range.from,
      range.to,
    );
    if (emptiedSourceIds.length > 0) {
      await blockModel.deleteMany({
        _id: { $in: emptiedSourceIds },
        listing: listing._id,
      });
    }
    return { released, from: range.from };
  }

  return {
    monthView,
    listBlocks,
    blockDates,
    unblockDates,
    resolveMonth,
  };
}

module.exports = {
  ...createAvailabilityService(),
  createAvailabilityService,
  parseRange,
  cleanNote,
  NOTE_MAX_LENGTH,
};

// Public availability of one listing (P07-T04): which nights a guest cannot
// book, plus the stay rules the date picker enforces. Dates only: never who
// holds a night or why (a reservation, a pending request and a host block look
// the same), so the answer is safe to show to anybody.
//
// This file was services/availability.js until P07-T03 (the host calendar)
// took that name; the stay rules themselves live in services/bookingRules.js.
//
//   parseAvailabilityQuery(query, { today }) -> { from, to }   (400 on bad input)
//   getAvailability(listing, query, deps)    -> JSON-ready payload
const ledger = require(\"./ledger\");
const { stayRulesFor } = require(\"./bookingRules\");
const {
  BOOKING_WINDOW,
  DEFAULT_TIMEZONE,
  tryParseDateOnly,
  formatDateOnly,
  addDays,
  isBefore,
  isAfter,
  todayIn,
} = require(\"../utils/dates\");
const { ValidationError } = require(\"../utils/errors\");

// Same cap as the ledger's own range limit.
const MAX_RANGE_NIGHTS = 400;

function readDate(query, name) {
  const raw = query ? query[name] : undefined;
  if (raw === undefined || raw === \"\") {
    throw new ValidationError(`\"${name}\" is required (YYYY-MM-DD).`);
  }
  // A repeated parameter (?from=a&from=b) or from[x]=y is not a string.
  const date = typeof raw === \"string\" ? tryParseDateOnly(raw) : null;
  if (!date) {
    throw new ValidationError(
      `\"${name}\" must be a valid date in YYYY-MM-DD format.`,
    );
  }
  return date;
}

/**
 * `from` is included, `to` is not (the same convention as a check-in/check-out
 * pair). Both are required real calendar dates, `to` after `from`, at most
 * 400 nights apart.
 */
function parseAvailabilityQuery(query) {
  const from = readDate(query, \"from\");
  const to = readDate(query, \"to\");
  if (!isAfter(to, from)) {
    throw new ValidationError('\"to\" must be after \"from\".');
  }
  if ((to.getTime() - from.getTime()) / 86400000 > MAX_RANGE_NIGHTS) {
    throw new ValidationError(
      `The range can cover at most ${MAX_RANGE_NIGHTS} nights.`,
    );
  }
  return { from, to };
}

/**
 * @param {object} listing  needs minNights and maxNights
 * @param {object} query    req.query (strings only are accepted)
 * @param {object} [deps]
 */
async function getAvailability(
  listing,
  query,
  {
    now = new Date(),
    ledgerService = ledger,
    timeZone = DEFAULT_TIMEZONE,
  } = {},
) {
  const { from, to } = parseAvailabilityQuery(query);
  const today = todayIn(timeZone, now);
  const rules = stayRulesFor(listing, { today });

  // Nights before today are not bookable anyway and nights beyond the last
  // possible stay are not worth a query: ask only for what can matter.
  const lastNight = addDays(
    tryParseDateOnly(rules.latestCheckIn),
    BOOKING_WINDOW.MAX_STAY_NIGHTS,
  );
  const askFrom = isBefore(from, today) ? today : from;
  const askTo = isAfter(to, lastNight) ? lastNight : to;

  let unavailable = [];
  if (isBefore(askFrom, askTo)) {
    unavailable = await ledgerService.unavailableDates(
      listing._id,
      askFrom,
      askTo,
      { now },
    );
  }
  return {
    from: formatDateOnly(from),
    to: formatDateOnly(to),
    unavailable: unavailable.map(formatDateOnly),
    rules,
  };
}

module.exports = {
  MAX_RANGE_NIGHTS,
  parseAvailabilityQuery,
  getAvailability,
};

// Booking rules (P07-T06): the one place that decides whether a stay may be
// booked. The reservation service (create), the availability API and the date
// picker all read their rules from here, so a rule is written once.
//
//   stayRulesFor(listing, { today })         the rules as plain data (for the picker and the API)
//   stayProblems({ checkIn, checkOut, rules, unavailable })
//                                             the date and stay-length rules only (messages)
//   bookingProblems({ listing, checkIn, checkOut, guests, now, unavailable })
//                                             every rule -> [{ code, message }], empty when acceptable
//
// Rules, each with its own message and code:
//   check_out_not_after_check_in, check_in_past, check_in_too_far (horizon),
//   below_min_nights, above_max_nights, over_capacity,
//   advance_notice (host-set hours before check-in), same_day_cutoff.
//
// Dates are date-only Dates (ADR-003). \"Now\" and \"today\" are read on the
// listing's own clock (its time zone), never the server's. A rule that needs
// the time of day compares wall-clock times in that zone, so it is not moved
// by the server's zone.
const {
  BOOKING_WINDOW,
  DEFAULT_TIMEZONE,
  bookingWindow,
  formatDateOnly,
  isAfter,
  isBefore,
  isSameDate,
  tryParseDateOnly,
  wallClockIn,
} = require(\"../utils/dates\");

const RULE_DEFAULTS = Object.freeze({
  ADVANCE_NOTICE_HOURS: 0, // no notice needed
  MAX_ADVANCE_NOTICE_HOURS: 168, // a host can ask for up to 7 days
  SAME_DAY_CUTOFF: \"20:00\", // a stay starting today must be booked before this
  CHECK_IN_TIME: \"14:00\",
});

const TIME = /^([01]\\d|2[0-3]):([0-5]\\d)$/;
const MS_PER_DAY = 24 * 60 * 60 * 1000;

/** \"HH:MM\" -> minutes since midnight, or null when it is not a valid time. */
function timeToMinutes(text) {
  const match = typeof text === \"string\" ? TIME.exec(text) : null;
  return match ? Number(match[1]) * 60 + Number(match[2]) : null;
}

function noticeHoursOf(listing) {
  const hours = listing && listing.advanceNoticeHours;
  return Number.isInteger(hours) &&
    hours >= 0 &&
    hours <= RULE_DEFAULTS.MAX_ADVANCE_NOTICE_HOURS
    ? hours
    : RULE_DEFAULTS.ADVANCE_NOTICE_HOURS;
}

function cutoffOf(listing) {
  const text = listing && listing.sameDayCutoffTime;
  return timeToMinutes(text) === null ? RULE_DEFAULTS.SAME_DAY_CUTOFF : text;
}

function checkInTimeOf(listing) {
  const text = listing && listing.checkInTime;
  return timeToMinutes(text) === null ? RULE_DEFAULTS.CHECK_IN_TIME : text;
}

const plural = (n, one, many) => `${n} ${n === 1 ? one : many}`;

/** 24 -> \"1 day\", 48 -> \"2 days\", 36 -> \"36 hours\", 1 -> \"1 hour\" */
function noticeLabel(hours) {
  return hours % 24 === 0
    ? plural(hours / 24, \"day\", \"days\")
    : plural(hours, \"hour\", \"hours\");
}

/** What the picker and the API show, and what the server enforces. */
function stayRulesFor(listing, { today }) {
  const { earliestCheckIn, latestCheckIn } = bookingWindow(today);
  const hostMin = Number.isInteger(listing && listing.minNights)
    ? listing.minNights
    : 1;
  const hostMax = Number.isInteger(listing && listing.maxNights)
    ? listing.maxNights
    : BOOKING_WINDOW.MAX_STAY_NIGHTS;
  const maxNights = Math.min(hostMax, BOOKING_WINDOW.MAX_STAY_NIGHTS);
  const minNights = Math.min(Math.max(hostMin, 1), maxNights);
  const guestCapacity = listing && listing.capacity && listing.capacity.guests;
  return {
    today: formatDateOnly(today),
    earliestCheckIn: formatDateOnly(earliestCheckIn),
    latestCheckIn: formatDateOnly(latestCheckIn),
    minNights,
    maxNights,
    // How many people the place sleeps (named so the public API output never
    // contains the word \"guest\": a test guards against leaking guest data).
    capacity: Number.isInteger(guestCapacity) ? guestCapacity : null,
    advanceNoticeHours: noticeHoursOf(listing),
    sameDayCutoffTime: cutoffOf(listing),
  };
}

const rule = (code, message) => ({ code, message });

// Date and stay-length rules, from the `rules` data alone.
function stayRuleProblems({ checkIn, checkOut, rules, unavailable = [] }) {
  if (!isAfter(checkOut, checkIn)) {
    return [
      rule(\"check_out_not_after_check_in\", \"Check-out must be after check-in.\"),
    ];
  }
  const problems = [];
  const nights = Math.round(
    (checkOut.getTime() - checkIn.getTime()) / MS_PER_DAY,
  );
  const today = tryParseDateOnly(rules.today);
  const latest = tryParseDateOnly(rules.latestCheckIn);
  if (isBefore(checkIn, today)) {
    problems.push(rule(\"check_in_past\", \"Check-in cannot be in the past.\"));
  }
  if (isAfter(checkIn, latest)) {
    problems.push(
      rule(
        \"check_in_too_far\",
        `Check-in can be at most ${BOOKING_WINDOW.MAX_HORIZON_DAYS} days ahead.`,
      ),
    );
  }
  if (nights < rules.minNights) {
    problems.push(
      rule(
        \"below_min_nights\",
        `The minimum stay is ${plural(rules.minNights, \"night\", \"nights\")}.`,
      ),
    );
  }
  if (nights > rules.maxNights) {
    problems.push(
      rule(
        \"above_max_nights\",
        `The maximum stay is ${plural(rules.maxNights, \"night\", \"nights\")}.`,
      ),
    );
  }
  const taken = unavailable
    .filter((d) => !isBefore(d, checkIn) && isBefore(d, checkOut))
    .map(formatDateOnly);
  if (taken.length) {
    problems.push(
      rule(
        \"nights_unavailable\",
        `These nights are not available: ${taken.join(\", \")}.`,
      ),
    );
  }
  return problems;
}

/**
 * Date and stay-length problems as messages (the picker's contract since
 * P07-T04). Empty when the stay is acceptable.
 */
function stayProblems(input) {
  return stayRuleProblems(input).map((p) => p.message);
}

/**
 * Wall-clock minutes from `now` until the check-in moment (check-in date plus
 * the listing's check-in time), both read in the listing's time zone.
 * Negative when check-in time has already passed.
 */
function minutesUntilCheckIn({ listing, checkIn, now }) {
  const clock = wallClockIn(
    (listing && listing.timezone) || DEFAULT_TIMEZONE,
    now,
  );
  const dayDiff = Math.round(
    (checkIn.getTime() - clock.date.getTime()) / MS_PER_DAY,
  );
  return (
    dayDiff * 24 * 60 + timeToMinutes(checkInTimeOf(listing)) - clock.minutes
  );
}

/**
 * Every booking rule for one request. `unavailable` (optional) is an array of
 * date-only Dates; the ledger, not this module, is what really refuses a taken
 * night.
 * @returns {{code: string, message: string}[]} in the order a guest should fix them
 */
function bookingProblems({
  listing,
  checkIn,
  checkOut,
  guests,
  now = new Date(),
  unavailable = [],
}) {
  const zone = (listing && listing.timezone) || DEFAULT_TIMEZONE;
  const clock = wallClockIn(zone, now);
  const rules = stayRulesFor(listing, { today: clock.date });
  const problems = stayRuleProblems({ checkIn, checkOut, rules, unavailable });
  if (problems.some((p) => p.code === \"check_out_not_after_check_in\"))
    return problems;

  if (
    Number.isInteger(guests) &&
    rules.capacity !== null &&
    guests > rules.capacity
  ) {
    problems.push(
      rule(
        \"over_capacity\",
        `This place hosts at most ${plural(rules.capacity, \"guest\", \"guests\")}.`,
      ),
    );
  }

  // Timing rules only matter for a check-in that is not already refused for
  // being in the past or beyond the horizon.
  const inWindow = !problems.some(
    (p) => p.code === \"check_in_past\" || p.code === \"check_in_too_far\",
  );
  if (inWindow) {
    let noticeFailed = false;
    if (rules.advanceNoticeHours > 0) {
      const needed = rules.advanceNoticeHours * 60;
      if (minutesUntilCheckIn({ listing, checkIn, now }) < needed) {
        noticeFailed = true;
        problems.push(
          rule(
            \"advance_notice\",
            `This host needs at least ${noticeLabel(rules.advanceNoticeHours)} notice before check-in. Choose a later check-in date.`,
          ),
        );
      }
    }
    // A same-day stay: refuse once the place's clock has reached the cut-off.
    // (An advance-notice failure already says the date is too soon.)
    if (!noticeFailed && isSameDate(checkIn, clock.date)) {
      if (clock.minutes >= timeToMinutes(rules.sameDayCutoffTime)) {
        problems.push(
          rule(
            \"same_day_cutoff\",
            `Bookings for today close at ${rules.sameDayCutoffTime} (the place's local time). Choose a later check-in date.`,
          ),
        );
      }
    }
  }
  return problems;
}

module.exports = {
  RULE_DEFAULTS,
  timeToMinutes,
  noticeLabel,
  stayRulesFor,
  stayProblems,
  bookingProblems,
  minutesUntilCheckIn,
};

// Cancelling a booking (P09-T03): the guest's and the host's cancel flows.
//
// - The guest may cancel a pending request (free) or a confirmed booking
//   (refund by the listing's policy, src/services/refunds.js).
// - The host may cancel a CONFIRMED booking (a pending request is declined, not
//   cancelled): the guest always gets everything back, a reason is required,
//   and the host's cancellation counter goes up by one.
// - Who is cancelling comes from who the person is (guest or host of THIS
//   booking), never from the form. Anybody else gets the same 404 as for a
//   booking that does not exist.
//
// The refund is worked out here and stored by the same compare-and-set that
// changes the status (reservations.transition), so a cancelled booking always
// carries its refund, and two cancellations at once leave exactly one winner.
// Nothing is paid back: payments are simulated (P16 acts on the record).
const { can } = require(\"../policies\");
const { sameId } = require(\"../policies/shared\");
const { refundForCancellation } = require(\"./refunds\");
const { parseReason } = require(\"../utils/reason\");
const { todayIn, DEFAULT_TIMEZONE } = require(\"../utils/dates\");
const {
  NotFoundError,
  ValidationError,
  ConflictError,
} = require(\"../utils/errors\");

const OBJECT_ID = /^[0-9a-f]{24}$/i;

const actorOf = (reservation, user) =>
  sameId(reservation.guest, user._id) ? \"guest\" : \"host\";

/**
 * Can this side cancel this booking right now? Pure.
 * guest: pending or confirmed; host: confirmed only. Never once the stay is over.
 */
function mayCancel(reservation, actor, now) {
  const allowed = actor === \"guest\" ? [\"pending\", \"confirmed\"] : [\"confirmed\"];
  if (!allowed.includes(reservation.status)) return false;
  const tz =
    (reservation.listingSnapshot && reservation.listingSnapshot.timezone) ||
    DEFAULT_TIMEZONE;
  return todayIn(tz, now).getTime() < reservation.checkOut.getTime();
}

/**
 * What the booking page shows next to the cancel button: whether the viewer
 * may cancel and what they would get back if they cancelled now. Pure.
 * @param {object} reservation
 * @param {{ actor: \"guest\"|\"host\", now: Date, formatMoney: Function, formatInstant: Function }} options
 * @returns {object|null} null when there is nothing to offer
 */
function cancelOffer(reservation, { actor, now, formatMoney, formatInstant }) {
  if (!mayCancel(reservation, actor, now)) return null;
  const refund = refundForCancellation({ reservation, actor, now });
  const currency =
    (reservation.pricingSnapshot && reservation.pricingSnapshot.currency) ||
    \"INR\";
  const snap = reservation.listingSnapshot || {};
  return {
    actor,
    refundMinor: refund.refundMinor,
    refundText: formatMoney(refund.refundMinor, currency),
    keptText: formatMoney(refund.retainedMinor, currency),
    totalText: formatMoney(refund.totalMinor, currency),
    full: refund.refundMinor === refund.totalMinor,
    ruleText: refund.ruleText,
    freeUntilText: refund.fullRefundUntil
      ? formatInstant(refund.fullRefundUntil, snap.timezone)
      : null,
    reasonRequired: actor === \"host\",
  };
}

/**
 * @param {object} deps replaceable in tests (defaults load the real models)
 * @param {{ id: string, user: object, reason?: string, now?: Date }} input
 * @returns {Promise<{ reservation: object, refund: object, actor: string }>}
 */
async function cancelBooking(
  {
    ReservationModel = require(\"../models/reservation\"),
    UserModel = require(\"../models/user\"),
    reservationService = require(\"./reservations\"),
    logger,
  } = {},
  { id, user, reason, now = new Date() },
) {
  const reservation = OBJECT_ID.test(String(id))
    ? await ReservationModel.findById(id)
    : null;
  if (!reservation || !can(\"reservation:cancel\", user, reservation)) {
    throw new NotFoundError(\"That booking does not exist.\");
  }
  const actor = actorOf(reservation, user);
  const note = parseReason(reason);
  if (actor === \"host\" && !note) {
    throw new ValidationError(\"Please tell the guest why you are cancelling.\");
  }
  if (actor === \"host\" && reservation.status === \"pending\") {
    throw new ConflictError(
      \"This request has not been accepted yet: decline it instead of cancelling it.\",
      {
        code: \"use_decline\",
      },
    );
  }
  if (!mayCancel(reservation, actor, now)) {
    throw new ConflictError(
      reservation.status === \"confirmed\" || reservation.status === \"pending\"
        ? \"This stay is already over, so it can no longer be cancelled.\"
        : \"This booking can no longer be cancelled.\",
      { code: \"not_cancellable\" },
    );
  }

  const refund = refundForCancellation({ reservation, actor, now });
  const updated = await reservationService.transition(
    reservation._id,
    actor === \"guest\" ? \"cancelled_by_guest\" : \"cancelled_by_host\",
    {
      actor,
      by: user._id,
      reason: note || undefined,
      refund,
      expectStatus: reservation.status,
      now,
    },
  );

  if (actor === \"host\") {
    // The cancellation is done and cannot be undone: a failure to count it is
    // reported, never turned into an error for the host.
    try {
      await UserModel.updateOne(
        { _id: reservation.host },
        { $inc: { hostCancellationCount: 1 } },
      );
    } catch (err) {
      if (logger)
        logger.error(
          { err, reservation: String(reservation._id) },
          \"host cancellation counter not updated\",
        );
    }
  }
  return { reservation: updated, refund, actor };
}

module.exports = { cancelBooking, cancelOffer, mayCancel };

// The checkout page's view model (P08-T03). It never prices anything itself:
// the lines and the total are exactly what services/pricing.js returned
// (through quoteService.getQuote), so the total the guest confirms is the
// total reservations.create stores (Signature #1). The only things added here
// are words for the lines and the comparison with the price the guest saw
// before (display only: it cannot change what is charged, because
// reservations.create compares the real price with `expectedTotalMinor`).
const { formatMoney } = require(\"../utils/money\");
const { parseDateOnly } = require(\"../utils/dates\");
const { CANCELLATION_POLICIES } = require(\"../config/constants\");
const { cancellationText } = require(\"../config/cancellationText\");

const plural = (n, one, many) => `${n} ${n === 1 ? one : many}`;

const dayFormat = new Intl.DateTimeFormat(\"en-IN\", {
  weekday: \"short\",
  day: \"numeric\",
  month: \"short\",
  year: \"numeric\",
  timeZone: \"UTC\",
});

/** \"2026-12-01\" -> \"Tue, 1 Dec 2026\" (date-only values are UTC midnight). */
const dayLabel = (iso) => dayFormat.format(parseDateOnly(iso));

/** The words for one breakdown line (the pricing service sends code + numbers). */
function lineLabel(line, currency) {
  switch (line.code) {
    case \"nights\":
      return `${formatMoney(line.unitMinor, currency)} × ${plural(line.quantity, \"night\", \"nights\")}`;
    case \"weekend_nights\":
      return `${formatMoney(line.unitMinor, currency)} × ${plural(line.quantity, \"weekend night\", \"weekend nights\")}`;
    case \"season_nights\":
      return `${line.label ? line.label + \": \" : \"\"}${formatMoney(line.unitMinor, currency)} × ${plural(line.quantity, \"night\", \"nights\")}`;
    case \"season_weekend_nights\":
      return `${line.label ? line.label + \": \" : \"\"}${formatMoney(line.unitMinor, currency)} × ${plural(line.quantity, \"weekend night\", \"weekend nights\")}`;
    case \"length_discount\":
      return `${line.kind === \"monthly\" ? \"Monthly\" : \"Weekly\"} stay discount (${line.rateBps / 100}%)`;
    case \"cleaning\":
      return \"Cleaning fee\";
    case \"service_fee\":
      return \"Service fee\";
    case \"tax\":
      return line.included ? \"Taxes (included in the price)\" : \"Taxes\";
    default:
      return \"Other charges\";
  }
}

// The lines of the quote the guest saw, carried in a hidden field only so the
// page can highlight what changed. Strict format \"code:amount;code:amount\";
// anything else is ignored. It is display only and never used for a price.
const PREVIOUS_LINE = /^[a-z0-9_]{1,40}:-?\\d{1,15}$/;

function encodeLines(quote) {
  return quote.lines
    .map((line) => `${line.key || line.code}:${line.amountMinor}`)
    .join(\";\");
}

function decodeLines(value) {
  const found = new Map();
  if (typeof value !== \"string\" || value.length > 400) return found;
  for (const part of value.split(\";\")) {
    if (!PREVIOUS_LINE.test(part)) continue;
    const [code, amount] = part.split(\":\");
    found.set(code, Number(amount));
  }
  return found;
}

function coverOf(listing) {
  return (
    (Array.isArray(listing.images) &&
      listing.images[0] &&
      listing.images[0].url) ||
    (listing.image && listing.image.url) ||
    \"\"
  );
}

/**
 * @param {object} listing  the listing document
 * @param {object} payload  what quoteService.getQuote returned (bookable: true)
 * @param {object} [options]
 * @param {number|null} [options.previousTotalMinor]  the total the guest confirmed before
 * @param {string} [options.previousLines]            encoded lines of that quote
 * @param {string} options.idempotencyKey
 */
function buildCheckoutView(
  listing,
  payload,
  { previousTotalMinor = null, previousLines = \"\", idempotencyKey } = {},
) {
  const { quote } = payload;
  const before = decodeLines(previousLines);
  const changed =
    previousTotalMinor !== null && previousTotalMinor !== quote.totalMinor;
  const lines = quote.lines.map((line) => ({
    code: line.code,
    label: lineLabel(line, quote.currency),
    amountMinor: line.amountMinor,
    included: Boolean(line.included),
    // A line is highlighted when it is new or its amount differs from what was shown.
    changed:
      changed && before.size > 0 && before.get(line.key || line.code) !== line.amountMinor,
  }));
  const policyValue = listing.cancellationPolicy;
  const policy = CANCELLATION_POLICIES.find((p) => p.value === policyValue);
  const houseRules =
    typeof listing.houseRules === \"string\" ? listing.houseRules.trim() : \"\";

  return {
    listing: {
      id: String(listing._id),
      title: listing.title,
      place: [listing.address && listing.address.city, listing.country]
        .filter(Boolean)
        .join(\", \"),
      coverUrl: coverOf(listing),
      checkInTime: listing.checkInTime || \"\",
      checkOutTime: listing.checkOutTime || \"\",
      houseRules,
      noSpecialRules: Boolean(listing.noSpecialRules),
    },
    stay: {
      in: payload.in,
      out: payload.out,
      inLabel: dayLabel(payload.in),
      outLabel: dayLabel(payload.out),
      nights: quote.nights,
      guests: payload.guests,
      guestsLabel: plural(payload.guests, \"guest\", \"guests\"),
    },
    currency: quote.currency,
    lines,
    totalMinor: quote.totalMinor,
    taxIncluded: Boolean(quote.taxIncluded),
    expectedTotalMinor: payload.expectedTotalMinor,
    encodedLines: encodeLines(quote),
    instant: Boolean(listing.instantBook),
    policy: {
      value: policy ? policy.value : \"\",
      label: policy ? policy.label : \"Not stated\",
      text: cancellationText(policyValue),
    },
    idempotencyKey,
    change: changed
      ? {
          previousTotalMinor,
          newTotalMinor: quote.totalMinor,
          differenceMinor: quote.totalMinor - previousTotalMinor,
        }
      : null,
  };
}

module.exports = {
  buildCheckoutView,
  lineLabel,
  dayLabel,
  encodeLines,
  decodeLines,
};

// The comparison workspace (P10-T03): 2 to 4 stays side by side.
//
// Prices are never worked out here. With dates, every column gets exactly what
// quoteService.getQuote returns (the call the booking panel and reservations
// use), so the total in a column is the total a guest would pay. Without
// dates only the nightly price is shown.
//
// Only a whitelist of fields reaches the view (never the precise point or the
// street address), and a stay that is not public any more becomes a column that
// says so, without its title.
const {
  AMENITIES,
  CANCELLATION_POLICIES,
  CANCELLATION_TERMS,
} = require(\"../config/constants\");
const { parseCompareQuery } = require(\"../validation/compareQuery\");
const { QuoteRefusedError } = require(\"../utils/errors\");
const { neighborhoodFor } = require(\"./neighborhood\");
const { SOURCE: NEARBY_SOURCE } = require(\"../config/nearby\");

const label = (list, value) => (list.find((i) => i.value === value) || {}).label;

// Real collaborators, loaded only when a test has not supplied a fake.
const LOADERS = {
  Listing: () => require(\"../models/listing\"),
  getQuote: () => require(\"./quoteService\").getQuote,
  distanceMeters: () => require(\"../utils/geo\").distanceMeters,
  publicPointOf: () => require(\"../utils/geo\").publicPointOf,
  LocationNotFoundError: () => require(\"./geocoding\").LocationNotFoundError,
  GeocoderUnavailableError: () => require(\"./geocoding\").GeocoderUnavailableError,
  lookupPlace: () => async (text) => {
    const found = await require(\"./geocoding\").lookupAddress({ location: text });
    const [lng, lat] = found.geometry.coordinates;
    return { point: { lng, lat }, name: found.placeName };
  },
};

function resolveDeps(override) {
  const deps = { ...override };
  for (const [name, load] of Object.entries(LOADERS)) {
    if (!(name in deps)) deps[name] = load();
  }
  return deps;
}

const isPublic = (listing) =>
  Boolean(listing) && listing.status === \"published\" && !listing.deletedAt;

/** \"about 1.4 km\" / \"about 650 m\": the public point is approximate on purpose. */
function distanceLabel(meters) {
  if (!Number.isFinite(meters)) return \"\";
  if (meters < 1000) return `about ${Math.max(10, Math.round(meters / 10) * 10)} m`;
  return `about ${(meters / 1000).toFixed(1)} km`;
}

/** Cleaning + service fee as a share of the total, one decimal (\"12.5%\"). */
function feesPercent(quote) {
  if (!quote || !(quote.totalMinor > 0)) return \"\";
  const fees = (quote.cleaningMinor || 0) + (quote.serviceFeeMinor || 0);
  const tenths = Math.round((fees * 1000) / quote.totalMinor);
  return `${tenths / 10}%`;
}

/**
 * One row per amenity at least one public stay has. `has` lines up with
 * `columns`. `onlyId` is set when exactly one of two or more public stays has
 * it (\"only in this one\").
 */
function amenityMatrix(columns, catalogue = AMENITIES) {
  const live = columns.filter((c) => c.available);
  return catalogue
    .filter((a) => live.some((c) => c.amenities.includes(a.value)))
    .map((a) => {
      const holders = live.filter((c) => c.amenities.includes(a.value));
      return {
        value: a.value,
        label: a.label,
        has: columns.map((c) => c.available && c.amenities.includes(a.value)),
        onlyId: live.length >= 2 && holders.length === 1 ? holders[0].id : null,
        inAll: holders.length === live.length,
      };
    });
}

/** The compare URL for these stays (used by \"remove\" and the change-dates form). */
function compareUrl({ ids, dates, place }) {
  const params = new URLSearchParams();
  params.set(\"ids\", ids.join(\",\"));
  if (dates) {
    params.set(\"in\", dates.in);
    params.set(\"out\", dates.out);
    params.set(\"guests\", String(dates.guests));
  }
  if (place) params.set(\"place\", place);
  return `/compare?${params.toString()}`;
}

async function quoteFor(deps, listing, dates, now) {
  if (!dates) return { state: \"none\" };
  try {
    const result = await deps.getQuote(
      listing,
      { in: dates.in, out: dates.out, guests: String(dates.guests) },
      { now },
    );
    if (!result.bookable) {
      return {
        state: \"unavailable\",
        note: result.problems.map((p) => p.message).join(\" \"),
      };
    }
    const q = result.quote;
    return {
      state: \"total\",
      totalMinor: q.totalMinor,
      avgPerNightMinor: q.avgPerNightMinor,
      nights: q.nights,
      feesPercent: feesPercent(q),
      taxIncluded: q.taxIncluded,
      currency: q.currency,
    };
  } catch (err) {
    if (err instanceof QuoteRefusedError) {
      return { state: \"noprice\", note: \"This stay has no valid price yet.\" };
    }
    throw err;
  }
}

// The two nearby rows (P15-T03): the nearest place of each category, read from
// what the host's listing already stored (P15-T01). Nothing is fetched here.
// Distances come from neighborhoodFor: measured from the public (approximate)
// point and rounded to 50 m, so a row never gives away more than the listing
// page does.
const NEARBY_ROWS = Object.freeze([
  { id: \"transit\", label: \"Nearest transit\", empty: \"None found nearby\" },
  { id: \"grocery\", label: \"Nearest grocery\", empty: \"None found nearby\" },
]);

/** { fetchedOn, transit, grocery }; each of the two is null (none found) or { name, kindLabel, distanceLabel }. null = nothing stored. */
function nearbyFor(listing) {
  const hood = neighborhoodFor(listing);
  if (!hood) return null;
  const nearest = (id) => {
    const category = hood.categories.find((c) => c.id === id);
    if (!category) return null;
    const { name, kindLabel, distanceLabel: distance } = category.items[0];
    return { name, kindLabel, distanceLabel: distance };
  };
  const out = { fetchedOn: hood.fetchedOn };
  for (const row of NEARBY_ROWS) out[row.id] = nearest(row.id);
  return out;
}

function toColumn(id, listing) {
  if (!isPublic(listing)) {
    return { id, available: false, amenities: [] };
  }
  const cap = listing.capacity || {};
  const policy = listing.cancellationPolicy || \"moderate\";
  return {
    id,
    available: true,
    title: listing.title,
    href: `/listings/${id}`,
    imageUrl: listing.image && listing.image.url ? listing.image.url : null,
    where: [listing.location, listing.country].filter(Boolean).join(\", \"),
    currency: (listing.pricing && listing.pricing.currency) || \"INR\",
    nightlyMinor:
      Number.isInteger(listing.pricing && listing.pricing.nightlyMinor)
        ? listing.pricing.nightlyMinor
        : null,
    capacity: {
      guests: cap.guests ?? null,
      bedrooms: cap.bedrooms ?? null,
      beds: cap.beds ?? null,
      bathrooms: cap.bathrooms ?? null,
    },
    amenities: Array.isArray(listing.amenities) ? listing.amenities.map(String) : [],
    houseRules: typeof listing.houseRules === \"string\" ? listing.houseRules.trim() : \"\",
    cancellation: {
      label: label(CANCELLATION_POLICIES, policy) || policy,
      terms: CANCELLATION_TERMS[policy] || \"\",
    },
    rating: {
      average: Number(listing.ratingAvg) || 0,
      count: Number(listing.ratingCount) || 0,
    },
    nearby: nearbyFor(listing),
  };
}

/** The rows to show, or null when no stay in the comparison has nearby data. */
function nearbySection(columns) {
  const withData = columns.filter((c) => c.available && c.nearby);
  if (!withData.length) return null;
  const dates = withData.map((c) => c.nearby.fetchedOn).sort();
  return {
    rows: NEARBY_ROWS.map(({ id, label, empty }) => ({ id, label, empty })),
    source: NEARBY_SOURCE,
    from: dates[0],
    to: dates[dates.length - 1],
  };
}

/**
 * @param {object} input
 * @param {object} input.query  req.query
 * @param {Date}   [input.now]
 * @param {object} [input.deps] fakes for tests
 */
async function compare({ query, now = new Date(), deps: override = {} }) {
  const deps = resolveDeps(override);
  const parsed = parseCompareQuery(query);
  const { ids, dates } = parsed;

  const found = await deps.Listing.find({ _id: { $in: ids } }).lean();
  const byId = new Map(found.map((l) => [String(l._id), l]));
  const columns = ids.map((id) => toColumn(id, byId.get(id)));
  const live = columns.filter((c) => c.available);

  const base = {
    ids,
    dates: dates ? { in: dates.in, out: dates.out, guests: dates.guests } : null,
    columns,
    removable: ids.length > 2,
    removeHref: Object.fromEntries(
      ids.map((id) => [
        id,
        compareUrl({
          ids: ids.filter((other) => other !== id),
          dates,
          place: parsed.place,
        }),
      ]),
    ),
    place: null,
    amenities: [],
    nearby: null,
    cheapestId: null,
    blocked: null,
  };

  // Prices in different currencies cannot be added or ranked: say so, show nothing else.
  const currencies = new Set(live.map((c) => c.currency));
  if (currencies.size > 1) {
    return {
      ...base,
      blocked:
        \"These stays are priced in different currencies, and comparing them is not supported yet. Remove one to compare the rest.\",
    };
  }

  await Promise.all(
    live.map(async (column) => {
      column.quote = await quoteFor(deps, byId.get(column.id), dates, now);
    }),
  );

  // Distance to a place the visitor named (straight line, not a route).
  if (parsed.place) {
    base.place = { text: parsed.place, name: \"\", note: \"\" };
    try {
      const target = await deps.lookupPlace(parsed.place);
      base.place.name = target.name || parsed.place;
      for (const column of live) {
        const point = deps.publicPointOf(byId.get(column.id));
        column.distance = point
          ? distanceLabel(deps.distanceMeters(point, target.point))
          : \"\";
      }
    } catch (err) {
      if (err instanceof deps.LocationNotFoundError) {
        base.place.note = \"We could not find that place. Try a town, area or landmark.\";
      } else if (err instanceof deps.GeocoderUnavailableError) {
        base.place.note = \"Place search is not available right now. The other rows still work.\";
      } else {
        throw err;
      }
    }
  }

  const priced = live.filter((c) => c.quote && c.quote.state === \"total\");
  if (priced.length >= 2) {
    base.cheapestId = priced.reduce((a, b) =>
      b.quote.totalMinor < a.quote.totalMinor ? b : a,
    ).id;
  }
  base.amenities = amenityMatrix(columns);
  base.nearby = nearbySection(columns);
  return base;
}

module.exports = {
  compare,
  amenityMatrix,
  compareUrl,
  distanceLabel,
  feesPercent,
  nearbyFor,
  nearbySection,
  NEARBY_ROWS,
};

// Conversations and messages (P11-T02).
//
//   startForListing(deps, user, listingId)         -> { conversation, created }
//   startForReservation(deps, user, reservationId) -> { conversation, created }
//   send(deps, user, conversationId, body)         -> the stored message
//   thread(deps, user, conversationId, { before }) -> { conversation, messages, hasMore, nextBefore }
//   listFor(deps, user, { page })                  -> { conversations, page, totalPages, total }
//
// Rules, all enforced here and never by a form or a script:
// - Only the conversation's guest and host can read or write it. Anyone else
//   (an admin included), a missing id and a malformed id are the same 404.
// - \"Contact host\" works on a public listing and never on your own listing.
//   There is one general conversation per (listing, guest) and one per booking
//   (the unique `threadKey` decides, so two clicks make one conversation).
// - Nothing is sent, and no conversation is started, while either account is
//   not active (suspended or deleted).
// - A message is plain text, 1-1000 characters; a longer one is refused, never
//   cut. Views print it escaped.
// - Each side has its own unread counter: sending raises the other side's,
//   opening the thread resets your own.
// - A conversation with no message yet is not listed.
// `deps` lets tests pass fakes; `now` is the clock.
const { can } = require(\"../policies\");
const { isParticipant } = require(\"../policies/conversation\");
const { sameId, isActiveUser } = require(\"../policies/shared\");
const { isPublic } = require(\"../utils/visibility\");
const { LIMITS, PAGE_SIZE, LIST_SIZE } = require(\"../config/conversations\");
const {
  ConflictError,
  ForbiddenError,
  NotFoundError,
  ValidationError,
} = require(\"../utils/errors\");
const { DEFAULT_TIMEZONE } = require(\"../utils/dates\");

const OBJECT_ID = /^[0-9a-f]{24}$/i;
// Tab and new line are allowed; every other control character is not.
// eslint-disable-next-line no-control-regex
const CONTROL = /[\\u0000-\\u0008\\u000b\\u000c\\u000e-\\u001f\\u007f]/;

const models = (deps = {}) => ({
  Conversation: deps.ConversationModel || require(\"../models/conversation\"),
  Message: deps.MessageModel || require(\"../models/message\"),
  Listing: deps.ListingModel || require(\"../models/listing\"),
  Reservation: deps.ReservationModel || require(\"../models/reservation\"),
  User: deps.UserModel || require(\"../models/user\"),
});
const clock = (deps) => (deps && deps.now) || new Date();
const idText = (value) => String(value && value._id ? value._id : value);
const validId = (value) => typeof value === \"string\" && OBJECT_ID.test(value);

/** \"guest\" or \"host\": which side `user` is on. Call only for a participant. */
const sideOf = (user, conversation) =>
  sameId(conversation.guest, user._id) ? \"guest\" : \"host\";
const otherSide = (side) => (side === \"guest\" ? \"host\" : \"guest\");

const when = (date) =>
  date instanceof Date
    ? new Intl.DateTimeFormat(\"en-IN\", {
        day: \"numeric\",
        month: \"short\",
        hour: \"numeric\",
        minute: \"2-digit\",
        hour12: true,
        timeZone: DEFAULT_TIMEZONE,
      }).format(date)
    : \"\";

/** The trimmed plain text of a message, or a ValidationError. */
function parseBody(raw) {
  if (typeof raw !== \"string\") {
    throw new ValidationError(\"Write a message first.\");
  }
  const body = raw.replace(/\\r\\n?/g, \"\\n\").trim();
  if (!body) throw new ValidationError(\"Write a message first.\");
  if (CONTROL.test(body)) {
    throw new ValidationError(\"That message has characters we cannot send.\");
  }
  if (body.length > LIMITS.body) {
    throw new ValidationError(
      `Messages can be up to ${LIMITS.body} characters (yours has ${body.length}).`,
    );
  }
  return body;
}

const preview = (body) => body.replace(/\\s+/g, \" \").slice(0, LIMITS.preview);

/** Accounts of both people must be active, or nothing is started or sent. */
async function assertBothActive(M, guestId, hostId) {
  const users = await M.User.find({ _id: { $in: [guestId, hostId] } })
    .select(\"status\")
    .lean();
  const ok =
    users.length === (sameId(guestId, hostId) ? 1 : 2) &&
    users.every((u) => isActiveUser(u));
  if (!ok) {
    throw new ConflictError(
      \"Messages are not available in this conversation right now.\",
    );
  }
}

/** The existing conversation for `threadKey`, or a new one (idempotent). */
async function findOrCreate(M, threadKey, fields) {
  const existing = await M.Conversation.findOne({ threadKey }).lean();
  if (existing) return { conversation: existing, created: false };
  try {
    const row = await M.Conversation.create({ threadKey, ...fields });
    const conversation =
      row && typeof row.toObject === \"function\" ? row.toObject() : row;
    return { conversation, created: true };
  } catch (err) {
    // Lost a race with a second click: the unique index says the thread exists.
    if (err && err.code === 11000) {
      const winner = await M.Conversation.findOne({ threadKey }).lean();
      if (winner) return { conversation: winner, created: false };
    }
    throw err;
  }
}

/** \"Contact host\": the guest's general conversation about a public listing. */
async function startForListing(deps, user, listingId) {
  const M = models(deps);
  const listing = validId(listingId)
    ? await M.Listing.findById(listingId).select(\"owner status deletedAt\").lean()
    : null;
  if (!listing || !isPublic(listing)) {
    throw new NotFoundError(\"That listing does not exist.\");
  }
  if (!user || !isActiveUser(user)) {
    throw new ForbiddenError(\"Your account cannot send messages.\");
  }
  if (sameId(listing.owner, user._id)) {
    throw new ForbiddenError(\"You cannot message yourself about your own listing.\");
  }
  if (!can(\"conversation:start\", user, listing)) {
    throw new ForbiddenError(\"You cannot message this host.\");
  }
  await assertBothActive(M, user._id, listing.owner);
  return findOrCreate(M, `listing:${idText(listing._id)}:${idText(user._id)}`, {
    listing: listing._id,
    guest: user._id,
    host: listing.owner,
    reservation: null,
  });
}

/** The conversation about one booking; either of its two people may open it. */
async function startForReservation(deps, user, reservationId) {
  const M = models(deps);
  const reservation = validId(reservationId)
    ? await M.Reservation.findById(reservationId)
        .select(\"listing guest host\")
        .lean()
    : null;
  // Not the guest or host (an admin included) = the same 404 as a missing booking.
  if (!reservation || !isParticipant(user, reservation)) {
    throw new NotFoundError(\"That booking does not exist.\");
  }
  if (!isActiveUser(user)) {
    throw new ForbiddenError(\"Your account cannot send messages.\");
  }
  await assertBothActive(M, reservation.guest, reservation.host);
  return findOrCreate(M, `reservation:${idText(reservation._id)}`, {
    listing: reservation.listing,
    guest: reservation.guest,
    host: reservation.host,
    reservation: reservation._id,
  });
}

/** The conversation if `user` is one of its two people, else a 404. */
async function loadFor(M, user, id) {
  const conversation =
    validId(id) && user ? await M.Conversation.findById(id).lean() : null;
  if (!conversation || !isParticipant(user, conversation)) {
    throw new NotFoundError(\"That conversation does not exist.\");
  }
  if (!can(\"conversation:view\", user, conversation)) {
    throw new ForbiddenError(\"Your account cannot use messages.\");
  }
  return conversation;
}

function describeMessage(row, user) {
  const created = row.createdAt instanceof Date ? row.createdAt : null;
  return {
    id: idText(row._id),
    body: row.body,
    mine: sameId(row.sender, user._id),
    when: when(created),
    iso: created ? created.toISOString() : \"\",
  };
}

/** Sends one message and raises the other side's unread counter. */
async function send(deps, user, conversationId, rawBody) {
  const M = models(deps);
  const conversation = await loadFor(M, user, conversationId);
  if (!can(\"conversation:send\", user, conversation)) {
    throw new ForbiddenError(\"Your account cannot send messages.\");
  }
  await assertBothActive(M, conversation.guest, conversation.host);
  const body = parseBody(rawBody);
  const now = clock(deps);
  const row = await M.Message.create({
    conversation: conversation._id,
    sender: user._id,
    body,
  });
  const side = sideOf(user, conversation);
  await M.Conversation.updateOne(
    { _id: conversation._id },
    {
      $inc: { [`unread.${otherSide(side)}`]: 1 },
      $set: {
        lastMessageAt: now,
        \"lastMessage.sender\": user._id,
        \"lastMessage.preview\": preview(body),
      },
    },
  );
  return describeMessage(
    {
      ...(typeof row.toObject === \"function\" ? row.toObject() : row),
      createdAt: (row && row.createdAt) || now,
    },
    user,
  );
}

async function people(M, conversation) {
  const [users, listings] = await Promise.all([
    M.User.find({ _id: { $in: [conversation.guest, conversation.host] } })
      .select(\"displayName username status\")
      .lean(),
    M.Listing.find({ _id: { $in: [conversation.listing] } })
      .select(\"title\")
      .lean(),
  ]);
  return { users, listings };
}

const nameOf = (users, id) => {
  const u = users.find((x) => sameId(x, id));
  return u ? u.displayName || u.username || \"A member\" : \"A member\";
};

/**
 * Messages of one conversation, oldest first, PAGE_SIZE at a time: the newest
 * page, or the page before the message id `before`. Opening it marks the
 * viewer's side read.
 */
async function thread(deps, user, conversationId, { before } = {}) {
  const M = models(deps);
  const conversation = await loadFor(M, user, conversationId);
  const filter = { conversation: conversation._id };
  if (validId(before)) filter._id = { $lt: before };
  const rows = await M.Message.find(filter)
    .sort({ _id: -1 })
    .limit(PAGE_SIZE + 1)
    .lean();
  const hasMore = rows.length > PAGE_SIZE;
  const page = rows.slice(0, PAGE_SIZE).reverse();

  const side = sideOf(user, conversation);
  if (conversation.unread && conversation.unread[side] > 0) {
    await M.Conversation.updateOne(
      { _id: conversation._id, [`unread.${side}`]: { $gt: 0 } },
      { $set: { [`unread.${side}`]: 0 } },
    );
  }
  const { users, listings } = await people(M, conversation);
  const otherId = side === \"guest\" ? conversation.host : conversation.guest;
  const other = users.find((u) => sameId(u, otherId));
  const mine = users.find((u) => sameId(u, user._id));
  const listing = listings[0];
  return {
    conversation: {
      id: idText(conversation._id),
      side,
      listingId: idText(conversation.listing),
      listingTitle: listing ? listing.title : \"A listing\",
      reservationId: conversation.reservation
        ? idText(conversation.reservation)
        : null,
      otherName: nameOf(users, otherId),
      // Neither side can write while either account is not active.
      canReply: Boolean(
        other && mine && isActiveUser(other) && isActiveUser(mine),
      ),
    },
    messages: page.map((row) => describeMessage(row, user)),
    hasMore,
    nextBefore: hasMore && page.length > 0 ? idText(rows[PAGE_SIZE - 1]._id) : null,
  };
}

/** The member's conversations that have messages, newest message first. */
async function listFor(deps, user, { page } = {}) {
  const M = models(deps);
  const mine = { $or: [{ guest: user._id }, { host: user._id }] };
  const filter = { $and: [mine, { lastMessageAt: { $ne: null } }] };
  const total = await M.Conversation.countDocuments(filter);
  const totalPages = Math.max(1, Math.ceil(total / LIST_SIZE));
  const n = typeof page === \"string\" && /^\\d{1,6}$/.test(page) ? Number(page) : 1;
  const current = Math.min(Math.max(1, n), totalPages);
  const rows = await M.Conversation.find(filter)
    .sort({ lastMessageAt: -1, _id: -1 })
    .skip((current - 1) * LIST_SIZE)
    .limit(LIST_SIZE)
    .lean();

  const userIds = [];
  const listingIds = [];
  for (const row of rows) {
    userIds.push(row.guest, row.host);
    listingIds.push(row.listing);
  }
  const [users, listings] = await Promise.all([
    rows.length
      ? M.User.find({ _id: { $in: userIds } })
          .select(\"displayName username\")
          .lean()
      : [],
    rows.length
      ? M.Listing.find({ _id: { $in: listingIds } })
          .select(\"title\")
          .lean()
      : [],
  ]);
  return {
    conversations: rows.map((row) => {
      const side = sideOf(user, row);
      const listing = listings.find((l) => sameId(l, row.listing));
      return {
        id: idText(row._id),
        side,
        listingTitle: listing ? listing.title : \"A listing\",
        otherName: nameOf(users, side === \"guest\" ? row.host : row.guest),
        preview: (row.lastMessage && row.lastMessage.preview) || \"\",
        lastFromMe: Boolean(
          row.lastMessage && sameId(row.lastMessage.sender, user._id),
        ),
        when: when(row.lastMessageAt),
        unread: (row.unread && row.unread[side]) || 0,
      };
    }),
    page: current,
    totalPages,
    total,
  };
}

module.exports = {
  startForListing,
  startForReservation,
  send,
  thread,
  listFor,
  parseBody,
};

// Destination suggestions for the search boxes (P05-T06). From the cities and
// countries of stays that really are public, nothing from a third party.
//
//   \"pan\"        -> cities starting \"pan\", and countries starting \"pan\"
//   \"panaji, g\"  -> cities starting \"panaji\" in a state starting \"g\"
//
// Each suggestion is \"City, State, Country\" as the host wrote it, with the number
// of public stays, and a `dest` that is guaranteed to find those stays: when the
// written text would not normalise to the stored keys, the keys are used instead
// (same rule as the empty-search suggestions, P05-T05).
//
// One aggregation, answered from the (status, cityKey) / (status, countryKey)
// indexes: at most MAX_SUGGESTIONS rows come back, whatever the data size.
const { publicListingFilter } = require(\"../utils/visibility\");
const { destinationParts, normaliseToken } = require(\"../utils/searchKeys\");

const MIN_CHARS = 2;
const MAX_QUERY = 100;
const MAX_SUGGESTIONS = 8;

const escapeRegex = (text) => text.replace(/[.*+?^${}()|[\\]\\\\]/g, \"\\\\$&\");
const startsWith = (text) => new RegExp(`^${escapeRegex(text)}`);

/** The match condition for what was typed, or null when it is too short to search. */
function conditionFor(input) {
  if (typeof input !== \"string\") return null;
  const parts = destinationParts(input.slice(0, MAX_QUERY));
  if (parts.length === 0 || parts[0].length < MIN_CHARS) return null;
  if (parts.length === 1) {
    return { $or: [{ cityKey: startsWith(parts[0]) }, { countryKey: startsWith(parts[0]) }] };
  }
  const cond = { cityKey: startsWith(parts[0]), stateKey: startsWith(parts[1]) };
  if (parts[2]) cond.countryKey = startsWith(parts[2]);
  return cond;
}

const firstPart = (text) => String(text || \"\").split(\",\")[0].trim();

function present(group) {
  const { cityKey = \"\", stateKey = \"\", countryKey = \"\" } = group._id || {};
  const expected = [cityKey, stateKey, countryKey].filter(Boolean);
  const written = [
    firstPart(group.city) || firstPart(group.location),
    group.state,
    group.country,
  ]
    .map((p) => String(p || \"\").trim())
    .filter(Boolean);
  const label = written.join(\", \");
  const parts = destinationParts(label);
  const safe =
    parts.length === expected.length && parts.every((p, i) => expected[i].startsWith(p));
  const text = safe ? label : expected.join(\", \");
  return { label: text, dest: text, count: group.count };
}

/**
 * @param {object} args
 * @param {object} args.Listing  the model
 * @param {string} args.q        what the visitor typed
 * @returns {Promise<Array<{ label: string, dest: string, count: number }>>}
 */
async function suggestDestinations({ Listing, q, limit = MAX_SUGGESTIONS }) {
  const cond = conditionFor(q);
  if (!cond) return [];
  const groups = await Listing.aggregate([
    { $match: { ...publicListingFilter(), ...cond } },
    {
      $group: {
        _id: { cityKey: \"$cityKey\", stateKey: \"$stateKey\", countryKey: \"$countryKey\" },
        count: { $sum: 1 },
        city: { $first: \"$address.city\" },
        state: { $first: \"$address.state\" },
        country: { $first: \"$address.country\" },
        location: { $first: \"$location\" },
      },
    },
    { $sort: { count: -1, \"_id.cityKey\": 1, \"_id.stateKey\": 1, \"_id.countryKey\": 1 } },
    { $limit: Math.min(limit, MAX_SUGGESTIONS) },
  ]);
  const seen = new Set();
  const out = [];
  for (const group of Array.isArray(groups) ? groups : []) {
    if (!group || !group._id || !group._id.cityKey) continue;
    const item = present(group);
    if (!item.dest || seen.has(item.dest)) continue;
    seen.add(item.dest);
    out.push(item);
  }
  return out;
}

module.exports = {
  MIN_CHARS,
  MAX_SUGGESTIONS,
  conditionFor,
  present,
  suggestDestinations,
  normaliseToken,
};

// Abandoned drafts (P04-T02): a draft nobody has touched for 90 days is not a
// listing anyone is going to finish. This deletes them (and their uploaded
// photos). It is a plain function so the sweeper job (P07-T07) can call it on
// a schedule; nothing calls it yet.
const DEFAULT_DAYS = 90;
const DAY_MS = 24 * 60 * 60 * 1000;

/**
 * @param {object} Listing the model
 * @param {object} [options]
 * @param {Date}   [options.now]
 * @param {number} [options.days]
 * @param {(publicId: string) => Promise<unknown>} [options.destroy] removes one
 *        photo from storage; errors are ignored (a leftover photo is not worth failing)
 * @returns {Promise<{ deleted: number, photosRemoved: number }>}
 */
async function deleteStaleDrafts(
  Listing,
  { now = new Date(), days = DEFAULT_DAYS, destroy } = {},
) {
  // Built with no argument and then set: application code makes dates from
  // values only in src/utils/dates.js (see tests/unit/noUserDate.test.js).
  const cutoff = new Date();
  cutoff.setTime(now.getTime() - days * DAY_MS);
  const stale = await Listing.find({
    status: \"draft\",
    updatedAt: { $lt: cutoff },
  })
    .select(\"images image\")
    .lean();

  let deleted = 0;
  let photosRemoved = 0;
  for (const draft of stale) {
    // Re-check in the delete itself: a host who saved a step a moment ago keeps
    // the draft, and a draft that was published meanwhile is never touched.
    const result = await Listing.deleteOne({
      _id: draft._id,
      status: \"draft\",
      updatedAt: { $lt: cutoff },
    });
    if (!result || result.deletedCount !== 1) continue;
    deleted += 1;
    if (!destroy) continue;
    const ids = (draft.images || [])
      .map((photo) => photo.publicId)
      .filter(Boolean);
    for (const id of ids) {
      try {
        await destroy(id);
        photosRemoved += 1;
      } catch {
        // best effort
      }
    }
  }
  return { deleted, photosRemoved };
}

module.exports = { deleteStaleDrafts, DEFAULT_DAYS };

// Sending email (P02-T05). One function, `send({ to, subject, text, html })`,
// over three transports:
//
//   console  writes the message to the log (development and tests). In
//            production it logs only the recipient and subject: a link in a log
//            is a password-reset key in a log.
//   resend   Resend's HTTPS API (https://resend.com/docs/api-reference/emails/send-email).
//            HTTPS, not SMTP, because Render's free plan blocks SMTP ports.
//   memory   keeps the messages in an array (`service.outbox`) for tests.
//
// A failed send throws EmailError with a short, safe message: never the API
// key, the address or the provider's reply.
const RESEND_URL = \"https://api.resend.com/emails\";
const TIMEOUT_MS = 8000;

class EmailError extends Error {
  constructor(message) {
    super(message);
    this.name = \"EmailError\";
  }
}

function checkMessage({ to, subject, text, headers }) {
  if (typeof to !== \"string\" || !/^[^\\s@,;<>]+@[^\\s@,;<>]+$/.test(to)) {
    throw new EmailError(\"invalid recipient\");
  }
  if (typeof subject !== \"string\" || !subject || /[\\r\\n]/.test(subject)) {
    throw new EmailError(\"invalid subject\");
  }
  if (typeof text !== \"string\" || !text) throw new EmailError(\"empty message\");
  if (headers !== undefined) {
    const ok =
      headers && typeof headers === \"object\" && !Array.isArray(headers) &&
      Object.entries(headers).every(
        ([k, v]) => /^[A-Za-z][A-Za-z0-9-]{0,60}$/.test(k) && typeof v === \"string\" && !/[\\r\\n]/.test(v),
      );
    if (!ok) throw new EmailError(\"invalid headers\");
  }
}

function createMemoryEmailService() {
  const outbox = [];
  return {
    transport: \"memory\",
    outbox,
    async send(message) {
      checkMessage(message);
      outbox.push({ ...message });
    },
  };
}

/**
 * @param {object} options
 * @param {{ transport?: string, from?: string, resendApiKey?: string|null }} [options.email]  config.email
 * @param {boolean} [options.isProduction]
 * @param {{ info?: Function, warn?: Function }} [options.logger]
 * @param {typeof fetch} [options.fetchImpl]
 */
function createEmailService({
  email = {},
  isProduction = false,
  logger = {},
  fetchImpl = globalThis.fetch,
} = {}) {
  const transport = email.transport || \"console\";
  const from = email.from || \"Dimora <no-reply@localhost>\";

  if (transport === \"resend\") {
    return {
      transport,
      async send(message) {
        checkMessage(message);
        let res;
        try {
          res = await fetchImpl(RESEND_URL, {
            method: \"POST\",
            headers: {
              Authorization: `Bearer ${email.resendApiKey}`,
              \"Content-Type\": \"application/json\",
            },
            body: JSON.stringify({
              from,
              to: [message.to],
              subject: message.subject,
              text: message.text,
              ...(message.html ? { html: message.html } : {}),
              ...(message.headers ? { headers: message.headers } : {}),
            }),
            signal: AbortSignal.timeout(TIMEOUT_MS),
          });
        } catch (err) {
          throw new EmailError(
            err && err.name === \"TimeoutError\" ? \"the email provider timed out\" : \"could not reach the email provider\",
          );
        }
        if (!res.ok) throw new EmailError(`the email provider answered ${res.status}`);
      },
    };
  }

  return {
    transport: \"console\",
    async send(message) {
      checkMessage(message);
      if (isProduction) {
        if (logger.warn) logger.warn({ subject: message.subject }, \"email not sent: no email provider is configured\");
        return;
      }
      if (logger.info) {
        logger.info(
          { email: { to: message.to, subject: message.subject, text: message.text } },
          \"email (console transport, not sent)\",
        );
      }
    },
  };
}

module.exports = { createEmailService, createMemoryEmailService, EmailError, RESEND_URL };

// Confirming an email address and resetting a password (P02-T05).
//
// Rules:
//   - A confirmation link proves the person can read mail sent to the address
//     the account had WHEN THE LINK WAS SENT; if the address changed since, it
//     confirms nothing.
//   - \"Forgot password\" never says whether the address belongs to an account:
//     the caller always shows the same answer. Suspended and deleted accounts get
//     no email.
//   - A reset link works once and for one hour. Using it sets the new password,
//     clears the failed-login lock, cancels other reset links, confirms the
//     address (the link proved it), and sends a \"your password was changed\" note.
const tokens = require(\"./emailTokens\");
const templates = require(\"../emails/templates\");

const models = (over = {}) => ({ UserModel: over.UserModel || require(\"../models/user\") });
const link = (baseUrl, path, raw) => `${String(baseUrl).replace(/\\/+$/, \"\")}${path}${raw}`;
const hours = (ms) => Math.round(ms / 3600000);

/** Sends the \"confirm your address\" email. Throws EmailThrottledError / EmailError. */
async function sendVerification({ user, emailService, baseUrl, now = new Date(), ...over }) {
  if (user.emailVerifiedAt) return { status: \"already_verified\" };
  const raw = await tokens.issue({ user, purpose: tokens.VERIFY, now, ...over });
  await emailService.send({
    to: user.email,
    ...templates.verifyEmail({
      name: user.displayName || user.username,
      link: link(baseUrl, \"/verify-email/\", raw),
      hours: hours(tokens.TTL_MS[tokens.VERIFY]),
    }),
  });
  return { status: \"sent\" };
}

/** Uses a confirmation token. { ok: true, user } or { ok: false }. */
async function verifyEmail({ raw, now = new Date(), ...over }) {
  const { UserModel } = models(over);
  const token = await tokens.consume({ raw, purpose: tokens.VERIFY, now, ...over });
  if (!token) return { ok: false };
  const user = await UserModel.findOneAndUpdate(
    { _id: token.user, email: token.email, status: \"active\" },
    { $set: { emailVerifiedAt: now } },
    { new: true },
  );
  return user ? { ok: true, user } : { ok: false };
}

/**
 * Sends a reset link if an active account has this address. Returns nothing the
 * caller could show: the answer to the visitor is the same either way.
 */
async function requestPasswordReset({ email, emailService, baseUrl, now = new Date(), ...over }) {
  const { UserModel } = models(over);
  const user = await UserModel.findOne({ email: String(email).trim().toLowerCase(), status: \"active\" });
  if (!user) return { sent: false };
  const raw = await tokens.issue({ user, purpose: tokens.RESET, now, ...over });
  await emailService.send({
    to: user.email,
    ...templates.resetPassword({
      name: user.displayName || user.username,
      link: link(baseUrl, \"/reset-password/\", raw),
      minutes: Math.round(tokens.TTL_MS[tokens.RESET] / 60000),
    }),
  });
  return { sent: true };
}

/** The active account a still-usable reset token belongs to, or null. Uses nothing. */
async function userForResetToken({ raw, now = new Date(), ...over }) {
  const { UserModel } = models(over);
  const token = await tokens.peek({ raw, purpose: tokens.RESET, now, ...over });
  if (!token) return null;
  return UserModel.findOne({ _id: token.user, email: token.email, status: \"active\" });
}

/**
 * Sets a new password with a reset token. The password must already have been
 * checked against the rules (validation/resetPasswordSchema).
 * @returns {{ ok: boolean, user?: object }}
 */
async function resetPassword({ raw, newPassword, emailService, now = new Date(), ...over }) {
  const { UserModel } = models(over);
  const token = await tokens.consume({ raw, purpose: tokens.RESET, now, ...over });
  if (!token) return { ok: false };
  const user = await UserModel.findOne({ _id: token.user, email: token.email, status: \"active\" });
  if (!user) return { ok: false };

  await user.setPassword(newPassword);
  user.attempts = 0; // lift the failed-login lock (P02-T02)
  if (!user.emailVerifiedAt) user.emailVerifiedAt = now; // the link was read at this address
  await user.save();
  await tokens.revokeAll({ userId: user._id, purpose: tokens.RESET, now, ...over });

  if (emailService) {
    try {
      await emailService.send({
        to: user.email,
        ...templates.passwordChanged({ name: user.displayName || user.username }),
      });
    } catch {
      // The password is already changed; the note is a courtesy.
    }
  }
  return { ok: true, user };
}

module.exports = {
  sendVerification,
  verifyEmail,
  requestPasswordReset,
  userForResetToken,
  resetPassword,
};

// Creating, checking and using the one-time email links (P02-T05).
//
//   issue    makes a token for (user, purpose), cancels the user's older unused
//            tokens of that purpose, and returns the raw token (the only time it
//            exists in clear). Throttled per account: one per minute, five per hour.
//   peek     \"is this token usable?\" without using it (the GET page, so a mail
//            scanner that opens the link cannot burn it).
//   consume  uses it, atomically: of two requests with the same token one wins.
const crypto = require(\"node:crypto\");
const { AppError } = require(\"../utils/errors\");

const VERIFY = \"verify_email\";
const RESET = \"reset_password\";
const TTL_MS = Object.freeze({
  [VERIFY]: 24 * 60 * 60 * 1000,
  [RESET]: 60 * 60 * 1000,
});
const MIN_GAP_MS = 60 * 1000;
const MAX_PER_HOUR = 5;
const TOKEN_PATTERN = /^[A-Za-z0-9_-]{43}$/; // 32 random bytes, base64url

class EmailThrottledError extends AppError {
  constructor(retryAfterSeconds) {
    super(429, `Please wait ${retryAfterSeconds} seconds before asking for another email.`, {
      code: \"email_throttled\",
    });
    this.retryAfterSeconds = retryAfterSeconds;
  }
}

const hashToken = (raw) => crypto.createHash(\"sha256\").update(raw).digest(\"hex\");
const model = (over = {}) => over.EmailTokenModel || require(\"../models/emailToken\");

async function issue({ user, purpose, now = new Date(), ...over }) {
  if (!TTL_MS[purpose]) throw new Error(`unknown token purpose \"${purpose}\"`);
  const Model = model(over);
  const recent = await Model.find({
    user: user._id,
    purpose,
    createdAt: { $gte: new Date(now.getTime() - 60 * 60 * 1000) },
  })
    .sort({ createdAt: -1 })
    .select(\"createdAt\")
    .lean();

  if (recent.length > 0) {
    const sinceLast = now.getTime() - new Date(recent[0].createdAt).getTime();
    if (sinceLast < MIN_GAP_MS) throw new EmailThrottledError(Math.ceil((MIN_GAP_MS - sinceLast) / 1000));
  }
  if (recent.length >= MAX_PER_HOUR) {
    const oldest = new Date(recent[recent.length - 1].createdAt).getTime();
    throw new EmailThrottledError(Math.max(1, Math.ceil((oldest + 60 * 60 * 1000 - now.getTime()) / 1000)));
  }

  await Model.updateMany({ user: user._id, purpose, usedAt: null }, { $set: { usedAt: now } });
  const raw = crypto.randomBytes(32).toString(\"base64url\");
  await Model.create({
    user: user._id,
    purpose,
    email: user.email,
    tokenHash: hashToken(raw),
    expiresAt: new Date(now.getTime() + TTL_MS[purpose]),
  });
  return raw;
}

function usable(raw, purpose, now) {
  if (typeof raw !== \"string\" || !TOKEN_PATTERN.test(raw)) return null;
  return { tokenHash: hashToken(raw), purpose, usedAt: null, expiresAt: { $gt: now } };
}

/** The token row if the token can still be used; nothing is changed. */
async function peek({ raw, purpose, now = new Date(), ...over }) {
  const filter = usable(raw, purpose, now);
  return filter ? model(over).findOne(filter).lean() : null;
}

/** Uses the token (once). Returns the row, or null if it is unknown, used or expired. */
async function consume({ raw, purpose, now = new Date(), ...over }) {
  const filter = usable(raw, purpose, now);
  return filter ? model(over).findOneAndUpdate(filter, { $set: { usedAt: now } }, { new: true }).lean() : null;
}

/** Cancels every unused token of a purpose (after a password reset). */
async function revokeAll({ userId, purpose, now = new Date(), ...over }) {
  await model(over).updateMany({ user: userId, purpose, usedAt: null }, { $set: { usedAt: now } });
}

module.exports = {
  VERIFY,
  RESET,
  TTL_MS,
  MIN_GAP_MS,
  MAX_PER_HOUR,
  TOKEN_PATTERN,
  EmailThrottledError,
  hashToken,
  issue,
  peek,
  consume,
  revokeAll,
};

// Flexible-date suggestions (P15-T04, signature #5): when the nights a guest
// asked for are taken, offer the nearest free stays of the SAME length.
//
//   suggestAlternatives(listing, { checkIn, checkOut, guests }, options)
//   -> { radiusDays, windows: [{ in, out, nights, shiftDays, quote }] }
//
// How it chooses (all of it is checked again at the moment of the answer):
// 1. availableRanges() gives the free stretches of the night ledger between
//    `radiusDays` (14) before the requested check-in and after the requested
//    check-out; an expired hold counts as free, a host block as taken.
// 2. Every start date that fits a free stretch is a candidate, nearest to the
//    requested check-in first (earlier first on a tie). Candidates are taken
//    greedily, skipping any that overlaps one already chosen, so three
//    suggestions are three different stays, not the same stay shifted by a day.
// 3. A candidate must pass the booking rules (minimum and maximum stay,
//    notice, cut-off, not in the past, capacity) and is priced by the quote
//    service itself, the same call the panel and the checkout make. A
//    candidate the quote service refuses is dropped, not shown.
// At most `max` (3) windows are returned; none is not an error.
//
// A suggestion can still be booked by someone else before the guest clicks it:
// that goes down the normal conflict path (a 409 at checkout).
const ledger = require(\"./ledger\");
const pricing = require(\"./pricing\");
const { bookingProblems } = require(\"./bookingRules\");
const {
  DEFAULT_TIMEZONE,
  addDays,
  formatDateOnly,
  nightsBetween,
  todayIn,
} = require(\"../utils/dates\");

const DEFAULTS = Object.freeze({ radiusDays: 14, max: 3 });
const MS_PER_DAY = 86400000;

const daysBetween = (a, b) =>
  Math.round((b.getTime() - a.getTime()) / MS_PER_DAY);

/**
 * @param {object} listing the listing document (rules and prices)
 * @param {{ checkIn: Date, checkOut: Date, guests: number }} stay date-only Dates
 * @param {object} [options]
 * @param {Date} [options.now]
 * @param {number} [options.radiusDays]
 * @param {number} [options.max]
 * @param {object} [options.ledgerService] needs availableRanges and unavailableDates
 * @param {object} [options.pricingService]
 * @param {Function} [options.getQuoteFn] replaceable in tests
 */
async function suggestAlternatives(
  listing,
  { checkIn, checkOut, guests },
  {
    now = new Date(),
    radiusDays = DEFAULTS.radiusDays,
    max = DEFAULTS.max,
    ledgerService = ledger,
    pricingService = pricing,
    getQuoteFn = (...args) => require(\"./quoteService\").getQuote(...args),
  } = {},
) {
  const nights = nightsBetween(checkIn, checkOut);
  const today = todayIn((listing && listing.timezone) || DEFAULT_TIMEZONE, now);

  // Never look at nights before today: they could not be booked anyway.
  let from = addDays(checkIn, -radiusDays);
  if (from.getTime() < today.getTime()) from = today;
  const to = addDays(checkOut, radiusDays);
  if (from.getTime() >= to.getTime()) return { radiusDays, windows: [] };

  const free = await ledgerService.availableRanges(listing._id, from, to, {
    now,
  });

  const candidates = [];
  for (const range of free) {
    for (let k = 0; k + nights <= range.nights; k += 1) {
      const start = addDays(range.from, k);
      const shift = daysBetween(checkIn, start);
      if (shift === 0) continue; // the requested stay itself
      candidates.push({ start, end: addDays(start, nights), shift });
    }
  }
  candidates.sort(
    (a, b) => Math.abs(a.shift) - Math.abs(b.shift) || a.shift - b.shift,
  );

  const windows = [];
  for (const candidate of candidates) {
    if (windows.length >= max) break;
    const overlaps = windows.some(
      (w) =>
        candidate.start.getTime() < w.endDate.getTime() &&
        candidate.end.getTime() > w.startDate.getTime(),
    );
    if (overlaps) continue;
    // Cheap rule check first; the quote below repeats it with the ledger and price.
    if (
      bookingProblems({
        listing,
        checkIn: candidate.start,
        checkOut: candidate.end,
        guests,
        now,
      }).length
    )
      continue;
    const payload = await getQuoteFn(
      listing,
      {
        in: formatDateOnly(candidate.start),
        out: formatDateOnly(candidate.end),
        guests: String(guests),
      },
      { now, ledgerService, pricingService },
    );
    if (!payload.bookable) continue;
    windows.push({
      in: payload.in,
      out: payload.out,
      nights,
      shiftDays: candidate.shift,
      quote: payload.quote,
      startDate: candidate.start,
      endDate: candidate.end,
    });
  }
  return {
    radiusDays,
    windows: windows.map(({ startDate, endDate, ...rest }) => rest), // eslint-disable-line no-unused-vars
  };
}

module.exports = { suggestAlternatives, DEFAULTS };

const mbxGeocoding = require(\"@mapbox/mapbox-sdk/services/geocoding\");
const { loadEnv } = require(\"../config/env\");
const { AppError, ValidationError } = require(\"../utils/errors\");

// Built on first use so that requiring this file does not need the environment.
// server.js calls getGeocodingClient() at startup so a malformed
// MAPBOX_SERVER_TOKEN still stops the server at boot.
let client;
function getGeocodingClient() {
  if (!client) {
    client = mbxGeocoding({ accessToken: loadEnv().mapbox.serverToken });
  }
  return client;
}

// The place could not be found: the user can fix it, so it is a 400.
class LocationNotFoundError extends ValidationError {
  constructor() {
    super(
      \"We couldn't find that location. Check the spelling or add the city and country.\",
      { code: \"location_not_found\" },
    );
  }
}

// Mapbox failed or timed out: not the user's fault, safe to retry.
class GeocoderUnavailableError extends AppError {
  constructor(cause) {
    super(
      503,
      \"Location lookup is temporarily unavailable. Please try again in a moment.\",
      { code: \"geocoder_unavailable\", cause },
    );
  }
}

function isPoint(geometry) {
  return (
    geometry &&
    geometry.type === \"Point\" &&
    Array.isArray(geometry.coordinates) &&
    geometry.coordinates.length >= 2 &&
    geometry.coordinates.slice(0, 2).every((n) => Number.isFinite(n))
  );
}

/**
 * Looks a place up and returns a GeoJSON Point `{ type, coordinates: [lng, lat] }`.
 * Throws LocationNotFoundError (no/invalid result) or GeocoderUnavailableError.
 */
async function geocodeAddress(input) {
  return (await lookupAddress(input)).geometry;
}

/**
 * Like geocodeAddress, but also returns Mapbox's own name for the place it
 * found (\"Panaji, Goa, India\"), so a host can check the match before saving.
 * `placeName` is \"\" when Mapbox gave none.
 * @returns {Promise<{ geometry: object, placeName: string }>}
 */
async function lookupAddress({ location, country }) {
  const query = [location, country]
    .map((part) => (typeof part === \"string\" ? part.trim() : \"\"))
    .filter(Boolean)
    .join(\", \");
  if (!query) throw new LocationNotFoundError();

  // Outside the try: a missing/invalid token is a configuration bug (500), not
  // a temporary outage.
  const geocoder = getGeocodingClient();
  let response;
  try {
    const request = { query, limit: 1 };
    // Stored coordinates need Mapbox's permanent licence (ADR-007); opt-in.
    if (loadEnv().mapbox.permanentGeocoding)
      request.mode = \"mapbox.places-permanent\";
    response = await geocoder.forwardGeocode(request).send();
  } catch (err) {
    throw new GeocoderUnavailableError(err);
  }

  const features = response && response.body && response.body.features;
  const geometry =
    Array.isArray(features) && features[0] && features[0].geometry;
  if (!isPoint(geometry)) throw new LocationNotFoundError();
  const name = features[0].place_name;
  return {
    geometry: {
      type: \"Point\",
      coordinates: [geometry.coordinates[0], geometry.coordinates[1]],
    },
    placeName: typeof name === \"string\" ? name.trim().slice(0, 300) : \"\",
  };
}

module.exports = {
  getGeocodingClient,
  geocodeAddress,
  lookupAddress,
  LocationNotFoundError,
  GeocoderUnavailableError,
};

// Data for the home page (P03-T05): the newest stays and the places that have
// the most stays. Only published listings are used; drafts from the wizard are not.
const { toCardItem } = require(\"../utils/listingCard\");
const { publicListingFilter } = require(\"../utils/visibility\");

const SCAN_LIMIT = 100; // newest listings looked at; keeps the query cheap
const FEATURED_LIMIT = 6;
const DESTINATION_LIMIT = 6;

const squash = (value) =>
  String(value ?? \"\")
    .replace(/\\s+/g, \" \")
    .trim();

/**
 * Groups listings by place (case-insensitive location + country) and returns
 * the busiest places first; ties are broken by name so the order is stable.
 * Each destination: { label, search, count, imageUrl }. `search` is the text
 * the listings page gets as ?search=.
 */
function pickDestinations(listings, limit = DESTINATION_LIMIT) {
  const groups = new Map();
  for (const listing of listings) {
    const location = squash(listing && listing.location);
    if (!location) continue;
    const country = squash(listing.country);
    const key = `${location}|${country}`.toLowerCase();
    let group = groups.get(key);
    if (!group) {
      group = {
        label: country ? `${location}, ${country}` : location,
        search: location,
        count: 0,
        imageUrl: null,
      };
      groups.set(key, group);
    }
    group.count += 1;
    if (!group.imageUrl && listing.image && listing.image.url) {
      group.imageUrl = listing.image.url;
    }
  }
  return [...groups.values()]
    .sort((a, b) => b.count - a.count || a.label.localeCompare(b.label))
    .slice(0, Math.max(0, limit));
}

async function loadHomeData(
  ListingModel,
  { scan = SCAN_LIMIT, featured = FEATURED_LIMIT } = {},
) {
  const docs = await ListingModel.find(publicListingFilter())
    .select(\"title image pricing location country\")
    .sort({ _id: -1 })
    .limit(scan)
    .lean();
  const listings = Array.isArray(docs) ? docs : [];
  return {
    featured: listings.slice(0, featured).map(toCardItem),
    destinations: pickDestinations(listings),
  };
}

module.exports = { loadHomeData, pickDestinations };

// The host's reservation calendar (P13-T02): all of a host's listings in one
// month, one row per listing, one cell per night, coloured (and worded) by what
// holds the night. Read-only; blocking nights is the per-listing calendar of
// P07-T03 and answering requests is the inbox of P09-T02.
//
// Source of truth for the nights is the night ledger (ADR-004), as in the
// per-listing calendar: a reserved night, a live request hold and a host block
// are all rows in it; a hold that has run out counts as free. The reservations
// behind the ledger rows give each cell its status and its link. Only this
// host's reservations are read.
//
//   monthOverview({ ... }, hostId, monthValue, { now }) -> plain data for the view
const {
  BOOKING_WINDOW,
  DEFAULT_TIMEZONE,
  addDays,
  addMonths,
  daysInMonth,
  formatDateOnly,
  formatMonthKey,
  isAfter,
  isBefore,
  isoWeekday,
  parseMonthKey,
  startOfMonth,
  todayIn,
} = require(\"../utils/dates\");

const MONTHS_BACK = 12;
const MAX_LISTINGS = 50;
const SHOWN_STATUSES = [\"published\", \"unpublished\", \"suspended\"]; // not drafts

const MONTH_NAMES = Object.freeze([
  \"January\",
  \"February\",
  \"March\",
  \"April\",
  \"May\",
  \"June\",
  \"July\",
  \"August\",
  \"September\",
  \"October\",
  \"November\",
  \"December\",
]);
const WEEKDAYS = Object.freeze([
  { short: \"M\", long: \"Monday\" },
  { short: \"T\", long: \"Tuesday\" },
  { short: \"W\", long: \"Wednesday\" },
  { short: \"T\", long: \"Thursday\" },
  { short: \"F\", long: \"Friday\" },
  { short: \"S\", long: \"Saturday\" },
  { short: \"S\", long: \"Sunday\" },
]);

// What holds a night. `letter` is a visual hint only: the state is always also
// written in words (never colour or a letter alone).
const STATES = Object.freeze({
  requested: {
    letter: \"R\",
    label: \"Request\",
    word: \"request awaiting your answer\",
  },
  booked: { letter: \"B\", label: \"Booked\", word: \"booked\" },
  stayed: { letter: \"S\", label: \"Stayed\", word: \"stay completed\" },
  blocked: { letter: \"X\", label: \"Blocked\", word: \"blocked by you\" },
});

const idText = (v) => String(v && v._id ? v._id : v);

function monthBounds(today) {
  return {
    min: addMonths(startOfMonth(today), -MONTHS_BACK),
    max: startOfMonth(addDays(today, BOOKING_WINDOW.MAX_HORIZON_DAYS)),
  };
}

/** The month asked for (YYYY-MM), else this month, kept inside the bounds. */
function resolveMonth(value, today) {
  const { min, max } = monthBounds(today);
  let month = parseMonthKey(value) || startOfMonth(today);
  if (isBefore(month, min)) month = min;
  if (isAfter(month, max)) month = max;
  return month;
}

function stateOf(row, reservation) {
  if (row.source.kind === \"block\") return \"blocked\";
  if (!reservation) return \"booked\";
  if (reservation.status === \"pending\") return \"requested\";
  if (reservation.status === \"completed\") return \"stayed\";
  return \"booked\";
}

/**
 * @param {{ ListingModel?, StayNightModel?, ReservationModel? }} deps
 * @param {*} hostId  the signed-in user's id
 * @param {string} [monthValue]  \"YYYY-MM\"
 * @param {{ now?: Date }} [options]
 */
async function monthOverview(
  {
    ListingModel = require(\"../models/listing\"),
    StayNightModel = require(\"../models/stayNight\"),
    ReservationModel = require(\"../models/reservation\"),
  } = {},
  hostId,
  monthValue,
  { now = new Date() } = {},
) {
  const today = todayIn(DEFAULT_TIMEZONE, now);
  const { min, max } = monthBounds(today);
  const month = resolveMonth(monthValue, today);
  const next = addMonths(month, 1);
  const monthKey = formatMonthKey(month);

  const found = await ListingModel.find({
    owner: hostId,
    deletedAt: null,
    status: { $in: SHOWN_STATUSES },
  })
    .select(\"title status\")
    .sort({ title: 1, _id: 1 })
    .limit(MAX_LISTINGS + 1)
    .lean();
  const truncated = found.length > MAX_LISTINGS;
  const listings = found.slice(0, MAX_LISTINGS);

  let nights = [];
  let reservations = new Map();
  if (listings.length > 0) {
    nights = (
      await StayNightModel.find({
        listing: { $in: listings.map((l) => l._id) },
        date: { $gte: month, $lt: next },
      })
        .select(\"listing date source holdExpiresAt\")
        .lean()
    ).filter((row) => !(row.holdExpiresAt && row.holdExpiresAt <= now)); // a lapsed hold is free
    const ids = [
      ...new Set(
        nights
          .filter((n) => n.source.kind === \"reservation\")
          .map((n) => idText(n.source.id)),
      ),
    ];
    if (ids.length > 0) {
      const docs = await ReservationModel.find({
        _id: { $in: ids },
        host: hostId,
      })
        .select(\"status guest checkIn checkOut\")
        .populate(\"guest\", \"displayName username\")
        .lean();
      reservations = new Map(docs.map((r) => [idText(r._id), r]));
    }
  }
  const byNight = new Map(
    nights.map((n) => [`${idText(n.listing)}|${n.date.getTime()}`, n]),
  );

  const days = [];
  for (let i = 0; i < daysInMonth(month); i += 1) {
    const date = addDays(month, i);
    const weekday = isoWeekday(date);
    days.push({
      day: date.getUTCDate(),
      iso: formatDateOnly(date),
      weekday: WEEKDAYS[weekday],
      weekend: weekday >= 5,
      today: date.getTime() === today.getTime(),
      date,
    });
  }

  const totals = { requested: 0, booked: 0, stayed: 0, blocked: 0 };
  const rows = listings.map((listing) => {
    const counts = { requested: 0, booked: 0, stayed: 0, blocked: 0 };
    const cells = days.map((day) => {
      const row = byNight.get(`${idText(listing._id)}|${day.date.getTime()}`);
      const dayWords = `${WEEKDAYS[isoWeekday(day.date)].long} ${day.day} ${MONTH_NAMES[month.getUTCMonth()]}`;
      if (!row)
        return {
          state: \"free\",
          day: day.day,
          today: day.today,
          srLabel: `${dayWords}: available`,
        };
      const reservation =
        row.source.kind === \"reservation\"
          ? reservations.get(idText(row.source.id))
          : null;
      const state = stateOf(row, reservation);
      counts[state] += 1;
      totals[state] += 1;
      const guest =
        reservation &&
        reservation.guest &&
        typeof reservation.guest === \"object\"
          ? reservation.guest.displayName || reservation.guest.username
          : null;
      return {
        state,
        letter: STATES[state].letter,
        day: day.day,
        today: day.today,
        href: reservation
          ? `/trips/${idText(reservation._id)}`
          : state === \"blocked\"
            ? `/host/listings/${idText(listing._id)}/calendar?month=${monthKey}`
            : null,
        srLabel: `${dayWords}: ${STATES[state].word}${guest ? `, guest ${guest}` : \"\"}`,
      };
    });
    return {
      listing: {
        id: idText(listing._id),
        title: listing.title,
        status: listing.status,
        calendarUrl: `/host/listings/${idText(listing._id)}/calendar?month=${monthKey}`,
      },
      cells,
      counts,
    };
  });

  return {
    monthKey,
    label: `${MONTH_NAMES[month.getUTCMonth()]} ${month.getUTCFullYear()}`,
    prevKey: isAfter(month, min) ? formatMonthKey(addMonths(month, -1)) : null,
    nextKey: isBefore(month, max) ? formatMonthKey(addMonths(month, 1)) : null,
    days: days.map((d) => ({
      day: d.day,
      iso: d.iso,
      weekday: d.weekday,
      weekend: d.weekend,
      today: d.today,
    })),
    rows,
    totals,
    truncated,
    limit: MAX_LISTINGS,
    legend: Object.entries(STATES).map(([key, s]) => ({
      key,
      letter: s.letter,
      label: s.label,
      word: s.word,
    })),
  };
}

module.exports = {
  monthOverview,
  resolveMonth,
  monthBounds,
  STATES,
  MAX_LISTINGS,
  MONTHS_BACK,
};

// The host's reservations inbox (P09-T02): what is waiting for an answer, what
// is confirmed, and accepting or declining a request. Moving the booking is
// services/reservations.js `transition` (compare-and-set); this file adds who
// may do it, the listing check, the reason and the page's data.
//
//   listInbox({ ... }, hostId, { now })      -> { pending, confirmed, truncated }
//   respond({ ... }, { id, user, decision, reason, now })
//        decision \"accept\" | \"decline\"; returns the updated reservation
const { can } = require(\"../policies\");
const { ConflictError, NotFoundError } = require(\"../utils/errors\");
const { DEFAULT_TIMEZONE, todayIn } = require(\"../utils/dates\");
const { formatMoney } = require(\"../utils/money\");
const { formatStayDate, formatInstant, referenceOf } = require(\"./trips\");
const { parseReason, REASON_MAX } = require(\"../utils/reason\");

const LIMIT = 50; // per section; a bigger backlog is shown as \"showing the first 50\"
const OBJECT_ID = /^[0-9a-f]{24}$/i;

const plural = (n, one, many) => `${n} ${n === 1 ? one : many}`;

/** \"5 h 12 min\", \"42 min\", \"less than a minute\", or \"\" once it has passed. */
function countdownText(expiresAt, now) {
  const ms = expiresAt.getTime() - now.getTime();
  if (ms <= 0) return \"\";
  const minutes = Math.floor(ms / 60000);
  if (minutes < 1) return \"less than a minute\";
  const hours = Math.floor(minutes / 60);
  const rest = minutes % 60;
  if (hours >= 24) {
    const days = Math.floor(hours / 24);
    return `${plural(days, \"day\", \"days\")} ${hours % 24} h`;
  }
  return hours > 0 ? `${hours} h ${rest} min` : `${rest} min`;
}

const idText = (v) => String(v && v._id ? v._id : v);

function guestSummary(guest, previousStays) {
  if (
    !guest ||
    typeof guest !== \"object\" ||
    typeof guest.toHexString === \"function\"
  ) {
    return {
      name: \"A guest\",
      profileUrl: null,
      memberSince: null,
      previousStays,
    };
  }
  return {
    name: guest.displayName || guest.username || \"A guest\",
    profileUrl: `/users/${idText(guest)}`,
    memberSince: guest.createdAt
      ? new Intl.DateTimeFormat(\"en-IN\", {
          month: \"short\",
          year: \"numeric\",
          timeZone: \"UTC\",
        }).format(guest.createdAt)
      : null,
    previousStays,
  };
}

function describeInboxRow(reservation, { previousStays, now }) {
  const snap = reservation.listingSnapshot || {};
  const price = reservation.pricingSnapshot || {};
  const expiresAt =
    reservation.holdExpiresAt instanceof Date
      ? reservation.holdExpiresAt
      : null;
  const waiting =
    reservation.status === \"pending\" && expiresAt && expiresAt > now;
  return {
    id: idText(reservation._id),
    reference: referenceOf(reservation),
    status: reservation.status,
    listingTitle: snap.title || \"Your place\",
    checkIn: formatStayDate(reservation.checkIn),
    checkOut: formatStayDate(reservation.checkOut),
    nights: reservation.nights,
    guests: reservation.guests,
    guestTotal: Number.isSafeInteger(price.totalMinor)
      ? formatMoney(price.totalMinor, price.currency || \"INR\")
      : null,
    guest: guestSummary(
      reservation.guest,
      previousStays.get(idText(reservation.guest)) || 0,
    ),
    // A request can be answered only while its hold is running.
    canAnswer: Boolean(waiting),
    expiresAtIso: waiting ? expiresAt.toISOString() : null,
    expiresAtMs: waiting ? expiresAt.getTime() : null,
    expiresText: waiting ? countdownText(expiresAt, now) : null,
    expiresAt: expiresAt ? formatInstant(expiresAt, snap.timezone) : null,
    instantBook: Boolean(snap.instantBook),
  };
}

/**
 * Pending requests first (soonest deadline first), then confirmed stays that
 * are not over (soonest check-in first), each with a guest summary: name,
 * member since, and how many stays that guest has completed with this host.
 */
/**
 * The two inbox lists as data (filter and sort). The query-plan review
 * (src/services/queryPlans.js) reads these, so what is checked against the
 * indexes is what the inbox runs.
 */
function inboxQueries(hostId, today) {
  return {
    pending: {
      filter: { host: hostId, status: \"pending\" },
      sort: { holdExpiresAt: 1, _id: 1 },
    },
    confirmed: {
      filter: { host: hostId, status: \"confirmed\", checkOut: { $gt: today } },
      sort: { checkIn: 1, _id: 1 },
    },
  };
}

async function listInbox(
  { ReservationModel = require(\"../models/reservation\") } = {},
  hostId,
  { now = new Date() } = {},
) {
  const today = todayIn(DEFAULT_TIMEZONE, now);
  const populateGuest = \"displayName username createdAt\";
  const queries = inboxQueries(hostId, today);
  const [pendingRows, confirmedRows] = await Promise.all([
    ReservationModel.find(queries.pending.filter)
      .sort(queries.pending.sort)
      .limit(LIMIT + 1)
      .populate(\"guest\", populateGuest)
      .lean(),
    ReservationModel.find(queries.confirmed.filter)
      .sort(queries.confirmed.sort)
      .limit(LIMIT + 1)
      .populate(\"guest\", populateGuest)
      .lean(),
  ]);

  const rows = [
    ...pendingRows.slice(0, LIMIT),
    ...confirmedRows.slice(0, LIMIT),
  ];
  const guestIds = [...new Set(rows.map((r) => idText(r.guest)))];
  const previousStays = new Map();
  if (guestIds.length > 0) {
    const grouped = await ReservationModel.aggregate([
      {
        $match: {
          host: hostId,
          status: \"completed\",
          guest: { $in: rows.map((r) => (r.guest && r.guest._id) || r.guest) },
        },
      },
      { $group: { _id: \"$guest\", count: { $sum: 1 } } },
    ]);
    for (const g of grouped) previousStays.set(String(g._id), g.count);
  }

  return {
    pending: pendingRows
      .slice(0, LIMIT)
      .map((r) => describeInboxRow(r, { previousStays, now })),
    confirmed: confirmedRows
      .slice(0, LIMIT)
      .map((r) => describeInboxRow(r, { previousStays, now })),
    truncated: pendingRows.length > LIMIT || confirmedRows.length > LIMIT,
    limit: LIMIT,
  };
}

/**
 * Accept or decline one request as its host.
 * - 404 when the booking does not exist or is not this user's to answer (the
 *   same answer for both);
 * - accepting needs a live listing that is not suspended (409 listing_suspended);
 *   declining is always possible, so a host can clear a request on a listing
 *   that was taken down;
 * - an expired request cannot be accepted (409 hold_expired) and one already
 *   answered gives the status that won (409), both from `transition`.
 */
async function respond(
  {
    ReservationModel = require(\"../models/reservation\"),
    ListingModel = require(\"../models/listing\"),
    reservationService = require(\"./reservations\"),
  } = {},
  { id, user, decision, reason, now = new Date() },
) {
  if (decision !== \"accept\" && decision !== \"decline\")
    throw new TypeError(\"decision must be accept or decline\");
  const note = decision === \"decline\" ? parseReason(reason) : \"\";
  const reservation = OBJECT_ID.test(String(id))
    ? await ReservationModel.findById(id)
    : null;
  if (!reservation || !can(\"reservation:respond\", user, reservation)) {
    throw new NotFoundError(\"That booking request does not exist.\");
  }

  if (decision === \"accept\") {
    const listing = await ListingModel.findById(reservation.listing).select(
      \"status deletedAt\",
    );
    if (!listing || listing.deletedAt || listing.status === \"suspended\") {
      throw new ConflictError(
        \"This listing is suspended or no longer exists, so the request cannot be accepted. You can still decline it.\",
        { code: \"listing_suspended\" },
      );
    }
  }

  return reservationService.transition(
    reservation._id,
    decision === \"accept\" ? \"confirmed\" : \"declined\",
    {
      actor: \"host\",
      by: user._id,
      reason: note || undefined,
      now,
    },
  );
}

module.exports = {
  listInbox,
  inboxQueries,
  respond,
  parseReason,
  countdownText,
  describeInboxRow,
  REASON_MAX,
  LIMIT,
};

// \"My listings\" (P04-T06): one row per listing a host owns, with its state, how
// far along the readiness checklist it is, when it last changed, and the
// actions that make sense for that state. The rows are plain data so the page
// stays simple and the rules are easy to test.
const { evaluateReadiness } = require(\"./readiness\");
const { galleryOf } = require(\"./images\");

const MAX_ROWS = 100;

const STATUS = Object.freeze({
  draft: { label: \"Draft\", variant: \"warning\" },
  published: { label: \"Published\", variant: \"success\" },
  unpublished: { label: \"Unpublished\", variant: \"neutral\" },
  suspended: { label: \"Suspended\", variant: \"danger\" },
});

const dayFormat = new Intl.DateTimeFormat(\"en-IN\", {
  day: \"numeric\",
  month: \"short\",
  year: \"numeric\",
  timeZone: \"Asia/Kolkata\", // ADR-008
});

/** \"17 Oct 2026\" for a Date; \"\" for anything that is not a valid Date. */
function formatDay(date) {
  return date instanceof Date && !Number.isNaN(date.getTime())
    ? dayFormat.format(date)
    : \"\";
}

/**
 * What the host can do from the list.
 * Each action is { kind: \"link\" | \"post\", label, href, primary? }; a \"post\" is
 * rendered as a small form with a CSRF token.
 */
function actionsFor({ id, status, canPublish }) {
  const base = `/host/listings/${id}`;
  const statusLink = { kind: \"link\", label: \"Status and checklist\", href: `${base}/status` };
  const calendarLink = { kind: \"link\", label: \"Calendar\", href: `${base}/calendar` };
  switch (status) {
    case \"draft\":
      return [{ kind: \"link\", label: \"Continue\", href: base, primary: true }, statusLink];
    case \"published\":
      return [
        { kind: \"link\", label: \"View\", href: `/listings/${id}`, primary: true },
        { kind: \"link\", label: \"Edit\", href: `/listings/${id}/edit` },
        calendarLink,
        statusLink,
        { kind: \"post\", label: \"Unpublish\", href: `${base}/unpublish` },
      ];
    case \"unpublished\":
      return [
        { kind: \"link\", label: \"Edit\", href: `/listings/${id}/edit`, primary: !canPublish },
        calendarLink,
        statusLink,
        ...(canPublish
          ? [{ kind: \"post\", label: \"Publish\", href: `${base}/publish`, primary: true }]
          : []),
      ];
    default: // suspended, or a state added later: nothing to change from here
      return [statusLink];
  }
}

/** One row of the table from a listing (document or plain object). */
function toRow(listing) {
  const status = Object.hasOwn(STATUS, listing.status) ? listing.status : \"draft\";
  const readiness = evaluateReadiness(listing);
  const id = String(listing._id);
  const cover = galleryOf(listing)[0];
  const where = [listing.get ? listing.get(\"address.city\") : listing.address?.city, listing.country]
    .filter(Boolean)
    .join(\", \");
  const updatedAt = listing.updatedAt instanceof Date ? listing.updatedAt : null;
  return {
    id,
    title: listing.title || \"Untitled listing\",
    where,
    coverUrl: cover ? cover.url : null,
    status,
    statusLabel: STATUS[status].label,
    statusVariant: STATUS[status].variant,
    score: readiness.score,
    canPublish: readiness.canPublish,
    missing: readiness.checks.filter((check) => !check.passed).length,
    updatedIso: updatedAt ? updatedAt.toISOString() : \"\",
    updatedLabel: formatDay(updatedAt),
    actions: actionsFor({ id, status, canPublish: readiness.canPublish }),
  };
}

/**
 * The host's own listings, newest change first, without deleted ones.
 * @returns {Promise<{ rows: object[], truncated: boolean }>}
 */
async function loadHostListings(Listing, ownerId, { limit = MAX_ROWS } = {}) {
  const found = await Listing.find({ owner: ownerId, deletedAt: null })
    .sort({ updatedAt: -1, _id: -1 })
    .limit(limit + 1);
  const listings = Array.isArray(found) ? found : [];
  return {
    rows: listings.slice(0, limit).map(toRow),
    truncated: listings.length > limit,
  };
}

module.exports = {
  MAX_ROWS,
  STATUS,
  formatDay,
  actionsFor,
  toRow,
  loadHostListings,
};

// The host's overview (P13-T01): four tiles, each a number a host can act on
// and each linking to the list it comes from. No charts.
//
//   Waiting for you    pending requests whose hold is still running, and when the
//                      soonest one runs out            -> /host/reservations
//   Next 7 days        confirmed check-ins and check-outs from today to six days
//                      ahead                           -> /host/reservations#inbox-confirmed
//   Estimated earnings what the host would receive for confirmed and completed
//                      stays that START this month. An ESTIMATE: Dimora pays
//                      nothing out yet  -> /host/calendar
//   Occupancy          booked nights / (published listings x 30 - blocked nights)
//                      over the next 30 nights, from the night ledger -> /host/calendar
//
// \"Host receivable\" of a booking is the stored price lines `nights`,
// `weekend_nights` and `cleaning`: what the host sets. The guest service fee is
// Dimora's and the tax line is passed on, so neither is counted. This is a
// definition for an estimate, not an accounting rule (ADR-009: payments are
// simulated).
const {
  DEFAULT_TIMEZONE,
  addDays,
  addMonths,
  startOfMonth,
  todayIn,
} = require(\"../utils/dates\");

const RECEIVABLE_CODES = Object.freeze([
  \"nights\",
  \"weekend_nights\",
  \"season_nights\",
  \"season_weekend_nights\",
  \"cleaning\",
]);
// A negative line the host gives up (P08-T04): taken off what they receive.
const DISCOUNT_CODE = \"length_discount\";
const WEEK_DAYS = 7;
const OCCUPANCY_DAYS = 30;
const LIST_LIMIT = 5;
const FETCH_LIMIT = 500;

const idText = (v) => String(v && v._id ? v._id : v);

/** What the host would receive for one stored price, in integer paise (0 if unreadable). */
function hostReceivableMinor(pricingSnapshot) {
  const lines =
    pricingSnapshot && Array.isArray(pricingSnapshot.lines)
      ? pricingSnapshot.lines
      : [];
  const gross = lines
    .filter(
      (l) =>
        l &&
        RECEIVABLE_CODES.includes(l.code) &&
        Number.isSafeInteger(l.amountMinor) &&
        l.amountMinor > 0,
    )
    .reduce((total, l) => total + l.amountMinor, 0);
  const discount = lines
    .filter((l) => l && l.code === DISCOUNT_CODE && Number.isSafeInteger(l.amountMinor) && l.amountMinor < 0)
    .reduce((total, l) => total - l.amountMinor, 0);
  return Math.max(0, gross - discount);
}

/** A whole percent, or null when there is nothing to divide by. */
function occupancyPercent(bookedNights, availableNights) {
  if (!(availableNights > 0)) return null;
  return Math.round((bookedNights / availableNights) * 100);
}

function guestName(reservation) {
  const g = reservation.guest;
  return g && typeof g === \"object\" && typeof g.toHexString !== \"function\"
    ? g.displayName || g.username || \"A guest\"
    : \"A guest\";
}

function stayRow(reservation, date) {
  const snap = reservation.listingSnapshot || {};
  return {
    id: idText(reservation._id),
    title: snap.title || \"Your place\",
    guest: guestName(reservation),
    guests: reservation.guests,
    date,
  };
}

/**
 * @param {{ ListingModel?, ReservationModel?, StayNightModel? }} deps
 * @param {*} hostId
 * @param {{ now?: Date }} [options]
 */
async function overview(
  {
    ListingModel = require(\"../models/listing\"),
    ReservationModel = require(\"../models/reservation\"),
    StayNightModel = require(\"../models/stayNight\"),
  } = {},
  hostId,
  { now = new Date() } = {},
) {
  const today = todayIn(DEFAULT_TIMEZONE, now);
  const weekEnd = addDays(today, WEEK_DAYS);
  const monthStart = startOfMonth(today);
  const nextMonth = addMonths(monthStart, 1);
  const horizon = addDays(today, OCCUPANCY_DAYS);

  const [listings, pending, week, earned] = await Promise.all([
    ListingModel.find({
      owner: hostId,
      deletedAt: null,
      status: { $in: [\"published\", \"unpublished\", \"suspended\"] },
    })
      .select(\"status\")
      .lean(),
    ReservationModel.find({
      host: hostId,
      status: \"pending\",
      holdExpiresAt: { $gt: now },
    })
      .sort({ holdExpiresAt: 1, _id: 1 })
      .limit(FETCH_LIMIT)
      .select(\"holdExpiresAt\")
      .lean(),
    ReservationModel.find({
      host: hostId,
      status: \"confirmed\",
      $or: [
        { checkIn: { $gte: today, $lt: weekEnd } },
        { checkOut: { $gte: today, $lt: weekEnd } },
      ],
    })
      .sort({ checkIn: 1, _id: 1 })
      .limit(FETCH_LIMIT)
      .populate(\"guest\", \"displayName username\")
      .select(\"guest guests checkIn checkOut listingSnapshot\")
      .lean(),
    ReservationModel.find({
      host: hostId,
      status: { $in: [\"confirmed\", \"completed\"] },
      checkIn: { $gte: monthStart, $lt: nextMonth },
    })
      .limit(FETCH_LIMIT)
      .select(\"pricingSnapshot\")
      .lean(),
  ]);

  const inWindow = (date) => date >= today && date < weekEnd;
  const checkIns = week.filter((r) => inWindow(r.checkIn));
  const checkOuts = week.filter((r) => inWindow(r.checkOut));

  // Occupancy: published listings only; nights held by confirmed or completed
  // stays are booked, host blocks are not available; a pending request counts
  // as neither (it may still be answered no).
  const published = listings.filter((l) => l.status === \"published\");
  let booked = 0;
  let blocked = 0;
  if (published.length > 0) {
    const rows = (
      await StayNightModel.find({
        listing: { $in: published.map((l) => l._id) },
        date: { $gte: today, $lt: horizon },
      })
        .select(\"source holdExpiresAt\")
        .lean()
    ).filter((r) => !(r.holdExpiresAt && r.holdExpiresAt <= now));
    const ids = [
      ...new Set(
        rows
          .filter((r) => r.source.kind === \"reservation\")
          .map((r) => idText(r.source.id)),
      ),
    ];
    const statuses = new Map();
    if (ids.length > 0) {
      const docs = await ReservationModel.find({
        _id: { $in: ids },
        host: hostId,
      })
        .select(\"status\")
        .lean();
      for (const d of docs) statuses.set(idText(d._id), d.status);
    }
    for (const row of rows) {
      if (row.source.kind === \"block\") blocked += 1;
      else if (
        [\"confirmed\", \"completed\"].includes(statuses.get(idText(row.source.id)))
      )
        booked += 1;
    }
  }
  const available = published.length * OCCUPANCY_DAYS - blocked;

  return {
    listingCount: listings.length,
    pending: {
      count: pending.length,
      soonestExpiry: pending.length > 0 ? pending[0].holdExpiresAt : null,
      capped: pending.length >= FETCH_LIMIT,
    },
    week: {
      days: WEEK_DAYS,
      checkIns: checkIns.length,
      checkOuts: checkOuts.length,
      upcomingCheckIns: checkIns
        .slice(0, LIST_LIMIT)
        .map((r) => stayRow(r, r.checkIn)),
      upcomingCheckOuts: checkOuts
        .slice(0, LIST_LIMIT)
        .map((r) => stayRow(r, r.checkOut)),
      capped: week.length >= FETCH_LIMIT,
    },
    earnings: {
      estimateMinor: earned.reduce(
        (t, r) => t + hostReceivableMinor(r.pricingSnapshot),
        0,
      ),
      stays: earned.length,
      monthStart,
      capped: earned.length >= FETCH_LIMIT,
    },
    occupancy: {
      days: OCCUPANCY_DAYS,
      percent: occupancyPercent(booked, available),
      bookedNights: booked,
      blockedNights: blocked,
      availableNights: Math.max(available, 0),
      listings: published.length,
    },
  };
}

module.exports = {
  overview,
  hostReceivableMinor,
  occupancyPercent,
  RECEIVABLE_CODES,
  WEEK_DAYS,
  OCCUPANCY_DAYS,
};

// Earnings and occupancy report for one host (P13-T04): one row per listing
// for a range of whole months, as a page and as a CSV.
//
// Definitions (the same as the overview tiles, P13-T01; an ESTIMATE, nothing is
// paid out - ADR-009):
//   bookings        confirmed or completed stays whose check-in is in the range
//   earnings        host receivable of those stays (nights + weekend nights +
//                   cleaning; the guest service fee and tax are not the host's)
//   nights booked   nights of confirmed or completed stays that fall inside the
//                   range, whichever month the stay started in
//   nights blocked  nights the host blocked inside the range
//   occupancy       booked / (days in the range - blocked), whole percent,
//                   at most 100; none when every night is blocked
// Requests still waiting, declined, expired and cancelled stays are not counted.
// Future nights only count once reserved. Days are India time (ADR-008).
// Money is integer paise per currency; totals are per currency, never mixed.
const {
  DEFAULT_TIMEZONE,
  addDays,
  addMonths,
  formatDateOnly,
  formatMonthKey,
  parseMonthKey,
  startOfMonth,
  todayIn,
} = require(\"../utils/dates\");
const { ValidationError } = require(\"../utils/errors\");
const { hostReceivableMinor } = require(\"./hostOverview\");

const MAX_MONTHS = 12; // longest range
const LOOK_BACK_MONTHS = 24; // earliest month offered
const LOOK_AHEAD_MONTHS = 12; // latest month offered
const DEFAULT_MONTHS = 3;
const FETCH_LIMIT = 5000;
const MS_DAY = 24 * 60 * 60 * 1000;

const idText = (v) => String(v && v._id ? v._id : v);
const monthDiff = (a, b) =>
  (b.getUTCFullYear() - a.getUTCFullYear()) * 12 + (b.getUTCMonth() - a.getUTCMonth());

/**
 * The range from the query: `from` and `to` are \"YYYY-MM\" (both optional, the
 * last 3 months by default). Throws ValidationError for anything else.
 * @returns {{from: Date, to: Date, start: Date, end: Date, days: number, fromKey: string, toKey: string}}
 *   start is the first day, end the first day AFTER the range (exclusive).
 */
function parseRange(query = {}, { now = new Date() } = {}) {
  const thisMonth = startOfMonth(todayIn(DEFAULT_TIMEZONE, now));
  const one = (v) => (typeof v === \"string\" ? v : undefined);
  const rawFrom = one(query.from);
  const rawTo = one(query.to);
  if ((query.from !== undefined && rawFrom === undefined) || (query.to !== undefined && rawTo === undefined)) {
    throw new ValidationError(\"Choose the months as YYYY-MM.\");
  }
  const badMonth = () => new ValidationError(\"Choose the months as YYYY-MM, for example 2026-10.\");
  const to = rawTo ? parseMonthKey(rawTo) : thisMonth;
  if (!to) throw badMonth();
  const from = rawFrom ? parseMonthKey(rawFrom) : addMonths(to, -(DEFAULT_MONTHS - 1));
  if (!from) throw badMonth();
  if (monthDiff(from, to) < 0) throw new ValidationError(\"The first month cannot be after the last month.\");
  if (monthDiff(from, to) + 1 > MAX_MONTHS) {
    throw new ValidationError(`A report can cover at most ${MAX_MONTHS} months.`);
  }
  if (monthDiff(from, thisMonth) > LOOK_BACK_MONTHS || monthDiff(thisMonth, to) > LOOK_AHEAD_MONTHS) {
    throw new ValidationError(
      `Choose months from the last ${LOOK_BACK_MONTHS} months to the next ${LOOK_AHEAD_MONTHS}.`,
    );
  }
  const start = from;
  const end = addMonths(to, 1);
  return {
    from,
    to,
    start,
    end,
    days: Math.round((end.getTime() - start.getTime()) / MS_DAY),
    fromKey: formatMonthKey(from),
    toKey: formatMonthKey(to),
  };
}

/** Nights of [checkIn, checkOut) that lie inside [start, end). */
function overlapNights(checkIn, checkOut, start, end) {
  const lo = Math.max(checkIn.getTime(), start.getTime());
  const hi = Math.min(checkOut.getTime(), end.getTime());
  return hi > lo ? Math.round((hi - lo) / MS_DAY) : 0;
}

/** A whole percent (0 to 100) or null when nothing was available. */
function occupancyPercent(booked, available) {
  if (!(available > 0)) return null;
  return Math.min(100, Math.round((booked / available) * 100));
}

async function buildReport(
  {
    ListingModel = require(\"../models/listing\"),
    ReservationModel = require(\"../models/reservation\"),
    StayNightModel = require(\"../models/stayNight\"),
  } = {},
  hostId,
  query,
  { now = new Date() } = {},
) {
  const range = parseRange(query, { now });
  const { start, end, days } = range;

  const listings = await ListingModel.find({
    owner: hostId,
    deletedAt: null,
    status: { $in: [\"published\", \"unpublished\", \"suspended\"] },
  })
    .sort({ title: 1, _id: 1 })
    .limit(50)
    .select(\"title status pricing.currency\")
    .lean();
  const ids = listings.map((l) => l._id);

  const [stays, blocks] = ids.length
    ? await Promise.all([
        ReservationModel.find({
          host: hostId,
          listing: { $in: ids },
          status: { $in: [\"confirmed\", \"completed\"] },
          checkIn: { $lt: end },
          checkOut: { $gt: start },
        })
          .limit(FETCH_LIMIT)
          .select(\"listing checkIn checkOut pricingSnapshot\")
          .lean(),
        StayNightModel.find({
          listing: { $in: ids },
          \"source.kind\": \"block\",
          date: { $gte: start, $lt: end },
        })
          .limit(FETCH_LIMIT * 10)
          .select(\"listing\")
          .lean(),
      ])
    : [[], []];

  const byListing = new Map(
    listings.map((l) => [
      idText(l._id),
      {
        id: idText(l._id),
        title: l.title,
        status: l.status,
        currency: (l.pricing && l.pricing.currency) || \"INR\",
        bookings: 0,
        nightsBooked: 0,
        nightsBlocked: 0,
        earningsMinor: 0,
      },
    ]),
  );

  for (const stay of stays) {
    const row = byListing.get(idText(stay.listing));
    if (!row) continue;
    const snap = stay.pricingSnapshot || {};
    if (snap.currency) row.currency = snap.currency;
    row.nightsBooked += overlapNights(stay.checkIn, stay.checkOut, start, end);
    if (stay.checkIn >= start && stay.checkIn < end) {
      row.bookings += 1;
      row.earningsMinor += hostReceivableMinor(snap);
    }
  }
  for (const block of blocks) {
    const row = byListing.get(idText(block.listing));
    if (row) row.nightsBlocked += 1;
  }

  const rows = [...byListing.values()].map((row) => {
    const available = Math.max(0, days - row.nightsBlocked);
    return {
      ...row,
      nightsAvailable: available,
      occupancy: occupancyPercent(row.nightsBooked, available),
    };
  });

  // Totals per currency; occupancy over the listings in that currency.
  const totals = new Map();
  for (const row of rows) {
    const t = totals.get(row.currency) || {
      currency: row.currency,
      listings: 0,
      bookings: 0,
      nightsBooked: 0,
      nightsAvailable: 0,
      earningsMinor: 0,
    };
    t.listings += 1;
    t.bookings += row.bookings;
    t.nightsBooked += row.nightsBooked;
    t.nightsAvailable += row.nightsAvailable;
    t.earningsMinor += row.earningsMinor;
    totals.set(row.currency, t);
  }

  return {
    range: {
      fromKey: range.fromKey,
      toKey: range.toKey,
      firstDay: formatDateOnly(start),
      lastDay: formatDateOnly(addDays(end, -1)),
      days,
    },
    rows,
    totals: [...totals.values()].map((t) => ({
      ...t,
      occupancy: occupancyPercent(t.nightsBooked, t.nightsAvailable),
    })),
    capped: stays.length >= FETCH_LIMIT,
    listingsShown: listings.length,
  };
}

// ---- CSV ----------------------------------------------------------------

/** Integer minor units as a plain decimal string (\"1234.50\"), no float involved. */
function minorToDecimal(minor, digits = 2) {
  if (!Number.isSafeInteger(minor)) throw new TypeError(\"minor must be a safe integer\");
  if (digits === 0) return String(minor);
  const sign = minor < 0 ? \"-\" : \"\";
  const abs = String(Math.abs(minor)).padStart(digits + 1, \"0\");
  return `${sign}${abs.slice(0, -digits)}.${abs.slice(-digits)}`;
}

/**
 * One CSV cell. Quoted per RFC 4180, and a text that a spreadsheet would run as
 * a formula (starts with = + - @ or a tab/return) is made safe with a leading
 * apostrophe.
 */
function csvCell(value) {
  let text = value === null || value === undefined ? \"\" : String(value);
  if (/^[=+\\-@\\t\\r]/.test(text)) text = `'${text}`;
  return /[\",\\r\\n]/.test(text) ? `\"${text.replace(/\"/g, '\"\"')}\"` : text;
}

/** Decimal places of a currency's minor unit (2 for INR, 0 for JPY). */
const currencyDigits = (currency) =>
  new Intl.NumberFormat(\"en\", { style: \"currency\", currency }).resolvedOptions().maximumFractionDigits;

const CSV_HEADER = [
  \"listing\",
  \"listing_id\",
  \"status\",
  \"period_first_day\",
  \"period_last_day\",
  \"bookings_started\",
  \"nights_booked\",
  \"nights_blocked\",
  \"nights_available\",
  \"occupancy_percent\",
  \"earnings_estimate\",
  \"currency\",
];

/** The report as CSV text: UTF-8 with a byte-order mark (so Excel reads it right), CRLF lines. */
function toCsv(report) {
  const lines = [CSV_HEADER.map(csvCell).join(\",\")];
  for (const r of report.rows) {
    lines.push(
      [
        r.title,
        r.id,
        r.status,
        report.range.firstDay,
        report.range.lastDay,
        r.bookings,
        r.nightsBooked,
        r.nightsBlocked,
        r.nightsAvailable,
        r.occupancy === null ? \"\" : r.occupancy,
        minorToDecimal(r.earningsMinor, currencyDigits(r.currency)),
        r.currency,
      ]
        .map(csvCell)
        .join(\",\"),
    );
  }
  return `\\uFEFF${lines.join(\"\\r\\n\")}\\r\\n`;
}

module.exports = {
  buildReport,
  parseRange,
  overlapNights,
  occupancyPercent,
  minorToDecimal,
  currencyDigits,
  csvCell,
  toCsv,
  CSV_HEADER,
  MAX_MONTHS,
  DEFAULT_MONTHS,
};

// Listing photos (P04-T03): checking uploads, storing them, and keeping the
// gallery in order.
//
// A listing's photos live in `listing.images` (see the model). The array order
// is the display order; `order` mirrors it and images[0] is the cover. The old
// `listing.image` field is a mirror of the cover that older pages still read;
// every function here keeps it in step (syncCover).
//
// Uploads are checked BEFORE anything is sent to Cloudinary: size, count and
// the file's real first bytes (the browser-supplied type and the file name
// prove nothing). If any upload fails, the ones that succeeded are deleted
// again and nothing is saved; if the save fails, the uploads are deleted.
const { AppError, ValidationError, NotFoundError } = require(\"../utils/errors\");
const {
  uploadBuffer,
  deleteImage,
  MAX_IMAGE_BYTES,
} = require(\"../config/cloudinary\");

const MAX_IMAGES = 10;
const TEXT_MAX = 200;
// eslint-disable-next-line no-control-regex
const CONTROL_CHARS = /[\\u0000-\\u001f\\u007f]/g;
const ID_PATTERN = /^[0-9a-f]{24}$/i;
const LIMIT_LABEL = `${MAX_IMAGE_BYTES / (1024 * 1024)} MB`;

class UploadFailedError extends AppError {
  constructor(
    message = \"We could not upload your photos just now. Nothing was saved; please try again.\",
    options,
  ) {
    super(502, message, { code: \"upload_failed\", ...options });
  }
}

// ---- Looking at a file --------------------------------------------------

/** \"jpeg\" | \"png\" | \"webp\" from the first bytes of a file, else null. */
function detectImageType(buffer) {
  if (!Buffer.isBuffer(buffer) || buffer.length < 12) return null;
  if (buffer[0] === 0xff && buffer[1] === 0xd8 && buffer[2] === 0xff) {
    return \"jpeg\";
  }
  if (
    buffer[0] === 0x89 &&
    buffer.toString(\"latin1\", 1, 4) === \"PNG\" &&
    buffer[4] === 0x0d &&
    buffer[5] === 0x0a &&
    buffer[6] === 0x1a &&
    buffer[7] === 0x0a
  ) {
    return \"png\";
  }
  if (
    buffer.toString(\"latin1\", 0, 4) === \"RIFF\" &&
    buffer.toString(\"latin1\", 8, 12) === \"WEBP\"
  ) {
    return \"webp\";
  }
  return null;
}

function displayName(file) {
  const raw =
    file && typeof file.originalname === \"string\" ? file.originalname : \"\";
  const clean = raw.replace(CONTROL_CHARS, \"\").trim().slice(0, 60);
  return clean ? `\"${clean}\"` : \"That file\";
}

/** Throws a ValidationError (a message for the host) unless `file` is a real,
 *  small-enough PNG, JPEG or WebP. `file` is a multer memory file. */
function assertValidImage(file) {
  const name = displayName(file);
  if (!file || !Buffer.isBuffer(file.buffer)) {
    throw new ValidationError(
      `${name} could not be read. Please choose it again.`,
    );
  }
  if (file.buffer.length === 0) {
    throw new ValidationError(`${name} is empty.`);
  }
  if (file.buffer.length > MAX_IMAGE_BYTES) {
    throw new ValidationError(`${name} is too large (maximum ${LIMIT_LABEL}).`);
  }
  if (!detectImageType(file.buffer)) {
    throw new ValidationError(`${name} is not a PNG, JPEG or WebP image.`);
  }
}

// ---- Keeping the gallery tidy -------------------------------------------

const byOrder = (a, b) => (a.order ?? 0) - (b.order ?? 0);

function plainText(value, label) {
  if (value === undefined || value === null) return \"\";
  if (typeof value !== \"string\") {
    throw new ValidationError(`${label} must be text.`);
  }
  const clean = value.replace(CONTROL_CHARS, \" \").replace(/\\s+/g, \" \").trim();
  if (clean.length > TEXT_MAX) {
    throw new ValidationError(
      `${label} can be at most ${TEXT_MAX} characters.`,
    );
  }
  return clean;
}

/** A listing saved before the gallery existed has a cover in `image` and an
 *  empty images[]: bring that cover into images[] before changing anything. */
function adoptLegacyCover(listing) {
  if (listing.images.length === 0 && listing.image && listing.image.url) {
    listing.images.push({
      url: listing.image.url,
      publicId: listing.image.filename || \"\",
      alt: \"\",
      caption: \"\",
      order: 0,
    });
  }
}

/** The old `image` field mirrors the cover. */
function syncCover(listing) {
  const cover = listing.images[0];
  listing.set(\"image.url\", cover ? cover.url : undefined);
  listing.set(
    \"image.filename\",
    cover && cover.publicId ? cover.publicId : undefined,
  );
}

/** order = position, then the cover mirror. Call after every change. */
function normalize(listing) {
  listing.images.sort(byOrder);
  listing.images.forEach((image, index) => {
    image.order = index;
  });
  syncCover(listing);
}

function prepare(listing) {
  adoptLegacyCover(listing);
  listing.images.sort(byOrder);
}

function findImage(listing, imageId) {
  const id = String(imageId ?? \"\");
  const image = ID_PATTERN.test(id)
    ? listing.images.find((item) => String(item._id) === id)
    : undefined;
  if (!image) throw new NotFoundError(\"That photo does not exist.\");
  return image;
}

/** What the pages show: [{ id, url, publicId, alt, caption }], cover first.
 *  Falls back to the old `image` field for a listing not yet migrated. */
function galleryOf(listing) {
  const images = (listing && listing.images ? [...listing.images] : [])
    .filter((item) => item && item.url)
    .sort(byOrder)
    .map((item) => ({
      id: String(item._id ?? \"\"),
      url: item.url,
      publicId: item.publicId || \"\",
      alt: item.alt || \"\",
      caption: item.caption || \"\",
    }));
  if (images.length === 0 && listing && listing.image && listing.image.url) {
    return [
      {
        id: \"\",
        url: listing.image.url,
        publicId: listing.image.filename || \"\",
        alt: \"\",
        caption: \"\",
      },
    ];
  }
  return images;
}

// ---- Uploading ------------------------------------------------------------

/** Sends every file to Cloudinary. If one fails, the others are deleted again
 *  and an UploadFailedError is thrown (nothing is left behind). */
async function uploadAll(files, log) {
  const settled = await Promise.allSettled(
    files.map((file) => uploadBuffer(file.buffer)),
  );
  const uploaded = settled
    .filter((item) => item.status === \"fulfilled\")
    .map((item) => item.value);
  const failure = settled.find((item) => item.status === \"rejected\");
  if (failure) {
    await Promise.all(uploaded.map((item) => deleteImage(item.public_id, log)));
    if (log) log.warn({ err: failure.reason }, \"photo upload failed\");
    throw new UploadFailedError(undefined, { cause: failure.reason });
  }
  return uploaded.map((item) => ({
    url: item.secure_url,
    publicId: item.public_id,
  }));
}

const plural = (n, word) => `${n} ${word}${n === 1 ? \"\" : \"s\"}`;

/** Adds uploaded files to the end of the gallery (the first photo of an empty
 *  gallery becomes the cover). All-or-nothing. Returns the new entries. */
async function addImages(listing, files, { log } = {}) {
  if (!Array.isArray(files) || files.length === 0) {
    throw new ValidationError(\"Choose at least one photo to upload.\");
  }
  prepare(listing);
  const room = MAX_IMAGES - listing.images.length;
  if (files.length > room) {
    throw new ValidationError(
      room <= 0
        ? `This listing already has the maximum of ${MAX_IMAGES} photos. Remove one to add another.`
        : `You can add ${plural(room, \"more photo\")} (a listing can have at most ${MAX_IMAGES}).`,
    );
  }
  files.forEach(assertValidImage); // every file, before anything is uploaded

  const uploaded = await uploadAll(files, log);
  const start = listing.images.length;
  for (const item of uploaded) {
    listing.images.push({
      ...item,
      alt: \"\",
      caption: \"\",
      order: listing.images.length,
    });
  }
  normalize(listing);
  try {
    await listing.save();
  } catch (err) {
    await Promise.all(uploaded.map((item) => deleteImage(item.publicId, log)));
    throw err;
  }
  return listing.images.slice(start);
}

/** Removes a photo. The cover passes to the next photo. A published listing
 *  keeps at least one. The Cloudinary copy is deleted after the save. */
async function removeImage(listing, imageId, { log } = {}) {
  prepare(listing);
  const image = findImage(listing, imageId);
  if (listing.status === \"published\" && listing.images.length <= 1) {
    throw new ValidationError(
      \"A published listing needs at least one photo. Add another one before removing this one.\",
    );
  }
  const { publicId } = image;
  listing.images.pull(image._id);
  normalize(listing);
  await listing.save();
  await deleteImage(publicId, log); // best effort; never throws
  return { publicId };
}

/** Puts the photos in the order given (every photo's id, exactly once). */
async function reorderImages(listing, orderedIds) {
  prepare(listing);
  const current = listing.images.map((item) => String(item._id));
  const wanted = Array.isArray(orderedIds) ? orderedIds.map(String) : null;
  if (
    !wanted ||
    wanted.length !== current.length ||
    new Set(wanted).size !== wanted.length ||
    !wanted.every((id) => current.includes(id))
  ) {
    throw new ValidationError(
      \"The list of photos has changed. Reload the page and try again.\",
    );
  }
  wanted.forEach((id, index) => {
    listing.images.find((item) => String(item._id) === id).order = index;
  });
  normalize(listing);
  await listing.save();
  return galleryOf(listing);
}

/** direction: \"earlier\" or \"later\". At either end it does nothing. */
async function moveImage(listing, imageId, direction) {
  if (direction !== \"earlier\" && direction !== \"later\") {
    throw new ValidationError(
      \"Choose whether to move the photo earlier or later.\",
    );
  }
  prepare(listing);
  const image = findImage(listing, imageId);
  const ids = listing.images.map((item) => String(item._id));
  const from = ids.indexOf(String(image._id));
  const to = direction === \"earlier\" ? from - 1 : from + 1;
  if (to < 0 || to >= ids.length) return galleryOf(listing);
  [ids[from], ids[to]] = [ids[to], ids[from]];
  return reorderImages(listing, ids);
}

/** Makes a photo the cover (moves it to the front). */
async function setCover(listing, imageId) {
  prepare(listing);
  const image = findImage(listing, imageId);
  const ids = listing.images.map((item) => String(item._id));
  const rest = ids.filter((id) => id !== String(image._id));
  return reorderImages(listing, [String(image._id), ...rest]);
}

/** Sets the alt text and/or caption of a photo (only the fields given). */
async function updateImageText(listing, imageId, { alt, caption } = {}) {
  prepare(listing);
  const image = findImage(listing, imageId);
  if (alt !== undefined) image.alt = plainText(alt, \"The description\");
  if (caption !== undefined) image.caption = plainText(caption, \"The caption\");
  await listing.save();
  return image;
}

/** The single-photo edit form: puts an already uploaded file in as the cover
 *  and returns the Cloudinary id of the cover it replaced (or undefined), for
 *  the caller to delete once the listing is saved. Nothing is saved here. */
function replaceCover(listing, { url, publicId }) {
  prepare(listing);
  const previous = listing.images[0];
  const previousPublicId = previous
    ? previous.publicId
    : listing.image && listing.image.filename;
  if (previous) listing.images.shift();
  listing.images.unshift({ url, publicId, alt: \"\", caption: \"\", order: 0 });
  normalize(listing);
  return previousPublicId || undefined;
}

module.exports = {
  MAX_IMAGES,
  MAX_IMAGE_BYTES,
  TEXT_MAX,
  UploadFailedError,
  detectImageType,
  assertValidImage,
  galleryOf,
  addImages,
  removeImage,
  reorderImages,
  moveImage,
  setCover,
  updateImageText,
  replaceCover,
  syncCover,
};

// Night-ledger service (ADR-004, P07-T02): the only code that reads or writes
// StayNight rows.
//
//   reserveNights(listingId, nights, source, holdExpiresAt?, { now }?)
//   releaseNights(sourceId)
//   confirmNights(sourceId)
//   availableRanges(listingId, from, to, { now }?)
//   nightsInRange(listingId, from, to, { now }?)       (P07-T03: calendar)
//   releaseBlockedNights(listingId, from, to)          (P07-T03: unblock)
//   unavailableDates(listingId, from, to, { now }?)    (P07-T04: public availability API)
//   confirmNights(sourceId)                            (P07-T05: accepting a request)
//   releaseNightsOn / trimNights / extendHold          (P09-T04: changing a booking's dates)
//   unavailableListingIdsFlexible(from, to, flexDays)  (P15-T04: search \"available +-3 days\")
//
// Booking works by inserting one row per night with `insertMany(...,
// { ordered: true })`. The unique (listing, date) index rejects a night that is
// already held (duplicate key, code 11000); the attempt then deletes the rows
// it had inserted and reports a ConflictError (409). Nights are always
// inserted in ascending order, so two overlapping requests cannot each hold
// part of the other's range and both fail forever: whoever takes the first
// contested night wins the rest. A losing request can still see a short-lived
// conflict caused by another attempt's rows that are about to be rolled back;
// the caller may simply retry.
//
// An expired hold (holdExpiresAt in the past) no longer blocks anyone: on a
// collision the service deletes those stale rows (conditional delete, so a
// row that was confirmed in the meantime is never touched) and retries once.
const mongoose = require(\"mongoose\");
const StayNightModel = require(\"../models/stayNight\");
const { ConflictError } = require(\"../utils/errors\");
const {
  isDateOnly,
  addDays,
  formatDateOnly,
  todayIn,
} = require(\"../utils/dates\");

// A booking is at most 90 nights; a host block may be longer (a season).
const MAX_NIGHTS_PER_CALL = 366;
const MAX_AVAILABILITY_SPAN_DAYS = 400;
const SOURCE_KINDS = [\"reservation\", \"block\"];

function isDuplicateKeyError(err) {
  if (!err) return false;
  if (err.code === 11000) return true;
  const writeErrors = [].concat(err.writeErrors || []);
  return writeErrors.some((e) => e && e.code === 11000);
}

/**
 * @param {object} [deps] replaceable in unit tests
 * @param {object} [deps.model]     the StayNight model
 * @param {Function} [deps.newId]   returns a new ObjectId
 * @param {Function} [deps.isValidId] true for a usable ObjectId
 */
function createLedgerService({
  model = StayNightModel,
  newId = () => new mongoose.Types.ObjectId(),
  isValidId = (value) => mongoose.isValidObjectId(value),
} = {}) {
  function requireId(value, name) {
    if (!isValidId(value)) {
      throw new TypeError(`${name} must be a valid ObjectId`);
    }
    return value;
  }

  function normalizeNights(nights) {
    if (!Array.isArray(nights) || nights.length === 0) {
      throw new TypeError(\"nights must be a non-empty array of dates\");
    }
    if (nights.length > MAX_NIGHTS_PER_CALL) {
      throw new TypeError(
        `at most ${MAX_NIGHTS_PER_CALL} nights can be reserved in one call`,
      );
    }
    for (const night of nights) {
      if (!isDateOnly(night)) {
        throw new TypeError(\"every night must be a date-only Date (00:00:00Z)\");
      }
    }
    const sorted = [...nights].sort((a, b) => a.getTime() - b.getTime());
    for (let i = 1; i < sorted.length; i += 1) {
      if (sorted[i].getTime() === sorted[i - 1].getTime()) {
        throw new TypeError(\"nights must not contain the same date twice\");
      }
    }
    return sorted;
  }

  function normalizeSource(source) {
    if (!source || !SOURCE_KINDS.includes(source.kind)) {
      throw new TypeError(
        `source.kind must be one of ${SOURCE_KINDS.join(\", \")}`,
      );
    }
    return { kind: source.kind, id: requireId(source.id, \"source.id\") };
  }

  function normalizeHold(holdExpiresAt, now) {
    if (holdExpiresAt === null || holdExpiresAt === undefined) return null;
    if (
      !(holdExpiresAt instanceof Date) ||
      !Number.isFinite(holdExpiresAt.getTime())
    ) {
      throw new TypeError(\"holdExpiresAt must be a valid Date or null\");
    }
    if (holdExpiresAt.getTime() <= now.getTime()) {
      throw new TypeError(\"holdExpiresAt must be in the future\");
    }
    return holdExpiresAt;
  }

  const isStale = (row, now) =>
    Boolean(row.holdExpiresAt) && row.holdExpiresAt.getTime() < now.getTime();

  async function conflictError(listing, nights, now) {
    const rows = await model.find({ listing, date: { $in: nights } }).lean();
    const taken = rows
      .filter((row) => !isStale(row, now))
      .map((row) => row.date)
      .sort((a, b) => a.getTime() - b.getTime());
    const message = taken.length
      ? `These nights are no longer available: ${taken.map(formatDateOnly).join(\", \")}.`
      : \"Those nights are no longer available.\";
    const err = new ConflictError(message, { code: \"nights_unavailable\" });
    err.conflictingDates = taken;
    return err;
  }

  /**
   * Holds every night for `source`, all or nothing.
   * @returns {Promise<{reserved: number, nights: Date[]}>}
   * @throws {ConflictError} code \"nights_unavailable\", with `conflictingDates`
   */
  async function reserveNights(
    listingId,
    nights,
    source,
    holdExpiresAt = null,
    { now = new Date() } = {},
  ) {
    const listing = requireId(listingId, \"listingId\");
    const sorted = normalizeNights(nights);
    const owner = normalizeSource(source);
    const hold = normalizeHold(holdExpiresAt, now);

    for (let attempt = 1; attempt <= 2; attempt += 1) {
      // Fresh _ids per attempt: compensation deletes exactly these rows, never
      // rows another attempt (or an earlier call for the same source) holds.
      const docs = sorted.map((date) => ({
        _id: newId(),
        listing,
        date,
        source: owner,
        ...(hold ? { holdExpiresAt: hold } : {}),
      }));
      try {
        await model.insertMany(docs, { ordered: true });
        return { reserved: docs.length, nights: sorted };
      } catch (err) {
        try {
          await model.deleteMany({ _id: { $in: docs.map((d) => d._id) } });
        } catch (cleanupErr) {
          const failure = new Error(
            \"Night ledger compensation failed; orphaned rows may remain\",
            { cause: err },
          );
          failure.cleanupError = cleanupErr;
          throw failure;
        }
        if (!isDuplicateKeyError(err)) throw err;

        if (attempt === 1) {
          const { deletedCount } = await model.deleteMany({
            listing,
            date: { $in: sorted },
            holdExpiresAt: { $lt: now },
          });
          if (deletedCount > 0) continue; // a stale hold was in the way: retry once
        }
        throw await conflictError(listing, sorted, now);
      }
    }
    throw new Error(\"unreachable\"); // the loop always returns or throws
  }

  /**
   * Frees every night held by a reservation or block. Safe to call twice.
   * @returns {Promise<{released: number}>}
   */
  async function releaseNights(sourceId) {
    requireId(sourceId, \"sourceId\");
    const { deletedCount } = await model.deleteMany({ \"source.id\": sourceId });
    return { released: deletedCount };
  }

  /**
   * A pending request was accepted: its nights no longer expire. Safe to call
   * twice.
   * @returns {Promise<{confirmed: number}>}
   */
  async function confirmNights(sourceId) {
    requireId(sourceId, \"sourceId\");
    const result = await model.updateMany(
      { \"source.id\": sourceId },
      { $unset: { holdExpiresAt: 1 } },
    );
    return { confirmed: result.modifiedCount || 0 };
  }

  /**
   * Free stretches inside [from, to): runs of consecutive nights nobody holds
   * (an expired hold counts as free). `to` is exclusive, so a range is a
   * valid check-in/check-out pair.
   * @returns {Promise<Array<{from: Date, to: Date, nights: number}>>}
   */
  async function availableRanges(
    listingId,
    from,
    to,
    { now = new Date() } = {},
  ) {
    const listing = requireId(listingId, \"listingId\");
    if (!isDateOnly(from) || !isDateOnly(to)) {
      throw new TypeError(\"from and to must be date-only Dates (00:00:00Z)\");
    }
    const span = (to.getTime() - from.getTime()) / 86400000;
    if (span <= 0) throw new TypeError(\"to must be after from\");
    if (span > MAX_AVAILABILITY_SPAN_DAYS) {
      throw new TypeError(
        `the range can cover at most ${MAX_AVAILABILITY_SPAN_DAYS} nights`,
      );
    }

    const rows = await model
      .find({ listing, date: { $gte: from, $lt: to } })
      .lean();
    const occupied = new Set(
      rows.filter((row) => !isStale(row, now)).map((row) => row.date.getTime()),
    );

    const ranges = [];
    let start = null;
    for (let i = 0; i < span; i += 1) {
      const day = addDays(from, i);
      if (occupied.has(day.getTime())) {
        if (start) {
          ranges.push({ from: start, to: day, nights: nightsOf(start, day) });
          start = null;
        }
      } else if (!start) {
        start = day;
      }
    }
    if (start) ranges.push({ from: start, to, nights: nightsOf(start, to) });
    return ranges;
  }

  function assertSpan(from, to) {
    if (!isDateOnly(from) || !isDateOnly(to)) {
      throw new TypeError(\"from and to must be date-only Dates (00:00:00Z)\");
    }
    const span = (to.getTime() - from.getTime()) / 86400000;
    if (span <= 0) throw new TypeError(\"to must be after from\");
    if (span > MAX_AVAILABILITY_SPAN_DAYS) {
      throw new TypeError(
        `the range can cover at most ${MAX_AVAILABILITY_SPAN_DAYS} nights`,
      );
    }
  }

  /**
   * Every occupied night of one listing inside [from, to), oldest first, as
   * { date, source: { kind, id }, holdExpiresAt }. An expired hold is left out
   * (it no longer blocks anyone). The calendar reads this; it carries no
   * guest information, only who owns the night.
   */
  async function nightsInRange(
    listingId,
    from,
    to,
    { now = new Date() } = {},
  ) {
    const listing = requireId(listingId, \"listingId\");
    assertSpan(from, to);
    const rows = await model
      .find({ listing, date: { $gte: from, $lt: to } })
      .lean();
    return rows
      .filter((row) => !isStale(row, now))
      .map((row) => ({
        date: row.date,
        source: { kind: row.source.kind, id: row.source.id },
        holdExpiresAt: row.holdExpiresAt || null,
      }))
      .sort((a, b) => a.date.getTime() - b.date.getTime());
  }

  /**
   * The nights of one listing that cannot be booked inside [from, to): held by
   * a reservation, a live hold or a host block, oldest first. An expired hold
   * counts as free. Only dates come back (never who or why), so the public
   * availability API cannot leak a guest and shows a block and a reservation
   * identically (P07-T04).
   * @returns {Promise<Date[]>}
   */
  async function unavailableDates(
    listingId,
    from,
    to,
    { now = new Date() } = {},
  ) {
    const listing = requireId(listingId, \"listingId\");
    if (!isDateOnly(from) || !isDateOnly(to)) {
      throw new TypeError(\"from and to must be date-only Dates (00:00:00Z)\");
    }
    const span = (to.getTime() - from.getTime()) / 86400000;
    if (span <= 0) throw new TypeError(\"to must be after from\");
    if (span > MAX_AVAILABILITY_SPAN_DAYS) {
      throw new TypeError(
        `the range can cover at most ${MAX_AVAILABILITY_SPAN_DAYS} nights`,
      );
    }
    const rows = await model
      .find(
        { listing, date: { $gte: from, $lt: to } },
        { date: 1, holdExpiresAt: 1 },
      )
      .lean();
    return rows
      .filter((row) => !isStale(row, now))
      .map((row) => row.date)
      .sort((a, b) => a.getTime() - b.getTime());
  }

  /**
   * Accepting a request removes the hold from its nights, so they no longer
   * expire (P07-T05). Only rows of this reservation are touched.
   * @returns {Promise<{confirmed: number}>}
   */
  async function confirmNights(sourceId) {
    requireId(sourceId, \"sourceId\");
    const { modifiedCount } = await model.updateMany(
      { \"source.id\": sourceId },
      { $unset: { holdExpiresAt: 1 } },
    );
    return { confirmed: modifiedCount };
  }

  /**
   * Changing a booking's dates (P09-T04) works on the DIFFERENCE between the
   * old and the new nights, because the unique (listing, date) index would
   * refuse a night the booking already holds. The three helpers below touch
   * only rows of ONE source.
   *
   * Frees the given nights of one source (the nights a failed change had just
   * added). Safe to call twice; other nights of the source stay.
   * @returns {Promise<{released: number}>}
   */
  async function releaseNightsOn(sourceId, nights) {
    requireId(sourceId, \"sourceId\");
    const sorted = normalizeNights(nights);
    const { deletedCount } = await model.deleteMany({
      \"source.id\": sourceId,
      date: { $in: sorted },
    });
    return { released: deletedCount };
  }

  /**
   * Keeps exactly `keep` among the nights of one source: every other row of
   * the source is deleted (the nights a change gave up). Idempotent, so a
   * failed trim can simply be run again.
   * @returns {Promise<{released: number}>}
   */
  async function trimNights(sourceId, keep) {
    requireId(sourceId, \"sourceId\");
    const sorted = normalizeNights(keep);
    const { deletedCount } = await model.deleteMany({
      \"source.id\": sourceId,
      date: { $nin: sorted },
    });
    return { released: deletedCount };
  }

  /**
   * Moves the hold of a source's still-held nights to a new instant (a
   * pending request whose dates changed gets a fresh answer period). Rows
   * without a hold (confirmed) are left alone.
   * @returns {Promise<{extended: number}>}
   */
  async function extendHold(sourceId, holdExpiresAt, { now = new Date() } = {}) {
    requireId(sourceId, \"sourceId\");
    const hold = normalizeHold(holdExpiresAt, now);
    if (!hold) throw new TypeError(\"holdExpiresAt must be a valid Date\");
    const { modifiedCount } = await model.updateMany(
      { \"source.id\": sourceId, holdExpiresAt: { $exists: true } },
      { $set: { holdExpiresAt: hold } },
    );
    return { extended: modifiedCount };
  }

  /**
   * Frees the HOST-BLOCKED nights of one listing inside [from, to). Only rows
   * with source.kind \"block\" are touched: a reserved or held night is never
   * released here. Also reports which blocks have no night left, so the
   * caller can drop their records.
   * @returns {Promise<{released: number, emptiedSourceIds: any[]}>}
   */
  async function releaseBlockedNights(listingId, from, to) {
    const listing = requireId(listingId, \"listingId\");
    assertSpan(from, to);
    const filter = {
      listing,
      \"source.kind\": \"block\",
      date: { $gte: from, $lt: to },
    };
    const rows = await model.find(filter).lean();
    if (rows.length === 0) return { released: 0, emptiedSourceIds: [] };

    const sourceIds = new Map();
    for (const row of rows) sourceIds.set(String(row.source.id), row.source.id);

    const { deletedCount } = await model.deleteMany(filter);

    const emptiedSourceIds = [];
    for (const id of sourceIds.values()) {
      const left = await model.exists({ \"source.id\": id });
      if (!left) emptiedSourceIds.push(id);
    }
    return { released: deletedCount, emptiedSourceIds };
  }

  /**
   * Is any night of this listing, from today (in the listing's time zone)
   * onward, held by a reservation? A request whose hold has expired does not
   * count, and neither does a host block.
   */
  async function hasUpcomingReservation(
    listingId,
    { now = new Date(), timeZone } = {},
  ) {
    const listing = requireId(listingId, \"listingId\");
    const row = await model.exists({
      listing,
      \"source.kind\": \"reservation\",
      date: { $gte: todayIn(timeZone || undefined, now) },
      $or: [{ holdExpiresAt: null }, { holdExpiresAt: { $gt: now } }],
    });
    return Boolean(row);
  }

  /**
   * Ids of the listings that have at least one night in [from, to) taken: a
   * reservation, a live hold or a host block. Used by search to leave out
   * listings that cannot host a stay. An expired hold counts as free.
   */
  async function unavailableListingIds(from, to, { now = new Date() } = {}) {
    if (!isDateOnly(from) || !isDateOnly(to)) {
      throw new TypeError(\"from and to must be date-only Dates (00:00:00Z)\");
    }
    const span = (to.getTime() - from.getTime()) / 86400000;
    if (span <= 0) throw new TypeError(\"to must be after from\");
    if (span > MAX_AVAILABILITY_SPAN_DAYS) {
      throw new TypeError(
        `the range can cover at most ${MAX_AVAILABILITY_SPAN_DAYS} nights`,
      );
    }
    const rows = await model
      // `_id: 0` and only indexed fields: answered from the index alone
      // (date_1_listing_1_holdExpiresAt_1, P18-T02).
      .find(
        { date: { $gte: from, $lt: to } },
        { _id: 0, listing: 1, holdExpiresAt: 1 },
      )
      .lean();
    const ids = new Map();
    for (const row of rows) {
      if (!isStale(row, now)) ids.set(String(row.listing), row.listing);
    }
    return [...ids.values()];
  }

  /**
   * Search with flexible dates (P15-T04): ids of the listings that have NO
   * free stay of the same length starting within `flexDays` days of `from`
   * (before or after). A listing with a free shifted stay is not returned, so
   * the search keeps it. Shifts that would start before `earliest` (today) do
   * not count. An expired hold counts as free.
   */
  async function unavailableListingIdsFlexible(
    from,
    to,
    flexDays,
    { now = new Date(), earliest = from } = {},
  ) {
    if (!isDateOnly(from) || !isDateOnly(to)) {
      throw new TypeError(\"from and to must be date-only Dates (00:00:00Z)\");
    }
    if (!Number.isInteger(flexDays) || flexDays < 0 || flexDays > 14) {
      throw new TypeError(\"flexDays must be a whole number from 0 to 14\");
    }
    const nights = nightsOf(from, to);
    if (nights <= 0) throw new TypeError(\"to must be after from\");
    const wideFrom = addDays(from, -flexDays);
    const wideTo = addDays(to, flexDays);
    if (nightsOf(wideFrom, wideTo) > MAX_AVAILABILITY_SPAN_DAYS) {
      throw new TypeError(
        `the range can cover at most ${MAX_AVAILABILITY_SPAN_DAYS} nights`,
      );
    }
    const rows = await model
      .find(
        { date: { $gte: wideFrom, $lt: wideTo } },
        { _id: 0, listing: 1, date: 1, holdExpiresAt: 1 },
      )
      .lean();
    const byListing = new Map();
    for (const row of rows) {
      if (isStale(row, now)) continue;
      const key = String(row.listing);
      if (!byListing.has(key)) {
        byListing.set(key, { id: row.listing, taken: new Set() });
      }
      byListing.get(key).taken.add(row.date.getTime());
    }
    const unavailable = [];
    for (const { id, taken } of byListing.values()) {
      let hasWindow = false;
      for (let shift = -flexDays; shift <= flexDays && !hasWindow; shift += 1) {
        const start = addDays(from, shift);
        if (start.getTime() < earliest.getTime()) continue;
        let free = true;
        for (let i = 0; i < nights; i += 1) {
          if (taken.has(addDays(start, i).getTime())) {
            free = false;
            break;
          }
        }
        if (free) hasWindow = true;
      }
      if (!hasWindow) unavailable.push(id);
    }
    return unavailable;
  }

  return {
    reserveNights,
    releaseNights,
    confirmNights,
    availableRanges,
    unavailableListingIdsFlexible,
    nightsInRange,
    releaseBlockedNights,
    unavailableDates,
    confirmNights,
    releaseNightsOn,
    trimNights,
    extendHold,
    hasUpcomingReservation,
    unavailableListingIds,
  };
}

function nightsOf(a, b) {
  return (b.getTime() - a.getTime()) / 86400000;
}

module.exports = {
  ...createLedgerService(),
  createLedgerService,
  isDuplicateKeyError,
  MAX_NIGHTS_PER_CALL,
};

// Publish, unpublish and delete a listing (P04-T05).
//
//   draft ──publish──▶ published ──unpublish──▶ unpublished ──publish──▶ published
//   any state ──soft delete──▶ hidden for good (the row stays: reviews and
//                              reservations remain readable by their owners)
//
// Publishing runs the Host Readiness Checklist (src/services/readiness.js);
// nothing else decides whether a listing may go public. Unpublishing and
// deleting hide the listing at once, because every public page filters on the
// status (src/utils/visibility.js).
const { evaluateReadiness } = require(\"./readiness\");
const ledger = require(\"./ledger\");
const { ValidationError, ConflictError } = require(\"../utils/errors\");

/** Publishing was refused because the checklist is not complete. */
class NotReadyError extends ValidationError {
  constructor(failed) {
    super(
      `This listing is not ready to publish yet. Still to do: ${failed
        .map((check) => check.label)
        .join(\"; \")}.`,
      { code: \"not_ready\" },
    );
    this.failed = failed;
  }
}

/**
 * draft/unpublished -> published. A published listing is left as it is.
 * @returns {Promise<{ changed: boolean, readiness: object }>}
 */
async function publishListing(listing, { readiness: options } = {}) {
  if (listing.deletedAt) {
    throw new ValidationError(\"This listing has been deleted.\");
  }
  const readiness = evaluateReadiness(listing, options);
  if (listing.status === \"published\") return { changed: false, readiness };
  if (![\"draft\", \"unpublished\"].includes(listing.status)) {
    throw new ValidationError(\"This listing cannot be published.\");
  }
  if (!readiness.canPublish) {
    throw new NotReadyError(readiness.checks.filter((check) => !check.passed));
  }
  listing.status = \"published\";
  await listing.save();
  return { changed: true, readiness };
}

/** published -> unpublished (hidden immediately). Already hidden: no change. */
async function unpublishListing(listing) {
  if (listing.deletedAt) {
    throw new ValidationError(\"This listing has been deleted.\");
  }
  if (listing.status === \"unpublished\") return { changed: false };
  if (listing.status !== \"published\") {
    throw new ValidationError(\"Only a published listing can be unpublished.\");
  }
  listing.status = \"unpublished\";
  await listing.save();
  return { changed: true };
}

/**
 * Soft delete: hides the listing for good, keeps the row. Refused while a
 * guest still has an upcoming reservation (the night ledger knows).
 */
async function softDeleteListing(
  listing,
  { now = new Date(), ledgerService = ledger } = {},
) {
  if (listing.deletedAt) return { changed: false };
  const upcoming = await ledgerService.hasUpcomingReservation(listing._id, {
    now,
    timeZone: listing.timezone,
  });
  if (upcoming) {
    throw new ConflictError(
      \"This listing has upcoming reservations, so it cannot be deleted. Unpublish it instead, or cancel the reservations first.\",
    );
  }
  listing.deletedAt = now;
  if (listing.status === \"published\") listing.status = \"unpublished\";
  await listing.save();
  return { changed: true };
}

module.exports = {
  NotReadyError,
  publishListing,
  unpublishListing,
  softDeleteListing,
};

// The Mongo filter for the listings page URL (P05-T02), shared by the page and
// the map data (P06-T04) so both always show the same stays: validated
// parameters -> search filter, minus the listings with a taken night in the
// requested stay (the night ledger).
const ledger = require(\"./ledger\");
const { buildFilter } = require(\"./search\");
const { areaCentre, areaCondition } = require(\"./area\");
const { parseListingQuery } = require(\"../validation/searchQuery\");
const { DEFAULT_TIMEZONE, todayIn } = require(\"../utils/dates\");

/**
 * @param {object} query req.query
 * @returns {Promise<{ parsed: object, filter: object, takenIds: Array }>}
 */
async function listingFilterFor(query, { now = new Date(), Listing = require(\"../models/listing\") } = {}) {
  const parsed = parseListingQuery(query, { now });
  let filter = buildFilter(parsed.searchParams);
  // \"Within N km of the destination\" (P06-T05): the circle REPLACES the text
  // match, so nearby towns count. `parsed.area` is what the page and the
  // suggestions need; it stays null when the destination has no stays to centre on.
  parsed.area = null;
  if (parsed.state.radius && parsed.searchParams.destination) {
    const centre = await areaCentre(Listing, parsed.searchParams.destination);
    if (centre) {
      const { destination, ...rest } = parsed.searchParams;
      void destination;
      const condition = areaCondition(centre, parsed.state.radius);
      filter = { ...buildFilter(rest), ...condition };
      parsed.area = { km: parsed.state.radius, centre, condition };
    }
  }
  let takenIds = [];
  if (parsed.stay) {
    // With \"Available +-3 days\" a listing stays if ANY same-length stay
    // starting within 3 days of the asked check-in is free (never before today).
    const taken = parsed.stay.flexDays
      ? await ledger.unavailableListingIdsFlexible(
          parsed.stay.checkIn,
          parsed.stay.checkOut,
          parsed.stay.flexDays,
          { now, earliest: todayIn(DEFAULT_TIMEZONE, now) },
        )
      : await ledger.unavailableListingIds(
          parsed.stay.checkIn,
          parsed.stay.checkOut,
          { now },
        );
    takenIds = taken;
    if (taken.length > 0) filter._id = { $nin: taken };
  }
  return { parsed, filter, takenIds };
}

module.exports = { listingFilterFor };

// Listing moderation for admins (P14-T03): the queue (reported, new, suspended),
// one listing's moderation page, and suspend / restore / mark reviewed. The
// routes (src/routes/admin.js) call these inside auditedMutation, which writes
// the audit row; nothing here writes one.
//
// - Suspend: only a published, not-deleted listing. It becomes `suspended` (so
//   every public page, search and booking check stops seeing it), the reason is
//   kept on the listing for the host to read, and the listing counts as
//   reviewed. Done with one conditional update, so two admins at once cannot
//   both succeed. Bookings already made are left alone (see docs).
// - Restore: only a listing suspended by moderation, never one hidden because
//   its host's account is suspended (that comes back when the host is
//   reinstated, P14-T02). It becomes `published` again and counts as reviewed.
// - Mark reviewed: takes a published listing out of the \"new\" queue.
// Reports (P12-T04) about a listing are shown but not closed here: that is
// P14-T04.
const mongoose = require(\"mongoose\");
const Listing = require(\"../models/listing\");
const Report = require(\"../models/report\");
const AuditLog = require(\"../models/auditLog\");
const { toPageNumber } = require(\"./audit\");
const { REPORT_REASONS } = require(\"../config/reports\");
const { notifier } = require(\"./notificationEvents\");

const PAGE_SIZE = 20;
const REASON_MIN = 5;
const REASON_MAX = 500;
const FILTERS = Object.freeze([\"reported\", \"new\", \"suspended\"]);
const LIST_FIELDS =
  \"title status address.city address.state country owner createdAt updatedAt hiddenByOwnerSuspension moderation deletedAt\";
const reasonLabel = Object.fromEntries(
  REPORT_REASONS.map((r) => [r.value, r.label]),
);

class ModerationError extends Error {
  /** @param {string} message user-safe text, shown to the admin */
  constructor(message) {
    super(message);
    this.name = \"ModerationError\";
  }
}

const isId = (value) =>
  typeof value === \"string\" && mongoose.isValidObjectId(value);

/** The trimmed reason, or a ModerationError when it is missing/too short/long. */
function cleanReason(value, { required = true } = {}) {
  const reason = typeof value === \"string\" ? value.trim() : \"\";
  if (!reason && !required) return \"\";
  if (reason.length < REASON_MIN) {
    throw new ModerationError(
      `Give a reason (at least ${REASON_MIN} characters). It is written to the audit log${required ? \" and shown to the host\" : \"\"}.`,
    );
  }
  if (reason.length > REASON_MAX) {
    throw new ModerationError(
      `The reason must be ${REASON_MAX} characters or fewer.`,
    );
  }
  return reason;
}

// Open reports per listing id: Map(idString -> count).
async function openReportCounts(ids) {
  if (!ids.length) return new Map();
  const rows = await Report.aggregate([
    {
      $match: { targetKind: \"listing\", status: \"open\", targetId: { $in: ids } },
    },
    { $group: { _id: \"$targetId\", count: { $sum: 1 } } },
  ]);
  return new Map(rows.map((r) => [String(r._id), r.count]));
}

function toRow(listing, reports) {
  return {
    id: String(listing._id),
    title: listing.title,
    status: listing.status,
    place: [listing.address && listing.address.city, listing.country]
      .filter(Boolean)
      .join(\", \"),
    host: listing.owner && listing.owner.username ? listing.owner.username : \"\",
    hostId: listing.owner && listing.owner._id ? String(listing.owner._id) : \"\",
    createdAt: listing.createdAt,
    openReports: reports.get(String(listing._id)) || 0,
    // Hidden because the HOST's account is suspended: restored by reinstating the host.
    hiddenWithHost: Boolean(listing.hiddenByOwnerSuspension),
    reviewed: Boolean(listing.moderation && listing.moderation.reviewedAt),
  };
}

/**
 * One page of a queue.
 *   reported   listings with open reports, most reports first
 *   new        published listings no admin has reviewed yet, oldest first
 *   suspended  suspended listings, latest first
 * @returns {{ rows: object[], page: number, totalPages: number, total: number, filter: string }}
 */
async function listQueue({ filter, page } = {}) {
  const which =
    typeof filter === \"string\" && FILTERS.includes(filter)
      ? filter
      : \"reported\";
  const requested = toPageNumber(page);

  let total;
  let listings;
  if (which === \"reported\") {
    const grouped = await Report.aggregate([
      { $match: { targetKind: \"listing\", status: \"open\" } },
      {
        $group: {
          _id: \"$targetId\",
          count: { $sum: 1 },
          latest: { $max: \"$createdAt\" },
        },
      },
    ]);
    // Only listings that still exist, most reported first, then most recent.
    const existing = await Listing.find({
      _id: { $in: grouped.map((g) => g._id) },
      deletedAt: null,
    })
      .select(\"_id\")
      .lean();
    const alive = new Set(existing.map((l) => String(l._id)));
    const ordered = grouped
      .filter((g) => alive.has(String(g._id)))
      .sort(
        (a, b) =>
          b.count - a.count ||
          b.latest - a.latest ||
          String(a._id).localeCompare(String(b._id)),
      );
    total = ordered.length;
    const totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE));
    const current = Math.min(requested, totalPages);
    const ids = ordered
      .slice((current - 1) * PAGE_SIZE, current * PAGE_SIZE)
      .map((g) => g._id);
    const found = await Listing.find({ _id: { $in: ids } })
      .select(LIST_FIELDS)
      .populate(\"owner\", \"username\")
      .lean();
    const byId = new Map(found.map((l) => [String(l._id), l]));
    listings = ids.map((id) => byId.get(String(id))).filter(Boolean);
    const counts = new Map(grouped.map((g) => [String(g._id), g.count]));
    return {
      rows: listings.map((l) => toRow(l, counts)),
      page: current,
      totalPages,
      total,
      filter: which,
    };
  }

  const query =
    which === \"new\"
      ? { status: \"published\", deletedAt: null, \"moderation.reviewedAt\": null }
      : { status: \"suspended\", deletedAt: null };
  const sort =
    which === \"new\" ? { createdAt: 1, _id: 1 } : { updatedAt: -1, _id: -1 };
  total = await Listing.countDocuments(query);
  const totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE));
  const current = Math.min(requested, totalPages);
  listings = await Listing.find(query)
    .select(LIST_FIELDS)
    .populate(\"owner\", \"username\")
    .sort(sort)
    .skip((current - 1) * PAGE_SIZE)
    .limit(PAGE_SIZE)
    .lean();
  const counts = await openReportCounts(listings.map((l) => l._id));
  return {
    rows: listings.map((l) => toRow(l, counts)),
    page: current,
    totalPages,
    total,
    filter: which,
  };
}

/**
 * The moderation page of one listing, or null for a malformed/unknown id (a
 * deleted listing can still be looked at). Never includes the host's email.
 */
async function getListingForModeration(id) {
  if (!isId(id)) return null;
  const listing = await Listing.findById(id)
    .select(`${LIST_FIELDS} description pricing images image status`)
    .populate(\"owner\", \"username displayName status\")
    .populate(\"moderation.suspendedBy\", \"username\")
    .lean();
  if (!listing) return null;

  const [reports, history] = await Promise.all([
    Report.find({
      targetKind: \"listing\",
      targetId: listing._id,
      status: \"open\",
    })
      .sort({ createdAt: -1, _id: -1 })
      .limit(20)
      .populate(\"reporter\", \"username\")
      .select(\"reporter reason details createdAt\")
      .lean(),
    AuditLog.find({ targetType: \"listing\", targetId: listing._id })
      .sort({ createdAt: -1, _id: -1 })
      .limit(10)
      .populate(\"actor\", \"username\")
      .lean(),
  ]);
  const photos = Array.isArray(listing.images)
    ? listing.images.length
    : listing.image && listing.image.url
      ? 1
      : 0;
  const desc =
    typeof listing.description === \"string\" ? listing.description.trim() : \"\";
  return {
    listing,
    summary: {
      id: String(listing._id),
      title: listing.title,
      status: listing.status,
      deleted: Boolean(listing.deletedAt),
      place: [
        listing.address && listing.address.city,
        listing.address && listing.address.state,
        listing.country,
      ]
        .filter(Boolean)
        .join(\", \"),
      nightlyMinor:
        listing.pricing && Number.isSafeInteger(listing.pricing.nightlyMinor)
          ? listing.pricing.nightlyMinor
          : null,
      currency: (listing.pricing && listing.pricing.currency) || \"INR\",
      photos,
      descriptionExcerpt: desc.length > 400 ? `${desc.slice(0, 400)}…` : desc,
      hiddenWithHost: Boolean(listing.hiddenByOwnerSuspension),
      reviewedAt:
        listing.moderation && listing.moderation.reviewedAt
          ? listing.moderation.reviewedAt
          : null,
      suspendedAt:
        listing.moderation && listing.moderation.suspendedAt
          ? listing.moderation.suspendedAt
          : null,
      suspendedBy:
        listing.moderation && listing.moderation.suspendedBy
          ? listing.moderation.suspendedBy.username
          : \"\",
      suspendReason:
        (listing.moderation && listing.moderation.suspendReason) || \"\",
      host: listing.owner
        ? {
            id: String(listing.owner._id),
            username: listing.owner.username,
            status: listing.owner.status || \"active\",
          }
        : null,
    },
    reports: reports.map((r) => ({
      reporter: r.reporter ? r.reporter.username : \"(deleted account)\",
      reason: reasonLabel[r.reason] || r.reason,
      details: r.details || \"\",
      createdAt: r.createdAt,
    })),
    history,
  };
}

/**
 * @returns {Promise<{ listing: object, reason: string, details: object }>}
 * @throws {ModerationError} nothing was changed
 */
async function suspendListing({ admin, id, reason, now = new Date() }) {
  const text = cleanReason(reason);
  if (!isId(id)) throw new ModerationError(\"That listing does not exist.\");
  const listing = await Listing.findById(id)
    .select(\"title status deletedAt owner\")
    .lean();
  if (!listing) throw new ModerationError(\"That listing does not exist.\");
  if (listing.deletedAt)
    throw new ModerationError(\"That listing was deleted by its host.\");
  if (listing.status !== \"published\") {
    throw new ModerationError(
      listing.status === \"suspended\"
        ? \"That listing is already suspended.\"
        : \"Only a published listing can be suspended: drafts and unpublished listings are not visible to guests anyway.\",
    );
  }
  const result = await Listing.updateOne(
    { _id: listing._id, status: \"published\", deletedAt: null },
    {
      $set: {
        status: \"suspended\",
        \"moderation.suspendedAt\": now,
        \"moderation.suspendedBy\": admin._id,
        \"moderation.suspendReason\": text,
        \"moderation.reviewedAt\": now,
        \"moderation.reviewedBy\": admin._id,
      },
      $unset: { hiddenByOwnerSuspension: \"\" },
    },
  );
  if (!result || result.modifiedCount !== 1) {
    throw new ModerationError(
      \"That listing changed while you were suspending it. Reload the page and try again.\",
    );
  }
  // The host reads the reason on the listing page; tell them too (P11-T04).
  await notifier.dispatch(\"listing.suspended\", { listing, reason: text });
  return {
    listing,
    reason: text,
    details: {
      title: listing.title,
      from: \"published\",
      to: \"suspended\",
      host: String(listing.owner || \"\"),
    },
  };
}

/** @throws {ModerationError} nothing was changed */
async function restoreListing({ admin, id, reason, now = new Date() }) {
  const text = cleanReason(reason);
  if (!isId(id)) throw new ModerationError(\"That listing does not exist.\");
  const listing = await Listing.findById(id)
    .select(\"title status deletedAt owner hiddenByOwnerSuspension\")
    .lean();
  if (!listing) throw new ModerationError(\"That listing does not exist.\");
  if (listing.deletedAt)
    throw new ModerationError(\"That listing was deleted by its host.\");
  if (listing.status !== \"suspended\")
    throw new ModerationError(\"That listing is not suspended.\");
  if (listing.hiddenByOwnerSuspension) {
    throw new ModerationError(
      \"This listing is hidden because its host's account is suspended. Reinstate the account to publish it again.\",
    );
  }
  const result = await Listing.updateOne(
    {
      _id: listing._id,
      status: \"suspended\",
      deletedAt: null,
      hiddenByOwnerSuspension: { $ne: true },
    },
    {
      $set: {
        status: \"published\",
        \"moderation.reviewedAt\": now,
        \"moderation.reviewedBy\": admin._id,
      },
      $unset: {
        \"moderation.suspendedAt\": \"\",
        \"moderation.suspendedBy\": \"\",
        \"moderation.suspendReason\": \"\",
      },
    },
  );
  if (!result || result.modifiedCount !== 1) {
    throw new ModerationError(
      \"That listing changed while you were restoring it. Reload the page and try again.\",
    );
  }
  await notifier.dispatch(\"listing.restored\", { listing });
  return {
    listing,
    reason: text,
    details: {
      title: listing.title,
      from: \"suspended\",
      to: \"published\",
      host: String(listing.owner || \"\"),
    },
  };
}

/** Takes a published listing out of the \"new\" queue. The note is optional. */
async function markReviewed({ admin, id, note, now = new Date() }) {
  const text = cleanReason(note, { required: false });
  if (!isId(id)) throw new ModerationError(\"That listing does not exist.\");
  const listing = await Listing.findById(id)
    .select(\"title status deletedAt moderation.reviewedAt\")
    .lean();
  if (!listing) throw new ModerationError(\"That listing does not exist.\");
  if (listing.deletedAt)
    throw new ModerationError(\"That listing was deleted by its host.\");
  if (listing.moderation && listing.moderation.reviewedAt)
    throw new ModerationError(\"That listing is already marked as reviewed.\");
  const result = await Listing.updateOne(
    { _id: listing._id, deletedAt: null, \"moderation.reviewedAt\": null },
    {
      $set: {
        \"moderation.reviewedAt\": now,
        \"moderation.reviewedBy\": admin._id,
      },
    },
  );
  if (!result || result.modifiedCount !== 1) {
    throw new ModerationError(
      \"That listing changed in the meantime. Reload the page and try again.\",
    );
  }
  return {
    listing,
    reason: text,
    details: { title: listing.title, status: listing.status },
  };
}

module.exports = {
  ModerationError,
  listQueue,
  getListingForModeration,
  suspendListing,
  restoreListing,
  markReviewed,
  cleanReason,
  FILTERS,
  PAGE_SIZE,
};

// Host listing statistics (P13-T03). APPROXIMATE by design, and labelled so.
//
// Counting rules
//  - A view counts once per browser session per listing per day. The \"seen\"
//    marks live in the session (at most MAX_SEEN of them, old days dropped).
//  - Not counted: requests with no or a bot-like User-Agent (a heuristic, so
//    some bots get through and a few odd browsers do not), the listing's own
//    host, the host's \"see it as a guest\" preview, and listings that are not
//    public.
//  - Counting never breaks a page: every failure is caught and logged.
//  - Counters only go up with $inc (views, checkout starts, daily saves). The
//    lifetime ListingStat.saves can be driven down by un-saves, and is clamped
//    at 0 so it is never negative.
const { todayIn, addDays, formatDateOnly, DEFAULT_TIMEZONE } = require(\"../utils/dates\");

const WINDOW_DAYS = 30;
const MIN_VIEWS_FOR_CONVERSION = 30;
const MAX_SEEN = 100;

// Words that show up in the User-Agent of crawlers, link previewers, monitors
// and scripts. A heuristic, not a guarantee.
const BOT_UA =
  /bot|crawl|spider|slurp|preview|facebookexternalhit|embedly|monitor|uptime|pingdom|lighthouse|headless|phantomjs|puppeteer|playwright|curl|wget|httpclient|python|java\\/|go-http|scrapy|axios|node-fetch|okhttp/i;

/** True for a missing, very short, or bot-like User-Agent. */
function isBot(userAgent) {
  if (typeof userAgent !== \"string\") return true;
  const ua = userAgent.trim();
  return ua.length < 10 || BOT_UA.test(ua);
}

const models = (deps = {}) => ({
  DayStat: deps.DayStat || require(\"../models/listingDayStat\"),
  ListingStat: deps.ListingStat || require(\"../models/listingStat\"),
  Reservation: deps.Reservation || require(\"../models/reservation\"),
});

const dayOf = (now) => todayIn(DEFAULT_TIMEZONE, now);

/** $inc one counter of today's row, creating it. One retry when two requests create it at once. */
async function bump(listingId, field, { now = new Date(), deps } = {}) {
  const { DayStat } = models(deps);
  const filter = { listing: listingId, day: dayOf(now) };
  const update = { $inc: { [field]: 1 } };
  try {
    await DayStat.updateOne(filter, update, { upsert: true });
  } catch (err) {
    if (err && err.code === 11000) {
      await DayStat.updateOne(filter, update, { upsert: true });
      return;
    }
    throw err;
  }
}

/** True the first time this session sees `key` today; remembers it. */
function firstTimeToday(session, key, now) {
  if (!session || typeof session !== \"object\") return false;
  const today = formatDateOnly(dayOf(now));
  const seen = session.statSeen && typeof session.statSeen === \"object\" ? session.statSeen : {};
  const kept = {};
  for (const [k, day] of Object.entries(seen)) if (day === today) kept[k] = day;
  if (kept[key]) {
    session.statSeen = kept;
    return false;
  }
  const keys = Object.keys(kept);
  if (keys.length >= MAX_SEEN) delete kept[keys[0]];
  kept[key] = today;
  session.statSeen = kept;
  return true;
}

function shouldCount(req, listing, { preview = false } = {}) {
  if (!req || !listing || preview) return false;
  if (isBot(req.get && req.get(\"user-agent\"))) return false;
  const owner = listing.owner && (listing.owner._id || listing.owner);
  if (req.user && owner && String(req.user._id) === String(owner)) return false;
  return true;
}

async function count(kind, req, listing, options = {}) {
  try {
    if (!shouldCount(req, listing, options)) return false;
    const now = options.now || new Date();
    const key = `${kind}:${listing._id}`;
    if (!firstTimeToday(req.session, key, now)) return false;
    await bump(listing._id, kind === \"v\" ? \"views\" : \"checkoutStarts\", { now, deps: options.deps });
    return true;
  } catch (err) {
    if (req && req.log) req.log.warn({ err }, \"listing stat not counted\");
    return false;
  }
}

/** A page view of a public listing. Never throws. */
const recordView = (req, listing, options) => count(\"v\", req, listing, options);

/** A checkout page opened for a listing. Never throws. */
const recordCheckoutStart = (req, listing, options) => count(\"c\", req, listing, options);

/** A stay was saved (a row was really created). Never throws. */
async function recordSave(listingId, { now, deps } = {}) {
  try {
    await bump(listingId, \"saves\", { now, deps });
  } catch {
    // statistics must never break saving
  }
}

/** After an un-save: the lifetime total may not stay below zero. Never throws. */
async function clampSaves(listingId, { deps } = {}) {
  try {
    const { ListingStat } = models(deps);
    await ListingStat.updateOne({ listing: listingId, saves: { $lt: 0 } }, { $set: { saves: 0 } });
  } catch {
    // see above
  }
}

/**
 * The last `days` days (today included) for one listing, oldest first, with
 * every day present (zeros where nothing was counted).
 * conversion = reservations created in the window / views in the window, only
 * when views >= 30 (below that a ratio says nothing); null otherwise.
 */
async function getStats(listingId, { now = new Date(), days = WINDOW_DAYS, deps } = {}) {
  const { DayStat, ListingStat, Reservation } = models(deps);
  const today = dayOf(now);
  const first = addDays(today, -(days - 1));
  const rows = await DayStat.find({ listing: listingId, day: { $gte: first, $lte: today } }).lean();
  const byDay = new Map(rows.map((r) => [formatDateOnly(r.day), r]));

  const series = [];
  const total = { views: 0, saves: 0, checkoutStarts: 0 };
  for (let i = 0; i < days; i += 1) {
    const day = addDays(first, i);
    const row = byDay.get(formatDateOnly(day)) || {};
    const point = {
      day: formatDateOnly(day),
      views: row.views || 0,
      saves: row.saves || 0,
      checkoutStarts: row.checkoutStarts || 0,
    };
    total.views += point.views;
    total.saves += point.saves;
    total.checkoutStarts += point.checkoutStarts;
    series.push(point);
  }

  const reservations = await Reservation.countDocuments({
    listing: listingId,
    createdAt: { $gte: first },
  });
  const lifetime = await ListingStat.findOne({ listing: listingId }).lean();
  const conversion =
    total.views >= MIN_VIEWS_FOR_CONVERSION
      ? Math.min(100, Math.round((reservations * 1000) / total.views) / 10)
      : null;

  return {
    days,
    from: formatDateOnly(first),
    to: formatDateOnly(today),
    series,
    total,
    reservations,
    conversion,
    minViewsForConversion: MIN_VIEWS_FOR_CONVERSION,
    savedNow: Math.max(0, (lifetime && lifetime.saves) || 0),
  };
}

module.exports = {
  isBot,
  recordView,
  recordCheckoutStart,
  recordSave,
  clampSaves,
  getStats,
  firstTimeToday,
  shouldCount,
  WINDOW_DAYS,
  MIN_VIEWS_FOR_CONVERSION,
  MAX_SEEN,
};

// Who may see where a home really is (P06-T02).
//
// Everybody sees the approximate (public) point. The precise point and the
// street address (address.line1) are shown only to
//   * the listing's host and admins, and
//   * a guest whose reservation of THIS listing is confirmed (or completed).
// A pending, expired or cancelled reservation does not count; neither does a
// reservation of another listing. Pure: the reservation is passed in, nothing is
// read from a database. The trip page (P09-T01) calls this.
const { isAdmin, sameId } = require(\"../policies/shared\");
const { toMapPoint } = require(\"../utils/geo\");

const REVEALING_STATUSES = Object.freeze([\"confirmed\", \"completed\"]);

function mayViewPreciseLocation({ viewer, listing, reservation } = {}) {
  if (!viewer || !listing) return false;
  if (isAdmin(viewer) || sameId(listing.owner, viewer)) return true;
  return Boolean(
    reservation &&
      REVEALING_STATUSES.includes(reservation.status) &&
      sameId(reservation.guest, viewer) &&
      sameId(reservation.listing, listing),
  );
}

/**
 * @returns {{ point: { lng: number, lat: number }, addressLine: string } | null}
 * null unless the viewer may see it (or there is nothing usable to show).
 */
function preciseLocationFor({ viewer, listing, reservation } = {}) {
  if (!mayViewPreciseLocation({ viewer, listing, reservation })) return null;
  const read = (path) =>
    typeof listing.get === \"function\"
      ? listing.get(path)
      : path.split(\".\").reduce((n, k) => (n == null ? undefined : n[k]), listing);
  const coordinates = read(\"geometry.coordinates\");
  const point = toMapPoint({
    type: read(\"geometry.type\"),
    coordinates: coordinates ? Array.from(coordinates) : undefined,
  });
  if (!point) return null;
  return { point, addressLine: String(read(\"address.line1\") ?? \"\") };
}

module.exports = { mayViewPreciseLocation, preciseLocationFor, REVEALING_STATUSES };

// Changing a listing's address (P04-T04): the new address is looked up first and
// the host must confirm the match before it is saved. The looked-up point is
// kept on the server (in the session) and tied to the exact address that was
// looked up, so the confirm form can never supply coordinates of its own.
const crypto = require(\"node:crypto\");

const TTL_MS = 15 * 60 * 1000;
const FIELDS = [\"line1\", \"city\", \"state\", \"country\", \"postalCode\"];

/** A fingerprint of (listing, address): the same address text gives the same key. */
function addressKey(listingId, address) {
  const text = [String(listingId), ...FIELDS.map((f) => String(address[f] ?? \"\").trim())].join(\"\\u0000\");
  return crypto.createHash(\"sha256\").update(text).digest(\"hex\");
}

/** Remembers a look-up result for this session. */
function rememberLookup(session, listingId, address, { geometry, placeName }, now = Date.now()) {
  session.pendingLocation = {
    key: addressKey(listingId, address),
    geometry,
    placeName,
    at: now,
  };
}

/**
 * The remembered point if it is for exactly this listing and address and is
 * not older than 15 minutes, else null. Clears it either way once it has been
 * asked for, so a confirmation works once.
 */
function takeLookup(session, listingId, address, now = Date.now()) {
  const pending = session && session.pendingLocation;
  if (!pending) return null;
  delete session.pendingLocation;
  if (pending.key !== addressKey(listingId, address)) return null;
  if (typeof pending.at !== \"number\" || now - pending.at > TTL_MS) return null;
  return pending;
}

module.exports = { addressKey, rememberLookup, takeLookup, TTL_MS };

// Map data for the search page (P06-T04): the stays that match a search and lie
// inside the map's box, as GeoJSON points.
//
// Privacy: the point of a feature is ALWAYS `publicGeometry` (the approximate
// point of P06-T02). The precise `geometry`, the address and the host never
// enter this module's query projection.
//
// The box is checked with plain longitude/latitude ranges on the coordinates
// (the box on the sphere would curve at its top and bottom edges); with a few
// thousand listings this is fine, a spatial index for it is a later,
// P18-T02, decision.
const { formatMoney } = require(\"../utils/money\");

const MAP_RESULT_CAP = 200;
const PROJECTION = { title: 1, \"pricing.nightlyMinor\": 1, \"pricing.currency\": 1, publicGeometry: 1 };

/** Mongo condition for the boxes of parseBbox (one or two, OR-ed). */
function bboxCondition(boxes) {
  const inside = (box) => ({
    \"publicGeometry.coordinates.0\": { $gte: box.west, $lte: box.east },
    \"publicGeometry.coordinates.1\": { $gte: box.south, $lte: box.north },
  });
  return boxes.length === 1 ? inside(boxes[0]) : { $or: boxes.map(inside) };
}

/** One GeoJSON feature, or null when the listing has no usable public point. */
function toFeature(listing) {
  const geometry = listing && listing.publicGeometry;
  const coords = geometry && Array.from(geometry.coordinates || []);
  if (
    !geometry ||
    geometry.type !== \"Point\" ||
    !coords ||
    coords.length < 2 ||
    !Number.isFinite(coords[0]) ||
    !Number.isFinite(coords[1])
  ) {
    return null;
  }
  const minor = listing.pricing && listing.pricing.nightlyMinor;
  const currency = (listing.pricing && listing.pricing.currency) || \"INR\";
  const hasPrice = Number.isSafeInteger(minor);
  const id = String(listing._id);
  return {
    type: \"Feature\",
    id,
    geometry: { type: \"Point\", coordinates: [coords[0], coords[1]] },
    properties: {
      id,
      title: typeof listing.title === \"string\" ? listing.title : \"\",
      priceMinor: hasPrice ? minor : null,
      priceLabel: hasPrice ? formatMoney(minor, currency) : \"\",
      url: `/listings/${id}`,
    },
  };
}

/**
 * @param {object} Listing the model
 * @param {object} filter the search filter (see listingFilterFor)
 * @param {Array|null} boxes parseBbox(...).boxes, or null for \"anywhere\"
 * @returns {Promise<{ type: \"FeatureCollection\", features: object[],
 *   meta: { total: number, returned: number, capped: boolean, cap: number, message: string } }>}
 */
async function searchMap(Listing, filter, boxes) {
  const query = { ...filter, \"publicGeometry.type\": \"Point\" };
  if (boxes && boxes.length) query.$and = [...(filter.$and || []), bboxCondition(boxes)];

  const total = await Listing.countDocuments(query);
  const docs = total
    ? await Listing.find(query, PROJECTION).sort({ _id: -1 }).limit(MAP_RESULT_CAP).lean()
    : [];
  const features = docs.map(toFeature).filter(Boolean);
  const capped = total > MAP_RESULT_CAP;

  let message = \"\";
  if (total === 0) message = \"No stays in this area.\";
  else if (capped) message = `Showing ${features.length} of ${total} stays. Zoom in to see the rest.`;

  return {
    type: \"FeatureCollection\",
    features,
    meta: { total, returned: features.length, capped, cap: MAP_RESULT_CAP, message },
  };
}

module.exports = { searchMap, bboxCondition, toFeature, MAP_RESULT_CAP };

// Changing the dates of a booking (P09-T04).
//
//   previewChange({ id, user, in, out, now })   what the new stay would cost; changes nothing
//   changeDates({ id, user, in, out, expectedTotalMinor, now })   does it
//
// Who and when: only the guest of the booking (policy `reservation:modify`;
// everybody else gets the same 404 as for a booking that does not exist), while
// the booking is `pending` (hold still running) or `confirmed` and the stay has
// not started (check-in moment on the listing's own clock). Guests stay the
// same: this changes the dates only.
//
// The new stay goes through the SAME rules and the SAME pricing as a new
// booking (bookingRules.js, pricing.quote), measured today: the price of the
// new dates is today's price of the place, and the difference is
// `new total - old total` (negative = cheaper). The difference is CALCULATED
// AND RECORDED in `Reservation.modifications`; no money moves (payments are
// simulated, P16).
//
// Order, which is what keeps the ledger honest (ADR-004). The unique
// (listing, date) index would refuse a night the booking already holds, so the
// ledger is changed by the DIFFERENCE between old and new nights:
//   1. hold the nights that are new (added = new \\ old), all or nothing. On a
//      conflict nothing was written and the booking is exactly as before.
//   2. pending only: move the hold of the kept nights to the new answer time.
//   3. compare-and-set the reservation (status, old dates and, for a pending
//      request, a still-running hold must be what we read). Only one of two
//      concurrent changes, or a change and a cancel/accept/expiry, can win.
//      The loser releases exactly the nights it added in step 1.
//   4. release the nights given up (trim to exactly the new nights).
// A night is therefore never free while the booking still needs it, and no
// state exists in which two bookings own the same night. If step 4 fails the
// old nights stay blocked (the safe side) and `trimNights` can be run again.
//
// A pending request goes back to the host: the hold restarts for 24 hours and
// the host is told (`reservation.modified`), so the host answers the NEW dates.
// A confirmed stay on a place that asks for approval keeps its confirmation:
// the host already accepted this guest for this place; they are told of the
// new dates and can cancel. (Known limit, see docs/tasks/P09-T04.md.)
const { can } = require(\"../policies\");
const {
  tryParseDateOnly,
  eachNight,
  formatDateOnly,
  instantAfter,
} = require(\"../utils/dates\");
const {
  NotFoundError,
  ValidationError,
  ConflictError,
  PriceChangedError,
} = require(\"../utils/errors\");
const { isPublic } = require(\"../utils/visibility\");
const { bookingProblems } = require(\"./bookingRules\");
const { checkInInstant } = require(\"./refunds\");

const { PENDING_HOLD_MS } = require(\"./reservations\");

const OBJECT_ID = /^[0-9a-f]{24}$/i;

const keyOf = (date) => date.getTime();

/**
 * Can this booking's dates still be changed? Pure.
 * @returns {{ ok: true } | { ok: false, code: string, message: string }}
 */
function modifiability(reservation, now = new Date()) {
  const status = reservation && reservation.status;
  if (status !== \"pending\" && status !== \"confirmed\") {
    return {
      ok: false,
      code: \"not_modifiable\",
      message: \"Only a request that is waiting for the host or a confirmed stay can be changed.\",
    };
  }
  if (
    status === \"pending\" &&
    !(reservation.holdExpiresAt && reservation.holdExpiresAt.getTime() > now.getTime())
  ) {
    return {
      ok: false,
      code: \"hold_expired\",
      message: \"This request has expired, so its dates can no longer be changed.\",
    };
  }
  if (now.getTime() >= checkInInstant(reservation).getTime()) {
    return {
      ok: false,
      code: \"stay_started\",
      message: \"This stay has already started, so its dates can no longer be changed.\",
    };
  }
  return { ok: true };
}

/** The nights to add and the nights to give up when going from one stay to another. */
function diffNights(oldIn, oldOut, newIn, newOut) {
  const before = eachNight(oldIn, oldOut);
  const after = eachNight(newIn, newOut);
  const had = new Set(before.map(keyOf));
  const wants = new Set(after.map(keyOf));
  return {
    before,
    after,
    added: after.filter((n) => !had.has(keyOf(n))),
    removed: before.filter((n) => !wants.has(keyOf(n))),
  };
}

function parseStay(inRaw, outRaw) {
  const checkIn = typeof inRaw === \"string\" ? tryParseDateOnly(inRaw) : null;
  const checkOut = typeof outRaw === \"string\" ? tryParseDateOnly(outRaw) : null;
  if (!checkIn || !checkOut) {
    return {
      problem: {
        code: \"invalid_dates\",
        message: \"Choose a check-in and a check-out date.\",
      },
    };
  }
  return { checkIn, checkOut };
}

/**
 * @param {object} [deps] replaceable in tests
 */
function createModificationService({
  ReservationModel = require(\"../models/reservation\"),
  ListingModel = require(\"../models/listing\"),
  ledgerService = require(\"./ledger\"),
  pricing = require(\"./pricing\"),
  notifier = null,
  logger = null,
} = {}) {
  async function tell(event, reservation) {
    if (!notifier) return;
    try {
      await notifier.dispatch(event, { reservation });
    } catch {
      // a notification is a courtesy; dispatch already swallows its own errors
    }
  }

  // The reservation this person may change, or the 404 everyone else gets.
  async function load(id, user) {
    const reservation = OBJECT_ID.test(String(id)) ? await ReservationModel.findById(id) : null;
    if (!reservation || !can(\"reservation:modify\", user, reservation)) {
      throw new NotFoundError(\"That booking does not exist.\");
    }
    return reservation;
  }

  async function loadListing(reservation) {
    const listing = await ListingModel.findById(reservation.listing);
    if (!listing || !isPublic(listing)) {
      throw new ConflictError(
        \"This place is not open for bookings at the moment, so the dates cannot be changed.\",
        { code: \"listing_unavailable\" },
      );
    }
    return listing;
  }

  // Everything that can be known without writing: the rules, the nights taken
  // by someone ELSE (the booking's own nights do not count against it) and the
  // price. `problems` is empty exactly when the change may be tried.
  async function evaluate(reservation, listing, { checkIn, checkOut }, now) {
    const problems = [];
    if (
      formatDateOnly(checkIn) === formatDateOnly(reservation.checkIn) &&
      formatDateOnly(checkOut) === formatDateOnly(reservation.checkOut)
    ) {
      problems.push({ code: \"no_change\", message: \"These are the dates you already have.\" });
    }
    if (!problems.length) {
      problems.push(
        ...bookingProblems({ listing, checkIn, checkOut, guests: reservation.guests, now }),
      );
    }
    if (!problems.length) {
      const own = new Set(eachNight(reservation.checkIn, reservation.checkOut).map(keyOf));
      const taken = (
        await ledgerService.unavailableDates(listing._id, checkIn, checkOut, { now })
      ).filter((night) => !own.has(keyOf(night)));
      if (taken.length) {
        problems.push({
          code: \"nights_unavailable\",
          message: `These nights are not available: ${taken.map(formatDateOnly).join(\", \")}.`,
        });
      }
    }
    if (problems.length) return { problems, quote: null, differenceMinor: null };

    // QuoteRefusedError (422) when the place has no valid price any more.
    const quote = pricing.quote({ listing, checkIn, checkOut, guests: reservation.guests });
    const old = reservation.pricingSnapshot || {};
    if (old.currency && quote.currency !== old.currency) {
      return {
        problems: [
          {
            code: \"currency_changed\",
            message: \"The price of this place is now in a different currency, so the dates cannot be changed. Please cancel and book again.\",
          },
        ],
        quote: null,
        differenceMinor: null,
      };
    }
    return { problems: [], quote, differenceMinor: quote.totalMinor - old.totalMinor };
  }

  /**
   * What changing to these dates would mean, without changing anything. A
   * booking that cannot be changed is a 409; wrong dates come back as
   * `problems` (so the page can show them next to the form).
   * @returns {Promise<{ reservation, listing, requested: boolean, problems: object[],
   *   checkIn?: Date, checkOut?: Date, quote: object|null, differenceMinor: number|null,
   *   reapproval: boolean }>}
   */
  async function previewChange({ id, user, in: inRaw, out: outRaw, now = new Date() }) {
    const reservation = await load(id, user);
    const state = modifiability(reservation, now);
    if (!state.ok) throw new ConflictError(state.message, { code: state.code });
    const listing = await loadListing(reservation);
    const base = {
      reservation,
      listing,
      reapproval: reservation.status === \"pending\",
      quote: null,
      differenceMinor: null,
    };
    const asked = inRaw !== undefined || outRaw !== undefined;
    if (!asked) return { ...base, requested: false, problems: [] };

    const stay = parseStay(inRaw, outRaw);
    if (stay.problem) return { ...base, requested: true, problems: [stay.problem] };
    const result = await evaluate(reservation, listing, stay, now);
    return {
      ...base,
      requested: true,
      checkIn: stay.checkIn,
      checkOut: stay.checkOut,
      ...result,
    };
  }

  /**
   * Moves the stay. @throws NotFoundError 404 (not yours / missing),
   *   ConflictError 409 (not_modifiable, hold_expired, stay_started,
   *   listing_unavailable, nights_unavailable, conflict), ValidationError 400
   *   (rule code or no_change / invalid_dates), PriceChangedError 409,
   *   QuoteRefusedError 422
   * @returns {Promise<{ reservation: object, quote: object, differenceMinor: number, reapproval: boolean }>}
   */
  async function changeDates({
    id,
    user,
    in: inRaw,
    out: outRaw,
    expectedTotalMinor,
    now = new Date(),
  }) {
    const reservation = await load(id, user);
    const state = modifiability(reservation, now);
    if (!state.ok) throw new ConflictError(state.message, { code: state.code });
    const listing = await loadListing(reservation);

    const stay = parseStay(inRaw, outRaw);
    if (stay.problem) throw new ValidationError(stay.problem.message, { code: stay.problem.code });
    const { checkIn, checkOut } = stay;

    const result = await evaluate(reservation, listing, stay, now);
    if (result.problems.length) {
      const first = result.problems[0];
      if (first.code === \"nights_unavailable\") {
        throw new ConflictError(first.message, { code: \"nights_unavailable\" });
      }
      throw new ValidationError(first.message, { code: first.code });
    }
    const { quote, differenceMinor } = result;

    // The price the guest looked at must be the price that is stored.
    let expected = null;
    if (expectedTotalMinor !== undefined && expectedTotalMinor !== null && expectedTotalMinor !== \"\") {
      expected =
        typeof expectedTotalMinor === \"string\" && /^\\d{1,15}$/.test(expectedTotalMinor)
          ? Number(expectedTotalMinor)
          : expectedTotalMinor;
      if (!Number.isSafeInteger(expected) || expected < 0) {
        throw new ValidationError(\"The expected total must be a whole number of paise.\");
      }
    }
    if (expected !== null && expected !== quote.totalMinor) throw new PriceChangedError(quote);

    const pending = reservation.status === \"pending\";
    const newHold = pending ? instantAfter(now, PENDING_HOLD_MS) : null;
    const { after, added } = diffNights(
      reservation.checkIn,
      reservation.checkOut,
      checkIn,
      checkOut,
    );
    const source = { kind: \"reservation\", id: reservation._id };

    // 1. Hold the new nights first. A conflict leaves everything as it was.
    if (added.length) {
      await ledgerService.reserveNights(listing._id, added, source, newHold, { now });
    }
    const undo = async () => {
      if (!added.length) return;
      try {
        await ledgerService.releaseNightsOn(reservation._id, added);
      } catch (err) {
        // Rows of a live booking outside its dates: the sweeper cannot see
        // them, but they only block (never double-book) those nights.
        if (logger) {
          logger.error(
            { err, reservation: String(reservation._id) },
            \"nights added by a failed date change were not released\",
          );
        }
      }
    };

    let updated;
    try {
      // 2. The kept nights of a pending request get the new answer time too.
      if (pending) await ledgerService.extendHold(reservation._id, newHold, { now });

      // 3. One winner.
      const old = reservation.pricingSnapshot || {};
      const entry = {
        from: reservation.status,
        to: reservation.status,
        at: now,
        actor: \"guest\",
        by: user._id,
        note: `dates changed from ${formatDateOnly(reservation.checkIn)} - ${formatDateOnly(reservation.checkOut)} to ${formatDateOnly(checkIn)} - ${formatDateOnly(checkOut)}`,
      };
      updated = await ReservationModel.findOneAndUpdate(
        {
          _id: reservation._id,
          status: reservation.status,
          checkIn: reservation.checkIn,
          checkOut: reservation.checkOut,
          ...(pending ? { holdExpiresAt: { $gt: now } } : {}),
        },
        {
          $set: {
            checkIn,
            checkOut,
            nights: quote.nights,
            pricingSnapshot: quote,
            ...(pending ? { holdExpiresAt: newHold } : {}),
          },
          $push: {
            statusHistory: entry,
            modifications: {
              at: now,
              by: user._id,
              from: {
                checkIn: reservation.checkIn,
                checkOut: reservation.checkOut,
                nights: reservation.nights,
                totalMinor: old.totalMinor,
              },
              to: { checkIn, checkOut, nights: quote.nights, totalMinor: quote.totalMinor },
              differenceMinor,
              currency: quote.currency,
              reapproval: pending,
            },
          },
        },
        { new: true },
      );
    } catch (err) {
      await undo();
      throw err;
    }
    if (!updated) {
      await undo();
      throw new ConflictError(\"That booking changed. Please reload and try again.\", {
        code: \"conflict\",
      });
    }

    // 4. Give up the old nights. Idempotent: if it fails the nights only stay
    // blocked, and running it again repairs it.
    try {
      await ledgerService.trimNights(reservation._id, after);
    } catch (err) {
      if (logger) {
        logger.error(
          { err, reservation: String(reservation._id) },
          \"nights given up by a date change were not released\",
        );
      }
    }

    await tell(\"reservation.modified\", updated);
    return { reservation: updated, quote, differenceMinor, reapproval: pending };
  }

  return { previewChange, changeDates };
}

/**
 * Words for the price difference. Pure.
 * @returns {{ kind: \"more\"|\"less\"|\"same\", text: string, amountText: string }}
 */
function describeDifference(differenceMinor, { formatMoney, currency }) {
  const amountText = formatMoney(Math.abs(differenceMinor), currency);
  if (differenceMinor > 0) {
    return { kind: \"more\", amountText, text: `The new stay costs ${amountText} more.` };
  }
  if (differenceMinor < 0) {
    return { kind: \"less\", amountText, text: `The new stay costs ${amountText} less.` };
  }
  return { kind: \"same\", amountText, text: \"The new stay costs the same.\" };
}

module.exports = {
  ...createModificationService({
    notifier: require(\"./notificationEvents\").notifier,
  }),
  createModificationService,
  modifiability,
  diffNights,
  describeDifference,
};

// Nearby places for a listing (P15-T01), from OpenStreetMap through the
// Overpass API. This is the ONLY code that calls Overpass, and it is reached
// only from: publishing a listing, a host's refresh button, the retry job and
// scripts/refresh-nearby.js. Guests and visitors only ever read what is stored
// in `listing.nearby` (a test checks that no public code imports this file).
//
// Privacy: the search is centred on the listing's PRECISE point, which never
// leaves the server. Every stored distance is measured from the PUBLIC
// (approximate) point instead. Exact distances to several places with known
// positions would let anyone work the home's position out again.
//
// What is stored (listing.nearby):
//   fetchedAt, source, key (hash of the precise point the data is for),
//   items [{ category, name, kind, distanceM }] (top 5 per category, nearest first),
//   attemptedAt, failures, nextRetryAt (set while a fetch keeps failing).
// A failed fetch never erases earlier data.
const crypto = require(\"node:crypto\");
const {
  SOURCE,
  CATEGORIES,
  RULES,
  readNearbyConfig,
} = require(\"../config/nearby\");
const { distanceMeters, publicPointOf, toMapPoint } = require(\"../utils/geo\");

class NearbyUnavailableError extends Error {
  constructor(message, { retryable = true, retryAfterMs = 0 } = {}) {
    super(message);
    this.name = \"NearbyUnavailableError\";
    this.retryable = retryable;
    this.retryAfterMs = retryAfterMs;
  }
}

// ---- small helpers --------------------------------------------------------

/** `date` moved by `ms` (no Date constructor with an argument; see noUserDate). */
function shift(date, ms) {
  const moved = new Date();
  moved.setTime(date.getTime() + ms);
  return moved;
}

const sleepFor = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

/** Same precise point -> same key; used to notice that the address moved. */
function keyFor(point) {
  return crypto
    .createHash(\"sha256\")
    .update(`${point.lng.toFixed(5)},${point.lat.toFixed(5)}`)
    .digest(\"hex\")
    .slice(0, 16);
}

// Control characters and bidi overrides can hide or reorder text.
const UNSAFE_CHARS = /[\\u0000-\\u001F\\u007F-\\u009F\\u200E\\u200F\\u202A-\\u202E\\u2066-\\u2069]/g;

/** Plain text, one line, at most 100 characters. HTML is NOT removed: every view escapes with <%= %>. */
function cleanName(value) {
  if (typeof value !== \"string\") return null;
  const text = value.replace(UNSAFE_CHARS, \" \").replace(/\\s+/g, \" \").trim().slice(0, 100);
  return text || null;
}

function kindOf(tags) {
  const raw =
    tags.amenity || tags.shop || tags.leisure || tags.highway || tags.railway || tags.public_transport;
  return typeof raw === \"string\" && /^[a-z_]{1,40}$/.test(raw) ? raw : null;
}

// ---- query and parser -----------------------------------------------------

/** Overpass QL for one category around the precise point. */
function buildQuery(point, category, { maxElements = RULES.maxElements } = {}) {
  const around = `(around:${category.radiusM},${point.lat.toFixed(6)},${point.lng.toFixed(6)})`;
  const parts = category.selectors.map((selector) => `  nwr${selector}${around};`);
  return [
    \"[out:json][timeout:20][maxsize:33554432];\",
    \"(\",
    ...parts,
    \");\",
    `out center tags ${maxElements};`,
  ].join(\"\\n\");
}

/**
 * Overpass elements -> the top places of one category, nearest first.
 * @param {object[]} elements Overpass `elements`
 * @param {{id: string}} category
 * @param {{lng:number, lat:number}} origin where distances are measured from (the PUBLIC point)
 */
function parseElements(elements, category, origin, { topN = RULES.topN } = {}) {
  const found = [];
  for (const element of Array.isArray(elements) ? elements : []) {
    if (!element || typeof element !== \"object\") continue;
    const tags = element.tags && typeof element.tags === \"object\" ? element.tags : {};
    const lat = element.lat ?? (element.center && element.center.lat);
    const lng = element.lon ?? (element.center && element.center.lon);
    const place = toMapPoint({ type: \"Point\", coordinates: [lng, lat] });
    if (!place) continue;
    const name = cleanName(tags.name) || cleanName(tags[\"name:en\"]);
    const kind = kindOf(tags);
    found.push({
      category: category.id,
      name,
      kind,
      // Rounded to 10 m: more precision would only pretend to be accurate.
      distanceM: Math.round(distanceMeters(origin, place) / 10) * 10,
    });
  }
  found.sort((a, b) => a.distanceM - b.distanceM || String(a.name).localeCompare(String(b.name)));

  // OpenStreetMap often has two entries for one place (a node and a building)
  // and chains repeat: keep the nearest of each name (or of each unnamed kind).
  const seen = new Set();
  const items = [];
  for (const item of found) {
    const key = item.name ? item.name.toLowerCase() : `(${item.kind})`;
    if (seen.has(key)) continue;
    seen.add(key);
    items.push(item);
    if (items.length >= topN) break;
  }
  return items;
}

// ---- Overpass client (one at a time, one retry) ---------------------------

let tail = Promise.resolve();
/** Global concurrency 1: tasks run strictly one after another in this process. */
function serial(task) {
  const run = tail.then(task, task);
  tail = run.catch(() => {});
  return run;
}

async function requestOnce(query, { fetchImpl, config }) {
  let response;
  try {
    response = await fetchImpl(config.endpoint, {
      method: \"POST\",
      headers: {
        \"User-Agent\": config.userAgent,
        Accept: \"application/json\",
        \"Content-Type\": \"application/x-www-form-urlencoded\",
      },
      body: new URLSearchParams({ data: query }).toString(),
      signal: AbortSignal.timeout(RULES.requestTimeoutMs),
    });
  } catch (err) {
    throw new NearbyUnavailableError(`Overpass did not answer (${err && err.name ? err.name : \"error\"})`);
  }
  if (response.status === 429 || response.status >= 500) {
    const seconds = Number(response.headers && response.headers.get && response.headers.get(\"retry-after\"));
    throw new NearbyUnavailableError(`Overpass is busy or down (HTTP ${response.status})`, {
      retryAfterMs: Number.isFinite(seconds) && seconds > 0 ? seconds * 1000 : 0,
    });
  }
  if (!response.ok) {
    throw new NearbyUnavailableError(`Overpass refused the query (HTTP ${response.status})`, { retryable: false });
  }
  let body;
  try {
    body = await response.json();
  } catch {
    throw new NearbyUnavailableError(\"Overpass sent something that is not JSON\");
  }
  // A query that ran out of time or memory can still answer 200, with a remark.
  if (body && typeof body.remark === \"string\" && /runtime error|timed out|out of memory/i.test(body.remark)) {
    throw new NearbyUnavailableError(\"Overpass could not finish the query in time\");
  }
  if (!body || !Array.isArray(body.elements)) {
    throw new NearbyUnavailableError(\"Overpass sent an unexpected answer\", { retryable: false });
  }
  return body.elements;
}

/** One request, with exactly one retry after a pause (Retry-After if given, capped). */
async function overpass(query, { fetchImpl, config, sleep }) {
  try {
    return await requestOnce(query, { fetchImpl, config });
  } catch (err) {
    if (!(err instanceof NearbyUnavailableError) || !err.retryable) throw err;
    await sleep(Math.min(err.retryAfterMs || RULES.retryPauseMs, RULES.maxRetryAfterMs));
    return requestOnce(query, { fetchImpl, config });
  }
}

// ---- when may we fetch? ---------------------------------------------------

/**
 * @returns {{ ok: true } | { ok: false, reason: \"fresh\"|\"cooldown\"|\"throttled\", retryAt: Date|null }}
 */
function mayFetch(stored, key, { manual, now }) {
  const n = stored || {};
  const sameSpot = n.key === key;
  if (n.attemptedAt && now.getTime() - n.attemptedAt.getTime() < RULES.attemptThrottleMs) {
    return { ok: false, reason: \"throttled\", retryAt: shift(n.attemptedAt, RULES.attemptThrottleMs) };
  }
  if (n.fetchedAt && sameSpot) {
    const age = now.getTime() - n.fetchedAt.getTime();
    if (manual && age < RULES.manualCooldownMs) {
      return { ok: false, reason: \"cooldown\", retryAt: shift(n.fetchedAt, RULES.manualCooldownMs) };
    }
    if (!manual && age < RULES.freshMs) {
      return { ok: false, reason: \"fresh\", retryAt: shift(n.fetchedAt, RULES.freshMs) };
    }
  }
  return { ok: true };
}

/** For the host button: can this listing be refreshed now? (no network, no writes) */
function manualVerdict(listing, { now = new Date(), config = readNearbyConfig() } = {}) {
  if (!config.enabled) return { ok: false, reason: \"disabled\", retryAt: null };
  const precise = toMapPoint(listing && listing.geometry);
  if (!precise) return { ok: false, reason: \"no_location\", retryAt: null };
  return mayFetch(listing.nearby, keyFor(precise), { manual: true, now });
}

// ---- the refresh ----------------------------------------------------------

function loadListingModel(deps) {
  return deps.Listing || require(\"../models/listing\");
}

/**
 * Fetches and stores the nearby places of one published listing.
 * Never throws for an Overpass problem: it reports `failed` and schedules a retry.
 * @returns {Promise<{status: \"disabled\"|\"skipped\"|\"no_location\"|\"fresh\"|\"cooldown\"|\"throttled\"|\"updated\"|\"failed\", ...}>}
 */
async function refreshListing(listing, { manual = false, now = new Date(), deps = {} } = {}) {
  const config = deps.config || readNearbyConfig();
  if (!config.enabled) return { status: \"disabled\" };
  if (!listing || listing.status !== \"published\" || listing.deletedAt) return { status: \"skipped\" };

  const precise = toMapPoint(listing.geometry);
  const origin = precise && publicPointOf(listing);
  if (!precise || !origin) return { status: \"no_location\" };

  const key = keyFor(precise);
  const verdict = mayFetch(listing.nearby, key, { manual, now });
  if (!verdict.ok) return { status: verdict.reason, retryAt: verdict.retryAt };

  const Listing = loadListingModel(deps);
  const fetchImpl = deps.fetch || globalThis.fetch;
  const sleep = deps.sleep || sleepFor;
  const log = deps.log || { info() {}, warn() {} };

  return serial(async () => {
    try {
      const items = [];
      for (const category of CATEGORIES) {
        const elements = await overpass(buildQuery(precise, category), { fetchImpl, config, sleep });
        items.push(...parseElements(elements, category, origin));
      }
      await Listing.updateOne(
        { _id: listing._id },
        {
          $set: {
            nearby: {
              fetchedAt: now,
              attemptedAt: now,
              source: SOURCE,
              key,
              items,
              failures: 0,
              nextRetryAt: null,
            },
          },
        },
      );
      log.info({ listingId: String(listing._id), places: items.length }, \"nearby places updated\");
      return { status: \"updated\", count: items.length };
    } catch (err) {
      if (!(err instanceof NearbyUnavailableError)) throw err;
      const failures = ((listing.nearby && listing.nearby.failures) || 0) + 1;
      const wait = RULES.retryBackoffMs[Math.min(failures - 1, RULES.retryBackoffMs.length - 1)];
      const nextRetryAt = shift(now, wait);
      // Dot paths: whatever was stored before stays.
      await Listing.updateOne(
        { _id: listing._id },
        { $set: { \"nearby.attemptedAt\": now, \"nearby.failures\": failures, \"nearby.nextRetryAt\": nextRetryAt } },
      );
      log.warn({ listingId: String(listing._id), failures, reason: err.message }, \"nearby places not updated\");
      return { status: \"failed\", failures, nextRetryAt, reason: err.message };
    }
  });
}

/**
 * Fire and forget: loads the listing and refreshes it in the background so a
 * slow Overpass never delays publishing. Every error is logged, none escapes.
 */
function scheduleRefresh(listingId, { manual = false, deps = {} } = {}) {
  let config;
  try {
    config = deps.config || readNearbyConfig();
  } catch (err) {
    if (deps.log) deps.log.warn({ err: err.message }, \"nearby places not configured\");
    return;
  }
  if (!config.enabled) return;
  const log = deps.log || { info() {}, warn() {} };
  setImmediate(async () => {
    try {
      const listing = await loadListingModel(deps).findById(listingId).lean();
      await refreshListing(listing, { manual, deps: { ...deps, config } });
    } catch (err) {
      log.warn({ listingId: String(listingId), err: err && err.message }, \"nearby refresh crashed\");
    }
  });
}

// ---- what the host page shows --------------------------------------------

/** Counts and names of what is stored, for the host's status page. No network. */
function summaryFor(listing, { now = new Date(), config } = {}) {
  const cfg = config || readNearbyConfig();
  const stored = (listing && listing.nearby) || {};
  const items = Array.isArray(stored.items) ? stored.items : [];
  const verdict = manualVerdict(listing, { now, config: cfg });
  return {
    enabled: cfg.enabled,
    fetchedOn: stored.fetchedAt ? stored.fetchedAt.toISOString().slice(0, 10) : null,
    source: stored.source || SOURCE,
    failing: Boolean(stored.nextRetryAt) && (stored.failures || 0) > 0,
    total: items.length,
    categories: CATEGORIES.map((c) => ({
      id: c.id,
      label: c.label,
      items: items
        .filter((i) => i.category === c.id)
        .map((i) => ({ name: i.name, kind: i.kind, distanceM: i.distanceM })),
    })),
    canRefresh: verdict.ok,
    retryOn: verdict.retryAt ? verdict.retryAt.toISOString().slice(0, 10) : null,
    refuseReason: verdict.ok ? null : verdict.reason,
  };
}

module.exports = {
  refreshListing,
  scheduleRefresh,
  manualVerdict,
  summaryFor,
  buildQuery,
  parseElements,
  cleanName,
  keyFor,
  mayFetch,
  NearbyUnavailableError,
  SOURCE,
};

// The retry job for nearby places (P15-T01): every few minutes, listings whose
// last fetch failed and whose `nearby.nextRetryAt` has passed are tried again,
// a few at a time (each refresh is 7 Overpass queries, one after another).
const { refreshListing } = require(\"./nearby\");
const { readNearbyConfig } = require(\"../config/nearby\");

const MINUTE_MS = 60 * 1000;

async function runRetryPass({
  Listing = require(\"../models/listing\"),
  refresh = refreshListing,
  now = new Date(),
  limit = 3,
  deps = {},
} = {}) {
  const due = await Listing.find({
    status: \"published\",
    deletedAt: null,
    \"nearby.nextRetryAt\": { $lte: now },
  })
    .sort({ \"nearby.nextRetryAt\": 1 })
    .limit(limit)
    .lean();
  const summary = { tried: 0, updated: 0, failed: 0 };
  for (const listing of due) {
    summary.tried += 1;
    const result = await refresh(listing, { manual: false, now, deps });
    if (result.status === \"updated\") summary.updated += 1;
    if (result.status === \"failed\") summary.failed += 1;
  }
  return summary;
}

/** Starts the job; returns a stop function. Does nothing when nearby places are off. */
function startNearbyRetry({ intervalMs = 5 * MINUTE_MS, logger, config } = {}) {
  const cfg = config || readNearbyConfig();
  if (!cfg.enabled) return () => {};
  const log = logger || { info() {}, warn() {} };
  let running = false;
  const timer = setInterval(async () => {
    if (running) return;
    running = true;
    try {
      const summary = await runRetryPass({ deps: { log, config: cfg } });
      if (summary.tried) log.info(summary, \"nearby retry pass\");
    } catch (err) {
      log.warn({ err: err && err.message }, \"nearby retry pass failed\");
    } finally {
      running = false;
    }
  }, intervalMs);
  timer.unref();
  return () => clearInterval(timer);
}

module.exports = { runRetryPass, startNearbyRetry };

// What the public listing page shows about the surroundings (P15-T02).
//
// A pure function over `listing.nearby` (stored by src/services/nearby.js, P15-T01):
// no network, no database. Guests only ever read stored data.
//
// Privacy: the stored items have no coordinates at all, and their distances are
// already measured from the PUBLIC (approximate) point. Here they are rounded
// again, to the nearest 50 m, and the map layer is just one dashed circle per
// category around that approximate centre: a radius, never a position. So the
// rule \"no per-item coordinates when fewer than 3 places are within 500 m\" holds
// by construction: there are never any.
const { CATEGORIES, SOURCE } = require(\"../config/nearby\");

const STEP_M = 50;

/** Nearest 50 m, never below 50 (\"about 0 m\" would mean \"on the spot\"). */
const roundDistance = (meters) => Math.max(STEP_M, Math.round(meters / STEP_M) * STEP_M);

function distanceLabel(roundedM) {
  const text =
    roundedM < 1000 ? `${roundedM} m` : `${(Math.round(roundedM / 100) / 10).toFixed(1)} km`;
  return `\\u2248 ${text} straight-line`;
}

/** @returns {null | {fetchedOn:string, source:string, categories:object[], rings:object[]}} null = show nothing */
function neighborhoodFor(listing) {
  const stored = listing && listing.nearby;
  if (!stored || !stored.fetchedAt || !Array.isArray(stored.items)) return null;

  const categories = [];
  for (const category of CATEGORIES) {
    const items = stored.items
      .filter(
        (item) =>
          item &&
          item.category === category.id &&
          Number.isFinite(item.distanceM) &&
          item.distanceM >= 0,
      )
      .map((item) => ({
        name: item.name || null,
        kindLabel: item.kind ? String(item.kind).replace(/_/g, \" \") : \"place\",
        distanceM: roundDistance(item.distanceM),
      }))
      .sort((a, b) => a.distanceM - b.distanceM)
      .map((item) => ({ ...item, distanceLabel: distanceLabel(item.distanceM) }));
    if (items.length) {
      categories.push({
        id: category.id,
        label: category.label,
        items,
        nearestM: items[0].distanceM,
      });
    }
  }
  if (!categories.length) return null;

  return {
    fetchedOn: stored.fetchedAt.toISOString().slice(0, 10),
    source: stored.source || SOURCE,
    categories,
    // For the map: one circle per category, radius = its nearest place.
    rings: categories.map((c) => ({ id: c.id, label: c.label, radiusM: c.nearestM })),
  };
}

module.exports = { neighborhoodFor, roundDistance, distanceLabel };

// Emailing notifications and the member's email preferences (P11-T05).
//
// Rules (docs/EMAIL.md):
//   - The in-app notification is always stored (notificationEvents.js); this
//     only decides whether a COPY is also emailed.
//   - Only to an active account with a CONFIRMED address (emailVerifiedAt).
//   - A group the member switched off is not emailed; a group that is
//     `essential` always is, and says so in the footer.
//   - Every optional email has a \"stop these emails\" link: a signed address
//     (HMAC of member + group, keyed from SESSION_SECRET). Opening it shows a
//     button; the POST switches the group off, so a mail scanner that opens
//     links changes nothing.
//   - Sending is best effort: a failure is logged (never the address or the
//     link) and never reaches the booking or admin action that caused it.
const crypto = require(\"node:crypto\");
const { GROUPS, GROUP_BY_KEY, GROUP_OF_TYPE, TOGGLEABLE } = require(\"../config/notificationPrefs\");
const templates = require(\"../emails/templates\");

const TOKEN_PATTERN = /^[0-9a-f]{24}\\.[a-z]{3,20}\\.[A-Za-z0-9_-]{43}$/;

const keyFor = (secret) => crypto.createHash(\"sha256\").update(`dimora-unsubscribe:${secret}`).digest();
const mac = (secret, userId, group) =>
  crypto.createHmac(\"sha256\", keyFor(secret)).update(`${userId}.${group}`).digest(\"base64url\");

/** The token in a \"stop these emails\" link. */
function unsubscribeToken({ userId, group, secret }) {
  return `${userId}.${group}.${mac(secret, userId, group)}`;
}

/** @returns {{ userId: string, group: string } | null} null for anything not made by us */
function readUnsubscribeToken(token, secret) {
  if (typeof token !== \"string\" || !TOKEN_PATTERN.test(token)) return null;
  const [userId, group, given] = token.split(\".\");
  const want = Buffer.from(mac(secret, userId, group));
  const got = Buffer.from(given);
  if (want.length !== got.length || !crypto.timingSafeEqual(want, got)) return null;
  const def = GROUP_BY_KEY.get(group);
  return def && !def.essential ? { userId, group } : null;
}

/** Does this member want the email copy of a notification type? */
function wantsEmail(user, type) {
  const group = GROUP_OF_TYPE.get(type);
  if (!group) return false;
  if (group.essential) return true;
  const chosen = user.notificationEmail && user.notificationEmail[group.key];
  return typeof chosen === \"boolean\" ? chosen : group.default;
}

/** The groups with what this member has chosen, for the settings page. */
function effectivePrefs(user) {
  return GROUPS.map((g) => ({
    key: g.key,
    label: g.label,
    description: g.description,
    essential: g.essential,
    enabled: g.essential ? true : wantsEmail(user, g.types[0]),
  }));
}

const absolute = (baseUrl, path) => {
  const base = String(baseUrl).replace(/\\/+$/, \"\");
  return typeof path === \"string\" && path.startsWith(\"/\") && !path.startsWith(\"//\") ? `${base}${path}` : base;
};

/**
 * @param {object} deps
 * @param {{ send: Function }} deps.emailService
 * @param {string} deps.baseUrl  public address of the site
 * @param {string} deps.secret   SESSION_SECRET (keys the unsubscribe links)
 * @param {{ warn?: Function }} [deps.logger]
 * @param {object} [deps.UserModel]
 */
function createNotificationMailer({ emailService, baseUrl, secret, logger = {}, UserModel } = {}) {
  const Users = () => UserModel || require(\"../models/user\");

  /**
   * Emails the copy of one stored notification if the member allows it.
   * Never throws. @returns {Promise<{ sent: boolean, reason?: string }>}
   */
  async function deliver({ userId, type, payload }) {
    try {
      const group = GROUP_OF_TYPE.get(type);
      if (!group) return { sent: false, reason: \"no_group\" };
      const user = await Users()
        .findById(userId)
        .select(\"email username displayName status emailVerifiedAt notificationEmail\")
        .lean();
      if (!user || user.status !== \"active\") return { sent: false, reason: \"no_account\" };
      if (!user.emailVerifiedAt) return { sent: false, reason: \"unconfirmed\" };
      if (!wantsEmail(user, type)) return { sent: false, reason: \"switched_off\" };
      const id = String(user._id);
      const unsubscribe = group.essential
        ? undefined
        : absolute(baseUrl, `/email/unsubscribe/${unsubscribeToken({ userId: id, group: group.key, secret })}`);
      const message = templates.notification({
        name: user.displayName || user.username,
        title: payload.title,
        body: payload.body,
        link: absolute(baseUrl, payload.url),
        groupLabel: group.label,
        unsubscribeLink: unsubscribe,
      });
      await emailService.send({
        to: user.email,
        ...message,
        ...(unsubscribe ? { headers: { \"List-Unsubscribe\": `<${unsubscribe}>` } } : {}),
      });
      return { sent: true };
    } catch (err) {
      if (logger.warn) logger.warn({ type, err: { name: err && err.name, message: err && err.message } }, \"notification email was not sent\");
      return { sent: false, reason: \"failed\" };
    }
  }

  return { deliver };
}

/**
 * Saves the member's choices. Only the groups they may switch off are read;
 * a group missing from `input` counts as switched off (an unchecked box).
 */
async function savePrefs(userId, input, { UserModel } = {}) {
  const Users = UserModel || require(\"../models/user\");
  const body = input && typeof input === \"object\" ? input : {};
  const set = {};
  for (const key of TOGGLEABLE) set[`notificationEmail.${key}`] = body[key] === \"on\" || body[key] === true;
  await Users.updateOne({ _id: userId }, { $set: set });
  return set;
}

/** Uses an unsubscribe token. @returns {Promise<{ ok: boolean, group?: object }>} */
async function unsubscribe(token, secret, { UserModel } = {}) {
  const parsed = readUnsubscribeToken(token, secret);
  if (!parsed) return { ok: false };
  const Users = UserModel || require(\"../models/user\");
  const result = await Users.updateOne(
    { _id: parsed.userId, status: \"active\" },
    { $set: { [`notificationEmail.${parsed.group}`]: false } },
  );
  const matched = result.matchedCount !== undefined ? result.matchedCount : result.n;
  return matched ? { ok: true, group: GROUP_BY_KEY.get(parsed.group) } : { ok: false };
}

module.exports = {
  createNotificationMailer,
  unsubscribeToken,
  readUnsubscribeToken,
  wantsEmail,
  effectivePrefs,
  savePrefs,
  unsubscribe,
  TOKEN_PATTERN,
};

// Booking and listing events -> notifications (P11-T04).
//
//   plan(event, ctx)      -> [{ userId, type, ref, payload }]   pure: who is told what
//   notifier.dispatch(event, ctx)                               sends the plan, never throws
//
// The table below is the whole policy: for each event, who is told, the
// notification type, the text and the link. Texts are plain; they use only
// facts the recipient may know (the listing title, the dates, the reason an
// admin gave the host). Nobody is told about their own action: the guest who
// cancels is not notified that they cancelled.
//
//   event                  told            type                        link
//   reservation.requested  host            reservation.requested       /host/reservations
//   reservation.booked     host            reservation.booked          /host/reservations   (instant book)
//   reservation.modified   host            reservation.modified        /host/reservations   (guest changed the dates, P09-T04)
//   reservation.accepted   guest           reservation.accepted        /trips/:id
//   reservation.declined   guest           reservation.declined        /trips/:id
//   reservation.expired    guest + host    reservation.expired         /trips/:id | /host/reservations
//   reservation.cancelled  the other side  reservation.cancelled       /trips/:id | /host/reservations
//   reservation.checkin_tomorrow  guest + host  reservation.checkin_tomorrow
//   review.available       guest           review.available            /trips/:id#review
//   listing.suspended      host            listing.suspended           /host/listings/:id/status
//   listing.restored       host            listing.restored            /host/listings/:id/status
//
// A failed notification never fails the booking or the admin action: dispatch
// logs and carries on. With no database connection there is nowhere to write,
// so it does nothing (this also keeps unit tests that stub the models quiet).
const { idOf } = require(\"../policies/shared\");
const { LIMITS } = require(\"../config/notifications\");

// Control characters would make `notify` refuse the whole message.
// eslint-disable-next-line no-control-regex
const CONTROL = /[\\u0000-\\u001f\\u007f]+/g;

/** One line of plain text no longer than `max` characters. */
function clip(value, max) {
  const text = String(value === undefined || value === null ? \"\" : value)
    .replace(CONTROL, \" \")
    .replace(/\\s+/g, \" \")
    .trim();
  return text.length <= max ? text : `${text.slice(0, max - 1).trimEnd()}\\u2026`;
}

const dayFormat = new Intl.DateTimeFormat(\"en-IN\", {
  day: \"numeric\",
  month: \"short\",
  year: \"numeric\",
  timeZone: \"UTC\", // a stay's dates are date-only UTC midnights
});
const day = (date) => (date instanceof Date ? dayFormat.format(date) : \"\");

const titleOf = (r) =>
  clip((r.listingSnapshot && r.listingSnapshot.title) || \"your stay\", 70);
const range = (r) => `${day(r.checkIn)} to ${day(r.checkOut)}`;
const plural = (n, word) => `${n} ${word}${n === 1 ? \"\" : \"s\"}`;

const guestUrl = (r) => `/trips/${idOf(r)}`;
const HOST_URL = \"/host/reservations\";

function reservationTargets(r) {
  return {
    ref: { kind: \"reservation\", id: idOf(r) },
    guest: idOf(r.guest),
    host: idOf(r.host),
  };
}

function toGuest(r, type, title, body, url = guestUrl(r)) {
  const t = reservationTargets(r);
  return { userId: t.guest, type, ref: t.ref, payload: { title, body, url } };
}
function toHost(r, type, title, body, url = HOST_URL) {
  const t = reservationTargets(r);
  return { userId: t.host, type, ref: t.ref, payload: { title, body, url } };
}

const EVENTS = {
  \"reservation.requested\": ({ reservation: r }) => [
    toHost(
      r,
      \"reservation.requested\",
      `New booking request: ${titleOf(r)}`,
      `A guest asked to stay ${range(r)} (${plural(r.nights, \"night\")}, ${plural(r.guests, \"guest\")}). Answer before the request runs out.`,
    ),
  ],
  \"reservation.booked\": ({ reservation: r }) => [
    toHost(
      r,
      \"reservation.booked\",
      `New booking: ${titleOf(r)}`,
      `${range(r)}, ${plural(r.nights, \"night\")}, ${plural(r.guests, \"guest\")}. It was confirmed instantly.`,
    ),
  ],
  // The guest moved the stay (P09-T04). A pending request starts a new answer
  // period, so the host is asked again; a confirmed stay only gets the news.
  \"reservation.modified\": ({ reservation: r }) => [
    toHost(
      r,
      \"reservation.modified\",
      r.status === \"pending\"
        ? `Request changed, please answer again: ${titleOf(r)}`
        : `Stay dates changed: ${titleOf(r)}`,
      r.status === \"pending\"
        ? `The guest changed the request to ${range(r)} (${plural(r.nights, \"night\")}). The 24 hours to answer start again.`
        : `The guest moved a confirmed stay to ${range(r)} (${plural(r.nights, \"night\")}). The old nights are open again.`,
    ),
  ],
  \"reservation.accepted\": ({ reservation: r }) => [
    toGuest(
      r,
      \"reservation.accepted\",
      `Booking confirmed: ${titleOf(r)}`,
      `The host accepted your request for ${range(r)}.`,
    ),
  ],
  \"reservation.declined\": ({ reservation: r }) => [
    toGuest(
      r,
      \"reservation.declined\",
      `Request declined: ${titleOf(r)}`,
      `The host declined your request for ${range(r)}.`,
    ),
  ],
  \"reservation.expired\": ({ reservation: r }) => [
    toGuest(
      r,
      \"reservation.expired\",
      `Request expired: ${titleOf(r)}`,
      `The host did not answer in time, so your request for ${range(r)} ended.`,
    ),
    toHost(
      r,
      \"reservation.expired\",
      `A request expired: ${titleOf(r)}`,
      `You did not answer the request for ${range(r)} in time.`,
    ),
  ],
  // Told: the side that did NOT cancel. `r.cancelledBy` is \"guest\" or \"host\".
  \"reservation.cancelled\": ({ reservation: r }) => {
    if (r.cancelledBy === \"guest\") {
      return [
        toHost(
          r,
          \"reservation.cancelled\",
          `Booking cancelled: ${titleOf(r)}`,
          `The guest cancelled ${range(r)}. Those nights are open again.`,
        ),
      ];
    }
    if (r.cancelledBy === \"host\") {
      const why = r.cancelReason ? ` Reason: ${clip(r.cancelReason, 160)}` : \"\";
      return [
        toGuest(
          r,
          \"reservation.cancelled\",
          `Booking cancelled by the host: ${titleOf(r)}`,
          `The host cancelled your stay for ${range(r)}.${why}`,
        ),
      ];
    }
    return []; // cancelled by neither side: nobody to tell
  },
  \"reservation.checkin_tomorrow\": ({ reservation: r }) => [
    toGuest(
      r,
      \"reservation.checkin_tomorrow\",
      `Check-in tomorrow: ${titleOf(r)}`,
      `Your stay starts ${day(r.checkIn)}.`,
    ),
    toHost(
      r,
      \"reservation.checkin_tomorrow\",
      `Guest arriving tomorrow: ${titleOf(r)}`,
      `A guest checks in on ${day(r.checkIn)}.`,
    ),
  ],
  \"review.available\": ({ reservation: r }) => [
    toGuest(
      r,
      \"review.available\",
      `How was ${titleOf(r)}?`,
      \"Your stay is over. You can leave a review.\",
      `${guestUrl(r)}#review`,
    ),
  ],
  \"listing.suspended\": ({ listing, reason }) => [
    listingNotice(
      listing,
      \"listing.suspended\",
      `Your listing was suspended: ${clip(listing.title, 70)}`,
      `It is no longer visible to guests.${reason ? ` Reason: ${clip(reason, 200)}` : \"\"}`,
    ),
  ],
  \"listing.restored\": ({ listing }) => [
    listingNotice(
      listing,
      \"listing.restored\",
      `Your listing is visible again: ${clip(listing.title, 70)}`,
      \"An admin restored it. Guests can find and book it.\",
    ),
  ],
};

function listingNotice(listing, type, title, body) {
  const id = idOf(listing);
  return {
    userId: idOf(listing.owner),
    type,
    ref: { kind: \"listing\", id },
    payload: { title, body, url: `/host/listings/${id}/status` },
  };
}

/** The events this module knows. */
const EVENT_NAMES = Object.freeze(Object.keys(EVENTS));

/**
 * Who is told what for `event`. Pure. Texts are cut to the notification limits.
 * Entries without a recipient are left out.
 * @throws {Error} for an unknown event name (a programming mistake)
 */
function plan(event, ctx) {
  const build = Object.prototype.hasOwnProperty.call(EVENTS, event)
    ? EVENTS[event]
    : null;
  if (!build) throw new Error(`Unknown notification event: ${event}`);
  return build(ctx || {})
    .filter((p) => p && p.userId)
    .map((p) => ({
      ...p,
      payload: {
        title: clip(p.payload.title, LIMITS.title),
        body: clip(p.payload.body, LIMITS.body),
        url: p.payload.url,
      },
    }));
}

const dbConnected = () => require(\"mongoose\").connection.readyState === 1;

/**
 * @param {object} [deps] `notify` (default: services/notifications), `connected`
 *   (default: the Mongoose connection is open), `logger`, `mailer`
 */
function createNotifier({ notify, connected = dbConnected, logger = console, mailer = null } = {}) {
  const send = notify || ((...args) => require(\"./notifications\").notify(...args));
  // Email copies (P11-T05): `{ deliver({ userId, type, payload }) }`, set once the
  // app has an email service. Sent in the background: a slow mail provider must
  // not slow down a booking. `pending` lets tests and shutdown wait for them.
  let emailer = mailer;
  const pending = new Set();
  function queueEmail(p) {
    if (!emailer) return;
    const job = Promise.resolve()
      .then(() => emailer.deliver({ userId: p.userId, type: p.type, payload: p.payload }))
      .catch((err) => logger.warn(`notification email ${p.type} failed: ${err && err.message}`))
      .finally(() => pending.delete(job));
    pending.add(job);
  }
  /** Sends the plan for `event`. Never throws. @returns {Promise<number>} how many were stored */
  async function dispatch(event, ctx) {
    let sent = 0;
    try {
      if (!connected()) return 0;
      for (const p of plan(event, ctx)) {
        try {
          await send(p.userId, p.type, p.ref, p.payload);
          sent += 1;
          queueEmail(p); // only for a notification that was stored
        } catch (err) {
          logger.warn(`notification ${p.type} was not stored: ${err && err.message}`);
        }
      }
    } catch (err) {
      logger.warn(`notification event ${event} failed: ${err && err.message}`);
    }
    return sent;
  }
  return {
    dispatch,
    setMailer(next) {
      emailer = next || null;
    },
    /** Resolves when every email started so far has finished (tests, shutdown). */
    async idle() {
      while (pending.size) await Promise.all([...pending]);
    },
  };
}

module.exports = { plan, createNotifier, notifier: createNotifier(), EVENT_NAMES, clip };

// Notifications (P11-T01): create one for one member, count and list a
// member's own, mark them read.
//
//   notify(userId, type, ref, payload, options)  -> the stored row
//   countUnread(userId, options)                 -> number
//   listFor(userId, { show, page }, options)     -> { items, page, ... }
//   markRead(userId, id, options)                -> { changed }
//   markAllRead(userId, options)                 -> { updated }
//
// Rules, all enforced here and never by a form or a script:
// - `notify` writes exactly one row, for exactly the member it is given.
//   Who should be told about an event is decided by the caller (P11-T04);
//   this file never looks anyone up and never copies a row to someone else.
// - Every read and every update has `user` in its filter, so a member can
//   only count, list or mark their own rows. Someone else's id and a missing
//   id are the same 404.
// - Text is plain text (title <= 120, body <= 300 characters); the link must
//   be a same-site path. Anything else in `payload` is dropped. A bad value
//   throws a ValidationError and nothing is written.
// - Reading a row (once, or all) sets `readAt` and `deleteAfter`; the TTL index
//   deletes it READ_RETENTION_DAYS later. Marking again changes nothing.
//
// `options` lets tests pass `{ NotificationModel, now }`.
const {
  REF_KINDS,
  TYPE_PATTERN,
  LIMITS,
  READ_RETENTION_DAYS,
  PAGE_SIZE,
} = require(\"../config/notifications\");
const { safeRedirectPath } = require(\"../utils/safeRedirect\");
const { NotFoundError, ValidationError } = require(\"../utils/errors\");
const { DEFAULT_TIMEZONE } = require(\"../utils/dates\");

const OBJECT_ID = /^[0-9a-f]{24}$/i;
const DAY_MS = 24 * 60 * 60 * 1000;
// eslint-disable-next-line no-control-regex
const CONTROL = /[\\u0000-\\u0008\\u000b\\u000c\\u000e-\\u001f\\u007f]/;

const model = (options) =>
  (options && options.NotificationModel) || require(\"../models/notification\");
const clock = (options) => (options && options.now) || new Date();

/** The 24-character hex text of an id, an ObjectId or a user document; else null. */
function idText(value) {
  const raw = value && value._id !== undefined ? value._id : value;
  if (raw === null || raw === undefined || Array.isArray(raw)) return null;
  const text = typeof raw === \"string\" ? raw : String(raw);
  return OBJECT_ID.test(text) ? text.toLowerCase() : null;
}

function requireUser(userId) {
  const id = idText(userId);
  if (!id) throw new ValidationError(\"A notification needs a valid recipient.\");
  return id;
}

/** A trimmed plain-text string within `max` characters, or a ValidationError. */
function text(value, name, max, { required = false } = {}) {
  if (value === undefined || value === null || value === \"\") {
    if (required) throw new ValidationError(`A notification needs a ${name}.`);
    return undefined;
  }
  if (typeof value !== \"string\") {
    throw new ValidationError(`The notification ${name} must be text.`);
  }
  const trimmed = value.trim();
  if (!trimmed) {
    if (required) throw new ValidationError(`A notification needs a ${name}.`);
    return undefined;
  }
  if (CONTROL.test(trimmed)) {
    throw new ValidationError(`The notification ${name} has control characters.`);
  }
  if (trimmed.length > max) {
    throw new ValidationError(
      `The notification ${name} is longer than ${max} characters.`,
    );
  }
  return trimmed;
}

function cleanRef(ref) {
  if (ref === undefined || ref === null) return undefined;
  if (typeof ref !== \"object\" || Array.isArray(ref)) {
    throw new ValidationError(\"The notification reference is not valid.\");
  }
  const id = idText(ref.id);
  if (!REF_KINDS.includes(ref.kind) || !id) {
    throw new ValidationError(\"The notification reference is not valid.\");
  }
  return { kind: ref.kind, id };
}

/**
 * Stores one notification for one member.
 * @param {*} userId the recipient (id, ObjectId or user document)
 * @param {string} type e.g. \"reservation.requested\"
 * @param {{ kind: string, id: * }} [ref] what it is about
 * @param {{ title: string, body?: string, url?: string }} payload
 */
async function notify(userId, type, ref, payload, options) {
  const user = requireUser(userId);
  if (
    typeof type !== \"string\" ||
    type.length > LIMITS.type ||
    !TYPE_PATTERN.test(type)
  ) {
    throw new ValidationError(\"The notification type is not valid.\");
  }
  const data = payload && typeof payload === \"object\" ? payload : {};
  const title = text(data.title, \"title\", LIMITS.title, { required: true });
  const body = text(data.body, \"text\", LIMITS.body);
  const url = text(data.url, \"link\", LIMITS.url);
  if (url !== undefined && safeRedirectPath(url, null) === null) {
    throw new ValidationError(\"The notification link must be a page on this site.\");
  }
  const doc = { user, type, title };
  const cleaned = cleanRef(ref);
  if (cleaned) doc.ref = cleaned;
  if (body !== undefined) doc.body = body;
  if (url !== undefined) doc.url = url;
  return model(options).create(doc);
}

/** How many of the member's notifications are unread. */
async function countUnread(userId, options) {
  const user = requireUser(userId);
  return model(options).countDocuments({ user, readAt: null });
}

function parsePage(raw) {
  const n = typeof raw === \"string\" && /^\\d{1,6}$/.test(raw) ? Number(raw) : 1;
  return n >= 1 ? n : 1;
}

const when = (date) =>
  new Intl.DateTimeFormat(\"en-IN\", {
    day: \"numeric\",
    month: \"short\",
    hour: \"numeric\",
    minute: \"2-digit\",
    hour12: true,
    timeZone: DEFAULT_TIMEZONE,
  }).format(date);

function describe(row) {
  const created = row.createdAt instanceof Date ? row.createdAt : null;
  return {
    id: String(row._id),
    type: row.type,
    title: row.title,
    body: row.body || \"\",
    // A stored link is trusted only if it still passes the same-site check.
    url: row.url ? safeRedirectPath(row.url, null) : null,
    read: Boolean(row.readAt),
    when: created ? when(created) : \"\",
    iso: created ? created.toISOString() : \"\",
  };
}

/**
 * One page of the member's own notifications, newest first.
 * @param {{ show?: string, page?: string }} query `show=unread` lists only unread
 */
async function listFor(userId, { show, page } = {}, options) {
  const user = requireUser(userId);
  const Notification = model(options);
  const unreadOnly = show === \"unread\";
  const filter = unreadOnly ? { user, readAt: null } : { user };
  const [total, unread] = await Promise.all([
    Notification.countDocuments(filter),
    unreadOnly
      ? Promise.resolve(null)
      : Notification.countDocuments({ user, readAt: null }),
  ]);
  const totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE));
  const current = Math.min(parsePage(page), totalPages);
  const rows = await Notification.find(filter)
    .sort({ createdAt: -1, _id: -1 })
    .skip((current - 1) * PAGE_SIZE)
    .limit(PAGE_SIZE)
    .lean();
  return {
    items: rows.map(describe),
    show: unreadOnly ? \"unread\" : \"all\",
    page: current,
    totalPages,
    total,
    unread: unreadOnly ? total : unread,
    pageSize: PAGE_SIZE,
  };
}

const readUpdate = (now) => ({
  $set: {
    readAt: now,
    deleteAfter: new Date(now.getTime() + READ_RETENTION_DAYS * DAY_MS),
  },
});

/**
 * Marks one of the member's notifications read. Doing it again is fine.
 * @returns {{ changed: boolean }} false when it was already read
 * @throws {NotFoundError} not the member's, or no such notification
 */
async function markRead(userId, id, options) {
  const user = requireUser(userId);
  const target = idText(id);
  if (!target) throw new NotFoundError(\"That notification does not exist.\");
  const Notification = model(options);
  const result = await Notification.updateOne(
    { _id: target, user, readAt: null },
    readUpdate(clock(options)),
  );
  if (result.modifiedCount > 0) return { changed: true };
  const mine = await Notification.exists({ _id: target, user });
  if (!mine) throw new NotFoundError(\"That notification does not exist.\");
  return { changed: false };
}

/** Marks all of the member's unread notifications read. */
async function markAllRead(userId, options) {
  const user = requireUser(userId);
  const result = await model(options).updateMany(
    { user, readAt: null },
    readUpdate(clock(options)),
  );
  return { updated: result.modifiedCount || 0 };
}

module.exports = {
  notify,
  countUnread,
  listFor,
  markRead,
  markAllRead,
  describe,
};

// Pricing (P08-T01): the one place that turns a listing's prices and a stay into
// an amount to pay (ADR-002). A pure function of its inputs: no database, no
// clock, no network, no floating point. Rounding is half up to the paisa, in
// src/utils/money.js. Rates and fees come from src/config/pricing.js.
//
// quote() returns
//   lines            what makes up the total, in display order; each line has a
//                    `code` (\"nights\", \"weekend_nights\", \"cleaning\",
//                    \"service_fee\", \"tax\") and `amountMinor`; the view writes the
//                    words. A line with `included: true` is shown but already
//                    inside the other amounts (tax in an inclusive price).
//   nights, subtotalMinor (the nights), cleaningMinor, serviceFeeMinor,
//   taxMinor, totalMinor, avgPerNightMinor, currency, taxMode, taxIncluded
//   breakdownVersion for stored snapshots (bump it when the shape changes)
// Always: totalMinor === the sum of the lines that are not `included` (the
// length discount line is negative).
//
// PRICE RULES (P08-T04), in the order they apply. Each shows as its own line.
//   1. Per night: a seasonal rate whose dates cover the night replaces the base
//      nightly price (seasons may not overlap; if stored data overlaps anyway,
//      the one that starts first wins). Lines: `season_nights` /
//      `season_weekend_nights`, with `label` (the season's name) and a `key`.
//   2. Weekend nights (config.weekendDays, the night that STARTS Friday or
//      Saturday): when the listing has a weekend markup (`pricing.weekendBps`),
//      the night costs the price from step 1 plus that percentage, in a season
//      too. Without a markup, a legacy absolute `pricing.weekendNightlyMinor`
//      applies to non-seasonal nights only. Lines: `weekend_nights`.
//   3. Length discount: a stay of 28+ nights gets the monthly percentage, of 7+
//      the weekly one; only the larger that applies, never both. It is taken
//      from the nights (steps 1 and 2) and never from the cleaning fee. Line:
//      `length_discount` (negative).
//   4. Cleaning fee, then service fee and tax on (nights - discount + cleaning);
//      the tax slab uses the average night price after the discount.
const defaultConfig = require(\"../config/pricing\");
const {
  percentOf,
  divideRound,
  multiplyMinor,
  sumMinor,
  mulDivRound,
  MAX_BPS,
} = require(\"../utils/money\");
const { eachNight, parseDateOnly } = require(\"../utils/dates\");
const { ValidationError, QuoteRefusedError } = require(\"../utils/errors\");

// Additive changes (new line codes, optional fields) keep version 1: an older
// stored snapshot is still read correctly.
const BREAKDOWN_VERSION = 1;
const MAX_DISCOUNT_BPS = 5000; // 50 %
const DEFAULT_WEEKLY_NIGHTS = 7;
const DEFAULT_MONTHLY_NIGHTS = 28;
const TAX_MODES = [\"exclusive\", \"inclusive\"];

const NO_PRICE =
  \"This listing does not have a valid nightly price, so it cannot be booked yet.\";

const isMinor = (value) => Number.isSafeInteger(value) && value >= 0;

function read(listing, path) {
  if (!listing || typeof listing !== \"object\") return undefined;
  if (typeof listing.get === \"function\") return listing.get(path);
  return path.split(\".\").reduce((node, key) => (node == null ? undefined : node[key]), listing);
}

/** Programming errors in the configuration are TypeErrors (a 500), never user messages. */
function assertConfig(config) {
  const bad = (what) => {
    throw new TypeError(`pricing config: ${what}`);
  };
  if (!config || typeof config !== \"object\") bad(\"missing\");
  if (!/^[A-Z]{3}$/.test(config.currency)) bad(\"currency must be a 3-letter code\");
  if (!Number.isInteger(config.serviceFeeBps) || config.serviceFeeBps < 0 || config.serviceFeeBps > MAX_BPS) {
    bad(\"serviceFeeBps must be an integer from 0 to 10000\");
  }
  if (!TAX_MODES.includes(config.taxMode)) bad(\"taxMode must be exclusive or inclusive\");
  if (!Array.isArray(config.taxSlabs) || config.taxSlabs.length === 0) bad(\"taxSlabs must be a non-empty list\");
  let previous = -1;
  config.taxSlabs.forEach((slab, index) => {
    const last = index === config.taxSlabs.length - 1;
    if (!Number.isInteger(slab.rateBps) || slab.rateBps < 0 || slab.rateBps > MAX_BPS) {
      bad(\"each slab needs a rateBps from 0 to 10000\");
    }
    if (slab.upToMinor === null) {
      if (!last) bad(\"only the last slab may have no upper limit\");
    } else if (!isMinor(slab.upToMinor) || slab.upToMinor <= previous) {
      bad(\"slab limits must be increasing integers\");
    } else {
      previous = slab.upToMinor;
    }
    if (last && slab.upToMinor !== null) bad(\"the last slab must have upToMinor: null\");
  });
  if (
    !Array.isArray(config.weekendDays) ||
    config.weekendDays.some((day) => !Number.isInteger(day) || day < 0 || day > 6)
  ) {
    bad(\"weekendDays must be a list of days 0-6\");
  }
}

function priceOf(listing, config) {
  const nightly = read(listing, \"pricing.nightlyMinor\");
  if (!Number.isSafeInteger(nightly) || nightly < 1) throw new QuoteRefusedError(NO_PRICE);

  const weekendValue = read(listing, \"pricing.weekendNightlyMinor\");
  const hasWeekend = weekendValue !== undefined && weekendValue !== null;
  if (hasWeekend && (!Number.isSafeInteger(weekendValue) || weekendValue < 1)) {
    throw new QuoteRefusedError(NO_PRICE);
  }

  const cleaningValue = read(listing, \"pricing.cleaningFeeMinor\");
  const hasCleaning = cleaningValue !== undefined && cleaningValue !== null;
  if (hasCleaning && !isMinor(cleaningValue)) {
    throw new QuoteRefusedError(\"This listing has an invalid cleaning fee, so it cannot be booked yet.\");
  }

  const currency = read(listing, \"pricing.currency\") ?? config.currency;
  if (currency !== config.currency) {
    throw new QuoteRefusedError(\"This listing's currency is not supported yet.\");
  }

  return {
    nightly,
    weekend: hasWeekend ? weekendValue : nightly,
    cleaning: hasCleaning ? cleaningValue : 0,
    currency,
    ...rulesOf(listing),
  };
}

const BAD_RULES = \"This listing has invalid price rules, so it cannot be booked yet.\";

/** The optional rules (P08-T04); anything unreadable refuses the quote rather than guessing. */
function rulesOf(listing) {
  const optionalBps = (path, max) => {
    const value = read(listing, path);
    if (value === undefined || value === null) return 0;
    if (!Number.isInteger(value) || value < 0 || value > max) throw new QuoteRefusedError(BAD_RULES);
    return value;
  };
  const weekendBps = optionalBps(\"pricing.weekendBps\", MAX_BPS);
  const weeklyBps = optionalBps(\"pricing.discounts.weeklyBps\", MAX_DISCOUNT_BPS);
  const monthlyBps = optionalBps(\"pricing.discounts.monthlyBps\", MAX_DISCOUNT_BPS);

  const raw = read(listing, \"pricing.seasonalRates\");
  const seasons = [];
  for (const entry of Array.isArray(raw) ? raw : []) {
    let from;
    let to;
    try {
      from = asDate(entry && entry.from, \"Season start\");
      to = asDate(entry && entry.to, \"Season end\");
    } catch {
      throw new QuoteRefusedError(BAD_RULES); // stored data, not user input
    }
    const nightly = entry && entry.nightlyMinor;
    if (
      !(from instanceof Date) ||
      !(to instanceof Date) ||
      Number.isNaN(from.getTime()) ||
      Number.isNaN(to.getTime()) ||
      to < from ||
      !Number.isSafeInteger(nightly) ||
      nightly < 1
    ) {
      throw new QuoteRefusedError(BAD_RULES);
    }
    seasons.push({ name: String((entry && entry.name) || \"Season\"), from, to, nightlyMinor: nightly });
  }
  seasons.sort((a, b) => a.from - b.from || a.to - b.to);
  return { weekendBps, weeklyBps, monthlyBps, seasons };
}

function asDate(value, label) {
  return typeof value === \"string\" ? parseDateOnly(value, label) : value;
}

function taxRateFor(averageMinor, slabs) {
  const slab = slabs.find((s) => s.upToMinor === null || averageMinor <= s.upToMinor);
  return slab.rateBps;
}

/**
 * @param {object} input
 * @param {object} input.listing    a listing document or plain object (reads `pricing.*`)
 * @param {Date|string} input.checkIn   date-only Date, or \"YYYY-MM-DD\"
 * @param {Date|string} input.checkOut  date-only Date (not charged), or \"YYYY-MM-DD\"
 * @param {number} input.guests     whole number, 1 or more (no price depends on it yet)
 * @param {object} [options]
 * @param {object} [options.config] defaults to src/config/pricing.js (tests pass their own)
 * @throws {ValidationError}  bad dates, a stay over 90 nights, bad guests
 * @throws {QuoteRefusedError} the listing has no usable price
 */
function quote({ listing, checkIn, checkOut, guests } = {}, { config = defaultConfig } = {}) {
  assertConfig(config);
  const nights = eachNight(asDate(checkIn, \"Check-in\"), asDate(checkOut, \"Check-out\"));
  if (!Number.isInteger(guests) || guests < 1) {
    throw new ValidationError(\"Guests must be a whole number of at least 1.\");
  }
  const price = priceOf(listing, config);

  // Steps 1 and 2: the price of every night, then one line per distinct group.
  const seasonOf = (night) => price.seasons.findIndex((x) => night >= x.from && night <= x.to);
  const groups = new Map(); // key -> {season index or -1, weekend, unit, quantity}
  for (const night of nights) {
    const index = seasonOf(night);
    const base = index === -1 ? price.nightly : price.seasons[index].nightlyMinor;
    const weekend = config.weekendDays.includes(night.getUTCDay());
    let unit = base;
    if (weekend) {
      if (price.weekendBps > 0) unit = base + percentOf(base, price.weekendBps);
      else if (index === -1) unit = price.weekend;
    }
    const key = `${index}:${weekend ? \"we\" : \"wd\"}`;
    const group = groups.get(key) || { index, weekend, unit, quantity: 0 };
    group.quantity += 1;
    groups.set(key, group);
  }
  // Base lines first (weekdays, weekends), then each season in date order.
  const ordered = [...groups.values()].sort(
    (a, b) => a.index - b.index || Number(a.weekend) - Number(b.weekend),
  );

  const lines = [];
  for (const group of ordered) {
    const line = {
      code: group.index === -1 ? (group.weekend ? \"weekend_nights\" : \"nights\") : group.weekend ? \"season_weekend_nights\" : \"season_nights\",
      quantity: group.quantity,
      unitMinor: group.unit,
      amountMinor: multiplyMinor(group.unit, group.quantity),
    };
    if (group.index !== -1) {
      line.key = `season_${group.index + 1}_${group.weekend ? \"weekend\" : \"weekday\"}`;
      line.label = price.seasons[group.index].name;
    }
    lines.push(line);
  }
  const subtotalMinor = sumMinor(lines.map((line) => line.amountMinor));

  // Step 3: the larger of the length discounts that apply, never both.
  const weeklyFrom = config.weeklyNights ?? DEFAULT_WEEKLY_NIGHTS;
  const monthlyFrom = config.monthlyNights ?? DEFAULT_MONTHLY_NIGHTS;
  const monthly = nights.length >= monthlyFrom ? price.monthlyBps : 0;
  const weekly = nights.length >= weeklyFrom ? price.weeklyBps : 0;
  const discountBps = Math.max(monthly, weekly);
  const discountMinor = discountBps > 0 ? percentOf(subtotalMinor, discountBps) : 0;
  if (discountMinor > 0) {
    lines.push({
      code: \"length_discount\",
      kind: monthly >= weekly ? \"monthly\" : \"weekly\",
      rateBps: discountBps,
      baseMinor: subtotalMinor,
      amountMinor: -discountMinor,
    });
  }
  const discountedMinor = subtotalMinor - discountMinor;
  const avgPerNightMinor = divideRound(discountedMinor, nights.length);

  const cleaningMinor = price.cleaning;
  if (cleaningMinor > 0) lines.push({ code: \"cleaning\", amountMinor: cleaningMinor });

  const accommodationMinor = sumMinor([discountedMinor, cleaningMinor]);
  const serviceFeeMinor = percentOf(accommodationMinor, config.serviceFeeBps);
  if (serviceFeeMinor > 0) {
    lines.push({
      code: \"service_fee\",
      rateBps: config.serviceFeeBps,
      baseMinor: accommodationMinor,
      amountMinor: serviceFeeMinor,
    });
  }

  const rateBps = taxRateFor(avgPerNightMinor, config.taxSlabs);
  const taxIncluded = config.taxMode === \"inclusive\";
  // Exclusive: tax on top. Inclusive: the part of the price that is tax.
  const taxMinor = taxIncluded
    ? accommodationMinor - mulDivRound(accommodationMinor, MAX_BPS, MAX_BPS + rateBps)
    : percentOf(accommodationMinor, rateBps);
  if (taxMinor > 0) {
    const line = { code: \"tax\", rateBps, baseMinor: accommodationMinor, amountMinor: taxMinor };
    if (taxIncluded) line.included = true;
    lines.push(line);
  }

  // The discount line is negative, so it is taken off after adding the others.
  const totalMinor =
    sumMinor(lines.filter((line) => !line.included && line.amountMinor >= 0).map((line) => line.amountMinor)) -
    discountMinor;

  return {
    lines,
    nights: nights.length,
    subtotalMinor,
    ...(discountMinor > 0 ? { discountMinor } : {}),
    cleaningMinor,
    serviceFeeMinor,
    taxMinor,
    totalMinor,
    avgPerNightMinor,
    currency: price.currency,
    taxMode: config.taxMode,
    taxIncluded,
    breakdownVersion: BREAKDOWN_VERSION,
  };
}

module.exports = { quote, BREAKDOWN_VERSION, assertConfig, MAX_DISCOUNT_BPS };

// Public profile data (P02-T03). What leaves this file is safe to show to
// anybody: the user is read with an explicit field list that leaves out the
// email, password hash, salt, role and status, so a template cannot print what
// it was never given.
const mongoose = require(\"mongoose\");
const { publicListingFilter } = require(\"../utils/visibility\");

const PUBLIC_FIELDS =
  \"username displayName avatar bio createdAt hostCancellationCount\";
const RECENT_REVIEWS = 5;
const EXCERPT = 200;

const monthYear = new Intl.DateTimeFormat(\"en-IN\", {
  month: \"long\",
  year: \"numeric\",
  timeZone: \"Asia/Kolkata\", // ADR-008
});

/** \"October 2026\" for a Date; \"\" for anything else. */
function formatMonthYear(date) {
  return date instanceof Date && !Number.isNaN(date.getTime())
    ? monthYear.format(date)
    : \"\";
}

function excerpt(text) {
  const clean = String(text ?? \"\")
    .replace(/\\s+/g, \" \")
    .trim();
  return clean.length > EXCERPT ? `${clean.slice(0, EXCERPT - 1)}…` : clean;
}

/**
 * @returns {Promise<object|null>} null when there is no such active user. The
 * same answer is given for a malformed id, an unknown id, a suspended account
 * and a deleted one, so a profile URL does not reveal which accounts exist.
 */
async function loadPublicProfile({ User, Listing, Review }, id) {
  if (typeof id !== \"string\" || !mongoose.isValidObjectId(id)) return null;
  const user = await User.findOne({ _id: id, status: \"active\" })
    .select(PUBLIC_FIELDS)
    .lean();
  if (!user) return null;

  const [listingCount, reviewCount, recent] = await Promise.all([
    Listing.countDocuments({ owner: user._id, ...publicListingFilter() }),
    Review.countDocuments({ author: user._id, status: { $ne: \"hidden\" } }),
    Review.find({ author: user._id, status: { $ne: \"hidden\" } })
      .sort({ createdAt: -1, _id: -1 })
      .limit(RECENT_REVIEWS * 3) // some may be on listings that are not public
      .select(\"rating comment createdAt\")
      .lean(),
  ]);

  // A review is shown only with a listing a visitor could open.
  const listings = recent.length
    ? await Listing.find({
        reviews: { $in: recent.map((review) => review._id) },
        ...publicListingFilter(),
      })
        .select(\"title reviews\")
        .lean()
    : [];
  const listingOf = new Map();
  for (const listing of listings) {
    for (const reviewId of listing.reviews || []) {
      listingOf.set(String(reviewId), listing);
    }
  }
  const reviews = recent
    .filter((review) => listingOf.has(String(review._id)))
    .slice(0, RECENT_REVIEWS)
    .map((review) => {
      const listing = listingOf.get(String(review._id));
      return {
        rating: review.rating,
        excerpt: excerpt(review.comment),
        listingId: String(listing._id),
        listingTitle: listing.title,
      };
    });

  return {
    id: String(user._id),
    displayName: user.displayName || user.username,
    username: user.username,
    avatarUrl: user.avatar && user.avatar.url ? user.avatar.url : null,
    bio: user.bio || \"\",
    memberSince: formatMonthYear(user.createdAt),
    listingCount,
    reviewCount,
    // Confirmed bookings this person cancelled as a host (P09-T03).
    hostCancellationCount: Number.isSafeInteger(user.hostCancellationCount)
      ? user.hostCancellationCount
      : 0,
    reviews,
  };
}

module.exports = { loadPublicProfile, formatMonthYear, excerpt, PUBLIC_FIELDS };

// Re-ordering \"Best match\" for a trip purpose (P15-T06; rules in
// src/config/purposes.js, explained on docs/RANKING.md).
//
// The score of a stay is the sum of the points of the rules it meets. Stays are
// ordered by score, highest first; stays with the same score keep the normal
// \"Best match\" order (rating, number of reviews, newest). The scoring is done in
// JavaScript on a small projection, so there is one definition of the rules and
// the page and the tests use the same one.
//
// Limit: only the MAX_RANKED best-matching stays (by the normal order) are
// scored; a search with more matches than that is ranked within its first
// MAX_RANKED. Pages past it keep the normal order.
const MAX_RANKED = 2000;
// The normal \"Best match\" order without search words (services/search.js
// sortSpec(\"relevance\")); tests/unit/purposeRank.sync.test.js keeps them equal.
const NORMAL_ORDER = Object.freeze({ ratingAvg: -1, ratingCount: -1, _id: -1 });
const FIELDS = \"amenities roomType capacity instantBook ratingAvg ratingCount\";

function meets(rule, listing) {
  const l = listing || {};
  switch (rule.kind) {
    case \"amenity\":
      return Array.isArray(l.amenities) && l.amenities.includes(rule.value);
    case \"roomType\":
      return l.roomType === rule.value;
    case \"minBedrooms\":
      return Number(l.capacity && l.capacity.bedrooms) >= rule.value;
    case \"minGuests\":
      return Number(l.capacity && l.capacity.guests) >= rule.value;
    case \"instantBook\":
      return l.instantBook === true;
    default:
      return false;
  }
}

/** { score, matched: [rule, ...] } for one listing (document or plain object). */
function scoreListing(purpose, listing) {
  const matched = purpose.rules.filter((rule) => meets(rule, listing));
  return { score: matched.reduce((sum, rule) => sum + rule.points, 0), matched };
}

const maxScore = (purpose) => purpose.rules.reduce((sum, rule) => sum + rule.points, 0);

/**
 * One page of `filter` ordered for `purpose`.
 * @returns {Promise<object[]>} Listing documents, in order
 */
async function rankedPage({ Listing, filter, purpose, page, pageSize }) {
  const rows = await Listing.find(filter)
    .select(FIELDS)
    .sort({ ...NORMAL_ORDER })
    .limit(MAX_RANKED)
    .lean();
  const scored = (Array.isArray(rows) ? rows : []).map((row, index) => ({
    id: row._id,
    index,
    score: scoreListing(purpose, row).score,
  }));
  scored.sort((a, b) => b.score - a.score || a.index - b.index);
  const start = (page - 1) * pageSize;
  const ids = scored.slice(start, start + pageSize).map((s) => s.id);
  if (ids.length === 0) return [];
  const docs = await Listing.find({ _id: { $in: ids } });
  const byId = new Map(docs.map((doc) => [String(doc._id), doc]));
  return ids.map((id) => byId.get(String(id))).filter(Boolean);
}

module.exports = { NORMAL_ORDER, MAX_RANKED, scoreListing, maxScore, meets, rankedPage };

// Query-plan review (P18-T02): the hot queries of the app, written down as data,
// and a small checker that says, for each one, whether a declared index can
// answer it and whether the index also delivers the sort order.
//
// Used by three things, so they cannot disagree:
//   tests/unit/queryPlans.test.js        every query has a usable index (no
//                                        collection scan) and the ones that
//                                        promise it need no in-memory sort;
//   scripts/explain-queries.js           runs the real explain(\"executionStats\")
//                                        on a database and prints the result;
//   tests/integration/queryPlans.db.test.js  the same check against MongoDB's
//                                        own planner.
//
// The checker is a model of the planner, not the planner: it knows the rules
// that decide the cases in this app (equality fields first, then the sort keys
// in order, direction may be reversed as a whole). MongoDB's explain is the
// authority; the DB test and the script check the model against it.
const { publicListingFilter } = require(\"../utils/visibility\");
const { parseDateOnly } = require(\"../utils/dates\");
const { sortSpec } = require(\"./search\");
const { tabQuery, TABS } = require(\"./trips\");
const { inboxQueries } = require(\"./hostInbox\");

// ---- the checker ------------------------------------------------------------

// Fields with so few values that an index starting with them narrows little.
const LOW_CARDINALITY = new Set([
  \"status\",
  \"targetKind\",
  \"deletedAt\",
  \"targetType\",
]);
const RANGE_OPS = new Set([\"$gt\", \"$gte\", \"$lt\", \"$lte\"]);
const GEO_OPS = new Set([
  \"$geoWithin\",
  \"$geoIntersects\",
  \"$near\",
  \"$nearSphere\",
]);

/** Classifies one field's condition: \"eq\", \"in\", \"range\", \"geo\" or \"other\" (not usable: $ne, $nin, regex...). */
function classify(condition) {
  if (condition === null || typeof condition !== \"object\") return \"eq\";
  if (condition instanceof Date || typeof condition.toHexString === \"function\")
    return \"eq\";
  if (condition instanceof RegExp) return \"other\";
  const ops = Object.keys(condition);
  if (ops.length && ops.every((op) => op === \"$eq\")) return \"eq\";
  if (ops.some((op) => GEO_OPS.has(op))) return \"geo\";
  if (ops.length && ops.every((op) => op === \"$in\")) return \"in\";
  if (ops.length && ops.every((op) => RANGE_OPS.has(op))) return \"range\";
  if (ops.some((op) => RANGE_OPS.has(op) || op === \"$in\")) return \"range\"; // mixed with $ne etc.: the range part still bounds the scan
  return \"other\";
}

/** Flattens $and and plain keys into { field: kind }; $or / $text are reported apart. */
function constraints(filter) {
  const fields = {};
  const result = { fields, or: null, text: false };
  const visit = (part) => {
    for (const [key, value] of Object.entries(part || {})) {
      if (key === \"$and\") value.forEach(visit);
      else if (key === \"$or\") result.or = value;
      else if (key === \"$text\") result.text = true;
      else if (key.startsWith(\"$\"))
        continue; // $nor, $expr...: no help to an index
      else {
        const kind = classify(value);
        // two conditions on one field: keep the stronger one
        const rank = { other: 0, range: 1, geo: 2, in: 3, eq: 4 };
        if (!fields[key] || rank[kind] > rank[fields[key]]) fields[key] = kind;
      }
    }
  };
  visit(filter);
  return result;
}

const sortEntries = (sort) =>
  Object.entries(sort || {}).filter(([, dir]) => dir === 1 || dir === -1);

/** Does this index, read forwards or backwards, deliver the sort after its equality keys? */
function deliversSort(keys, fields, sort) {
  const wanted = sortEntries(sort);
  if (!wanted.length) return true;
  for (const flip of [1, -1]) {
    let i = 0; // position in the sort
    let ok = true;
    for (const [field, dir] of Object.entries(keys)) {
      if (i >= wanted.length) break;
      if (fields[field] === \"eq\" && !(wanted[i][0] === field)) continue; // fixed by the filter
      if (field !== wanted[i][0] || dir * flip !== wanted[i][1]) {
        ok = false;
        break;
      }
      i += 1;
    }
    if (ok && i >= wanted.length) return true;
  }
  return false;
}

/**
 * @param {{ filter: object, sort?: object }} query
 * @param {Array<{ name: string, keys: object }>} indexes
 * @returns {{ usable: boolean, index: string|null, noSort: boolean, branches?: object[] }}
 */
function analyse(query, indexes) {
  const { fields, or, text } = constraints(query.filter);
  const sort = query.sort || {};

  if (or) {
    // Every branch must have an index of its own; a merged $or cannot be sorted by one.
    const branches = or.map((branch) =>
      analyse(
        { filter: { ...query.filter, $or: undefined, ...branch }, sort: {} },
        indexes,
      ),
    );
    const usable = branches.every((b) => b.usable);
    return { usable, index: null, noSort: false, branches };
  }

  const candidates = [];
  for (const { name, keys } of indexes) {
    const entries = Object.entries(keys);
    const first = entries[0];
    if (!first) continue;
    let usable = false;
    if (text) usable = Object.values(keys).includes(\"text\");
    else if (Object.values(keys).includes(\"text\")) usable = false;
    else if (Object.values(keys).includes(\"2dsphere\"))
      usable = fields[first[0]] === \"geo\";
    else if (fields[first[0]] && fields[first[0]] !== \"other\") usable = true;
    else if (
      !Object.keys(fields).length &&
      sortEntries(sort).length &&
      first[0] === sortEntries(sort)[0][0]
    )
      usable = true;
    if (!usable) continue;
    // how many leading keys the filter constrains (more is a tighter scan)
    let depth = 0;
    for (const [field] of entries) {
      if (fields[field] && fields[field] !== \"other\") depth += 1;
      else break;
    }
    const noSort =
      !text &&
      !Object.values(keys).includes(\"2dsphere\") &&
      deliversSort(keys, fields, sort);
    const geo = Object.values(keys).includes(\"2dsphere\");
    const score =
      depth * 10 + (noSort ? 5 : 0) + (geo ? 20 : 0) - entries.length * 0.01;
    candidates.push({
      name,
      noSort,
      score,
      lowFirst: LOW_CARDINALITY.has(first[0]),
    });
  }
  if (!candidates.length)
    return { usable: false, index: null, noSort: !sortEntries(sort).length };
  // `status: \"confirmed\"` matches most of the collection; an index that starts
  // with a person or a listing is the one MongoDB's planner prefers when it has both.
  const selective = candidates.filter((c) => !c.lowFirst);
  const pool = selective.length ? selective : candidates;
  const best = pool.reduce((a, b) => (b.score > a.score ? b : a));
  // The query needs no in-memory sort if ANY usable index delivers the order.
  const noSort = candidates.some((c) => c.noSort);
  return { usable: true, index: best.name, noSort };
}

// ---- the declared indexes ---------------------------------------------------

/** Mongoose's own name for an index that has no explicit one. */
const autoName = (keys) =>
  Object.entries(keys)
    .map(([k, v]) => `${k}_${v}`)
    .join(\"_\");

/** Every index a model declares (field-level `unique`/`index` ones included). */
function declaredIndexes(Model) {
  const list = Model.schema
    .indexes()
    .map(([keys, options]) => ({
      name: (options && options.name) || autoName(keys),
      keys,
      options: options || {},
    }));
  // `_id` is always indexed
  list.push({ name: \"_id_\", keys: { _id: 1 }, options: {} });
  return list;
}

// ---- the queries --------------------------------------------------------------

const ID = \"64b7f0c2a1b2c3d4e5f60718\";
const OTHER = \"64b7f0c2a1b2c3d4e5f60719\";
const DAY = parseDateOnly(\"2026-12-10\");
const LATER = parseDateOnly(\"2026-12-13\");
const NOW = new Date(); // an instant for the examples; dates are only made from values in utils/dates.js
NOW.setTime(Date.UTC(2026, 10, 20, 6));

const q = (id, model, group, source, filter, rest = {}) => ({
  id,
  model,
  group,
  source,
  filter,
  ...rest,
});

/**
 * Each query: where it runs (source), its filter and sort as the service builds
 * them, and what is promised:
 *   noSort    the index must also deliver the order (no in-memory SORT stage);
 *   bounded   a sort in memory is accepted because the set that is sorted is
 *             small by construction (one host's, one guest's, one city's);
 *   scan      a collection scan is accepted, with the reason (admin-only text search).
 * Filters marked \"mirrors\" are copied from the service by hand; the others call it.
 */
function hotQueries() {
  const inbox = inboxQueries(ID, DAY);
  const tabs = Object.fromEntries(
    TABS.map((t) => [
      t.key || t,
      tabQuery(t.key || t, ID, { now: NOW, today: DAY }),
    ]),
  );
  const published = publicListingFilter();
  const search = (name, extra = {}) => ({
    filter: { ...published, ...extra },
    sort: sortSpec(name).sort,
  });
  return [
    // ---- search (listings) ----
    q(
      \"search.relevance\",
      \"Listing\",
      \"search\",
      \"services/search.js sortSpec\",
      search(\"relevance\").filter,
      { sort: search(\"relevance\").sort, noSort: true },
