const MODELS = {
  Listing: () => require(\"../models/listing\"),
  Reservation: () => require(\"../models/reservation\"),
  StayNight: () => require(\"../models/stayNight\"),
  AvailabilityBlock: () => require(\"../models/availabilityBlock\"),
  Review: () => require(\"../models/review\"),
  Report: () => require(\"../models/report\"),
  AuditLog: () => require(\"../models/auditLog\"),
  User: () => require(\"../models/user\"),
};

/** The model class for a query's collection. */
const modelFor = (query) => MODELS[query.model]();

/** Every hot query with the checker's verdict against the declared indexes. */
function reviewQueries(queries = hotQueries()) {
  const cache = new Map();
  return queries.map((query) => {
    if (!cache.has(query.model))
      cache.set(query.model, declaredIndexes(modelFor(query)));
    const verdict = analyse(query, cache.get(query.model));
    return {
      ...query,
      ...verdict,
      indexes: cache.get(query.model).map((i) => i.name),
    };
  });
}

// ---- MongoDB's own account (explain) -----------------------------------------

/** Every stage of a plan, depth first, as { stage, indexName? }. */
function planStages(plan, out = []) {
  if (!plan || typeof plan !== \"object\") return out;
  out.push({
    stage: plan.stage,
    ...(plan.indexName ? { indexName: plan.indexName } : {}),
  });
  for (const key of [\"inputStage\", \"outerStage\", \"innerStage\"])
    planStages(plan[key], out);
  if (Array.isArray(plan.inputStages))
    plan.inputStages.forEach((s) => planStages(s, out));
  if (plan.shards) plan.shards.forEach((s) => planStages(s.winningPlan, out));
  return out;
}

/**
 * Runs `explain(\"executionStats\")` for one query on the connected database and
 * summarises it.
 * @returns {Promise<{ stages: string[], indexes: string[], collscan: boolean,
 *   sortInMemory: boolean, fetch: boolean, keysExamined: number,
 *   docsExamined: number, returned: number, millis: number }>}
 */
async function runExplain(query, { limit = 0 } = {}) {
  const Model = modelFor(query);
  let cursor = Model.find(query.filter, query.project || undefined);
  if (query.sort && Object.keys(query.sort).length)
    cursor = cursor.sort(query.sort);
  if (limit) cursor = cursor.limit(limit);
  const report = await cursor.explain(\"executionStats\");
  const stats = report.executionStats || {};
  const stages = planStages((report.queryPlanner || {}).winningPlan).map(
    (s) => s.stage,
  );
  const indexes = planStages((report.queryPlanner || {}).winningPlan)
    .filter((s) => s.indexName)
    .map((s) => s.indexName);
  return {
    stages,
    indexes: [...new Set(indexes)],
    collscan: stages.includes(\"COLLSCAN\"),
    sortInMemory: stages.includes(\"SORT\"),
    fetch: stages.includes(\"FETCH\"),
    keysExamined: stats.totalKeysExamined || 0,
    docsExamined: stats.totalDocsExamined || 0,
    returned: stats.nReturned || 0,
    millis: stats.executionTimeMillis || 0,
  };
}

/**
 * What a measured plan breaks, given what the query promises:
 * a collection scan (unless the query says why it is accepted), an in-memory
 * sort where the query promises none, a document fetch where it promises an
 * index-only answer.
 */
function violations(query, measured) {
  const found = [];
  if (measured.collscan && !query.scan) found.push(\"collection scan\");
  if (measured.sortInMemory && query.noSort) found.push(\"in-memory sort\");
  if (query.covered && (measured.fetch || measured.docsExamined > 0))
    found.push(\"reads documents (not index-only)\");
  return found;
}

module.exports = {
  analyse,
  constraints,
  classify,
  deliversSort,
  declaredIndexes,
  autoName,
  hotQueries,
  reviewQueries,
  modelFor,
  planStages,
  runExplain,
  violations,
};

// The quote the booking panel shows (P08-T02). It never prices anything
// itself: the amounts are exactly what services/pricing.js returns, the same
// call reservations.create makes, so the number a guest sees is the number
// that is stored (Signature #1). The rules and the taken nights are checked
// first; a stay that cannot be booked gets its reasons and no price.
//
//   getQuote(listing, query, { now, ledgerService, pricingService, alternatives })
//   -> { in, out, guests, bookable, problems: [{code, message}],
//        quote: <pricing.quote output> | null, expectedTotalMinor | null,
//        alternatives?: { radiusDays, windows: [{ in, out, nights, shiftDays, quote }] } }
//
// With `alternatives: true` and the nights taken, the answer also carries the
// nearest free stays of the same length (services/flexibleDates.js, P15-T04).
//
// Reasons for unavailable nights are dates only: a block, a reservation and a
// live hold read the same (no guest or host information leaves the server).
const ledger = require(\"./ledger\");
const pricing = require(\"./pricing\");
const { bookingProblems } = require(\"./bookingRules\");
const { parseQuoteQuery } = require(\"../validation/quoteQuery\");
const { formatDateOnly } = require(\"../utils/dates\");

async function getQuote(
  listing,
  query,
  {
    now = new Date(),
    ledgerService = ledger,
    pricingService = pricing,
    alternatives = false,
  } = {},
) {
  const { checkIn, checkOut, guests } = parseQuoteQuery(query);
  const base = {
    in: formatDateOnly(checkIn),
    out: formatDateOnly(checkOut),
    guests,
  };

  const problems = bookingProblems({ listing, checkIn, checkOut, guests, now });
  // Only a stay the rules accept is looked up in the ledger (its span is then
  // at most 90 nights).
  if (problems.length === 0) {
    const taken = await ledgerService.unavailableDates(
      listing._id,
      checkIn,
      checkOut,
      { now },
    );
    if (taken.length > 0) {
      problems.push({
        code: \"nights_unavailable\",
        message: `These nights are not available: ${taken.map(formatDateOnly).join(\", \")}.`,
      });
    }
  }
  if (problems.length > 0) {
    const answer = {
      ...base,
      bookable: false,
      problems,
      quote: null,
      expectedTotalMinor: null,
    };
    if (alternatives && problems.some((p) => p.code === \"nights_unavailable\")) {
      // Loaded here, not at the top: flexibleDates asks this service for prices.
      const { suggestAlternatives } = require(\"./flexibleDates\");
      answer.alternatives = await suggestAlternatives(
        listing,
        { checkIn, checkOut, guests },
        { now, ledgerService, pricingService },
      );
    }
    return answer;
  }
  // QuoteRefusedError (422) when the listing has no valid price.
  const quote = pricingService.quote({ listing, checkIn, checkOut, guests });
  return {
    ...base,
    bookable: true,
    problems: [],
    quote,
    expectedTotalMinor: quote.totalMinor,
  };
}

module.exports = { getQuote };

// How often a stay was shown and clicked under each ordering (P15-T06), kept
// in ListingStat so the trip-purpose ranking can be compared with the default
// order. Counters only: no user, no session, no time. A stay is \"shown\" when it
// is on a results page ordered by Best match (with or without a purpose), and
// \"clicked\" when its page is opened from that results page (`?from=<variant>`),
// once per listing per session.
//
// Reading the numbers (docs/RANKING.md): shown/clicked are per STAY, so one
// results page adds up to 12 \"shown\". Position, who is searching and refreshes
// all move click-through; the figure says what happened, not why.
const mongoose = require(\"mongoose\");
const { PURPOSE_SLUGS } = require(\"../config/purposes\");

const VARIANTS = Object.freeze([\"default\", ...PURPOSE_SLUGS]);
const isReady = () => mongoose.connection.readyState === 1;

async function recordShown({ ListingStat, ids, variant, ready = isReady }) {
  if (!VARIANTS.includes(variant) || !Array.isArray(ids) || ids.length === 0 || !ready()) return;
  await ListingStat.bulkWrite(
    ids.map((id) => ({
      updateOne: { filter: { listing: id }, update: { $inc: { [`ranking.${variant}.shown`]: 1 } }, upsert: true },
    })),
    { ordered: false },
  );
}

async function recordClick({ ListingStat, listingId, variant, ready = isReady }) {
  if (!VARIANTS.includes(variant) || !listingId || !ready()) return;
  await ListingStat.updateOne(
    { listing: listingId },
    { $inc: { [`ranking.${variant}.clicked`]: 1 } },
    { upsert: true },
  );
}

/** @returns {Promise<Array<{variant: string, shown: number, clicked: number, ctr: number|null}>>} */
async function summary({ ListingStat }) {
  const group = { _id: null };
  for (const v of VARIANTS) {
    group[`${v}_shown`] = { $sum: `$ranking.${v}.shown` };
    group[`${v}_clicked`] = { $sum: `$ranking.${v}.clicked` };
  }
  const [row] = await ListingStat.aggregate([{ $group: group }]);
  return VARIANTS.map((variant) => {
    const shown = (row && row[`${variant}_shown`]) || 0;
    const clicked = (row && row[`${variant}_clicked`]) || 0;
    return { variant, shown, clicked, ctr: shown > 0 ? clicked / shown : null };
  });
}

module.exports = { VARIANTS, recordShown, recordClick, summary };

// Rating aggregates of a listing (P12-T02): `ratingSum`, `ratingCount` and
// `ratingAvg` (= sum / count, 0 when there is no review).
//
// Every change is ONE atomic update of the listing document, written as an
// update pipeline that adds to the sum and the count and derives the average
// from the new values inside the same operation. Nothing is read first, so two
// reviews written at the same moment can never overwrite each other's total
// (a recompute from a stale read could).
//
// The same update also adds or removes the review in `listing.reviews`, so the
// list and the totals never disagree.
//
//   ratingUpdate({ add: { reviewId, stars } })      a review was written
//   ratingUpdate({ remove: { reviewId, stars } })   a review was deleted
//   ratingUpdate({ change: { from, to } })          a review's rating was edited
//   recomputeRatings(...)                           repair from the reviews themselves

const RATING = Object.freeze({ MIN: 1, MAX: 5 });

/** Only whole ratings 1 to 5 count towards an aggregate. */
const isCountable = (stars) =>
  Number.isInteger(stars) && stars >= RATING.MIN && stars <= RATING.MAX;

/** Stages that derive the average from the sum and count already in the document. */
const averageStage = {
  $set: {
    ratingAvg: {
      $cond: [
        { $gt: [\"$ratingCount\", 0] },
        { $divide: [\"$ratingSum\", \"$ratingCount\"] },
        0,
      ],
    },
  },
};

/**
 * The update pipeline for one review being added, removed or re-rated.
 * @param {{ add?: {reviewId: *, stars: number}, remove?: {reviewId: *, stars: number},
 *           change?: {from: number, to: number} }} change
 */
function ratingUpdate(change) {
  const { add, remove, change: rerate } = change;
  if ([add, remove, rerate].filter(Boolean).length !== 1)
    throw new TypeError(\"give exactly one of add, remove and change\");
  if (rerate) {
    // The review stays in the list; only the sum (and the count, if the old
    // rating was not countable) move. Still one atomic update.
    const { from, to } = rerate;
    const sumDelta =
      (isCountable(to) ? to : 0) - (isCountable(from) ? from : 0);
    const countDelta = (isCountable(to) ? 1 : 0) - (isCountable(from) ? 1 : 0);
    return [
      {
        $set: {
          ratingSum: {
            $max: [0, { $add: [{ $ifNull: [\"$ratingSum\", 0] }, sumDelta] }],
          },
          ratingCount: {
            $max: [0, { $add: [{ $ifNull: [\"$ratingCount\", 0] }, countDelta] }],
          },
        },
      },
      averageStage,
    ];
  }
  const { reviewId, stars } = add || remove;
  const sign = add ? 1 : -1;
  const counted = isCountable(stars);

  const reviews = add
    ? { $concatArrays: [{ $ifNull: [\"$reviews\", []] }, [reviewId]] }
    : {
        $filter: {
          input: { $ifNull: [\"$reviews\", []] },
          as: \"id\",
          cond: { $ne: [\"$$id\", reviewId] },
        },
      };

  const set = { reviews };
  if (counted) {
    // Never below zero, even if the totals were already wrong.
    set.ratingSum = {
      $max: [0, { $add: [{ $ifNull: [\"$ratingSum\", 0] }, sign * stars] }],
    };
    set.ratingCount = {
      $max: [0, { $add: [{ $ifNull: [\"$ratingCount\", 0] }, sign] }],
    };
  }
  return counted ? [{ $set: set }, averageStage] : [{ $set: set }];
}

/** A review was written: add it to the list and the totals, in one update. */
function addReview(ListingModel, listingId, review) {
  return ListingModel.updateOne(
    { _id: listingId },
    ratingUpdate({ add: { reviewId: review._id, stars: review.rating } }),
    { updatePipeline: true },
  );
}

/** A review was deleted: take it out of the list and the totals, in one update. */
function removeReview(ListingModel, listingId, review) {
  return ListingModel.updateOne(
    { _id: listingId },
    ratingUpdate({ remove: { reviewId: review._id, stars: review.rating } }),
    { updatePipeline: true },
  );
}

/** A review's rating was edited: move the totals by the difference, in one update. */
function changeRating(ListingModel, listingId, { from, to }) {
  return ListingModel.updateOne(
    { _id: listingId },
    ratingUpdate({ change: { from, to } }),
    { updatePipeline: true },
  );
}

/**
 * Set a listing's totals from its reviews (repair, and migration 009). The
 * reviews are the truth; use it when the totals are suspected wrong, not on
 * every write.
 * @returns {{ ratingSum: number, ratingCount: number, ratingAvg: number }}
 */
function totalsOf(reviews) {
  const ratings = (Array.isArray(reviews) ? reviews : [])
    .map((r) => (r ? r.rating : undefined))
    .filter(isCountable);
  const ratingSum = ratings.reduce((total, r) => total + r, 0);
  const ratingCount = ratings.length;
  return {
    ratingSum,
    ratingCount,
    ratingAvg: ratingCount > 0 ? ratingSum / ratingCount : 0,
  };
}

async function recomputeRatings({ ListingModel, ReviewModel }, listingId) {
  const listing = await ListingModel.findById(listingId)
    .select(\"reviews\")
    .lean();
  if (!listing) return null;
  const reviews = await ReviewModel.find({
    _id: { $in: listing.reviews || [] },
    status: { $ne: \"hidden\" }, // a hidden review is not in the totals (P14-T04)
  })
    .select(\"rating\")
    .lean();
  const totals = totalsOf(reviews);
  await ListingModel.updateOne({ _id: listingId }, { $set: totals });
  return totals;
}

module.exports = {
  RATING,
  isCountable,
  ratingUpdate,
  addReview,
  removeReview,
  changeRating,
  totalsOf,
  recomputeRatings,
};

// Host Readiness Checklist (P04-T05). One pure function decides whether a
// listing may go public; the checklist the host sees AND the publish action
// both call it, so the page can never say \"ready\" while the server refuses.
//
// It checks that things are PRESENT, not that they are good: a 200-character
// description of nonsense passes. The score is \"how many of these items are
// done\", not a quality rating.
const {
  CANCELLATION_POLICY_VALUES,
  READINESS,
} = require(\"../config/constants\");

const TIME = /^([01]\\d|2[0-3]):[0-5]\\d$/;

const text = (value) => (typeof value === \"string\" ? value.trim() : \"\");
const isInt = (value) => Number.isInteger(value);

function hasPoint(listing) {
  const c = listing.geometry && listing.geometry.coordinates;
  return (
    Array.isArray(c) && c.length >= 2 && c.slice(0, 2).every(Number.isFinite)
  );
}

const plural = (n, word) => `${n} ${word}${n === 1 ? \"\" : \"s\"}`;

/**
 * @param {object} listing  a Listing document or a plain object
 * @param {object} [options]
 * @param {number} [options.minPhotos]            default 5
 * @param {number} [options.minDescriptionChars]  default 200
 * @returns {{
 *   score: number,
 *   canPublish: boolean,
 *   checks: Array<{ key: string, label: string, passed: boolean, hint: string, step: number }>
 * }}
 *   `step` is the wizard step where the host fixes the item; `hint` is empty
 *   once the check has passed.
 */
function evaluateReadiness(listing, options = {}) {
  const minPhotos = options.minPhotos ?? READINESS.minPhotos;
  const minChars = options.minDescriptionChars ?? READINESS.minDescriptionChars;
  const l = listing || {};

  const photoCount = (Array.isArray(l.images) ? l.images : []).filter(
    (image) => image && image.url,
  ).length;
  const descriptionLength = text(l.description).length;
  const address = l.address || {};
  const capacity = l.capacity || {};
  const nightly = l.pricing && l.pricing.nightlyMinor;

  const addressPresent = Boolean(
    text(address.line1) && text(address.city) && text(address.country),
  );
  const addressConfirmed =
    addressPresent && hasPoint(l) && l.needsReview !== true;
  const capacitySet =
    isInt(capacity.guests) &&
    capacity.guests >= 1 &&
    isInt(capacity.beds) &&
    capacity.beds >= 1;
  const priceSet = isInt(nightly) && nightly > 0;
  const rulesDone = text(l.houseRules).length > 0 || l.noSpecialRules === true;
  const timesSet =
    TIME.test(text(l.checkInTime)) && TIME.test(text(l.checkOutTime));
  const policyChosen = CANCELLATION_POLICY_VALUES.includes(
    l.cancellationPolicy,
  );

  const checks = [
    {
      key: \"photos\",
      label: `At least ${plural(minPhotos, \"photo\")}`,
      passed: photoCount >= minPhotos,
      hint: `You have ${photoCount}. Add ${plural(Math.max(0, minPhotos - photoCount), \"more photo\")}.`,
      step: 4,
    },
    {
      key: \"description\",
      label: `A description of at least ${minChars} characters`,
      passed: descriptionLength >= minChars,
      hint: `You have written ${descriptionLength} of ${minChars} characters.`,
      step: 1,
    },
    {
      key: \"address\",
      label: \"Address entered and found on the map\",
      passed: addressConfirmed,
      hint: \"Enter the street, city and country so we can find the place on the map.\",
      step: 2,
    },
    {
      key: \"capacity\",
      label: \"Guests and beds set\",
      passed: capacitySet,
      hint: \"Say how many guests the place sleeps and how many beds it has.\",
      step: 3,
    },
    {
      key: \"price\",
      label: \"Nightly price set\",
      passed: priceSet,
      hint: \"Set the price for one night.\",
      step: 5,
    },
    {
      key: \"rules\",
      label: 'House rules written, or \"no special rules\" confirmed',
      passed: rulesDone,
      hint: 'Write your house rules, or tick \"I have no special house rules\".',
      step: 5,
    },
    {
      key: \"times\",
      label: \"Check-in and check-out times\",
      passed: timesSet,
      hint: \"Give both times, like 14:00 and 11:00.\",
      step: 5,
    },
    {
      key: \"cancellation\",
      label: \"Cancellation policy chosen\",
      passed: policyChosen,
      hint: \"Choose how guests can cancel.\",
      step: 5,
    },
  ].map((check) => ({ ...check, hint: check.passed ? \"\" : check.hint }));

  const passedCount = checks.filter((check) => check.passed).length;
  return {
    score: Math.round((passedCount / checks.length) * 100),
    canPublish: passedCount === checks.length,
    checks,
  };
}

module.exports = { evaluateReadiness };

// Refund calculation (P09-T03). Pure: no database, no clock (`now` is passed
// in). Money is integer paise. The rules are data in src/config/cancellation.js.
//
// A refund is CALCULATED AND RECORDED only; no money moves (payments are
// simulated until P16).
const { POLICIES, RULE_TEXT, HOUR_MS } = require(\"../config/cancellation\");
const {
  DEFAULT_TIMEZONE,
  parseClockTime,
  zonedInstant,
} = require(\"../utils/dates\");

/**
 * The instant check-in starts: the check-in date at the listing's check-in
 * time on the listing's own clock (\"00:00\" when the snapshot has no valid time).
 */
function checkInInstant(reservation) {
  const snap = reservation.listingSnapshot || {};
  const minutes = parseClockTime(snap.checkInTime);
  return zonedInstant(
    reservation.checkIn,
    minutes === null ? 0 : minutes,
    snap.timezone || DEFAULT_TIMEZONE,
  );
}

function bookedAtOf(reservation) {
  if (reservation.createdAt instanceof Date) return reservation.createdAt;
  const first = Array.isArray(reservation.statusHistory)
    ? reservation.statusHistory[0]
    : null;
  return first && first.at instanceof Date ? first.at : null;
}

const isMinor = (n) => Number.isSafeInteger(n) && n >= 0;

// total, one night's average price, and the price of the other nights.
function amountsOf(reservation) {
  const price = reservation.pricingSnapshot || {};
  const total = price.totalMinor;
  if (!isMinor(total))
    throw new TypeError(\"The booking has no total to refund from.\");
  const nights =
    Number.isInteger(reservation.nights) && reservation.nights > 0
      ? reservation.nights
      : 1;
  const subtotal = isMinor(price.subtotalMinor) ? price.subtotalMinor : total;
  const firstNight = Math.min(
    isMinor(price.avgPerNightMinor)
      ? price.avgPerNightMinor
      : Math.round(subtotal / nights),
    subtotal,
  );
  return { total, firstNight, rest: subtotal - firstNight };
}

function ruleHolds(rule, { now, checkInAt, bookedAt }) {
  const when = rule.when;
  if (when.freeUntilHoursBeforeCheckIn !== undefined) {
    return (
      now.getTime() <=
      checkInAt.getTime() - when.freeUntilHoursBeforeCheckIn * HOUR_MS
    );
  }
  if (when.withinHoursOfBooking !== undefined) {
    if (!bookedAt) return false;
    return (
      now.getTime() - bookedAt.getTime() <=
        when.withinHoursOfBooking * HOUR_MS &&
      checkInAt.getTime() - now.getTime() >=
        when.minHoursBeforeCheckIn * HOUR_MS
    );
  }
  return when.before === \"checkIn\";
}

function retainedBy(keep, { total, firstNight, rest }) {
  switch (keep.kind) {
    case \"nothing\":
      return 0;
    case \"everything\":
      return total;
    case \"firstNight\":
      return firstNight + Math.ceil(rest * keep.restShare);
    case \"refundShareOfTotal\":
      return total - Math.floor(total * keep.share);
    default:
      throw new TypeError(`Unknown refund rule kind: ${keep.kind}`);
  }
}

// Until when a full refund still holds under the rule that applies (or null).
function fullRefundUntil(rule, { checkInAt, bookedAt }) {
  const when = rule.when;
  if (rule.keep.kind !== \"nothing\") return null;
  const dates = [];
  if (when.freeUntilHoursBeforeCheckIn !== undefined) {
    dates.push(
      checkInAt.getTime() - when.freeUntilHoursBeforeCheckIn * HOUR_MS,
    );
  }
  if (when.withinHoursOfBooking !== undefined && bookedAt) {
    dates.push(bookedAt.getTime() + when.withinHoursOfBooking * HOUR_MS);
    dates.push(checkInAt.getTime() - when.minHoursBeforeCheckIn * HOUR_MS);
  }
  if (!dates.length) return null;
  const earliest = new Date();
  earliest.setTime(Math.min(...dates));
  return earliest;
}

function result(policy, rule, total, retained, extra = {}) {
  const retainedMinor = Math.min(Math.max(retained, 0), total);
  return {
    policy: policy || null,
    rule,
    ruleText: RULE_TEXT[rule],
    totalMinor: total,
    refundMinor: total - retainedMinor,
    retainedMinor,
    fullRefundUntil: null,
    ...extra,
  };
}

/**
 * What a GUEST gets back if they cancel at `now`, under the listing's policy.
 * @param {string} policy \"flexible\" | \"moderate\" | \"strict\" (anything else: no refund promised)
 * @param {object} reservation checkIn (date-only Date), nights, createdAt,
 *   pricingSnapshot {totalMinor, subtotalMinor, avgPerNightMinor},
 *   listingSnapshot {timezone, checkInTime}
 * @param {Date} now
 * @returns {{ policy, rule, ruleText, totalMinor, refundMinor, retainedMinor, fullRefundUntil: Date|null, checkInAt: Date }}
 */
function refundFor(policy, reservation, now) {
  if (!(now instanceof Date) || !Number.isFinite(now.getTime())) {
    throw new TypeError(\"now must be a valid Date\");
  }
  const amounts = amountsOf(reservation);
  const checkInAt = checkInInstant(reservation);
  const base = { checkInAt };
  const rules = Object.hasOwn(POLICIES, policy) ? POLICIES[policy] : null;
  if (!rules)
    return result(policy, \"no_policy\", amounts.total, amounts.total, base);
  if (now.getTime() >= checkInAt.getTime()) {
    return result(policy, \"stay_started\", amounts.total, amounts.total, base);
  }
  const context = { now, checkInAt, bookedAt: bookedAtOf(reservation) };
  for (const rule of rules) {
    if (!ruleHolds(rule, context)) continue;
    return result(
      policy,
      rule.id,
      amounts.total,
      retainedBy(rule.keep, amounts),
      {
        ...base,
        fullRefundUntil: fullRefundUntil(rule, context),
      },
    );
  }
  // Every policy ends with a rule that always holds; reaching this is a data error.
  throw new Error(`Policy ${policy} has no rule for this cancellation.`);
}

/**
 * The refund for one cancellation, whoever cancels:
 * - the host: always everything back;
 * - the guest, request not yet answered (pending): everything back;
 * - the guest, confirmed: refundFor(policy of the booking).
 */
function refundForCancellation({ reservation, actor, now }) {
  const { total } = amountsOf(reservation);
  const checkInAt = checkInInstant(reservation);
  const snap = reservation.listingSnapshot || {};
  const policy = snap.cancellationPolicy || null;
  if (actor === \"host\")
    return result(policy, \"host_cancelled\", total, 0, { checkInAt });
  if (actor !== \"guest\") throw new TypeError(\"actor must be guest or host\");
  if (reservation.status === \"pending\")
    return result(policy, \"request_withdrawn\", total, 0, { checkInAt });
  return refundFor(policy, reservation, now);
}

module.exports = { refundFor, refundForCancellation, checkInInstant };

// The moderators' reports queue (P14-T04): list, open one, close it as
// resolved or dismissed. The routes (src/routes/admin.js) call closeReport
// inside auditedMutation, which writes the audit row; nothing here writes one.
//
// - A report is only ever closed, never deleted. Closing is a compare-and-set
//   on `status: \"open\"`, so two admins cannot both close it.
// - \"Resolved\" means action was taken (or is no longer needed), \"dismissed\"
//   means nothing needed action. Both need a short note; the reporter reads the
//   outcome on their \"My reports\" page, never the note or who closed it.
// - Closing can also close the other OPEN reports about the same target in one
//   step, so one decision does not need five clicks.
// - Reports about messages cannot be opened yet: messaging (P11) does not
//   exist. When it does, a message report may show only the reported
//   conversation, never the inbox (docs/tasks/P14-T04.md).
const mongoose = require(\"mongoose\");
const { toPageNumber } = require(\"./audit\");
const {
  REPORT_KINDS,
  REPORT_REASONS,
  REPORT_STATUSES,
} = require(\"../config/reports\");

const PAGE_SIZE = 20;
const NOTE_MIN = 5;
const NOTE_MAX = 500;
const STATUS_FILTERS = Object.freeze([\"open\", \"resolved\", \"dismissed\"]);
const KIND_VALUES = REPORT_KINDS.map((k) => k.value);
const kindLabel = Object.fromEntries(
  REPORT_KINDS.map((k) => [k.value, k.label]),
);
const reasonLabel = Object.fromEntries(
  REPORT_REASONS.map((r) => [r.value, r.label]),
);
const OUTCOMES = Object.freeze({ resolve: \"resolved\", dismiss: \"dismissed\" });

class ReportAdminError extends Error {
  /** @param {string} message user-safe text, shown to the admin */
  constructor(message) {
    super(message);
    this.name = \"ReportAdminError\";
  }
}

const isId = (value) =>
  typeof value === \"string\" && mongoose.isValidObjectId(value);

function models(over = {}) {
  return {
    ReportModel: over.ReportModel || require(\"../models/report\"),
    ReviewModel: over.ReviewModel || require(\"../models/review\"),
    ListingModel: over.ListingModel || require(\"../models/listing\"),
    UserModel: over.UserModel || require(\"../models/user\"),
  };
}

function cleanNote(value) {
  const note = typeof value === \"string\" ? value.trim() : \"\";
  if (note.length < NOTE_MIN) {
    throw new ReportAdminError(
      `Write a short note (at least ${NOTE_MIN} characters). It is written to the audit log.`,
    );
  }
  if (note.length > NOTE_MAX)
    throw new ReportAdminError(
      `The note must be ${NOTE_MAX} characters or fewer.`,
    );
  return note;
}

function toRow(report, openOnTarget) {
  return {
    id: String(report._id),
    kind: report.targetKind,
    kindLabel: kindLabel[report.targetKind] || \"Item\",
    target: report.targetLabel || \"Removed item\",
    reasonLabel: reasonLabel[report.reason] || \"Other\",
    reporter:
      report.reporter && report.reporter.username
        ? report.reporter.username
        : \"(removed account)\",
    status: report.status,
    createdAt: report.createdAt,
    resolvedAt: report.resolvedAt || null,
    openOnTarget: openOnTarget || 0,
  };
}

/**
 * One page of the queue. Open reports are oldest first (nobody waits longest
 * for nothing); closed ones are newest first.
 * @returns {{ rows: object[], page: number, totalPages: number, total: number, status: string, kind: string, counts: object }}
 */
async function listReports({ status, kind, page, ...over } = {}) {
  const { ReportModel } = models(over);
  const which =
    typeof status === \"string\" && STATUS_FILTERS.includes(status)
      ? status
      : \"open\";
  const filter = { status: which };
  const kindWanted =
    typeof kind === \"string\" && KIND_VALUES.includes(kind) ? kind : \"\";
  if (kindWanted) filter.targetKind = kindWanted;

  const [total, openTotal] = await Promise.all([
    ReportModel.countDocuments(filter),
    ReportModel.countDocuments({ status: \"open\" }),
  ]);
  const totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE));
  const current = Math.min(toPageNumber(page), totalPages);
  const rows = await ReportModel.find(filter)
    .sort(
      which === \"open\" ? { createdAt: 1, _id: 1 } : { resolvedAt: -1, _id: -1 },
    )
    .skip((current - 1) * PAGE_SIZE)
    .limit(PAGE_SIZE)
    .populate(\"reporter\", \"username\")
    .lean();

  // How many open reports each row's target has (one grouped query).
  const open = new Map();
  if (rows.length > 0) {
    const grouped = await ReportModel.aggregate([
      {
        $match: {
          status: \"open\",
          targetId: { $in: rows.map((r) => r.targetId) },
        },
      },
      {
        $group: {
          _id: { kind: \"$targetKind\", id: \"$targetId\" },
          count: { $sum: 1 },
        },
      },
    ]);
    for (const g of grouped) open.set(`${g._id.kind}|${g._id.id}`, g.count);
  }
  return {
    rows: rows.map((r) => toRow(r, open.get(`${r.targetKind}|${r.targetId}`))),
    page: current,
    totalPages,
    total,
    status: which,
    kind: kindWanted,
    openTotal,
  };
}

/** What the moderator needs to see about the reported thing. */
async function describeReported(
  report,
  { ListingModel, ReviewModel, UserModel },
) {
  const id = report.targetId;
  if (report.targetKind === \"listing\") {
    const listing = await ListingModel.findById(id)
      .select(\"title status deletedAt owner\")
      .lean();
    if (!listing) return { kind: \"listing\", gone: true };
    return {
      kind: \"listing\",
      title: listing.title,
      status: listing.deletedAt ? \"deleted\" : listing.status,
      url: `/admin/listings/${id}`,
    };
  }
  if (report.targetKind === \"review\") {
    const review = await ReviewModel.findById(id)
      .populate(\"author\", \"username\")
      .lean();
    if (!review) return { kind: \"review\", gone: true };
    const listing = review.listing
      ? await ListingModel.findById(review.listing).select(\"title\").lean()
      : await ListingModel.findOne({ reviews: review._id })
          .select(\"title\")
          .lean();
    return {
      kind: \"review\",
      id: String(review._id),
      rating: review.rating,
      comment: review.comment || \"\",
      author:
        review.author && review.author.username
          ? review.author.username
          : \"(removed account)\",
      authorId:
        review.author && review.author._id ? String(review.author._id) : null,
      listingTitle: listing ? listing.title : \"(a listing that is gone)\",
      hidden: review.status === \"hidden\",
      hiddenReason:
        review.moderation && review.moderation.hiddenReason
          ? review.moderation.hiddenReason
          : \"\",
      createdAt: review.createdAt || null,
    };
  }
  if (report.targetKind === \"user\") {
    const user = await UserModel.findById(id).select(\"username status\").lean();
    if (!user) return { kind: \"user\", gone: true };
    return {
      kind: \"user\",
      username: user.username,
      status: user.status,
      url: `/admin/users/${id}`,
    };
  }
  // A message: messaging does not exist yet, so there is no thread to show.
  return { kind: \"message\", unavailable: true };
}

/** One report with the reported thing and the other reports about it, or null. */
async function getReport(id, over = {}) {
  if (!isId(id)) return null;
  const m = models(over);
  const report = await m.ReportModel.findById(id)
    .populate(\"reporter\", \"username\")
    .populate(\"resolvedBy\", \"username\")
    .lean();
  if (!report) return null;
  const [target, others] = await Promise.all([
    describeReported(report, m),
    m.ReportModel.find({
      targetKind: report.targetKind,
      targetId: report.targetId,
      _id: { $ne: report._id },
    })
      .sort({ createdAt: -1, _id: -1 })
      .limit(20)
      .populate(\"reporter\", \"username\")
      .select(\"reason details status createdAt reporter\")
      .lean(),
  ]);
  return {
    report: {
      ...toRow(report, 0),
      details: report.details || \"\",
      note: report.resolutionNote || \"\",
      resolvedBy:
        report.resolvedBy && report.resolvedBy.username
          ? report.resolvedBy.username
          : null,
      targetKind: report.targetKind,
      targetId: String(report.targetId),
    },
    target,
    others: others.map((o) => ({
      id: String(o._id),
      reasonLabel: reasonLabel[o.reason] || \"Other\",
      details: o.details || \"\",
      status: o.status,
      reporter:
        o.reporter && o.reporter.username
          ? o.reporter.username
          : \"(removed account)\",
      createdAt: o.createdAt,
    })),
    openOthers: others.filter((o) => o.status === \"open\").length,
  };
}

/**
 * Close one open report as resolved or dismissed.
 * @param {{ admin: object, id: string, outcome: \"resolve\"|\"dismiss\", note: string, closeOthers?: boolean, now?: Date }} input
 * @returns {Promise<{ report: object, outcome: string, note: string, closedOthers: number, details: object }>}
 * @throws {ReportAdminError} nothing was changed
 */
async function closeReport({
  admin,
  id,
  outcome,
  note,
  closeOthers = false,
  now = new Date(),
  ...over
}) {
  const status = OUTCOMES[outcome];
  if (!status) throw new ReportAdminError(\"Choose resolve or dismiss.\");
  const text = cleanNote(note);
  if (!isId(id)) throw new ReportAdminError(\"That report does not exist.\");
  const { ReportModel } = models(over);

  const report = await ReportModel.findOneAndUpdate(
    { _id: id, status: \"open\" },
    {
      $set: {
        status,
        resolvedAt: now,
        resolvedBy: admin._id,
        resolutionNote: text,
      },
    },
    { new: true },
  ).lean();
  if (!report) {
    const exists = await ReportModel.exists({ _id: id });
    throw new ReportAdminError(
      exists
        ? \"This report was already closed.\"
        : \"That report does not exist.\",
    );
  }

  let closedOthers = 0;
  if (closeOthers) {
    const result = await ReportModel.updateMany(
      {
        targetKind: report.targetKind,
        targetId: report.targetId,
        status: \"open\",
      },
      {
        $set: {
          status,
          resolvedAt: now,
          resolvedBy: admin._id,
          resolutionNote: text,
        },
      },
    );
    closedOthers = result.modifiedCount || 0;
  }
  return {
    report,
    outcome: status,
    note: text,
    closedOthers,
    details: {
      outcome: status,
      targetKind: report.targetKind,
      targetId: String(report.targetId),
      closedOthers,
    },
  };
}

module.exports = {
  listReports,
  getReport,
  closeReport,
  cleanNote,
  ReportAdminError,
  PAGE_SIZE,
  NOTE_MIN,
  NOTE_MAX,
  STATUS_FILTERS,
  REPORT_STATUSES,
};

// Reports (P12-T04): sending one and listing your own.
//
//   describeTarget(deps, kind, id)   -> { kind, id, owner, label, url }   (404 when it cannot be reported)
//   createReport(deps, { user, kind, id, reason, details, now })
//   listMyReports(deps, userId)      -> rows for the \"Your reports\" page
//
// Rules, all enforced here and never by the form:
// - you can only report what you could open: a published listing, a review on
//   one, an active member; anything else is the same 404 as a missing id;
// - you cannot report your own listing, review or profile (policy report:create);
// - one OPEN report per person and target. The partial unique index on the
//   model decides it, so two simultaneous clicks make one report;
// - at most LIMITS.perDay reports per person in 24 hours, counted in the
//   database (the per-minute limiter on the route is per server process);
// - the reason comes from a fixed list; \"something else\" needs a few words;
// - details are plain text, trimmed, up to 1000 characters (longer is refused, never cut).
// Messages are not reportable until messaging exists (P11).
const mongoose = require(\"mongoose\");
const { can } = require(\"../policies\");
const { isPublic } = require(\"../utils/visibility\");
const {
  REPORT_KINDS,
  REPORTABLE_KINDS,
  REPORT_REASONS,
  REASON_VALUES,
  LIMITS,
} = require(\"../config/reports\");
const {
  AppError,
  ConflictError,
  ForbiddenError,
  NotFoundError,
  ValidationError,
} = require(\"../utils/errors\");

const DAY_MS = 24 * 60 * 60 * 1000;
const OBJECT_ID = /^[0-9a-f]{24}$/i;
const kindLabel = Object.fromEntries(
  REPORT_KINDS.map((k) => [k.value, k.label]),
);
const reasonLabel = Object.fromEntries(
  REPORT_REASONS.map((r) => [r.value, r.label]),
);

const STATUS_TEXT = Object.freeze({
  open: { label: \"Received\", note: \"We have your report and will look at it.\" },
  resolved: {
    label: \"Looked at\",
    note: \"We looked into this and took action where it was needed.\",
  },
  dismissed: {
    label: \"Closed\",
    note: \"We looked into this and found nothing that needs action.\",
  },
});

const label = (text, max = 120) =>
  String(text || \"\")
    .replace(/\\s+/g, \" \")
    .trim()
    .slice(0, max);

/** Reason and details from a form. Returns { reason, details }; throws ValidationError. */
function parseReportInput({ reason, details }) {
  if (typeof reason !== \"string\" || !REASON_VALUES.includes(reason)) {
    throw new ValidationError(\"Choose a reason for your report.\");
  }
  if (
    details !== undefined &&
    details !== null &&
    typeof details !== \"string\"
  ) {
    throw new ValidationError(\"The details must be text.\");
  }
  const text = (details || \"\").trim();
  if (text.length > LIMITS.detailsMax) {
    throw new ValidationError(
      `The details can be at most ${LIMITS.detailsMax} characters.`,
    );
  }
  if (reason === \"other\" && text.length < LIMITS.otherMin) {
    throw new ValidationError(
      `Please say a little more (at least ${LIMITS.otherMin} characters) when the reason is \"something else\".`,
    );
  }
  return { reason, details: text };
}

/**
 * What a report is about, or a 404. `owner` is who made it; the policy uses it
 * to refuse reports about your own things.
 */
async function describeTarget(
  {
    ListingModel = require(\"../models/listing\"),
    ReviewModel = require(\"../models/review\"),
    UserModel = require(\"../models/user\"),
  } = {},
  kind,
  id,
) {
  const missing = () =>
    new NotFoundError(
      \"That cannot be reported: it does not exist or is no longer visible.\",
    );
  if (typeof kind !== \"string\" || !REPORT_KINDS.some((k) => k.value === kind)) {
    throw new ValidationError(\"Choose what you want to report.\");
  }
  if (!REPORTABLE_KINDS.includes(kind)) {
    throw new ValidationError(\"Messages cannot be reported yet.\");
  }
  if (typeof id !== \"string\" || !OBJECT_ID.test(id)) throw missing();

  if (kind === \"listing\") {
    const listing = await ListingModel.findById(id)
      .select(\"title owner status deletedAt\")
      .lean();
    if (!isPublic(listing)) throw missing();
    return {
      kind,
      id,
      owner: listing.owner || null,
      label: label(listing.title),
      url: `/listings/${id}`,
    };
  }
  if (kind === \"review\") {
    const review = await ReviewModel.findById(id).select(\"author listing\").lean();
    if (!review) throw missing();
    // A review is shown only on its listing, so it is reportable only while that
    // listing is public. The review knows its listing (since reviews v2); only a
    // review without one is looked up by the listing's own list of reviews, which
    // has no index (P18-T02).
    const listing = review.listing
      ? await ListingModel.findById(review.listing).select(\"title status deletedAt\").lean()
      : await ListingModel.findOne({ reviews: review._id }).select(\"title status deletedAt\").lean();
    if (!isPublic(listing)) throw missing();
    return {
      kind,
      id,
      owner: review.author || null,
      label: label(`A review of ${listing.title}`),
      url: `/listings/${listing._id}#reviews-heading`,
    };
  }
  const member = await UserModel.findOne({ _id: id, status: \"active\" })
    .select(\"username displayName\")
    .lean();
  if (!member) throw missing();
  return {
    kind,
    id,
    owner: member._id,
    label: label(member.displayName || member.username),
    url: `/users/${id}`,
  };
}

/**
 * @returns {Promise<{ report: object, created: true }>}
 * Errors: 400 bad input, 403 your own / inactive account, 404 not reportable,
 * 409 `already_reported`, 429 `report_limit`.
 */
async function createReport(
  { ReportModel = require(\"../models/report\"), ...targets } = {},
  { user, kind, id, reason, details, now = new Date() },
) {
  const input = parseReportInput({ reason, details });
  const target = await describeTarget(targets, kind, id);
  if (!can(\"report:create\", user, { owner: target.owner })) {
    const own =
      user && target.owner && String(target.owner) === String(user._id);
    throw new ForbiddenError(
      own
        ? `You cannot report your own ${kindLabel[kind].toLowerCase()}.`
        : \"Your account cannot send reports.\",
    );
  }

  const since = new Date();
  since.setTime(now.getTime() - DAY_MS);
  if (
    (await ReportModel.countDocuments({
      reporter: user._id,
      createdAt: { $gte: since },
    })) >= LIMITS.perDay
  ) {
    throw new AppError(
      429,
      \"You have sent a lot of reports today. Please try again tomorrow.\",
      { code: \"report_limit\" },
    );
  }

  const duplicate = () =>
    new ConflictError(
      \"You already have an open report about this. We will look at it; there is no need to send it again.\",
      {
        code: \"already_reported\",
      },
    );
  const same = {
    reporter: user._id,
    targetKind: kind,
    targetId: id,
    status: \"open\",
  };
  if (await ReportModel.exists(same)) throw duplicate();
  try {
    const report = await ReportModel.create({
      reporter: user._id,
      targetKind: kind,
      targetId: id,
      targetOwner: target.owner,
      targetLabel: target.label,
      reason: input.reason,
      details: input.details || undefined,
    });
    return { report, created: true };
  } catch (err) {
    if (err && err.code === 11000) throw duplicate(); // two clicks at once: the index decided
    throw err;
  }
}

/** The reporter's own reports, newest first (what the \"Your reports\" page prints). */
async function listMyReports(
  { ReportModel = require(\"../models/report\") } = {},
  userId,
  { limit = 50 } = {},
) {
  if (!mongoose.isValidObjectId(String(userId))) return [];
  const rows = await ReportModel.find({ reporter: userId })
    .sort({ createdAt: -1, _id: -1 })
    .limit(limit)
    .select(\"targetKind targetId targetLabel reason status createdAt\")
    .lean();
  return rows.map((row) => {
    const status = STATUS_TEXT[row.status] || STATUS_TEXT.open;
    return {
      id: String(row._id),
      kind: row.targetKind,
      kindLabel: kindLabel[row.targetKind] || \"Item\",
      target: row.targetLabel || \"Removed item\",
      reasonLabel: reasonLabel[row.reason] || \"Other\",
      status: row.status,
      statusLabel: status.label,
      statusNote: status.note,
      createdAt: row.createdAt,
    };
  });
}

module.exports = {
  createReport,
  describeTarget,
  listMyReports,
  parseReportInput,
  STATUS_TEXT,
};

// Reservation lookup for admins (P14-T05). READ-ONLY: nothing here changes a
// reservation (an admin who must act on a booking does it through the
// listing or account tools, which are audited). Search text is matched as
// plain text, never as a pattern.
const mongoose = require(\"mongoose\");
const Reservation = require(\"../models/reservation\");
const User = require(\"../models/user\");
const Listing = require(\"../models/listing\");
const { STATUSES } = require(\"./stateMachine\");
const { toPageNumber } = require(\"./audit\");

const PAGE_SIZE = 20;
const QUERY_MAX = 100;
// How many guests / listings one text search may widen to. Past this the page
// says so and asks for a narrower search instead of building a huge $in.
const LOOKUP_CAP = 50;

const escapeRegex = (text) => text.replace(/[.*+?^${}()|[\\]\\\\]/g, \"\\\\$&\");
const isId = (value) => typeof value === \"string\" && mongoose.isValidObjectId(value) && /^[a-f0-9]{24}$/i.test(value);

/**
 * Reservations matching `q` and/or one status, newest first.
 *  - `q` that is a 24-character id: that reservation, or every reservation of
 *    that guest, host or listing;
 *  - any other `q`: guests by username / email / display name, and listings by
 *    title (case-insensitive, plain text).
 * @returns {{rows: object[], page: number, totalPages: number, total: number, q: string, status: string, capped: boolean}}
 */
async function searchReservations({ q, status, page } = {}) {
  const text = typeof q === \"string\" ? q.trim().slice(0, QUERY_MAX) : \"\";
  const filter = {};
  let capped = false;

  if (text) {
    if (isId(text)) {
      const id = new mongoose.Types.ObjectId(text);
      filter.$or = [{ _id: id }, { guest: id }, { host: id }, { listing: id }];
    } else {
      const rx = new RegExp(escapeRegex(text), \"i\");
      const [guests, listings] = await Promise.all([
        User.find({ $or: [{ username: rx }, { email: rx }, { displayName: rx }] })
          .select(\"_id\")
          .limit(LOOKUP_CAP + 1)
          .lean(),
        Listing.find({ title: rx }).select(\"_id\").limit(LOOKUP_CAP + 1).lean(),
      ]);
      capped = guests.length > LOOKUP_CAP || listings.length > LOOKUP_CAP;
      filter.$or = [
        { guest: { $in: guests.slice(0, LOOKUP_CAP).map((u) => u._id) } },
        { listing: { $in: listings.slice(0, LOOKUP_CAP).map((l) => l._id) } },
      ];
    }
  }
  const wanted = typeof status === \"string\" && STATUSES.includes(status) ? status : \"\";
  if (wanted) filter.status = wanted;

  const total = await Reservation.countDocuments(filter);
  const totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE));
  const current = Math.min(toPageNumber(page), totalPages);
  const rows = await Reservation.find(filter)
    .select(\"listing guest host checkIn checkOut nights guests status pricingSnapshot.totalMinor pricingSnapshot.currency listingSnapshot.title createdAt\")
    .sort({ createdAt: -1, _id: -1 })
    .skip((current - 1) * PAGE_SIZE)
    .limit(PAGE_SIZE)
    .populate(\"guest\", \"username\")
    .populate(\"host\", \"username\")
    .populate(\"listing\", \"title\")
    .lean();
  return { rows, page: current, totalPages, total, q: text, status: wanted, capped };
}

/** One reservation with its people and listing, or null for a malformed or unknown id. */
async function getReservation(id) {
  if (!isId(id)) return null;
  return Reservation.findById(id)
    .populate(\"guest\", \"username displayName email status\")
    .populate(\"host\", \"username displayName email status\")
    .populate(\"listing\", \"title status deletedAt\")
    .lean();
}

module.exports = { searchReservations, getReservation, PAGE_SIZE, LOOKUP_CAP };

// Reservations (P07-T05): creating a booking and changing its status.
//
//   create({ guest, listing, in, out, guests, expectedTotalMinor, idempotencyKey })
//   transition(reservationId, to, { actor, by, reason, now }?)
//
// create() order, which is what keeps the ledger and the reservations
// consistent (ADR-004):
//   1. validate input; a repeated idempotency key returns the original
//   2. load the listing; booking rules (bookingRules.js); quote; compare the price the guest saw
//   3. hold every night in the ledger (the database refuses a second owner)
//   4. check the listing is still public (a host may unpublish meanwhile)
//   5. insert the reservation; if that fails, release the nights
// So a reservation never exists without its nights; a night without a live
// reservation can only remain if step 5's cleanup itself fails (the sweeper,
// P07-T07, removes such orphans).
//
// transition() is compare-and-set: the update only matches while the status is
// still the one that was read, so \"host accepts while guest cancels\" has one
// winner and the other gets a 409.
const { isActiveUser, sameId, idOf } = require(\"../policies/shared\");
const {
  DEFAULT_TIMEZONE,
  tryParseDateOnly,
  isDateOnly,
  todayIn,
  eachNight,
  formatDateOnly,
  instantAfter,
} = require(\"../utils/dates\");
const {
  ValidationError,
  ForbiddenError,
  NotFoundError,
  ConflictError,
  PriceChangedError,
} = require(\"../utils/errors\");
const { isPublic } = require(\"../utils/visibility\");
const { bookingProblems } = require(\"./bookingRules\");
const { assertTransition, releasesNights } = require(\"./stateMachine\");

const PENDING_HOLD_MS = 24 * 60 * 60 * 1000;
const KEY_PATTERN = /^[A-Za-z0-9_-]{8,64}$/;

const isDuplicateKey = (err) =>
  Boolean(err) &&
  (err.code === 11000 ||
    [].concat(err.writeErrors || []).some((e) => e && e.code === 11000));

function toDate(value, label) {
  if (isDateOnly(value)) return value;
  const date = typeof value === \"string\" ? tryParseDateOnly(value) : null;
  if (!date) {
    throw new ValidationError(`${label} must be a valid date in YYYY-MM-DD format.`);
  }
  return date;
}

function parseGuests(value) {
  const n = typeof value === \"string\" && /^\\d{1,3}$/.test(value) ? Number(value) : value;
  if (!Number.isInteger(n) || n < 1) {
    throw new ValidationError(\"Guests must be a whole number, 1 or more.\");
  }
  return n;
}

function parseExpected(value) {
  if (value === undefined || value === null || value === \"\") return null;
  const n = typeof value === \"string\" && /^\\d{1,15}$/.test(value) ? Number(value) : value;
  if (!Number.isSafeInteger(n) || n < 0) {
    throw new ValidationError(\"The expected total must be a whole number of paise.\");
  }
  return n;
}

function parseKey(value) {
  if (typeof value !== \"string\" || !KEY_PATTERN.test(value)) {
    throw new ValidationError(
      \"A booking needs an idempotency key of 8 to 64 letters, digits, - or _.\",
    );
  }
  return value;
}

const lineDate = (d) => formatDateOnly(d);

/**
 * @param {object} [deps] replaceable in unit tests
 */
// Which notification (P11-T04) follows each move; see notificationEvents.js.
const TRANSITION_EVENTS = Object.freeze({
  confirmed: \"reservation.accepted\",
  declined: \"reservation.declined\",
  expired: \"reservation.expired\",
  cancelled_by_guest: \"reservation.cancelled\",
  cancelled_by_host: \"reservation.cancelled\",
  completed: \"review.available\",
});

function createReservationService({
  ReservationModel = require(\"../models/reservation\"),
  ListingModel = require(\"../models/listing\"),
  ledgerService = require(\"./ledger\"),
  pricing = require(\"./pricing\"),
  newId = () => new (require(\"mongoose\").Types.ObjectId)(),
  // Tells the people involved (P11-T04): `{ dispatch(event, { reservation }) }`.
  // None by default, so a service built in a test sends nothing; the exported
  // instance at the bottom of this file gets the real one.
  notifier = null,
  replayRetries = 5,
  replayDelayMs = 40,
  sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms)),
} = {}) {
  // Never throws and never changes the result: a notification is a courtesy.
  async function tell(event, reservation) {
    if (!notifier) return;
    try {
      await notifier.dispatch(event, { reservation });
    } catch {
      // dispatch already swallows its own errors; this keeps a custom notifier harmless too
    }
  }

  const sameRequest = (reservation, wanted) =>
    sameId(reservation.listing, wanted.listing) &&
    lineDate(reservation.checkIn) === lineDate(wanted.checkIn) &&
    lineDate(reservation.checkOut) === lineDate(wanted.checkOut) &&
    reservation.guests === wanted.guests;

  function replayOf(reservation, wanted) {
    if (!sameRequest(reservation, wanted)) {
      throw new ConflictError(
        \"That booking key was already used for a different stay. Please start the booking again.\",
        { code: \"idempotency_key_reused\" },
      );
    }
    return { reservation, created: false };
  }

  // The first request may still be between \"nights held\" and \"reservation
  // saved\" when its twin arrives (double click): wait briefly for it.
  async function waitForOriginal(guestId, key) {
    for (let attempt = 0; attempt < replayRetries; attempt += 1) {
      const found = await ReservationModel.findOne({ guest: guestId, idempotencyKey: key });
      if (found) return found;
      await sleep(replayDelayMs);
    }
    return null;
  }

  async function releaseQuietly(id) {
    try {
      await ledgerService.releaseNights(id);
    } catch {
      // Orphaned rows are removed by the sweeper (P07-T07); the original error
      // is the one the caller must see.
    }
  }

  /**
   * @returns {Promise<{reservation: object, created: boolean}>}
   * @throws ValidationError 400, ForbiddenError 403, NotFoundError 404,
   *   ConflictError 409 (nights_unavailable, idempotency_key_reused),
   *   PriceChangedError 409 (price_changed, carries `.quote`),
   *   QuoteRefusedError 422
   */
  async function create(input, { now = new Date() } = {}) {
    const { guest, listing: listingRef, in: inRaw, out: outRaw } = input || {};
    const key = parseKey(input && input.idempotencyKey);
    if (!isActiveUser(guest)) {
      throw new ForbiddenError(\"Your account cannot make bookings.\");
    }
    const listingId = idOf(listingRef);
    if (!listingId) throw new NotFoundError(\"That place is not available for booking.\");
    const checkIn = toDate(inRaw, \"Check-in\");
    const checkOut = toDate(outRaw, \"Check-out\");
    const guests = parseGuests(input.guests);
    const expectedTotalMinor = parseExpected(input.expectedTotalMinor);
    const wanted = { listing: listingId, checkIn, checkOut, guests };

    const earlier = await ReservationModel.findOne({ guest: guest._id, idempotencyKey: key });
    if (earlier) return replayOf(earlier, wanted);

    const listing = await ListingModel.findById(listingId);
    if (!listing || !isPublic(listing) || !listing.owner) {
      throw new NotFoundError(\"That place is not available for booking.\");
    }
    if (sameId(listing.owner, guest._id)) {
      throw new ForbiddenError(\"You cannot book your own listing.\");
    }

    // Booking rules (P07-T06): one module decides dates, stay length,
    // capacity, advance notice and the same-day cut-off, each with its own
    // message and code. The first problem is the one the guest sees.
    const problems = bookingProblems({ listing, checkIn, checkOut, guests, now });
    if (problems.length) {
      throw new ValidationError(problems[0].message, { code: problems[0].code });
    }

    const quote = pricing.quote({ listing, checkIn, checkOut, guests });
    if (expectedTotalMinor !== null && expectedTotalMinor !== quote.totalMinor) {
      throw new PriceChangedError(quote);
    }

    const instant = Boolean(listing.instantBook);
    const status = instant ? \"confirmed\" : \"pending\";
    const holdExpiresAt = instant ? null : instantAfter(now, PENDING_HOLD_MS);
    const _id = newId();

    try {
      await ledgerService.reserveNights(
        listing._id,
        eachNight(checkIn, checkOut),
        { kind: \"reservation\", id: _id },
        holdExpiresAt,
        { now },
      );
    } catch (err) {
      if (err instanceof ConflictError) {
        const original = await waitForOriginal(guest._id, key);
        if (original) return replayOf(original, wanted);
      }
      throw err;
    }

    // The host may have unpublished or deleted the listing meanwhile.
    let stillPublic = false;
    try {
      stillPublic = isPublic(await ListingModel.findById(listing._id).select(\"status deletedAt\"));
    } catch (err) {
      await releaseQuietly(_id);
      throw err;
    }
    if (!stillPublic) {
      await releaseQuietly(_id);
      throw new NotFoundError(\"That place is not available for booking.\");
    }

    const cover =
      (Array.isArray(listing.images) && listing.images[0] && listing.images[0].url) ||
      (listing.image && listing.image.url) ||
      undefined;
    try {
      const reservation = await ReservationModel.create({
        _id,
        listing: listing._id,
        guest: guest._id,
        host: listing.owner,
        checkIn,
        checkOut,
        nights: quote.nights,
        guests,
        status,
        ...(holdExpiresAt ? { holdExpiresAt } : {}),
        statusHistory: [
          { from: null, to: status, at: now, actor: \"guest\", by: guest._id, note: instant ? \"instant booking\" : \"request sent\" },
        ],
        pricingSnapshot: quote,
        listingSnapshot: {
          title: listing.title,
          city: listing.address && listing.address.city,
          coverUrl: cover,
          houseRules: listing.houseRules,
          noSpecialRules: Boolean(listing.noSpecialRules),
          cancellationPolicy: listing.cancellationPolicy,
          checkInTime: listing.checkInTime,
          checkOutTime: listing.checkOutTime,
          timezone: listing.timezone || DEFAULT_TIMEZONE,
          instantBook: instant,
        },
        idempotencyKey: key,
      });
      await tell(instant ? \"reservation.booked\" : \"reservation.requested\", reservation);
      return { reservation, created: true };
    } catch (err) {
      await releaseQuietly(_id);
      if (isDuplicateKey(err)) {
        // A twin request saved first: its reservation (and nights) stand.
        const original = await ReservationModel.findOne({ guest: guest._id, idempotencyKey: key });
        if (original) return replayOf(original, wanted);
      }
      throw err;
    }
  }

  // Extra conditions that make a transition valid only at the right time, and
  // the error when the update did not match although the status did.
  function guardFor(to, current, now) {
    if (to === \"confirmed\") {
      return {
        filter: { holdExpiresAt: { $gt: now } },
        onMiss: () =>
          new ConflictError(\"This request has expired and can no longer be accepted.\", { code: \"hold_expired\" }),
      };
    }
    if (to === \"expired\") {
      return {
        filter: { holdExpiresAt: { $lte: now } },
        onMiss: () => new ConflictError(\"This request has not expired yet.\", { code: \"hold_active\" }),
      };
    }
    if (to === \"completed\") {
      const tz = (current.listingSnapshot && current.listingSnapshot.timezone) || DEFAULT_TIMEZONE;
      return {
        filter: { checkOut: { $lte: todayIn(tz, now) } },
        onMiss: () => new ConflictError(\"The stay is not over yet.\", { code: \"stay_not_over\" }),
      };
    }
    return { filter: {}, onMiss: null };
  }

  /**
   * Moves a reservation to `to`. `actor` is \"guest\", \"host\" or \"system\"; who
   * the caller really is (policy) is checked by the caller.
   * @returns {Promise<object>} the updated reservation
   */
  async function transition(reservationId, to, { actor, by, reason, refund, expectStatus, now = new Date() } = {}) {
    const current = await ReservationModel.findById(reservationId);
    if (!current) throw new NotFoundError(\"That reservation does not exist.\");
    // The caller worked something out (a refund) from this status: if the
    // booking has moved on since, say so instead of applying a stale result.
    if (expectStatus && current.status !== expectStatus) {
      throw new ConflictError(\"That booking changed. Please reload and try again.\", { code: \"conflict\" });
    }
    assertTransition(current.status, to, actor);

    const guard = guardFor(to, current, now);
    const set = { status: to };
    const unset = {};
    if (to === \"confirmed\" || releasesNights(to) || to === \"completed\") unset.holdExpiresAt = 1;
    if (to === \"cancelled_by_guest\" || to === \"cancelled_by_host\") {
      set.cancelledBy = actor;
      if (reason) set.cancelReason = String(reason).slice(0, 500);
      // The refund is stored by the same compare-and-set that cancels, so a
      // cancelled booking always has the amount that was worked out for it.
      if (refund) {
        set.refund = {
          amountMinor: refund.refundMinor,
          retainedMinor: refund.retainedMinor,
          totalMinor: refund.totalMinor,
          currency: current.pricingSnapshot && current.pricingSnapshot.currency,
          policy: refund.policy || undefined,
          rule: refund.rule,
          calculatedAt: now,
        };
      }
    }
    const entry = { from: current.status, to, at: now, actor, ...(by ? { by } : {}), ...(reason ? { note: String(reason).slice(0, 500) } : {}) };

    const updated = await ReservationModel.findOneAndUpdate(
      { _id: current._id, status: current.status, ...guard.filter },
      { $set: set, ...(Object.keys(unset).length ? { $unset: unset } : {}), $push: { statusHistory: entry } },
      { new: true },
    );
    if (!updated) {
      const latest = await ReservationModel.findById(current._id);
      if (latest && latest.status === current.status && guard.onMiss) throw guard.onMiss();
      assertTransition(latest ? latest.status : current.status, to, actor); // names the status that won
      throw new ConflictError(\"That reservation changed. Please reload and try again.\", { code: \"conflict\" });
    }

    if (to === \"confirmed\") await ledgerService.confirmNights(updated._id);
    else if (releasesNights(to)) await ledgerService.releaseNights(updated._id);

    const event = TRANSITION_EVENTS[to];
    if (event) await tell(event, updated);
    return updated;
  }

  return { create, transition };
}

module.exports = {
  ...createReservationService({ notifier: require(\"./notificationEvents\").notifier }),
  createReservationService,
  PENDING_HOLD_MS,
};

// Hiding and restoring a review (P14-T04). The routes (src/routes/admin.js)
// call these inside auditedMutation, which writes the audit row; nothing here
// writes one.
//
// Hide: a visible review becomes `hidden` with a compare-and-set, so two
// admins at once cannot both succeed; then, in ONE atomic update of the
// listing (services/ratings.js), the review leaves the listing's list and its
// rating totals. Restore does the same in reverse. If the listing update
// fails the review's status is put back, so the status and the totals never
// disagree. The guest's stay still counts as reviewed, so hiding does not let
// the guest write a new review for it.
const mongoose = require(\"mongoose\");
const ratings = require(\"./ratings\");

const REASON_MIN = 5;
const REASON_MAX = 500;

class ReviewModerationError extends Error {
  /** @param {string} message user-safe text, shown to the admin */
  constructor(message) {
    super(message);
    this.name = \"ReviewModerationError\";
  }
}

const isId = (value) =>
  typeof value === \"string\" && mongoose.isValidObjectId(value);

function cleanReason(value) {
  const reason = typeof value === \"string\" ? value.trim() : \"\";
  if (reason.length < REASON_MIN) {
    throw new ReviewModerationError(
      `Give a reason (at least ${REASON_MIN} characters). It is written to the audit log.`,
    );
  }
  if (reason.length > REASON_MAX) {
    throw new ReviewModerationError(
      `The reason must be ${REASON_MAX} characters or fewer.`,
    );
  }
  return reason;
}

function deps(over = {}) {
  return {
    ReviewModel: over.ReviewModel || require(\"../models/review\"),
    ListingModel: over.ListingModel || require(\"../models/listing\"),
  };
}

/** The listing a review belongs to: its own field, else the listing that holds it. */
async function listingIdOf(review, ListingModel) {
  if (review.listing) return review.listing;
  const holder = await ListingModel.findOne({ reviews: review._id })
    .select(\"_id\")
    .lean();
  return holder ? holder._id : null;
}

async function hideReview({ admin, id, reason, now = new Date(), ...over }) {
  const { ReviewModel, ListingModel } = deps(over);
  const why = cleanReason(reason);
  if (!isId(id)) throw new ReviewModerationError(\"That review does not exist.\");

  const review = await ReviewModel.findOneAndUpdate(
    { _id: id, status: { $ne: \"hidden\" } },
    {
      $set: {
        status: \"hidden\",
        \"moderation.hiddenAt\": now,
        \"moderation.hiddenBy\": admin._id,
        \"moderation.hiddenReason\": why,
      },
    },
    { new: true },
  ).lean();
  if (!review) {
    const exists = await ReviewModel.exists({ _id: id });
    throw new ReviewModerationError(
      exists ? \"This review is already hidden.\" : \"That review does not exist.\",
    );
  }
  const listingId = await listingIdOf(review, ListingModel);
  try {
    if (listingId) await ratings.removeReview(ListingModel, listingId, review);
  } catch (err) {
    await ReviewModel.updateOne(
      { _id: id },
      { $set: { status: \"visible\" }, $unset: { moderation: \"\" } },
    );
    throw err;
  }
  return {
    review,
    listingId,
    reason: why,
    details: {
      rating: review.rating,
      listingId: listingId ? String(listingId) : null,
    },
  };
}

async function restoreReview({ admin, id, reason, ...over }) {
  const { ReviewModel, ListingModel } = deps(over);
  const why = cleanReason(reason);
  if (!isId(id)) throw new ReviewModerationError(\"That review does not exist.\");

  const review = await ReviewModel.findOneAndUpdate(
    { _id: id, status: \"hidden\" },
    { $set: { status: \"visible\" }, $unset: { moderation: \"\" } },
    { new: true },
  ).lean();
  if (!review) {
    const exists = await ReviewModel.exists({ _id: id });
    throw new ReviewModerationError(
      exists ? \"This review is not hidden.\" : \"That review does not exist.\",
    );
  }
  const listingId = await listingIdOf(review, ListingModel);
  try {
    if (listingId) await ratings.addReview(ListingModel, listingId, review);
  } catch (err) {
    await ReviewModel.updateOne(
      { _id: id },
      {
        $set: {
          status: \"hidden\",
          \"moderation.hiddenAt\": new Date(),
          \"moderation.hiddenBy\": admin._id,
          \"moderation.hiddenReason\": \"(restore failed; hidden again)\",
        },
      },
    );
    throw err;
  }
  return {
    review,
    listingId,
    reason: why,
    details: {
      rating: review.rating,
      listingId: listingId ? String(listingId) : null,
    },
  };
}

module.exports = {
  hideReview,
  restoreReview,
  cleanReason,
  ReviewModerationError,
  REASON_MIN,
  REASON_MAX,
};

// Writing a review (P12-T01): who may review, and when.
//
// A review belongs to one completed reservation (ADR-010). Every rule has its
// own message and code:
//   not found / not yours ........ 404  (the same answer for both)
//   suspended or signed-out ...... 403 account_not_active
//   own listing .................. 403 own_listing
//   stay not completed ........... 409 stay_not_completed
//   past the window .............. 409 review_window_closed (default 30 days after check-out)
//   already reviewed ............. 409 already_reviewed (also when two requests race: the
//                                  partial unique index on `reservation` decides)
//   bad rating or comment ........ 400
// Editing and replying (P12-T03):
//   edit: only the author, only while the review is visible and inside the edit
//   window (REVIEW_EDIT_DAYS after it was posted); 409 review_edit_window_closed
//   after that. A new rating moves the listing's totals by the difference, in
//   one atomic update (ratings.changeRating).
//   reply: only the listing's host, one reply per review (writing again
//   replaces it), never on a hidden review, 1000 characters at most.
// A review is still allowed after the host deleted the listing: it stays
// attached to the listing's id and to the snapshot taken at booking time.
const {
  ConflictError,
  ForbiddenError,
  NotFoundError,
  ValidationError,
} = require(\"../utils/errors\");
const {
  DEFAULT_TIMEZONE,
  todayIn,
  addDays,
  isAfter,
} = require(\"../utils/dates\");
const { isActiveUser, sameId } = require(\"../policies/shared\");
const ratings = require(\"./ratings\");

const DEFAULT_WINDOW_DAYS = 30;
const DEFAULT_EDIT_DAYS = 7;
const COMMENT_MAX = 2000;
const REPLY_MAX = 1000;
const DAY_MS = 24 * 60 * 60 * 1000;
const OBJECT_ID = /^[0-9a-f]{24}$/i;

/** The last day (date-only) a stay can be reviewed: check-out + window. */
function windowEnd(reservation, windowDays) {
  return addDays(reservation.checkOut, windowDays);
}

function parseRating(raw) {
  const text = typeof raw === \"number\" ? String(raw) : raw;
  if (typeof text !== \"string\" || !/^[1-5]$/.test(text.trim())) {
    throw new ValidationError(\"Choose a rating from 1 to 5 stars.\");
  }
  return Number(text.trim());
}

function parseComment(raw) {
  if (typeof raw !== \"string\")
    throw new ValidationError(\"Write a comment about your stay.\");
  const text = raw.trim();
  if (text.length === 0)
    throw new ValidationError(\"Write a comment about your stay.\");
  if (text.length > COMMENT_MAX) {
    throw new ValidationError(
      `The comment can be at most ${COMMENT_MAX} characters.`,
    );
  }
  return text;
}

function parseReply(raw) {
  const text = typeof raw === \"string\" ? raw.trim() : \"\";
  if (text.length === 0) throw new ValidationError(\"Write a reply.\");
  if (text.length > REPLY_MAX) {
    throw new ValidationError(
      `The reply can be at most ${REPLY_MAX} characters.`,
    );
  }
  return text;
}

/** When a review was posted: `createdAt`, else the time its id was created. */
function postedAt(review) {
  const created =
    review && review.createdAt ? new Date(review.createdAt) : null;
  if (created && !Number.isNaN(created.getTime())) return created;
  return review && review._id && typeof review._id.getTimestamp === \"function\"
    ? review._id.getTimestamp()
    : null;
}

/** The moment the author can no longer edit this review (null if its age is unknown). */
function editDeadline(review, editDays = DEFAULT_EDIT_DAYS) {
  const posted = postedAt(review);
  return posted ? new Date(posted.getTime() + editDays * DAY_MS) : null;
}

/** Can the author still edit? (Ownership and status are checked elsewhere.) */
function isEditable(review, now = new Date(), editDays = DEFAULT_EDIT_DAYS) {
  if (!review || review.status === \"hidden\") return false;
  const deadline = editDeadline(review, editDays);
  return Boolean(deadline) && now.getTime() <= deadline.getTime();
}

const isDuplicateKey = (err) =>
  Boolean(err) && (err.code === 11000 || err.code === 11001);

function createReviewService({
  ReservationModel = require(\"../models/reservation\"),
  ReviewModel = require(\"../models/review\"),
  ListingModel = require(\"../models/listing\"),
  windowDays = DEFAULT_WINDOW_DAYS,
  editDays = DEFAULT_EDIT_DAYS,
} = {}) {
  /**
   * @param {{ user: object, listingId: string, reservationId: string,
   *           rating: unknown, comment: unknown, now?: Date, windowDays?: number }} input
   * @returns {Promise<object>} the stored review
   */
  async function submit({
    user,
    listingId,
    reservationId,
    rating,
    comment,
    now = new Date(),
    windowDays: days = windowDays,
  }) {
    // Input first: nothing is looked up for a request that is wrong in itself.
    const stars = parseRating(rating);
    const text = parseComment(comment);

    if (!isActiveUser(user)) {
      throw new ForbiddenError(\"Your account cannot write reviews.\", {
        code: \"account_not_active\",
      });
    }
    const reservation = OBJECT_ID.test(String(reservationId))
      ? await ReservationModel.findById(reservationId)
      : null;
    // Somebody else's booking, a booking of another listing, and a booking that
    // does not exist all look the same.
    if (
      !reservation ||
      !sameId(reservation.guest, user._id) ||
      (listingId && !sameId(reservation.listing, listingId))
    ) {
      throw new NotFoundError(\"That stay does not exist.\");
    }
    if (sameId(reservation.host, user._id)) {
      throw new ForbiddenError(\"You cannot review your own listing.\", {
        code: \"own_listing\",
      });
    }
    if (reservation.status !== \"completed\") {
      throw new ConflictError(\"You can review a stay once it is completed.\", {
        code: \"stay_not_completed\",
      });
    }
    const snapshot = reservation.listingSnapshot || {};
    const today = todayIn(snapshot.timezone || DEFAULT_TIMEZONE, now);
    if (isAfter(today, windowEnd(reservation, days))) {
      throw new ConflictError(
        `Reviews can be written up to ${days} days after check-out.`,
        {
          code: \"review_window_closed\",
        },
      );
    }
    if (await ReviewModel.exists({ reservation: reservation._id })) {
      throw new ConflictError(\"You have already reviewed this stay.\", {
        code: \"already_reviewed\",
      });
    }

    let review;
    try {
      review = await ReviewModel.create({
        author: user._id,
        listing: reservation.listing,
        reservation: reservation._id,
        rating: stars,
        comment: text,
        legacy: false,
        listingSnapshot: { title: snapshot.title, city: snapshot.city },
      });
    } catch (err) {
      // Two requests for the same stay at once: the unique index let one in.
      if (isDuplicateKey(err)) {
        throw new ConflictError(\"You have already reviewed this stay.\", {
          code: \"already_reviewed\",
        });
      }
      throw err;
    }
    // One atomic update adds the review to the listing's list and to its rating
    // totals (services/ratings.js). If it fails, the review is taken back so a
    // review never exists without being counted.
    try {
      await ratings.addReview(ListingModel, reservation.listing, review);
    } catch (err) {
      await ReviewModel.deleteOne({ _id: review._id }).catch(() => {});
      throw err;
    }
    return review;
  }

  /**
   * The stay a signed-in guest could review on this listing right now, or
   * null: completed, inside the window, not reviewed yet, newest check-out first.
   * It only decides whether the page offers the form; `submit` decides again.
   */
  async function findReviewable({
    user,
    listingId,
    now = new Date(),
    windowDays: days = windowDays,
  }) {
    if (!isActiveUser(user) || !OBJECT_ID.test(String(listingId))) return null;
    const candidates = await ReservationModel.find({
      guest: user._id,
      listing: listingId,
      status: \"completed\",
    })
      .sort({ checkOut: -1 })
      .limit(10)
      .lean();
    const open = candidates.filter((r) => {
      const snap = r.listingSnapshot || {};
      return (
        !isAfter(
          todayIn(snap.timezone || DEFAULT_TIMEZONE, now),
          windowEnd(r, days),
        ) && !sameId(r.host, user._id)
      );
    });
    if (open.length === 0) return null;
    const reviewed = await ReviewModel.find({
      reservation: { $in: open.map((r) => r._id) },
    })
      .select(\"reservation\")
      .lean();
    const done = new Set(reviewed.map((r) => String(r.reservation)));
    const next = open.find((r) => !done.has(String(r._id)));
    return next
      ? { reservationId: String(next._id), reviewUntil: windowEnd(next, days) }
      : null;
  }

  /**
   * Delete a review and take it out of the listing's list and totals. Only the
   * request that really deleted it changes the totals, so deleting twice at
   * once subtracts once. Who may delete is the route's `review:delete` policy.
   * @returns {Promise<object|null>} the deleted review, or null if it was already gone
   */
  async function remove({ listingId, reviewId }) {
    const removed = await ReviewModel.findOneAndDelete({ _id: reviewId });
    if (!removed) return null;
    // A hidden review (P14-T04) was already taken out of the list and the
    // totals when it was hidden; subtracting again would count it twice.
    if (removed.status === \"hidden\") return removed;
    try {
      await ratings.removeReview(ListingModel, listingId, removed);
    } catch (err) {
      // The review is gone but the totals were not changed: repair them from the reviews.
      await ratings
        .recomputeRatings({ ListingModel, ReviewModel }, listingId)
        .catch(() => {});
      throw err;
    }
    return removed;
  }

  /**
   * What the booking page shows about reviewing a stay:
   *   \"open\"   completed, inside the window, not reviewed (the form)
   *   \"done\"   already reviewed (the review)
   *   \"closed\" completed, not reviewed, the window has passed
   *   \"none\"   anything else (not the guest, not completed yet)
   * @returns {Promise<{state: string, review?: object, until?: Date}>}
   */
  async function stateFor({
    user,
    reservation,
    now = new Date(),
    windowDays: days = windowDays,
    editDays: editFor = editDays,
  }) {
    if (
      !isActiveUser(user) ||
      !reservation ||
      !sameId(reservation.guest, user._id) ||
      reservation.status !== \"completed\"
    ) {
      return { state: \"none\" };
    }
    const review = await ReviewModel.findOne({
      reservation: reservation._id,
    }).lean();
    if (review) {
      return {
        state: \"done\",
        review,
        editable: isEditable(review, now, editFor),
        editUntil: editDeadline(review, editFor),
      };
    }
    const snap = reservation.listingSnapshot || {};
    const until = windowEnd(reservation, days);
    const open = !isAfter(
      todayIn(snap.timezone || DEFAULT_TIMEZONE, now),
      until,
    );
    return { state: open ? \"open\" : \"closed\", until };
  }

  /**
   * The author changes the rating and/or comment of their own review, inside
   * the edit window. One compare-and-set on the review (author, visible, still
   * inside the window) returns the document as it was, so the rating difference
   * is exact even when two edits arrive together; then ONE atomic update moves
   * the listing's totals by that difference. If that update fails the review is
   * put back, so the review and the totals never disagree.
   * @returns {Promise<{review: object, changed: boolean}>}
   */
  async function edit({
    user,
    listingId,
    reviewId,
    rating,
    comment,
    now = new Date(),
    editDays: days = editDays,
  }) {
    const stars = parseRating(rating);
    const text = parseComment(comment);
    if (!isActiveUser(user)) {
      throw new ForbiddenError(\"Your account cannot edit reviews.\", {
        code: \"account_not_active\",
      });
    }
    if (!OBJECT_ID.test(String(reviewId))) {
      throw new NotFoundError(\"That review does not exist.\");
    }
    const current = await ReviewModel.findOne({ _id: reviewId });
    // Somebody else's review, a review of another listing, a hidden review and
    // one that does not exist all look the same.
    if (
      !current ||
      current.status === \"hidden\" ||
      !sameId(current.author, user._id) ||
      (current.listing && listingId && !sameId(current.listing, listingId))
    ) {
      throw new NotFoundError(\"That review does not exist.\");
    }
    if (!isEditable(current, now, days)) {
      throw new ConflictError(
        `A review can be edited for ${days} days after it was posted.`,
        { code: \"review_edit_window_closed\" },
      );
    }
    if (current.rating === stars && current.comment === text) {
      return { review: current, changed: false };
    }

    const cutoff = new Date(now.getTime() - days * DAY_MS);
    const before = await ReviewModel.findOneAndUpdate(
      {
        _id: current._id,
        author: user._id,
        status: { $ne: \"hidden\" },
        createdAt: { $gte: cutoff },
      },
      { $set: { rating: stars, comment: text, editedAt: now } },
      { new: false },
    );
    if (!before) {
      // Hidden, deleted or past the window between the read and the write.
      throw new ConflictError(\"This review can no longer be edited.\", {
        code: \"review_edit_window_closed\",
      });
    }

    if (before.rating !== stars) {
      const target = before.listing || current.listing || listingId;
      try {
        await ratings.changeRating(ListingModel, target, {
          from: before.rating,
          to: stars,
        });
        // Hidden while we were changing it: the totals no longer include it,
        // so repair them from the reviews instead of trusting the difference.
        if (await ReviewModel.exists({ _id: before._id, status: \"hidden\" })) {
          await ratings.recomputeRatings({ ListingModel, ReviewModel }, target);
        }
      } catch (err) {
        await ReviewModel.updateOne(
          { _id: before._id },
          {
            $set: {
              rating: before.rating,
              comment: before.comment,
              ...(before.editedAt ? { editedAt: before.editedAt } : {}),
            },
            ...(before.editedAt ? {} : { $unset: { editedAt: \"\" } }),
          },
        ).catch(() => {});
        throw err;
      }
    }
    const plain = before.toObject ? before.toObject() : { ...before };
    return {
      review: { ...plain, rating: stars, comment: text, editedAt: now },
      changed: true,
    };
  }

  // The listing's host (who `listing` is, already authorized by the route's
  // `review:reply` policy) answers a visible review of that listing.
  async function loadReplyTarget({ user, listing, reviewId }) {
    if (!isActiveUser(user) || !listing || !sameId(listing.owner, user._id)) {
      throw new ForbiddenError(\"Only the host can reply to reviews.\", {
        code: \"not_host\",
      });
    }
    // A hidden review leaves the listing's list, so membership covers it too.
    const listed = (listing.reviews || []).some((r) => sameId(r, reviewId));
    if (!listed || !OBJECT_ID.test(String(reviewId))) {
      throw new NotFoundError(\"That review does not exist.\");
    }
  }

  /**
   * The host writes (or replaces) the one public reply to a review. Replacing
   * keeps the first reply's date and records `editedAt`.
   * @returns {Promise<object>} the review with its reply
   */
  async function reply({ user, listing, reviewId, text, now = new Date() }) {
    const body = parseReply(text);
    await loadReplyTarget({ user, listing, reviewId });
    const existing = await ReviewModel.findOne({
      _id: reviewId,
      status: { $ne: \"hidden\" },
    });
    if (!existing) throw new NotFoundError(\"That review does not exist.\");
    const had = existing.reply && existing.reply.text;
    const update = had
      ? { $set: { \"reply.text\": body, \"reply.editedAt\": now } }
      : {
          $set: {
            reply: {
              text: body,
              author: user._id,
              createdAt: now,
            },
          },
        };
    const saved = await ReviewModel.findOneAndUpdate(
      { _id: reviewId, status: { $ne: \"hidden\" } },
      update,
      { new: true },
    );
    if (!saved) throw new NotFoundError(\"That review does not exist.\");
    return saved;
  }

  /** The host takes their reply back. @returns {Promise<boolean>} whether there was one */
  async function removeReply({ user, listing, reviewId }) {
    await loadReplyTarget({ user, listing, reviewId });
    const done = await ReviewModel.findOneAndUpdate(
      { _id: reviewId, \"reply.text\": { $exists: true } },
      { $unset: { reply: \"\" } },
      { new: false },
    );
    return Boolean(done);
  }

  return {
    submit,
    remove,
    edit,
    reply,
    removeReply,
    findReviewable,
    stateFor,
  };
}

module.exports = {
  ...createReviewService(),
  createReviewService,
  parseRating,
  parseComment,
  parseReply,
  windowEnd,
  editDeadline,
  isEditable,
  DEFAULT_WINDOW_DAYS,
  DEFAULT_EDIT_DAYS,
  COMMENT_MAX,
  REPLY_MAX,
};

// Saved searches (P10-T02): a name and the canonical query string of
// /listings. The query is built HERE from the validated search state
// (parseListingQuery, the same function the listings page uses), so what is
// stored is only known parameters with valid values, in a fixed order, without
// the page number; the browser's text is never stored or redirected to as is.
// The re-run link is \"/listings?\" + that string.
//
// Dates are stored as chosen: a saved search with dates that have passed shows
// the listings page's own message about them when it is run.
const { parseListingQuery } = require(\"../validation/searchQuery\");
const { queryPairs } = require(\"../utils/searchUrl\");
const { SEARCH_LIMITS } = require(\"../config/wishlists\");
const { parseName } = require(\"./wishlistLists\");
const { NotFoundError, ConflictError, ValidationError } = require(\"../utils/errors\");

const OBJECT_ID = /^[0-9a-f]{24}$/i;

function model(deps = {}) {
  return deps.SavedSearch || require(\"../models/savedSearch\");
}

/**
 * The canonical query string for what a form or link sent.
 * @param {object} raw  req.body / req.query (without name and _csrf)
 * @returns {string} \"dest=Goa&guests=2\" (\"\" when nothing valid was set)
 */
function canonicalQuery(raw) {
  const { _csrf, name, ...rest } = raw && typeof raw === \"object\" ? raw : {};
  void _csrf;
  void name;
  const { state } = parseListingQuery(rest);
  // `page` is never saved, and neither is the sort order's default.
  const { page, ...kept } = state;
  void page;
  return new URLSearchParams(queryPairs(kept)).toString();
}

const hrefOf = (query) => `/listings?${query}`;

/** A short description of a query for the list (\"Goa · 2 guests · 12 Nov to 15 Nov\"). */
function describeQuery(query) {
  const p = new URLSearchParams(query);
  const parts = [];
  if (p.get(\"dest\")) parts.push(p.get(\"radius\") ? `${p.get(\"dest\")} (within ${p.get(\"radius\")} km)` : p.get(\"dest\"));
  if (p.get(\"in\") && p.get(\"out\")) parts.push(`${p.get(\"in\")} to ${p.get(\"out\")}`);
  if (p.get(\"guests\")) parts.push(`${p.get(\"guests\")} guest${p.get(\"guests\") === \"1\" ? \"\" : \"s\"}`);
  if (p.get(\"minPrice\") || p.get(\"maxPrice\")) {
    parts.push(`price ${p.get(\"minPrice\") || \"0\"}${p.get(\"maxPrice\") ? ` to ${p.get(\"maxPrice\")}` : \"+\"}`);
  }
  if (p.get(\"type\")) parts.push(p.get(\"type\"));
  const other = [...p.keys()].filter(
    (k) => ![\"dest\", \"radius\", \"in\", \"out\", \"guests\", \"minPrice\", \"maxPrice\", \"type\", \"sort\"].includes(k),
  );
  if (other.length) parts.push(`${new Set(other).size} more filter${new Set(other).size === 1 ? \"\" : \"s\"}`);
  return parts.join(\" · \") || \"All stays\";
}

async function save(userId, { name, params }, deps) {
  const SavedSearch = model(deps);
  const clean = parseName(name);
  const query = (deps && deps.canonicalQuery ? deps.canonicalQuery : canonicalQuery)(params);
  if (!query) {
    throw new ValidationError(\"Set a destination, dates or a filter first: there is nothing to save in an empty search.\");
  }
  if (query.length > SEARCH_LIMITS.queryMax) throw new ValidationError(\"That search is too long to save.\");
  const count = await SavedSearch.countDocuments({ owner: userId });
  if (count >= SEARCH_LIMITS.maxSaved) {
    throw new ConflictError(`You can keep at most ${SEARCH_LIMITS.maxSaved} saved searches. Delete one first.`, {
      code: \"too_many_searches\",
    });
  }
  try {
    const doc = await SavedSearch.create({ owner: userId, name: clean, query });
    return { id: String(doc._id), name: doc.name, query, href: hrefOf(query) };
  } catch (err) {
    if (err && err.code === 11000) {
      throw new ConflictError(\"You already have a saved search with that name.\", { code: \"name_taken\" });
    }
    throw err;
  }
}

/** The member's saved searches, newest first, with their re-run links. */
async function list(userId, deps) {
  const rows = await model(deps)
    .find({ owner: userId })
    .sort({ createdAt: -1 })
    .limit(SEARCH_LIMITS.maxSaved)
    .lean();
  return rows.map((row) => ({
    id: String(row._id),
    name: row.name,
    summary: describeQuery(row.query),
    href: hrefOf(row.query),
    createdAt: row.createdAt,
  }));
}

async function remove(userId, id, deps) {
  if (!OBJECT_ID.test(String(id))) throw new NotFoundError(\"That saved search does not exist.\");
  const result = await model(deps).deleteOne({ _id: id, owner: userId });
  if (!result.deletedCount) throw new NotFoundError(\"That saved search does not exist.\");
  return { removed: true };
}

module.exports = { save, list, remove, canonicalQuery, describeQuery };

// Search (P05-T01): turns validated parameters into a Mongo filter and runs it.
// Only listings a visitor may see are ever matched (published, not deleted).
//
//   destination  \"Panaji, Goa\": each comma-separated part must START the city,
//                state or country key (anchored, so an index can serve it)
//   keywords     words in the title or description (the text index)
//   minPrice / maxPrice   rupees per night
//   guests / bedrooms     at least this many
//   propertyType / roomType   any of
//   amenities    all of
//   instantBook  true = only instant-book listings
//   category     one slug from src/config/categories.js (P05-T04); added as one
//                more condition, so it narrows the other filters, never widens
//
// `sort` and `page` (P05-T03) are handled by searchPage below; the URL names and
// forms are P05-T02.
const { parseSearchParams, DEFAULT_SORT } = require(\"../validation/search\");
const { publicListingFilter } = require(\"../utils/visibility\");
const { destinationParts, escapeRegex } = require(\"../utils/searchKeys\");
const { rupeesToMinor } = require(\"../utils/listingFields\");
const { categoryClause } = require(\"../config/categories\");

const PAGE_SIZE = 12;
const DEFAULT_LIMIT = 24;
const MAX_LIMIT = 100;

/**
 * The filter for already validated parameters (see parseSearchParams).
 * Values are only ever placed as plain strings, numbers, RegExps built from
 * escaped text, or arrays of strings, never as objects taken from the request.
 */
function buildFilter(params = {}) {
  const filter = { ...publicListingFilter() };

  const parts = destinationParts(params.destination);
  if (parts.length) {
    filter.$and = parts.map((part) => {
      const start = new RegExp(`^${escapeRegex(part)}`);
      return { $or: [{ cityKey: start }, { stateKey: start }, { countryKey: start }] };
    });
  }

  if (typeof params.keywords === \"string\" && params.keywords.trim()) {
    filter.$text = { $search: params.keywords.trim() };
  }

  const price = {};
  if (typeof params.minPrice === \"number\") price.$gte = rupeesToMinor(params.minPrice);
  if (typeof params.maxPrice === \"number\") price.$lte = rupeesToMinor(params.maxPrice);
  if (Object.keys(price).length) filter[\"pricing.nightlyMinor\"] = price;

  if (Number.isInteger(params.guests)) filter[\"capacity.guests\"] = { $gte: params.guests };
  if (Number.isInteger(params.bedrooms)) filter[\"capacity.bedrooms\"] = { $gte: params.bedrooms };

  if (Array.isArray(params.propertyType) && params.propertyType.length) {
    filter.propertyType = { $in: params.propertyType };
  }
  if (Array.isArray(params.roomType) && params.roomType.length) {
    filter.roomType = { $in: params.roomType };
  }
  if (Array.isArray(params.amenities) && params.amenities.length) {
    filter.amenities = { $all: params.amenities };
  }
  // Accessibility features are declared by hosts (P15-T05): a listing must
  // declare ALL the ones asked for. Listings that declare nothing never match.
  if (Array.isArray(params.access) && params.access.length) {
    filter.accessibility = { $all: params.access };
  }
  if (params.instantBook === true) filter.instantBook = true;

  const category = categoryClause(params.category);
  if (category) filter.$and = [...(filter.$and || []), category];

  return filter;
}

/** Validates `query` and builds the filter in one step. */
function searchFilterFor(query) {
  const { value, errors } = parseSearchParams(query);
  return { params: value, errors, filter: buildFilter(value) };
}

/**
 * Runs a search. Newest first until P05-T03 adds sorting.
 * @returns {Promise<{ listings: object[], params: object, errors: object, filter: object }>}
 */
async function searchListings(Listing, query, { limit = DEFAULT_LIMIT, skip = 0 } = {}) {
  const { params, errors, filter } = searchFilterFor(query);
  const take = Math.min(Math.max(Number.isInteger(limit) ? limit : DEFAULT_LIMIT, 1), MAX_LIMIT);
  const listings = await Listing.find(filter)
    .sort({ _id: -1 })
    .skip(Math.max(Number.isInteger(skip) ? skip : 0, 0))
    .limit(take);
  return { listings, params, errors, filter };
}

/** MongoDB's own account of how a search runs (used by the index check). */
async function explainSearch(Listing, query) {
  const { filter } = searchFilterFor(query);
  return Listing.find(filter).explain(\"executionStats\");
}

/**
 * The Mongo sort for a sort name. Every order ends with `_id` in the same
 * direction, so two listings never tie and a listing never appears on two
 * pages (or none) while paging.
 *  relevance  text score (only when searching by keywords), then rating, then newest
 *  price_asc / price_desc   nightly price
 *  rating     average rating, then number of reviews
 *  newest     most recently created
 * @returns {{ sort: object, projection?: object }}
 */
function sortSpec(name, { hasText = false } = {}) {
  switch (name) {
    case \"price_asc\":
      return { sort: { \"pricing.nightlyMinor\": 1, _id: 1 } };
    case \"price_desc\":
      return { sort: { \"pricing.nightlyMinor\": -1, _id: -1 } };
    case \"rating\":
      return { sort: { ratingAvg: -1, ratingCount: -1, _id: -1 } };
    case \"newest\":
      return { sort: { createdAt: -1, _id: -1 } };
    default: // relevance
      return hasText
        ? {
            projection: { score: { $meta: \"textScore\" } },
            sort: { score: { $meta: \"textScore\" }, ratingAvg: -1, ratingCount: -1, _id: -1 },
          }
        : { sort: { ratingAvg: -1, ratingCount: -1, _id: -1 } };
  }
}

/**
 * One page of results with the numbers a results page needs.
 * @returns {Promise<{
 *   listings: object[], total: number, page: number, totalPages: number,
 *   pageSize: number, sort: string, outOfRange: boolean,
 *   params: object, errors: object, filter: object }>}
 * `outOfRange` is true when the page asked for is past the last one: then
 * `listings` is empty and `totalPages` says where the last page is.
 */
async function searchPage(Listing, query) {
  const { params, errors, filter } = searchFilterFor(query);
  const sort = params.sort || DEFAULT_SORT;
  const requested = Number.isInteger(params.page) ? params.page : 1;

  const total = await Listing.countDocuments(filter);
  const totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE));
  const base = { total, page: requested, totalPages, pageSize: PAGE_SIZE, sort, params, errors, filter };
  if (requested > totalPages) return { ...base, listings: [], outOfRange: true };

  const spec = sortSpec(sort, { hasText: Boolean(filter.$text) });
  const cursor = spec.projection ? Listing.find(filter, spec.projection) : Listing.find(filter);
  const listings = await cursor
    .sort(spec.sort)
    .skip((requested - 1) * PAGE_SIZE)
    .limit(PAGE_SIZE);
  return { ...base, listings, outOfRange: false };
}

module.exports = {
  PAGE_SIZE,
  sortSpec,
  searchPage,
  DEFAULT_LIMIT,
  MAX_LIMIT,
  buildFilter,
  searchFilterFor,
  searchListings,
  explainSearch,
};

// Read-only sharing of a wishlist by a link (P10-T04).
//
//   enableShare(userId, listId)  the owner makes the link (idempotent: the same
//                                link until they stop sharing)
//   revokeShare(userId, listId)  the owner stops sharing; the link dies at once
//   viewShared(token)            what a visitor with the link may see
//
// What a visitor sees: the list's name, the owner's display name and the
// stays that are still public, as ordinary cards. Never: the owner's email,
// username, id or profile link, the member's notes, when things were saved,
// stays that were hidden or removed, or any other list. Opening the page
// changes nothing. An unknown, malformed, revoked or orphaned token, and a list
// whose owner is no longer an active member, are the same 404.
const crypto = require(\"node:crypto\");
const { LIMITS } = require(\"../config/wishlists\");
const { toCardItem } = require(\"../utils/listingCard\");
const { NotFoundError } = require(\"../utils/errors\");

const OBJECT_ID = /^[0-9a-f]{24}$/i;
const TOKEN_PATTERN = /^[A-Za-z0-9_-]{32}$/;

function models(deps = {}) {
  return {
    Wishlist: deps.Wishlist || require(\"../models/wishlist\"),
    WishlistItem: deps.WishlistItem || require(\"../models/wishlistItem\"),
    Listing: deps.Listing || require(\"../models/listing\"),
    User: deps.User || require(\"../models/user\"),
    newToken: deps.newToken || (() => crypto.randomBytes(24).toString(\"base64url\")),
    now: deps.now || (() => new Date()),
  };
}

const isPublic = (listing) =>
  Boolean(listing) && listing.status === \"published\" && !listing.deletedAt;

async function ownedList(userId, listId, Wishlist) {
  const list = OBJECT_ID.test(String(listId))
    ? await Wishlist.findOne({ _id: listId, owner: userId }).lean()
    : null;
  if (!list) throw new NotFoundError(\"That list does not exist.\");
  return list;
}

/** @returns {Promise<{ token: string, created: boolean }>} */
async function enableShare(userId, listId, deps) {
  const { Wishlist, newToken, now } = models(deps);
  const list = await ownedList(userId, listId, Wishlist);
  if (list.shareToken) return { token: list.shareToken, created: false };
  for (let attempt = 0; attempt < 3; attempt += 1) {
    const token = newToken();
    try {
      // Only when nobody made a link meanwhile: a twin request gets the same one.
      const result = await Wishlist.updateOne(
        { _id: list._id, owner: userId, shareToken: { $exists: false } },
        { $set: { shareToken: token, sharedAt: now() } },
      );
      const matched = result.matchedCount !== undefined ? result.matchedCount : result.n;
      if (matched) return { token, created: true };
      const again = await Wishlist.findOne({ _id: list._id, owner: userId }).lean();
      if (again && again.shareToken) return { token: again.shareToken, created: false };
    } catch (err) {
      if (!(err && err.code === 11000)) throw err; // the token clashed (astronomically unlikely): try another
    }
  }
  throw new Error(\"Could not make a share link.\");
}

/** @returns {Promise<{ revoked: boolean }>} */
async function revokeShare(userId, listId, deps) {
  const { Wishlist } = models(deps);
  const list = await ownedList(userId, listId, Wishlist);
  await Wishlist.updateOne(
    { _id: list._id, owner: userId },
    { $unset: { shareToken: 1, sharedAt: 1 } },
  );
  return { revoked: Boolean(list.shareToken) };
}

/**
 * @returns {Promise<{ name: string, ownerName: string, items: object[], hidden: number }>}
 * @throws NotFoundError
 */
async function viewShared(token, deps) {
  const { Wishlist, WishlistItem, Listing, User } = models(deps);
  if (typeof token !== \"string\" || !TOKEN_PATTERN.test(token)) {
    throw new NotFoundError(\"That shared list does not exist.\");
  }
  const list = await Wishlist.findOne({ shareToken: token }).lean();
  const owner = list
    ? await User.findById(list.owner).select(\"displayName username status\").lean()
    : null;
  if (!list || !owner || owner.status !== \"active\") {
    throw new NotFoundError(\"That shared list does not exist.\");
  }
  const rows = await WishlistItem.find({ wishlist: list._id })
    .sort({ createdAt: -1 })
    .limit(LIMITS.maxItems)
    .lean();
  const listings = rows.length
    ? await Listing.find({ _id: { $in: rows.map((r) => r.listing) } })
        .select(\"title image location country pricing status deletedAt\")
        .lean()
    : [];
  const byId = new Map(listings.map((l) => [String(l._id), l]));
  const items = rows
    .map((row) => byId.get(String(row.listing)))
    .filter(isPublic)
    .map(toCardItem);
  return {
    name: list.name,
    ownerName: owner.displayName || owner.username,
    items,
    hidden: rows.length - items.length,
  };
}

module.exports = { enableShare, revokeShare, viewShared, TOKEN_PATTERN };

// Reservation state machine (P07-T05). The only place that says which status
// changes are allowed, and who may make them. Pure: no database, no clock.
//
//   pending ──host──► confirmed        confirmed ──guest──► cancelled_by_guest
//   pending ──host──► declined         confirmed ──host───► cancelled_by_host
//   pending ──system► expired          confirmed ──system─► completed
//   pending ──guest─► cancelled_by_guest
//
// A booking on an instant-book listing is created already `confirmed`
// (that is a creation, not a transition). Any other move is an
// InvalidTransitionError (409).
//
// Nights: pending and confirmed reservations hold their nights in the ledger
// (ADR-004). declined, expired and both cancellations RELEASE them. completed
// keeps its (past) rows, as ADR-004 says \"past rows kept\".
const { InvalidTransitionError } = require(\"../utils/errors\");

const STATUSES = Object.freeze([
  \"pending\",
  \"confirmed\",
  \"declined\",
  \"expired\",
  \"cancelled_by_guest\",
  \"cancelled_by_host\",
  \"completed\",
]);

const ACTORS = Object.freeze([\"guest\", \"host\", \"system\"]);

// from -> to -> the actors who may make the move.
const TRANSITIONS = Object.freeze({
  pending: Object.freeze({
    confirmed: [\"host\"],
    declined: [\"host\"],
    expired: [\"system\"],
    cancelled_by_guest: [\"guest\"],
  }),
  confirmed: Object.freeze({
    cancelled_by_guest: [\"guest\"],
    cancelled_by_host: [\"host\"],
    completed: [\"system\"],
  }),
  declined: Object.freeze({}),
  expired: Object.freeze({}),
  cancelled_by_guest: Object.freeze({}),
  cancelled_by_host: Object.freeze({}),
  completed: Object.freeze({}),
});

const RELEASING = Object.freeze([
  \"declined\",
  \"expired\",
  \"cancelled_by_guest\",
  \"cancelled_by_host\",
]);

const isStatus = (value) => STATUSES.includes(value);

/** Statuses a reservation can still leave. */
const isTerminal = (status) =>
  isStatus(status) && Object.keys(TRANSITIONS[status]).length === 0;

/** Does a reservation in this status keep rows in the night ledger? */
const holdsNights = (status) =>
  status === \"pending\" || status === \"confirmed\" || status === \"completed\";

/** Does moving INTO this status free the nights? */
const releasesNights = (to) => RELEASING.includes(to);

/** Is `from -> to` in the table (any actor)? */
function canTransition(from, to) {
  return isStatus(from) && isStatus(to) && Boolean(TRANSITIONS[from][to]);
}

/** Actors allowed to make `from -> to` (empty when the move is not allowed). */
function actorsFor(from, to) {
  return canTransition(from, to) ? [...TRANSITIONS[from][to]] : [];
}

/**
 * Throws InvalidTransitionError (409) unless the move is in the table and, when
 * `actor` is given, that actor may make it.
 */
function assertTransition(from, to, actor) {
  if (!canTransition(from, to)) throw new InvalidTransitionError(from, to);
  if (actor !== undefined && !TRANSITIONS[from][to].includes(actor)) {
    throw new InvalidTransitionError(
      from,
      to,
      `A ${actor} cannot change a reservation from ${from} to ${to}.`,
    );
  }
}

module.exports = {
  STATUSES,
  ACTORS,
  TRANSITIONS,
  isStatus,
  isTerminal,
  holdsNights,
  releasesNights,
  canTransition,
  actorsFor,
  assertTransition,
};

// What to offer when a search finds nothing (P05-T05).
//
// Two kinds of suggestion, both guaranteed to lead somewhere:
//   * \"Remove this filter\": for some of the active filters, how many stays there
//     would be without it. Only filters whose removal gives at least one stay
//     are offered, the ones giving most stays first.
//   * Popular destinations: places that really have stays, linked with NO other
//     filter, so each of them has results by construction.
// A \"clear all filters\" link is offered only when there is any stay at all.
//
// Cost: at most MAX_EXTRA_QUERIES (5) database queries per empty search: up to
// 4 counts (one per filter group looked at) and 1 for the destinations. With more
// than 4 active filter groups only the first 4 in GROUPS order are looked at.
const { buildFilter } = require(\"./search\");
const { publicListingFilter } = require(\"../utils/visibility\");
const { destinationParts, normaliseToken } = require(\"../utils/searchKeys\");
const { listingsUrl } = require(\"../utils/searchUrl\");

const MAX_EXTRA_QUERIES = 5;
const MAX_FILTER_COUNTS = MAX_EXTRA_QUERIES - 1; // one query is kept for destinations
const MAX_FILTER_SUGGESTIONS = 3;
const MAX_DESTINATIONS = 6;
const SCAN_LIMIT = 200; // newest public listings looked at for destinations

const plural = (n, one, many) => `${n} ${n === 1 ? one : many}`;

// A filter group: the URL parameters it owns, the search-service parameters it
// owns, when it is active and how to describe removing it. In the order they
// are looked at (dates and amenities usually remove the most stays).
const GROUPS = [
  {
    key: \"radius\",
    urlKeys: [\"radius\"],
    serviceKeys: [],
    active: (p) => Boolean(p.area),
    label: (s) => `Search only \"${s.dest}\" itself, not ${s.radius} km around it`,
  },
  {
    key: \"dates\",
    urlKeys: [\"in\", \"out\"],
    serviceKeys: [], // dates act through the night ledger, not the filter
    active: (p) => Boolean(p.stay),
    label: (s) => `Remove the dates (${s.in} to ${s.out})`,
  },
  {
    key: \"amenities\",
    urlKeys: [\"amenities\"],
    serviceKeys: [\"amenities\"],
    active: (p) => Array.isArray(p.searchParams.amenities) && p.searchParams.amenities.length > 0,
    label: () => \"Remove the amenity filters\",
  },
  {
    key: \"access\",
    urlKeys: [\"access\"],
    serviceKeys: [\"access\"],
    active: (p) => Array.isArray(p.searchParams.access) && p.searchParams.access.length > 0,
    label: () => \"Remove the accessibility filters\",
  },
  {
    key: \"price\",
    urlKeys: [\"minPrice\", \"maxPrice\"],
    serviceKeys: [\"minPrice\", \"maxPrice\"],
    active: (p) => p.searchParams.minPrice !== undefined || p.searchParams.maxPrice !== undefined,
    label: () => \"Remove the price limit\",
  },
  {
    key: \"type\",
    urlKeys: [\"type\"],
    serviceKeys: [\"propertyType\"],
    active: (p) => Array.isArray(p.searchParams.propertyType) && p.searchParams.propertyType.length > 0,
    label: () => \"Allow any property type\",
  },
  {
    key: \"guests\",
    urlKeys: [\"guests\"],
    serviceKeys: [\"guests\"],
    active: (p) => p.searchParams.guests !== undefined,
    label: (s) => `Remove the guest count (${plural(s.guests, \"guest\", \"guests\")})`,
  },
  {
    key: \"instantBook\",
    urlKeys: [\"instantBook\"],
    serviceKeys: [\"instantBook\"],
    active: (p) => p.searchParams.instantBook === true,
    label: () => \"Include stays that are not instant book\",
  },
  {
    key: \"roomType\",
    urlKeys: [\"roomType\"],
    serviceKeys: [\"roomType\"],
    active: (p) => Array.isArray(p.searchParams.roomType) && p.searchParams.roomType.length > 0,
    label: () => \"Allow any room type\",
  },
  {
    key: \"bedrooms\",
    urlKeys: [\"bedrooms\"],
    serviceKeys: [\"bedrooms\"],
    active: (p) => p.searchParams.bedrooms !== undefined,
    label: () => \"Remove the bedroom minimum\",
  },
  {
    key: \"keywords\",
    urlKeys: [\"keywords\"],
    serviceKeys: [\"keywords\"],
    active: (p) => typeof p.searchParams.keywords === \"string\" && p.searchParams.keywords !== \"\",
    label: (s) => `Remove the words \"${s.keywords}\"`,
  },
  {
    key: \"destination\",
    urlKeys: [\"dest\", \"radius\"],
    serviceKeys: [\"destination\"],
    active: (p) => destinationParts(p.searchParams.destination).length > 0,
    label: (s) => `Search everywhere instead of \"${s.dest}\"`,
  },
];

/** The filter the page would use without one group of filters. */
function filterWithout(parsed, group, takenIds) {
  const params = { ...parsed.searchParams };
  for (const key of group.serviceKeys) delete params[key];
  // With a radius the circle replaces the destination text (P06-T05); removing
  // the radius or the destination itself brings the plain search back.
  const keepArea = parsed.area && group.key !== \"radius\" && group.key !== \"destination\";
  if (keepArea) delete params.destination;
  const filter = { ...buildFilter(params), ...(keepArea ? parsed.area.condition : {}) };
  // Taken nights still exclude listings, unless the dates are what is dropped.
  if (group.key !== \"dates\" && takenIds.length > 0) filter._id = { $nin: takenIds };
  return filter;
}

/**
 * Popular destinations from the newest public listings: the cities with the most
 * stays. The link text is the city as a host wrote it; if searching for exactly
 * that text would not find the city's own key, the normalised key is used
 * instead, so a destination link can never lead to an empty page.
 * @returns {Promise<Array<{ label: string, dest: string, count: number }>>}
 */
async function popularDestinations(Listing, limit = MAX_DESTINATIONS) {
  const listings = await Listing.find(publicListingFilter())
    .select(\"cityKey address.city location\")
    .sort({ _id: -1 })
    .limit(SCAN_LIMIT)
    .lean();
  const groups = new Map();
  for (const listing of Array.isArray(listings) ? listings : []) {
    const key = listing && listing.cityKey;
    if (typeof key !== \"string\" || key === \"\") continue;
    const shown = String(
      (listing.address && listing.address.city) || listing.location || \"\",
    )
      .split(\",\")[0]
      .trim();
    const group = groups.get(key) || { key, label: shown, count: 0 };
    group.count += 1;
    if (!group.label && shown) group.label = shown;
    groups.set(key, group);
  }
  return [...groups.values()]
    .sort((a, b) => b.count - a.count || a.key.localeCompare(b.key))
    .slice(0, limit)
    .map((group) => {
      const parts = destinationParts(group.label);
      const safe = parts.length === 1 && parts[0] === normaliseToken(group.label) && group.key.startsWith(parts[0]);
      return {
        label: group.label && safe ? group.label : group.key,
        dest: safe ? group.label : group.key,
        count: group.count,
      };
    });
}

/**
 * @param {object} args
 * @param {object} args.Listing    the model
 * @param {object} args.parsed     the result of parseListingQuery
 * @param {Array}  [args.takenIds] listing ids with a taken night in the stay
 * @returns {Promise<{
 *   filterSuggestions: Array<{ key, label, count, url }>,
 *   destinations: Array<{ label, dest, count, url }>,
 *   hasAnyStays: boolean, queries: number }>}
 */
async function suggestForEmptyResults({ Listing, parsed, takenIds = [] }) {
  const looked = GROUPS.filter((group) => group.active(parsed)).slice(0, MAX_FILTER_COUNTS);

  const counts = await Promise.all(
    looked.map((group) => Listing.countDocuments(filterWithout(parsed, group, takenIds))),
  );
  const destinations = await popularDestinations(Listing);

  const state = { ...parsed.state };
  const filterSuggestions = looked
    .map((group, index) => ({ group, count: counts[index], index }))
    .filter(({ count }) => Number.isInteger(count) && count > 0) // never offer a dead end
    .sort((a, b) => b.count - a.count || a.index - b.index)
    .slice(0, MAX_FILTER_SUGGESTIONS)
    .map(({ group, count }) => ({
      key: group.key,
      label: group.label(state),
      count,
      url: listingsUrl(state, Object.fromEntries(group.urlKeys.map((k) => [k, undefined]))),
    }));

  return {
    filterSuggestions,
    destinations: destinations.map((d) => ({ ...d, url: listingsUrl({}, { dest: d.dest }) })),
    hasAnyStays: destinations.length > 0,
    queries: looked.length + 1,
  };
}

module.exports = {
  MAX_EXTRA_QUERIES,
  MAX_FILTER_COUNTS,
  MAX_FILTER_SUGGESTIONS,
  GROUPS,
  popularDestinations,
  suggestForEmptyResults,
};

// Sweeper (P07-T07): the housekeeping that keeps reservations, the night
// ledger and the listings tidy. One pass (`runOnce`) does four things, in this
// order, and a failure in one never stops the next:
//
//   1. expire    pending reservations whose hold ran out   (-> \"expired\", nights released)
//   2. complete  confirmed reservations whose check-out date has passed in the
//                listing's own time zone                     (-> \"completed\")
//   3. orphans   ledger rows whose reservation is missing or has released its
//                nights, and block rows with no block record (deleted)
//   4. drafts    listing drafts untouched for 90 days (src/services/drafts.js)
//   5. remind    (only when a `notifier` is given, P11-T04) tell the guest and
//                the host the day before check-in, once per reservation
//

// Safe on several instances at once. Steps 1 and 2 go through
// reservations.transition(), a compare-and-set: when two instances try the same
// reservation, one wins and the other gets a 409 that is counted as \"skipped\",
// not as an error. Step 3 deletes by row _id and re-running it deletes nothing;
// step 4 re-checks each draft in its own delete. Nothing here needs a lock.
//
// Why orphan rows get a grace period: booking inserts the ledger rows FIRST and
// the reservation (or block record) a moment later (ADR-004). A row without an
// owner is therefore normal for a few milliseconds. Only rows older than
// `orphanGraceMs` (default 10 minutes) are judged.
//
// The clock is injectable (`runOnce({ now })`), so tests move time instead of
// waiting. Application code makes dates from values only in src/utils/dates.js
// (tests/unit/noUserDate.test.js), hence `shift()` below.
const { AppError } = require(\"../utils/errors\");
const { DEFAULT_TIMEZONE, todayIn } = require(\"../utils/dates\");
const { holdsNights } = require(\"./stateMachine\");

const MINUTE_MS = 60 * 1000;
const HOUR_MS = 60 * MINUTE_MS;

const DEFAULTS = Object.freeze({
  batchSize: 200, // reservations handled per page
  maxBatches: 5, // pages per step per run (backlog continues next minute)
  orphanGraceMs: 10 * MINUTE_MS, // a ledger row must be this old to be judged
  orphanScanRows: 1000, // ledger rows examined per run (a rolling window)
  draftsEveryMs: HOUR_MS, // the draft clean-up runs at most this often
  draftDays: 90,
});

// The calendar is ahead of UTC by at most 14 hours (Pacific/Kiritimati). So no
// stay can be over anywhere while its check-out is after \"today\" there: that
// date narrows the database query, and the exact test is made per reservation
// in its own zone.
const LATEST_ZONE = \"Pacific/Kiritimati\";
// ...and behind UTC by at most 12 hours (Baker Island).
const EARLIEST_ZONE = \"Etc/GMT+12\";
const DAY_MS = 24 * HOUR_MS;

/** `now` moved by `ms`, without handing a value to the Date constructor. */
function shift(now, ms) {
  const moved = new Date();
  moved.setTime(now.getTime() + ms);
  return moved;
}

/** A 409 from a transition means another instance (or a user) got there first. */
const lostRace = (err) => err instanceof AppError && err.statusCode === 409;

const describeError = (err) =>
  err && err.message ? String(err.message) : String(err);

/**
 * @param {object} [deps] replaceable in unit tests; the defaults load the real
 *   models and services only when called, so requiring this file has no
 *   side effects
 */
function createSweeper({
  ReservationModel = require(\"../models/reservation\"),
  StayNightModel = require(\"../models/stayNight\"),
  AvailabilityBlockModel = require(\"../models/availabilityBlock\"),
  ListingModel = require(\"../models/listing\"),
  reservationService = require(\"./reservations\"),
  deleteStaleDrafts = require(\"./drafts\").deleteStaleDrafts,
  notifier = null, // `{ dispatch(event, ctx) }` (notificationEvents.js); none = no reminders
  destroyImage,
  logger,
  options = {},
} = {}) {
  const settings = { ...DEFAULTS, ...options };
  const log = logger || { info() {}, warn() {}, error() {} };
  const destroy =
    destroyImage ||
    ((publicId) => require(\"../config/cloudinary\").deleteImage(publicId, log));

  let orphanCursor = null; // where the next orphan scan resumes (per instance)
  let lastDraftRun = null; // when the draft clean-up last ran (per instance)

  /**
   * Walks the matching reservations in _id order, `batchSize` at a time, and
   * calls `handle` for each. Paging by _id (not by \"the first N that match\")
   * means a reservation that cannot be handled right now never hides the ones
   * behind it.
   */
  async function forEachReservation(filter, projection, handle) {
    let after = null;
    for (let page = 0; page < settings.maxBatches; page += 1) {
      const rows = await ReservationModel.find(
        after ? { ...filter, _id: { $gt: after } } : filter,
      )
        .sort({ _id: 1 })
        .limit(settings.batchSize)
        .select(projection)
        .lean();
      for (const row of rows) await handle(row);
      if (rows.length < settings.batchSize) return;
      after = rows[rows.length - 1]._id;
    }
  }

  async function expirePending(now, summary) {
    await forEachReservation(
      { status: \"pending\", holdExpiresAt: { $lt: now } },
      \"_id\",
      async (row) => {
        try {
          await reservationService.transition(row._id, \"expired\", {
            actor: \"system\",
            now,
            reason: \"The host did not answer before the request ran out.\",
          });
          summary.expired += 1;
        } catch (err) {
          if (lostRace(err)) summary.skipped += 1;
          else
            summary.errors.push({
              step: \"expire\",
              id: String(row._id),
              message: describeError(err),
            });
        }
      },
    );
  }

  async function completeStays(now, summary) {
    await forEachReservation(
      { status: \"confirmed\", checkOut: { $lte: todayIn(LATEST_ZONE, now) } },
      \"_id checkOut listingSnapshot.timezone\",
      async (row) => {
        const zone =
          (row.listingSnapshot && row.listingSnapshot.timezone) ||
          DEFAULT_TIMEZONE;
        try {
          // Still the last night in this zone: leave it for a later pass.
          if (row.checkOut.getTime() > todayIn(zone, now).getTime()) return;
          await reservationService.transition(row._id, \"completed\", {
            actor: \"system\",
            now,
            reason: \"The stay is over.\",
          });
          summary.completed += 1;
        } catch (err) {
          if (lostRace(err)) summary.skipped += 1;
          else
            summary.errors.push({
              step: \"complete\",
              id: String(row._id),
              message: describeError(err),
            });
        }
      },
    );
  }

  /**
   * \"Check-in tomorrow\" (P11-T04). A confirmed booking whose check-in is the
   * day after today IN THE LISTING'S OWN ZONE. Each one is claimed first with a
   * conditional update (`reminders.checkIn` not yet set), so two instances, or
   * the next pass, cannot send it twice; the price of that is that a failure
   * after the claim loses the reminder rather than repeating it.
   */
  async function remindCheckIns(now, summary) {
    if (!notifier) return;
    summary.reminded = summary.reminded || 0;
    await forEachReservation(
      {
        status: \"confirmed\",
        \"reminders.checkIn\": { $exists: false },
        // Tomorrow somewhere on Earth; the exact test is per reservation below.
        checkIn: {
          $gt: todayIn(EARLIEST_ZONE, now),
          $lte: shift(todayIn(LATEST_ZONE, now), DAY_MS),
        },
      },
      \"_id guest host listing checkIn checkOut nights guests listingSnapshot\",
      async (row) => {
        const zone =
          (row.listingSnapshot && row.listingSnapshot.timezone) ||
          DEFAULT_TIMEZONE;
        if (row.checkIn.getTime() !== shift(todayIn(zone, now), DAY_MS).getTime())
          return;
        try {
          const claim = await ReservationModel.updateOne(
            {
              _id: row._id,
              status: \"confirmed\",
              \"reminders.checkIn\": { $exists: false },
            },
            { $set: { \"reminders.checkIn\": now } },
          );
          if (!claim || claim.modifiedCount !== 1) {
            summary.skipped += 1; // another instance claimed it
            return;
          }
          await notifier.dispatch(\"reservation.checkin_tomorrow\", {
            reservation: row,
          });
          summary.reminded += 1;
        } catch (err) {
          summary.errors.push({
            step: \"remind\",
            id: String(row._id),
            message: describeError(err),
          });
        }
      },
    );
  }

  // Ids (as strings) of the sources that still own their ledger rows.
  async function liveSources(kind, ids) {
    if (ids.length === 0) return new Set();
    if (kind === \"block\") {
      const blocks = await AvailabilityBlockModel.find({ _id: { $in: ids } })
        .select(\"_id\")
        .lean();
      return new Set(blocks.map((b) => String(b._id)));
    }
    const reservations = await ReservationModel.find({ _id: { $in: ids } })
      .select(\"_id status\")
      .lean();
    return new Set(
      reservations
        .filter((r) => holdsNights(r.status))
        .map((r) => String(r._id)),
    );
  }

  async function removeOrphanNights(now, summary) {
    const cutoff = shift(now, -settings.orphanGraceMs);
    const rows = await StayNightModel.find(
      orphanCursor ? { _id: { $gt: orphanCursor } } : {},
    )
      .sort({ _id: 1 })
      .limit(settings.orphanScanRows)
      .select(\"_id source createdAt\")
      .lean();
    // A short page means the end of the collection: start over next time.
    orphanCursor =
      rows.length < settings.orphanScanRows ? null : rows[rows.length - 1]._id;

    // Too young to judge (its owner may still be being written).
    const old = rows.filter(
      (row) => !row.createdAt || row.createdAt.getTime() < cutoff.getTime(),
    );
    const idsByKind = { reservation: new Set(), block: new Set() };
    for (const row of old) {
      if (row.source && idsByKind[row.source.kind])
        idsByKind[row.source.kind].add(String(row.source.id));
    }

    const live = {};
    for (const kind of Object.keys(idsByKind)) {
      live[kind] = await liveSources(kind, [...idsByKind[kind]]);
    }

    const orphanRowIds = old
      .filter(
        (row) =>
          row.source &&
          live[row.source.kind] &&
          !live[row.source.kind].has(String(row.source.id)),
      )
      .map((row) => row._id);
    if (orphanRowIds.length === 0) return;

    const result = await StayNightModel.deleteMany({
      _id: { $in: orphanRowIds },
    });
    summary.orphanNights += (result && result.deletedCount) || 0;
  }

  async function removeStaleDrafts(now, summary, force) {
    if (
      !force &&
      lastDraftRun &&
      now.getTime() - lastDraftRun.getTime() < settings.draftsEveryMs
    )
      return;
    const result = await deleteStaleDrafts(ListingModel, {
      now,
      days: settings.draftDays,
      destroy,
    });
    lastDraftRun = now;
    summary.staleDrafts += (result && result.deleted) || 0;
  }

  /**
   * One pass. Never throws: problems are returned in `errors`.
   * @param {{ now?: Date, drafts?: boolean }} [run] `drafts: true` forces the
   *   draft clean-up even if it ran recently
   * @returns {Promise<{ at: Date, expired: number, completed: number,
   *   orphanNights: number, staleDrafts: number, skipped: number,
   *   errors: Array<{ step: string, id?: string, message: string }> }>}
   */
  async function runOnce({ now = new Date(), drafts = false } = {}) {
    const summary = {
      at: now,
      expired: 0,
      completed: 0,
      orphanNights: 0,
      staleDrafts: 0,
      skipped: 0,
      errors: [],
    };
    const steps = [
      [\"expire\", () => expirePending(now, summary)],
      [\"complete\", () => completeStays(now, summary)],
      [\"orphans\", () => removeOrphanNights(now, summary)],
      [\"drafts\", () => removeStaleDrafts(now, summary, drafts)],
      [\"remind\", () => remindCheckIns(now, summary)],
    ];
    for (const [name, step] of steps) {
      try {
        await step();
      } catch (err) {
        summary.errors.push({ step: name, message: describeError(err) });
      }
    }
    return summary;
  }

  return { runOnce };
}

/**
 * Runs `runOnce` now and then every `intervalMs`. A pass that is still running
 * when the next tick arrives makes that tick a no-op (no overlapping passes in
 * one process). The timer does not keep the process alive.
 * @returns {{ stop: () => void, tick: () => Promise<void> }}
 */
function startSweeper({
  runOnce,
  intervalMs = MINUTE_MS,
  logger,
  setIntervalFn = setInterval,
  clearIntervalFn = clearInterval,
}) {
  const log = logger || { info() {}, warn() {}, error() {} };
  let running = false;

  async function tick() {
    if (running) return;
    running = true;
    try {
      const s = await runOnce();
      const worked =
        s.expired + s.completed + s.orphanNights + s.staleDrafts + (s.reminded || 0);
      if (worked > 0) {
        log.info(
          {
            expired: s.expired,
            completed: s.completed,
            orphanNights: s.orphanNights,
            staleDrafts: s.staleDrafts,
            reminded: s.reminded || 0,
            skipped: s.skipped,
          },
          \"sweeper pass\",
        );
      }
      for (const problem of s.errors)
        log.error({ sweeper: problem }, \"sweeper step failed\");
    } catch (err) {
      log.error({ err }, \"sweeper pass crashed\");
    } finally {
      running = false;
    }
  }

  const timer = setIntervalFn(tick, intervalMs);
  if (timer && typeof timer.unref === \"function\") timer.unref();
  tick(); // catch up straight away after a restart
  return { stop: () => clearIntervalFn(timer), tick };
}

module.exports = { createSweeper, startSweeper, shift, DEFAULTS };

// Guest trips (P09-T01): the four tabs of /trips and the confirmation page of
// one booking. Reads only; moving a booking between statuses is
// services/reservations.js. Everything a view needs is worked out here, so the
// views only print.
//
// Tabs (a booking is in exactly one):
//   Upcoming   confirmed, check-out after today
//   Pending    waiting for the host, hold still running
//   Past       completed, or confirmed with check-out passed (the sweeper has
//              not marked it completed yet)
//   Cancelled  declined, expired, cancelled by either side, or a request whose
//              hold ran out and the sweeper has not expired yet
// \"Today\" is the date in the app's default time zone (Asia/Kolkata).
const {
  CANCELLATION_POLICIES,
  CANCELLATION_TERMS,
} = require(\"../config/constants\");
const {
  DEFAULT_TIMEZONE,
  todayIn,
  formatDateOnly,
  isAfter,
} = require(\"../utils/dates\");
const { windowEnd, DEFAULT_WINDOW_DAYS } = require(\"./reviews\");
const { RULE_TEXT } = require(\"../config/cancellation\");
const { cancelOffer } = require(\"./cancellations\");
const { modifiability } = require(\"./modifications\");

const TABS = Object.freeze([
  { key: \"upcoming\", label: \"Upcoming\" },
  { key: \"pending\", label: \"Pending\" },
  { key: \"past\", label: \"Past\" },
  { key: \"cancelled\", label: \"Cancelled\" },
]);
const TAB_KEYS = TABS.map((t) => t.key);
const PAGE_SIZE = 10;
const CLOSED = [
  \"declined\",
  \"expired\",
  \"cancelled_by_guest\",
  \"cancelled_by_host\",
];

const parseTab = (raw) =>
  typeof raw === \"string\" && TAB_KEYS.includes(raw) ? raw : \"upcoming\";

function parsePage(raw) {
  const n = typeof raw === \"string\" && /^\\d{1,6}$/.test(raw) ? Number(raw) : 1;
  return n >= 1 ? n : 1;
}

/** MongoDB filter and sort of one tab, for one guest. */
function tabQuery(tab, guestId, { now, today }) {
  const base = { guest: guestId };
  switch (tab) {
    case \"upcoming\":
      return {
        filter: { ...base, status: \"confirmed\", checkOut: { $gt: today } },
        sort: { checkIn: 1, _id: 1 },
      };
    case \"pending\":
      return {
        filter: { ...base, status: \"pending\", holdExpiresAt: { $gt: now } },
        sort: { holdExpiresAt: 1, _id: 1 },
      };
    case \"past\":
      return {
        filter: {
          ...base,
          $or: [
            { status: \"completed\" },
            { status: \"confirmed\", checkOut: { $lte: today } },
          ],
        },
        sort: { checkOut: -1, _id: -1 },
      };
    case \"cancelled\":
      return {
        filter: {
          ...base,
          $or: [
            { status: { $in: CLOSED } },
            { status: \"pending\", holdExpiresAt: { $lte: now } },
          ],
        },
        sort: { updatedAt: -1, _id: -1 },
      };
    default:
      throw new TypeError(`unknown tab: ${tab}`);
  }
}

/** The tab one booking belongs to (the same rules as tabQuery). */
function tabOf(reservation, { now = new Date() } = {}) {
  const today = todayIn(DEFAULT_TIMEZONE, now);
  const { status } = reservation;
  if (status === \"completed\") return \"past\";
  if (status === \"confirmed\")
    return reservation.checkOut > today ? \"upcoming\" : \"past\";
  if (status === \"pending\") {
    return reservation.holdExpiresAt && reservation.holdExpiresAt > now
      ? \"pending\"
      : \"cancelled\";
  }
  return \"cancelled\";
}

const STATUS_LABELS = {
  pending: { label: \"Waiting for the host\", tone: \"warning\" },
  confirmed: { label: \"Confirmed\", tone: \"success\" },
  completed: { label: \"Completed\", tone: \"secondary\" },
  declined: { label: \"Declined by the host\", tone: \"danger\" },
  expired: { label: \"Request expired\", tone: \"secondary\" },
  cancelled_by_host: { label: \"Cancelled by the host\", tone: \"danger\" },
};

function statusInfo(
  reservation,
  { viewerIsGuest = true, now = new Date() } = {},
) {
  if (reservation.status === \"cancelled_by_guest\") {
    return {
      label: viewerIsGuest ? \"Cancelled by you\" : \"Cancelled by the guest\",
      tone: \"secondary\",
    };
  }
  if (
    reservation.status === \"pending\" &&
    !(reservation.holdExpiresAt && reservation.holdExpiresAt > now)
  ) {
    return STATUS_LABELS.expired;
  }
  return (
    STATUS_LABELS[reservation.status] || {
      label: reservation.status,
      tone: \"secondary\",
    }
  );
}

const dateFormat = new Intl.DateTimeFormat(\"en-IN\", {
  day: \"numeric\",
  month: \"short\",
  year: \"numeric\",
  timeZone: \"UTC\",
});
const weekdayFormat = new Intl.DateTimeFormat(\"en-IN\", {
  weekday: \"short\",
  timeZone: \"UTC\",
});

/** \"12 Nov 2026\" from a date-only Date. */
const formatStayDate = (date) => dateFormat.format(date);
const formatStayWeekday = (date) => weekdayFormat.format(date);

function formatInstant(instant, timeZone = DEFAULT_TIMEZONE) {
  try {
    return new Intl.DateTimeFormat(\"en-IN\", {
      day: \"numeric\",
      month: \"short\",
      hour: \"numeric\",
      minute: \"2-digit\",
      hour12: true,
      timeZone,
    }).format(instant);
  } catch {
    return formatInstant(instant, DEFAULT_TIMEZONE);
  }
}

const plural = (n, one, many) => `${n} ${n === 1 ? one : many}`;

/** The words for one stored breakdown line (the snapshot keeps codes and numbers). */
function lineLabel(line, formatMoney, currency) {
  switch (line.code) {
    case \"nights\":
      return `${formatMoney(line.unitMinor, currency)} × ${plural(line.quantity, \"night\", \"nights\")}`;
    case \"weekend_nights\":
      return `${formatMoney(line.unitMinor, currency)} × ${plural(line.quantity, \"weekend night\", \"weekend nights\")}`;
    case \"season_nights\":
      return `${line.label ? line.label + \": \" : \"\"}${formatMoney(line.unitMinor, currency)} × ${plural(line.quantity, \"night\", \"nights\")}`;
    case \"season_weekend_nights\":
      return `${line.label ? line.label + \": \" : \"\"}${formatMoney(line.unitMinor, currency)} × ${plural(line.quantity, \"weekend night\", \"weekend nights\")}`;
    case \"length_discount\":
      return `${line.kind === \"monthly\" ? \"Monthly\" : \"Weekly\"} stay discount (${line.rateBps / 100}%)`;
    case \"cleaning\":
      return \"Cleaning fee\";
    case \"service_fee\":
      return \"Service fee\";
    case \"tax\":
      return line.included ? \"Taxes (included in the price)\" : \"Taxes\";
    default:
      return \"Other charges\";
  }
}

// A populated document, as opposed to a bare ObjectId or string id (an ObjectId
// has an `_id` getter in some driver versions, so `_id` alone proves nothing).
const isDocument = (value) =>
  Boolean(value) &&
  typeof value === \"object\" &&
  typeof value.toHexString !== \"function\";

/** What the booking page shows about reviewing: a form, the review, or why not. */
function describeReview(review) {
  const state = review && review.state ? review.state : \"none\";
  const out = {
    state,
    until: review && review.until ? formatStayDate(review.until) : null,
  };
  if (state === \"done\" && review.review) {
    out.rating = review.review.rating;
    out.comment = review.review.comment || \"\";
    out.legacy = Boolean(review.review.legacy);
    // Editing (P12-T03) and the host's reply, if there is one.
    out.id = review.review._id ? String(review.review._id) : \"\";
    out.editable = Boolean(review.editable);
    out.editUntil = review.editUntil ? formatStayDate(review.editUntil) : null;
    out.edited = Boolean(review.review.editedAt);
    out.reply =
      review.review.reply && review.review.reply.text
        ? String(review.review.reply.text)
        : \"\";
  }
  return out;
}

/** The note the host left when declining (status history), or \"\". */
function declineReasonOf(reservation) {
  if (reservation.status !== \"declined\") return \"\";
  const history = Array.isArray(reservation.statusHistory)
    ? reservation.statusHistory
    : [];
  const entry = [...history]
    .reverse()
    .find((h) => h && h.to === \"declined\" && h.note);
  return entry ? String(entry.note) : \"\";
}

/**
 * How a cancelled booking ended (P09-T03): who cancelled, the reason they gave
 * and the refund that was worked out (recorded, simulated: no money moves).
 */
function cancelledInfo(reservation, { formatMoney, currency }) {
  if (
    reservation.status !== \"cancelled_by_guest\" &&
    reservation.status !== \"cancelled_by_host\"
  )
    return null;
  const refund = reservation.refund;
  const hasRefund = refund && Number.isSafeInteger(refund.amountMinor);
  return {
    by: reservation.status === \"cancelled_by_host\" ? \"host\" : \"guest\",
    reason: reservation.cancelReason ? String(reservation.cancelReason) : \"\",
    refund: hasRefund
      ? {
          amountText: formatMoney(refund.amountMinor, currency),
          keptText: formatMoney(refund.retainedMinor || 0, currency),
          full: refund.amountMinor === refund.totalMinor,
          none: refund.amountMinor === 0,
          ruleText: RULE_TEXT[refund.rule] || \"\",
        }
      : null,
  };
}

const idText = (value) => String(value && value._id ? value._id : value);

/** A short code a guest and a host can quote: DIM-1A2B3C4D. */
const referenceOf = (reservation) =>
  `DIM-${idText(reservation._id).slice(-8).toUpperCase()}`;

function policyInfo(policy) {
  const found = CANCELLATION_POLICIES.find((p) => p.value === policy);
  if (!found) return null;
  return { label: found.label, terms: CANCELLATION_TERMS[policy] || \"\" };
}

/** One row of a tab. */
function describeRow(
  reservation,
  { now = new Date(), reviewed = false, windowDays = DEFAULT_WINDOW_DAYS } = {},
) {
  const snap = reservation.listingSnapshot || {};
  const info = statusInfo(reservation, { viewerIsGuest: true, now });
  const price = reservation.pricingSnapshot || {};
  return {
    id: idText(reservation._id),
    reference: referenceOf(reservation),
    listingTitle: snap.title || \"A place on Dimora\",
    city: snap.city || \"\",
    coverUrl: snap.coverUrl || \"\",
    checkIn: formatStayDate(reservation.checkIn),
    checkOut: formatStayDate(reservation.checkOut),
    nights: reservation.nights,
    guests: reservation.guests,
    statusLabel: info.label,
    tone: info.tone,
    totalMinor: Number.isSafeInteger(price.totalMinor)
      ? price.totalMinor
      : null,
    currency: price.currency || \"INR\",
    holdsUntil:
      reservation.status === \"pending\" && reservation.holdExpiresAt
        ? formatInstant(reservation.holdExpiresAt, snap.timezone)
        : null,
    reviewPrompt: reviewPromptOf(reservation, { now, reviewed, windowDays }),
  };
}

/** \"open\" = this stay can be reviewed now, \"done\" = it was, null = not applicable. */
function reviewPromptOf(reservation, { now, reviewed, windowDays }) {
  if (reservation.status !== \"completed\") return null;
  if (reviewed) return \"done\";
  const snap = reservation.listingSnapshot || {};
  const closed = isAfter(
    todayIn(snap.timezone || DEFAULT_TIMEZONE, now),
    windowEnd(reservation, windowDays),
  );
  return closed ? null : \"open\";
}

/**
 * One page of a guest's trips in one tab, with the count of every tab.
 * @param {{ ReservationModel?: object }} deps
 */
async function listTrips(
  {
    ReservationModel = require(\"../models/reservation\"),
    ReviewModel = require(\"../models/review\"),
  } = {},
  guestId,
  { tab, page, now = new Date(), windowDays = DEFAULT_WINDOW_DAYS } = {},
) {
  const key = parseTab(tab);
  const context = { now, today: todayIn(DEFAULT_TIMEZONE, now) };
  const queries = Object.fromEntries(
    TAB_KEYS.map((k) => [k, tabQuery(k, guestId, context)]),
  );
  const counts = await Promise.all(
    TAB_KEYS.map((k) => ReservationModel.countDocuments(queries[k].filter)),
  );
  const countOf = Object.fromEntries(TAB_KEYS.map((k, i) => [k, counts[i]]));
  const total = countOf[key];
  const totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE));
  const current = Math.min(parsePage(String(page)), totalPages);
  const rows =
    total === 0
      ? []
      : await ReservationModel.find(queries[key].filter)
          .sort(queries[key].sort)
          .skip((current - 1) * PAGE_SIZE)
          .limit(PAGE_SIZE)
          .lean();
  // Which finished stays on this page already have a review (one query).
  const finished = rows
    .filter((r) => r.status === \"completed\")
    .map((r) => r._id);
  const reviewed = new Set();
  if (finished.length > 0) {
    const found = await ReviewModel.find({ reservation: { $in: finished } })
      .select(\"reservation\")
      .lean();
    for (const review of found) reviewed.add(String(review.reservation));
  }
  return {
    tab: key,
    tabs: TABS.map((t) => ({ ...t, count: countOf[t.key] })),
    page: current,
    totalPages,
    total,
    items: rows.map((r) =>
      describeRow(r, {
        now,
        reviewed: reviewed.has(String(r._id)),
        windowDays,
      }),
    ),
  };
}

/**
 * The history of date changes (P09-T04), oldest first, in words: when, from
 * which dates to which, and what the price did. Shown to everyone who may see
 * the booking; it contains no contact details.
 */
function changesOf(reservation, { formatMoney, currency }) {
  const list = Array.isArray(reservation.modifications)
    ? reservation.modifications
    : [];
  const range = (stay) =>
    stay && stay.checkIn && stay.checkOut
      ? `${formatStayDate(stay.checkIn)} to ${formatStayDate(stay.checkOut)}`
      : \"\";
  return list.map((entry) => {
    const diff = Number.isSafeInteger(entry.differenceMinor)
      ? entry.differenceMinor
      : 0;
    const money = formatMoney(Math.abs(diff), entry.currency || currency);
    return {
      atText: entry.at ? formatInstant(entry.at, DEFAULT_TIMEZONE) : \"\",
      fromText: range(entry.from),
      toText: range(entry.to),
      differenceText:
        diff > 0
          ? `${money} more`
          : diff < 0
            ? `${money} less`
            : \"same price\",
      reapproval: Boolean(entry.reapproval),
    };
  });
}

/**
 * Everything the confirmation page shows.
 * `reservation` has `listing`, `host` and `guest` populated (any may be missing
 * if the document was deleted; the snapshots still carry the contract).
 * Who may see it is the caller's `can(\"reservation:view\")`.
 * What is shown only after confirmation (host contact, exact address) is
 * decided here, from the status, never by the view.
 * @param {object} reservation
 * @param {{ viewerRole: \"guest\"|\"host\"|\"admin\", formatMoney: Function, now?: Date,
 *           review?: { state: string, review?: object, until?: Date } }} options
 */
function describeTrip(
  reservation,
  { viewerRole, formatMoney, now = new Date(), review = { state: \"none\" } },
) {
  const snap = reservation.listingSnapshot || {};
  const price = reservation.pricingSnapshot || {};
  const currency = price.currency || \"INR\";
  const listing = isDocument(reservation.listing) ? reservation.listing : null;
  const host = isDocument(reservation.host) ? reservation.host : null;
  const guest = isDocument(reservation.guest) ? reservation.guest : null;
  const viewerIsGuest = viewerRole === \"guest\";
  const info = statusInfo(reservation, { viewerIsGuest, now });
  const revealed =
    reservation.status === \"confirmed\" || reservation.status === \"completed\";

  const lines = (price.lines || []).map((line) => ({
    label: lineLabel(line, formatMoney, currency),
    amount: formatMoney(line.amountMinor, currency),
    included: Boolean(line.included),
  }));

  let address = null;
  let mapUrl = null;
  if (revealed && listing) {
    const a = listing.address || {};
    const parts = [
      a.line1,
      a.city,
      [a.state, a.postalCode].filter(Boolean).join(\" \"),
      a.country,
    ].filter((p) => p && String(p).trim());
    address =
      parts.length > 0
        ? parts
        : listing.location
          ? [listing.location, listing.country].filter(Boolean)
          : null;
    const c = listing.geometry && listing.geometry.coordinates;
    if (Array.isArray(c) && c.length === 2 && c.every(Number.isFinite)) {
      mapUrl = `https://www.openstreetmap.org/?mlat=${c[1]}&mlon=${c[0]}#map=17/${c[1]}/${c[0]}`;
    }
  }

  const holdActive =
    reservation.status === \"pending\" &&
    reservation.holdExpiresAt &&
    reservation.holdExpiresAt > now;
  return {
    id: idText(reservation._id),
    reference: referenceOf(reservation),
    status: reservation.status,
    statusLabel: info.label,
    tone: info.tone,
    tab: tabOf(reservation, { now }),
    viewerRole,
    listing: {
      id: listing ? idText(listing) : null,
      title: snap.title || (listing && listing.title) || \"A place on Dimora\",
      city: snap.city || \"\",
      coverUrl: snap.coverUrl || \"\",
      url:
        listing && !listing.deletedAt ? `/listings/${idText(listing)}` : null,
    },
    checkIn: formatStayDate(reservation.checkIn),
    checkInWeekday: formatStayWeekday(reservation.checkIn),
    checkOut: formatStayDate(reservation.checkOut),
    checkOutWeekday: formatStayWeekday(reservation.checkOut),
    checkInIso: formatDateOnly(reservation.checkIn),
    checkOutIso: formatDateOnly(reservation.checkOut),
    checkInTime: snap.checkInTime || \"\",
    checkOutTime: snap.checkOutTime || \"\",
    nights: reservation.nights,
    guests: reservation.guests,
    lines,
    totalMinor: price.totalMinor,
    totalText: formatMoney(price.totalMinor, currency),
    avgPerNightText: Number.isSafeInteger(price.avgPerNightMinor)
      ? formatMoney(price.avgPerNightMinor, currency)
      : null,
    taxNote: price.taxIncluded ? \"Taxes are included in the price shown.\" : \"\",
    houseRules: snap.noSpecialRules ? \"\" : snap.houseRules || \"\",
    noSpecialRules: Boolean(snap.noSpecialRules) || !snap.houseRules,
    cancellation: policyInfo(snap.cancellationPolicy),
    instantBook: Boolean(snap.instantBook),
    holdsUntil: holdActive
      ? formatInstant(reservation.holdExpiresAt, snap.timezone)
      : null,
    // Shown only once the booking is confirmed (or done), and only to people who may see the booking.
    revealed,
    hostContact:
      revealed && viewerIsGuest && host
        ? {
            name: host.displayName || host.username,
            email: host.email || null,
            profileUrl: `/users/${idText(host)}`,
          }
        : null,
    guestName:
      !viewerIsGuest && guest ? guest.displayName || guest.username : null,
    address,
    mapUrl,
    declineReason: declineReasonOf(reservation),
    cancelled: cancelledInfo(reservation, { formatMoney, currency }),
    // The cancel button and what it would refund, for the guest only (the host
    // cancels from the booking requests page).
    cancel: viewerIsGuest
      ? cancelOffer(reservation, {
          actor: \"guest\",
          now,
          formatMoney,
          formatInstant,
        })
      : null,
    // \"Change dates\" for the guest while the booking can still move (P09-T04),
    // and the changes made so far for everyone who may see the booking.
    change:
      viewerIsGuest && modifiability(reservation, now).ok
        ? {
            url: `/trips/${idText(reservation._id)}/change`,
            reapproval: reservation.status === \"pending\",
          }
        : null,
    changes: changesOf(reservation, { formatMoney, currency }),
    review: describeReview(review),
    paymentSimulated: true,
  };
}

module.exports = {
  TABS,
  PAGE_SIZE,
  parseTab,
  parsePage,
  tabQuery,
  tabOf,
  statusInfo,
  describeRow,
  describeTrip,
  listTrips,
  lineLabel,
  referenceOf,
  formatStayDate,
  formatStayWeekday,
  formatInstant,
  reviewPromptOf,
  describeReview,
};

// Trust indicators (P12-T05): only facts the system actually knows, each with
// the meaning it really has. Shown on the public profile and in the host card
// of a listing.
//
//   emailConfirmed  the member opened a link sent to their address (P02-T05).
//                   It does NOT mean their identity was checked.
//   memberSince     month and year the account was created
//   staysHosted     reservations at their places that reached \"completed\"
//   response        of the booking REQUESTS (not instant bookings) of the last
//                   12 months that were decided, the share the host answered
//                   (accepted or declined) rather than let expire. Shown only
//                   with at least MIN_DECIDED decided requests; below that the
//                   page says nothing about it, never a percentage of 1 or 2.
//
// Deliberately absent: \"verified host\", \"superhost\", \"trusted\", star badges, a
// score. Dimora does no independent check of anybody, so none of those would be
// true. docs/TRUST.md lists the copy and the rules for adding an indicator.
const mongoose = require(\"mongoose\");

const MIN_DECIDED = 5;
const WINDOW_DAYS = 365;
const MAX_SCANNED = 500;

const monthYear = new Intl.DateTimeFormat(\"en-IN\", {
  month: \"long\",
  year: \"numeric\",
  timeZone: \"Asia/Kolkata\", // ADR-008
});
const formatMonthYear = (date) =>
  date instanceof Date && !Number.isNaN(date.getTime()) ? monthYear.format(date) : \"\";

/**
 * Counts, from the status history of booking requests, how many the host
 * answered and how many expired unanswered. A request that the guest withdrew,
 * or that is still waiting, is in neither. A booking that was never a request
 * (instant book: it starts as confirmed) has no \"from pending\" step.
 * @param {Array<{ statusHistory?: Array<{from?: string|null, to?: string, actor?: string}> }>} reservations
 */
function summariseRequests(reservations) {
  let answered = 0;
  let expired = 0;
  for (const reservation of reservations || []) {
    const step = ((reservation && reservation.statusHistory) || []).find((h) => h && h.from === \"pending\");
    if (!step) continue;
    if ((step.to === \"confirmed\" || step.to === \"declined\") && step.actor === \"host\") answered += 1;
    else if (step.to === \"expired\") expired += 1;
  }
  return { answered, expired };
}

/** { percent, basedOn } or null when there are too few decided requests to say anything. */
function responseFrom({ answered, expired }) {
  const decided = answered + expired;
  if (decided < MIN_DECIDED) return null;
  return { percent: Math.round((100 * answered) / decided), basedOn: decided };
}

const plural = (n, one, many) => `${n} ${n === 1 ? one : many}`;

/**
 * @param {{ emailConfirmed: boolean, memberSince: string, stats?: { staysHosted: number, answered: number, expired: number } | null }} input
 * @returns {{ items: {key: string, text: string}[], emailConfirmed: boolean, memberSince: string, staysHosted: number, response: object|null }}
 */
function buildTrust({ emailConfirmed, memberSince, stats = null }) {
  const staysHosted = stats && Number.isSafeInteger(stats.staysHosted) ? stats.staysHosted : 0;
  const response = stats ? responseFrom(stats) : null;
  const items = [];
  if (emailConfirmed) items.push({ key: \"email\", text: \"Email address confirmed\" });
  if (memberSince) items.push({ key: \"since\", text: `Member since ${memberSince}` });
  if (staysHosted > 0) items.push({ key: \"stays\", text: `${plural(staysHosted, \"stay\", \"stays\")} hosted` });
  if (response) {
    items.push({
      key: \"response\",
      text: `Answered ${response.percent}% of booking requests in the last 12 months (${plural(response.basedOn, \"request\", \"requests\")})`,
    });
  }
  return { items, emailConfirmed: Boolean(emailConfirmed), memberSince, staysHosted, response };
}

/**
 * Reads what the indicators need. `member` is a user document (or lean object)
 * that already has createdAt / emailVerifiedAt, or an id (the user is read).
 * Without a database connection the facts that live on the user are still
 * shown and the counted ones are left out.
 */
async function loadTrust(
  { User, Reservation },
  member,
  { now = new Date(), isReady = () => mongoose.connection.readyState === 1 } = {},
) {
  let user = member && typeof member === \"object\" && \"createdAt\" in member ? member : null;
  const id = member && member._id ? member._id : member;
  const ready = Boolean(isReady());
  if (!user) {
    if (!ready || !mongoose.isValidObjectId(id)) return null;
    user = await User.findById(id).select(\"createdAt emailVerifiedAt\").lean();
    if (!user) return null;
  }
  let stats = null;
  if (ready && Reservation && user._id) {
    const since = new Date(now.getTime() - WINDOW_DAYS * 24 * 60 * 60 * 1000);
    const [staysHosted, recent] = await Promise.all([
      Reservation.countDocuments({ host: user._id, status: \"completed\" }),
      Reservation.find({ host: user._id, createdAt: { $gte: since }, \"statusHistory.from\": \"pending\" })
        .sort({ createdAt: -1 })
        .limit(MAX_SCANNED)
        .select(\"statusHistory\")
        .lean(),
    ]);
    stats = { staysHosted, ...summariseRequests(recent) };
  }
  return buildTrust({
    emailConfirmed: Boolean(user.emailVerifiedAt),
    memberSince: formatMonthYear(user.createdAt),
    stats,
  });
}

module.exports = {
  MIN_DECIDED,
  WINDOW_DAYS,
  MAX_SCANNED,
  summariseRequests,
  responseFrom,
  buildTrust,
  loadTrust,
  formatMonthYear,
};

// User management for admins (P14-T02): search, activity summary, suspend and
// reinstate. The routes (src/routes/admin.js) call these inside
// auditedMutation, which writes the audit row; nothing here writes one.
//
// Suspending an account:
//   1. sets status \"suspended\" (atomically, only from \"active\");
//   2. hides its published listings (status \"suspended\", flagged so that
//      reinstating restores exactly those);
//   3. deletes the account's sessions from the session store;
//   4. reports how many pending / confirmed reservations there are to handle.
//      Reservations do not exist yet (P07-T05), so that count is 0 for now.
// Reinstating reverses 1 and 2.
const mongoose = require(\"mongoose\");
const User = require(\"../models/user\");
const Listing = require(\"../models/listing\");
const Review = require(\"../models/review\");
const AuditLog = require(\"../models/auditLog\");
const { toPageNumber } = require(\"./audit\");

const PAGE_SIZE = 20;
const REASON_MIN = 5;
const REASON_MAX = 500;
const QUERY_MAX = 100;
const LIST_FIELDS = \"username email displayName role status createdAt\";

class UserAdminError extends Error {
  /** @param {string} message user-safe text, shown to the admin */
  constructor(message) {
    super(message);
    this.name = \"UserAdminError\";
  }
}

function escapeRegex(text) {
  return text.replace(/[.*+?^${}()|[\\]\\\\]/g, \"\\\\$&\");
}

function isId(value) {
  return typeof value === \"string\" && mongoose.isValidObjectId(value);
}

/** The trimmed reason, or a UserAdminError when it is missing/too short/long. */
function cleanReason(value) {
  const reason = typeof value === \"string\" ? value.trim() : \"\";
  if (reason.length < REASON_MIN) {
    throw new UserAdminError(
      `Give a reason (at least ${REASON_MIN} characters). It is written to the audit log.`,
    );
  }
  if (reason.length > REASON_MAX) {
    throw new UserAdminError(`The reason must be ${REASON_MAX} characters or fewer.`);
  }
  return reason;
}

/**
 * Users matching a text (username, email or display name; case-insensitive,
 * matched as plain text, never as a pattern), optionally one status.
 * @returns {{rows: object[], page: number, totalPages: number, total: number, q: string, status: string}}
 */
async function searchUsers({ q, status, page } = {}) {
  const text = typeof q === \"string\" ? q.trim().slice(0, QUERY_MAX) : \"\";
  const filter = {};
  if (text) {
    const rx = new RegExp(escapeRegex(text), \"i\");
    filter.$or = [{ username: rx }, { email: rx }, { displayName: rx }];
  }
  const wanted = typeof status === \"string\" && User.STATUSES.includes(status) ? status : \"\";
  if (wanted) filter.status = wanted;

  const total = await User.countDocuments(filter);
  const totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE));
  const current = Math.min(toPageNumber(page), totalPages);
  const rows = await User.find(filter)
    .select(LIST_FIELDS)
    .sort({ username: 1, _id: 1 })
    .skip((current - 1) * PAGE_SIZE)
    .limit(PAGE_SIZE)
    .lean();
  return { rows, page: current, totalPages, total, q: text, status: wanted };
}

/**
 * One account with a small activity summary, or null for a malformed or
 * unknown id. Never includes the password hash or salt.
 */
async function getUserSummary(id) {
  if (!isId(id)) return null;
  const user = await User.findById(id).select(LIST_FIELDS).lean();
  if (!user) return null;

  const [byStatus, reviewsWritten, history] = await Promise.all([
    Listing.aggregate([
      { $match: { owner: user._id, deletedAt: null } },
      { $group: { _id: \"$status\", count: { $sum: 1 } } },
    ]),
    Review.countDocuments({ author: user._id }),
    AuditLog.find({ targetType: \"user\", targetId: user._id })
      .sort({ createdAt: -1, _id: -1 })
      .limit(10)
      .populate(\"actor\", \"username\")
      .lean(),
  ]);

  const listings = { draft: 0, published: 0, unpublished: 0, suspended: 0, total: 0 };
  for (const row of byStatus) {
    if (row._id in listings) listings[row._id] = row.count;
    listings.total += row.count;
  }
  return {
    user,
    activity: { listings, reviewsWritten },
    // Reservations arrive with P07-T05.
    reservations: { pending: 0, confirmed: 0 },
    history,
  };
}

/**
 * Deletes every session that belongs to `username` from the session store.
 * - connect-mongo: one deleteMany on the sessions collection (the session is
 *   stored as JSON text, so the passport user is matched in that text).
 * - express-session MemoryStore (tests, local use): walks all().
 * A store that supports neither is reported, never silently skipped.
 * @returns {Promise<number>} sessions deleted (-1 when the store reports no count)
 */
async function destroyUserSessions(store, username) {
  if (!store) throw new Error(\"destroyUserSessions: no session store\");

  if (store.collectionP && typeof store.collectionP.then === \"function\") {
    const collection = await store.collectionP;
    const needle = `\"passport\":{\"user\":${JSON.stringify(username)}`;
    const result = await collection.deleteMany({
      session: { $regex: escapeRegex(needle) },
    });
    return typeof result.deletedCount === \"number\" ? result.deletedCount : -1;
  }

  if (typeof store.all === \"function\" && typeof store.destroy === \"function\") {
    const sessions = await new Promise((resolve, reject) =>
      store.all((err, all) => (err ? reject(err) : resolve(all))),
    );
    if (sessions && !Array.isArray(sessions)) {
      let deleted = 0;
      for (const [sid, sess] of Object.entries(sessions)) {
        if (sess && sess.passport && sess.passport.user === username) {
          await new Promise((resolve, reject) =>
            store.destroy(sid, (err) => (err ? reject(err) : resolve())),
          );
          deleted += 1;
        }
      }
      return deleted;
    }
  }

  throw new Error(\"destroyUserSessions: this session store cannot delete by user\");
}

/**
 * @param {object} args
 * @param {object} args.admin the acting admin (req.user)
 * @param {string} args.id target user id
 * @param {string} args.reason required text
 * @param {object} args.store session store (req.sessionStore)
 * @returns {Promise<{user: object, details: object, reason: string}>}
 * @throws {UserAdminError} nothing was changed
 */
async function suspendUser({ admin, id, reason, store }) {
  const text = cleanReason(reason);
  if (!isId(id)) throw new UserAdminError(\"That account does not exist.\");
  const target = await User.findById(id).select(\"username role status\");
  if (!target) throw new UserAdminError(\"That account does not exist.\");

  if (String(target._id) === String(admin._id)) {
    throw new UserAdminError(\"You cannot suspend your own account.\");
  }
  if (target.status !== \"active\") {
    throw new UserAdminError(`That account is already ${target.status}.`);
  }
  if (target.role === \"admin\") {
    const admins = await User.countDocuments({ role: \"admin\", status: { $in: [\"active\", null] } });
    if (admins <= 1) throw new UserAdminError(\"You cannot suspend the last admin.\");
  }

  // Only an active account can become suspended; two admins acting at once
  // cannot both succeed.
  const res = await User.updateOne(
    { _id: target._id, status: \"active\" },
    { $set: { status: \"suspended\" } },
  );
  if (res.modifiedCount !== 1) {
    throw new UserAdminError(\"That account changed while you were working. Reload and try again.\");
  }

  const hidden = await Listing.updateMany(
    { owner: target._id, status: \"published\", deletedAt: null },
    { $set: { status: \"suspended\", hiddenByOwnerSuspension: true } },
  );
  const sessions = await destroyUserSessions(store, target.username);

  return {
    user: target,
    reason: text,
    details: {
      username: target.username,
      role: target.role,
      from: \"active\",
      to: \"suspended\",
      listingsHidden: hidden.modifiedCount,
      sessionsDeleted: sessions,
      // Reservations: none exist yet (P07-T05). When they do, pending ones are
      // declined here and confirmed ones are counted for admin handling.
      reservationsPendingDeclined: 0,
      reservationsConfirmedFlagged: 0,
    },
  };
}

/** Reverses suspendUser. A deleted account cannot be reinstated. */
async function reinstateUser({ id, reason }) {
  const text = cleanReason(reason);
  if (!isId(id)) throw new UserAdminError(\"That account does not exist.\");
  const target = await User.findById(id).select(\"username role status\");
  if (!target) throw new UserAdminError(\"That account does not exist.\");
  if (target.status !== \"suspended\") {
    throw new UserAdminError(\"Only a suspended account can be reinstated.\");
  }

  const res = await User.updateOne(
    { _id: target._id, status: \"suspended\" },
    { $set: { status: \"active\" } },
  );
  if (res.modifiedCount !== 1) {
    throw new UserAdminError(\"That account changed while you were working. Reload and try again.\");
  }
  const restored = await Listing.updateMany(
    { owner: target._id, status: \"suspended\", hiddenByOwnerSuspension: true, deletedAt: null },
    { $set: { status: \"published\" }, $unset: { hiddenByOwnerSuspension: \"\" } },
  );

  return {
    user: target,
    reason: text,
    details: {
      username: target.username,
      from: \"suspended\",
      to: \"active\",
      listingsRestored: restored.modifiedCount,
    },
  };
}

module.exports = {
  searchUsers,
  getUserSummary,
  suspendUser,
  reinstateUser,
  destroyUserSessions,
  cleanReason,
  UserAdminError,
  PAGE_SIZE,
  REASON_MIN,
  REASON_MAX,
};

// Named lists, moving stays between them and notes (P10-T02). Every function
// takes the signed-in member's id and only ever touches that member's own
// lists: a list id that is not theirs is a 404, the same as one that does not
// exist.
//
// The heart (setSaved, P10-T01) still saves into the default list; here the
// member organises what is saved. A stay may be in several lists; \"saved\" for
// ListingStat.saves means \"in at least one list\" is NOT tracked: the counter
// follows rows as in P10-T01, and moving a stay never changes it.
const { LIMITS, NAME_MAX, NOTE_MAX } = require(\"../config/wishlists\");
const {
  NotFoundError,
  ConflictError,
  ValidationError,
} = require(\"../utils/errors\");
const { ensureDefaultList } = require(\"./wishlists\");

const OBJECT_ID = /^[0-9a-f]{24}$/i;
// eslint-disable-next-line no-control-regex
const CONTROL = /[\\u0000-\\u001f\\u007f]/;

function models(deps = {}) {
  return {
    Wishlist: deps.Wishlist || require(\"../models/wishlist\"),
    WishlistItem: deps.WishlistItem || require(\"../models/wishlistItem\"),
  };
}

const isDuplicate = (err) => Boolean(err) && err.code === 11000;

/** A list name: one line, 1 to 60 characters, no control characters. */
function parseName(value) {
  const name = typeof value === \"string\" ? value.replace(/\\s+/g, \" \").trim() : \"\";
  if (!name) throw new ValidationError(\"Give the list a name.\");
  if (name.length > NAME_MAX) {
    throw new ValidationError(`A list name can have at most ${NAME_MAX} characters.`);
  }
  if (CONTROL.test(name)) throw new ValidationError(\"That name has characters that are not allowed.\");
  return name;
}

/** A note: plain text up to 300 characters; blank means \"remove the note\". */
function parseNote(value) {
  if (value === undefined || value === null) return \"\";
  if (typeof value !== \"string\") throw new ValidationError(\"A note must be text.\");
  const note = value.replace(/\\r\\n?/g, \"\\n\").trim();
  if (note.length > NOTE_MAX) {
    throw new ValidationError(`A note can have at most ${NOTE_MAX} characters.`);
  }
  // eslint-disable-next-line no-control-regex
  if (/[\\u0000-\\u0009\\u000b-\\u001f\\u007f]/.test(note)) {
    throw new ValidationError(\"That note has characters that are not allowed.\");
  }
  return note;
}

async function ownedList(userId, listId, deps) {
  const { Wishlist } = models(deps);
  const list = OBJECT_ID.test(String(listId))
    ? await Wishlist.findOne({ _id: listId, owner: userId }).lean()
    : null;
  if (!list) throw new NotFoundError(\"That list does not exist.\");
  return list;
}

const duplicateName = () =>
  new ConflictError(\"You already have a list with that name.\", { code: \"name_taken\" });

/** @returns {Promise<{ id: string, name: string }>} */
async function createList(userId, name, deps) {
  const { Wishlist } = models(deps);
  const clean = parseName(name);
  const count = await Wishlist.countDocuments({ owner: userId });
  if (count >= LIMITS.maxLists) {
    throw new ConflictError(`You can have at most ${LIMITS.maxLists} lists. Delete one to make another.`, {
      code: \"too_many_lists\",
    });
  }
  try {
    const list = await Wishlist.create({ owner: userId, name: clean, isDefault: false });
    return { id: String(list._id), name: list.name };
  } catch (err) {
    if (isDuplicate(err)) throw duplicateName();
    throw err;
  }
}

async function renameList(userId, listId, name, deps) {
  const { Wishlist } = models(deps);
  const list = await ownedList(userId, listId, deps);
  const clean = parseName(name);
  try {
    await Wishlist.updateOne({ _id: list._id, owner: userId }, { $set: { name: clean } });
  } catch (err) {
    if (isDuplicate(err)) throw duplicateName();
    throw err;
  }
  return { id: String(list._id), name: clean };
}

/**
 * Deletes a list. The stays in it are not lost: they move to the default list
 * (a stay already there is simply not repeated; notes travel with them). The
 * default list itself cannot be deleted. If the default list could not hold
 * them all (100 stays), nothing is deleted.
 * @returns {Promise<{ moved: number }>}
 */
async function deleteList(userId, listId, deps) {
  const { Wishlist, WishlistItem } = models(deps);
  const list = await ownedList(userId, listId, deps);
  if (list.isDefault) {
    throw new ConflictError(\"Your main list cannot be deleted.\", { code: \"default_list\" });
  }
  const target = await ensureDefaultList(userId, deps);
  const rows = await WishlistItem.find({ wishlist: list._id }).lean();
  const there = new Set(
    (await WishlistItem.find({ wishlist: target._id }).select(\"listing\").lean()).map((r) => String(r.listing)),
  );
  const toMove = rows.filter((row) => !there.has(String(row.listing)));
  if (there.size + toMove.length > LIMITS.maxItems) {
    throw new ConflictError(
      `Your main list would hold more than ${LIMITS.maxItems} stays. Remove some first.`,
      { code: \"target_full\" },
    );
  }
  for (const row of toMove) {
    try {
      await WishlistItem.updateOne({ _id: row._id }, { $set: { wishlist: target._id } });
    } catch (err) {
      if (!isDuplicate(err)) throw err; // it got there meanwhile: the row below is removed with the list
    }
  }
  await WishlistItem.deleteMany({ wishlist: list._id });
  await Wishlist.deleteOne({ _id: list._id, owner: userId, isDefault: false });
  return { moved: toMove.length };
}

/**
 * Moves one stay from one of the member's lists to another. If the target
 * already has it the stay is only taken out of the source.
 * @returns {Promise<{ moved: boolean }>}
 */
async function moveItem(userId, { from, to, listingId }, deps) {
  const { WishlistItem } = models(deps);
  if (!OBJECT_ID.test(String(listingId))) throw new NotFoundError(\"That stay is not in this list.\");
  const source = await ownedList(userId, from, deps);
  const target = await ownedList(userId, to, deps);
  if (String(source._id) === String(target._id)) {
    throw new ValidationError(\"Choose a different list to move it to.\");
  }
  const row = await WishlistItem.findOne({ wishlist: source._id, listing: listingId, owner: userId }).lean();
  if (!row) throw new NotFoundError(\"That stay is not in this list.\");
  const already = await WishlistItem.findOne({ wishlist: target._id, listing: listingId }).lean();
  if (already) {
    await WishlistItem.deleteOne({ _id: row._id });
    return { moved: true };
  }
  const count = await WishlistItem.countDocuments({ wishlist: target._id });
  if (count >= LIMITS.maxItems) {
    throw new ConflictError(`That list is full (${LIMITS.maxItems} stays).`, { code: \"target_full\" });
  }
  try {
    await WishlistItem.updateOne({ _id: row._id }, { $set: { wishlist: target._id } });
  } catch (err) {
    if (!isDuplicate(err)) throw err;
    await WishlistItem.deleteOne({ _id: row._id }); // a twin request put it there first
  }
  return { moved: true };
}

/** Sets (or, when blank, removes) the member's note on a stay in one of their lists. */
async function setNote(userId, { listId, listingId, note }, deps) {
  const { WishlistItem } = models(deps);
  if (!OBJECT_ID.test(String(listingId))) throw new NotFoundError(\"That stay is not in this list.\");
  const list = await ownedList(userId, listId, deps);
  const clean = parseNote(note);
  const result = await WishlistItem.updateOne(
    { wishlist: list._id, listing: listingId, owner: userId },
    clean ? { $set: { note: clean } } : { $unset: { note: 1 } },
  );
  const matched = result.matchedCount !== undefined ? result.matchedCount : result.n;
  if (!matched) throw new NotFoundError(\"That stay is not in this list.\");
  return { note: clean };
}

module.exports = {
  createList,
  renameList,
  deleteList,
  moveItem,
  setNote,
  parseName,
  parseNote,
};

// Saving stays to a member's wishlist (P10-T01).
//
// setSaved(...) says what the final state should be (\"saved\" or \"not saved\"),
// not \"flip it\", so a double click or a retried request cannot undo itself.
// `ListingStat.saves` follows the rows: +1 only when a row was really created,
// -n only for the n rows really deleted.
const { LIMITS, DEFAULT_NAME } = require(\"../config/wishlists\");
const { toCardItem } = require(\"../utils/listingCard\");
const {
  NotFoundError,
  ConflictError,
  ValidationError,
} = require(\"../utils/errors\");

const OBJECT_ID = /^[0-9a-f]{24}$/i;

// Models are looked up on first use so a test can pass fakes through `deps`.
function models(deps = {}) {
  return {
    Wishlist: deps.Wishlist || require(\"../models/wishlist\"),
    WishlistItem: deps.WishlistItem || require(\"../models/wishlistItem\"),
    ListingStat: deps.ListingStat || require(\"../models/listingStat\"),
    stats: deps.stats || require(\"./listingStats\"),
    Listing: deps.Listing || require(\"../models/listing\"),
    now: deps.now || (() => new Date()),
  };
}

const isPublic = (listing) =>
  Boolean(listing) && listing.status === \"published\" && !listing.deletedAt;

/** The member's default list, created on first use. */
async function ensureDefaultList(userId, deps) {
  const { Wishlist } = models(deps);
  const find = () => Wishlist.findOne({ owner: userId, isDefault: true }).lean();
  const existing = await find();
  if (existing) return existing;
  try {
    return await Wishlist.findOneAndUpdate(
      { owner: userId, isDefault: true },
      {
        $setOnInsert: { owner: userId, name: DEFAULT_NAME, isDefault: true },
      },
      { upsert: true, new: true },
    ).lean();
  } catch (err) {
    // Two requests created it at once: the unique index let one win.
    if (err && err.code === 11000) return find();
    throw err;
  }
}

/**
 * Makes the stay saved (`saved` true) or not saved (false) for this member.
 * @returns {Promise<{ saved: boolean, changed: boolean }>}
 */
async function setSaved(userId, listingId, saved, deps) {
  const { WishlistItem, ListingStat, Listing, stats, now } = models(deps);
  if (typeof saved !== \"boolean\") {
    throw new ValidationError(\"Say whether to save or to remove this stay.\");
  }
  if (!OBJECT_ID.test(String(listingId))) {
    throw new NotFoundError(\"That stay does not exist.\");
  }

  if (!saved) {
    // Removing is always allowed, also for a stay that is no longer public.
    const result = await WishlistItem.deleteMany({
      owner: userId,
      listing: listingId,
    });
    const removed = result.deletedCount || 0;
    if (removed > 0) {
      await ListingStat.updateOne(
        { listing: listingId },
        { $inc: { saves: -removed } },
        { upsert: true },
      );
      await stats.clampSaves(listingId); // never below zero (P13-T03)
    }
    return { saved: false, changed: removed > 0 };
  }

  const listing = await Listing.findById(listingId)
    .select(\"status deletedAt\")
    .lean();
  if (!isPublic(listing)) {
    throw new NotFoundError(\"That stay is not available.\");
  }

  const list = await ensureDefaultList(userId, deps);
  const already = await WishlistItem.findOne({
    wishlist: list._id,
    listing: listingId,
  }).lean();
  if (already) return { saved: true, changed: false };

  // Not exact under a burst of parallel requests (two can both see 99); the
  // overshoot is bounded by the number of simultaneous requests.
  const count = await WishlistItem.countDocuments({ wishlist: list._id });
  if (count >= LIMITS.maxItems) {
    throw new ConflictError(
      `Your saved list is full (${LIMITS.maxItems} stays). Remove one to save another.`,
    );
  }

  const result = await WishlistItem.updateOne(
    { wishlist: list._id, listing: listingId },
    {
      $setOnInsert: {
        wishlist: list._id,
        owner: userId,
        listing: listingId,
        createdAt: now(),
      },
    },
    { upsert: true },
  );
  const created = (result.upsertedCount || 0) > 0;
  if (created) {
    await ListingStat.updateOne(
      { listing: listingId },
      { $inc: { saves: 1 } },
      { upsert: true },
    );
    await stats.recordSave(listingId); // daily count for the host (P13-T03)
  }
  return { saved: true, changed: created };
}

/** ids (as strings) of every stay this member has saved, for the heart state. */
async function savedIdsFor(userId, deps) {
  if (!userId) return new Set();
  const { WishlistItem } = models(deps);
  const rows = await WishlistItem.find({ owner: userId })
    .select(\"listing\")
    .limit(LIMITS.maxLists * LIMITS.maxItems)
    .lean();
  return new Set(rows.map((row) => String(row.listing)));
}

/**
 * The saved-stays page: newest first. A stay that is no longer public (hidden,
 * deleted, suspended) stays in the list as \"no longer available\" so the member
 * sees what happened and can remove it; it is never dropped silently.
 */
async function overview(userId, deps, { listId } = {}) {
  const { WishlistItem, Listing } = models(deps);
  // Without `listId`: every stay the member saved, each once. With it: the
  // stays of that one list (the caller has checked the list is theirs).
  const filter = listId ? { owner: userId, wishlist: listId } : { owner: userId };
  const found = await WishlistItem.find(filter)
    .sort({ createdAt: -1 })
    .limit(LIMITS.maxLists * LIMITS.maxItems)
    .lean();
  const seen = new Set();
  const rows = found.filter((row) => {
    const key = String(row.listing);
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
  const listings = rows.length
    ? await Listing.find({ _id: { $in: rows.map((row) => row.listing) } })
        .select(\"title image location country pricing status deletedAt\")
        .lean()
    : [];
  const byId = new Map(listings.map((l) => [String(l._id), l]));
  const items = rows.map((row) => {
    const listing = byId.get(String(row.listing));
    const available = isPublic(listing);
    return {
      id: String(row.listing),
      available,
      title: (listing && listing.title) || \"A stay that was removed\",
      savedAt: row.createdAt,
      note: row.note || \"\",
      card: available ? toCardItem(listing) : null,
    };
  });
  return {
    items,
    availableCount: items.filter((i) => i.available).length,
    limit: LIMITS.maxItems,
  };
}

/**
 * The member's lists with how many stays each holds, the default one first
 * (P10-T02). A member who never saved anything has none yet.
 * @returns {Promise<Array<{ id: string, name: string, isDefault: boolean, count: number }>>}
 */
async function listsFor(userId, deps) {
  const { Wishlist, WishlistItem } = models(deps);
  const lists = await Wishlist.find({ owner: userId })
    .sort({ isDefault: -1, name: 1 })
    .limit(LIMITS.maxLists)
    .lean();
  if (lists.length === 0) return [];
  const rows = await WishlistItem.find({ owner: userId })
    .select(\"wishlist\")
    .limit(LIMITS.maxLists * LIMITS.maxItems)
    .lean();
  const counts = new Map();
  for (const row of rows) {
    const key = String(row.wishlist);
    counts.set(key, (counts.get(key) || 0) + 1);
  }
  return lists.map((list) => ({
    id: String(list._id),
    name: list.name,
    isDefault: Boolean(list.isDefault),
    count: counts.get(String(list._id)) || 0,
    shareToken: list.shareToken || null, // for the owner's own page (P10-T04)
  }));
}

module.exports = {
  listsFor,
  setSaved,
  savedIdsFor,
  overview,
  ensureDefaultList,
  isPublic,
};

// The listing wizard (P04-T02): the six steps, how a draft's stored data maps to
// each step's form, and which steps are finished.
//
// A step is finished when the host has saved it (listing.wizardSteps) AND what
// is stored for it still passes that step's validation, so removing the last
// photo, say, makes the photos step unfinished again. Steps 1-5 collect data;
// step 6 is the review. You can open step N only when steps 1..N-1 are finished.
const { validateStep } = require(\"../validation/wizard\");
const { galleryOf } = require(\"./images\");
const { rupeesToMinor, minorToRupees } = require(\"../utils/listingFields\");
const { seasonFormValues } = require(\"../utils/priceRules\");

const STEPS = Object.freeze([
  { n: 1, key: \"basics\", title: \"The basics\" },
  { n: 2, key: \"location\", title: \"Location\" },
  { n: 3, key: \"details\", title: \"Rooms and amenities\" },
  { n: 4, key: \"photos\", title: \"Photos\" },
  { n: 5, key: \"pricing\", title: \"Price and rules\" },
  { n: 6, key: \"review\", title: \"Review and publish\" },
]);
const DATA_STEPS = [1, 2, 3, 5];
const LAST_DATA_STEP = 5;
const REVIEW_STEP = 6;

const stepByNumber = (n) => STEPS.find((step) => step.n === n);

/** \"1\"..\"6\" (as in a URL) -> 1..6, or null for anything else. */
function parseStep(value) {
  return /^[1-6]$/.test(String(value)) ? Number(value) : null;
}

const get = (listing, path, fallback = \"\") => {
  const value = listing.get ? listing.get(path) : undefined;
  return value === undefined || value === null ? fallback : value;
};

/** The form values for a step, from what is stored. */
function formValues(listing, n) {
  switch (n) {
    case 1:
      return {
        title: get(listing, \"title\"),
        description: get(listing, \"description\"),
        propertyType: get(listing, \"propertyType\"),
        roomType: get(listing, \"roomType\"),
        vibe: get(listing, \"vibe\"),
      };
    case 2:
      return {
        line1: get(listing, \"address.line1\"),
        city: get(listing, \"address.city\"),
        state: get(listing, \"address.state\"),
        country: get(listing, \"address.country\"),
        postalCode: get(listing, \"address.postalCode\"),
      };
    case 3:
      return {
        guests: get(listing, \"capacity.guests\"),
        bedrooms: get(listing, \"capacity.bedrooms\"),
        beds: get(listing, \"capacity.beds\"),
        bathrooms: get(listing, \"capacity.bathrooms\"),
        amenities: [...(listing.amenities || [])],
        accessibility: [...(listing.accessibility || [])],
      };
    case 5: {
      const nightlyMinor = listing.get(\"pricing.nightlyMinor\");
      const nightly = minorToRupees(nightlyMinor);
      const cleaning = minorToRupees(listing.get(\"pricing.cleaningFeeMinor\"));
      return {
        price: nightly === null ? \"\" : nightly,
        cleaningFee: cleaning === null ? 0 : cleaning,
        minNights: get(listing, \"minNights\"),
        maxNights: get(listing, \"maxNights\"),
        advanceNoticeHours: get(listing, \"advanceNoticeHours\"),
        sameDayCutoffTime: get(listing, \"sameDayCutoffTime\"),
        checkInTime: get(listing, \"checkInTime\"),
        checkOutTime: get(listing, \"checkOutTime\"),
        cancellationPolicy: get(listing, \"cancellationPolicy\"),
        instantBook: Boolean(listing.instantBook),
        houseRules: get(listing, \"houseRules\"),
        noSpecialRules: Boolean(listing.noSpecialRules),
        ...priceRuleValues(listing, nightlyMinor),
      };
    }
    default:
      return {};
  }
}

/** The price-rule form values (P08-T04). An older absolute weekend price shows as its percentage. */
function priceRuleValues(listing, nightlyMinor) {
  const bps = listing.get(\"pricing.weekendBps\");
  const absolute = listing.get(\"pricing.weekendNightlyMinor\");
  let weekendPercent = 0;
  if (Number.isInteger(bps)) weekendPercent = Math.round(bps / 100);
  else if (Number.isInteger(absolute) && Number.isInteger(nightlyMinor) && nightlyMinor > 0 && absolute > nightlyMinor) {
    weekendPercent = Math.min(100, Math.round(((absolute - nightlyMinor) / nightlyMinor) * 100));
  }
  const weekly = listing.get(\"pricing.discounts.weeklyBps\");
  const monthly = listing.get(\"pricing.discounts.monthlyBps\");
  return {
    weekendPercent,
    weeklyDiscountPercent: Number.isInteger(weekly) ? Math.round(weekly / 100) : 0,
    monthlyDiscountPercent: Number.isInteger(monthly) ? Math.round(monthly / 100) : 0,
    ...seasonFormValues(listing.get(\"pricing.seasonalRates\")),
  };
}

const hasPoint = (listing) => {
  const coordinates = listing.get(\"geometry.coordinates\");
  return Array.isArray(coordinates) && coordinates.length === 2;
};

function isStepComplete(listing, n) {
  if (n === REVIEW_STEP) {
    return DATA_STEPS.concat(4).every((step) => isStepComplete(listing, step));
  }
  if (!(listing.wizardSteps || []).includes(n)) return false;
  if (n === 4) return galleryOf(listing).length >= 1;
  if (n === 2 && !hasPoint(listing)) return false;
  return (
    Object.keys(validateStep(n, formValues(listing, n)).errors).length === 0
  );
}

/** The steps for the stepper: { n, key, title, complete, reachable }. */
function stepStatuses(listing) {
  let blocked = false;
  return STEPS.map((step) => {
    const complete = isStepComplete(listing, step.n);
    const reachable = !blocked;
    if (!complete) blocked = true;
    return { ...step, complete, reachable };
  });
}

/** The step the host should open next: the first unfinished one, else the review. */
function firstIncompleteStep(listing) {
  for (let n = 1; n <= LAST_DATA_STEP; n += 1) {
    if (!isStepComplete(listing, n)) return n;
  }
  return REVIEW_STEP;
}

function canOpenStep(listing, n) {
  for (let earlier = 1; earlier < n; earlier += 1) {
    if (!isStepComplete(listing, earlier)) return false;
  }
  return true;
}

function markStepDone(listing, n) {
  const done = new Set(listing.wizardSteps || []);
  done.add(n);
  listing.wizardSteps = [...done].sort((a, b) => a - b);
}

/**
 * Copies a validated step's values onto the listing (does not save).
 * `geometry` is the looked-up point for step 2.
 */
function applyStep(listing, n, value, { geometry } = {}) {
  switch (n) {
    case 1:
      listing.set({
        title: value.title,
        description: value.description,
        propertyType: value.propertyType,
        roomType: value.roomType,
        // An empty choice clears the setting.
        vibe: value.vibe || undefined,
      });
      break;
    case 2:
      listing.set({
        address: {
          line1: value.line1,
          city: value.city,
          state: value.state || undefined,
          country: value.country,
          postalCode: value.postalCode || undefined,
        },
        // The older pages still show these two text fields: city and state only,
        // never the street address.
        location: [value.city, value.state].filter(Boolean).join(\", \"),
        country: value.country,
        needsReview: false,
      });
      if (geometry) listing.set(\"geometry\", geometry);
      break;
    case 3:
      listing.set({
        \"capacity.guests\": value.guests,
        \"capacity.bedrooms\": value.bedrooms,
        \"capacity.beds\": value.beds,
        \"capacity.bathrooms\": value.bathrooms,
        amenities: value.amenities,
        accessibility: value.accessibility,
      });
      break;
    case 5:
      listing.set({
        \"pricing.nightlyMinor\": rupeesToMinor(value.price),
        \"pricing.cleaningFeeMinor\": rupeesToMinor(value.cleaningFee) ?? 0,
        \"pricing.currency\": \"INR\",
        // Price rules (P08-T04). An older absolute weekend price is replaced by
        // the percentage the form showed for it.
        \"pricing.weekendBps\": value.weekendPercent > 0 ? value.weekendPercent * 100 : undefined,
        \"pricing.weekendNightlyMinor\": undefined,
        \"pricing.discounts.weeklyBps\": value.weeklyDiscountPercent > 0 ? value.weeklyDiscountPercent * 100 : undefined,
        \"pricing.discounts.monthlyBps\": value.monthlyDiscountPercent > 0 ? value.monthlyDiscountPercent * 100 : undefined,
        \"pricing.seasonalRates\": value.seasons && value.seasons.length > 0 ? value.seasons : undefined,
        minNights: value.minNights,
        maxNights: value.maxNights,
        advanceNoticeHours: value.advanceNoticeHours,
        sameDayCutoffTime: value.sameDayCutoffTime,
        checkInTime: value.checkInTime,
        checkOutTime: value.checkOutTime,
        cancellationPolicy: value.cancellationPolicy,
        instantBook: value.instantBook,
        houseRules: value.houseRules || undefined,
        // written rules replace the \"none\" confirmation
        noSpecialRules: value.houseRules ? false : value.noSpecialRules,
      });
      break;
    default:
      throw new Error(`Step ${n} has no data to apply`);
  }
}

/** The text sent to the geocoder (the whole address) for step 2 values. */
function addressQuery(value) {
  return [value.line1, value.city, value.state, value.postalCode]
    .filter(Boolean)
    .join(\", \");
}

/** True when the stored address differs from the submitted one (or has no point). */
function addressChanged(listing, value) {
  const now = formValues(listing, 2);
  return (
    !hasPoint(listing) ||
    [\"line1\", \"city\", \"state\", \"country\", \"postalCode\"].some(
      (key) =>
        String(now[key] ?? \"\").trim() !== String(value[key] ?? \"\").trim(),
    )
  );
}

module.exports = {
  STEPS,
  DATA_STEPS,
  LAST_DATA_STEP,
  REVIEW_STEP,
  stepByNumber,
  parseStep,
  formValues,
  isStepComplete,
  stepStatuses,
  firstIncompleteStep,
  canOpenStep,
  markStepDone,
  applyStep,
  addressQuery,
  addressChanged,
};

// Accessibility features for the listing page (P15-T05): stored keys to labels.
// The host declares them and Dimora has not checked them; keys that are not in
// the shared list (old data, a typo) are dropped, never shown raw, and each
// feature appears once, in the list's own order.
const { ACCESSIBILITY_FEATURES } = require(\"../config/constants\");

/** Labels of the declared features, in a fixed order. */
function accessibilityLabels(keys) {
  const chosen = new Set(Array.isArray(keys) ? keys : []);
  return ACCESSIBILITY_FEATURES.filter((item) => chosen.has(item.value)).map(
    (item) => item.label,
  );
}

module.exports = { accessibilityLabels };

// Amenities for the listing page (P04-T07): the stored keys, grouped and
// labelled. Keys that are not in the shared list (old data, a typo) are
// dropped, never shown raw, and each amenity appears once.
const { AMENITIES, AMENITY_GROUPS } = require(\"../config/constants\");

const BY_VALUE = new Map(AMENITIES.map((item) => [item.value, item]));

/** [{ group, items: [label] }] in a fixed group order; empty groups left out. */
function groupAmenities(keys) {
  const chosen = new Set(Array.isArray(keys) ? keys : []);
  return AMENITY_GROUPS.map((group) => ({
    group,
    items: AMENITIES.filter(
      (item) => item.group === group && chosen.has(item.value),
    ).map((item) => item.label),
  })).filter((entry) => entry.items.length > 0);
}

/** The label for one stored value, or null if it is not a known amenity. */
const amenityLabel = (value) => (BY_VALUE.get(value) || {}).label ?? null;

module.exports = { groupAmenities, amenityLabel };

// The map box of a search (P06-T04): ?bbox=west,south,east,north in degrees,
// the order Mapbox GL's map.getBounds().toArray() gives them.
//
// Only four plain numbers are accepted; anything else is refused with a
// message, so nothing but numbers ever reaches a database query.
//
// The box is turned into one or two longitude/latitude boxes:
//   * a box 360 degrees wide or wider (zoomed right out, Mapbox can report
//     -250 .. 250) covers every longitude;
//   * a box that crosses the antimeridian (170 .. -170, or 170 .. 190) is two
//     boxes, 170 .. 180 and -180 .. -170.
const MAX_LNG_ABS = 720; // far more than any real map reports
const WORLD_WIDTH = 360;

// Longitudes already inside [-180, 180] are returned untouched (the arithmetic
// below would add rounding noise to them); only outside values are wrapped.
function wrapLng(lng) {
  if (lng >= -180 && lng <= 180) return lng;
  return ((((lng + 180) % 360) + 360) % 360) - 180;
}

/**
 * @param {unknown} value the raw query value
 * @returns {{ ok: true, boxes: Array<{west:number,south:number,east:number,north:number}> }
 *   | { ok: false, message: string }}
 */
function parseBbox(value) {
  if (typeof value !== \"string\") {
    return { ok: false, message: \"bbox must be four numbers: west,south,east,north.\" };
  }
  const parts = value.split(\",\");
  if (parts.length !== 4 || parts.some((part) => part.trim() === \"\")) {
    return { ok: false, message: \"bbox must be four numbers: west,south,east,north.\" };
  }
  const [west, south, east, north] = parts.map((part) => Number(part));
  if (![west, south, east, north].every(Number.isFinite)) {
    return { ok: false, message: \"bbox must be four numbers: west,south,east,north.\" };
  }
  if (south < -90 || north > 90 || south > north) {
    return { ok: false, message: \"bbox latitudes must be between -90 and 90, south first.\" };
  }
  if (Math.abs(west) > MAX_LNG_ABS || Math.abs(east) > MAX_LNG_ABS) {
    return { ok: false, message: \"bbox longitudes are out of range.\" };
  }

  let width = east - west;
  if (width < 0) width += WORLD_WIDTH; // wrapped input: 170,..,-170 crosses the antimeridian
  if (width >= WORLD_WIDTH) {
    return { ok: true, boxes: [{ west: -180, south, east: 180, north }] };
  }

  const w = wrapLng(west);
  const e = wrapLng(east);
  if (w <= e) return { ok: true, boxes: [{ west: w, south, east: e, north }] };
  return {
    ok: true,
    boxes: [
      { west: w, south, east: 180, north },
      { west: -180, south, east: e, north },
    ],
  };
}

module.exports = { parseBbox, wrapLng };

// Calendar-date helpers (ADR-003, P07-T01).
//
// A stay date is a calendar date stored as a Date at 00:00:00.000Z (\"date-only
// Date\"). It is parsed only from a strict YYYY-MM-DD string and never with
// `new Date(userString)`, whose result depends on the input format and the
// server's time zone. All arithmetic here is UTC-only, so DST changes cannot
// move a date. A stay of N nights occupies check-in .. check-out minus one day;
// the check-out day itself is not an occupied night.
//
// \"Today\" for any rule is a calendar date in the listing's time zone
// (todayIn). Instants (createdAt, holdExpiresAt...) stay ordinary Dates.
const { ValidationError } = require(\"./errors\");

const DEFAULT_TIMEZONE = \"Asia/Kolkata\";
const MS_PER_DAY = 24 * 60 * 60 * 1000;

// Booking-window limits shared by search, quotes and booking. Host-set advance
// notice and the same-day cut-off (P07-T06) are added on top of these by
// src/services/bookingRules.js.
const BOOKING_WINDOW = Object.freeze({
  MIN_ADVANCE_DAYS: 0, // earliest check-in = today (listing time zone)
  MAX_HORIZON_DAYS: 365, // latest check-in = today + 365 days
  MAX_STAY_NIGHTS: 90, // longest single stay
});

// Four-digit year starting 1-9 (so Date.UTC never maps a year to 19xx), ASCII
// digits only, no spaces, no time part, no trailing newline.
const DATE_ONLY = /^([1-9]\\d{3})-(\\d{2})-(\\d{2})$/;

/** True for a valid Date at exactly 00:00:00.000Z. */
function isDateOnly(value) {
  return (
    value instanceof Date &&
    Number.isFinite(value.getTime()) &&
    value.getTime() % MS_PER_DAY === 0
  );
}

function assertDateOnly(value, name) {
  if (!isDateOnly(value)) {
    throw new TypeError(
      `${name} must be a date-only Date (00:00:00.000Z); got ${String(value)}`,
    );
  }
}

/**
 * Strict parse of \"YYYY-MM-DD\" into a date-only Date, or null when the value is
 * not a string in that exact form or is not a real calendar date
 * (2026-02-30, 2026-13-01, 2026-1-5, 2026-01-05T00:00:00Z, \" 2026-01-05\"...).
 */
function tryParseDateOnly(value) {
  if (typeof value !== \"string\") return null;
  const match = DATE_ONLY.exec(value);
  if (!match) return null;
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const date = new Date(Date.UTC(year, month - 1, day));
  // Date.UTC rolls 30 February over to March; reject anything that moved.
  if (
    date.getUTCFullYear() !== year ||
    date.getUTCMonth() !== month - 1 ||
    date.getUTCDate() !== day
  ) {
    return null;
  }
  return date;
}

/** Like tryParseDateOnly but throws a ValidationError (400) with a clear message. */
function parseDateOnly(value, label = \"Date\") {
  const date = tryParseDateOnly(value);
  if (!date) {
    throw new ValidationError(
      `${label} must be a valid date in YYYY-MM-DD format.`,
    );
  }
  return date;
}

/** \"YYYY-MM-DD\" for a date-only Date. */
function formatDateOnly(date) {
  assertDateOnly(date, \"date\");
  return date.toISOString().slice(0, 10);
}

/** The date-only Date `days` calendar days after `date` (negative = before). */
function addDays(date, days) {
  assertDateOnly(date, \"date\");
  if (!Number.isInteger(days)) {
    throw new TypeError(`days must be an integer; got ${String(days)}`);
  }
  return new Date(date.getTime() + days * MS_PER_DAY);
}

function compareDates(a, b) {
  assertDateOnly(a, \"first date\");
  assertDateOnly(b, \"second date\");
  const diff = a.getTime() - b.getTime();
  return diff < 0 ? -1 : diff > 0 ? 1 : 0;
}

const isBefore = (a, b) => compareDates(a, b) < 0;
const isAfter = (a, b) => compareDates(a, b) > 0;
const isSameDate = (a, b) => compareDates(a, b) === 0;

/** Number of nights from check-in to check-out. Check-out must be after check-in. */
function nightsBetween(checkIn, checkOut) {
  assertDateOnly(checkIn, \"checkIn\");
  assertDateOnly(checkOut, \"checkOut\");
  const nights = (checkOut.getTime() - checkIn.getTime()) / MS_PER_DAY;
  if (nights <= 0) {
    throw new ValidationError(\"Check-out must be after check-in.\");
  }
  return nights;
}

/**
 * The occupied nights of a stay as date-only Dates: check-in up to, but not
 * including, check-out. Stays longer than `maxNights` (default 90) are
 * rejected, so a huge range can never allocate a huge array.
 */
function eachNight(
  checkIn,
  checkOut,
  { maxNights = BOOKING_WINDOW.MAX_STAY_NIGHTS } = {},
) {
  const count = nightsBetween(checkIn, checkOut);
  if (count > maxNights) {
    throw new ValidationError(`A stay can be at most ${maxNights} nights.`);
  }
  const nights = [];
  for (let i = 0; i < count; i += 1) nights.push(addDays(checkIn, i));
  return nights;
}

/**
 * Today's calendar date in an IANA time zone, as a date-only Date.
 * `now` is injectable so rules can be tested at exact instants.
 */
function todayIn(timeZone = DEFAULT_TIMEZONE, now = new Date()) {
  if (typeof timeZone !== \"string\" || !timeZone) {
    throw new TypeError(\"timeZone must be a non-empty IANA time zone name\");
  }
  if (!(now instanceof Date) || !Number.isFinite(now.getTime())) {
    throw new TypeError(\"now must be a valid Date\");
  }
  let parts;
  try {
    parts = new Intl.DateTimeFormat(\"en-US\", {
      timeZone,
      year: \"numeric\",
      month: \"2-digit\",
      day: \"2-digit\",
    }).formatToParts(now);
  } catch (err) {
    if (err instanceof RangeError) {
      throw new ValidationError(`Unknown time zone: ${timeZone}`);
    }
    throw err;
  }
  const get = (type) => Number(parts.find((p) => p.type === type).value);
  return new Date(Date.UTC(get(\"year\"), get(\"month\") - 1, get(\"day\")));
}

/** The instant `ms` milliseconds after `instant` (holds, expiries). */
function instantAfter(instant, ms) {
  if (!(instant instanceof Date) || !Number.isFinite(instant.getTime())) {
    throw new TypeError(\"instant must be a valid Date\");
  }
  return new Date(instant.getTime() + ms);
}

/**
 * The wall clock in an IANA time zone at instant `now`: the calendar date (a
 * date-only Date) and the minutes since local midnight (0..1439). Booking
 * rules that depend on the time of day (P07-T06) use it, so a rule reads the
 * place's clock, not the server's.
 */
function wallClockIn(timeZone = DEFAULT_TIMEZONE, now = new Date()) {
  const date = todayIn(timeZone, now); // validates both arguments
  const parts = new Intl.DateTimeFormat(\"en-US\", {
    timeZone,
    hourCycle: \"h23\",
    hour: \"2-digit\",
    minute: \"2-digit\",
  }).formatToParts(now);
  const get = (type) => Number(parts.find((p) => p.type === type).value);
  return { date, minutes: (get(\"hour\") % 24) * 60 + get(\"minute\") };
}

/** \"14:00\" -> 840 (minutes since local midnight); null for anything else. */
function parseClockTime(value) {
  const hit = /^([01]\\d|2[0-3]):([0-5]\\d)$/.exec(typeof value === \"string\" ? value : \"\");
  return hit ? Number(hit[1]) * 60 + Number(hit[2]) : null;
}

// How far ahead of UTC a zone's wall clock is at `instant`, in minutes.
function zoneOffsetMinutes(timeZone, instant) {
  const parts = new Intl.DateTimeFormat(\"en-US\", {
    timeZone,
    hourCycle: \"h23\",
    year: \"numeric\",
    month: \"2-digit\",
    day: \"2-digit\",
    hour: \"2-digit\",
    minute: \"2-digit\",
    second: \"2-digit\",
  }).formatToParts(instant);
  const get = (type) => Number(parts.find((p) => p.type === type).value);
  const asUtc = Date.UTC(
    get(\"year\"),
    get(\"month\") - 1,
    get(\"day\"),
    get(\"hour\") % 24,
    get(\"minute\"),
    get(\"second\"),
  );
  return Math.round((asUtc - Math.floor(instant.getTime() / 1000) * 1000) / 60000);
}

/**
 * The instant at which the wall clock of `timeZone` shows `minutes` (since
 * midnight) on the calendar date `date`. Cut-offs such as \"24 hours before
 * check-in\" (P09-T03) are counted from it, so they follow the listing's own
 * clock, daylight saving included. A time that does not exist (the hour
 * skipped when clocks go forward) is read with the offset from before the
 * jump; a time that happens twice (clocks go back) is the first occurrence.
 */
function zonedInstant(date, minutes, timeZone = DEFAULT_TIMEZONE) {
  assertDateOnly(date, \"date\");
  if (!Number.isInteger(minutes) || minutes < 0 || minutes > 1439) {
    throw new TypeError(\"minutes must be a whole number from 0 to 1439\");
  }
  todayIn(timeZone, date); // validates the zone name (ValidationError)
  const asIfUtc = date.getTime() + minutes * 60000;
  let instant = asIfUtc - zoneOffsetMinutes(timeZone, new Date(asIfUtc)) * 60000;
  // The offset may differ at the instant just found (a DST change in between).
  const corrected = asIfUtc - zoneOffsetMinutes(timeZone, new Date(instant)) * 60000;
  if (corrected !== instant) {
    const again = asIfUtc - zoneOffsetMinutes(timeZone, new Date(corrected)) * 60000;
    // Keep the earlier of two valid answers (the first occurrence of a repeated hour).
    instant = again === corrected ? Math.min(instant, corrected) : corrected;
  }
  return new Date(instant);
}

/** First and last allowed check-in date for a given \"today\". */
function bookingWindow(today) {
  assertDateOnly(today, \"today\");
  return {
    earliestCheckIn: addDays(today, BOOKING_WINDOW.MIN_ADVANCE_DAYS),
    latestCheckIn: addDays(today, BOOKING_WINDOW.MAX_HORIZON_DAYS),
  };
}

/**
 * Checks a stay against the booking-window constants and returns its number of
 * nights. Throws a ValidationError whose message names the rule that failed.
 */
function assertBookableDates({ checkIn, checkOut, today }) {
  const { earliestCheckIn, latestCheckIn } = bookingWindow(today);
  assertDateOnly(checkIn, \"checkIn\");
  if (isBefore(checkIn, earliestCheckIn)) {
    throw new ValidationError(
      BOOKING_WINDOW.MIN_ADVANCE_DAYS === 0
        ? \"Check-in cannot be in the past.\"
        : `Check-in must be at least ${BOOKING_WINDOW.MIN_ADVANCE_DAYS} day(s) from today.`,
    );
  }
  if (isAfter(checkIn, latestCheckIn)) {
    throw new ValidationError(
      `Check-in can be at most ${BOOKING_WINDOW.MAX_HORIZON_DAYS} days ahead.`,
    );
  }
  const nights = nightsBetween(checkIn, checkOut);
  if (nights > BOOKING_WINDOW.MAX_STAY_NIGHTS) {
    throw new ValidationError(
      `A stay can be at most ${BOOKING_WINDOW.MAX_STAY_NIGHTS} nights.`,
    );
  }
  return nights;
}

// ---- Calendar months (P07-T03): a month grid needs the first day of a month,
// month-to-month steps and the weekday of a date, all in UTC like the rest. ----

// \"YYYY-MM\": the only month format accepted from a URL.
const MONTH_KEY = /^([1-9]\\d{3})-(0[1-9]|1[0-2])$/;

/** First day of the month given as \"YYYY-MM\" (a date-only Date), or null. */
function parseMonthKey(value) {
  if (typeof value !== \"string\") return null;
  const match = MONTH_KEY.exec(value);
  if (!match) return null;
  return new Date(Date.UTC(Number(match[1]), Number(match[2]) - 1, 1));
}

/** \"YYYY-MM\" for a date-only Date. */
function formatMonthKey(date) {
  assertDateOnly(date, \"date\");
  return date.toISOString().slice(0, 7);
}

/** The first day of the month that contains `date`. */
function startOfMonth(date) {
  assertDateOnly(date, \"date\");
  return new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), 1));
}

/** The first day of the month `months` months after (or before) `date`'s month. */
function addMonths(date, months) {
  assertDateOnly(date, \"date\");
  if (!Number.isInteger(months)) {
    throw new TypeError(`months must be an integer; got ${String(months)}`);
  }
  return new Date(
    Date.UTC(date.getUTCFullYear(), date.getUTCMonth() + months, 1),
  );
}

/** Number of days in the month that contains `date`. */
function daysInMonth(date) {
  const first = startOfMonth(date);
  return (addMonths(first, 1).getTime() - first.getTime()) / MS_PER_DAY;
}

/** Weekday with Monday = 0 ... Sunday = 6. */
function isoWeekday(date) {
  assertDateOnly(date, \"date\");
  return (date.getUTCDay() + 6) % 7;
}

module.exports = {
  DEFAULT_TIMEZONE,
  BOOKING_WINDOW,
  isDateOnly,
  tryParseDateOnly,
  parseDateOnly,
  formatDateOnly,
  addDays,
  compareDates,
  isBefore,
  isAfter,
  isSameDate,
  nightsBetween,
  eachNight,
  todayIn,
  instantAfter,
  wallClockIn,
  parseClockTime,
  zonedInstant,
  bookingWindow,
  assertBookableDates,
  parseMonthKey,
  formatMonthKey,
  startOfMonth,
  addMonths,
  daysInMonth,
  isoWeekday,
};

// Typed application errors. Throw these from controllers/services; the error
// handler (src/middleware/errors.js) maps them to a status code and a safe page.
//
// `message` is written by us for the user, so it is shown as-is for 4xx errors.
// For 5xx the handler never shows it in production.

class AppError extends Error {
  /**
   * @param {number} statusCode HTTP status
   * @param {string} message    user-safe text
   * @param {object} [options]
   * @param {string} [options.code]  stable machine-readable code
   * @param {unknown} [options.cause] underlying error (logged, never shown)
   */
  constructor(statusCode, message, { code, cause } = {}) {
    super(message, cause === undefined ? undefined : { cause });
    this.name = this.constructor.name;
    this.statusCode = statusCode;
    this.code = code || \"app_error\";
  }
}

class ValidationError extends AppError {
  constructor(message = \"The submitted data is not valid.\", options) {
    super(400, message, { code: \"validation_error\", ...options });
  }
}

class ForbiddenError extends AppError {
  constructor(message = \"You are not allowed to do that.\", options) {
    super(403, message, { code: \"forbidden\", ...options });
  }
}

class NotFoundError extends AppError {
  constructor(message = \"Page Not Found\", options) {
    super(404, message, { code: \"not_found\", ...options });
  }
}

class ConflictError extends AppError {
  constructor(message = \"That conflicts with the current state.\", options) {
    super(409, message, { code: \"conflict\", ...options });
  }
}

// A state-machine move that is not allowed (used by the reservation lifecycle).
class InvalidTransitionError extends ConflictError {
  constructor(from, to, message) {
    super(message || `Cannot change status from ${from} to ${to}.`, {
      code: \"invalid_transition\",
    });
    this.from = from;
    this.to = to;
  }
}

// The pricing service cannot give a price for this listing (no valid nightly
// price, an unsupported currency...). 422: the request is fine, the listing is not.
class QuoteRefusedError extends AppError {
  constructor(
    message = \"This listing cannot be priced right now.\",
    options,
  ) {
    super(422, message, { code: \"quote_refused\", ...options });
  }
}

// The price the guest saw is no longer the price: carries the new quote so the
// checkout page can show the difference and ask again (P07-T05, P08-T03).
class PriceChangedError extends ConflictError {
  constructor(quote, message) {
    super(
      message || \"The price has changed. Please review the new total.\",
      { code: \"price_changed\" },
    );
    this.quote = quote;
  }
}

module.exports = {
  AppError,
  ValidationError,
  ForbiddenError,
  NotFoundError,
  ConflictError,
  InvalidTransitionError,
  QuoteRefusedError,
  PriceChangedError,
};

// Legacy error type, kept so existing `new ExpressError(status, message)` calls
// keep working. New code should throw the typed errors in ./errors.js.
const { AppError } = require(\"./errors\");

class ExpressError extends AppError {
  constructor(statusCode, message) {
    super(statusCode, message);
  }
}

module.exports = ExpressError;

// What the listings page shows about its filters (P05-T04), made from the
// validated state (see src/validation/searchQuery.js) and nothing else:
//   activeChips(state)      one chip per active filter, each with a link that
//                           removes just that filter and keeps the rest
//   filterCount(state)      how many filters the filter panel owns are on
//   resetFiltersHref(state) the page without the panel's filters and category
//   categoryLinks(state)    the category strip: \"All\" first, then each category
// Labels are plain text; the views escape them.
const {
  PROPERTY_TYPES,
  ROOM_TYPES,
  AMENITIES,
  ACCESSIBILITY_FEATURES,
} = require(\"../config/constants\");
const { CATEGORIES, getCategory } = require(\"../config/categories\");
const { listingsUrl } = require(\"./searchUrl\");

// The filters the filter panel edits (the rest of the state is carried through
// the panel form as hidden inputs, see hiddenFields in searchUrl.js).
const PANEL_FIELDS = Object.freeze([
  \"radius\",
  \"minPrice\",
  \"maxPrice\",
  \"type\",
  \"roomType\",
  \"bedrooms\",
  \"amenities\",
  \"access\",
  \"instantBook\",
]);

const labelOf = (list) => new Map(list.map((item) => [item.value, item.label]));
const PROPERTY_LABELS = labelOf(PROPERTY_TYPES);
const ROOM_LABELS = labelOf(ROOM_TYPES);
const AMENITY_LABELS = labelOf(AMENITIES);
const ACCESS_LABELS = labelOf(ACCESSIBILITY_FEATURES);

const MONTHS = [\"Jan\", \"Feb\", \"Mar\", \"Apr\", \"May\", \"Jun\", \"Jul\", \"Aug\", \"Sep\", \"Oct\", \"Nov\", \"Dec\"];

/** \"2026-12-24\" -> \"24 Dec 2026\" (text only, no Date, so no time zone can shift it). */
function dayLabel(value) {
  const match = /^(\\d{4})-(\\d{2})-(\\d{2})$/.exec(String(value));
  if (!match) return String(value);
  return `${Number(match[3])} ${MONTHS[Number(match[2]) - 1] ?? match[2]} ${match[1]}`;
}

const rupees = (n) => `₹${Number(n).toLocaleString(\"en-IN\")}`;
const plural = (n, one, many) => `${n} ${n === 1 ? one : many}`;
const asList = (value) => (Array.isArray(value) ? value : value === undefined ? [] : [value]);

/** The list without one value (undefined when nothing is left, which removes the parameter). */
const without = (value, item) => {
  const rest = asList(value).filter((entry) => entry !== item);
  return rest.length ? rest : undefined;
};

/**
 * @param {object} state  the validated URL state
 * @returns {Array<{ key: string, label: string, href: string }>} in a fixed order
 */
function activeChips(state = {}) {
  const chips = [];
  const add = (key, label, changes) =>
    chips.push({ key, label, href: listingsUrl(state, changes) });

  if (state.dest) add(\"dest\", `Where: ${state.dest}`, { dest: undefined });
  if (state.dest && Number.isInteger(state.radius)) {
    add(\"radius\", `Within ${state.radius} km`, { radius: undefined });
  }
  if (state.in && state.out) {
    add(\"dates\", `${dayLabel(state.in)} to ${dayLabel(state.out)}`, { in: undefined, out: undefined, flex: undefined });
  }
  if (state.flex === 3 && state.in && state.out) {
    add(\"flex\", \"Available ±3 days\", { flex: undefined });
  }
  if (Number.isInteger(state.guests)) {
    add(\"guests\", plural(state.guests, \"guest\", \"guests\"), { guests: undefined });
  }

  const category = getCategory(state.category);
  if (category) add(\"category\", category.label, { category: undefined });

  const hasMin = typeof state.minPrice === \"number\";
  const hasMax = typeof state.maxPrice === \"number\";
  if (hasMin || hasMax) {
    const label =
      hasMin && hasMax
        ? `${rupees(state.minPrice)} to ${rupees(state.maxPrice)} a night`
        : hasMin
          ? `From ${rupees(state.minPrice)} a night`
          : `Up to ${rupees(state.maxPrice)} a night`;
    add(\"price\", label, { minPrice: undefined, maxPrice: undefined });
  }

  for (const value of asList(state.type)) {
    add(`type:${value}`, PROPERTY_LABELS.get(value) ?? value, { type: without(state.type, value) });
  }
  for (const value of asList(state.roomType)) {
    add(`roomType:${value}`, ROOM_LABELS.get(value) ?? value, { roomType: without(state.roomType, value) });
  }
  if (Number.isInteger(state.bedrooms) && state.bedrooms > 0) {
    add(\"bedrooms\", `${state.bedrooms}+ bedrooms`, { bedrooms: undefined });
  }
  for (const value of asList(state.amenities)) {
    add(`amenity:${value}`, AMENITY_LABELS.get(value) ?? value, { amenities: without(state.amenities, value) });
  }
  for (const value of asList(state.access)) {
    add(`access:${value}`, `${ACCESS_LABELS.get(value) ?? value} (declared)`, { access: without(state.access, value) });
  }
  if (state.instantBook === true) add(\"instantBook\", \"Instant book\", { instantBook: undefined });
  if (typeof state.minRating === \"number\") {
    add(\"minRating\", `Rated ${state.minRating}+`, { minRating: undefined });
  }
  if (state.keywords) add(\"keywords\", `Keywords: ${state.keywords}`, { keywords: undefined });

  return chips;
}

/** How many of the filter panel's filters are on (a price range counts once). */
function filterCount(state = {}) {
  let count = 0;
  if (state.dest && Number.isInteger(state.radius)) count += 1;
  if (typeof state.minPrice === \"number\" || typeof state.maxPrice === \"number\") count += 1;
  count += asList(state.type).length;
  count += asList(state.roomType).length;
  if (Number.isInteger(state.bedrooms) && state.bedrooms > 0) count += 1;
  count += asList(state.amenities).length;
  count += asList(state.access).length;
  if (state.instantBook === true) count += 1;
  return count;
}

/** The page without the panel's filters and the category (search, dates and guests stay). */
function resetFiltersHref(state = {}) {
  const changes = { category: undefined };
  for (const name of PANEL_FIELDS) changes[name] = undefined;
  return listingsUrl(state, changes);
}

/**
 * The strip: \"All stays\" and every category, each with the link that selects it
 * (the rest of the search is kept, the page goes back to 1) and whether it is
 * the current one. Choosing \"All\" removes the category.
 */
function categoryLinks(state = {}) {
  const active = getCategory(state.category);
  return [
    {
      slug: \"\",
      label: \"All stays\",
      icon: \"fa-border-all\",
      href: listingsUrl(state, { category: undefined }),
      active: !active,
    },
    ...CATEGORIES.map((category) => ({
      slug: category.slug,
      label: category.label,
      icon: category.icon,
      href: listingsUrl(state, { category: category.slug }),
      active: Boolean(active) && active.slug === category.slug,
    })),
  ];
}

module.exports = {
  PANEL_FIELDS,
  activeChips,
  filterCount,
  resetFiltersHref,
  categoryLinks,
  dayLabel,
};

// Turns a stored GeoJSON Point into the { lng, lat } pair the detail page puts
// in data- attributes. Returns null when the listing has no usable location
// (old data, or a value outside the valid range), so the page can say so
// instead of drawing a map at a wrong place.
function toMapPoint(geometry) {
  if (!geometry || geometry.type !== \"Point\") return null;
  const coordinates = geometry.coordinates;
  if (!Array.isArray(coordinates) || coordinates.length < 2) return null;

  const lng = coordinates[0];
  const lat = coordinates[1];
  if (typeof lng !== \"number\" || typeof lat !== \"number\") return null;
  if (!Number.isFinite(lng) || !Number.isFinite(lat)) return null;
  if (lng < -180 || lng > 180 || lat < -90 || lat > 90) return null;

  return { lng, lat };
}

// ---------------------------------------------------------------------------
// Approximate public location (P06-T02).
//
// The map a visitor sees must not reveal where a home is. Each listing has a
// public point: the precise point moved 300 to 800 metres in a direction that
// depends on the listing id AND a server secret (HMAC-SHA256). Both matter:
//   * deterministic: the same listing always gets the same public point, so
//     reloading the page and averaging the answers gains nothing;
//   * keyed: the id is public (it is in the URL), so an offset computed from
//     the id alone could be computed by anybody and subtracted again. With the
//     secret, the offset is unknowable from outside.
// The move is a great-circle step, so it is right near the poles and across the
// antimeridian (longitude wraps).
// ---------------------------------------------------------------------------
const crypto = require(\"node:crypto\");

const EARTH_RADIUS_M = 6371008.8;
const MIN_OFFSET_M = 300;
const MAX_OFFSET_M = 800;
const COORDINATE_DECIMALS = 5; // about 1 m
// Radius of the circle the detail page draws around the public point (P06-T03).
// It must be larger than MAX_OFFSET_M, so the circle always contains the real
// home without being centred on it.
const PUBLIC_AREA_RADIUS_M = 1000;
// Rounding to 5 decimals can move a point by up to about 1 m, so the step is
// drawn from [300 + 1, 800 - 1]: the rounded point is still 300 to 800 m away.
const ROUNDING_MARGIN_M = 1;
const DEV_SECRET = \"dimora-development-location-secret-not-for-production\";

let locationSecret = null;

/**
 * Sets the secret the offsets are keyed with. Called once at start-up with the
 * session secret (src/app.js). Changing it moves every public point (they are
 * recomputed the next time a listing is saved, or by migration 007).
 */
function configureLocationSecret(secret) {
  if (typeof secret !== \"string\" || secret.length < 16) {
    throw new TypeError(\"The location secret must be a string of at least 16 characters\");
  }
  locationSecret = `${secret}|dimora-location-v1`;
}

function secretInUse() {
  if (locationSecret) return locationSecret;
  // Only a development or test run may fall back; a production run that never
  // configured a secret must fail rather than use a key anyone can read here.
  if (process.env.NODE_ENV === \"production\") {
    throw new Error(\"The location secret is not configured\");
  }
  return `${DEV_SECRET}|dimora-location-v1`;
}

/** The step for a listing: a direction (radians) and a distance (metres). */
function offsetFor(listingId, secret = secretInUse()) {
  const digest = crypto
    .createHmac(\"sha256\", secret)
    .update(`offset|${String(listingId)}`)
    .digest();
  const unit = (from) => digest.readUIntBE(from, 6) / 2 ** 48; // [0, 1)
  return {
    bearing: unit(0) * 2 * Math.PI,
    meters:
      MIN_OFFSET_M +
      ROUNDING_MARGIN_M +
      unit(6) * (MAX_OFFSET_M - MIN_OFFSET_M - 2 * ROUNDING_MARGIN_M),
  };
}

const round = (value) => Number(value.toFixed(COORDINATE_DECIMALS));

/**
 * The public point for a precise GeoJSON Point.
 * @returns {{ type: \"Point\", coordinates: [number, number] } | null} null when
 * the precise point is unusable or there is no id.
 */
function approximatePoint(geometry, listingId, { secret } = {}) {
  const precise = toMapPoint(geometry);
  if (!precise || listingId === undefined || listingId === null || String(listingId) === \"\") {
    return null;
  }
  const { bearing, meters } = offsetFor(listingId, secret);
  const delta = meters / EARTH_RADIUS_M;
  const lat1 = (precise.lat * Math.PI) / 180;
  const lng1 = (precise.lng * Math.PI) / 180;

  const sinLat2 = Math.sin(lat1) * Math.cos(delta) + Math.cos(lat1) * Math.sin(delta) * Math.cos(bearing);
  const lat2 = Math.asin(Math.max(-1, Math.min(1, sinLat2)));
  const lng2 =
    lng1 +
    Math.atan2(
      Math.sin(bearing) * Math.sin(delta) * Math.cos(lat1),
      Math.cos(delta) - Math.sin(lat1) * Math.sin(lat2),
    );

  const lat = Math.max(-90, Math.min(90, (lat2 * 180) / Math.PI));
  let lng = (lng2 * 180) / Math.PI;
  lng = ((((lng + 180) % 360) + 360) % 360) - 180; // wrap into [-180, 180)
  return { type: \"Point\", coordinates: [round(lng), round(lat)] };
}

/** Great-circle distance in metres between two { lng, lat } points. */
function distanceMeters(a, b) {
  const rad = (d) => (d * Math.PI) / 180;
  const dLat = rad(b.lat - a.lat);
  const dLng = rad(b.lng - a.lng);
  const h =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(rad(a.lat)) * Math.cos(rad(b.lat)) * Math.sin(dLng / 2) ** 2;
  return 2 * EARTH_RADIUS_M * Math.asin(Math.min(1, Math.sqrt(h)));
}

/**
 * The { lng, lat } a page may show for a listing (a document or plain object):
 * its stored public point, or, for a listing saved before this existed, the
 * public point computed from its precise one. Never the precise point itself.
 */
function publicPointOf(listing) {
  if (!listing) return null;
  const read = (path) => (typeof listing.get === \"function\" ? listing.get(path) : path.split(\".\").reduce((n, k) => (n == null ? undefined : n[k]), listing));
  const stored = toMapPoint({
    type: read(\"publicGeometry.type\"),
    coordinates: read(\"publicGeometry.coordinates\") && Array.from(read(\"publicGeometry.coordinates\")),
  });
  if (stored) return stored;
  const precise = {
    type: read(\"geometry.type\"),
    coordinates: read(\"geometry.coordinates\") && Array.from(read(\"geometry.coordinates\")),
  };
  const id = read(\"_id\");
  return toMapPoint(approximatePoint(precise, id));
}

module.exports = {
  toMapPoint,
  approximatePoint,
  publicPointOf,
  distanceMeters,
  configureLocationSecret,
  offsetFor,
  MIN_OFFSET_M,
  MAX_OFFSET_M,
  PUBLIC_AREA_RADIUS_M,
};

// Cloudinary delivery URLs (P04-T03). The stored URL is the original upload,
// which can be many megabytes; pages ask for a size that fits instead, in the
// format and quality the visitor's browser handles best (f_auto, q_auto).
//
//   imageUrl(\"https://res.cloudinary.com/x/image/upload/v1/a.jpg\", \"card\")
//   -> \"https://res.cloudinary.com/x/image/upload/w_800,f_auto,q_auto/v1/a.jpg\"
//
// Anything that is not a Cloudinary upload URL (seed photos on Unsplash, a
// missing value) is returned unchanged, and a URL that already carries a
// transformation is not transformed twice.
const PRESETS = Object.freeze({
  card: \"w_800,f_auto,q_auto\", // cards and the main gallery picture
  thumb: \"w_200,h_150,c_fill,f_auto,q_auto\", // gallery thumbnails
  full: \"w_1600,f_auto,q_auto\", // the full-screen viewer
  edit: \"w_250,f_auto,q_auto\", // the host's photo manager
  avatar: \"w_256,h_256,c_fill,g_auto,f_auto,q_auto\", // profile pictures (square)
});

const UPLOAD = /^(https:\\/\\/res\\.cloudinary\\.com\\/[^/]+\\/image\\/upload\\/)(.*)$/;
// \"w_800,f_auto\" or \"c_fill,h_150\": letters, underscore, value; comma separated.
const TRANSFORMATION = /^[a-z]{1,3}_[^/,]+(,[a-z]{1,3}_[^/,]+)*$/;

function imageUrl(url, preset = \"card\") {
  if (typeof url !== \"string\" || url === \"\") return \"\";
  if (!Object.hasOwn(PRESETS, preset)) {
    throw new Error(`imageUrl: unknown preset \"${preset}\"`);
  }
  const match = UPLOAD.exec(url);
  if (!match) return url;
  const [, base, rest] = match;
  const firstSegment = rest.split(\"/\")[0];
  if (TRANSFORMATION.test(firstSegment)) return url; // already transformed
  return `${base}${PRESETS[preset]}/${rest}`;
}

const UNSPLASH_HOST = \"images.unsplash.com\";
const MIN_WIDTH = 100;
const MAX_WIDTH = 4000;

/**
 * The `srcset` of a picture: the same photo at several widths, so a phone
 * downloads a 400 px file and a large screen a 1200 px one (P18-T01).
 *   imageSrcset(\"https://res.cloudinary.com/x/image/upload/v1/a.jpg\", [400, 800])
 *   -> \"https://res.cloudinary.com/x/image/upload/w_400,f_auto,q_auto/v1/a.jpg 400w,
 *       https://res.cloudinary.com/x/image/upload/w_800,f_auto,q_auto/v1/a.jpg 800w\"
 * Cloudinary uploads and the Unsplash seed photos are resized; any other URL, or
 * one that already carries a transformation, gives \"\" (the plain `src` is used).
 * @param {string} url
 * @param {number[]} [widths] whole numbers from 100 to 4000
 */
function imageSrcset(url, widths = [400, 800, 1200]) {
  if (
    !Array.isArray(widths) ||
    widths.length === 0 ||
    !widths.every((w) => Number.isInteger(w) && w >= MIN_WIDTH && w <= MAX_WIDTH)
  ) {
    throw new Error(\"imageSrcset: widths must be whole numbers from 100 to 4000\");
  }
  if (typeof url !== \"string\" || url === \"\") return \"\";

  const cloud = UPLOAD.exec(url);
  if (cloud) {
    const [, base, rest] = cloud;
    if (TRANSFORMATION.test(rest.split(\"/\")[0])) return \"\";
    return widths.map((w) => `${base}w_${w},f_auto,q_auto/${rest} ${w}w`).join(\", \");
  }

  let parsed;
  try {
    parsed = new URL(url);
  } catch {
    return \"\";
  }
  if (parsed.protocol !== \"https:\" || parsed.hostname !== UNSPLASH_HOST) return \"\";
  return widths
    .map((w) => {
      const sized = new URL(url);
      sized.searchParams.set(\"w\", String(w));
      sized.searchParams.set(\"auto\", \"format\");
      sized.searchParams.set(\"q\", \"70\");
      return `${sized.toString()} ${w}w`;
    })
    .join(\", \");
}

module.exports = { imageUrl, imageSrcset, PRESETS };

// JSON for a <script type=\"application/ld+json\"> block (P17-T02).
//
// JSON.stringify alone is not safe there: a title like \"</script><script>...\"
// would close the block. The one implementation lives in
// src/utils/structuredData.js (`safeJson`, used by `listingJsonLd`, P04-T07);
// this name is kept for code that only needs the escaping. views/listings/show.ejs
// prints a `structuredData` local with the raw tag, so whatever sets it must be
// built with `listingJsonLd` or `jsonForScript`.
const { safeJson } = require(\"./structuredData\");

module.exports = { jsonForScript: safeJson };

// Turns a stored listing (document or lean object) into the `item` the
// listing-card partial takes. Prices are integer paise (listing.pricing).
function nightlyMinor(doc) {
  const minor = doc.pricing && doc.pricing.nightlyMinor;
  return Number.isInteger(minor) && minor >= 0 ? minor : null;
}

function toCardItem(listing) {
  const doc = listing || {};
  return {
    id: String(doc._id ?? doc.id ?? \"\"),
    title: doc.title ?? \"\",
    imageUrl: doc.image && doc.image.url ? doc.image.url : null,
    location: doc.location,
    country: doc.country,
    priceMinor: nightlyMinor(doc),
    currency: (doc.pricing && doc.pricing.currency) || \"INR\",
  };
}

module.exports = { toCardItem };

// Small conversions between what the old listing form submits (rupees, free
// text place) and the v2 listing fields. The wizard (P04-T02) replaces the
// form, and with it most of this file.

/** Whole or fractional rupees -> integer paise. Returns null if not a number. */
function rupeesToMinor(rupees) {
  // An empty or blank string is \"nothing typed\", not zero rupees.
  if (typeof rupees === \"string\" && rupees.trim() === \"\") return null;
  const n = typeof rupees === \"string\" ? Number(rupees.trim()) : rupees;
  if (typeof n !== \"number\" || !Number.isFinite(n) || n < 0) return null;
  return Math.round(n * 100);
}

/** Paise -> rupees for an input box: 250000 -> 2500, 123456 -> 1234.56. */
function minorToRupees(minor) {
  return Number.isInteger(minor) ? minor / 100 : null;
}

/** Best-effort structured address from the old location/country text. */
function addressFromLegacy(location, country) {
  const city = String(location ?? \"\").trim();
  const nation = String(country ?? \"\").trim();
  const address = {};
  if (city) address.city = city;
  if (nation) address.country = nation;
  return address;
}

/** The images[] entry for a stored cover image, or [] when there is none.
 *  (`filename` is the old name of the Cloudinary id; it becomes `publicId`.) */
function imagesFromCover(image) {
  if (!image || typeof image.url !== \"string\" || !image.url) return [];
  return [
    {
      url: image.url,
      publicId: image.filename || \"\",
      alt: \"\",
      caption: \"\",
      order: 0,
    },
  ];
}

module.exports = {
  rupeesToMinor,
  minorToRupees,
  addressFromLegacy,
  imagesFromCover,
};

// Money (P03-T03 display, P08-T01 arithmetic). Amounts are integers in MINOR
// units (paise for INR): never floats, never strings (ADR-002).
const formatters = new Map();

function formatterFor(currency, fractionDigits) {
  const key = `${currency}:${fractionDigits}`;
  let fmt = formatters.get(key);
  if (!fmt) {
    fmt = new Intl.NumberFormat(\"en-IN\", {
      style: \"currency\",
      currency,
      minimumFractionDigits: fractionDigits,
      maximumFractionDigits: fractionDigits,
    });
    formatters.set(key, fmt);
  }
  return fmt;
}

/**
 * formatMoney(123456)        -> \"₹1,234.56\"
 * formatMoney(120000)        -> \"₹1,200\"      (whole amounts drop the .00)
 * formatMoney(null)          -> \"N/A\"          (no price set)
 * formatMoney(1050, \"USD\")   -> \"$10.50\"
 * Throws TypeError for anything that is not an integer amount (a float here
 * is a bug, and showing a rounded price would hide it).
 */
function formatMoney(minor, currency = \"INR\") {
  if (minor === null || minor === undefined) return \"N/A\";
  if (typeof minor !== \"number\" || !Number.isSafeInteger(minor)) {
    throw new TypeError(\"formatMoney expects an integer amount in minor units\");
  }
  if (typeof currency !== \"string\" || !/^[A-Z]{3}$/.test(currency)) {
    throw new TypeError(
      \"formatMoney expects a 3-letter currency code such as INR\",
    );
  }
  const digits = formatterFor(currency, undefined).resolvedOptions()
    .maximumFractionDigits;
  const divisor = 10 ** digits;
  const whole = minor % divisor === 0;
  return formatterFor(currency, whole ? 0 : digits).format(minor / divisor);
}

// ---------------------------------------------------------------------------
// Arithmetic (P08-T01). Everything here works on integers in minor units and
// never touches a float. Intermediate products can exceed 2^53, so they are
// computed with BigInt and converted back (with a check) only at the end.
//
// ROUNDING RULE (the only one in the app): a fraction of a paisa is rounded
// half up, i.e. 0.5 paisa and above goes up, below goes down. Amounts are never
// negative here, so \"up\" means away from zero too.
//   percentOf(1, 5000)   (50% of 1 paisa)  -> 1
//   percentOf(1, 4999)   (49.99%)          -> 0
//   percentOf(999, 1800) (18% of 9.99)     -> 180   (179.82 rounds to 180)
// ---------------------------------------------------------------------------

const MAX_BPS = 10000; // 100 %

/** Throws TypeError unless `value` is a non-negative safe integer. */
function assertMinor(value, name = \"amount\") {
  if (typeof value !== \"number\" || !Number.isSafeInteger(value) || value < 0) {
    throw new TypeError(`${name} must be a non-negative integer in minor units`);
  }
  return value;
}

function toSafe(big, name) {
  const n = Number(big);
  if (!Number.isSafeInteger(n)) {
    throw new RangeError(`${name} is too large`);
  }
  return n;
}

/** round-half-up of amount * numerator / denominator, all integers, exactly. */
function mulDivRound(amount, numerator, denominator) {
  assertMinor(amount, \"amount\");
  assertMinor(numerator, \"numerator\");
  if (typeof denominator !== \"number\" || !Number.isSafeInteger(denominator) || denominator < 1) {
    throw new TypeError(\"denominator must be a positive integer\");
  }
  const d = BigInt(denominator);
  const exact = BigInt(amount) * BigInt(numerator);
  return toSafe((exact * 2n + d) / (2n * d), \"result\");
}

/**
 * `basisPoints` hundredths of a percent of `amount`: 1800 = 18 %, 250 = 2.5 %.
 * Basis points keep rates as integers too.
 */
function percentOf(amount, basisPoints) {
  assertMinor(amount, \"amount\");
  if (!Number.isInteger(basisPoints) || basisPoints < 0 || basisPoints > MAX_BPS) {
    throw new TypeError(`basisPoints must be an integer from 0 to ${MAX_BPS}`);
  }
  return mulDivRound(amount, basisPoints, MAX_BPS);
}

/** amount / divisor, rounded half up (the average of an integer total). */
function divideRound(amount, divisor) {
  return mulDivRound(amount, 1, divisor);
}

/** amount x count (a whole number of nights, say), checked for overflow. */
function multiplyMinor(amount, count) {
  assertMinor(amount, \"amount\");
  assertMinor(count, \"count\");
  return toSafe(BigInt(amount) * BigInt(count), \"result\");
}

/** Sum of amounts, checked for overflow. An empty list is 0. */
function sumMinor(amounts) {
  if (!Array.isArray(amounts)) throw new TypeError(\"sumMinor expects an array\");
  let total = 0n;
  for (const amount of amounts) total += BigInt(assertMinor(amount, \"amount\"));
  return toSafe(total, \"sum\");
}

module.exports = {
  formatMoney,
  assertMinor,
  percentOf,
  divideRound,
  mulDivRound,
  multiplyMinor,
  sumMinor,
  MAX_BPS,
};

// Per-page <title> and meta description (P03-T02). Controllers pass `pageTitle`
// and optionally `pageDescription` to res.render; the layout turns them into
// the tags with these helpers (registered as app.locals in app.js).
const SITE_NAME = \"Dimora\";
const DEFAULT_DESCRIPTION =
  \"Dimora is a place to find a stay, or to list your own home and welcome guests.\";
const TITLE_MAX = 70;
const DESCRIPTION_MAX = 160;

const squash = (value) =>
  String(value ?? \"\")
    .replace(/\\s+/g, \" \")
    .trim();

/** \"Page name | Dimora\"; just \"Dimora\" when the page gives no name. */
function fullTitle(pageTitle) {
  let title = squash(pageTitle);
  if (!title) return SITE_NAME;
  if (title.length > TITLE_MAX)
    title = `${title.slice(0, TITLE_MAX - 1).trimEnd()}…`;
  return `${title} | ${SITE_NAME}`;
}

/** The page's own description, shortened at a word boundary; else the site default. */
function metaDescription(pageDescription) {
  const text = squash(pageDescription);
  if (!text) return DEFAULT_DESCRIPTION;
  if (text.length <= DESCRIPTION_MAX) return text;
  const cut = text.slice(0, DESCRIPTION_MAX - 1);
  const atWord = cut.lastIndexOf(\" \");
  return `${(atWord > 80 ? cut.slice(0, atWord) : cut).trimEnd()}…`;
}

module.exports = { SITE_NAME, DEFAULT_DESCRIPTION, fullTitle, metaDescription };

// Page links for the pagination partial (P03-T03); sorting and the real query
// handling arrive in P05-T02/T03. Pure functions, no Express.

function toPageCount(totalPages) {
  const n = Math.floor(Number(totalPages));
  return Number.isFinite(n) && n >= 1 ? n : 1;
}

function toPage(page, totalPages) {
  const n = Math.floor(Number(page));
  if (!Number.isFinite(n) || n < 1) return 1;
  return Math.min(n, totalPages);
}

/**
 * Which links to show: first, last, the current page and `windowSize` pages on
 * each side; \"gap\" items stand for skipped ranges (a gap that would hide a
 * single page shows that page instead).
 * pageItems(5, 10) -> 1 … 4 5 6 … 10
 */
function pageItems(page, totalPages, windowSize = 1) {
  const last = toPageCount(totalPages);
  const current = toPage(page, last);
  const wanted = new Set([1, last]);
  for (let n = current - windowSize; n <= current + windowSize; n += 1) {
    if (n >= 1 && n <= last) wanted.add(n);
  }
  const numbers = [...wanted].sort((a, b) => a - b);
  const items = [];
  let previous = 0;
  for (const n of numbers) {
    if (n - previous === 2)
      items.push({
        type: \"page\",
        number: previous + 1,
        current: previous + 1 === current,
      });
    else if (n - previous > 2) items.push({ type: \"gap\" });
    items.push({ type: \"page\", number: n, current: n === current });
    previous = n;
  }
  return items;
}

// Only a same-site path may be the base of a link.
function safeBase(baseUrl) {
  if (
    typeof baseUrl !== \"string\" ||
    baseUrl[0] !== \"/\" ||
    baseUrl[1] === \"/\" ||
    baseUrl[1] === \"\\\\\"
  )
    return \"/\";
  // eslint-disable-next-line no-control-regex
  if (/[\\u0000-\\u001f\\u007f\\\\?#]/.test(baseUrl)) return \"/\";
  return baseUrl;
}

/**
 * Link to page `number`, keeping the other query parameters. Page 1 has no
 * `page` parameter (one canonical URL per page).
 */
function pageHref(baseUrl, query, number, param = \"page\") {
  const params = new URLSearchParams();
  for (const [key, value] of Object.entries(query || {})) {
    if (key === param) continue;
    for (const v of Array.isArray(value) ? value : [value]) {
      if (
        typeof v === \"string\" ||
        typeof v === \"number\" ||
        typeof v === \"boolean\"
      ) {
        if (String(v) !== \"\") params.append(key, String(v));
      }
    }
  }
  if (number > 1) params.set(param, String(number));
  const qs = params.toString();
  return `${safeBase(baseUrl)}${qs ? `?${qs}` : \"\"}`;
}

module.exports = { pageItems, pageHref, toPage, toPageCount };

// The seasonal-price rows of the pricing form (P08-T04). The form is flat (no
// nested names), so season N is four boxes: season1Name, season1From,
// season1To, season1Price. This turns them into the stored shape and checks
// them; the browser is never trusted. Pure: no database, no clock.
const { tryParseDateOnly, formatDateOnly, nightsBetween } = require(\"./dates\");
const { rupeesToMinor, minorToRupees } = require(\"./listingFields\");

const MAX_SEASONS = 5;
const NAME_MAX = 40;
const MIN_RUPEES = 100;
const MAX_RUPEES = 1000000;
const MAX_SPAN_DAYS = 366;

const FIELD = (n) => ({
  name: `season${n}Name`,
  from: `season${n}From`,
  to: `season${n}To`,
  price: `season${n}Price`,
});
const ROWS = Array.from({ length: MAX_SEASONS }, (_, i) => i + 1);
const SEASON_FIELD_NAMES = ROWS.flatMap((n) => Object.values(FIELD(n)));

const str = (v) => (typeof v === \"string\" ? v.trim() : v === undefined || v === null ? \"\" : String(v).trim());

/**
 * @param {object} body the step's submitted fields
 * @returns {{ seasons: {name:string, from:Date, to:Date, nightlyMinor:number}[], errors: Record<string,string> }}
 *   `errors` is keyed by form field id; seasons are sorted by start date.
 */
function parseSeasons(body = {}) {
  const errors = {};
  const rows = [];
  for (const n of ROWS) {
    const f = FIELD(n);
    const v = { name: str(body[f.name]), from: str(body[f.from]), to: str(body[f.to]), price: str(body[f.price]) };
    const filled = Object.values(v).filter(Boolean).length;
    if (filled === 0) continue;
    if (filled < 4) {
      const firstEmpty = [\"name\", \"from\", \"to\", \"price\"].find((k) => !v[k]);
      errors[f[firstEmpty]] = \"Fill in all four boxes of this season, or clear them all.\";
      continue;
    }
    let ok = true;
    const fail = (key, message) => {
      if (!errors[f[key]]) errors[f[key]] = message;
      ok = false;
    };
    if (v.name.length > NAME_MAX) fail(\"name\", `The name can be at most ${NAME_MAX} characters.`);
    const from = tryParseDateOnly(v.from);
    const to = tryParseDateOnly(v.to);
    if (!from) fail(\"from\", \"Use a date like 2026-12-20.\");
    if (!to) fail(\"to\", \"Use a date like 2027-01-05.\");
    if (from && to) {
      if (to < from) fail(\"to\", \"A season cannot end before it starts.\");
      else if (nightsBetween(from, new Date(to.getTime() + 86400000)) > MAX_SPAN_DAYS) {
        fail(\"to\", `A season can last at most ${MAX_SPAN_DAYS} days.`);
      }
    }
    const price = Number(v.price);
    if (!Number.isFinite(price) || price < MIN_RUPEES || price > MAX_RUPEES) {
      fail(\"price\", `The price must be a number from ₹${MIN_RUPEES} to ₹${MAX_RUPEES.toLocaleString(\"en-IN\")}.`);
    }
    if (ok) rows.push({ n, name: v.name, from, to, nightlyMinor: rupeesToMinor(price) });
  }

  // Seasons may not overlap: report the later one, on its start date.
  const byStart = [...rows].sort((a, b) => a.from - b.from || a.n - b.n);
  for (let i = 1; i < byStart.length; i += 1) {
    const before = byStart[i - 1];
    const row = byStart[i];
    if (row.from <= before.to && !errors[FIELD(row.n).from]) {
      errors[FIELD(row.n).from] = `This overlaps the season \"${before.name}\". Seasons cannot share a night.`;
    }
  }
  const seasons = byStart.map(({ name, from, to, nightlyMinor }) => ({ name, from, to, nightlyMinor }));
  return { seasons, errors };
}

/** The flat form values (season1Name ... season5Price) for the stored seasons. */
function seasonFormValues(stored) {
  const out = {};
  const list = Array.isArray(stored) ? stored : [];
  for (const n of ROWS) {
    const f = FIELD(n);
    const season = list[n - 1];
    out[f.name] = season ? season.name : \"\";
    out[f.from] = season && season.from ? formatDateOnly(season.from) : \"\";
    out[f.to] = season && season.to ? formatDateOnly(season.to) : \"\";
    const rupees = season ? minorToRupees(season.nightlyMinor) : null;
    out[f.price] = rupees === null ? \"\" : rupees;
  }
  return out;
}

module.exports = { parseSeasons, seasonFormValues, SEASON_FIELD_NAMES, MAX_SEASONS, FIELD, ROWS };

// Review ratings for the listing page (P04-T07).

/**
 * { average, count } from a list of reviews. Only whole ratings 1-5 count;
 * anything else (missing, text, out of range) is ignored. `average` has one
 * decimal and is null when there is nothing to average.
 */
function summarizeRatings(reviews) {
  const ratings = (Array.isArray(reviews) ? reviews : [])
    .map((review) => (review ? review.rating : undefined))
    .filter((r) => Number.isInteger(r) && r >= 1 && r <= 5);
  if (ratings.length === 0) return { average: null, count: 0 };
  const sum = ratings.reduce((total, r) => total + r, 0);
  return {
    average: Math.round((sum / ratings.length) * 10) / 10,
    count: ratings.length,
  };
}

module.exports = { summarizeRatings };

// A reason typed by a person who declines or cancels a booking (P09-T02,
// P09-T03): optional text, up to 500 characters. Too long is refused, never cut.
const { ValidationError } = require(\"./errors\");

const REASON_MAX = 500;

/** @returns {string} the trimmed reason, \"\" when there is none */
function parseReason(raw) {
  if (raw === undefined || raw === null) return \"\";
  if (typeof raw !== \"string\")
    throw new ValidationError(\"The reason must be text.\");
  const text = raw.trim();
  if (text.length > REASON_MAX) {
    throw new ValidationError(
      `The reason can be at most ${REASON_MAX} characters.`,
    );
  }
  return text;
}

module.exports = { parseReason, REASON_MAX };

// What a request log may say about a URL (P17-T05): the path, never the query
// string, and never a one-time token that travels in the path
// (/verify-email/<token>, /reset-password/<token>; P02-T05). A reset link in a
// log is a key to the account for as long as the link lives.
const TOKEN_ROUTES = /^(\\/(?:verify-email|reset-password)\\/)[^/]+/;

/** @param {string|undefined} url the raw request URL (path and query) */
function redactPath(url) {
  const path = String(url || \"\").split(\"?\")[0].split(\"#\")[0];
  return path.replace(TOKEN_ROUTES, \"$1[redacted]\");
}

module.exports = { redactPath };

// The app's routes as data, read from the routers themselves (P19-T01), so the
// API list in docs/API.md can be checked against what the app really serves
// (tests/unit/docsApi.test.js) instead of being trusted.
//
// Mount points come from src/app.js (`app.use(\"<prefix>\", xRouter)`); the
// routes come from each router's own stack. Handlers wrapped by wrapAsync have
// no name, so \"who may call it\" is read from the named middleware in front
// (isLoggedIn, adminGuard) and, for the admin and API routers, from the guard
// mounted on the whole router.
const fs = require(\"node:fs\");
const path = require(\"node:path\");

const ROOT = path.join(__dirname, \"..\", \"..\");
const GUARDS = /^(isLoggedIn|adminGuard|isAdmin|requireLogin)$/;

function mounts() {
  const source = fs.readFileSync(path.join(ROOT, \"src\", \"app.js\"), \"utf8\");
  const files = {};
  for (const m of source.matchAll(
    /const (\\w+Router) = require\\(\"\\.\\/routes\\/([\\w.-]+)\"\\)/g,
  ))
    files[m[1]] = m[2];
  const found = [];
  for (const m of source.matchAll(/app\\.use\\(\"([^\"]+)\",\\s*(\\w+Router)\\)/g)) {
    if (files[m[2]]) found.push({ prefix: m[1], file: files[m[2]] });
  }
  return found;
}

const join = (prefix, route) => {
  const p =
    `${prefix === \"/\" ? \"\" : prefix}${route === \"/\" ? \"\" : route}` || \"/\";
  return p.replace(/\\/+$/, \"\") || \"/\";
};

/** @returns {Array<{ method: string, path: string, guards: string[], file: string }>} */
function listRoutes() {
  const out = [];
  for (const { prefix, file } of mounts()) {
    const router = require(path.join(ROOT, \"src\", \"routes\", file));
    const wide = router.stack
      .filter(
        (l) =>
          !l.route && l.handle && l.handle.name && l.handle.name !== \"router\",
      )
      .map((l) => l.handle.name);
    for (const layer of router.stack) {
      if (!layer.route) continue;
      for (const method of Object.keys(layer.route.methods)) {
        // only the handlers that answer THIS method (a route can chain .get().post())
        const own = layer.route.stack.filter(
          (l) => !l.method || l.method === method,
        );
        const guards = [
          ...new Set([
            ...wide,
            ...own.map((l) => l.handle.name).filter((n) => GUARDS.test(n)),
          ]),
        ];
        out.push({
          method: method.toUpperCase(),
          path: join(prefix, layer.route.path),
          guards,
          file,
        });
      }
    }
  }
  return out.sort((a, b) =>
    a.path === b.path
      ? a.method.localeCompare(b.method)
      : a.path.localeCompare(b.path),
  );
}

module.exports = { listRoutes, mounts };

// Only same-site paths may be used as a post-login destination. Anything that a
// browser could read as another host (//evil.com, /\\evil.com, https://...,
// javascript:, control characters) is refused.
const BASE = \"http://dimora.invalid\";
const MAX_LENGTH = 2048;
// The auth pages themselves: going back to them after login would be a loop.
const AUTH_PATHS = new Set([\"/login\", \"/signup\", \"/logout\"]);

/**
 * Returns `value` when it is a safe local path, otherwise `fallback`.
 * Never throws.
 */
function safeRedirectPath(value, fallback = \"/\") {
  if (typeof value !== \"string\") return fallback;
  if (value.length === 0 || value.length > MAX_LENGTH) return fallback;
  // Must be an absolute path on this site: one leading slash, not two, and
  // no backslash (browsers treat \"\\\" like \"/\").
  if (value[0] !== \"/\" || value[1] === \"/\" || value[1] === \"\\\\\")
    return fallback;
  // eslint-disable-next-line no-control-regex
  if (/[\\u0000-\\u001f\\u007f\\\\]/.test(value)) return fallback;
  let url;
  try {
    url = new URL(value, BASE);
  } catch {
    return fallback;
  }
  if (url.origin !== BASE) return fallback;
  // \"/..//evil.com\" stays on this site in a browser, but its normalised path
  // starts with \"//\", which some code would pass on as a network-path reference.
  if (url.pathname.startsWith(\"//\")) return fallback;
  if (AUTH_PATHS.has(url.pathname.replace(/\\/+$/, \"\") || \"/\")) return fallback;
  return value;
}

module.exports = { safeRedirectPath };

// Search keys (P05-T01): lower-case, accent-free copies of a listing's city,
// state and country, so \"São Paulo\", \"sao paulo\" and \"SAO  PAULO\" are the same
// place and an index can answer \"starts with\" questions. The same function
// builds the stored keys and the keys a visitor's search is compared with, so
// the two can never disagree.

const MAX_KEY = 100;
const MAX_PARTS = 3;
const MAX_PART = 60;

/**
 * \"  São  Paulo! \" -> \"sao paulo\". Letters, digits and single spaces survive;
 * punctuation and hyphens become spaces (\"Île-de-France\" -> \"ile de france\").
 * Latin accents are removed; the combining vowel signs of other scripts are
 * kept (\"पुणे\" stays \"पुणे\"), or a Hindi city name would fall apart.
 */
function normaliseToken(value) {
  if (typeof value !== \"string\") return \"\";
  return value
    .normalize(\"NFKD\")
    .replace(/[\\u0300-\\u036f]/g, \"\")
    .toLowerCase()
    .replace(/[^\\p{L}\\p{M}\\p{N}\\s]/gu, \" \")
    .replace(/\\s+/g, \" \")
    .trim()
    .slice(0, MAX_KEY);
}

/**
 * Keys for one place.
 * @returns {{ cityKey: string, stateKey: string, countryKey: string, locationKey: string }}
 * `locationKey` joins the non-empty parts with \"|\" (\"panaji|goa|india\"): a
 * stable id for a destination, for grouping and (later) suggestions.
 */
function locationKeys({ city, state, country } = {}) {
  const cityKey = normaliseToken(city);
  const stateKey = normaliseToken(state);
  const countryKey = normaliseToken(country);
  return {
    cityKey,
    stateKey,
    countryKey,
    locationKey: [cityKey, stateKey, countryKey].filter(Boolean).join(\"|\"),
  };
}

/**
 * Keys for a listing document or plain object. A listing that has no
 * structured address yet (written before the wizard) falls back to its old
 * free-text `location` (\"Panaji, Goa\": the first part is the city) and `country`.
 */
function keysForListing(listing) {
  const doc = listing || {};
  const get = (path) => (typeof doc.get === \"function\" ? doc.get(path) : undefined);
  const address = doc.address || {};
  let city = get(\"address.city\") ?? address.city ?? get(\"location\") ?? doc.location;
  let state = get(\"address.state\") ?? address.state;
  // \"Panaji, Goa\" typed into one field: the first part is the city and, when
  // there is no state of its own, the second is the state.
  if (typeof city === \"string\" && city.includes(\",\")) {
    const [first, second] = city.split(\",\").map((part) => part.trim());
    city = first;
    if (!state && second) state = second;
  }
  return locationKeys({
    city,
    state,
    country: get(\"address.country\") ?? address.country ?? get(\"country\") ?? doc.country,
  });
}

/**
 * What a visitor typed in the destination box, as up to three normalised parts:
 * \"Panaji, Goa\" -> [\"panaji\", \"goa\"]. Each part must start a city, state or
 * country key. Empty parts are dropped.
 */
function destinationParts(input) {
  if (typeof input !== \"string\") return [];
  return input
    .split(\",\")
    .map((part) => normaliseToken(part).slice(0, MAX_PART))
    .filter(Boolean)
    .slice(0, MAX_PARTS);
}

/** Escapes a string for use inside a regular expression. */
function escapeRegex(text) {
  return String(text).replace(/[.*+?^${}()|[\\]\\\\/-]/g, \"\\\\$&\");
}

module.exports = {
  normaliseToken,
  locationKeys,
  keysForListing,
  destinationParts,
  escapeRegex,
  MAX_PARTS,
};

// Links for the listings page (P05-T02). Every link on the page (search form,
// filters, sort, pagination) is made here from the page's validated state, so
// the query is never lost and never invented.
const ORDER = [
  \"dest\",
  \"radius\",
  \"in\",
  \"out\",
  \"guests\",
  \"flex\",
  \"category\",
  \"minPrice\",
  \"maxPrice\",
  \"type\",
  \"amenities\",
  \"access\",
  \"minRating\",
  \"sort\",
  \"purpose\",
  \"page\",
  \"keywords\",
  \"bedrooms\",
  \"roomType\",
  \"instantBook\",
];

const isEmpty = (value) =>
  value === undefined ||
  value === null ||
  value === \"\" ||
  (Array.isArray(value) && value.length === 0);

/**
 * The parameters of a link: `state` with `changes` applied (`undefined`, `\"\"`
 * or [] removes one), in a fixed order, page 1 left out. Changing anything
 * but `page` goes back to page 1.
 * @returns {Array<[string, string]>}
 */
function queryPairs(state = {}, changes = {}) {
  const merged = { ...state, ...changes };
  if (!Object.hasOwn(changes, \"page\")) delete merged.page;
  if (merged.page === 1 || merged.page === \"1\") delete merged.page;
  const pairs = [];
  for (const name of ORDER) {
    const value = merged[name];
    if (isEmpty(value)) continue;
    for (const item of Array.isArray(value) ? value : [value]) {
      pairs.push([name, String(item)]);
    }
  }
  return pairs;
}

/** \"/listings?dest=Goa&guests=2\" (just \"/listings\" when nothing is set). */
function listingsUrl(state, changes) {
  const params = new URLSearchParams(queryPairs(state, changes));
  const text = params.toString();
  return text ? `/listings?${text}` : \"/listings\";
}

/** Pairs for hidden inputs that carry the rest of the state through a form. */
function hiddenFields(state, except = []) {
  const skip = new Set([...except, \"page\"]);
  return queryPairs(state).filter(([name]) => !skip.has(name));
}

module.exports = { queryPairs, listingsUrl, hiddenFields, ORDER };

// Search-engine facing pieces (P18-T05): canonical URLs, the robots.txt text,
// the sitemap, and which pages must not be indexed.
//
// Every absolute URL is made from the configured public address
// (APP_BASE_URL), never from the Host header of the request, so a forged
// header cannot put another site's address into a page or the sitemap.

// Pages that belong to one signed-in person, to staff, or to the machinery of
// the site. robots.txt asks crawlers to stay out of them and the page itself
// says \"noindex\" (robots.txt alone does not remove a page from a search engine).
const PRIVATE_PREFIXES = Object.freeze([
  \"/account\",
  \"/admin\",
  \"/api\",
  \"/compare\",
  \"/conversations\",
  \"/host\",
  \"/login\",
  \"/notifications\",
  \"/reports\",
  \"/signup\",
  \"/trips\",
  \"/wishlists\",
]);

// Pages under /listings that are not the public listing page.
const PRIVATE_LISTING_PATH =
  /^\\/listings\\/(new|[^/]+\\/(checkout|edit|images)(\\/|$))/;

// The most links a sitemap file may hold is 50,000; this is far below it and
// keeps the query small. A bigger site needs a sitemap index.
const SITEMAP_LIMIT = 5000;

const STATIC_PAGES = Object.freeze([
  \"/\",
  \"/listings\",
  \"/about\",
  \"/privacy\",
  \"/terms\",
]);

const trimSlash = (base) => String(base || \"\").replace(/\\/+$/, \"\");

/** \"https://dimora.example.com\" + \"/listings/1\" -> one absolute URL. */
function absoluteUrl(base, pathname = \"/\") {
  const path = String(pathname).startsWith(\"/\") ? pathname : `/${pathname}`;
  return `${trimSlash(base)}${path}`;
}

/** True for a path that must not be indexed (private, staff, or machinery). */
function isPrivatePath(pathname) {
  const path = String(pathname || \"/\");
  if (PRIVATE_LISTING_PATH.test(path)) return true;
  return PRIVATE_PREFIXES.some(
    (prefix) => path === prefix || path.startsWith(`${prefix}/`),
  );
}

/**
 * The one URL a page is known by. The query string is dropped (dates, guests,
 * filters and sort all show the same stays), except `page` on the results
 * list, because page 2 is a different set of stays. A private page, and any
 * page that did not answer 200, has none.
 */
function canonicalUrl(base, { path = \"/\", query = {}, status = 200 } = {}) {
  if (status !== 200 || isPrivatePath(path)) return \"\";
  const clean = path.length > 1 ? path.replace(/\\/+$/, \"\") : path;
  if (clean === \"/listings\") {
    const page = Number.parseInt(
      Array.isArray(query.page) ? query.page[0] : query.page,
      10,
    );
    if (Number.isInteger(page) && page > 1 && page <= 10000) {
      return absoluteUrl(base, `/listings?page=${page}`);
    }
  }
  return absoluteUrl(base, clean);
}

/** The value of <meta name=\"robots\">, or \"\" to say nothing (index, follow). */
function robotsMeta({ path = \"/\", status = 200 } = {}) {
  return status !== 200 || isPrivatePath(path) ? \"noindex, nofollow\" : \"\";
}

/** The text of /robots.txt. */
function robotsTxt(base) {
  const lines = [\"User-agent: *\"];
  for (const prefix of PRIVATE_PREFIXES) lines.push(`Disallow: ${prefix}/`);
  lines.push(\"Disallow: /listings/new\");
  lines.push(\"Disallow: /listings/*/checkout\");
  lines.push(\"Disallow: /listings/*/edit\");
  lines.push(\"Disallow: /listings/*/images\");
  lines.push(\"\", `Sitemap: ${absoluteUrl(base, \"/sitemap.xml\")}`, \"\");
  return lines.join(\"\\n\");
}

const xmlEscape = (text) =>
  String(text)
    .replace(/&/g, \"&amp;\")
    .replace(/</g, \"&lt;\")
    .replace(/>/g, \"&gt;\")
    .replace(/\"/g, \"&quot;\")
    .replace(/'/g, \"&apos;\");

/** \"2026-10-29\" from a Date (UTC), or \"\" for anything else. */
function lastmod(value) {
  const date = value instanceof Date ? value : new Date(value);
  return Number.isNaN(date.getTime()) ? \"\" : date.toISOString().slice(0, 10);
}

/**
 * @param {string} base  the public address
 * @param {Array<{ _id: any, updatedAt?: Date }>} listings  public listings only
 * @returns {string} sitemap XML
 */
function sitemapXml(base, listings = []) {
  const rows = STATIC_PAGES.map((path) => ({ loc: absoluteUrl(base, path) }));
  for (const listing of listings.slice(
    0,
    SITEMAP_LIMIT - STATIC_PAGES.length,
  )) {
    if (!listing || !listing._id) continue;
    rows.push({
      loc: absoluteUrl(base, `/listings/${listing._id}`),
      lastmod: lastmod(listing.updatedAt),
    });
  }
  const body = rows
    .map(
      (row) =>
        `  <url><loc>${xmlEscape(row.loc)}</loc>${row.lastmod ? `<lastmod>${row.lastmod}</lastmod>` : \"\"}</url>`,
    )
    .join(\"\\n\");
  return `<?xml version=\"1.0\" encoding=\"UTF-8\"?>\\n<urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\">\\n${body}\\n</urlset>\\n`;
}

module.exports = {
  PRIVATE_PREFIXES,
  SITEMAP_LIMIT,
  STATIC_PAGES,
  absoluteUrl,
  isPrivatePath,
  canonicalUrl,
  robotsMeta,
  robotsTxt,
  sitemapXml,
};

// schema.org JSON-LD for a public listing page (P04-T07). Returned as the
// text of a <script type=\"application/ld+json\"> element. The JSON is made safe
// to put inside HTML: < > & and the line separators are written as \\u escapes,
// so a title like \"</script><script>\" cannot end the element.
//
// Only what is already public goes in: the street address and the exact point
// are NOT included (the city, state and country are).
const { imageUrl } = require(\"./imageUrl\");
const { formatMoney } = require(\"./money\");
const { amenityLabel } = require(\"./amenities\");

const MAX_DESCRIPTION = 500;
const MAX_IMAGES = 10;

function safeJson(value) {
  return JSON.stringify(value)
    .replace(/</g, \"\\\\u003c\")
    .replace(/>/g, \"\\\\u003e\")
    .replace(/&/g, \"\\\\u0026\")
    .replace(/\\u2028/g, \"\\\\u2028\")
    .replace(/\\u2029/g, \"\\\\u2029\");
}

const clip = (text, max) => {
  const clean = String(text ?? \"\")
    .replace(/\\s+/g, \" \")
    .trim();
  return clean.length > max ? `${clean.slice(0, max - 1).trimEnd()}…` : clean;
};

/**
 * @param {object} listing  a Listing document or plain object
 * @param {object} extras   { gallery: [{url}], rating: { average, count } }
 * @returns {string} JSON text, safe inside a script element
 */
function listingJsonLd(listing, { gallery = [], rating } = {}) {
  const address = listing.address || {};
  const data = {
    \"@context\": \"https://schema.org\",
    \"@type\": \"LodgingBusiness\",
    name: clip(listing.title, 200),
  };
  const description = clip(listing.description, MAX_DESCRIPTION);
  if (description) data.description = description;

  const images = gallery
    .filter((item) => item && item.url)
    .slice(0, MAX_IMAGES)
    .map((item) => imageUrl(item.url, \"full\"));
  if (images.length) data.image = images;

  const place = {
    \"@type\": \"PostalAddress\",
    addressLocality: address.city || undefined,
    addressRegion: address.state || undefined,
    addressCountry: address.country || listing.country || undefined,
  };
  if (place.addressLocality || place.addressRegion || place.addressCountry) {
    data.address = place;
  }

  const nightly = listing.pricing && listing.pricing.nightlyMinor;
  if (Number.isInteger(nightly) && nightly > 0) {
    data.priceRange = `${formatMoney(nightly, listing.pricing.currency || \"INR\")} per night`;
  }

  const features = (listing.amenities || [])
    .map(amenityLabel)
    .filter(Boolean)
    .map((name) => ({
      \"@type\": \"LocationFeatureSpecification\",
      name,
      value: true,
    }));
  if (features.length) data.amenityFeature = features;

  if (rating && rating.count > 0 && rating.average !== null) {
    data.aggregateRating = {
      \"@type\": \"AggregateRating\",
      ratingValue: rating.average,
      reviewCount: rating.count,
      bestRating: 5,
      worstRating: 1,
    };
  }
  return safeJson(data);
}

module.exports = { listingJsonLd, safeJson };

// Who may see a listing page (P04-T05). A soft-deleted listing is gone for
// everyone; a draft or unpublished one is visible to its host and to admins;
// a published one to everybody. Public queries use `publicListingFilter`.

/** Mongo filter for the public pages: published and not soft-deleted. */
function publicListingFilter() {
  return { status: \"published\", deletedAt: null };
}

/** Published and not deleted (one document in memory). */
function isPublic(listing) {
  return (
    Boolean(listing) && listing.status === \"published\" && !listing.deletedAt
  );
}

module.exports = { publicListingFilter, isPublic };

