        page: text(req.query.page),
      });
      res.render(\"admin/reports\", { pageTitle: \"Reports\", result });
    };

    module.exports.report = async (req, res) => {
      const page = await reportQueue.getReport(req.params.id);
      if (!page) throw new NotFoundError(\"That report does not exist.\");
      res.render(\"admin/report\", { pageTitle: `Report ${page.report.id.slice(-6)}`, page });
    };

    function reportBack(id) {
      return mongoose.isValidObjectId(id) ? `/admin/reports/${id}` : \"/admin/reports\";
    }

    async function refusingReport(back, work) {
      try {
        return await work();
      } catch (err) {
        if (err instanceof reportQueue.ReportAdminError || err instanceof reviewModeration.ReviewModerationError) {
          throw new AdminRefusal(err.message, back);
        }
        throw err;
      }
    }

    function closeWith(outcome, verb) {
      return async (req) => {
        const { id } = req.params;
        const done = await refusingReport(reportBack(id), () =>
          reportQueue.closeReport({
            admin: req.user,
            id,
            outcome,
            note: text(req.body && req.body.note),
            closeOthers: Boolean(req.body && req.body.closeOthers === \"1\"),
          }),
        );
        return {
          audit: { action: `report.${outcome}`, targetType: \"report\", targetId: done.report._id, reason: done.note, details: done.details },
          redirectTo: \"/admin/reports\",
          flash: done.closedOthers > 0 ? `Report ${verb}, with ${done.closedOthers} other open report${done.closedOthers === 1 ? \"\" : \"s\"} about the same thing.` : `Report ${verb}.`,
        };
      };
    }

    // Wrapped in auditedMutation by src/routes/admin.js.
    module.exports.resolveReport = closeWith(\"resolve\", \"resolved\");
    module.exports.dismissReport = closeWith(\"dismiss\", \"dismissed\");

    // `from` is the report page the moderator came from (a valid id only).
    const backFrom = (req) => (req.body && typeof req.body.from === \"string\" ? reportBack(req.body.from) : \"/admin/reports\");

    module.exports.hideReview = async (req) => {
      const { id } = req.params;
      const done = await refusingReport(backFrom(req), () =>
        reviewModeration.hideReview({ admin: req.user, id, reason: text(req.body && req.body.reason) }),
      );
      return {
        audit: { action: \"review.hide\", targetType: \"review\", targetId: done.review._id, reason: done.reason, details: done.details },
        redirectTo: backFrom(req),
        flash: \"The review is hidden and no longer counts in the listing's rating.\",
      };
    };

    module.exports.restoreReview = async (req) => {
      const { id } = req.params;
      const done = await refusingReport(backFrom(req), () =>
        reviewModeration.restoreReview({ admin: req.user, id, reason: text(req.body && req.body.reason) }),
      );
      return {
        audit: { action: \"review.restore\", targetType: \"review\", targetId: done.review._id, reason: done.reason, details: done.details },
        redirectTo: backFrom(req),
        flash: \"The review is visible again and counts in the listing's rating.\",
      };
    };

    // Host availability calendar (P07-T03): /host/listings/:id/calendar.
    // Every route is behind authorize(\"listing:edit\") (src/routes/host.js), so
    // only the listing's host gets here and the listing is on req.listing.
    const availability = require(\"../services/availability\");
    const { formatMonthKey } = require(\"../utils/dates\");
    const {
      ConflictError,
      NotFoundError,
      ValidationError,
    } = require(\"../utils/errors\");

    const calendarUrl = (id, month) =>
      `/host/listings/${id}/calendar${month ? `?month=${month}` : \"\"}`;

    // Only a live listing has guests to plan around: a draft is still being
    // written and a suspended one is out of the host's hands.
    function guardListing(req, res) {
      const listing = req.listing;
      if (listing.deletedAt) throw new NotFoundError(\"That listing does not exist.\");
      if ([\"published\", \"unpublished\"].includes(listing.status)) return true;
      if (listing.status === \"draft\") {
        req.flash(
          \"error\",
          \"Finish and publish this listing before you manage its availability.\",
        );
        res.redirect(`/host/listings/${listing._id}`);
      } else {
        req.flash(\"error\", \"This listing is suspended, so its calendar is closed.\");
        res.redirect(`/host/listings/${listing._id}/status`);
      }
      return false;
    }

    async function renderCalendar(
      req,
      res,
      { month, status = 200, errors = {}, values = {} } = {},
    ) {
      const listing = req.listing;
      const calendar = await availability.monthView(listing, month);
      const { runs, truncated } = await availability.listBlocks(listing);
      res.status(status).render(\"host/calendar.ejs\", {
        listing,
        calendar,
        runs,
        truncated,
        errors,
        values,
        noteMaxLength: availability.NOTE_MAX_LENGTH,
        pageTitle: `Availability: ${listing.title}`,
        pageDescription: \"Block and unblock the nights your place is not available.\",
      });
    }

    // The month to go back to after a change: the one that holds the first night.
    function monthAfter(from, fallback) {
      return from ? formatMonthKey(from) : fallback;
    }

    module.exports.show = async (req, res) => {
      if (!guardListing(req, res)) return;
      const month = typeof req.query.month === \"string\" ? req.query.month : undefined;
      await renderCalendar(req, res, { month });
    };

    module.exports.block = async (req, res) => {
      if (!guardListing(req, res)) return;
      const body = req.body ?? {};
      const month = typeof body.month === \"string\" ? body.month : undefined;
      let result;
      try {
        result = await availability.blockDates(req.listing, body, {
          userId: req.user._id,
        });
      } catch (err) {
        if (err instanceof ValidationError || err instanceof ConflictError) {
          return renderCalendar(req, res, {
            month,
            status: err.statusCode,
            errors: { block: err.message },
            values: body,
          });
        }
        throw err;
      }
      req.flash(
        \"success\",
        result.changed
          ? `Blocked ${result.blocked} ${result.blocked === 1 ? \"night\" : \"nights\"}.${
              result.alreadyBlocked
                ? ` ${result.alreadyBlocked} ${result.alreadyBlocked === 1 ? \"night was\" : \"nights were\"} already blocked.`
                : \"\"
            }`
          : \"Those nights were already blocked.\",
      );
      res.redirect(calendarUrl(req.listing._id, monthAfter(result.from, month)));
    };

    module.exports.unblock = async (req, res) => {
      if (!guardListing(req, res)) return;
      const body = req.body ?? {};
      const month = typeof body.month === \"string\" ? body.month : undefined;
      let result;
      try {
        result = await availability.unblockDates(req.listing, body);
      } catch (err) {
        if (err instanceof ValidationError) {
          return renderCalendar(req, res, {
            month,
            status: err.statusCode,
            errors: { unblock: err.message },
            values: { unblockFrom: body.from, unblockThrough: body.through },
          });
        }
        throw err;
      }
      req.flash(
        \"success\",
        result.released
          ? `Unblocked ${result.released} ${result.released === 1 ? \"night\" : \"nights\"}.`
          : \"Nothing was blocked between those dates.\",
      );
      res.redirect(calendarUrl(req.listing._id, monthAfter(result.from, month)));
    };

    // GET /api/listings/:id/availability?from=YYYY-MM-DD&to=YYYY-MM-DD (P07-T04)
    const Listing = require(\"../models/listing\");
    const { can } = require(\"../policies\");
    const { isPublic } = require(\"../utils/visibility\");
    const { NotFoundError } = require(\"../utils/errors\");
    const { getAvailability } = require(\"../services/availabilityApi\");

    module.exports.show = async (req, res) => {
      const listing = await Listing.findById(req.params.id).select(
        \"owner status deletedAt timezone checkInTime minNights maxNights capacity advanceNoticeHours sameDayCutoffTime\",
      );
      // Same visibility as the page: public listings for everybody, a draft or
      // unpublished one only for its host; anything else looks like it is missing.
      const visible =
        listing &&
        !listing.deletedAt &&
        (isPublic(listing) || can(\"listing:edit\", req.user, listing));
      if (!visible) throw new NotFoundError(\"That listing does not exist.\");

      const payload = await getAvailability(listing, req.query, {
        timeZone: listing.timezone || undefined,
      });
      // Availability changes with every booking: never serve a cached copy.
      res.set(\"Cache-Control\", \"no-store\");
      res.json(payload);
    };

    // Checkout (P08-T03): GET/POST /listings/:id/checkout?in&out&guests
    //
    // GET  shows the stay, the rules, the cancellation terms and the final price
    //      breakdown, with a hidden idempotency key and the total the guest is
    //      about to confirm.
    // POST sends that stay, that total and that key to reservations.create. If the
    //      real price differs from the confirmed total (PriceChangedError) the page
    //      is drawn again with the differences highlighted and a confirmation box
    //      that must be ticked. Nothing is booked in that case.
    //
    // Nothing here prices anything or decides availability: quoteService (the same
    // call as the quote API) and reservations.create do, so the total shown is the
    // total stored.
    const crypto = require(\"node:crypto\");
    const { ensureVerifiedEmail } = require(\"../middleware/verified\");
    const Listing = require(\"../models/listing\");
    const reservationService = require(\"../services/reservations\");
    const { getQuote } = require(\"../services/quoteService\");
    const listingStats = require(\"../services/listingStats\");
    const { buildCheckoutView } = require(\"../services/checkout\");
    const { isPublic } = require(\"../utils/visibility\");
    const { isActiveUser, sameId } = require(\"../policies/shared\");
    const {
      ForbiddenError,
      NotFoundError,
      ValidationError,
      ConflictError,
      PriceChangedError,
    } = require(\"../utils/errors\");

    const GENERIC = \"validation_error\";

    const newKey = () => crypto.randomBytes(16).toString(\"hex\"); // 32 hex characters

    const listingPath = (id, params) => {
      const query = params ? new URLSearchParams(params).toString() : \"\";
      return `/listings/${id}${query ? `?${query}` : \"\"}`;
    };

    const checkoutPath = (id, stay) =>
      `/listings/${id}/checkout?${new URLSearchParams({ in: stay.in, out: stay.out, guests: stay.guests }).toString()}`;

    // Where a guest lands after booking. The trips page (P09-T01) will replace it.
    const confirmationPath = (reservation) => listingPath(reservation.listing);

    const text = (value) => (typeof value === \"string\" ? value : \"\");

    async function loadBookable(id, user) {
      const listing = await Listing.findById(id);
      if (!listing || !isPublic(listing) || !listing.owner) {
        throw new NotFoundError(\"That place is not available for booking.\");
      }
      if (!isActiveUser(user)) {
        throw new ForbiddenError(\"Your account cannot make bookings.\");
      }
      if (sameId(listing.owner, user._id)) {
        throw new ForbiddenError(\"You cannot book your own listing.\");
      }
      return listing;
    }

    function render(res, listing, status, view) {
      res.set(\"Cache-Control\", \"no-store\");
      res.status(status).render(\"checkout/show.ejs\", {
        pageTitle: `Confirm your stay at ${listing.title}`,
        pageDescription: \"Review your stay and the price before you book.\",
        checkout: view,
      });
    }

    module.exports.show = async (req, res) => {
      if (!ensureVerifiedEmail(req, res)) return; // P02-T05
      const listing = await loadBookable(req.params.id, req.user);
      let payload;
      try {
        payload = await getQuote(listing, req.query);
      } catch (err) {
        if (err instanceof ValidationError && err.fields) {
          req.flash(
            \"error\",
            Object.values(err.fields)[0] || \"Please choose your dates first.\",
          );
          return res.redirect(listingPath(listing._id));
        }
        throw err;
      }
      if (!payload.bookable) {
        // e.g. the nights were taken while the guest was on the listing page.
        req.flash(\"error\", payload.problems[0].message);
        return res.redirect(listingPath(listing._id, { guests: payload.guests }));
      }
      await listingStats.recordCheckoutStart(req, listing); // approximate; never fails the page
      return render(
        res,
        listing,
        200,
        buildCheckoutView(listing, payload, { idempotencyKey: newKey() }),
      );
    };

    module.exports.submit = async (req, res) => {
      if (!ensureVerifiedEmail(req, res)) return; // P02-T05
      const body = req.body && typeof req.body === \"object\" ? req.body : {};
      const stay = {
        in: text(body.in),
        out: text(body.out),
        guests: text(body.guests),
      };
      const key = text(body.idempotencyKey);
      const expected = text(body.expectedTotalMinor);
      const listing = await loadBookable(req.params.id, req.user);

      // A browser that does not send the confirmed total cannot book: the server
      // would have nothing to compare the price with.
      if (!/^\\d{1,15}$/.test(expected)) {
        req.flash(
          \"error\",
          \"The booking page was out of date. Please check the details and confirm again.\",
        );
        return res.redirect(listingPath(listing._id));
      }

      try {
        const { reservation } = await reservationService.create({
          guest: req.user,
          listing: listing._id,
          in: stay.in,
          out: stay.out,
          guests: stay.guests,
          expectedTotalMinor: expected,
          idempotencyKey: key,
        });
        const instant = reservation.status === \"confirmed\";
        const reference = String(reservation._id).slice(-8).toUpperCase();
        req.flash(
          \"success\",
          instant
            ? `You are booked. Your reference is ${reference}. (Simulation: no payment was taken.)`
            : `Your request was sent to the host, who has 24 hours to answer. Your reference is ${reference}. (Simulation: no payment was taken.)`,
        );
        return res.redirect(confirmationPath(reservation));
      } catch (err) {
        if (err instanceof PriceChangedError) {
          // Draw the page again with the new price; nothing was booked.
          const payload = await getQuote(listing, stay);
          if (!payload.bookable) {
            req.flash(\"error\", payload.problems[0].message);
            return res.redirect(listingPath(listing._id));
          }
          const view = buildCheckoutView(listing, payload, {
            previousTotalMinor: Number(expected),
            previousLines: text(body.previousLines),
            idempotencyKey: key,
          });
          return render(res, listing, 409, view);
        }
        if (err instanceof ConflictError && err.code === \"nights_unavailable\") {
          req.flash(
            \"error\",
            \"Some of those nights were just taken. Please choose other dates.\",
          );
          return res.redirect(listingPath(listing._id, { guests: stay.guests }));
        }
        if (err instanceof ConflictError && err.code === \"idempotency_key_reused\") {
          req.flash(\"error\", err.message);
          return res.redirect(checkoutPath(listing._id, stay));
        }
        // A booking rule that changed while the guest was on the page (notice,
        // same-day cut-off, stay length): its own message, back to the listing.
        if (err instanceof ValidationError && err.code && err.code !== GENERIC) {
          req.flash(\"error\", err.message);
          return res.redirect(listingPath(listing._id));
        }
        throw err;
      }
    };

    // GET /compare (P10-T03). Public: it shows only what the listing pages show,
    // and the link can be shared. The price depends on today's availability, so
    // the page is never cached.
    const service = require(\"../services/compare\");

    module.exports.show = async (req, res) => {
      const result = await service.compare({ query: req.query });
      res.set(\"Cache-Control\", \"no-store\");
      res.render(\"compare/index.ejs\", {
        ...result,
        pageTitle: \"Compare stays\",
        pageDescription: \"Compare prices, rooms and amenities of the stays you shortlisted.\",
      });
    };

    // Messages (P11-T02): JSON endpoints under /api and three small pages (the
    // \"Contact host\" button, the inbox list, one thread, the reply form). Everything works on the signed-in member's own
    // conversations; the service answers 404 for anyone else's.
    const conversations = require(\"../services/conversations\");
    const { AppError, ValidationError } = require(\"../utils/errors\");

    const str = (value) => (typeof value === \"string\" ? value : undefined);

    function needLogin(req) {
      if (!req.user) {
        throw new AppError(401, \"Please log in.\", { code: \"unauthenticated\" });
      }
    }
    const noStore = (res) => res.set(\"Cache-Control\", \"no-store\");

    // ---- JSON (/api) ----------------------------------------------------------

    module.exports.apiList = async (req, res) => {
      needLogin(req);
      noStore(res);
      res.json(await conversations.listFor({}, req.user, { page: str(req.query.page) }));
    };

    module.exports.apiThread = async (req, res) => {
      needLogin(req);
      noStore(res);
      res.json(
        await conversations.thread({}, req.user, req.params.id, {
          before: str(req.query.before),
        }),
      );
    };

    module.exports.apiSend = async (req, res) => {
      needLogin(req);
      noStore(res);
      const message = await conversations.send(
        {},
        req.user,
        req.params.id,
        req.body && req.body.body,
      );
      res.status(201).json({ message });
    };

    function started({ conversation, created }, res) {
      const id = String(conversation._id);
      res
        .status(created ? 201 : 200)
        .json({ conversation: { id, url: `/conversations/${id}` } });
    }

    module.exports.apiStartForListing = async (req, res) => {
      needLogin(req);
      noStore(res);
      started(await conversations.startForListing({}, req.user, req.params.id), res);
    };

    module.exports.apiStartForReservation = async (req, res) => {
      needLogin(req);
      noStore(res);
      started(
        await conversations.startForReservation({}, req.user, req.params.id),
        res,
      );
    };

    // ---- Pages ----------------------------------------------------------------

    /** POST /listings/:id/contact -> the conversation page. */
    module.exports.contact = async (req, res) => {
      const { conversation } = await conversations.startForListing(
        {},
        req.user,
        req.params.id,
      );
      res.redirect(`/conversations/${conversation._id}`);
    };

    /** GET /messages?page= : the member's conversations (P11-T03). */
    module.exports.inbox = async (req, res) => {
      const list = await conversations.listFor({}, req.user, {
        page: str(req.query.page),
      });
      noStore(res);
      res.render(\"conversations/index.ejs\", {
        ...list,
        pageTitle: \"Messages\",
        pageDescription: \"Your conversations with hosts and guests.\",
      });
    };

    /** GET /conversations/:id */
    module.exports.show = async (req, res) => {
      const before = str(req.query.before);
      const data = await conversations.thread({}, req.user, req.params.id, {
        before,
      });
      noStore(res); // private messages
      res.render(\"conversations/show.ejs\", {
        ...data,
        // Only the newest page is kept current by polling; an older page is not.
        live: !before,
        pageTitle: `Messages: ${data.conversation.listingTitle}`,
        pageDescription: \"Your messages.\",
      });
    };

    /** POST /conversations/:id/messages (the reply form) */
    module.exports.sendForm = async (req, res) => {
      const back = `/conversations/${encodeURIComponent(req.params.id)}`;
      try {
        await conversations.send({}, req.user, req.params.id, req.body && req.body.body);
      } catch (err) {
        if (!(err instanceof ValidationError)) throw err;
        req.flash(\"error\", err.message);
      }
      res.redirect(back);
    };

    // Email confirmation and password reset (P02-T05). The services decide; this
    // only reads the form, picks the page and writes the flash text.
    //
    //   GET  /verify-email/:token   page with a button (does NOT use the token: a
    //                               mail scanner that opens links cannot burn it)
    //   POST /verify-email          uses the token
    //   GET  /verify-email/needed   why you are here and \"send me the link again\"
    //   POST /verify-email/resend   signed-in members, throttled
    //   GET/POST /forgot-password   always the same answer
    //   GET  /reset-password/:token page with the form (does not use the token)
    //   POST /reset-password        sets the password
    const emailAuth = require(\"../services/emailAuth\");
    const { TOKEN_PATTERN, EmailThrottledError, peek } = require(\"../services/emailTokens\");
    const { forgotPasswordSchema, resetPasswordSchema, PASSWORD_MIN } = require(\"../validation\");

    const JOI = { abortEarly: false, stripUnknown: true, errors: { wrap: { label: false } } };
    const firstMessages = (error) => [...new Set(error.details.map((d) => d.message))].join(\" \");

    const FORGOT_ANSWER =
      \"If an account uses that address, we have sent it a link to reset the password. The link works once, for one hour.\";
    const SEND_FAILED = \"We could not send the email just now. Please try again in a few minutes.\";

    function logFailure(req, err, what) {
      const log = req.app.locals.logger;
      if (log && log.error) log.error({ err: { name: err && err.name, message: err && err.message } }, what);
    }

    function invalidLink(res, kind) {
      return res.status(400).render(\"users/linkInvalid.ejs\", {
        pageTitle: \"This link does not work\",
        kind,
      });
    }

    const tokenParam = (req) => (TOKEN_PATTERN.test(String(req.params.token)) ? String(req.params.token) : null);

    // ---- confirm the address ----------------------------------------------------

    module.exports.showVerify = async (req, res) => {
      const raw = tokenParam(req);
      const token = raw && (await peek({ raw, purpose: \"verify_email\" }));
      if (!token) return invalidLink(res, \"verify\");
      res.render(\"users/verifyEmail.ejs\", { pageTitle: \"Confirm your email\", token: raw });
    };

    module.exports.verify = async (req, res) => {
      const raw = req.body && typeof req.body.token === \"string\" ? req.body.token : \"\";
      const result = await emailAuth.verifyEmail({ raw });
      if (!result.ok) return invalidLink(res, \"verify\");
      req.flash(\"success\", \"Your email address is confirmed. You can publish listings and book stays.\");
      res.redirect(req.user ? \"/account\" : \"/login\");
    };

    module.exports.showNeeded = (req, res) => {
      if (req.user.emailVerifiedAt) {
        req.flash(\"success\", \"Your email address is already confirmed.\");
        return res.redirect(\"/account\");
      }
      res.render(\"users/verifyNeeded.ejs\", {
        pageTitle: \"Confirm your email\",
        email: req.user.email,
      });
    };

    module.exports.resend = async (req, res) => {
      try {
        const result = await emailAuth.sendVerification({
          user: req.user,
          emailService: req.app.locals.emailService,
          baseUrl: req.app.locals.appBaseUrl,
        });
        req.flash(
          \"success\",
          result.status === \"already_verified\"
            ? \"Your email address is already confirmed.\"
            : `We sent a confirmation link to ${req.user.email}. It is valid for 24 hours.`,
        );
      } catch (err) {
        if (err instanceof EmailThrottledError) req.flash(\"error\", err.message);
        else {
          logFailure(req, err, \"verification email failed\");
          req.flash(\"error\", SEND_FAILED);
        }
      }
      res.redirect(\"/verify-email/needed\");
    };

    // ---- forgot / reset password -------------------------------------------------

    module.exports.showForgot = (req, res) => {
      res.render(\"users/forgot.ejs\", {
        pageTitle: \"Forgot your password\",
        pageDescription: \"Ask for a link to choose a new Dimora password.\",
      });
    };

    module.exports.forgot = async (req, res) => {
      const { error, value } = forgotPasswordSchema.validate(req.body ?? {}, JOI);
      if (error) {
        req.flash(\"error\", firstMessages(error));
        return res.redirect(\"/forgot-password\");
      }
      try {
        await emailAuth.requestPasswordReset({
          email: value.email,
          emailService: req.app.locals.emailService,
          baseUrl: req.app.locals.appBaseUrl,
        });
      } catch (err) {
        // Throttled, or the provider failed: the visitor still gets the same answer,
        // so the form cannot be used to find out which addresses have accounts.
        if (!(err instanceof EmailThrottledError)) logFailure(req, err, \"password reset email failed\");
      }
      req.flash(\"success\", FORGOT_ANSWER);
      res.redirect(\"/login\");
    };

    module.exports.showReset = async (req, res) => {
      const raw = tokenParam(req);
      const user = raw && (await emailAuth.userForResetToken({ raw }));
      if (!user) return invalidLink(res, \"reset\");
      res.render(\"users/reset.ejs\", { pageTitle: \"Choose a new password\", token: raw, passwordMin: PASSWORD_MIN });
    };

    module.exports.reset = async (req, res) => {
      const body = req.body && typeof req.body === \"object\" ? req.body : {};
      const raw = typeof body.token === \"string\" && TOKEN_PATTERN.test(body.token) ? body.token : null;
      const user = raw && (await emailAuth.userForResetToken({ raw }));
      if (!user) return invalidLink(res, \"reset\");

      const { error, value } = resetPasswordSchema.validate(body, {
        ...JOI,
        context: { username: user.username, email: user.email },
      });
      if (error) {
        // The token is not used up by a form that did not pass the rules.
        req.flash(\"error\", firstMessages(error));
        return res.redirect(`/reset-password/${raw}`);
      }
      const result = await emailAuth.resetPassword({
        raw,
        newPassword: value.newPassword,
        emailService: req.app.locals.emailService,
      });
      if (!result.ok) return invalidLink(res, \"reset\");
      req.flash(\"success\", \"Your password was changed. Log in with the new password.\");
      res.redirect(\"/login\");
    };

    // The listing wizard (P04-T02): /host/listings/... Every step is a full-page
    // form post, so it works without JavaScript; each step saves the draft, and a
    // draft is invisible to the public until it is published at the end.
    const crypto = require(\"node:crypto\");
    const { ensureVerifiedEmail } = require(\"../middleware/verified\");
    const Listing = require(\"../models/listing\");
    const { loadHostListings, MAX_ROWS } = require(\"../services/hostListings\");
    const wizard = require(\"../services/wizard\");
    const { galleryOf, MAX_IMAGES } = require(\"../services/images\");
    const {
      geocodeAddress,
      LocationNotFoundError,
      GeocoderUnavailableError,
    } = require(\"../services/geocoding\");
    const { validateStep } = require(\"../validation/wizard\");
    const { evaluateReadiness } = require(\"../services/readiness\");
    const lifecycle = require(\"../services/lifecycle\");
    const nearby = require(\"../services/nearby\");
    const { NotFoundError, ValidationError } = require(\"../utils/errors\");
    const {
      PROPERTY_TYPES,
      ROOM_TYPES,
      VIBES,
      CANCELLATION_POLICIES,
      AMENITIES,
      ACCESSIBILITY_FEATURES,
    } = require(\"../config/constants\");

    const TOKEN = /^[0-9a-f-]{36}$/i;
    const stepUrl = (id, n) => `/host/listings/${id}/steps/${n}`;
    const statusUrl = (id) => `/host/listings/${id}/status`;

    function renderStep(
      res,
      { listing, n, values, errors = {}, status = 200, formError },
    ) {
      const step = wizard.stepByNumber(n);
      const steps = listing
        ? wizard.stepStatuses(listing)
        : wizard.STEPS.map((item) => ({
            ...item,
            complete: false,
            reachable: item.n === 1,
          }));
      res.status(status).render(\"host/step.ejs\", {
        listing,
        step,
        steps,
        values: values ?? (listing ? wizard.formValues(listing, n) : {}),
        errors,
        formError,
        lists: { PROPERTY_TYPES, ROOM_TYPES, VIBES, CANCELLATION_POLICIES, AMENITIES, ACCESSIBILITY_FEATURES },
        photoList: listing && n === 4 ? galleryOf(listing) : [],
        maxImages: MAX_IMAGES,
        readiness:
          listing && n === wizard.REVIEW_STEP ? evaluateReadiness(listing) : null,
        draftToken: listing ? undefined : crypto.randomUUID(),
        pageTitle: `${step.title} (step ${n} of ${wizard.STEPS.length})`,
        pageDescription: \"Add your place to Dimora, one short step at a time.\",
      });
    }

    // Only a draft can be worked on here; a published listing is edited elsewhere.
    function requireDraft(req, res) {
      if (req.listing.status === \"draft\") return true;
      req.flash(
        \"error\",
        \"This listing is already published. You can edit it here.\",
      );
      res.redirect(`/listings/${req.listing._id}/edit`);
      return false;
    }

    module.exports.newForm = (req, res) => renderStep(res, { n: 1 });

    module.exports.create = async (req, res) => {
      const { draftToken, ...body } = req.body ?? {};
      if (draftToken !== undefined && !TOKEN.test(String(draftToken))) {
        throw new ValidationError(\"That form has expired. Please start again.\");
      }
      const { value, errors } = validateStep(1, body);
      if (!value) {
        return renderStep(res, { n: 1, values: body, errors, status: 400 });
      }

      const draft = new Listing({
        status: \"draft\",
        owner: req.user._id,
        draftToken: draftToken ? String(draftToken).toLowerCase() : undefined,
      });
      wizard.applyStep(draft, 1, value);
      wizard.markStepDone(draft, 1);
      try {
        await draft.save();
      } catch (err) {
        // The same form was submitted twice: use the draft the first one made.
        if (err && err.code === 11000 && draftToken) {
          const first = await Listing.findOne({
            owner: req.user._id,
            draftToken: String(draftToken).toLowerCase(),
          });
          if (first) return res.redirect(stepUrl(first._id, 2));
        }
        throw err;
      }
      res.redirect(stepUrl(draft._id, 2));
    };

    // /host/listings/:id: carry on where the host left off.
    module.exports.resume = (req, res) => {
      if (req.listing.status !== \"draft\") {
        return res.redirect(`/listings/${req.listing._id}`);
      }
      res.redirect(
        stepUrl(req.listing._id, wizard.firstIncompleteStep(req.listing)),
      );
    };

    module.exports.showStep = (req, res) => {
      const n = wizard.parseStep(req.params.n);
      if (n === null) throw new NotFoundError(\"That step does not exist.\");
      if (!requireDraft(req, res)) return;
      if (!wizard.canOpenStep(req.listing, n)) {
        const target = wizard.firstIncompleteStep(req.listing);
        req.flash(\"error\", `Please finish step ${target} first.`);
        return res.redirect(stepUrl(req.listing._id, target));
      }
      renderStep(res, { listing: req.listing, n });
    };

    module.exports.saveStep = async (req, res) => {
      const n = wizard.parseStep(req.params.n);
      if (n === null || n === wizard.REVIEW_STEP) {
        throw new NotFoundError(\"That step does not exist.\");
      }
      const listing = req.listing;
      if (!requireDraft(req, res)) return;
      if (!wizard.canOpenStep(listing, n)) {
        const target = wizard.firstIncompleteStep(listing);
        req.flash(\"error\", `Please finish step ${target} first.`);
        return res.redirect(stepUrl(listing._id, target));
      }

      // The photos have their own forms; here \"Continue\" only checks there is one.
      if (n === 4) {
        if (galleryOf(listing).length < 1) {
          return renderStep(res, {
            listing,
            n,
            status: 400,
            formError: \"Add at least one photo before you continue.\",
          });
        }
        wizard.markStepDone(listing, n);
        await listing.save();
        return res.redirect(stepUrl(listing._id, n + 1));
      }

      const { value, errors } = validateStep(n, req.body);
      if (!value) {
        return renderStep(res, {
          listing,
          n,
          values: req.body,
          errors,
          status: 400,
        });
      }

      let geometry;
      if (n === 2 && wizard.addressChanged(listing, value)) {
        try {
          geometry = await geocodeAddress({
            location: wizard.addressQuery(value),
            country: value.country,
          });
        } catch (err) {
          if (err instanceof LocationNotFoundError) {
            return renderStep(res, {
              listing,
              n,
              values: req.body,
              errors: { line1: err.message },
              status: 400,
            });
          }
          if (err instanceof GeocoderUnavailableError) {
            if (req.log) req.log.warn({ err }, \"geocoding failed\");
            return renderStep(res, {
              listing,
              n,
              values: req.body,
              formError: err.message,
              status: 503,
            });
          }
          throw err;
        }
      }

      wizard.applyStep(listing, n, value, { geometry });
      wizard.markStepDone(listing, n);
      await listing.save();
      res.redirect(stepUrl(listing._id, n + 1));
    };

    // Publish a draft (or re-publish an unpublished listing). The Host Readiness
    // Checklist (src/services/readiness.js) decides; the page showed the same one.
    module.exports.publish = async (req, res) => {
      if (!ensureVerifiedEmail(req, res)) return; // P02-T05
      const listing = req.listing;
      if (listing.deletedAt)
        throw new NotFoundError(\"That listing does not exist.\");
      if (listing.status === \"published\") {
        req.flash(\"success\", \"This listing is already published.\");
        return res.redirect(`/listings/${listing._id}`);
      }
      if (
        listing.status === \"draft\" &&
        !wizard.isStepComplete(listing, wizard.REVIEW_STEP)
      ) {
        const target = wizard.firstIncompleteStep(listing);
        req.flash(\"error\", `Finish step ${target} before you publish.`);
        return res.redirect(stepUrl(listing._id, target));
      }
      try {
        await lifecycle.publishListing(listing);
      } catch (err) {
        if (err instanceof lifecycle.NotReadyError) {
          req.flash(\"error\", err.message);
          const first = err.failed[0];
          return res.redirect(
            listing.status === \"draft\"
              ? stepUrl(listing._id, first.step)
              : statusUrl(listing._id),
          );
        }
        throw err;
      }
      // Nearby places are fetched in the background: a slow or broken Overpass
      // never delays or blocks publishing (P15-T01).
      nearby.scheduleRefresh(listing._id, { deps: { log: req.log } });
      req.flash(\"success\", \"Your listing is published.\");
      res.redirect(`/listings/${listing._id}`);
    };

    module.exports.unpublish = async (req, res) => {
      const { changed } = await lifecycle.unpublishListing(req.listing);
      req.flash(
        \"success\",
        changed
          ? \"Your listing is unpublished. Guests can no longer see it.\"
          : \"This listing was already unpublished.\",
      );
      res.redirect(statusUrl(req.listing._id));
    };

    // The listing's state, its checklist and what the host can do next.
    module.exports.status = (req, res) => {
      const listing = req.listing;
      if (listing.deletedAt)
        throw new NotFoundError(\"That listing does not exist.\");
      res.render(\"host/status.ejs\", {
        listing,
        readiness: evaluateReadiness(listing),
        nearby: nearby.summaryFor(listing),
        pageTitle: `Status of ${listing.title}`,
        pageDescription: \"Publish, unpublish or delete your listing.\",
      });
    };

    // Host button \"Refresh nearby places\" (P15-T01). The check is instant; the
    // fetch itself runs in the background and the host sees the result on this page.
    module.exports.refreshNearby = (req, res) => {
      const listing = req.listing;
      if (listing.deletedAt)
        throw new NotFoundError(\"That listing does not exist.\");
      const back = () => res.redirect(statusUrl(listing._id));
      if (listing.status !== \"published\") {
        req.flash(\"error\", \"Nearby places are fetched when a listing is published.\");
        return back();
      }
      const verdict = nearby.manualVerdict(listing);
      if (!verdict.ok) {
        const why = {
          disabled: \"Nearby places are switched off on this site.\",
          no_location: \"This listing has no location yet.\",
          cooldown: `Nearby places were updated recently. You can refresh them again on ${verdict.retryAt && verdict.retryAt.toISOString().slice(0, 10)}.`,
          throttled: \"A refresh was just tried. Please wait a few minutes.\",
          fresh: \"Nearby places are up to date.\",
        }[verdict.reason];
        req.flash(\"error\", why || \"Nearby places cannot be refreshed now.\");
        return back();
      }
      nearby.scheduleRefresh(listing._id, { manual: true, deps: { log: req.log } });
      req.flash(\"success\", \"We are fetching nearby places. This can take a minute; reload this page to see them.\");
      return back();
    };

    // \"My listings\": everything this host owns and what to do next with each.
    module.exports.myListings = async (req, res) => {
      const { rows, truncated } = await loadHostListings(Listing, req.user._id);
      res.render(\"host/listings.ejs\", {
        rows,
        truncated,
        maxRows: MAX_ROWS,
