    // /host/reservations: the host's inbox, and accepting or declining a request.
    const { listInbox, respond } = require(\"../services/hostInbox\");
    const { cancelBooking } = require(\"../services/cancellations\");
    const { ConflictError, ValidationError } = require(\"../utils/errors\");

    async function renderInbox(req, res, { status = 200, error } = {}) {
      const inbox = await listInbox({}, req.user._id);
      res.status(status).render(\"host/reservations.ejs\", {
        ...inbox,
        problem: error || null,
        pageTitle: \"Booking requests\",
      });
    }

    module.exports.index = async (req, res) => {
      await renderInbox(req, res);
    };

    function answer(decision, doneMessage) {
      return async (req, res) => {
        try {
          await respond(
            {},
            {
              id: req.params.id,
              user: req.user,
              decision,
              reason: req.body ? req.body.reason : undefined,
            },
          );
        } catch (err) {
          // A booking that changed under the host (expired, answered, listing
          // suspended) is shown as a 409 on a fresh inbox, with the reason.
          if (err instanceof ConflictError)
            return renderInbox(req, res, { status: 409, error: err.message });
          throw err;
        }
        req.flash(\"success\", doneMessage);
        res.redirect(\"/host/reservations\");
      };
    }

    module.exports.accept = answer(
      \"accept\",
      \"Request accepted. The dates stay booked and the guest will see it under Your trips.\",
    );
    module.exports.decline = answer(
      \"decline\",
      \"Request declined. The dates are free again.\",
    );

    // POST /host/reservations/:id/cancel (P09-T03). A missing reason is shown on
    // the inbox (400); a booking that changed (already cancelled, over, ...) as a 409.
    module.exports.cancel = async (req, res) => {
      try {
        await cancelBooking(
          { logger: req.log },
          {
            id: req.params.id,
            user: req.user,
            reason: req.body ? req.body.reason : undefined,
          },
        );
      } catch (err) {
        if (err instanceof ConflictError)
          return renderInbox(req, res, { status: 409, error: err.message });
        if (err instanceof ValidationError)
          return renderInbox(req, res, { status: 400, error: err.message });
        throw err;
      }
      req.flash(
        \"success\",
        \"Booking cancelled. The dates are free again, the guest gets a full refund (calculated only: Dimora does not move money yet) and the cancellation is counted on your profile.\",
      );
      return res.redirect(\"/host/reservations\");
    };

    // /host/listings/:id/stats (P13-T03). Behind authorize(\"listing:edit\"), so only
    // the listing's host gets here and the listing is on req.listing.
    const listingStats = require(\"../services/listingStats\");
    const { NotFoundError } = require(\"../utils/errors\");

    module.exports.show = async (req, res) => {
      const listing = req.listing;
      if (listing.deletedAt) throw new NotFoundError(\"That listing does not exist.\");
      const stats = await listingStats.getStats(listing._id);
      res.set(\"Cache-Control\", \"no-store\");
      res.render(\"host/stats\", { pageTitle: `Statistics: ${listing.title}`, listing, stats });
    };

    // Photo management for a listing the signed-in user may edit (the routes run
    // authorize(\"listing:edit\") first, which leaves the listing on req.listing).
    // Every action is a plain form post that redirects back to the photo section of
    // the edit page with a message, so it works without JavaScript.
    const images = require(\"../services/images\");
    const { AppError, NotFoundError, ValidationError } = require(\"../utils/errors\");

    // The listing wizard's photo step uses the same actions and asks to come back
    // to itself with ?wizard=1 (a fixed target, never a URL taken from the request).
    const backTo = (req) =>
      req.query && req.query.wizard === \"1\"
        ? `/host/listings/${req.params.id}/steps/4`
        : `/listings/${req.params.id}/edit#photos`;

    // Problems the host can fix (a bad file, a full gallery, a failed upload) come
    // back to the form as a message; anything else is a real error.
    async function respond(req, res, action) {
      try {
        const message = await action();
        req.flash(\"success\", message);
      } catch (err) {
        const explainable =
          err instanceof ValidationError ||
          err instanceof NotFoundError ||
          err instanceof images.UploadFailedError;
        if (!explainable) throw err;
        if (req.log && err instanceof AppError && err.statusCode >= 500) {
          req.log.warn({ err }, \"photo action failed\");
        }
        req.flash(\"error\", err.message);
      }
      res.redirect(backTo(req));
    }

    const plural = (n, word) => `${n} ${word}${n === 1 ? \"\" : \"s\"}`;

    module.exports.upload = (req, res) =>
      respond(req, res, async () => {
        const added = await images.addImages(req.listing, req.files || [], {
          log: req.log,
        });
        return `${plural(added.length, \"photo\")} added.`;
      });

    module.exports.reorder = (req, res) =>
      respond(req, res, async () => {
        const order = [].concat((req.body && req.body.order) ?? []);
        await images.reorderImages(req.listing, order);
        return \"Photo order saved.\";
      });

    module.exports.move = (req, res) =>
      respond(req, res, async () => {
        await images.moveImage(
          req.listing,
          req.params.imageId,
          req.body && req.body.direction,
        );
        return \"Photo moved.\";
      });

    module.exports.makeCover = (req, res) =>
      respond(req, res, async () => {
        await images.setCover(req.listing, req.params.imageId);
        return \"Cover photo changed.\";
      });

    module.exports.updateText = (req, res) =>
      respond(req, res, async () => {
        const body = req.body || {};
        await images.updateImageText(req.listing, req.params.imageId, {
          alt: body.alt,
          caption: body.caption,
        });
        return \"Photo details saved.\";
      });

    module.exports.remove = (req, res) =>
      respond(req, res, async () => {
        await images.removeImage(req.listing, req.params.imageId, { log: req.log });
        return \"Photo removed.\";
      });

    const { neighborhoodFor } = require(\"../services/neighborhood\");
    const Listing = require(\"../models/listing.js\");
    const User = require(\"../models/user\");
    const Reservation = require(\"../models/reservation\");
    const { loadTrust } = require(\"../services/trust\");
    const ListingStat = require(\"../models/listingStat\");
    const { VARIANTS, recordClick } = require(\"../services/rankingStats\");
    const reviewService = require(\"../services/reviews\");
    const listingStats = require(\"../services/listingStats\");
    const { summarizeRatings } = require(\"../utils/ratings\");
    const { can } = require(\"../policies\");
    const { searchPage } = require(\"../services/search\");
    const { isAdmin } = require(\"../policies/shared\");
    const { getGeocodingClient } = require(\"../services/geocoding\");
    const { deleteImage } = require(\"../config/cloudinary\");
    const { galleryOf, replaceCover } = require(\"../services/images\");
    const { imageUrl } = require(\"../utils/imageUrl\");
    const { publicPointOf } = require(\"../utils/geo\");
    const { accessibilityLabels } = require(\"../utils/accessibility\");
    const { ACCESSIBILITY_NOTICE } = require(\"../config/constants\");
    const { isPublic } = require(\"../utils/visibility\");
    const { softDeleteListing } = require(\"../services/lifecycle\");
    const { stayRulesFor } = require(\"../services/bookingRules\");
    const { todayIn, tryParseDateOnly, formatDateOnly } = require(\"../utils/dates\");
    const { evaluateReadiness } = require(\"../services/readiness\");
    const { NotFoundError, ConflictError } = require(\"../utils/errors\");
    const { groupAmenities } = require(\"../utils/amenities\");
    const { listingJsonLd } = require(\"../utils/structuredData\");
    const {
      PROPERTY_TYPES,
      ROOM_TYPES,
      CANCELLATION_POLICIES,
    } = require(\"../config/constants\");
    const {
      rupeesToMinor,
      addressFromLegacy,
      imagesFromCover,
    } = require(\"../utils/listingFields\");

    // The sort choices offered on the listings page, in the order shown.
    const SORT_OPTIONS = [
      { value: \"relevance\", label: \"Best match\" },
      { value: \"price_asc\", label: \"Price: low to high\" },
      { value: \"price_desc\", label: \"Price: high to low\" },
      { value: \"rating\", label: \"Top rated\" },
      { value: \"newest\", label: \"Newest\" },
    ];

    // server.js calls this at startup so a malformed MAPBOX_SERVER_TOKEN still
    // stops the server at boot (the client is otherwise built on first use).
    module.exports.initGeocoding = getGeocodingClient;

    module.exports.index = async (req, res) => {
      // Only published listings are public (the search filter says so); results are
      // sorted and 12 to a page. The URL names and filter forms are P05-T02/T04.
      const results = await searchPage(Listing, req.query);
      res.render(\"listings/index.ejs\", {
        allListings: results.listings,
