    };

    // Reports (P12-T04). The form shows what is being reported (looked up by the
    // server from kind + id, never taken from the page), who may send it is the
    // `report:create` policy, and everything else is services/reports.js.
    const { can } = require(\"../policies\");
    const {
      REPORT_REASONS,
      REASON_VALUES,
      REPORT_KINDS,
      LIMITS,
    } = require(\"../config/reports\");
    const {
      createReport,
      describeTarget,
      listMyReports,
    } = require(\"../services/reports\");
    const {
      ValidationError,
      ConflictError,
      ForbiddenError,
    } = require(\"../utils/errors\");

    const text = (value) => (typeof value === \"string\" ? value : \"\");

    async function renderForm(
      req,
      res,
      { kind, id, values = {}, error = null, status = 200 },
    ) {
      const target = await describeTarget({}, kind, id);
      if (!can(\"report:create\", req.user, { owner: target.owner })) {
        throw new ForbiddenError(
          target.owner && String(target.owner) === String(req.user._id)
            ? \"You cannot report your own listing, review or profile.\"
            : \"Your account cannot send reports.\",
        );
      }
      res.status(status).render(\"reports/new.ejs\", {
        target: {
          kind: target.kind,
          id: target.id,
          label: target.label,
          url: target.url,
        },
        kindLabel: REPORT_KINDS.find((k) => k.value === target.kind).label,
        reasons: REPORT_REASONS,
        limits: LIMITS,
        values: { reason: text(values.reason), details: text(values.details) },
        error,
        pageTitle: \"Report\",
      });
    }

    module.exports.newForm = async (req, res) => {
      await renderForm(req, res, {
        kind: text(req.query.kind),
        id: text(req.query.id),
        // A link may suggest a reason (\"Report inaccurate accessibility information\"); only a listed one counts.
        values: {
          reason: REASON_VALUES.includes(text(req.query.reason))
            ? text(req.query.reason)
            : \"\",
        },
      });
    };

    module.exports.create = async (req, res) => {
      const body = req.body && typeof req.body === \"object\" ? req.body : {};
      const kind = text(body.kind);
      const id = text(body.id);
      try {
        await createReport(
          {},
          { user: req.user, kind, id, reason: body.reason, details: body.details },
        );
      } catch (err) {
        if (err instanceof ValidationError && kind && id) {
          // Show the form again with what was typed and the reason it was refused.
          return renderForm(req, res, {
            kind,
            id,
            values: body,
            error: err.message,
            status: 400,
          });
        }
        if (err instanceof ConflictError && err.code === \"already_reported\") {
          req.flash(\"error\", err.message);
          return res.redirect(\"/reports\");
        }
        throw err;
      }
      req.flash(
        \"success\",
        \"Thank you. Your report was received. You can follow its status here.\",
      );
      return res.redirect(\"/reports\");
    };

    module.exports.index = async (req, res) => {
      const reports = await listMyReports({}, req.user._id);
      res.render(\"reports/index.ejs\", { reports, pageTitle: \"Your reports\" });
    };

    const Listing = require(\"../models/listing.js\");
    const reviewService = require(\"../services/reviews\");
    const { publicListingFilter } = require(\"../utils/visibility\");

    // A review belongs to one completed stay (P12-T01, ADR-010): the form sends
    // the reservation, and the service decides whether this person may review it.
    module.exports.createReview = async (req, res) => {
      const { reservation, rating, comment } = req.body.review;
      await reviewService.submit({
        user: req.user,
        listingId: req.params.id,
        reservationId: reservation,
        rating,
        comment,
        windowDays: req.app.locals.reviewWindowDays,
      });

      req.flash(\"success\", \"Thank you, your review was added.\");
      // A stay at a listing that has since been taken down is still reviewable;
      // there is no listing page to return to then.
      const stillPublic = await Listing.exists({
        _id: req.params.id,
        ...publicListingFilter(),
      });
      res.redirect(
        stillPublic ? `/listings/${req.params.id}` : `/trips/${reservation}`,
      );
    };

    // The author edits rating and comment (P12-T03). The form says which page it
    // was on, so the guest lands back there.
    module.exports.updateReview = async (req, res) => {
      const { id, reviewId } = req.params;
      const { rating, comment, from } = req.body.review;
      const { review, changed } = await reviewService.edit({
        user: req.user,
        listingId: id,
        reviewId,
        rating,
        comment,
        editDays: req.app.locals.reviewEditDays,
      });
      req.flash(\"success\", changed ? \"Your review was updated.\" : \"No changes.\");
      const trip = review.reservation
        ? `/trips/${review.reservation}#review`
        : null;
      res.redirect(
        from === \"trip\" && trip ? trip : `/listings/${id}#review-${reviewId}`,
      );
    };

    // The host's reply to a review (P12-T03).
    module.exports.createReply = async (req, res) => {
      const { id, reviewId } = req.params;
      await reviewService.reply({
        user: req.user,
        listing: req.listing,
        reviewId,
        text: req.body.reply.text,
      });
      req.flash(\"success\", \"Your reply was posted.\");
      res.redirect(`/listings/${id}#review-${reviewId}`);
    };

    module.exports.destroyReply = async (req, res) => {
      const { id, reviewId } = req.params;
      const removed = await reviewService.removeReply({
        user: req.user,
        listing: req.listing,
        reviewId,
      });
      req.flash(
        \"success\",
        removed ? \"Your reply was removed.\" : \"No reply to remove.\",
      );
      res.redirect(`/listings/${id}#review-${reviewId}`);
    };

    module.exports.destroyreview = async (req, res) => {
      const { id, reviewId } = req.params;
      // One service call: deletes the review and updates the listing's list and
      // rating totals together (P12-T02).
      await reviewService.remove({ listingId: id, reviewId });
      req.flash(\"success\", \"Review Deleted\");
      res.redirect(`/listings/${id}`);
    };

    // The listings page with search (P05-T02): /listings and its URL parameters.
    //
    // Filters come from the search service (P05-T01); dates are applied through
    // the night ledger (a listing with any taken night in the stay is left out).
    // Sorting and paging (P05-T03): five sort orders, 12 to a page, and a page past
    // the last one is a normal 200 page that explains and links to the last page
    // (the list itself is not fetched then). The rating filter (`minRating`) is
    // validated and kept in every link, but only starts to act in P12-T02. The
    // category strip, the filter panel and the chips for the active filters
    // (P05-T04) and the suggestions for an empty search (P05-T05) are built from
    // the same validated state.
    const Listing = require(\"../models/listing\");
    const { listingFilterFor } = require(\"../services/listingFilter\");
    const { searchMap } = require(\"../services/mapSearch\");
    const { parseBbox } = require(\"../utils/bbox\");
    const { ValidationError } = require(\"../utils/errors\");
    const { queryPairs, listingsUrl, hiddenFields } = require(\"../utils/searchUrl\");
    const { sortSpec } = require(\"../services/search\");
    const { suggestForEmptyResults } = require(\"../services/suggestions\");
    const { suggestDestinations } = require(\"../services/destinations\");
    const ListingStat = require(\"../models/listingStat\");
    const { PURPOSES, getPurpose } = require(\"../config/purposes\");
    const { rankedPage, maxScore } = require(\"../services/purposeRank\");
    const { recordShown } = require(\"../services/rankingStats\");
    const { formatDateOnly, todayIn, DEFAULT_TIMEZONE } = require(\"../utils/dates\");
    const {
      activeChips,
      filterCount,
      resetFiltersHref,
      categoryLinks,
      PANEL_FIELDS,
    } = require(\"../utils/filterChips\");
    const { getCategory } = require(\"../config/categories\");
    const { PROPERTY_TYPES, ROOM_TYPES, AMENITIES } = require(\"../config/constants\");
    const { RADII_KM } = require(\"../services/area\");

    const PAGE_SIZE = 12;

    module.exports.PAGE_SIZE = PAGE_SIZE;

    // The sort choices offered on the listings page, in the order shown.
    const SORT_OPTIONS = Object.freeze([
      { value: \"relevance\", label: \"Best match\" },
      { value: \"price_asc\", label: \"Price: low to high\" },
      { value: \"price_desc\", label: \"Price: high to low\" },
      { value: \"rating\", label: \"Top rated\" },
      { value: \"newest\", label: \"Newest\" },
    ]);
    const DEFAULT_SORT = \"relevance\";

    module.exports.SORT_OPTIONS = SORT_OPTIONS;

    module.exports.index = async (req, res) => {
      const now = new Date();
      const { parsed, filter, takenIds } = await listingFilterFor(req.query, {
        now,
      });
      const sort = parsed.state.sort || DEFAULT_SORT;
      const requested = parsed.page;

      const total = await Listing.countDocuments(filter);
      const totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE));
      // A page past the last one (with results to show) is explained, not fetched.
      const outOfRange = total > 0 && requested > totalPages;
      const page = Math.min(requested, totalPages);

      // A trip purpose re-orders \"Best match\" (P15-T06). It needs that sort and no
      // search words (words have their own relevance), and says so when it cannot act.
      const purpose = getPurpose(parsed.state.purpose);
      const hasText = Boolean(filter.$text);
      const purposeActive = Boolean(purpose) && sort === \"relevance\" && !hasText;
      // Which ordering the page shows, for the click-through comparison; null for
      // the other sort orders and for word searches (not comparable).
      const rankVariant = sort === \"relevance\" && !hasText ? (purpose ? purpose.slug : \"default\") : null;

      let listings = [];
      if (!outOfRange) {
        if (purposeActive) {
          listings = await rankedPage({ Listing, filter, purpose, page, pageSize: PAGE_SIZE });
        } else {
          const spec = sortSpec(sort, { hasText });
          const cursor = spec.projection
            ? Listing.find(filter, spec.projection)
            : Listing.find(filter);
          listings = await cursor
            .sort(spec.sort)
            .skip((page - 1) * PAGE_SIZE)
            .limit(PAGE_SIZE);
        }
        // Counters only, never in the way of the page, and not for crawlers.
        if (rankVariant && listings.length > 0 && !/bot|crawl|spider|preview|monitor/i.test(req.get(\"user-agent\") || \"\")) {
          recordShown({ ListingStat, ids: listings.map((l) => l._id), variant: rankVariant }).catch(() => {});
        }
      }

      const pageState = { ...parsed.state };
      delete pageState.page;
      // A sort order alone is not a search.
      const filterState = { ...pageState };
      delete filterState.sort;
      delete filterState.purpose;
      const filtered = Object.keys(filterState).length > 0;

      // Sort links keep the search and start again at page 1.
      const sortLinks = SORT_OPTIONS.map((option) => ({
        ...option,
        current: option.value === sort,
        href: listingsUrl(pageState, {
          sort: option.value === DEFAULT_SORT ? undefined : option.value,
        }),
      }));
      // \"Plan for\": the purposes, each as a link that keeps the search (P15-T06).
      const purposeLinks = [
        { slug: \"\", label: \"Any trip\", current: !purpose, href: listingsUrl(pageState, { purpose: undefined }) },
        ...PURPOSES.map((p) => ({
          slug: p.slug,
          label: p.label,
          current: Boolean(purpose) && purpose.slug === p.slug,
          href: listingsUrl(pageState, { purpose: p.slug }),
        })),
      ];
      const purposeInfo = purpose
        ? {
            slug: purpose.slug,
            label: purpose.label,
            summary: purpose.summary,
            rules: purpose.rules,
            max: maxScore(purpose),
            active: purposeActive,
            why: purposeActive
              ? null
              : hasText
                ? \"Trip ranking is off while you search by words.\"
                : \"Trip ranking only applies to the Best match order.\",
          }
        : null;

      const from = (page - 1) * PAGE_SIZE + 1;
      const showing =
        total > 0 && !outOfRange && totalPages > 1
          ? { from, to: from + listings.length - 1 }
          : null;

      // Only an empty, filtered search gets suggestions (at most 5 extra queries).
      const suggestions =
        total === 0 && filtered
          ? await suggestForEmptyResults({ Listing, parsed, takenIds })
          : null;

      res.render(\"listings/index.ejs\", {
        allListings: listings,
        state: { ...pageState, ...(page > 1 ? { page } : {}) },
        pageState,
        form: parsed.form,
        errors: parsed.errors,
        chips: activeChips(pageState),
        filterCount: filterCount(pageState),
        resetFiltersHref: resetFiltersHref(pageState),
        categories: categoryLinks(pageState),
        activeCategory: getCategory(pageState.category),
        panel: {
          values: pageState,
          typed: parsed.drawer,
          fields: PANEL_FIELDS,
          lists: { PROPERTY_TYPES, ROOM_TYPES, AMENITIES, RADII_KM },
        },
        hiddenFields,
        mapQuery: new URLSearchParams(queryPairs(pageState)).toString(),
        sortLinks,
        purposeLinks,
        purposeInfo,
        rankVariant,
        showing,
        outOfRange,
        lastPageHref: listingsUrl(pageState, { page: totalPages }),
        suggestions,
        total,
        page,
        totalPages,
        filtered,
        suggestions,
        today: formatDateOnly(todayIn(DEFAULT_TIMEZONE, now)),
        pageTitle: filtered
          ? \"Search results\"
          : page > 1
            ? `Explore stays (page ${page})`
            : \"Explore stays\",
        pageDescription: \"Browse places to stay on Dimora.\",
      });
    };

    // GET /api/search/map?bbox=west,south,east,north&<the listings page filters>
    // GeoJSON of at most MAP_RESULT_CAP stays (approximate points only); without
    // `bbox` it covers every place. `meta` says how many matched and whether the
    // list was cut. Wrong filter values are ignored as on the page; a wrong bbox is
    // a 400.
    // Suggestions for the destination boxes (P05-T06). `q` is whatever was typed; a
    // missing, repeated or too short `q` is an empty list, not an error.
    module.exports.destinations = async (req, res) => {
      const q = typeof req.query.q === \"string\" ? req.query.q : \"\";
      const suggestions = await suggestDestinations({ Listing, q });
      res.set(\"Cache-Control\", \"private, max-age=30\");
      res.json({ suggestions });
    };

    module.exports.mapData = async (req, res) => {
      let boxes = null;
      if (req.query.bbox !== undefined) {
        const box = parseBbox(req.query.bbox);
        if (!box.ok) throw new ValidationError(box.message);
        boxes = box.boxes;
      }
      const { filter } = await listingFilterFor(req.query);
      const result = await searchMap(Listing, filter, boxes);
      res.set(\"Cache-Control\", \"no-store\");
      res.json(result);
    };

    // Editing a listing section by section (P04-T04): /listings/:id/edit shows the
    // same forms as the wizard, each saved on its own. The address is special: a
    // changed address is looked up first and only saved after the host confirms the
    // match. Validation is the wizard's (src/validation/wizard.js), so a published
    // listing can never be edited into something the wizard would have refused.
    const wizard = require(\"../services/wizard\");
    const { galleryOf, MAX_IMAGES } = require(\"../services/images\");
    const {
      lookupAddress,
      LocationNotFoundError,
      GeocoderUnavailableError,
    } = require(\"../services/geocoding\");
    const { rememberLookup, takeLookup } = require(\"../services/locationConfirm\");
    const { validateStep } = require(\"../validation/wizard\");
    const { NotFoundError } = require(\"../utils/errors\");
    const {
      PROPERTY_TYPES,
      ROOM_TYPES,
      VIBES,
      CANCELLATION_POLICIES,
      AMENITIES,
      ACCESSIBILITY_FEATURES,
    } = require(\"../config/constants\");

    // URL key -> wizard step number. Photos have their own routes.
    const SECTIONS = Object.freeze({ basics: 1, location: 2, details: 3, pricing: 5 });
    const LISTS = { PROPERTY_TYPES, ROOM_TYPES, VIBES, CANCELLATION_POLICIES, AMENITIES, ACCESSIBILITY_FEATURES };

    const editUrl = (listing, key) => `/listings/${listing._id}/edit${key ? `#${key}` : \"\"}`;

    /** The edit page. `failed` = { key, values, errors, formError } for a section that was refused. */
    function renderEdit(res, listing, { failed, status = 200 } = {}) {
      const values = {};
      const errors = {};
      for (const [key, step] of Object.entries(SECTIONS)) {
        const own = failed && failed.key === key;
        values[key] = own && failed.values ? failed.values : wizard.formValues(listing, step);
        errors[key] = own && failed.errors ? failed.errors : {};
      }
      res.status(status).render(\"listings/edit.ejs\", {
        listing,
        values,
        errors,
        formError: failed && failed.formError,
        failedKey: failed && failed.key,
        lists: LISTS,
        gallery: galleryOf(listing),
        maxImages: MAX_IMAGES,
        pageTitle: `Edit ${listing.title}`,
        pageDescription: \"Change the details of your listing.\",
      });
    }

    module.exports.renderEdit = renderEdit;
    module.exports.SECTIONS = SECTIONS;

    module.exports.renderEditForm = (req, res) => {
      // A listing still being written belongs in the wizard.
      if (req.listing.status === \"draft\") {
        return res.redirect(`/host/listings/${req.listing._id}`);
      }
      renderEdit(res, req.listing);
    };

    module.exports.save = async (req, res) => {
      const listing = req.listing; // loaded by authorize(\"listing:edit\")
      const key = req.params.key;
      if (!Object.hasOwn(SECTIONS, key)) {
        throw new NotFoundError(\"That part of the listing does not exist.\");
      }
      if (listing.status === \"draft\") {
        return res.redirect(`/host/listings/${listing._id}`);
      }
      const step = SECTIONS[key];

      // `confirmed` belongs to the location confirmation form, not to the address.
      const { confirmed, ...body } = req.body ?? {};
      const { value, errors } = validateStep(step, body);
      if (!value) {
        return renderEdit(res, listing, {
          failed: { key, values: body, errors },
          status: 400,
        });
      }

      let geometry;
      if (step === 2 && wizard.addressChanged(listing, value)) {
        const pending = confirmed === \"on\" ? takeLookup(req.session, listing._id, value) : null;
        if (pending) {
          geometry = pending.geometry;
        } else {
          let found;
          try {
            found = await lookupAddress({
              location: wizard.addressQuery(value),
              country: value.country,
            });
          } catch (err) {
            if (err instanceof LocationNotFoundError) {
              return renderEdit(res, listing, {
                failed: { key, values: body, errors: { line1: err.message } },
                status: 400,
              });
            }
            if (err instanceof GeocoderUnavailableError) {
              if (req.log) req.log.warn({ err }, \"geocoding failed\");
              return renderEdit(res, listing, {
                failed: { key, values: body, formError: err.message },
                status: 503,
              });
            }
            throw err;
          }
          rememberLookup(req.session, listing._id, value, found);
          return res.render(\"listings/confirm-location.ejs\", {
            listing,
            address: value,
            placeName: found.placeName,
            pageTitle: \"Confirm the location\",
            pageDescription: \"Check that we found the right place.\",
          });
        }
      }

      wizard.applyStep(listing, step, value, { geometry });
      await listing.save();
      req.flash(\"success\", \"Changes saved.\");
      res.redirect(editUrl(listing, key));
    };

    // /trips (a guest's bookings in four tabs) and /trips/:id (one booking's
    // confirmation page, also readable by the booking's host and by an admin).
    const Reservation = require(\"../models/reservation\");
    const { can } = require(\"../policies\");
    const { sameId } = require(\"../policies/shared\");
    const { listTrips, describeTrip } = require(\"../services/trips\");
    const reviewService = require(\"../services/reviews\");
    const { cancelBooking } = require(\"../services/cancellations\");
    const modifications = require(\"../services/modifications\");
    const {
      lineLabel,
      referenceOf,
      formatStayDate,
      formatStayWeekday,
    } = require(\"../services/trips\");
    const { formatMoney } = require(\"../utils/money\");
    const { formatDateOnly, todayIn, DEFAULT_TIMEZONE } = require(\"../utils/dates\");
    const {
      NotFoundError,
      ConflictError,
      ValidationError,
      PriceChangedError,
    } = require(\"../utils/errors\");

    const OBJECT_ID = /^[0-9a-f]{24}$/i;

    module.exports.index = async (req, res) => {
      const trips = await listTrips({}, req.user._id, {
        tab: req.query.tab,
        page: req.query.page,
        windowDays: req.app.locals.reviewWindowDays,
      });
      res.render(\"trips/index.ejs\", { ...trips, pageTitle: \"Your trips\" });
    };

    module.exports.show = async (req, res) => {
      const { id } = req.params;
      const reservation = OBJECT_ID.test(id)
        ? await Reservation.findById(id)
            .populate(
              \"listing\",
              \"title address location country geometry deletedAt\",
            )
            .populate(\"host\", \"displayName username email\")
            .populate(\"guest\", \"displayName username\")
            .lean()
        : null;
      // Someone who may not see it gets the same answer as for a booking that does
      // not exist: the page never confirms that a reference is real.
      if (!reservation || !can(\"reservation:view\", req.user, reservation)) {
        throw new NotFoundError(\"That booking does not exist.\");
      }
      const viewerRole = sameId(reservation.guest, req.user._id)
        ? \"guest\"
        : sameId(reservation.host, req.user._id)
          ? \"host\"
          : \"admin\";
      // The review form, the review itself, or why there is none (P12-T02).
      const review =
        viewerRole === \"guest\"
          ? await reviewService.stateFor({
              user: req.user,
              reservation,
              windowDays: req.app.locals.reviewWindowDays,
              editDays: req.app.locals.reviewEditDays,
            })
          : { state: \"none\" };
      const trip = describeTrip(reservation, { viewerRole, formatMoney, review });
      res.set(\"Cache-Control\", \"no-store\"); // contains contact details and an address
      res.render(\"trips/show.ejs\", {
        trip,
        pageTitle: `Booking ${trip.reference}`,
      });
    };

    // POST /trips/:id/cancel: the guest cancels (P09-T03). A booking that changed
    // under them (answered, cancelled, over) is shown again with the reason.
    module.exports.cancel = async (req, res) => {
      let result;
      try {
        result = await cancelBooking(
          { logger: req.log },
          {
            id: req.params.id,
            user: req.user,
            reason: req.body ? req.body.reason : undefined,
          },
        );
      } catch (err) {
        if (err instanceof ConflictError) {
          req.flash(\"error\", err.message);
          return res.redirect(`/trips/${req.params.id}`);
        }
        throw err;
      }
      req.flash(
        \"success\",
        \"Your booking is cancelled and the dates are free again. The refund below is calculated only: Dimora does not move money yet.\",
      );
      return res.redirect(`/trips/${result.reservation._id}`);
    };

    // ---- Change the dates (P09-T04) ----------------------------------------

    // A query or body value is used only when it is one plain string (never an
    // array or an object made by repeated or bracketed parameters).
    const plain = (value) => (typeof value === \"string\" ? value : undefined);

    const changePath = (id, { in: checkIn, out } = {}) => {
      const q = [];
      if (checkIn) q.push(`in=${encodeURIComponent(checkIn)}`);
      if (out) q.push(`out=${encodeURIComponent(out)}`);
      return `/trips/${id}/change${q.length ? `?${q.join(\"&\")}` : \"\"}`;
    };

    // What the change page prints. The new stay's amounts are the ones the service
    // will store (the same pricing call), nothing is computed here.
    function changeView(preview, extra = {}) {
      const { reservation, listing, quote } = preview;
      const snap = reservation.listingSnapshot || {};
      const tz = snap.timezone || DEFAULT_TIMEZONE;
      const price = reservation.pricingSnapshot || {};
      const currency = price.currency || \"INR\";
      const id = String(reservation._id);
      return {
        id,
        reference: referenceOf(reservation),
        title: snap.title || (listing && listing.title) || \"Your stay\",
        reapproval: preview.reapproval,
        instantBook: Boolean(snap.instantBook),
        current: {
          inLabel: `${formatStayWeekday(reservation.checkIn)}, ${formatStayDate(reservation.checkIn)}`,
          outLabel: `${formatStayWeekday(reservation.checkOut)}, ${formatStayDate(reservation.checkOut)}`,
          inIso: formatDateOnly(reservation.checkIn),
          outIso: formatDateOnly(reservation.checkOut),
          nights: reservation.nights,
          guests: reservation.guests,
          totalText: formatMoney(price.totalMinor, currency),
        },
        form: {
          in: preview.checkIn ? formatDateOnly(preview.checkIn) : \"\",
          out: preview.checkOut ? formatDateOnly(preview.checkOut) : \"\",
        },
        minDate: formatDateOnly(todayIn(tz)),
        problems: preview.problems.map((p) => p.message),
        proposal: quote
          ? {
              inLabel: `${formatStayWeekday(preview.checkIn)}, ${formatStayDate(preview.checkIn)}`,
              outLabel: `${formatStayWeekday(preview.checkOut)}, ${formatStayDate(preview.checkOut)}`,
              nights: quote.nights,
              lines: (quote.lines || []).map((line) => ({
                label: lineLabel(line, formatMoney, quote.currency),
                amount: formatMoney(line.amountMinor, quote.currency),
                included: Boolean(line.included),
              })),
              totalText: formatMoney(quote.totalMinor, quote.currency),
              totalMinor: quote.totalMinor,
              difference: modifications.describeDifference(preview.differenceMinor, {
                formatMoney,
                currency: quote.currency,
              }),
            }
          : null,
        priceChanged: extra.previousTotalMinor
          ? { previousText: formatMoney(extra.previousTotalMinor, currency) }
          : null,
      };
    }

    async function renderChange(req, res, status, preview, extra) {
      res.set(\"Cache-Control\", \"no-store\");
      res.status(status).render(\"trips/change.ejs\", {
        change: changeView(preview, extra),
        pageTitle: \"Change dates\",
      });
    }

    // GET /trips/:id/change[?in=&out=]: the form, and with dates the new price and
    // the difference. Changes nothing.
    module.exports.changeForm = async (req, res) => {
      let preview;
      try {
        preview = await modifications.previewChange({
          id: req.params.id,
          user: req.user,
          in: plain(req.query.in),
          out: plain(req.query.out),
        });
      } catch (err) {
        if (err instanceof ConflictError) {
          req.flash(\"error\", err.message);
          return res.redirect(`/trips/${req.params.id}`);
        }
        throw err;
      }
      return renderChange(req, res, 200, preview);
    };

    // POST /trips/:id/change: applies the change the guest confirmed. The total
    // they looked at travels with the form; the server compares it with its own.
    module.exports.change = async (req, res) => {
      const body = req.body || {};
      const stay = { in: plain(body.in), out: plain(body.out) };
      let result;
      try {
        result = await modifications.changeDates({
          id: req.params.id,
          user: req.user,
          ...stay,
          expectedTotalMinor: plain(body.expectedTotalMinor),
        });
      } catch (err) {
        if (err instanceof PriceChangedError) {
          // Nothing changed: show the new price and ask again.
          const preview = await modifications.previewChange({
            id: req.params.id,
            user: req.user,
            ...stay,
          });
          return renderChange(req, res, 409, preview, {
            previousTotalMinor: Number(plain(body.expectedTotalMinor)) || null,
          });
        }
        if (err instanceof ConflictError && err.code === \"nights_unavailable\") {
          req.flash(\"error\", \"Some of those nights were just taken. Please choose other dates.\");
          return res.redirect(changePath(req.params.id, stay));
        }
        if (err instanceof ConflictError) {
          req.flash(\"error\", err.message);
          return res.redirect(`/trips/${req.params.id}`);
        }
        if (err instanceof ValidationError && err.code !== \"validation_error\") {
          req.flash(\"error\", err.message);
          return res.redirect(changePath(req.params.id, stay));
        }
        throw err;
      }
      req.flash(
        \"success\",
        result.reapproval
          ? \"Your new dates were sent back to the host, who has 24 hours to answer. The new nights are held for you meanwhile. (Simulation: no payment was taken or returned.)\"
          : \"Your dates are changed. The price difference is recorded only: Dimora does not take or return money yet.\",
      );
      return res.redirect(`/trips/${result.reservation._id}`);
    };

    const mongoose = require(\"mongoose\");
    const passport = require(\"passport\");
    const User = require(\"../models/user\");
    const { signupSchema } = require(\"../validation\");
    const { safeRedirectPath } = require(\"../utils/safeRedirect\");
    const { sendVerification } = require(\"../services/emailAuth\");

    // What the visitor is told. None of this text comes from the database driver,
    // passport or Mongoose.
    const MESSAGES = Object.freeze({
      // Same text for an unknown user, a wrong password, a locked account and a
      // deleted account, so the form cannot be used to find out which usernames exist.
      loginFailed:
        \"Incorrect username or password. After several failed attempts an account is locked for a while.\",
      suspended:
        \"This account is suspended. Contact support if you think this is a mistake.\",
      usernameTaken: \"That username is already taken. Choose another one.\",
      // Does not say which of the two was the problem: a taken email must not be
      // confirmable from the signup form.
      cannotCreate:
        \"We couldn't create an account with those details. If you already have an account, log in instead.\",
      signupInvalid: \"Please check the details you entered and try again.\",
    });

    // The unique index on `email` (P02-T01) rejects a second account with the same
    // address with a duplicate-key error.
    function isDuplicateEmailError(err) {
      if (!err || err.code !== 11000) return false;
      if (err.keyPattern && err.keyPattern.email) return true;
      return typeof err.message === \"string\" && err.message.includes(\"email\");
    }

    function isUsernameTakenError(err) {
      return Boolean(err) && err.name === \"UserExistsError\";
    }

    function isDuplicateUsernameError(err) {
      if (!err || err.code !== 11000) return false;
      if (err.keyPattern && err.keyPattern.username) return true;
      return typeof err.message === \"string\" && err.message.includes(\"username\");
    }

    module.exports.signup = async (req, res, next) => {
      const { error, value } = signupSchema.validate(req.body ?? {}, {
        abortEarly: false,
        // Fields the form does not have (role, status, ...) are dropped here and
        // below only username, email and password are used.
        stripUnknown: true,
        errors: { wrap: { label: false } },
      });
      if (error) {
        // Joi messages for this schema are our own text (see validation/index.js).
        // One flash entry: the layout prints the array joined by bare commas.
        const messages = [...new Set(error.details.map((d) => d.message))];
        req.flash(\"error\", messages.join(\" \"));
        return res.redirect(\"/signup\");
      }

      try {
        const { username, email, password } = value;
        const registeredUser = await User.register(
          new User({ email, username }),
          password,
        );
        // Ask for a confirmed address (P02-T05). A failed email never fails the signup.
        let confirmationSent = false;
        if (req.app.locals.emailVerificationRequired) {
          try {
            await sendVerification({
              user: registeredUser,
              emailService: req.app.locals.emailService,
              baseUrl: req.app.locals.appBaseUrl,
            });
            confirmationSent = true;
          } catch (mailErr) {
            const log = req.app.locals.logger;
            if (log && log.error) log.error({ err: { name: mailErr.name, message: mailErr.message } }, \"verification email failed\");
          }
        }
        req.login(registeredUser, (err) => {
          if (err) {
            return next(err);
          }
          req.flash(
            \"success\",
            confirmationSent
              ? \"User registered successfully. We sent a link to confirm your email address.\"
              : \"User registered successfully\",
          );
          res.redirect(\"/listings\");
        });
      } catch (e) {
        if (isUsernameTakenError(e) || isDuplicateUsernameError(e)) {
          req.flash(\"error\", MESSAGES.usernameTaken);
        } else if (isDuplicateEmailError(e)) {
          req.flash(\"error\", MESSAGES.cannotCreate);
        } else if (e instanceof mongoose.Error.ValidationError) {
          req.flash(\"error\", MESSAGES.signupInvalid);
        } else {
          // Unexpected (database down, ...): the error page, with the real error
          // in the log only.
          return next(e);
        }
        res.redirect(\"/signup\");
      }
    };

    module.exports.renderSignupForm = (req, res) => {
      res.render(\"./users/signup.ejs\", {
        pageTitle: \"Sign up\",
        pageDescription: \"Create a Dimora account to book stays or list your home.\",
      });
    };
    module.exports.renderLoginForm = (req, res) => {
      res.render(\"./users/login.ejs\", {
        pageTitle: \"Log in\",
        pageDescription: \"Log in to your Dimora account.\",
        next: safeRedirectPath(req.query && req.query.next, \"\"),
      });
    };

    function failLogin(req, res, message) {
      req.flash(\"error\", message);
      return res.redirect(\"/login\");
    }

    // passport.authenticate with a callback instead of failureRedirect/failureFlash:
    // the failure text is ours (never passport's or the plugin's), and the account
    // status is checked after the password so a stranger learns nothing from it.
    module.exports.login = (req, res, next) => {
      passport.authenticate(\"local\", (err, user) => {
        if (err) return next(err);
        if (!user) return failLogin(req, res, MESSAGES.loginFailed);
        if (user.status === \"deleted\") {
          return failLogin(req, res, MESSAGES.loginFailed);
        }
        if (user.status === \"suspended\") {
          return failLogin(req, res, MESSAGES.suspended);
        }
        // req.logIn starts a new session (passport 0.7), so a session id set before
        // login cannot be reused afterwards (session fixation).
        req.logIn(user, (loginErr) => {
          if (loginErr) return next(loginErr);
          req.flash(\"success\", \"Welcome back to Dimora ,You are logged in\");
          res.redirect(res.locals.redirectUrl || \"/listings\");
        });
      })(req, res, next);
    };

    module.exports.logout = (req, res, next) => {
      req.logout((err) => {
        if (err) {
          return next(err);
        }
        req.flash(\"success\", \"You are logged out\");
        res.redirect(\"/listings\");
      });
    };

    module.exports.MESSAGES = MESSAGES;

    // /wishlists and the heart's POST /listings/:id/save (P10-T01).
    const service = require(\"../services/wishlists\");
    const lists = require(\"../services/wishlistLists\");
    const searches = require(\"../services/savedSearches\");
    const shared = require(\"../services/sharedLists\");
    const { ValidationError, ConflictError } = require(\"../utils/errors\");
    const { safeRedirectPath } = require(\"../utils/safeRedirect\");

    /** Where a form (no JavaScript) goes back to: the page it was sent from. */
    function backPath(req, fallback) {
      try {
        const from = new URL(req.get(\"referer\") || \"\");
        if (from.host === req.get(\"host\")) {
          return safeRedirectPath(from.pathname + from.search, fallback);
        }
      } catch {
        // no or unreadable Referer: use the fallback
      }
      return fallback;
    }

    const OBJECT_ID = /^[0-9a-f]{24}$/i;
    const plain = (value) => (typeof value === \"string\" ? value : undefined);

    // `?list=<id>` shows one list (with notes and \"move\"); without it every saved
    // stay is shown once. An id that is not the member's own shows everything.
    module.exports.index = async (req, res) => {
      const all = await service.listsFor(req.user._id);
      const wanted = plain(req.query.list);
      const current = OBJECT_ID.test(wanted || \"\") ? all.find((l) => l.id === wanted) || null : null;
      const saved = await service.overview(req.user._id, undefined, current ? { listId: current.id } : {});
      res.set(\"Cache-Control\", \"no-store\");
      res.render(\"wishlists/index.ejs\", {
        ...saved,
        lists: all,
        currentList: current,
        pageTitle: current ? current.name : \"Saved stays\",
        pageDescription: \"The stays you saved on Dimora.\",
      });
    };

    // Body: saved=true | saved=false. The page sends the state it wants, so
    // repeating a request never flips the heart back.
    module.exports.save = async (req, res) => {
      const value = req.body && req.body.saved;
      if (value !== \"true\" && value !== \"false\") {
        throw new ValidationError(\"Say whether to save or to remove this stay.\");
      }
      const result = await service.setSaved(
        req.user._id,
        req.params.id,
        value === \"true\",
      );
      // fetch() asks for JSON; a plain form post gets a redirect and a message.
      if (req.accepts([\"html\", \"json\"]) === \"json\") return res.json(result);
      req.flash(
        \"success\",
        result.saved ? \"Saved to your saved stays.\" : \"Removed from your saved stays.\",
      );
      return res.redirect(backPath(req, `/listings/${encodeURIComponent(req.params.id)}`));
    };

    // ---- Named lists, moving and notes (P10-T02) ----------------------------

    const listPath = (id) => (id ? `/wishlists?list=${encodeURIComponent(id)}` : \"/wishlists\");

    // Runs a list action: a refusal the member can fix (a name in use, a full
    // list, a note too long) is shown on the page they came from; everything else
    // is an error page.
    async function act(req, res, { run, ok, back }) {
      try {
        const result = await run();
        req.flash(\"success\", typeof ok === \"function\" ? ok(result) : ok);
        return res.redirect(typeof back === \"function\" ? back(result) : back);
      } catch (err) {
        if (err instanceof ValidationError || err instanceof ConflictError) {
          req.flash(\"error\", err.message);
          return res.redirect(typeof back === \"function\" ? back(null) : back);
        }
        throw err;
      }
    }

    module.exports.createList = (req, res) =>
      act(req, res, {
        run: () => lists.createList(req.user._id, req.body && req.body.name),
        ok: (list) => `List \"${list.name}\" created.`,
        back: (list) => (list ? listPath(list.id) : \"/wishlists\"),
      });

    module.exports.renameList = (req, res) =>
      act(req, res, {
        run: () => lists.renameList(req.user._id, req.params.id, req.body && req.body.name),
        ok: \"List renamed.\",
        back: listPath(req.params.id),
      });

    module.exports.deleteList = (req, res) =>
      act(req, res, {
        run: () => lists.deleteList(req.user._id, req.params.id),
        ok: (r) =>
          r.moved > 0
            ? `List deleted. Its ${r.moved} stay${r.moved === 1 ? \" was\" : \"s were\"} moved to your main list.`
            : \"List deleted.\",
        // a refusal keeps the member on the list they tried to delete
        back: (r) => (r ? \"/wishlists\" : listPath(req.params.id)),
      });

    module.exports.moveItem = (req, res) =>
      act(req, res, {
        run: () =>
          lists.moveItem(req.user._id, {
            from: req.params.id,
            to: plain(req.body && req.body.to),
            listingId: req.params.listingId,
          }),
        ok: \"Stay moved.\",
        back: listPath(req.params.id),
      });

    module.exports.setNote = (req, res) =>
      act(req, res, {
        run: () =>
          lists.setNote(req.user._id, {
            listId: req.params.id,
            listingId: req.params.listingId,
            note: req.body && req.body.note,
          }),
        ok: (r) => (r.note ? \"Note saved.\" : \"Note removed.\"),
        back: listPath(req.params.id),
      });

    // ---- Saved searches ------------------------------------------------------

    module.exports.searchesIndex = async (req, res) => {
      res.set(\"Cache-Control\", \"no-store\");
      res.render(\"wishlists/searches.ejs\", {
        searches: await searches.list(req.user._id),
        pageTitle: \"Saved searches\",
        pageDescription: \"The searches you saved on Dimora.\",
      });
    };

    // The listings page posts its own state (hidden fields) plus a name. The
    // query that is stored is built from that state by the server.
    module.exports.saveSearch = async (req, res) => {
      const body = req.body && typeof req.body === \"object\" ? req.body : {};
      try {
        await searches.save(req.user._id, { name: body.name, params: body });
      } catch (err) {
        if (err instanceof ValidationError || err instanceof ConflictError) {
          req.flash(\"error\", err.message);
          return res.redirect(backPath(req, \"/listings\"));
        }
        throw err;
      }
      req.flash(\"success\", \"Search saved. Find it under Saved searches.\");
      return res.redirect(\"/saved-searches\");
    };

    module.exports.deleteSearch = async (req, res) => {
      await searches.remove(req.user._id, req.params.id);
      req.flash(\"success\", \"Saved search deleted.\");
      return res.redirect(\"/saved-searches\");
    };

    // ---- Share links (P10-T04) ------------------------------------------------

    module.exports.share = (req, res) =>
      act(req, res, {
        run: () => shared.enableShare(req.user._id, req.params.id),
        ok: (r) => (r.created ? \"Share link created. Anyone who has it can see this list.\" : \"This list is already shared.\"),
        back: listPath(req.params.id),
      });

    module.exports.revokeShare = (req, res) =>
      act(req, res, {
        run: () => shared.revokeShare(req.user._id, req.params.id),
        ok: \"Sharing stopped. The old link no longer works.\",
        back: listPath(req.params.id),
      });

    // Public. Read-only; the link is the credential, so the page must not be
    // indexed, cached or leaked through the Referer header.
    module.exports.showShared = async (req, res) => {
      const data = await shared.viewShared(req.params.token);
      res.set({
        \"Cache-Control\": \"private, no-store\",
        \"X-Robots-Tag\": \"noindex, nofollow\",
        \"Referrer-Policy\": \"no-referrer\",
      });
      res.render(\"wishlists/shared.ejs\", {
        ...data,
        pageTitle: data.name,
        pageDescription: \"A list of stays shared on Dimora.\",
      });
    };

    // The text of the emails (P02-T05). Each function returns { subject, text, html }.
    // Names and links are escaped in the HTML part; the subject is fixed text.
    const escapeHtml = (value) =>
      String(value).replace(/[&<>\"']/g, (c) => ({ \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\", \"'\": \"&#39;\" })[c]);

    function wrap(bodyHtml) {
      return `<div style=\"font-family:Arial,Helvetica,sans-serif;font-size:16px;line-height:1.5;color:#222\">${bodyHtml}<p style=\"color:#666;font-size:13px\">Dimora is a college project. If you did not expect this email you can ignore it.</p></div>`;
    }

    function button(link, label) {
      return `<p><a href=\"${escapeHtml(link)}\" style=\"display:inline-block;background:#212529;color:#fff;padding:10px 18px;border-radius:6px;text-decoration:none\">${escapeHtml(label)}</a></p><p style=\"font-size:14px\">Or paste this address into your browser:<br>${escapeHtml(link)}</p>`;
    }

    function verifyEmail({ name, link, hours }) {
      return {
        subject: \"Confirm your email address for Dimora\",
        text: `Hi ${name},\\n\\nConfirm that this is your email address by opening this link (valid for ${hours} hours):\\n\\n${link}\\n\\nYou need a confirmed address to publish a listing or book a stay.\\n\\nIf you did not create a Dimora account you can ignore this email.`,
        html: wrap(
          `<p>Hi ${escapeHtml(name)},</p><p>Confirm that this is your email address. The link is valid for ${escapeHtml(hours)} hours.</p>${button(link, \"Confirm my email\")}<p>You need a confirmed address to publish a listing or book a stay.</p>`,
        ),
      };
    }

    function resetPassword({ name, link, minutes }) {
      return {
        subject: \"Reset your Dimora password\",
        text: `Hi ${name},\\n\\nSomeone asked to reset the password of your Dimora account. To choose a new one, open this link (valid for ${minutes} minutes, works once):\\n\\n${link}\\n\\nIf this was not you, ignore this email: your password has not changed.`,
        html: wrap(
          `<p>Hi ${escapeHtml(name)},</p><p>Someone asked to reset the password of your Dimora account. The link is valid for ${escapeHtml(minutes)} minutes and works once.</p>${button(link, \"Choose a new password\")}<p>If this was not you, ignore this email: your password has not changed.</p>`,
        ),
      };
    }

    function passwordChanged({ name }) {
      return {
        subject: \"Your Dimora password was changed\",
        text: `Hi ${name},\\n\\nThe password of your Dimora account was just changed using a reset link. If this was you, there is nothing to do. If it was not, reset your password again and contact the site's administrator.`,
        html: wrap(
          `<p>Hi ${escapeHtml(name)},</p><p>The password of your Dimora account was just changed using a reset link.</p><p>If this was you, there is nothing to do. If it was not, reset your password again and contact the site's administrator.</p>`,
        ),
      };
    }

    /**
     * An email copy of an in-app notification (P11-T05). `link` is an absolute
     * address on this site; `unsubscribeLink` is omitted for essential messages.
     */
    function notification({ name, title, body, link, groupLabel, unsubscribeLink }) {
      const text = [
        `Hi ${name},`,
        \"\",
        title,
        ...(body ? [\"\", body] : []),
        \"\",
        `Open it on Dimora: ${link}`,
        \"\",
        unsubscribeLink
          ? `You get this email because of your \"${groupLabel}\" notification setting. Stop these emails: ${unsubscribeLink}`
          : `You get this email because it is about something you run on Dimora (${groupLabel}). It cannot be turned off.`,
      ].join(\"\\n\");
      const footer = unsubscribeLink
        ? `<p style=\"color:#666;font-size:13px\">You get this email because of your &ldquo;${escapeHtml(groupLabel)}&rdquo; notification setting. <a href=\"${escapeHtml(unsubscribeLink)}\">Stop these emails</a>.</p>`
        : `<p style=\"color:#666;font-size:13px\">You get this email because it is about something you run on Dimora (${escapeHtml(groupLabel)}). It cannot be turned off.</p>`;
      return {
        subject: String(title).replace(/[\\r\\n]+/g, \" \").slice(0, 150),
        text,
        html: wrap(
          `<p>Hi ${escapeHtml(name)},</p><p><strong>${escapeHtml(title)}</strong></p>${body ? `<p>${escapeHtml(body)}</p>` : \"\"}${button(link, \"Open on Dimora\")}${footer}`,
        ),
      };
    }

    module.exports = { verifyEmail, resetPassword, passwordChanged, notification, escapeHtml };

    // Guard and audit wrapper for the /admin area (P14-T01).
    const audit = require(\"../services/audit\");
    const { isAdmin } = require(\"../policies/shared\");
    const { NotFoundError } = require(\"../utils/errors\");

    /**
     * Thrown by an auditedMutation handler when it refuses to act (a rule is
     * broken, the form is incomplete) BEFORE changing anything. The wrapper shows
     * `message` as a flash error and redirects to `redirectTo`; no audit row is
     * written because nothing happened.
     */
    class AdminRefusal extends Error {
      constructor(message, redirectTo = \"/admin\") {
        super(message);
        this.name = \"AdminRefusal\";
        this.redirectTo = redirectTo;
      }
    }

    /**
     * router.use(adminGuard) for the whole area. Anyone who is not an active admin
     * (visitors included) gets the ordinary 404 page, so /admin does not reveal
     * that it exists.
     */
    function adminGuard(req, res, next) {
      if (!isAdmin(req.user)) throw new NotFoundError();
      res.set(\"Cache-Control\", \"no-store\");
      res.locals.pageTitle = res.locals.pageTitle || \"Admin\";
      next();
    }

    /**
     * Wraps every admin route that changes data. The handler does the change and
     * RETURNS what to log; it must not respond itself:
     *
     *   router.post(\"/users/:id/suspend\", auditedMutation(async (req) => {
     *     ...change something...
     *     return {
     *       audit: { action: \"user.suspend\", targetType: \"user\", targetId: id, reason, details },
     *       redirectTo: \"/admin/users\",   // or respond: (res) => res.render(...)
     *       flash: \"Account suspended.\",  // optional success message
     *     };
     *   }));
     *
     * The wrapper writes the audit row first and only then answers, so a change
     * without an audit entry never succeeds quietly: it throws (a 500 and a test
     * failure). The change itself has already happened by then; the answer is what
     * is withheld.
     */
    function auditedMutation(handler) {
      async function run(req, res) {
        let result;
        try {
          result = await handler(req, res);
        } catch (err) {
          if (err instanceof AdminRefusal && !res.headersSent) {
            req.flash(\"error\", err.message);
            return res.redirect(err.redirectTo);
          }
          throw err;
        }
        if (res.headersSent) {
          throw new Error(\"auditedMutation: the handler responded itself; return { audit, ... } instead\");
        }
        if (!result || !result.audit) {
          throw new Error(\"auditedMutation: the handler returned no audit entry\");
        }
        await audit.record({ ...result.audit, req });
        if (req.auditRecorded !== 1) {
          throw new Error(`auditedMutation: expected exactly one audit entry, got ${req.auditRecorded}`);
        }
        if (result.flash) req.flash(\"success\", result.flash);
        if (typeof result.respond === \"function\") return result.respond(res);
        return res.redirect(result.redirectTo || \"/admin\");
      }

      function auditedMutationMiddleware(req, res, next) {
        req.auditRecorded = 0;
        run(req, res).catch(next);
      }
      // Lets tests check a route table without calling anything.
      auditedMutationMiddleware.auditedMutation = true;
      return auditedMutationMiddleware;
    }

    module.exports = { adminGuard, auditedMutation, AdminRefusal };

    const { ForbiddenError } = require(\"../utils/errors\");
    const { hasRole } = require(\"../policies/shared\");
    const { ROLES } = require(\"../models/user\");
    const { safeRedirectPath } = require(\"../utils/safeRedirect\");

    /** Remembers where the visitor was going and sends them to the login page. */
    function redirectToLogin(req, res) {
      req.session.redirectUrl = req.originalUrl;
      req.flash(\"error\", \"You must be logged in to do that\");
      return res.redirect(\"/login\");
    }

    function isLoggedIn(req, res, next) {
      if (!req.isAuthenticated()) return redirectToLogin(req, res);
      next();
    }

    /**
     * Login only: works out where to send the user afterwards and leaves it in
     * `res.locals.redirectUrl` (undefined = use the default). Sources, in order:
     * the page they were stopped at (session), then a `next` form field / query
     * parameter. Either is used only if it is a same-site path.
     */
    function saveRedirectUrl(req, res, next) {
      const fromSession = req.session && req.session.redirectUrl;
      if (req.session) delete req.session.redirectUrl;
      const fromForm = (req.body && req.body.next) || (req.query && req.query.next);
      const target =
        safeRedirectPath(fromSession, null) || safeRedirectPath(fromForm, null);
      if (target) res.locals.redirectUrl = target;
      next();
    }

    /**
     * Route guard for a whole area, e.g. router.use(requireRole(\"admin\")).
     * Anonymous -> login page; logged in without the role (or suspended) -> 403.
     */
    function requireRole(role) {
      if (!ROLES.includes(role)) {
        throw new Error(`requireRole: unknown role \"${role}\"`);
      }
      return function requireRoleMiddleware(req, res, next) {
        if (!req.user) return redirectToLogin(req, res);
        if (!hasRole(req.user, role)) throw new ForbiddenError();
        next();
      };
    }

    module.exports = { redirectToLogin, isLoggedIn, saveRedirectUrl, requireRole };

    // authorize(\"listing:edit\"): loads the resource, then asks the policy.
    //
    //   anonymous            -> login page (same as isLoggedIn)
    //   resource missing     -> 404
    //   policy says no       -> 403 (or 404 with { concealForbidden: true }, for
    //                           private resources, so their existence is not leaked)
    //   policy says yes      -> the resource is left on req.<type> (req.listing,
    //                           req.review) and the request continues
    //
    // Actions without a loader (listing:create, review:create) have no resource.
    // `{ resource: \"listing\" }` loads a different resource than the action's prefix
    // names: \"review:reply\" is decided by the listing's owner, so its route loads
    // the listing (req.listing) and the policy receives it.
    const Listing = require(\"../models/listing.js\");
    const Review = require(\"../models/review.js\");
    const { can } = require(\"../policies\");
    const { sameId } = require(\"../policies/shared\");
    const { ForbiddenError, NotFoundError } = require(\"../utils/errors\");
    const { redirectToLogin } = require(\"./auth\");

    const LOADERS = {
      listing: async (req) => Listing.findById(req.params.id),

      // The review must belong to the listing in the URL, otherwise
      // /listings/<any>/reviews/<id> would reach a review of another listing.
      review: async (req) => {
        const { id, reviewId } = req.params;
        const listing = await Listing.findById(id);
        if (!listing) return null;
        const belongs = (listing.reviews || []).some((r) => sameId(r, reviewId));
        if (!belongs) return null;
        return Review.findById(reviewId);
      },
    };

    const NOT_FOUND = {
      listing: \"That listing does not exist.\",
      review: \"That review does not exist.\",
    };

    const FORBIDDEN = {
      \"listing:create\": \"You are not allowed to create listings.\",
      \"listing:edit\": \"Only the host can edit this listing.\",
      \"listing:delete\": \"Only the host can delete this listing.\",
      \"review:create\": \"You are not allowed to write reviews.\",
      \"review:delete\": \"Only the author can delete this review.\",
      \"review:edit\": \"Only the author can edit this review.\",
      \"review:reply\": \"Only the host can reply to reviews.\",
    };

    function authorize(action, { concealForbidden = false, resource: kind } = {}) {
      // Fails at startup (route definition) for a typo, not on the first request.
      can(action, undefined, undefined);
      const type = kind || action.split(\":\")[0];
      const load = action.endsWith(\":create\") ? null : LOADERS[type];

      const authorizeMiddleware = async (req, res, next) => {
        if (!req.user) return redirectToLogin(req, res);

        let resource;
        if (load) {
          resource = await load(req);
          if (!resource) throw new NotFoundError(NOT_FOUND[type]);
        }

        if (!can(action, req.user, resource)) {
          if (concealForbidden) throw new NotFoundError(NOT_FOUND[type]);
          throw new ForbiddenError(FORBIDDEN[action]);
        }

        if (resource) req[type] = resource;
        next();
      };
      // Lets the route matrix test (P17-T01) see which action guards a route.
      authorizeMiddleware.policyAction = action;
      return authorizeMiddleware;
    }

    module.exports = { authorize };

    // A booking form whose session ran out (P08-T03). Logging in again creates a
    // new session with a new CSRF token, so the checkout form that was open in the
    // browser is rejected by the CSRF check before any route runs. For that one
    // route, instead of the dead-end 403 page, the guest is sent back to the GET
    // checkout page for the same stay: it asks them to log in if needed, then
    // returns to the checkout with a fresh form. Nothing is booked by the rejected
    // request, and the redirect target is built only from the route's own id (24
    // hex characters) and strictly checked stay parameters, never from a free-form
    // value.
    const CHECKOUT_POST = /^\\/listings\\/([0-9a-f]{24})\\/checkout\\/?$/i;
    const DATE_ONLY = /^\\d{4}-\\d{2}-\\d{2}$/;
    const GUESTS = /^\\d{1,3}$/;

    const MESSAGE =
      \"Your session ended before the booking was sent. Nothing was booked. Please check the details and confirm again.\";

    /**
     * Used as the CSRF middleware's `onInvalid`: returns true when it answered the
     * request (a redirect), false to let the normal 403 happen.
     */
    function recoverCheckout(req, res) {
      if (req.method !== \"POST\") return false;
      const match = CHECKOUT_POST.exec(req.path || \"\");
      if (!match || typeof req.flash !== \"function\") return false;
      const body = req.body && typeof req.body === \"object\" ? req.body : {};
      const params = new URLSearchParams();
      if (
        typeof body.in === \"string\" &&
        DATE_ONLY.test(body.in) &&
        typeof body.out === \"string\" &&
        DATE_ONLY.test(body.out) &&
        typeof body.guests === \"string\" &&
        GUESTS.test(body.guests)
      ) {
        params.set(\"in\", body.in);
        params.set(\"out\", body.out);
        params.set(\"guests\", body.guests);
      }
      const query = params.toString();
      req.flash(\"error\", MESSAGE);
      res.redirect(`/listings/${match[1]}/checkout${query ? `?${query}` : \"\"}`);
      return true;
    }

    module.exports = { recoverCheckout, CHECKOUT_POST };

    // CSRF protection (P01-T10, ADR-006): a synchronizer token kept in the session.
    //
    // - Each session gets one random token (`req.session.csrfToken`). It is exposed
    //   to views as `res.locals.csrfToken` (hidden field, <meta> tag, query string).
    // - Every request that is not GET/HEAD/OPTIONS must send the same token in the
    //   `X-CSRF-Token` header, the `_csrf` query parameter or the `_csrf` body field.
    // - Must run AFTER the session and the urlencoded body parser, and BEFORE
    //   multer and every router. Multipart forms cannot send the token in the body
    //   (multer has not parsed it yet), so they put it in the query string.
    // - The token is bound to the session. A new session (login and logout both
    //   regenerate it) gets a new token; a form rendered before that is rejected
    //   with the 403 page and the visitor is asked to reload.
    //
    // No package is used: csurf is deprecated and this is ~40 lines.
    const crypto = require(\"node:crypto\");
    const { ForbiddenError } = require(\"../utils/errors\");

    const SAFE_METHODS = new Set([\"GET\", \"HEAD\", \"OPTIONS\"]);
    const HEADER = \"x-csrf-token\";
    const FIELD = \"_csrf\";
    const TOKEN_BYTES = 32;

    const MESSAGE =
      \"Your form has expired or could not be verified. Please reload the page and try again.\";

    /** The session's token, created on first use. Undefined if there is no session. */
    function getToken(req) {
      if (!req.session) return undefined;
      if (typeof req.session.csrfToken !== \"string\") {
        req.session.csrfToken = crypto
          .randomBytes(TOKEN_BYTES)
          .toString(\"base64url\");
      }
      return req.session.csrfToken;
    }

    /** Constant-time comparison; false for anything that is not a matching string. */
    function tokensMatch(expected, supplied) {
      if (typeof expected !== \"string\" || typeof supplied !== \"string\")
        return false;
      const a = Buffer.from(expected);
      const b = Buffer.from(supplied);
      return a.length === b.length && crypto.timingSafeEqual(a, b);
    }

    /** Header, then query string, then body. Only strings count (no arrays). */
    function submittedToken(req) {
      const fromHeader = req.get(HEADER);
      if (typeof fromHeader === \"string\" && fromHeader) return fromHeader;
      const fromQuery = req.query && req.query[FIELD];
      if (typeof fromQuery === \"string\" && fromQuery) return fromQuery;
      const fromBody = req.body && req.body[FIELD];
      if (typeof fromBody === \"string\" && fromBody) return fromBody;
      return undefined;
    }

    /**
     * @param {object} [options]
     * @param {(req, res) => boolean} [options.onInvalid] called when the token is
     *   missing or wrong; return true if it already answered the request (the
     *   checkout form's \"session ended\" redirect, P08-T03), false for the 403
     */
    function csrfProtection({ onInvalid } = {}) {
      return function csrfProtectionMiddleware(req, res, next) {
        const expected = getToken(req);
        res.locals.csrfToken = expected || \"\";

        if (SAFE_METHODS.has(req.method)) return next();

        if (!expected || !tokensMatch(expected, submittedToken(req))) {
          if (req.log)
            req.log.warn({ event: \"csrf_rejected\" }, \"csrf token rejected\");
          if (onInvalid && onInvalid(req, res)) return undefined;
          return next(new ForbiddenError(MESSAGE, { code: \"csrf_invalid\" }));
        }

        // The field is not part of any form's data: validation schemas reject
        // unknown keys, so remove it once it has been checked.
        if (req.body && typeof req.body === \"object\") delete req.body[FIELD];
        next();
      };
    }

    module.exports = { csrfProtection, getToken, tokensMatch, SAFE_METHODS };

    const mongoose = require(\"mongoose\");
    const { AppError } = require(\"../utils/errors\");

    const TITLES = {
      400: \"Bad request\",
      401: \"Please log in\",
      403: \"Not allowed\",
      404: \"Page Not Found\",
      409: \"Conflict\",
      413: \"Upload too large\",
      429: \"Too many requests\",
      500: \"Something went wrong\",
    };
    const GENERIC_500 = \"Something went wrong on our side. Please try again.\";

    function titleFor(status) {
      return TITLES[status] || (status >= 500 ? TITLES[500] : \"Request failed\");
    }

    /**
     * Turns anything that was thrown into { status, message, code, expose }.
     * `message` is always safe to show to a visitor in production.
     * Handles non-Error throws (strings, objects, null).
     */
    function normalizeError(err) {
      if (err instanceof AppError) {
        const status = err.statusCode;
        return {
          status,
          code: err.code,
          message: status >= 500 ? GENERIC_500 : err.message,
        };
      }
      if (err instanceof mongoose.Error.CastError) {
        // e.g. /listings/not-an-object-id
        return { status: 404, code: \"not_found\", message: \"Page Not Found\" };
      }
      if (err instanceof mongoose.Error.ValidationError) {
        return {
          status: 400,
          code: \"validation_error\",
          message: \"The submitted data is not valid.\",
        };
      }
      if (err && typeof err === \"object\" && err.code === 11000) {
        return {
          status: 409,
          code: \"duplicate_key\",
          message: \"That value is already in use.\",
        };
      }
      if (err && typeof err === \"object\" && err.name === \"MulterError\") {
        const tooBig = err.code === \"LIMIT_FILE_SIZE\";
        const tooMany =
          err.code === \"LIMIT_FILE_COUNT\" || err.code === \"LIMIT_UNEXPECTED_FILE\";
        let message = \"The upload could not be processed.\";
        if (tooBig) message = \"That image is too large (maximum 5 MB).\";
        else if (tooMany)
          message =
            \"Too many files were sent (a listing can have at most 10 photos).\";
        return {
          status: tooBig ? 413 : 400,
          code: \"upload_rejected\",
          message,
        };
      }
      // http-errors style client errors from Express/body-parser (4xx, expose=true).
      if (
        err &&
        typeof err === \"object\" &&
        Number.isInteger(err.status) &&
        err.status >= 400 &&
        err.status < 500 &&
        err.expose === true
      ) {
        return {
          status: err.status,
          code: \"client_error\",
          message:
            typeof err.message === \"string\" ? err.message : titleFor(err.status),
        };
      }
      return { status: 500, code: \"internal_error\", message: GENERIC_500 };
    }

    function wantsJson(req) {
      const url = req.originalUrl || req.url || \"\";
      if (url === \"/api\" || url.startsWith(\"/api/\") || url.startsWith(\"/api?\")) {
        return true;
      }
      return req.accepts([\"html\", \"json\"]) === \"json\";
    }

    function detailOf(err) {
      if (err instanceof Error) return err.stack || `${err.name}: ${err.message}`;
      try {
        return `Non-error value thrown: ${JSON.stringify(err)}`;
      } catch {
        return `Non-error value thrown: ${String(err)}`;
      }
    }

    /**
     * Express error handler.
     * - production: only the safe message (never stack, driver text or 5xx messages)
     * - development/test: also the stack/detail
     * - /api paths (or Accept: application/json): JSON body, otherwise error.ejs
     * - if the response has already started, defer to Express (closes the socket)
     */
    function createErrorHandler({ isProduction, logger }) {
      return function errorHandler(err, req, res, next) {
        if (res.headersSent) {
          return next(err);
        }

        const { status, code, message } = normalizeError(err);
        const log = req.log || logger;
        const requestId = req.id;

        if (log) {
          if (status >= 500) {
            log.error({ err, status, code }, \"request failed\");
          } else {
            log.info({ status, code, errName: err && err.name }, \"client error\");
          }
        }

        const detail = isProduction ? undefined : detailOf(err);

        if (wantsJson(req)) {
          const body = { error: { status, code, message, requestId } };
          // Per-field messages of a validation error (P08-T02), already written for users.
          if (status < 500 && err && err.fields && typeof err.fields === \"object\") {
            body.error.fields = err.fields;
          }
          if (detail) body.error.detail = detail;
          return res.status(status).json(body);
        }

        res.status(status).render(
          \"error.ejs\",
          {
            status,
            title: titleFor(status),
            pageTitle: `${status} ${titleFor(status)}`,
            message,
            detail,
            requestId,
            // Defaults for the layout when the error happened before the locals
            // middleware ran (e.g. a session store failure).
            success: res.locals.success || [],
            error: res.locals.error || [],
            currUser: res.locals.currUser || null,
            currentPath: res.locals.currentPath || \"\",
            mapPublicToken: res.locals.mapPublicToken || \"\",
          },
          (renderErr, html) => {
            if (renderErr) {
              if (log) log.error({ err: renderErr }, \"error page failed to render\");
              res
                .status(status)
                .type(\"text/plain\")
                .send(`${titleFor(status)}\\n${message}`);
              return;
            }
            res.send(html);
          },
        );
      };
    }

    module.exports = { createErrorHandler, normalizeError };

    const { ValidationError } = require(\"../utils/errors\");
    const {
      listingSchema,
      reviewSchema,
      reviewEditSchema,
      reviewReplySchema,
    } = require(\"../validation\");

    // Authentication guards live in ./auth, object-level authorization (who may
    // edit/delete what) in ./authorize and ../policies (P02-T06).
    const { isLoggedIn, saveRedirectUrl, requireRole } = require(\"./auth\");
    const { authorize } = require(\"./authorize\");

    module.exports.isLoggedIn = isLoggedIn;
    module.exports.saveRedirectUrl = saveRedirectUrl;
    module.exports.requireRole = requireRole;
    module.exports.authorize = authorize;

    module.exports.validateListing = (req, res, next) => {
      // `?? {}`: a request with no parsable body must fail validation, not crash.
      const { error, value } = listingSchema.validate(req.body ?? {});
      if (error) {
        let errMsg = error.details.map((el) => el.message).join(\",\");
        throw new ValidationError(errMsg);
      }
      req.body = value; // trimmed strings, price as a number
      next();
    };

    function validateWith(schema) {
      return (req, res, next) => {
        // `?? {}`: a request with no parsable body must fail validation, not crash.
        const { error } = schema.validate(req.body ?? {});
        if (error) {
          throw new ValidationError(
            error.details.map((el) => el.message).join(\",\"),
          );
        }
        next();
      };
    }

    module.exports.validateReviewEdit = validateWith(reviewEditSchema);
    module.exports.validateReviewReply = validateWith(reviewReplySchema);

    module.exports.validateReview = (req, res, next) => {
      let { error } = reviewSchema.validate(req.body);
      if (error) {
        let errMsg = error.details.map((el) => el.message).join(\",\");
        throw new ValidationError(errMsg);
      } else next();
    };

    // Input guard (P17-T02): refuses request input that is shaped like an attack
    // before any controller sees it.
    //
    // 1. Operator and path injection. A key that contains \"$\" or \".\" (`email[$ne]=x`,
    //    `a.b=1`), or is named __proto__/constructor/prototype, has no place in any
    //    form or query this site accepts. Left alone, a nested value can end up
    //    inside a database filter (`{ username: { $ne: \"\" } }`) or an update.
    //    The request is refused (400), not silently cleaned, so a probe is visible
    //    in the logs and in tests.
    // 2. Shape. Nesting deeper than 8 levels, more than 5,000 values, or a NUL
    //    character in a string is refused too.
    //
    // It looks at req.query and req.body. Run it right after the urlencoded parser
    // (app.js), and again right after every multer middleware, because multer
    // parses its text fields later than the urlencoded parser and builds nested
    // objects the same way.
    //
    // Duplicate parameters (?q=a&q=b, \"HPP\") are NOT refused here: some parameters
    // legitimately repeat (checkboxes, ?ids=). Every query parser handles arrays on
    // purpose, and tests/unit/inputParsers.test.js pins how.
    const { ValidationError } = require(\"../utils/errors\");

    // Size limits of the form parser. 100 kb is far above any form of this site
    // (the largest text field, a listing description, is capped lower by Joi);
    // anything bigger answers 413 (see src/middleware/errors.js).
    const URLENCODED_OPTIONS = Object.freeze({
      extended: true,
      limit: \"100kb\",
      parameterLimit: 1000,
    });

    const MAX_DEPTH = 8;
    const MAX_VALUES = 5000;
    // \"$\" or \".\" anywhere, or a prototype name (also as the start of a flat key such as \"__proto__[x]\").
    const BAD_KEY = /[$.]|^(?:__proto__|constructor|prototype)(?:\\[|$)/;

    /**
     * @returns {null | { reason: \"operator_key\"|\"nul\"|\"too_deep\"|\"too_large\", path: string }}
     *   `path` names keys only (never values), safe to log.
     */
    function findUnsafeInput(root) {
      const stack = [{ value: root, path: \"\", depth: 0 }];
      let seen = 0;
      while (stack.length) {
        const { value, path, depth } = stack.pop();
        seen += 1;
        if (seen > MAX_VALUES) return { reason: \"too_large\", path };
        if (typeof value === \"string\") {
          if (value.includes(\"\\u0000\")) return { reason: \"nul\", path };
          continue;
        }
        if (value === null || typeof value !== \"object\") continue;
        if (depth >= MAX_DEPTH) return { reason: \"too_deep\", path };
        if (Array.isArray(value)) {
          value.forEach((item, i) =>
            stack.push({ value: item, path: `${path}[${i}]`, depth: depth + 1 }),
          );
          continue;
        }
        for (const key of Object.keys(value)) {
          const here = path ? `${path}.${key}` : key;
          if (BAD_KEY.test(key)) return { reason: \"operator_key\", path: here };
          stack.push({ value: value[key], path: here, depth: depth + 1 });
        }
      }
      return null;
    }

    function inputGuard(req, res, next) {
      for (const where of [\"query\", \"body\"]) {
        const found = findUnsafeInput(req[where]);
        if (found) {
          if (req.log) {
            req.log.warn(
              { where, reason: found.reason, path: found.path.slice(0, 80) },
              \"request input refused\",
            );
          }
          return next(new ValidationError(\"That request contains input we do not accept.\"));
        }
      }
      return next();
    }

    module.exports = { inputGuard, findUnsafeInput, URLENCODED_OPTIONS };

    const { ValidationError } = require(\"../utils/errors\");
    const { assertValidImage } = require(\"../services/images\");
    const {
      geocodeAddress,
      LocationNotFoundError,
      GeocoderUnavailableError,
    } = require(\"../services/geocoding\");

    // A new listing must come with a photo. (multer has already parsed the form.)
    module.exports.requireImage = (req, res, next) => {
      if (!req.file) {
        throw new ValidationError(\"Please choose an image for your listing.\");
      }
      next();
    };

    // A submitted photo must really be a PNG, JPEG or WebP (its first bytes are
    // checked, not the name or the type the browser claims) and small enough. Runs
    // before geocoding and before anything is sent to Cloudinary.
    module.exports.verifyUploadedImage = (req, res, next) => {
      if (req.file) assertValidImage(req.file);
      next();
    };

    function hasGeometry(listing) {
      return Boolean(
        listing.geometry &&
        Array.isArray(listing.geometry.coordinates) &&
        listing.geometry.coordinates.length >= 2,
      );
    }

    /**
     * Sets req.geometry from the submitted location + country.
     * On edit (req.listing is set by authorize(\"listing:edit\")) it only looks the place up again when
     * the location or country changed, or when the stored listing has no coordinates.
     * A place that cannot be found, or a geocoder outage, flashes a message and sends
     * the user back to the form (`backTo(req)`) so nothing is uploaded or saved.
     */
    module.exports.geocodeListing = ({ backTo }) =>
      async function geocodeListing(req, res, next) {
        const { location, country } = req.body.listing;
        const existing = req.listing;
        if (
          existing &&
          existing.location === location &&
          existing.country === country &&
          hasGeometry(existing)
        ) {
          return next();
        }
        try {
          req.geometry = await geocodeAddress({ location, country });
        } catch (err) {
          if (
            err instanceof LocationNotFoundError ||
            err instanceof GeocoderUnavailableError
          ) {
            if (req.log && err instanceof GeocoderUnavailableError) {
              req.log.warn({ err }, \"geocoding failed\");
            }
            req.flash(\"error\", err.message);
            return res.redirect(backTo(req));
          }
          throw err;
        }
        next();
      };

    // Puts `savedIds` (a Set of listing ids the signed-in member has saved) in
    // res.locals so the heart on a card or detail page shows the right state.
    // The heart is a convenience: if the lookup fails the page still renders, with
    // every heart empty, and the failure is logged.
    const mongoose = require(\"mongoose\");
    const { savedIdsFor } = require(\"../services/wishlists\");

    async function withSavedIds(req, res, next) {
      res.locals.savedIds = new Set();
      // No database connection (a unit test, or the database is down): skip the
      // lookup instead of waiting for it to time out.
      if (!req.user || mongoose.connection.readyState !== 1) return next();
      try {
        res.locals.savedIds = await savedIdsFor(req.user._id);
      } catch (err) {
        if (req.log) req.log.warn({ err }, \"could not load saved stays\");
      }
      next();
    }

    module.exports = { withSavedIds };

    // Security baseline (P01-T09): per-request CSP nonce, helmet headers, and rate
    // limits for the login and signup forms.
    const crypto = require(\"node:crypto\");
    const helmet = require(\"helmet\");
    const { rateLimit, ipKeyGenerator } = require(\"express-rate-limit\");
    const { AppError } = require(\"../utils/errors\");

    /** A fresh nonce per request; views put it on every inline <script>/<style>. */
    function assignCspNonce(req, res, next) {
      res.locals.cspNonce = crypto.randomBytes(16).toString(\"base64\");
      next();
    }

    const nonce = (req, res) => `'nonce-${res.locals.cspNonce}'`;

    // Third-party hosts the pages load from (see views/layouts/boilerPlate.ejs).
    const JSDELIVR = \"https://cdn.jsdelivr.net\"; // Bootstrap CSS/JS
    const CDNJS = \"https://cdnjs.cloudflare.com\"; // Font Awesome
    const GOOGLE_FONTS_CSS = \"https://fonts.googleapis.com\";
    const GOOGLE_FONTS_FILES = \"https://fonts.gstatic.com\";
    const MAPBOX = \"https://api.mapbox.com\";
    const MAPBOX_TILES = \"https://*.tiles.mapbox.com\";
    const MAPBOX_EVENTS = \"https://events.mapbox.com\";
    const CLOUDINARY = \"https://res.cloudinary.com\";
    const UNSPLASH = \"https://images.unsplash.com\"; // seed data pictures
    const MUSCACHE = \"https://a0.muscache.com\"; // pictures of imported sample_airbnb listings

    /**
     * helmet with a CSP that allows only this site, the CDNs above, Mapbox and
     * Cloudinary. Inline <script>/<style> blocks need the request's nonce. Inline
     * style=\"\" attributes are still allowed (style-src-attr): Mapbox GL and a few
     * views use them; scripts get no such exception.
     */
    function securityHeaders({ isProduction = false } = {}) {
      return helmet({
        contentSecurityPolicy: {
          useDefaults: true,
          directives: {
            defaultSrc: [\"'self'\"],
            scriptSrc: [\"'self'\", nonce, JSDELIVR, MAPBOX],
            scriptSrcAttr: [\"'none'\"],
            styleSrc: [\"'self'\", nonce, JSDELIVR, CDNJS, GOOGLE_FONTS_CSS, MAPBOX],
            styleSrcAttr: [\"'unsafe-inline'\"],
            fontSrc: [\"'self'\", GOOGLE_FONTS_FILES, CDNJS, \"data:\"],
            imgSrc: [
              \"'self'\",
              \"data:\",
              \"blob:\",
              CLOUDINARY,
              UNSPLASH,
              MUSCACHE,
              MAPBOX,
              MAPBOX_TILES,
            ],
            connectSrc: [\"'self'\", MAPBOX, MAPBOX_TILES, MAPBOX_EVENTS],
            workerSrc: [\"'self'\", \"blob:\"],
            childSrc: [\"'self'\", \"blob:\"],
            objectSrc: [\"'none'\"],
            baseUri: [\"'self'\"],
            formAction: [\"'self'\"],
            frameAncestors: [\"'self'\"],
            // Only meaningful (and safe) behind HTTPS.
            upgradeInsecureRequests: isProduction ? [] : null,
          },
        },
        // The Mapbox public token can be restricted by URL, which needs a Referer.
        referrerPolicy: { policy: \"strict-origin-when-cross-origin\" },
        strictTransportSecurity: isProduction ? undefined : false,
      });
    }

    function tooManyAttempts(req, res, next) {
      next(
        new AppError(
          429,
          \"Too many attempts. Please wait a few minutes and try again.\",
          { code: \"rate_limited\" },
        ),
      );
    }

    function tooManyAccountTries(req, res, next) {
      next(
        new AppError(429, \"Too many attempts on your account settings. Please wait a while and try again.\", {
          code: \"rate_limited\",
        }),
      );
    }

    function tooManyEmails(req, res, next) {
      next(
        new AppError(429, \"Too many email requests. Please wait a while and try again.\", {
          code: \"rate_limited\",
        }),
      );
    }

    function tooManySuggestions(req, res, next) {
      next(
        new AppError(429, \"Too many suggestion requests. Please wait a moment.\", {
          code: \"rate_limited\",
        }),
      );
    }

    function tooManyQuotes(req, res, next) {
      next(
        new AppError(429, \"Too many price checks. Please wait a minute and try again.\", {
          code: \"rate_limited\",
        }),
      );
    }

    function tooManyMessages(req, res, next) {
      next(
        new AppError(429, \"You are sending messages very quickly. Please wait a minute and try again.\", {
          code: \"rate_limited\",
        }),
      );
    }

    function tooManyReports(req, res, next) {
      next(
        new AppError(429, \"You are sending reports very quickly. Please wait a minute and try again.\", {
          code: \"rate_limited\",
        }),
      );
    }

    /**
     * Created per app (not at module load) so every test app starts with empty
     * counters. Login: 5 failed attempts per 15 minutes per IP (a successful
     * login is not counted). Signup: 10 per hour per IP. Quote: 60 per minute per IP.
     */
    function createAuthLimiters() {
      const common = {
        standardHeaders: true,
        legacyHeaders: false,
        handler: tooManyAttempts,
      };
      return {
        login: rateLimit({
          ...common,
          windowMs: 15 * 60 * 1000,
          limit: 5,
          skipSuccessfulRequests: true,
          // passport redirects both ways, so \"success\" means \"now logged in\".
          requestWasSuccessful: (req) => Boolean(req.user),
        }),
        signup: rateLimit({ ...common, windowMs: 60 * 60 * 1000, limit: 10 }),
        // Password change and account deletion (P02-T04): 10 an hour per signed-in
        // member, on top of the account's own failed-password lock.
        account: rateLimit({
          ...common,
          handler: tooManyAccountTries,
          windowMs: 60 * 60 * 1000,
          limit: 10,
          keyGenerator: (req) => (req.user && req.user._id ? `user:${req.user._id}` : ipKeyGenerator(req.ip)),
        }),
        // Password-reset and \"send the confirmation link again\" (P02-T05): 10 an
        // hour per IP, on top of the per-account limits in services/emailTokens.js.
        emailLink: rateLimit({ ...common, handler: tooManyEmails, windowMs: 60 * 60 * 1000, limit: 10 }),
        // Destination suggestions (P05-T06): a few per second while typing, and
        // the script waits 250 ms between keystrokes.
        destinations: rateLimit({ ...common, handler: tooManySuggestions, windowMs: 60 * 1000, limit: 120 }),
        // Price checks (P08-T02): a guest picking dates makes a few per minute.
        quote: rateLimit({ ...common, handler: tooManyQuotes, windowMs: 60 * 1000, limit: 60 }),
        // Messages and \"Contact host\" (P11-T02): 20 a minute per signed-in member.
        message: rateLimit({
          ...common,
          handler: tooManyMessages,
          windowMs: 60 * 1000,
          limit: 20,
          keyGenerator: (req) => (req.user && req.user._id ? `user:${req.user._id}` : ipKeyGenerator(req.ip)),
        }),
        // Reports (P12-T04): 5 a minute per signed-in member (per IP for anyone
        // else). The daily cap is counted in the database by services/reports.js.
        report: rateLimit({
          ...common,
          handler: tooManyReports,
          windowMs: 60 * 1000,
          limit: 5,
          keyGenerator: (req) => (req.user && req.user._id ? `user:${req.user._id}` : ipKeyGenerator(req.ip)),
        }),
      };
    }

    module.exports = { assignCspNonce, securityHeaders, createAuthLimiters };

    // \"Confirm your email first\" (P02-T05). Publishing a listing and booking a stay
    // need a confirmed address. Called at the top of the controller action (not as
    // route middleware, so the route guards the authorization matrix checks stay as
    // they are):
    //
    //   if (!ensureVerifiedEmail(req, res)) return;
    //
    // Returns true when the request may go on. Otherwise it has already answered
    // (a flash message and a redirect to /verify-email/needed) and returns false.
    // The server decides; nothing the browser sends can skip it.
    // With EMAIL_VERIFICATION_REQUIRED=false (app.locals.emailVerificationRequired)
    // it always returns true.
    const MESSAGE =
      \"Confirm your email address first. You need a confirmed address to publish a listing or book a stay.\";

    function isEmailVerified(user) {
      return Boolean(user && user.emailVerifiedAt);
    }

    function ensureVerifiedEmail(req, res) {
      if (!req.app.locals.emailVerificationRequired) return true;
      if (isEmailVerified(req.user)) return true;
      req.flash(\"error\", MESSAGE);
      res.redirect(\"/verify-email/needed\");
      return false;
    }

    module.exports = { ensureVerifiedEmail, isEmailVerified, MESSAGE };

    // Audit log (P14-T01): one row per administrative action, written by
    // src/services/audit.js in the same request as the action itself.
    //
    // Append-only by design: a row is created once and never changed. Saving an
    // existing row, every update/replace/delete query and bulkWrite with anything
    // but inserts are refused here, and the admin area has no route that edits or
    // removes rows (the viewer is read-only). A direct driver call
    // (`Model.collection`) or a database shell is outside what the model can
    // stop; restrict database credentials for that.
    const mongoose = require(\"mongoose\");
    const Schema = mongoose.Schema;

    const TARGET_TYPES = Object.freeze([
      \"user\",
      \"listing\",
      \"review\",
      \"report\",
      \"reservation\",
      \"system\",
    ]);

    const auditLogSchema = new Schema(
      {
        // The admin who acted. null for an action taken outside a login
        // (`scripts/make-admin.js`); `actorLabel` then says who/what did it.
        actor: { type: Schema.Types.ObjectId, ref: \"User\", default: null },
        actorLabel: { type: String, trim: true, maxlength: 120 },

        // Stable machine name, e.g. \"user.make_admin\", \"user.suspend\".
        action: {
          type: String,
          required: true,
          trim: true,
          match: /^[a-z][a-z0-9_]*(\\.[a-z][a-z0-9_]*)+$/,
          maxlength: 80,
        },
        targetType: { type: String, enum: TARGET_TYPES, required: true },
        targetId: { type: Schema.Types.ObjectId, default: null },

        // Required free text for actions that need a reason (suspensions...).
        reason: { type: String, trim: true, maxlength: 1000 },

        // Small, non-secret facts about the change (old/new status...). Never
        // passwords, tokens or whole documents.
        details: { type: Schema.Types.Mixed },

        requestId: { type: String, maxlength: 80 },
      },
      { timestamps: { createdAt: true, updatedAt: false }, versionKey: false },
    );

    // The audit page reads newest first, ties by _id (P18-T02, migration 010). With
    // only createdAt in the index the _id tie-break forced a sort of the whole log,
    // which only ever grows; this index delivers the order.
    auditLogSchema.index({ createdAt: -1, _id: -1 }, { name: \"createdAt_-1__id_-1\" });
    auditLogSchema.index({ actor: 1, createdAt: -1 });
    auditLogSchema.index({ targetType: 1, targetId: 1, createdAt: -1 });
    auditLogSchema.index({ action: 1, createdAt: -1 });

    const REFUSED = \"Audit log entries cannot be changed or deleted.\";

    auditLogSchema.pre(\"save\", function () {
      if (!this.isNew) throw new Error(REFUSED);
    });

    auditLogSchema.pre(
      [
        \"updateOne\",
        \"updateMany\",
        \"replaceOne\",
        \"findOneAndUpdate\",
        \"findOneAndReplace\",
        \"findOneAndDelete\",
        \"deleteOne\",
        \"deleteMany\",
      ],
      { document: false, query: true },
      function () {
        throw new Error(REFUSED);
      },
    );

    auditLogSchema.pre(
      [\"deleteOne\", \"updateOne\"],
      { document: true, query: false },
      function () {
        throw new Error(REFUSED);
      },
    );

    // Only inserts may go through bulkWrite (Mongoose 9 passes the operations as
    // the first argument; throwing refuses the call).
    auditLogSchema.pre(\"bulkWrite\", function (ops) {
      const onlyInserts =
        Array.isArray(ops) && ops.every((op) => op && op.insertOne);
      if (!onlyInserts) throw new Error(REFUSED);
    });

    const AuditLog = mongoose.model(\"AuditLog\", auditLogSchema);

    module.exports = AuditLog;
    module.exports.TARGET_TYPES = TARGET_TYPES;
    module.exports.REFUSED_MESSAGE = REFUSED;

    // A host's \"I am not available\" record (P07-T03). One document per block the
    // host created: the date range as asked and an optional private note.
    //
    // The nights themselves live in the night ledger (src/models/stayNight.js)
    // with source { kind: \"block\", id: <this _id> }; the ledger, not this record,
    // decides what is blocked. After a partial unblock the record may therefore
    // describe more nights than are still blocked; the calendar always reads the
    // ledger. A block with no night left is deleted.
    //
    // `from` is the first blocked night and `to` the day after the last one (the
    // same half-open range as a stay: ADR-003). Both are date-only (00:00:00Z).
    const mongoose = require(\"mongoose\");
    const { isDateOnly } = require(\"../utils/dates\");
    const Schema = mongoose.Schema;

    const NOTE_MAX_LENGTH = 200;

    const dateOnly = {
      type: Date,
      required: true,
      validate: {
        validator: isDateOnly,
        message: \"must be a date-only value (00:00:00.000Z)\",
      },
    };

    const availabilityBlockSchema = new Schema(
      {
        listing: { type: Schema.Types.ObjectId, ref: \"Listing\", required: true },
        from: dateOnly,
        to: dateOnly,
        note: { type: String, trim: true, maxlength: NOTE_MAX_LENGTH, default: \"\" },
        createdBy: { type: Schema.Types.ObjectId, ref: \"User\" },
      },
      { timestamps: { createdAt: true, updatedAt: false }, versionKey: false },
    );

    availabilityBlockSchema.index({ listing: 1, from: 1 });

    const AvailabilityBlock = mongoose.model(
      \"AvailabilityBlock\",
      availabilityBlockSchema,
    );
    AvailabilityBlock.NOTE_MAX_LENGTH = NOTE_MAX_LENGTH;

    module.exports = AvailabilityBlock;

    // A conversation between one guest and one host (P11-T02). Two kinds:
    //   - general: about a listing, started with \"Contact host\"
    //     (threadKey `listing:<listingId>:<guestId>`), and
    //   - reservation-bound: about one booking, opened by either side
    //     (threadKey `reservation:<reservationId>`).
    // The unique index on `threadKey` makes both idempotent: starting twice (or two
    // clicks at once) gives the same conversation. Created and changed only by
    // src/services/conversations.js.
    const mongoose = require(\"mongoose\");
    const { LIMITS } = require(\"../config/conversations\");

    const Schema = mongoose.Schema;

    const conversationSchema = new Schema(
      {
        threadKey: { type: String, required: true, maxlength: 80 },
        listing: { type: Schema.Types.ObjectId, ref: \"Listing\", required: true },
        guest: { type: Schema.Types.ObjectId, ref: \"User\", required: true },
        host: { type: Schema.Types.ObjectId, ref: \"User\", required: true },
        reservation: { type: Schema.Types.ObjectId, ref: \"Reservation\", default: null },

        // Messages this side has not read yet (one counter per side).
        unread: {
          guest: { type: Number, default: 0, min: 0 },
          host: { type: Number, default: 0, min: 0 },
        },
        // null until the first message: such a thread is not listed.
        lastMessageAt: { type: Date, default: null },
        lastMessage: {
          sender: { type: Schema.Types.ObjectId, ref: \"User\" },
          preview: { type: String, maxlength: LIMITS.preview },
        },
      },
      { timestamps: true },
    );

    conversationSchema.index({ threadKey: 1 }, { unique: true });
    // \"My conversations\", newest message first, for either side.
    conversationSchema.index({ guest: 1, lastMessageAt: -1 });
    conversationSchema.index({ host: 1, lastMessageAt: -1 });

    module.exports = mongoose.model(\"Conversation\", conversationSchema);

    // One-time links sent by email (P02-T05): \"confirm your address\" and \"reset your
    // password\". Only a SHA-256 hash of the token is stored, so a copy of the
    // database cannot be used to take over an account. A token works once (`usedAt`)
    // and only until `expiresAt`; the TTL index removes rows a week after that.
    const mongoose = require(\"mongoose\");

    const PURPOSES = [\"verify_email\", \"reset_password\"];
    const KEEP_AFTER_EXPIRY_SECONDS = 7 * 24 * 60 * 60;

    const emailTokenSchema = new mongoose.Schema(
      {
        user: { type: mongoose.Schema.Types.ObjectId, ref: \"User\", required: true },
        purpose: { type: String, enum: PURPOSES, required: true },
        // The address the link was sent to. A link for an address the account no
        // longer has confirms nothing.
        email: { type: String, required: true },
        tokenHash: { type: String, required: true, unique: true },
        expiresAt: { type: Date, required: true },
        usedAt: { type: Date, default: null },
      },
      { timestamps: { createdAt: true, updatedAt: false } },
    );

    emailTokenSchema.index({ expiresAt: 1 }, { expireAfterSeconds: KEEP_AFTER_EXPIRY_SECONDS });
    emailTokenSchema.index({ user: 1, purpose: 1, createdAt: -1 });

    const EmailToken = mongoose.model(\"EmailToken\", emailTokenSchema);

    module.exports = EmailToken;
    module.exports.PURPOSES = PURPOSES;

    // Listing model v2 (P04-T01). Money is integer paise (ADR-002). Documents
    // written before v2 are upgraded by scripts/migrations/003-listing-model-v2.js;
    // until it has run they still load (every new field has a default or is
    // optional) but show no price, because the old `price` field is now
    // `legacyPrice`.
    //
    // Validators only run on fields that change, so an old listing with, say, a
    // price under the floor can still be edited; the floor applies to new values.
    const mongoose = require(\"mongoose\");
    const Schema = mongoose.Schema;
    const Review = require(\"./review\");
    const { keysForListing } = require(\"../utils/searchKeys\");
    const { approximatePoint } = require(\"../utils/geo\");

    const STATUSES = [\"draft\", \"published\", \"unpublished\", \"suspended\"];
    const {
      PROPERTY_TYPE_VALUES: PROPERTY_TYPES,
      ROOM_TYPE_VALUES: ROOM_TYPES,
      VIBE_VALUES: VIBES,
      CANCELLATION_POLICY_VALUES: CANCELLATION_POLICIES,
    } = require(\"../config/constants\");

    // Nightly price floor: INR 100 (10 000 paise). A stay below it is almost
    // certainly a typo (1 instead of 1000). Ceiling: INR 10 lakh a night.
    const MIN_NIGHTLY_MINOR = 10000;
    const MAX_MINOR = 100000000;
    const MAX_IMAGES = 10;
    const MAX_GUESTS = 16;
    const TIME_PATTERN = /^([01]\\d|2[0-3]):[0-5]\\d$/;

    const integer = {
      validator: (v) => v === null || v === undefined || Number.isInteger(v),
      message: \"{PATH} must be a whole number\",
    };

    // The floor is checked for a new or changed value only: an amount that is
    // already stored (an old listing priced below today's floor) must not stop the
    // host from saving, unpublishing or deleting that listing.
    const minorAmount = (min, path) => ({
      type: Number,
      max: [MAX_MINOR, \"{PATH} is too large\"],
      validate: [
        integer,
        {
          validator: function atLeastMin(value) {
            if (value === null || value === undefined) return true;
            // `this` is the document when it validates itself (not in update validators).
            const isDoc = this && typeof this.isModified === \"function\";
            if (isDoc && !this.isNew && path && !this.isModified(path)) return true;
            return value >= min;
          },
          message: `{PATH} must be at least ${min} (minor units)`,
        },
      ],
    });

    // One gallery photo (P04-T03). `_id` identifies it in the photo routes.
    // `publicId` is the Cloudinary id (empty for pictures that are not ours, such
    // as seed data). `alt` is the text a screen reader reads, `caption` is shown
    // under the photo in the viewer. The array order is the display order and
    // `order` mirrors it (0 = the cover); src/services/images.js keeps both in step.
    const imageSchema = new Schema({
      url: { type: String, required: true },
      publicId: { type: String },
      alt: { type: String, trim: true, maxlength: 200 },
      caption: { type: String, trim: true, maxlength: 200 },
      order: { type: Number, min: 0, validate: integer, default: 0 },
    });

    const nearbyItemSchema = new Schema(
      {
        name: { type: String },
        category: { type: String },
        distanceMeters: { type: Number, min: 0 },
      },
      { _id: false },
    );

    const count = (def, min, max) => ({
      type: Number,
      default: def,
      min,
      max,
      validate: integer,
    });

    const listingSchema = new Schema(
      {
        title: {
          type: String,
          required: true,
        },

        description: {
          type: String,
        },

        // draft until the host publishes (P04-T05). Only published listings are
        // public. Listings created before v2 are migrated to published.
        status: {
          type: String,
          enum: STATUSES,
          default: \"draft\",
          required: true,
        },

        propertyType: { type: String, enum: PROPERTY_TYPES },
        roomType: { type: String, enum: ROOM_TYPES },
        // The setting a host chose (beach, mountain, ...). Optional, no default;
        // the category strip on /listings filters on it (P05-T04).
        vibe: { type: String, enum: VIBES },

        // The setting around the place (beach, mountain, ...). Optional: the host
        // chooses it in the basics step; the category strip on /listings reads it
        // (P05-T04). Listings that never set it simply match no vibe category.
        vibe: { type: String, enum: VIBES },

        // Mirror of the cover photo (images[0]), kept in step by the media service
        // (src/services/images.js) because older pages and the cards still read it.
        // images[] is the source of truth.
        image: {
          filename: {
            type: String,
          },
          url: {
            type: String,
          },
        },

        images: {
          type: [imageSchema],
          validate: {
            validator: (v) => v.length <= MAX_IMAGES,
            message: `A listing can have at most ${MAX_IMAGES} photos`,
          },
        },

        // Free text from the old form; kept because the pages still show it.
        location: {
          type: String,
        },

        country: {
          type: String,
        },

        // Structured address (the wizard fills it in, P04-T02). Derived from
        // location/country for old listings, which are flagged needsReview.
        address: {
          line1: { type: String, trim: true, maxlength: 200 },
          city: { type: String, trim: true, maxlength: 100 },
          state: { type: String, trim: true, maxlength: 100 },
          country: { type: String, trim: true, maxlength: 100 },
          postalCode: { type: String, trim: true, maxlength: 20 },
        },

        // True while address (or price/coordinates) was guessed during migration
        // and the host has not confirmed it.
        needsReview: { type: Boolean, default: false },

        // Precise point: private (never sent to the browser as such, P06-T02).
        // A draft has none until the location step has looked the address up.
        geometry: {
          type: {
            type: String,
            enum: [\"Point\"],
            required: function () {
              return this.status !== \"draft\";
            },
          },
          coordinates: {
            type: [Number],
            required: function () {
              return this.status !== \"draft\";
            },
          },
        },

        // Approximate point shown publicly; filled by P06-T02.
        publicGeometry: {
          type: { type: String, enum: [\"Point\"] },
          coordinates: { type: [Number], default: undefined },
        },

        timezone: { type: String, default: \"Asia/Kolkata\" }, // ADR-008

        capacity: {
          guests: count(2, 1, MAX_GUESTS),
          bedrooms: count(1, 0, 50),
          beds: count(1, 0, 50),
          bathrooms: {
            type: Number,
            default: 1,
            min: 0,
            max: 50,
            validate: {
              validator: (v) => v === null || v === undefined || (v * 2) % 1 === 0,
              message: \"{PATH} must be a whole or half number\",
            },
          },
        },

        amenities: { type: [{ type: String, trim: true, maxlength: 60 }] },
        // Declared by the host, never verified (P15-T05); keys from ACCESSIBILITY_FEATURES.
        accessibility: { type: [{ type: String, trim: true, maxlength: 40 }] },
        houseRules: { type: String, trim: true, maxlength: 2000 },
        // The host explicitly says there are no special rules (a readiness item).
        noSpecialRules: { type: Boolean, default: false },

        checkInTime: {
          type: String,
          default: \"14:00\",
          match: [TIME_PATTERN, \"Check-in time must look like 14:00\"],
        },
        checkOutTime: {
          type: String,
          default: \"11:00\",
          match: [TIME_PATTERN, \"Check-out time must look like 11:00\"],
        },

        minNights: { type: Number, default: 1, min: 1, max: 365, validate: integer },
        maxNights: { type: Number, default: 30, min: 1, max: 365, validate: integer },

        // Booking rules set by the host (P07-T06; src/services/bookingRules.js).
        // Notice is measured before the check-in moment, in the listing's time
        // zone. The cut-off is the time of day (listing zone) after which a stay
        // starting today can no longer be booked.
        advanceNoticeHours: { type: Number, default: 0, min: 0, max: 168, validate: integer },
        sameDayCutoffTime: {
          type: String,
          default: \"20:00\",
          match: [TIME_PATTERN, \"Same-day cut-off must look like 20:00\"],
        },

        instantBook: { type: Boolean, default: false },
        cancellationPolicy: {
          type: String,
          enum: CANCELLATION_POLICIES,
          default: \"moderate\",
        },

        pricing: {
          nightlyMinor: minorAmount(MIN_NIGHTLY_MINOR, \"pricing.nightlyMinor\"),
          weekendNightlyMinor: minorAmount(MIN_NIGHTLY_MINOR, \"pricing.weekendNightlyMinor\"),
          cleaningFeeMinor: { ...minorAmount(0, \"pricing.cleaningFeeMinor\"), default: 0 },
          // Price rules (P08-T04), applied in the order documented in
          // src/services/pricing.js. Weekend markup: percent added to a weekend
          // night's price, in basis points (2000 = 20 %).
          weekendBps: {
            type: Number,
            validate: { validator: (v) => v === undefined || v === null || (Number.isInteger(v) && v >= 0 && v <= 10000), message: \"Weekend markup must be a whole number of basis points from 0 to 10000.\" },
          },
          // At most 5 seasons, which may not overlap; `from` and `to` are date-only
          // (UTC midnight) and both inclusive.
          seasonalRates: {
            type: [
              new Schema(
                {
                  name: { type: String, required: true, trim: true, maxlength: 40 },
                  from: { type: Date, required: true },
                  to: { type: Date, required: true },
                  nightlyMinor: minorAmount(MIN_NIGHTLY_MINOR, \"pricing.seasonalRates.nightlyMinor\"),
                },
                { _id: false },
              ),
            ],
            validate: [
              { validator: (v) => !v || v.length <= 5, message: \"A listing can have at most 5 seasonal prices.\" },
              {
                validator: (v) => !v || v.every((x) => x.from <= x.to),
                message: \"A season cannot end before it starts.\",
              },
              {
                validator: (v) => {
                  const sorted = [...(v || [])].sort((a, b) => a.from - b.from);
                  return sorted.every((x, i) => i === 0 || x.from > sorted[i - 1].to);
                },
                message: \"Seasonal prices cannot overlap.\",
              },
            ],
            default: undefined,
          },
          // Whole-percent discounts for long stays, in basis points (1000 = 10 %),
          // at most 50 %. A stay of 28+ nights gets the monthly one, 7+ the weekly
          // one; the larger applies, never both.
          discounts: {
            weeklyBps: { type: Number, min: 0, max: 5000, validate: integer },
            monthlyBps: { type: Number, min: 0, max: 5000, validate: integer },
          },
          currency: {
            type: String,
            default: \"INR\",
            match: [/^[A-Z]{3}$/, \"Currency must be a 3-letter code such as INR\"],
          },
        },

        // The old rupee price, kept as it was stored before migration 003.
        legacyPrice: { type: Number },

        // Denormalised from reviews (P12-T02): changed only by services/ratings.js,
        // in one atomic update together with `reviews`. ratingAvg = sum / count.
        ratingSum: { type: Number, default: 0, min: 0, validate: integer },
        ratingAvg: { type: Number, default: 0, min: 0, max: 5 },
        ratingCount: { type: Number, default: 0, min: 0, validate: integer },

        // Nearby places cache (P15-T01).
        nearby: {
          fetchedAt: { type: Date },
          items: { type: [nearbyItemSchema] },
        },

        reviews: [
          {
            type: Schema.Types.ObjectId,
            ref: \"Review\",
          },
        ],
        owner: {
          type: Schema.Types.ObjectId,
          ref: \"User\",
        },

        // Listing wizard (P04-T02). `wizardSteps` lists the steps (1-5) the host has
        // completed; `draftToken` is a one-time id the first step carries so that
        // submitting it twice (double click, back button) makes one draft.
        wizardSteps: { type: [Number], default: undefined },
        draftToken: { type: String, maxlength: 64 },

        // Search keys (P05-T01): lower-case, accent-free copies of the city, state
        // and country, kept in step with the address by the validate hook below.
        cityKey: { type: String, maxlength: 100 },
        stateKey: { type: String, maxlength: 100 },
        countryKey: { type: String, maxlength: 100 },
        locationKey: { type: String, maxlength: 320 },

        // Set only on listings imported from a sample dataset (scripts/import-dataset.js);
        // the import matches on it, so running it twice never duplicates.
        importedFrom: {
          source: { type: String, maxlength: 40 },
          id: { type: String, maxlength: 64 },
        },

        // Places around the listing, from OpenStreetMap (P15-T01). Written only by
        // src/services/nearby.js; distances are straight lines from the PUBLIC
        // (approximate) point. `key` says which precise point the data is for.
        nearby: {
          fetchedAt: { type: Date },
          attemptedAt: { type: Date },
          source: { type: String, maxlength: 60 },
          key: { type: String, maxlength: 32 },
          failures: { type: Number, default: 0, min: 0 },
          nextRetryAt: { type: Date },
          items: [
            {
              _id: false,
              category: { type: String, maxlength: 20 },
              name: { type: String, maxlength: 100 },
              kind: { type: String, maxlength: 40 },
              distanceM: { type: Number, min: 0 },
            },
          ],
        },

        // Soft delete: the row stays, the pages stop showing it (P04-T05).
        deletedAt: { type: Date },

        // Set when the listing went from published to suspended only because its
        // host's account was suspended (P14-T02). Reinstating the host restores
        // exactly these listings; a listing suspended by moderation (P14-T03) does
        // not carry the flag and stays suspended.
        hiddenByOwnerSuspension: { type: Boolean },

        // Moderation (P14-T03). `reviewedAt/By`: an admin has looked at the
        // listing (marked reviewed, suspended it or restored it); a published
        // listing without it is in the \"new\" queue. `suspended*` describe the
        // CURRENT moderation suspension, cleared when the listing is restored (the
        // audit log keeps the history). The reason is shown to the host.
        moderation: {
          reviewedAt: { type: Date },
          reviewedBy: { type: Schema.Types.ObjectId, ref: \"User\" },
          suspendedAt: { type: Date },
          suspendedBy: { type: Schema.Types.ObjectId, ref: \"User\" },
          suspendReason: { type: String, trim: true, maxlength: 500 },
        },
      },
      { timestamps: true },
    );

    // The search keys always follow the address (and, for old listings, the
    // free-text location), so a save can never leave them stale. Updates that skip
    // `save()` (updateOne, bulkWrite) must set them themselves; see buildSeedListings.
    listingSchema.pre(\"validate\", function () {
      const keys = keysForListing(this);
      for (const [name, value] of Object.entries(keys)) {
        if (this.get(name) !== value) this.set(name, value);
      }
    });

    // The public point always follows the precise one (P06-T02): same listing, same
    // offset, so it moves only when the address does. Updates that skip save() must
    // set it themselves; migration 007 repairs the rest.
    listingSchema.pre(\"validate\", function () {
      const coordinates = this.get(\"geometry.coordinates\");
      const precise = {
        type: this.get(\"geometry.type\"),
        coordinates: coordinates ? Array.from(coordinates) : undefined,
      };
      const wanted = approximatePoint(precise, this._id);
      if (!wanted) {
        if (this.get(\"publicGeometry.type\") !== undefined) this.set(\"publicGeometry\", undefined);
        return;
      }
      const now = this.get(\"publicGeometry.coordinates\");
      const same =
        now &&
        this.get(\"publicGeometry.type\") === \"Point\" &&
        now[0] === wanted.coordinates[0] &&
        now[1] === wanted.coordinates[1];
      if (!same) this.set(\"publicGeometry\", wanted);
    });

    // A stay whose minimum is longer than its maximum can never be booked.
    listingSchema.pre(\"validate\", function () {
      if (
        Number.isFinite(this.minNights) &&
        Number.isFinite(this.maxNights) &&
        this.minNights > this.maxNights
      ) {
        this.invalidate(
          \"minNights\",
          \"Minimum nights cannot be more than maximum nights\",
          this.minNights,
        );
      }
    });

    // Index names are explicit and match the migrations, which build the same
    // indexes on existing databases (003, 005-007, and 010 for the sort indexes and
    // the two it drops). Migration 003 also built status_1_address.city_1 and
    // pricing.nightlyMinor_1; migration 010 (P18-T02) drops them because no query
    // uses them any more (see docs/PERFORMANCE.md).
    listingSchema.index({ owner: 1, status: 1 }, { name: \"owner_1_status_1\" });
    listingSchema.index(
      { title: \"text\", description: \"text\" },
      { name: \"title_text_description_text\" },
    );
    // Search (P05-T01): status + city + price, and status + country + price, serve
    // the destination box and the price filter. Built by migration 006.
    listingSchema.index(
      { status: 1, cityKey: 1, \"pricing.nightlyMinor\": 1 },
      { name: \"status_1_cityKey_1_pricing.nightlyMinor_1\" },
    );
    listingSchema.index(
      { status: 1, countryKey: 1, \"pricing.nightlyMinor\": 1 },
      { name: \"status_1_countryKey_1_pricing.nightlyMinor_1\" },
    );
    // Sorting the public listings without a destination (P18-T02, migration 010):
    // each order the search offers, and the home page and the map, read the
    // published listings already in order instead of sorting them in memory.
    // Price descending reads the price index backwards.
    listingSchema.index(
      { status: 1, _id: -1 },
      { name: \"status_1__id_-1\" },
    );
    listingSchema.index(
      { status: 1, createdAt: -1, _id: -1 },
      { name: \"status_1_createdAt_-1__id_-1\" },
    );
    listingSchema.index(
      { status: 1, ratingAvg: -1, ratingCount: -1, _id: -1 },
      { name: \"status_1_ratingAvg_-1_ratingCount_-1__id_-1\" },
    );
    listingSchema.index(
      { status: 1, \"pricing.nightlyMinor\": 1, _id: 1 },
      { name: \"status_1_pricing.nightlyMinor_1__id_1\" },
    );
    // Map queries (P06-T04) use the PUBLIC point only. Built by migration 007.
    listingSchema.index({ publicGeometry: \"2dsphere\" }, { name: \"publicGeometry_2dsphere\" });

    // One draft per (host, form): see draftToken. Built by migration 005.
    listingSchema.index(
      { owner: 1, draftToken: 1 },
      {
        name: \"owner_1_draftToken_1\",
        unique: true,
        partialFilterExpression: { draftToken: { $type: \"string\" } },
      },
    );

    // Deleting a listing removes the reviews written before bookings existed. A
    // review of a real stay (it has a reservation) is kept: it stays attached to
    // the listing's id and to the snapshot taken when it was written (P12-T01).
    listingSchema.post(\"findOneAndDelete\", async (listing) => {
      if (listing) {
        await Review.deleteMany({
          _id: { $in: listing.reviews },
          reservation: { $exists: false },
        });
      }
    });

    const Listing = mongoose.model(\"Listing\", listingSchema);

    Listing.STATUSES = STATUSES;
    Listing.MIN_NIGHTLY_MINOR = MIN_NIGHTLY_MINOR;
    Listing.MAX_IMAGES = MAX_IMAGES;

    module.exports = Listing;

    // Daily counters about one listing (P13-T03), one row per listing per day.
    // The day is a date-only UTC-midnight Date for the calendar day in the app's
    // time zone (utils/dates DEFAULT_TIMEZONE). Rows are only ever created and
    // bumped with $inc by services/listingStats.js; nothing here is exact:
    //   views          page opens, once per browser session per listing per day,
    //                  bots and the host's own visits left out
    //   saves          stays saved that day (an un-save does not subtract: the
    //                  lifetime total in ListingStat.saves is the net figure)
    //   checkoutStarts checkout page opens, same once-per-session-per-day rule
    const mongoose = require(\"mongoose\");
    const Schema = mongoose.Schema;

    const counter = { type: Number, default: 0, min: 0 };

    const listingDayStatSchema = new Schema({
      listing: { type: Schema.Types.ObjectId, ref: \"Listing\", required: true },
      day: { type: Date, required: true },
      views: counter,
      saves: counter,
      checkoutStarts: counter,
    });

    listingDayStatSchema.index({ listing: 1, day: 1 }, { unique: true });

    module.exports = mongoose.model(\"ListingDayStat\", listingDayStatSchema);

    // Counters about one listing, kept apart from the listing so counting never
    // rewrites (or races with) a host's edit. `saves` = wishlist entries holding
    // the listing (P10-T01). Host stats (P13-T03) read it.
    const mongoose = require(\"mongoose\");
    const Schema = mongoose.Schema;

    const listingStatSchema = new Schema({
      listing: {
        type: Schema.Types.ObjectId,
        ref: \"Listing\",
        required: true,
        unique: true,
      },
      saves: { type: Number, default: 0, min: 0 },
      // How often the stay was shown on, and opened from, a results page ordered by
      // Best match, per ordering (P15-T06; src/services/rankingStats.js).
      ranking: Object.fromEntries(
        [\"default\", \"work\", \"family\", \"weekend\"].map((variant) => [
          variant,
          { shown: { type: Number, default: 0, min: 0 }, clicked: { type: Number, default: 0, min: 0 } },
        ]),
      ),
    });

    module.exports = mongoose.model(\"ListingStat\", listingStatSchema);

    // One message (P11-T02): plain text, written only by
    // src/services/conversations.js `send`, never edited or deleted.
    const mongoose = require(\"mongoose\");
    const { LIMITS } = require(\"../config/conversations\");

    const Schema = mongoose.Schema;

    const messageSchema = new Schema(
      {
        conversation: {
          type: Schema.Types.ObjectId,
          ref: \"Conversation\",
          required: true,
        },
        sender: { type: Schema.Types.ObjectId, ref: \"User\", required: true },
        body: { type: String, required: true, maxlength: LIMITS.body },
      },
      { timestamps: { createdAt: true, updatedAt: false } },
    );

    messageSchema.index({ conversation: 1, _id: -1 });

    module.exports = mongoose.model(\"Message\", messageSchema);

    // In-app notification (P11-T01): one row per message to one member. Written
    // only through src/services/notifications.js `notify`, which validates the
    // text and the link; read only for the member it belongs to (every query in
    // the service filters on `user`).
    //
    // Lifecycle: created unread (`readAt: null`, no `deleteAfter`). Reading sets
    // `readAt` and `deleteAfter` (read time + READ_RETENTION_DAYS); the TTL index
    // on `deleteAfter` then removes the row. MongoDB ignores a row whose
    // `deleteAfter` is not a date, so unread rows are never removed by it.
    const mongoose = require(\"mongoose\");
    const {
      REF_KINDS,
      TYPE_PATTERN,
      LIMITS,
    } = require(\"../config/notifications\");

    const Schema = mongoose.Schema;

    const notificationSchema = new Schema(
      {
        // The only person who can see this row.
        user: {
          type: Schema.Types.ObjectId,
          ref: \"User\",
          required: true,
        },
        type: {
          type: String,
          required: true,
          trim: true,
          match: TYPE_PATTERN,
          maxlength: LIMITS.type,
        },
        // What the message is about (a booking, a listing...), if anything.
        ref: {
          kind: { type: String, enum: REF_KINDS },
          id: { type: Schema.Types.ObjectId },
        },
        // Plain text; views escape it. `url` is a same-site path.
        title: {
          type: String,
          required: true,
          trim: true,
          maxlength: LIMITS.title,
        },
        body: { type: String, trim: true, maxlength: LIMITS.body },
        url: { type: String, trim: true, maxlength: LIMITS.url },
        readAt: { type: Date, default: null },
        deleteAfter: { type: Date },
      },
      { timestamps: { createdAt: true, updatedAt: false } },
    );

    // The list (newest first, optionally unread only) and the unread count.
    notificationSchema.index({ user: 1, readAt: 1, createdAt: -1 });
    // TTL: removes a read notification once `deleteAfter` has passed.
    notificationSchema.index({ deleteAfter: 1 }, { expireAfterSeconds: 0 });

    module.exports = mongoose.model(\"Notification\", notificationSchema);

    // A report about a listing, review, member or message (P12-T04). Created only
    // through src/services/reports.js. Never deleted: moderators (P14-T04) close
    // it as resolved or dismissed.
    //
    // One OPEN report per (reporter, target): the partial unique index below is
    // what makes that true under concurrent requests; the service only turns the
    // index error into a friendly message. Once a report is closed the same
    // person may report the same target again.
    const mongoose = require(\"mongoose\");
    const {
      KIND_VALUES,
      REASON_VALUES,
      REPORT_STATUSES,
      LIMITS,
    } = require(\"../config/reports\");
    const Schema = mongoose.Schema;

    const reportSchema = new Schema(
      {
        reporter: { type: Schema.Types.ObjectId, ref: \"User\", required: true },
        targetKind: { type: String, enum: KIND_VALUES, required: true },
        targetId: { type: Schema.Types.ObjectId, required: true },
        // Who made the thing that was reported (listing host, review author, the
        // member). null when unknown (an old review without an author).
        targetOwner: { type: Schema.Types.ObjectId, ref: \"User\", default: null },
        // Short text so the reporter's list still reads when the target changes or goes.
        targetLabel: { type: String, trim: true, maxlength: 160 },

        reason: { type: String, enum: REASON_VALUES, required: true },
        details: { type: String, trim: true, maxlength: LIMITS.detailsMax },

        status: {
          type: String,
          enum: REPORT_STATUSES,
          default: \"open\",
          required: true,
        },
        // Filled when a moderator closes it (P14-T04).
        resolvedAt: { type: Date },
        resolvedBy: { type: Schema.Types.ObjectId, ref: \"User\" },
        resolutionNote: { type: String, trim: true, maxlength: 500 },
      },
      { timestamps: true },
    );

    reportSchema.index(
      { reporter: 1, targetKind: 1, targetId: 1 },
      { unique: true, partialFilterExpression: { status: \"open\" } },
    );
    reportSchema.index({ reporter: 1, createdAt: -1 });
    reportSchema.index({ status: 1, createdAt: -1 }); // the moderators' queue
    reportSchema.index({ targetKind: 1, targetId: 1 });

    module.exports = mongoose.model(\"Report\", reportSchema);

    // A booking (P07-T05). Created only through src/services/reservations.js,
    // which holds the nights in the ledger first (ADR-004). Never hard-deleted.
    //
    // The snapshots keep the guest's contract correct when the listing changes
    // later: the price breakdown, and the title, rules and policy as they were.
    const mongoose = require(\"mongoose\");
    const { isDateOnly } = require(\"../utils/dates\");
    const { STATUSES, ACTORS } = require(\"../services/stateMachine\");
    const Schema = mongoose.Schema;

    const dateOnly = {
      type: Date,
      required: true,
      validate: {
        validator: isDateOnly,
        message: \"{PATH} must be a date-only value (00:00:00.000Z)\",
      },
    };
    const minor = { type: Number, min: 0, validate: Number.isSafeInteger };

    const historySchema = new Schema(
      {
        from: { type: String, enum: [...STATUSES, null], default: null },
        to: { type: String, enum: STATUSES, required: true },
        at: { type: Date, required: true },
        actor: { type: String, enum: ACTORS, required: true },
        by: { type: Schema.Types.ObjectId, ref: \"User\" },
        note: { type: String, maxlength: 500 },
      },
      { _id: false },
    );

    const reservationSchema = new Schema(
      {
        listing: { type: Schema.Types.ObjectId, ref: \"Listing\", required: true },
        guest: { type: Schema.Types.ObjectId, ref: \"User\", required: true },
        host: { type: Schema.Types.ObjectId, ref: \"User\", required: true },

        checkIn: dateOnly,
        checkOut: dateOnly,
        nights: { type: Number, required: true, min: 1, max: 90, validate: Number.isInteger },
        guests: { type: Number, required: true, min: 1, max: 100, validate: Number.isInteger },

        status: { type: String, enum: STATUSES, required: true },
        statusHistory: { type: [historySchema], default: [] },
        // Set only while a host-approval request is pending (the ledger rows carry
        // the same instant).
        holdExpiresAt: { type: Date },

        pricingSnapshot: {
          lines: { type: [Schema.Types.Mixed], default: [] },
          nights: minor,
          subtotalMinor: minor,
          cleaningMinor: minor,
          serviceFeeMinor: minor,
          taxMinor: minor,
          totalMinor: { ...minor, required: true },
          avgPerNightMinor: minor,
          currency: { type: String, required: true, match: /^[A-Z]{3}$/ },
          taxMode: { type: String },
          taxIncluded: { type: Boolean },
          breakdownVersion: { type: Number },
        },

        listingSnapshot: {
          title: { type: String },
          city: { type: String },
          coverUrl: { type: String },
          houseRules: { type: String },
          noSpecialRules: { type: Boolean },
          cancellationPolicy: { type: String },
          checkInTime: { type: String },
          checkOutTime: { type: String },
          timezone: { type: String },
          instantBook: { type: Boolean },
        },

        // Chosen by the browser per checkout page; a repeated submit returns the
        // original reservation (unique with the guest).
        idempotencyKey: { type: String, required: true, minlength: 8, maxlength: 64 },

        // Set once by the sweeper when \"check-in tomorrow\" was sent (P11-T04), so
        // a repeated pass or a second instance sends it only once.
        reminders: { checkIn: { type: Date } },

        cancelReason: { type: String, trim: true, maxlength: 500 },
        cancelledBy: { type: String, enum: ACTORS },
        // What a cancellation refunds (P09-T03), written in the same update that
        // changes the status. CALCULATED AND RECORDED only: no money moves
        // (payments are simulated until P16, which acts on this record).
        refund: {
          amountMinor: minor,
          retainedMinor: minor,
          totalMinor: minor,
          currency: { type: String, match: /^[A-Z]{3}$/ },
          policy: { type: String },
          rule: { type: String },
          calculatedAt: { type: Date },
        },
        // Every change of dates (P09-T04), oldest first. The price snapshot above
        // always describes the CURRENT dates; each entry keeps what it replaced and
        // the difference between the two totals. CALCULATED AND RECORDED only: no
        // money moves (payments are simulated).
        modifications: {
          type: [
            new Schema(
              {
                at: { type: Date, required: true },
                by: { type: Schema.Types.ObjectId, ref: \"User\" },
                from: {
                  checkIn: dateOnly,
                  checkOut: dateOnly,
                  nights: { type: Number, min: 1, max: 90 },
                  totalMinor: minor,
                },
                to: {
                  checkIn: dateOnly,
                  checkOut: dateOnly,
                  nights: { type: Number, min: 1, max: 90 },
                  totalMinor: minor,
                },
                // new total - old total; negative when the new stay costs less
                differenceMinor: { type: Number, validate: Number.isSafeInteger },
                currency: { type: String, match: /^[A-Z]{3}$/ },
                // a pending request went back to the host for a new answer
                reapproval: { type: Boolean, default: false },
              },
              { _id: false },
            ),
          ],
          default: [],
        },
        paymentStatus: {
          type: String,
          enum: [\"none\", \"simulated_paid\", \"refunded_simulated\"],
          default: \"none\",
        },
      },
      { timestamps: true },
    );

    reservationSchema.pre(\"validate\", function () {
      if (this.checkIn && this.checkOut && this.checkOut <= this.checkIn) {
        this.invalidate(\"checkOut\", \"Check-out must be after check-in.\");
      }
    });

    reservationSchema.index({ guest: 1, createdAt: -1 });
    // The host's requests inbox (P18-T02, migration 010): pending requests by
    // hold, confirmed stays by check-in, already in order. They also serve every
    // query on (host, status), which is why the plain (host, status) index is gone.
    reservationSchema.index(
      { host: 1, status: 1, holdExpiresAt: 1, _id: 1 },
      { name: \"host_1_status_1_holdExpiresAt_1__id_1\" },
    );
    reservationSchema.index(
      { host: 1, status: 1, checkIn: 1, _id: 1 },
      { name: \"host_1_status_1_checkIn_1__id_1\" },
    );
    reservationSchema.index({ listing: 1, checkIn: 1 });
    reservationSchema.index({ guest: 1, idempotencyKey: 1 }, { unique: true });
    // The sweeper (P07-T07) looks for requests past their hold and for stays whose
    // check-out has passed.
    reservationSchema.index({ status: 1, holdExpiresAt: 1 });
    reservationSchema.index({ status: 1, checkOut: 1 });

    module.exports = mongoose.model(\"Reservation\", reservationSchema);

    const mongoose = require(\"mongoose\");
    const Schema = mongoose.Schema;

    // Review model v2 (P12-T01). A new review belongs to one completed
    // reservation: `reservation` is set, `legacy` is false, and a partial unique
    // index allows one review per reservation. Reviews written before bookings
    // existed have no reservation and are marked `legacy: true` by migration 008
    // (ADR-010); they keep their content and are shown with a note.
    //
    // `listing` is the listing that was stayed in. It is kept even if the listing
    // is later deleted, together with `listingSnapshot` (title and city when the
    // review was written), so a review never loses what it was about.
    const reviewSchema = new Schema(
      {
        comment: String,
        rating: {
          type: Number,
          min: 1,
          max: 5,
        },
        author: {
          type: Schema.Types.ObjectId,
          ref: \"User\",
        },
        listing: {
          type: Schema.Types.ObjectId,
          ref: \"Listing\",
        },
        reservation: {
          type: Schema.Types.ObjectId,
          ref: \"Reservation\",
        },
        legacy: {
          type: Boolean,
          default: false,
        },
        // Moderation (P14-T04). A hidden review is not shown on the listing and is
        // not in the listing's rating totals; its stay still counts as reviewed, so
        // the guest cannot simply write another. Reviews written before this field
        // existed have no status and are visible.
        status: {
          type: String,
          enum: [\"visible\", \"hidden\"],
          default: \"visible\",
        },
        moderation: {
          hiddenAt: Date,
          hiddenBy: { type: Schema.Types.ObjectId, ref: \"User\" },
          hiddenReason: { type: String, trim: true, maxlength: 500 },
        },
        listingSnapshot: {
          title: String,
          city: String,
        },
        // Set when the author changes the rating or comment inside the edit window
        // (P12-T03). Shown as \"Edited\" next to the review.
        editedAt: Date,
        // The host's one public reply (P12-T03). The host is the listing's owner;
        // `author` records who wrote it. Absent until the host replies.
        reply: {
          text: { type: String, trim: true, maxlength: 1000 },
          author: { type: Schema.Types.ObjectId, ref: \"User\" },
          createdAt: Date,
          editedAt: Date,
        },
      },
      { timestamps: true },
    );

    // One review per reservation. Partial, so legacy reviews (no reservation) do
    // not collide. Built by migration 008 and by the model at startup.
    reviewSchema.index(
      { reservation: 1 },
      {
        name: \"reservation_1_unique\",
        unique: true,
        partialFilterExpression: { reservation: { $type: \"objectId\" } },
      },
    );
    // A listing's reviews, newest first (the listing page and its aggregates).
    reviewSchema.index(
      { listing: 1, createdAt: -1 },
      { name: \"listing_1_createdAt_-1\" },
    );
    reviewSchema.index(
      { author: 1, createdAt: -1 },
      { name: \"author_1_createdAt_-1\" },
    );

    module.exports = mongoose.model(\"Review\", reviewSchema);

    // A search a member saved with a name (P10-T02). `query` is the canonical
    // query string of /listings (built by the server from the validated search
    // state, never copied from the browser), without the page number.
    const mongoose = require(\"mongoose\");
    const Schema = mongoose.Schema;

    const savedSearchSchema = new Schema(
      {
        owner: { type: Schema.Types.ObjectId, ref: \"User\", required: true },
        name: { type: String, trim: true, required: true, maxlength: 60 },
        query: { type: String, required: true, maxlength: 1000 },
      },
      { timestamps: true },
