    module.exports.reviewSchema = Joi.object({
        review: Joi.object({
            reservation: Joi.string().hex().length(24).required(),
            rating: Joi.number().integer().required().min(1).max(5),
            comment: Joi.string().trim().min(1).max(2000).required(),
