    module.exports.reviewEditSchema = Joi.object({
        review: Joi.object({
            rating: Joi.number().integer().required().min(1).max(5),
            comment: Joi.string().trim().min(1).max(2000).required(),
            from: Joi.string().valid(\"trip\", \"listing\"),
        }).required(),
    });

    // The host's reply to a review (P12-T03).
    module.exports.reviewReplySchema = Joi.object({
        reply: Joi.object({
            text: Joi.string().trim().min(1).max(1000).required(),
        }).required(),
    });

    // ---- Signup (P02-T02) -------------------------------------------------------
    const { isCommonPassword } = require(\"./commonPasswords\");

    const USERNAME_PATTERN = /^[A-Za-z0-9_]+$/;
    const PASSWORD_MIN = 10;
    const PASSWORD_MAX = 128;


    // The password rule, shared by signup and \"change password\" (P02-T04): length,
    // not a common password, not the username or the email's name. The username
    // and email come from the object being validated (signup) or from the Joi
    // `context` option (change password, where the object has no username).
    function passwordRule() {
        return Joi.string().min(PASSWORD_MIN).max(PASSWORD_MAX).required()
            .custom((value, helpers) => {
                if (value.length > PASSWORD_MAX) return value; // already refused for its length
                if (isCommonPassword(value)) return helpers.error(\"password.common\");
                const { username, email } = { ...(helpers.prefs.context || {}), ...(helpers.state.ancestors[0] || {}) };
                const lower = value.toLowerCase();
                const localPart = typeof email === \"string\" ? email.split(\"@\")[0].toLowerCase() : \"\";
                if (
                    (typeof username === \"string\" && lower === username.trim().toLowerCase()) ||
                    (localPart && lower === localPart)
                ) {
                    return helpers.error(\"password.personal\");
                }
                return value;
            })
            .messages({
                \"any.required\": \"Choose a password.\",
                \"string.base\": \"Choose a password.\",
                \"string.empty\": \"Choose a password.\",
                \"string.min\": `Password must be at least ${PASSWORD_MIN} characters.`,
                \"string.max\": `Password must be at most ${PASSWORD_MAX} characters.`,
                \"password.common\": \"That password is too common. Choose a less predictable one.\",
                \"password.personal\": \"Password must not be the same as your username or email.\",
            });
    }

    // The messages are written for the person filling in the form and are shown as
    // they are (flash). Joi's own wording never reaches the page.
    module.exports.signupSchema = Joi.object({
        username: Joi.string().trim().min(3).max(30).pattern(USERNAME_PATTERN).required()
            .messages({
                \"any.required\": \"Choose a username.\",
                \"string.base\": \"Choose a username.\",
                \"string.empty\": \"Choose a username.\",
                \"string.min\": \"Username must be 3 to 30 characters.\",
                \"string.max\": \"Username must be 3 to 30 characters.\",
                \"string.pattern.base\": \"Username can only contain letters, numbers and underscores.\",
            }),
        email: Joi.string().trim().lowercase().max(254).email({ tlds: { allow: false } }).required()
            .messages({
                \"any.required\": \"Enter your email address.\",
                \"string.base\": \"Enter your email address.\",
                \"string.empty\": \"Enter your email address.\",
                \"string.max\": \"Enter a valid email address.\",
                \"string.email\": \"Enter a valid email address.\",
            }),
        password: passwordRule(),
    });

    // Change password (P02-T04). Validate with `{ context: { username, email } }`.
    // The current password is only checked for being present: it is verified
    // against the stored hash, never against the strength rules.
    module.exports.changePasswordSchema = Joi.object({
        currentPassword: Joi.string().max(PASSWORD_MAX).required().messages({
            \"any.required\": \"Enter your current password.\",
            \"string.base\": \"Enter your current password.\",
            \"string.empty\": \"Enter your current password.\",
            \"string.max\": \"Enter your current password.\",
        }),
        newPassword: passwordRule(),
        confirmPassword: Joi.string().empty(\"\").required().valid(Joi.ref(\"newPassword\")).messages({
            \"any.required\": \"Type the new password again to confirm it.\",
            \"string.empty\": \"Type the new password again to confirm it.\",
            \"any.only\": \"The two new passwords do not match.\",
        }),
    }).custom((value, helpers) => {
        if (value.currentPassword === value.newPassword) return helpers.error(\"password.same\");
        return value;
    }).messages({ \"password.same\": \"The new password must be different from the current one.\" });

    // Delete account (P02-T04): the password again, and the word DELETE.
    module.exports.deleteAccountSchema = Joi.object({
        password: Joi.string().max(PASSWORD_MAX).required().messages({
            \"any.required\": \"Enter your password to delete your account.\",
            \"string.base\": \"Enter your password to delete your account.\",
            \"string.empty\": \"Enter your password to delete your account.\",
            \"string.max\": \"Enter your password to delete your account.\",
        }),
        confirm: Joi.string().trim().valid(\"DELETE\").required().messages({
            \"any.required\": \"Type DELETE to confirm.\",
            \"string.base\": \"Type DELETE to confirm.\",
            \"string.empty\": \"Type DELETE to confirm.\",
            \"any.only\": \"Type DELETE to confirm.\",
        }),
    });

    // Forgot password (P02-T05): only the address; the answer never says whether it is known.
    module.exports.forgotPasswordSchema = Joi.object({
        email: Joi.string().trim().lowercase().max(254).email({ tlds: { allow: false } }).required()
            .messages({
                \"any.required\": \"Enter your email address.\",
                \"string.base\": \"Enter your email address.\",
                \"string.empty\": \"Enter your email address.\",
                \"string.max\": \"Enter a valid email address.\",
                \"string.email\": \"Enter a valid email address.\",
            }),
    });

    // Reset password (P02-T05). Validate with `{ context: { username, email } }`.
    module.exports.resetPasswordSchema = Joi.object({
        token: Joi.string().pattern(/^[A-Za-z0-9_-]{43}$/).required().messages({
            \"any.required\": \"This link is not valid.\",
            \"string.base\": \"This link is not valid.\",
            \"string.empty\": \"This link is not valid.\",
            \"string.pattern.base\": \"This link is not valid.\",
        }),
        newPassword: passwordRule(),
        confirmPassword: Joi.string().empty(\"\").required().valid(Joi.ref(\"newPassword\")).messages({
            \"any.required\": \"Type the new password again to confirm it.\",
            \"string.empty\": \"Type the new password again to confirm it.\",
            \"any.only\": \"The two passwords do not match.\",
        }),
    });

    module.exports.USERNAME_PATTERN = USERNAME_PATTERN;
    module.exports.PASSWORD_MIN = PASSWORD_MIN;
    module.exports.PASSWORD_MAX = PASSWORD_MAX;

    // The \"edit my profile\" form (P02-T03). Only these three fields are accepted;
    // anything else in the request (an id, a role, an email) is refused, so the form
    // can never be used to change more than it shows.
    const Joi = require(\"joi\");

    // eslint-disable-next-line no-control-regex -- refusing control characters is the point
    const NO_CONTROL_CHARS = /^[^\\u0000-\\u0009\\u000B\\u000C\\u000E-\\u001F\\u007F]*$/;

    const profileSchema = Joi.object({
      displayName: Joi.string()
        .trim()
        .max(60)
        // eslint-disable-next-line no-control-regex -- refusing control characters is the point
        .pattern(/^[^\\u0000-\\u001F\\u007F]*$/)
        .allow(\"\")
        .default(\"\")
        .label(\"Display name\")
        .messages({
          \"string.max\": \"Display name must be 60 characters or fewer.\",
          \"string.pattern.base\": \"Display name cannot contain control characters.\",
        }),
      // Line breaks are kept (as \"\\n\"); other control characters are refused.
      bio: Joi.string()
        .trim()
        .max(500)
        .allow(\"\")
        .default(\"\")
        .custom((value) => value.replace(/\\r\\n?/g, \"\\n\"))
        .pattern(NO_CONTROL_CHARS)
        .label(\"Bio\")
        .messages({
          \"string.max\": \"Bio must be 500 characters or fewer.\",
          \"string.pattern.base\": \"Bio cannot contain control characters.\",
        }),
      removeAvatar: Joi.boolean()
        .truthy(\"on\", \"1\", \"true\")
        .falsy(\"off\", \"0\", \"false\", \"\")
        .default(false),
    });

    /**
     * @returns {{ value: object|undefined, errors: Record<string,string> }}
     */
    function validateProfile(body) {
      const { error, value } = profileSchema.validate(body ?? {}, {
        abortEarly: false,
        errors: { wrap: { label: false } },
      });
      if (!error) return { value, errors: {} };
      const errors = {};
      for (const detail of error.details) {
        const field = detail.path[0] ?? \"form\";
        if (!errors[field]) errors[field] = detail.message;
      }
      return { value: undefined, errors };
    }

    module.exports = { validateProfile, profileSchema };

    // Query of GET /api/listings/:id/quote?in=&out=&guests= (P08-T02). Only plain
    // strings are accepted (a repeated parameter or in[x]=y is refused), dates are
    // strict YYYY-MM-DD (ADR-003), guests a whole number. Problems are reported
    // per field so the page can show each next to its input.
    const { tryParseDateOnly, isAfter } = require(\"../utils/dates\");
    const { ValidationError } = require(\"../utils/errors\");

    const GUESTS = /^\\d{1,3}$/;

    function dateField(query, name, label, fields) {
      const raw = query ? query[name] : undefined;
      if (raw === undefined || raw === \"\") {
        fields[name] = `${label} is required (YYYY-MM-DD).`;
        return null;
      }
      const date = typeof raw === \"string\" ? tryParseDateOnly(raw) : null;
      if (!date) {
        fields[name] = `${label} must be a valid date in YYYY-MM-DD format.`;
        return null;
      }
      return date;
    }

    /**
     * @returns {{checkIn: Date, checkOut: Date, guests: number}}
     * @throws {ValidationError} 400, with `.fields` = { in?, out?, guests? }
     */
    function parseQuoteQuery(query) {
      const fields = {};
      const checkIn = dateField(query, \"in\", \"Check-in\", fields);
      const checkOut = dateField(query, \"out\", \"Check-out\", fields);
      if (checkIn && checkOut && !isAfter(checkOut, checkIn)) {
        fields.out = \"Check-out must be after check-in.\";
      }
      const rawGuests = query ? query.guests : undefined;
      let guests = null;
      if (rawGuests === undefined || rawGuests === \"\") {
        fields.guests = \"Guests is required (a whole number, 1 or more).\";
      } else if (
        typeof rawGuests !== \"string\" ||
        !GUESTS.test(rawGuests) ||
        Number(rawGuests) < 1
      ) {
        fields.guests = \"Guests must be a whole number, 1 or more.\";
      } else {
        guests = Number(rawGuests); // the place's own capacity is a booking rule
      }
      const names = Object.keys(fields);
      if (names.length > 0) {
        const err = new ValidationError(fields[names[0]]);
        err.fields = fields;
        throw err;
      }
      return { checkIn, checkOut, guests };
    }

    module.exports = { parseQuoteQuery };

    // Search parameters (P05-T01): what a visitor may ask for. Everything is
    // coerced to a plain string, number or boolean; an object or a list where a
    // single value belongs is refused, so `?guests[$gt]=1` or `?guests=1&guests=9`
    // can never reach the database as an operator. Unknown names are dropped.
    const Joi = require(\"joi\");
    const {
      PROPERTY_TYPE_VALUES,
      ROOM_TYPE_VALUES,
      AMENITY_VALUES,
      ACCESSIBILITY_VALUES,
    } = require(\"../config/constants\");
    const { CATEGORY_SLUGS } = require(\"../config/categories\");

    const MAX_RUPEES = 1000000;
    // Result order and page (P05-T03). The default order is \"relevance\".
    const SORTS = Object.freeze([\"relevance\", \"price_asc\", \"price_desc\", \"rating\", \"newest\"]);
    const DEFAULT_SORT = \"relevance\";
    const MAX_PAGE = 1000;

    const text = (label, max) =>
      Joi.string()
        .trim()
        .max(max)
        .allow(\"\")
        .label(label)
        .messages({ \"string.max\": `${label} must be at most ${max} characters.` });

    const oneOrMany = (values, label) =>
      Joi.array()
        .single()
        .items(Joi.string().valid(...values))
        .unique()
        .max(values.length)
        .label(label)
        .messages({
          \"any.only\": `${label} is not one of the choices.`,
          \"array.includes\": `${label} is not one of the choices.`,
        });

    const searchSchema = Joi.object({
      destination: text(\"Destination\", 100),
      keywords: text(\"Keywords\", 100),
      minPrice: Joi.number().empty(\"\").min(0).max(MAX_RUPEES).label(\"Minimum price\"),
      maxPrice: Joi.number().empty(\"\").min(0).max(MAX_RUPEES).label(\"Maximum price\"),
      guests: Joi.number().empty(\"\").integer().min(1).max(16).label(\"Guests\"),
      bedrooms: Joi.number().empty(\"\").integer().min(0).max(50).label(\"Bedrooms\"),
      propertyType: oneOrMany(PROPERTY_TYPE_VALUES, \"Property type\"),
      roomType: oneOrMany(ROOM_TYPE_VALUES, \"Room type\"),
      amenities: oneOrMany(AMENITY_VALUES, \"Amenities\"),
      access: oneOrMany(ACCESSIBILITY_VALUES, \"Accessibility features\"),
      instantBook: Joi.boolean().truthy(\"1\", \"true\", \"on\").falsy(\"0\", \"false\", \"off\", \"\"),
      // One category from the strip (P05-T04); anything else, including a list or an
      // object, is refused.
      category: Joi.string()
        .empty(\"\")
        .valid(...CATEGORY_SLUGS)
        .label(\"Category\")
        .messages({
          \"any.only\": \"Category is not one of the choices.\",
          \"string.base\": \"Category is not one of the choices.\",
        }),
      sort: Joi.string()
        .empty(\"\")
        .valid(...SORTS)
        .label(\"Sort order\")
        .messages({ \"any.only\": \"Sort order is not one of the choices.\" }),
      page: Joi.number()
        .empty(\"\")
        .integer()
        .min(1)
        .max(MAX_PAGE)
        .label(\"Page\")
        .messages({
          \"number.base\": \"Page must be a number.\",
          \"number.integer\": \"Page must be a whole number.\",
          \"number.min\": \"Page must be 1 or more.\",
          \"number.max\": `Page must be ${MAX_PAGE} or fewer.`,
        }),
    })
      .custom((value, helpers) => {
        if (
          value.minPrice !== undefined &&
          value.maxPrice !== undefined &&
          value.minPrice > value.maxPrice
        ) {
          return helpers.error(\"price.order\");
        }
        return value;
      })
      .messages({ \"price.order\": \"The minimum price cannot be more than the maximum.\" });

    const KNOWN = [
      \"destination\",
      \"keywords\",
      \"minPrice\",
      \"maxPrice\",
      \"guests\",
      \"bedrooms\",
      \"propertyType\",
      \"roomType\",
      \"amenities\",
      \"access\",
      \"instantBook\",
      \"category\",
      \"sort\",
      \"page\",
    ];

    /**
     * @param {object} query req.query (or any plain object)
     * @returns {{ value: object, errors: Record<string,string> }} `value` holds the
     * valid, coerced parameters; `errors` the problems by name. Valid parameters
     * are returned even when others failed, so a page can still search with what
     * was understood and say what was not.
     */
    function parseSearchParams(query) {
      const input = query && typeof query === \"object\" ? query : {};
      const { error, value } = searchSchema.validate(input, {
        abortEarly: false,
        stripUnknown: true,
        errors: { wrap: { label: false } },
      });
      if (!error) return { value: compact(value), errors: {} };

      const errors = {};
      const bad = new Set();
      for (const detail of error.details) {
        const field = detail.path[0] ?? \"maxPrice\";
        bad.add(field);
        if (!errors[field]) errors[field] = detail.message;
      }
      // Keep the parameters that were fine.
      const kept = {};
      for (const key of KNOWN) {
        if (bad.has(key) || !Object.hasOwn(input, key)) continue;
        const original = input[key];
        const single = searchSchema.extract(key);
        const { error: oneError, value: oneValue } = single.validate(original);
        if (!oneError) kept[key] = oneValue;
      }
      return { value: compact(kept), errors };
    }

    /** Drops empty strings so \"destination=\" means \"no destination\". */
    function compact(value) {
      const out = {};
      for (const [key, v] of Object.entries(value)) {
        if (v === \"\" || v === undefined) continue;
        if (Array.isArray(v) && v.length === 0) continue;
        out[key] = v;
      }
      return out;
    }

    module.exports = {
      parseSearchParams,
      searchSchema,
      MAX_RUPEES,
      SORTS,
      DEFAULT_SORT,
      MAX_PAGE,
    };

